def timed_feedback_coherence_window(baud: object = None) -> float:
    """Choose a bus-rate-aware window for one four-motor 0x43 snapshot.

    The old fixed 60 ms window could combine M1/M2 from one timed-return
    cycle with M3/M4 from the next cycle after a dropped byte.  That produces
    a physically impossible four-rope solution, which then appears as a
    sudden height spike or a crooked corner.  At high baud the four 37-byte
    replies fit in a few milliseconds; at a slower baud we widen the window
    only as much as the wire time requires.
    """
    try:
        rate = float(baud)
    except (TypeError, ValueError):
        rate = 0.0
    if rate <= 0.0:
        return TRACKING_POSITION_COHERENCE_SECONDS
    wire_seconds = (
        (TIMED_FEEDBACK_FRAME_BYTES + 2)
        * 10.0
        * len(MOTOR_IDS)
        / rate
    )
    # The controller's 10 ms timed-return interval can stagger the four motor
    # replies across several USB reads.  Keep enough room for one genuine
    # cycle, while duplicate-address detection below prevents a lost frame
    # from silently joining two adjacent cycles.
    return max(0.025, min(TRACKING_POSITION_COHERENCE_SECONDS, wire_seconds * 8.0))


def normalized_grid_shape(rows: object = GRID_DEFAULT_ROWS, cols: object = GRID_DEFAULT_COLS) -> tuple[int, int]:
    """Validate the configurable boundary-inclusive compensation grid shape."""
    try:
        normalized_rows = int(rows)
        normalized_cols = int(cols)
    except (TypeError, ValueError):
        raise ValueError("网格行列必须是有效整数") from None
    if (
        normalized_rows != float(rows)
        or normalized_cols != float(cols)
        or not GRID_MIN_ROWS <= normalized_rows <= GRID_MAX_ROWS
        or not GRID_MIN_COLS <= normalized_cols <= GRID_MAX_COLS
        or normalized_rows * normalized_cols > GRID_MAX_POINTS
    ):
        raise ValueError(
            f"网格行列必须在 {GRID_MIN_ROWS}..{GRID_MAX_ROWS} × "
            f"{GRID_MIN_COLS}..{GRID_MAX_COLS}，且总点数不超过 {GRID_MAX_POINTS}"
        )
    return normalized_rows, normalized_cols


def grid_sampling_points(
    rows: object = GRID_DEFAULT_ROWS,
    cols: object = GRID_DEFAULT_COLS,
) -> list[dict]:
    """Return boundary-inclusive snake-order points in the 110×148 frame.

    ``row`` is the Y index from bottom to top and ``col`` is the X index from
    left to right.  Odd rows reverse X order, so a physical sampler can move
    continuously between rows instead of teleporting back to the left edge.
    """
    normalized_rows, normalized_cols = normalized_grid_shape(rows, cols)
    # This helper is also used while STATE is being initialized, before the
    # later solver function definitions exist.  Use the fixed constants here.
    width, height = WORKSPACE_WIDTH_MM, WORKSPACE_HEIGHT_MM
    points: list[dict] = []
    for row in range(normalized_rows):
        y = height * row / max(1, normalized_rows - 1)
        columns = range(normalized_cols) if row % 2 == 0 else range(normalized_cols - 1, -1, -1)
        for col in columns:
            x = width * col / max(1, normalized_cols - 1)
            points.append(
                {
                    "index": len(points),
                    "row": row,
                    "col": col,
                    "x_mm": round(x, 6),
                    "y_mm": round(y, 6),
                }
            )
    return points


def grid_sampling_path(
    rows: object = GRID_DEFAULT_ROWS,
    cols: object = GRID_DEFAULT_COLS,
) -> list[tuple[float, float]]:
    """Return only the XY tuples for plotting or an offline sampler."""
    return [(point["x_mm"], point["y_mm"]) for point in grid_sampling_points(rows, cols)]


def _grid_empty_node(point: dict, reason: str = "缺少网格样本") -> dict:
    result = {
        **point,
        "valid": False,
        "invalid_reason": reason,
        "absolute_positions_deg": None,
        "phase_current_ma": None,
        "solved_xy_mm": None,
        "solved_z_mm": None,
        "plane_reference_z_mm": None,
        "height_error_mm": None,
        "z_fit_spread_mm": None,
        "xy_error_mm": None,
        "fit_error_mm": None,
        "tension_feedforward_ma": None,
        "position_compensation_deg": None,
    }
    return result


def blank_grid_compensation(
    rows: object = GRID_DEFAULT_ROWS,
    cols: object = GRID_DEFAULT_COLS,
) -> dict:
    """Create an explicitly disabled, not-yet-sampled persistent table."""
    points = grid_sampling_points(rows, cols)
    normalized_rows, normalized_cols = normalized_grid_shape(rows, cols)
    return {
        "version": GRID_COMPENSATION_VERSION,
        "schema": GRID_COMPENSATION_SCHEMA,
        "coordinate_frame": "ball_center_workspace",
        "workspace_width": WORKSPACE_WIDTH_MM,
        "workspace_height": WORKSPACE_HEIGHT_MM,
        "rows": normalized_rows,
        "cols": normalized_cols,
        "valid": False,
        "enabled": False,
        "invalid_reason": "尚未采集网格样本",
        "target_current_ma": GRID_DEFAULT_TENSION_CURRENT_MA,
        "max_xy_error_mm": GRID_MAX_XY_ERROR_MM,
        "max_height_error_mm": GRID_MAX_HEIGHT_ERROR_MM,
        "max_z_spread_mm": GRID_MAX_Z_SPREAD_MM,
        "sample_count": len(points),
        "valid_sample_count": 0,
        "min_phase_current_ma": None,
        "max_height_error_observed_mm": None,
        "max_xy_error_observed_mm": None,
        "reference_phase_current_ma": None,
        "plane_reference_z_mm": None,
        "interpolation": {
            "primary": "bilinear",
            "fallback": "nearest_valid",
            "boundary": "clamp_to_workspace",
        },
        "samples": [_grid_empty_node(point) for point in points],
        "created_at": None,
        "updated_at": None,
    }


def _finite_grid_vector(value: object, length: int) -> list[float] | None:
    if not isinstance(value, (list, tuple)) or len(value) != length:
        return None
    try:
        result = [float(item) for item in value]
    except (TypeError, ValueError):
        return None
    return result if all(math.isfinite(item) for item in result) else None


def _grid_record_value(record: dict, *names: str) -> object:
    for name in names:
        if name in record:
            return record[name]
    return None


def _grid_nominal_positions(
    x: float,
    y: float,
    calibration: dict,
) -> list[float] | None:
    try:
        if len(calibration.get("slope", [])) != len(MOTOR_IDS) or len(calibration.get("intercept", [])) != len(MOTOR_IDS):
            return None
        nominal = [motor_degrees(index, x, y, calibration) for index in range(len(MOTOR_IDS))]
    except (IndexError, KeyError, TypeError, ValueError, ZeroDivisionError):
        return None
    return nominal if all(math.isfinite(value) for value in nominal) else None


def _grid_source_records(raw_samples: object) -> list[object]:
    if isinstance(raw_samples, dict):
        value = raw_samples.get("samples", raw_samples.get("nodes", []))
        return list(value) if isinstance(value, list) else []
    return list(raw_samples) if isinstance(raw_samples, list) else []


def build_grid_compensation(
    raw_samples: object,
    calibration: dict | None = None,
    *,
    rows: object = GRID_DEFAULT_ROWS,
    cols: object = GRID_DEFAULT_COLS,
    reference_phase_current_ma: object = None,
    target_current_ma: object = None,
    plane_reference_z_mm: object = None,
    max_fit_error_mm: object = GRID_MAX_FIT_ERROR_MM,
) -> dict:
    """Build the offline grid table from raw or partially missing samples.

    Each supplied record may identify a node by ``row``/``col`` or ``index``;
    records without an identifier follow the generated snake order. Raw
    absolute positions and phase currents are retained. When possible, XY/Z
    and both compensation vectors are derived from the same four-rope
    calibration, but no serial operation is performed here. A node is not
    usable for live compensation unless all four currents are at least the
    requested tension floor and its planar solve meets the strict XY/Z gates.
    """
    normalized_rows, normalized_cols = normalized_grid_shape(rows, cols)
    try:
        fit_limit = float(max_fit_error_mm)
    except (TypeError, ValueError):
        raise ValueError("网格拟合误差上限必须是有效数字") from None
    if not math.isfinite(fit_limit) or fit_limit <= 0.0:
        raise ValueError("网格拟合误差上限必须大于 0")
    calibration = calibration if isinstance(calibration, dict) else calibration_data()
    if target_current_ma is None:
        target_current_ma = calibration.get("grid_tension_target_current_ma", GRID_DEFAULT_TENSION_CURRENT_MA)
    try:
        target_current = float(target_current_ma)
    except (TypeError, ValueError):
        raise ValueError("网格张力下限必须是有效数字") from None
    if (
        not math.isfinite(target_current)
        or target_current < GRID_TENSION_MIN_CURRENT_MA
        or target_current > GRID_TENSION_MAX_CURRENT_MA
    ):
        raise ValueError(
            f"网格张力下限必须在 {GRID_TENSION_MIN_CURRENT_MA}..{GRID_TENSION_MAX_CURRENT_MA}mA"
        )
    tension_low = max(float(GRID_TENSION_MIN_CURRENT_MA), target_current - GRID_TENSION_BAND_MA)
    tension_high = min(float(GRID_TENSION_MAX_CURRENT_MA), target_current + GRID_TENSION_BAND_MA)
    if plane_reference_z_mm is None:
        plane_reference_z_mm = calibration.get("grid_plane_reference_z_mm")
    try:
        plane_reference = float(plane_reference_z_mm) if plane_reference_z_mm is not None else None
    except (TypeError, ValueError):
        plane_reference = None
    if plane_reference is not None and not math.isfinite(plane_reference):
        plane_reference = None
    points = grid_sampling_points(normalized_rows, normalized_cols)
    by_key: dict[tuple[int, int], object] = {}
    sequential: list[object] = []
    for record in _grid_source_records(raw_samples):
        if isinstance(record, dict) and "row" in record and "col" in record:
            try:
                key = (int(record["row"]), int(record["col"]))
            except (TypeError, ValueError):
                sequential.append(record)
                continue
            by_key[key] = record
        elif isinstance(record, dict) and "index" in record:
            try:
                index = int(record["index"])
            except (TypeError, ValueError):
                sequential.append(record)
                continue
            if 0 <= index < len(points):
                point = points[index]
                by_key[(point["row"], point["col"])] = record
            else:
                sequential.append(record)
        else:
            sequential.append(record)
    for point in points:
        key = (point["row"], point["col"])
        if key not in by_key and sequential:
            by_key[key] = sequential.pop(0)

    nodes: list[dict] = []
    for point in points:
        raw = by_key.get((point["row"], point["col"]))
        if raw is None:
            nodes.append(_grid_empty_node(point))
            continue
        if isinstance(raw, (list, tuple)):
            raw = {"absolute_positions_deg": raw}
        if not isinstance(raw, dict):
            nodes.append(_grid_empty_node(point, "网格样本格式无效"))
            continue
        positions = _finite_grid_vector(
            _grid_record_value(raw, "absolute_positions_deg", "positions_deg", "absolute_positions", "positions"),
            len(MOTOR_IDS),
        )
        currents = _finite_grid_vector(
            _grid_record_value(raw, "phase_current_ma", "phase_currents_ma", "phase_current", "currents_ma"),
            len(MOTOR_IDS),
        )
        solved_xy = _finite_grid_vector(
            _grid_record_value(raw, "solved_xy_mm", "xy_mm", "resolved_xy_mm", "xy"),
            2,
        )
        try:
            solved_z = float(_grid_record_value(raw, "solved_z_mm", "resolved_z_mm", "z_mm", "z"))
        except (TypeError, ValueError):
            solved_z = None
        if solved_z is not None and not math.isfinite(solved_z):
            solved_z = None
        try:
            z_spread = float(_grid_record_value(raw, "z_fit_spread_mm", "fit_spread_mm", "z_spread_mm"))
        except (TypeError, ValueError):
            z_spread = None
        if z_spread is not None and (not math.isfinite(z_spread) or z_spread < 0.0):
            z_spread = None
        if positions and (solved_xy is None or solved_z is None or z_spread is None):
            solved = position_to_xyz([float(value) for value in positions], calibration)
            if solved is not None:
                solved_xy = [float(solved[0]), float(solved[1])]
                solved_z = float(solved[2])
                z_spread = float(solved[3])
        if solved_xy is not None:
            left, bottom, _, _ = drawable_workspace(calibration)
            solved_xy = [solved_xy[0] - left, solved_xy[1] - bottom]
        try:
            sample_plane_reference = _grid_record_value(raw, "plane_reference_z_mm", "z_reference_mm")
            if sample_plane_reference is not None:
                sample_plane_reference = float(sample_plane_reference)
            else:
                sample_plane_reference = plane_reference
        except (TypeError, ValueError):
            sample_plane_reference = plane_reference
        if sample_plane_reference is not None and not math.isfinite(sample_plane_reference):
            sample_plane_reference = None
        try:
            height_error = float(_grid_record_value(raw, "height_error_mm", "height_deviation_mm"))
        except (TypeError, ValueError):
            height_error = None
        if height_error is None and solved_z is not None and sample_plane_reference is not None:
            height_error = abs(solved_z - sample_plane_reference)
        if height_error is not None and (not math.isfinite(height_error) or height_error < 0.0):
            height_error = None
        try:
            xy_error = float(_grid_record_value(raw, "xy_error_mm", "position_error_mm"))
        except (TypeError, ValueError):
            xy_error = None
        if xy_error is None and solved_xy is not None:
            xy_error = math.hypot(solved_xy[0] - point["x_mm"], solved_xy[1] - point["y_mm"])
        if xy_error is not None and (not math.isfinite(xy_error) or xy_error < 0.0):
            xy_error = None
        try:
            fit_error = float(_grid_record_value(raw, "fit_error_mm", "fitting_error_mm"))
        except (TypeError, ValueError):
            fit_error = None
        if fit_error is None and xy_error is not None:
            fit_error = max(xy_error, height_error or 0.0, z_spread or 0.0)
        if fit_error is not None and (not math.isfinite(fit_error) or fit_error < 0.0):
            fit_error = None
        nominal_positions = _finite_grid_vector(
            _grid_record_value(raw, "nominal_positions_deg", "expected_positions_deg"),
            len(MOTOR_IDS),
        ) or _grid_nominal_positions(point["x_mm"], point["y_mm"], calibration)
        position_compensation = _finite_grid_vector(
            _grid_record_value(raw, "position_compensation_deg", "position_bias_deg"),
            len(MOTOR_IDS),
        )
        if position_compensation is None and positions and nominal_positions:
            # Store the correction from the nominal kinematic target to the
            # measured absolute encoder target.  The live controller adds this
            # residual to the nominal target, so a grid node replays the
            # absolute position actually observed during calibration.
            position_compensation = [measured - nominal for nominal, measured in zip(nominal_positions, positions)]
        reason = ""
        if positions is None:
            reason = "缺少四电机绝对位置"
        elif currents is None:
            reason = "缺少四电机相电流"
        elif solved_xy is None or solved_z is None or z_spread is None:
            reason = "无法从四电机位置解算 XY/Z"
        elif fit_error is None:
            reason = "缺少拟合误差"
        elif fit_error > fit_limit:
            reason = f"拟合误差 {fit_error:.2f}mm 超过 {fit_limit:.2f}mm"
        elif height_error is None:
            reason = "缺少相对平面高度"
        elif height_error > GRID_MAX_HEIGHT_ERROR_MM:
            reason = f"平面高度偏差 {height_error:.2f}mm 超过 {GRID_MAX_HEIGHT_ERROR_MM:.2f}mm"
        elif z_spread > GRID_MAX_Z_SPREAD_MM:
            reason = f"四绳 Z 解算离散 {z_spread:.2f}mm 超过 {GRID_MAX_Z_SPREAD_MM:.2f}mm"
        elif xy_error > GRID_MAX_XY_ERROR_MM:
            reason = f"XY 误差 {xy_error:.2f}mm 超过 {GRID_MAX_XY_ERROR_MM:.2f}mm"
        elif any(abs(value) < tension_low for value in currents):
            reason = f"存在相电流低于目标带宽下限 {tension_low:.0f}mA"
        elif any(abs(value) > tension_high for value in currents):
            reason = f"存在相电流高于目标带宽上限 {tension_high:.0f}mA"
        elif position_compensation is None:
            reason = "缺少基准位置，无法生成位置补偿"
        node = {
            **point,
            "valid": not bool(reason),
            "invalid_reason": reason,
            "absolute_positions_deg": positions,
            "phase_current_ma": currents,
            "solved_xy_mm": [round(value, 6) for value in solved_xy] if solved_xy is not None else None,
            "solved_z_mm": round(solved_z, 6) if solved_z is not None else None,
            "plane_reference_z_mm": round(sample_plane_reference, 6) if sample_plane_reference is not None else None,
            "height_error_mm": round(height_error, 6) if height_error is not None else None,
            "z_fit_spread_mm": round(z_spread, 6) if z_spread is not None else None,
            "xy_error_mm": round(xy_error, 6) if xy_error is not None else None,
            "fit_error_mm": round(fit_error, 6) if fit_error is not None else None,
            "tension_feedforward_ma": None,
            "position_compensation_deg": (
                [round(value, 6) for value in position_compensation]
                if position_compensation is not None
                and all(abs(value) <= GRID_POSITION_COMPENSATION_LIMIT_DEG for value in position_compensation)
                else None
            ),
        }
        if node["valid"] and node["position_compensation_deg"] is None:
            node["valid"] = False
            node["invalid_reason"] = "位置补偿超出安全范围或不可计算"
        nodes.append(node)

    valid_nodes = [node for node in nodes if node["valid"]]
    if reference_phase_current_ma is not None:
        reference = _finite_grid_vector(reference_phase_current_ma, len(MOTOR_IDS))
        if reference is None or any(value < 0.0 for value in reference):
            raise ValueError("网格参考相电流必须是四个非负有限数")
    elif valid_nodes:
        reference = [
            float(statistics.median(abs(node["phase_current_ma"][index]) for node in valid_nodes))
            for index in range(len(MOTOR_IDS))
        ]
    else:
        reference = None
    if reference is not None:
        for node in valid_nodes:
            feedforward = [
                max(-GRID_TENSION_FEEDFORWARD_LIMIT_MA, min(
                    GRID_TENSION_FEEDFORWARD_LIMIT_MA,
                    target_current - abs(node["phase_current_ma"][index]),
                ))
                for index in range(len(MOTOR_IDS))
            ]
            node["tension_feedforward_ma"] = [round(value, 6) for value in feedforward]
    else:
        for node in valid_nodes:
            node["valid"] = False
            node["invalid_reason"] = "没有可用的参考相电流"
        valid_nodes = []
    valid_count = len(valid_nodes)
    complete = valid_count == len(nodes)
    now = round(time.time(), 3)
    result = blank_grid_compensation(normalized_rows, normalized_cols)
    result.update(
        {
            "valid": complete,
            "enabled": False,
            "invalid_reason": "" if complete else f"网格存在 {len(nodes) - valid_count} 个缺失或无效点；仅保留离线诊断",
            "target_current_ma": round(target_current, 6),
            "max_xy_error_mm": GRID_MAX_XY_ERROR_MM,
            "max_height_error_mm": GRID_MAX_HEIGHT_ERROR_MM,
            "max_z_spread_mm": GRID_MAX_Z_SPREAD_MM,
            "valid_sample_count": valid_count,
            "min_phase_current_ma": (
                round(min(abs(float(value)) for node in valid_nodes for value in node["phase_current_ma"]), 6)
                if valid_nodes else None
            ),
            "max_height_error_observed_mm": (
                round(max(float(node["height_error_mm"]) for node in valid_nodes), 6)
                if valid_nodes else None
            ),
            "max_xy_error_observed_mm": (
                round(max(float(node["xy_error_mm"]) for node in valid_nodes), 6)
                if valid_nodes else None
            ),
            "plane_reference_z_mm": round(plane_reference, 6) if plane_reference is not None else None,
            "reference_phase_current_ma": [round(value, 6) for value in reference] if reference is not None else None,
            "samples": nodes,
            "created_at": now,
            "updated_at": now,
        }
    )
    return result


def validate_grid_compensation(data: object) -> tuple[bool, str]:
    """Validate schema, fixed frame, node coordinates and vector lengths."""
    if not isinstance(data, dict):
        return False, "网格补偿结构缺失"
    if data.get("version") != GRID_COMPENSATION_VERSION or data.get("schema") != GRID_COMPENSATION_SCHEMA:
        return False, "网格补偿版本不受支持"
    if data.get("coordinate_frame") != "ball_center_workspace":
        return False, "网格补偿坐标系不是球心工作区"
    try:
        if not math.isclose(float(data.get("workspace_width")), WORKSPACE_WIDTH_MM, abs_tol=0.0001) or not math.isclose(float(data.get("workspace_height")), WORKSPACE_HEIGHT_MM, abs_tol=0.0001):
            return False, "网格补偿工作区不是 110×148mm"
        rows, cols = normalized_grid_shape(data.get("rows"), data.get("cols"))
        target_current = float(data.get("target_current_ma", GRID_DEFAULT_TENSION_CURRENT_MA))
    except (TypeError, ValueError):
        return False, "网格补偿行列无效"
    if not math.isfinite(target_current) or not GRID_TENSION_MIN_CURRENT_MA <= target_current <= GRID_TENSION_MAX_CURRENT_MA:
        return False, "网格补偿张力下限无效"
    samples = data.get("samples")
    expected = grid_sampling_points(rows, cols)
    if not isinstance(samples, list) or len(samples) != len(expected):
        return False, "网格补偿节点数量不完整"
    if data.get("sample_count") not in (None, len(expected)):
        return False, "网格补偿声明的节点数量不匹配"
    for point, node in zip(expected, samples):
        if not isinstance(node, dict):
            return False, "网格补偿节点格式无效"
        if (node.get("row"), node.get("col")) != (point["row"], point["col"]):
            return False, "网格补偿节点索引不连续"
        try:
            if abs(float(node.get("x_mm")) - point["x_mm"]) > 0.0001 or abs(float(node.get("y_mm")) - point["y_mm"]) > 0.0001:
                return False, "网格补偿节点越过固定边界或坐标不匹配"
        except (TypeError, ValueError):
            return False, "网格补偿节点坐标无效"
        if node.get("valid") is True:
            currents = _finite_grid_vector(node.get("phase_current_ma"), len(MOTOR_IDS))
            if _finite_grid_vector(node.get("absolute_positions_deg"), len(MOTOR_IDS)) is None or currents is None or _finite_grid_vector(node.get("solved_xy_mm"), 2) is None or _finite_grid_vector(node.get("tension_feedforward_ma"), len(MOTOR_IDS)) is None or _finite_grid_vector(node.get("position_compensation_deg"), len(MOTOR_IDS)) is None:
                return False, "有效网格节点缺少四电机补偿向量"
            try:
                height_error = float(node.get("height_error_mm"))
                z_spread = float(node.get("z_fit_spread_mm"))
                xy_error = float(node.get("xy_error_mm"))
                if not math.isfinite(float(node.get("solved_z_mm"))) or not math.isfinite(float(node.get("fit_error_mm"))) or not math.isfinite(height_error) or not math.isfinite(z_spread) or not math.isfinite(xy_error):
                    return False, "有效网格节点解算值无效"
            except (TypeError, ValueError):
                return False, "有效网格节点解算值缺失"
            tension_low = max(float(GRID_TENSION_MIN_CURRENT_MA), target_current - GRID_TENSION_BAND_MA)
            tension_high = min(float(GRID_TENSION_MAX_CURRENT_MA), target_current + GRID_TENSION_BAND_MA)
            if any(not tension_low <= abs(value) <= tension_high for value in currents):
                return False, "有效网格节点相电流超出声明的诊断带宽"
            if height_error > GRID_MAX_HEIGHT_ERROR_MM or z_spread > GRID_MAX_Z_SPREAD_MM or xy_error > GRID_MAX_XY_ERROR_MM:
                return False, "有效网格节点超过平面质量门槛"
    if data.get("valid") is True and not all(node.get("valid") is True for node in samples):
        return False, "网格补偿标记有效但仍存在缺失节点"
    return True, ""


def normalize_grid_compensation(data: object) -> dict:
    """Load a grid table without ever allowing malformed data to be used."""
    if not isinstance(data, dict):
        return blank_grid_compensation()
    try:
        rows, cols = normalized_grid_shape(data.get("rows", GRID_DEFAULT_ROWS), data.get("cols", GRID_DEFAULT_COLS))
    except ValueError:
        rows, cols = GRID_DEFAULT_ROWS, GRID_DEFAULT_COLS
    normalized = blank_grid_compensation(rows, cols)
    normalized.update(copy.deepcopy(data))
    normalized["rows"] = rows
    normalized["cols"] = cols
    schema_ok, reason = validate_grid_compensation(normalized)
    if not schema_ok:
        normalized["valid"] = False
        normalized["enabled"] = False
        normalized["invalid_reason"] = reason
    elif normalized.get("valid") is not True:
        normalized["enabled"] = False
    return normalized


def interpolate_grid_compensation(data: object, x: object, y: object) -> dict:
    """Interpolate offline compensation; bilinear first, nearest on holes.

    Coordinates are clamped to the fixed rectangle and the result reports the
    method, source nodes, missing-node fallback and whether it is actually
    eligible for a future live integration.  An incomplete/disabled table is
    never marked ``apply_allowed`` even when a nearest diagnostic value exists.
    """
    empty = {
        "ok": False,
        "ready": False,
        "apply_allowed": False,
        "method": None,
        "fallback": False,
        "clamped": False,
        "x_mm": None,
        "y_mm": None,
        "source_indices": [],
        "nearest_distance_mm": None,
        "tension_feedforward_ma": None,
        "position_compensation_deg": None,
        "reason": "网格补偿不可用",
    }
    schema_ok, schema_reason = validate_grid_compensation(data)
    if not schema_ok:
        empty["reason"] = schema_reason
        return empty
    try:
        query_x = float(x)
        query_y = float(y)
    except (TypeError, ValueError):
        empty["reason"] = "查询坐标无效"
        return empty
    if not math.isfinite(query_x) or not math.isfinite(query_y):
        empty["reason"] = "查询坐标不是有限数"
        return empty
    width, height = WORKSPACE_WIDTH_MM, WORKSPACE_HEIGHT_MM
    clamped_x = max(0.0, min(width, query_x))
    clamped_y = max(0.0, min(height, query_y))
    rows, cols = int(data["rows"]), int(data["cols"])
    samples = data["samples"]
    by_key = {(int(node["row"]), int(node["col"])): node for node in samples}
    col_position = clamped_x / width * (cols - 1)
    row_position = clamped_y / height * (rows - 1)
    col0 = min(cols - 1, max(0, int(math.floor(col_position))))
    row0 = min(rows - 1, max(0, int(math.floor(row_position))))
    col1 = min(cols - 1, col0 + 1)
    row1 = min(rows - 1, row0 + 1)
    u = col_position - col0
    v = row_position - row0
    corner_keys = ((row0, col0), (row0, col1), (row1, col0), (row1, col1))
    corners = [by_key[key] for key in corner_keys]
    vectors = ("tension_feedforward_ma", "position_compensation_deg")
    bilinear_ok = all(node.get("valid") is True and all(_finite_grid_vector(node.get(name), len(MOTOR_IDS)) is not None for name in vectors) for node in corners)
    method = "bilinear"
    source_nodes = corners
    weights = ((1.0 - u) * (1.0 - v), u * (1.0 - v), (1.0 - u) * v, u * v)
    if not bilinear_ok:
        method = "nearest_valid"
        valid_nodes = [node for node in samples if node.get("valid") is True and all(_finite_grid_vector(node.get(name), len(MOTOR_IDS)) is not None for name in vectors)]
        if not valid_nodes:
            empty.update({"clamped": query_x != clamped_x or query_y != clamped_y, "x_mm": clamped_x, "y_mm": clamped_y, "reason": "没有可用的有效网格点"})
            return empty
        nearest = min(valid_nodes, key=lambda node: math.hypot(float(node["x_mm"]) - clamped_x, float(node["y_mm"]) - clamped_y))
        source_nodes = [nearest]
        weights = (1.0,)
    result = dict(empty)
    result.update(
        {
            "ok": True,
            "ready": bool(data.get("valid") is True),
            "apply_allowed": bool(data.get("enabled") is True and data.get("valid") is True and method == "bilinear"),
            "method": method,
            "fallback": method != "bilinear",
            "clamped": query_x != clamped_x or query_y != clamped_y,
            "x_mm": round(clamped_x, 6),
            "y_mm": round(clamped_y, 6),
            "source_indices": [int(node["index"]) for node in source_nodes],
            "nearest_distance_mm": round(math.hypot(float(source_nodes[0]["x_mm"]) - clamped_x, float(source_nodes[0]["y_mm"]) - clamped_y), 6) if method != "bilinear" else 0.0,
            "tension_feedforward_ma": [
                round(sum(float(weight) * float(node["tension_feedforward_ma"][index]) for weight, node in zip(weights, source_nodes)), 6)
                for index in range(len(MOTOR_IDS))
            ],
            "position_compensation_deg": [
                round(sum(float(weight) * float(node["position_compensation_deg"][index]) for weight, node in zip(weights, source_nodes)), 6)
                for index in range(len(MOTOR_IDS))
            ],
            "reason": "" if method == "bilinear" and data.get("valid") is True else "网格不完整或未启用，仅返回离线诊断值",
        }
    )
    return result


def grid_current_limits_at(
    x: object,
    y: object,
    calibration: dict | None = None,
    fallback_current: object = None,
) -> list[int]:
    """Return the live per-motor command caps for one XY point.

    Geometry remains the nominal four-sphere solution. The grid contributes a
    bounded current-cap feed-forward only; a malformed, incomplete, or
    disabled map falls back to one shared cap and can never affect motion.
    """
    data = calibration if calibration is not None else calibration_data()
    try:
        base = trajectory_runtime_current() if fallback_current is None else int(fallback_current)
    except (TypeError, ValueError):
        base = TRAJECTORY_DEFAULT_CURRENT
    base = max(300, min(OPERATING_CURRENT_MAX_MA, base))
    grid = data.get("grid_compensation") if isinstance(data, dict) else None
    if not isinstance(grid, dict) or grid.get("enabled") is not True or grid.get("valid") is not True:
        return [base for _ in MOTOR_IDS]
    interpolated = interpolate_grid_compensation(grid, x, y)
    if interpolated.get("apply_allowed") is not True:
        return [base for _ in MOTOR_IDS]
    adjustments = _finite_grid_vector(interpolated.get("tension_feedforward_ma"), len(MOTOR_IDS))
    if adjustments is None:
        return [base for _ in MOTOR_IDS]
    return normalized_trajectory_current_limits(
        [base + int(round(value)) for value in adjustments]
    )


def grid_motor_positions_at(
    x: object,
    y: object,
    calibration: dict | None = None,
    nominal_positions: object = None,
) -> list[float]:
    """Return absolute motor targets corrected by the validated grid map.

    The nominal four-sphere transform remains the fallback.  A complete,
    enabled grid contributes only the measured absolute-position residual at
    the requested XY point; no relative position command is ever generated.
    """
    data = calibration if calibration is not None else calibration_data()
    if nominal_positions is None:
        nominal = [motor_degrees(index, float(x), float(y), data) for index in range(len(MOTOR_IDS))]
    else:
        try:
            nominal = [float(value) for value in nominal_positions]
        except (TypeError, ValueError):
            nominal = []
    if len(nominal) != len(MOTOR_IDS):
        return nominal
    grid = data.get("grid_compensation") if isinstance(data, dict) else None
    if not isinstance(grid, dict) or grid.get("enabled") is not True or grid.get("valid") is not True:
        return nominal
    interpolated = interpolate_grid_compensation(grid, x, y)
    if interpolated.get("apply_allowed") is not True:
        return nominal
    correction = _finite_grid_vector(interpolated.get("position_compensation_deg"), len(MOTOR_IDS))
    if correction is None:
        return nominal
    return [round(value + delta, 6) for value, delta in zip(nominal, correction)]


def _solve_square_linear_system(matrix: list[list[float]], vector: list[float]) -> list[float] | None:
    """Solve a small square linear system with pivoting and no NumPy dependency."""
    size = len(vector)
    if size < 1 or len(matrix) != size or any(len(row) != size for row in matrix):
        return None
    augmented = [
        [float(matrix[row][column]) for column in range(size)] + [float(vector[row])]
        for row in range(size)
    ]
    for column in range(size):
        pivot = max(range(column, size), key=lambda row: abs(augmented[row][column]))
        if abs(augmented[pivot][column]) < 1e-10:
            return None
        if pivot != column:
            augmented[column], augmented[pivot] = augmented[pivot], augmented[column]
        scale = augmented[column][column]
        augmented[column] = [value / scale for value in augmented[column]]
        for row in range(size):
            if row == column:
                continue
            factor = augmented[row][column]
            if abs(factor) < 1e-15:
                continue
            augmented[row] = [
                left - factor * right
                for left, right in zip(augmented[row], augmented[column])
            ]
    result = [augmented[row][size] for row in range(size)]
    return result if all(math.isfinite(value) for value in result) else None


def equilibrium_tension_model(
    x: object,
    y: object,
    calibration: dict | None = None,
) -> dict:
    """Calculate positive planar wrench-balance weights for the four cables.

    At board height each force acts from its measured attachment point toward
    its measured cable exit.  Four tensions are solved from force X/Y, moment
    about the ball centre, and ``Σwᵢ=1``.  Every weight must be strictly
    positive: a cable can pull but cannot push, so a boundary/singular point is
    reported infeasible instead of being hidden by an arbitrary weight floor.
    """
    data = calibration if calibration is not None else calibration_data()
    try:
        query_x = float(x)
        query_y = float(y)
    except (TypeError, ValueError):
        return {"ok": False, "weights": None, "unit_vectors": None, "residual": None, "reason": "XY无效"}
    if not math.isfinite(query_x) or not math.isfinite(query_y):
        return {"ok": False, "weights": None, "unit_vectors": None, "residual": None, "reason": "XY不是有限数"}
    exit_x, exit_y = cable_exit_coordinates(data)
    attachment_x, attachment_y = ball_attachment_offsets(data)
    unit_vectors: list[tuple[float, float]] = []
    moment_arms: list[float] = []
    for cable_x, cable_y, offset_x, offset_y in zip(exit_x, exit_y, attachment_x, attachment_y):
        dx = float(cable_x) - (query_x + float(offset_x))
        dy = float(cable_y) - (query_y + float(offset_y))
        distance = math.hypot(dx, dy)
        if distance < 1e-9:
            return {
                "ok": False,
                "weights": None,
                "unit_vectors": unit_vectors,
                "residual": None,
                "reason": "目标与出绳锚点重合，正张力平衡奇异",
            }
        ux, uy = dx / distance, dy / distance
        unit_vectors.append((ux, uy))
        moment_arms.append(float(offset_x) * uy - float(offset_y) * ux)
    constraints = [
        [vector[0] for vector in unit_vectors],
        [vector[1] for vector in unit_vectors],
        list(moment_arms),
        [1.0 for _ in unit_vectors],
    ]
    raw_weights = _solve_square_linear_system(constraints, [0.0, 0.0, 0.0, 1.0])
    if raw_weights is None:
        return {"ok": False, "weights": None, "unit_vectors": unit_vectors, "residual": None, "reason": "四个拉力方向无法求解"}
    if any(not math.isfinite(value) for value in raw_weights):
        return {"ok": False, "weights": None, "unit_vectors": unit_vectors, "residual": None, "reason": "张力权重无效"}
    if min(raw_weights, default=0.0) <= 1e-6:
        return {
            "ok": False,
            "weights": raw_weights,
            "unit_vectors": unit_vectors,
            "residual": None,
            "reason": "目标不在四绳最小正张力可行域内",
        }
    total = sum(raw_weights)
    if total <= 1e-9:
        return {"ok": False, "weights": None, "unit_vectors": unit_vectors, "residual": None, "reason": "张力权重全为零"}
    weights = [value / total for value in raw_weights]
    resultant = (
        sum(weight * vector[0] for weight, vector in zip(weights, unit_vectors)),
        sum(weight * vector[1] for weight, vector in zip(weights, unit_vectors)),
    )
    resultant_moment = sum(weight * arm for weight, arm in zip(weights, moment_arms))
    residual = math.hypot(*resultant)
    if residual > GRID_FORCE_BALANCE_MAX_RESIDUAL or abs(resultant_moment) > 1e-6:
        return {
            "ok": False,
            "weights": weights,
            "unit_vectors": unit_vectors,
            "residual": residual,
            "reason": "正张力解的平面合力残差过大",
            "resultant": resultant,
            "resultant_moment_mm": resultant_moment,
        }
    return {
        "ok": True,
        "weights": weights,
        "unit_vectors": unit_vectors,
        "residual": residual,
        "edge_regularized": False,
        "resultant": resultant,
        "resultant_moment_mm": resultant_moment,
        "moment_arms_mm": moment_arms,
    }


def equilibrium_current_targets(
    x: object,
    y: object,
    target_current_ma: object,
    calibration: dict | None = None,
) -> dict:
    """Convert force-balance weights into per-motor current targets.

    These are feedback targets, not claims that a position-mode current field
    equals physical force. The smallest target is the operator's global floor;
    the relative ratios cancel the planar cable-force resultant as closely as
    the four available cable directions permit.
    """
    try:
        floor = float(target_current_ma)
    except (TypeError, ValueError):
        return {"ok": False, "target_currents_ma": None, "model": equilibrium_tension_model(x, y, calibration), "reason": "张力下限无效"}
    floor = max(float(GRID_TENSION_MIN_CURRENT_MA), min(float(GRID_TENSION_MAX_CURRENT_MA), floor))
    model = equilibrium_tension_model(x, y, calibration)
    weights = model.get("weights")
    if not model.get("ok") or not isinstance(weights, list) or not weights:
        return {"ok": False, "target_currents_ma": None, "model": model, "reason": model.get("reason", "张力模型无效")}
    minimum = max(1e-6, min(float(value) for value in weights))
    scale = floor / minimum
    maximum_target = min(float(OPERATING_CURRENT_MAX_MA), floor * GRID_FORCE_BALANCE_MAX_RATIO)
    targets = [min(maximum_target, max(floor, value * scale)) for value in weights]
    return {
        "ok": True,
        "target_currents_ma": [round(value, 3) for value in targets],
        "floor_current_ma": round(floor, 3),
        "model": model,
        "saturated": any(value >= OPERATING_CURRENT_MAX_MA - 1e-9 for value in targets),
    }


def force_position_self_stress_bias(
    x: object,
    y: object,
    contraction_mm: object,
    calibration: dict | None = None,
) -> dict:
    """Map one bounded preload scalar into the four-cable self-stress mode.

    Cable length is shortened in proportion to the positive equilibrium tension
    weights.  Because those weights satisfy the planar force and moment balance,
    the virtual position error primarily creates internal cable load instead of
    translating or rotating the ball.  At a board-supported boundary where a
    strictly positive free-space solution does not exist, use a small equal
    fallback rather than inventing a negative (pushing) cable force.
    """

    data = calibration if calibration is not None else calibration_data()
    try:
        contraction = max(
            0.0,
            min(FORCE_POSITION_CONTRACTION_MAX_MM, float(contraction_mm)),
        )
    except (TypeError, ValueError):
        contraction = 0.0
    model = equilibrium_tension_model(x, y, data)
    weights = model.get("weights") if model.get("ok") else None
    fallback = not isinstance(weights, list) or len(weights) != len(MOTOR_IDS)
    if fallback:
        weights = [1.0 for _ in MOTOR_IDS]
    normalized = [max(0.0, float(value)) for value in weights]
    peak = max(normalized, default=0.0)
    if peak <= 1e-9:
        normalized = [1.0 for _ in MOTOR_IDS]
        peak = 1.0
        fallback = True
    normalized = [value / peak for value in normalized]
    slopes = effective_slopes(data)
    if len(slopes) != len(MOTOR_IDS):
        slopes = [0.0 for _ in MOTOR_IDS]
    length_bias_mm = [-contraction * value for value in normalized]
    position_bias_deg = [
        max(
            -FORCE_POSITION_BIAS_MAX_DEG,
            min(FORCE_POSITION_BIAS_MAX_DEG, float(slope) * length_delta),
        )
        for slope, length_delta in zip(slopes, length_bias_mm)
    ]
    return {
        "ok": True,
        "fallback": fallback,
        "contraction_mm": contraction,
        "weights": [round(value, 6) for value in normalized],
        "length_bias_mm": [round(value, 6) for value in length_bias_mm],
        "position_bias_deg": [round(value, 6) for value in position_bias_deg],
        "equilibrium": model,
    }


def update_force_position_current_ema(
    previous: object,
    measured_currents_ma: object,
) -> list[float | None]:
    """Filter the noisy absolute phase-current proxy without hiding raw data."""

    old = list(previous) if isinstance(previous, (list, tuple)) else []
    samples = list(measured_currents_ma) if isinstance(measured_currents_ma, (list, tuple)) else []
    if len(old) != len(MOTOR_IDS):
        old = [None for _ in MOTOR_IDS]
    if len(samples) != len(MOTOR_IDS):
        return old
    alpha = max(0.01, min(1.0, FORCE_POSITION_CURRENT_EMA_ALPHA))
    result: list[float | None] = []
    for prior, sample in zip(old, samples):
        try:
            value = abs(float(sample))
        except (TypeError, ValueError):
            result.append(prior if isinstance(prior, (int, float)) else None)
            continue
        if not math.isfinite(value):
            result.append(prior if isinstance(prior, (int, float)) else None)
            continue
        result.append(
            value
            if prior is None or not math.isfinite(float(prior))
            else float(prior) + alpha * (value - float(prior))
        )
    return result


def update_force_position_contraction(
    contraction_mm: object,
    filtered_currents_ma: object,
    target_currents_ma: object,
    elapsed_seconds: object,
    current_limit_ma: object = OPERATING_CURRENT_MAX_MA,
) -> tuple[float, dict]:
    """Update only the scalar self-stress preload from motor-current feedback.

    The lowest normalized cable current is deliberately authoritative: three
    taut ropes do not make a fourth slack rope acceptable.  EMA filtering and a
    wide deadband reject commutation/noise, while separate tighten/relax slew
    limits make every target change gentle.  Near the 2 A protection ceiling the
    loop can only relax, never pull harder.
    """

    try:
        current = max(
            FORCE_POSITION_CONTRACTION_MIN_MM,
            min(FORCE_POSITION_CONTRACTION_MAX_MM, float(contraction_mm)),
        )
        dt = max(0.001, min(0.10, float(elapsed_seconds)))
        limit = max(300.0, min(float(OPERATING_CURRENT_MAX_MA), float(current_limit_ma)))
        measured = [float(value) for value in filtered_currents_ma]
        targets = [max(1.0, float(value)) for value in target_currents_ma]
    except (TypeError, ValueError):
        try:
            safe_current = float(contraction_mm)
        except (TypeError, ValueError):
            safe_current = FORCE_POSITION_CONTRACTION_MIN_MM
        if not math.isfinite(safe_current):
            safe_current = FORCE_POSITION_CONTRACTION_MIN_MM
        safe_current = max(
            FORCE_POSITION_CONTRACTION_MIN_MM,
            min(FORCE_POSITION_CONTRACTION_MAX_MM, safe_current),
        )
        return safe_current, {
            "updated": False,
            "reason": "电流反馈或目标不完整",
        }
    if (
        len(measured) != len(MOTOR_IDS)
        or len(targets) != len(MOTOR_IDS)
        or any(not math.isfinite(value) for value in measured + targets)
    ):
        return current, {"updated": False, "reason": "电流反馈或目标无效"}
    ratios = [value / target for value, target in zip(measured, targets)]
    controlling_ratio = min(ratios)
    peak_current = max(measured)
    if peak_current >= limit * 0.92:
        rate = -FORCE_POSITION_RELAX_RATE_MM_S
        reason = "接近保护上限，柔和放松自应力"
    elif controlling_ratio < FORCE_POSITION_CURRENT_RATIO_LOW:
        normalized_error = min(
            1.0,
            max(0.0, (1.0 - controlling_ratio) / FORCE_POSITION_CURRENT_RATIO_LOW),
        )
        rate = FORCE_POSITION_TIGHTEN_RATE_MM_S * max(0.12, normalized_error)
        reason = "最低张力不足，沿自应力方向柔和收绳"
    elif controlling_ratio > FORCE_POSITION_CURRENT_RATIO_HIGH:
        normalized_error = min(1.0, controlling_ratio - 1.0)
        rate = -FORCE_POSITION_RELAX_RATE_MM_S * max(0.12, normalized_error)
        reason = "四绳张力有余量，柔和减小预紧"
    else:
        rate = 0.0
        reason = "张力代理位于死区"
    updated = max(
        FORCE_POSITION_CONTRACTION_MIN_MM,
        min(FORCE_POSITION_CONTRACTION_MAX_MM, current + rate * dt),
    )
    return round(updated, 6), {
        "updated": abs(updated - current) > 1e-9,
        "reason": reason,
        "current_ratio": round(controlling_ratio, 4),
        "ratios": [round(value, 4) for value in ratios],
        "rate_mm_s": round(rate, 4),
        "peak_current_ma": round(peak_current, 1),
    }


def balanced_torque_current_targets(
    x: object,
    y: object,
    floor_current_ma: object,
    calibration: dict | None = None,
    *,
    maximum_current_ma: object = HYBRID_PASSIVE_TORQUE_MAX_CURRENT_MA,
) -> tuple[list[int], dict]:
    """Return a bounded four-motor torque vector for the current encoder pose.

    The current is only a motor-torque proxy.  Geometry supplies the relative
    ratios; the operator-selected value remains the minimum command.  When a
    boundary point has no strictly-positive free-space equilibrium, equal low
    torque is the safest fallback because board contact/friction supplies the
    missing reaction and no cable is deliberately released.
    """

    try:
        floor = max(
            TRACKING_MIN_CURRENT,
            min(OPERATING_CURRENT_MAX_MA, int(round(float(floor_current_ma)))),
        )
        maximum = max(
            floor,
            min(OPERATING_CURRENT_MAX_MA, int(round(float(maximum_current_ma)))),
        )
    except (TypeError, ValueError):
        floor = TRACKING_DEFAULT_CURRENT
        maximum = HYBRID_PASSIVE_TORQUE_MAX_CURRENT_MA
    balance = equilibrium_current_targets(x, y, floor, calibration)
    raw_targets = balance.get("target_currents_ma") if balance.get("ok") else None
    if not isinstance(raw_targets, list) or len(raw_targets) != len(MOTOR_IDS):
        return [floor for _ in MOTOR_IDS], balance
    return (
        [max(floor, min(maximum, int(round(float(value))))) for value in raw_targets],
        balance,
    )


def slewed_current(current_ma: object, target_ma: object, step_ma: object) -> int:
    """Move one integer current set-point by at most ``step_ma``."""

    current = int(round(float(current_ma)))
    target = int(round(float(target_ma)))
    step = max(1, abs(int(round(float(step_ma)))))
    return current + max(-step, min(step, target - current))


def equilibrium_current_limits_at(
    x: object,
    y: object,
    calibration: dict | None = None,
    fallback_current: object = None,
) -> dict:
    """Return safe per-motor caps and force-balance targets at one XY point."""
    data = calibration if calibration is not None else calibration_data()
    try:
        floor = float(data.get("grid_tension_target_current_ma", GRID_DEFAULT_TENSION_CURRENT_MA))
    except (AttributeError, TypeError, ValueError):
        floor = float(GRID_DEFAULT_TENSION_CURRENT_MA)
    target = equilibrium_current_targets(x, y, floor, data)
    if not target.get("ok"):
        base = grid_current_limits_at(x, y, data, fallback_current)
        return {"current_limits_ma": base, "target_currents_ma": None, "model": target.get("model"), "fallback": True}
    target_currents = [float(value) for value in target["target_currents_ma"]]
    map_caps = grid_current_limits_at(x, y, data, fallback_current)
    # A small cap headroom lets position mode reach the feedback target. The
    # validated grid cap remains the hard local ceiling; all values stay in the
    # Normal user commands stay in the 300..2A operating range. HARD_CURRENT
    # is retained only for the independent transient/driver protection path.
    desired_caps = [
        max(300.0, value + GRID_FORCE_BALANCE_HEADROOM_MA)
        for value in target_currents
    ]
    limits = [
        max(300, min(OPERATING_CURRENT_MAX_MA, int(round(min(map_cap, desired_cap)))))
        for map_cap, desired_cap in zip(map_caps, desired_caps)
    ]
    return {
        "current_limits_ma": limits,
        "target_currents_ma": [round(value, 3) for value in target_currents],
        "model": target["model"],
        "fallback": False,
    }


def auto_balance_force_currents(
    current_limits: list[int],
    target_currents: object,
    maximum_limit: int = OPERATING_CURRENT_MAX_MA,
    maximum_limits: object = None,
) -> list[int]:
    """Nudge command caps toward the position-dependent force targets."""
    if not isinstance(target_currents, (list, tuple)) or len(target_currents) != len(MOTOR_IDS):
        return current_limits
    try:
        desired = [float(value) for value in target_currents]
    except (TypeError, ValueError):
        return current_limits
    with STATE_LOCK:
        telemetry = copy.deepcopy(STATE.get("telemetry", {}))
    maximum = max(300, min(OPERATING_CURRENT_MAX_MA, int(maximum_limit)))
    if isinstance(maximum_limits, (list, tuple)) and len(maximum_limits) == len(MOTOR_IDS):
        try:
            per_motor_maximum = [max(300, min(OPERATING_CURRENT_MAX_MA, int(value))) for value in maximum_limits]
        except (TypeError, ValueError):
            per_motor_maximum = [maximum for _ in MOTOR_IDS]
    else:
        per_motor_maximum = [maximum for _ in MOTOR_IDS]
    updated = list(current_limits)
    changes = []
    for index, address in enumerate(MOTOR_IDS):
        measured = telemetry.get(str(address), {}).get("phase_current")
        if not isinstance(measured, (int, float)) or not math.isfinite(float(measured)):
            continue
        measured_abs = abs(float(measured))
        if measured_abs < desired[index] - GRID_FORCE_BALANCE_DEADBAND_MA:
            next_value = min(per_motor_maximum[index], updated[index] + GRID_CURRENT_ADJUST_STEP_MA)
        elif measured_abs > desired[index] + GRID_FORCE_BALANCE_DEADBAND_MA:
            next_value = max(300, updated[index] - GRID_CURRENT_ADJUST_STEP_MA)
        else:
            next_value = updated[index]
        if next_value != updated[index]:
            changes.append({"motor": index + 1, "measured_ma": round(measured_abs, 1), "target_ma": round(desired[index], 1), "from": updated[index], "to": next_value})
            updated[index] = next_value
    if changes:
        append_process_log("force_balance_current_adjust", changes=changes, target_currents_ma=desired)
    return updated


def attach_grid_compensation(
    calibration: dict,
    raw_samples: object,
    *,
    rows: object = GRID_DEFAULT_ROWS,
    cols: object = GRID_DEFAULT_COLS,
    reference_phase_current_ma: object = None,
    target_current_ma: object = None,
    plane_reference_z_mm: object = None,
    max_fit_error_mm: object = GRID_MAX_FIT_ERROR_MM,
) -> dict:
    """Return a calibration copy with the offline table attached."""
    if not isinstance(calibration, dict):
        raise ValueError("校准结构必须是对象")
    updated = copy.deepcopy(calibration)
    grid = build_grid_compensation(
        raw_samples,
        calibration,
        rows=rows,
        cols=cols,
        reference_phase_current_ma=reference_phase_current_ma,
        target_current_ma=target_current_ma,
        plane_reference_z_mm=plane_reference_z_mm,
        max_fit_error_mm=max_fit_error_mm,
    )
    updated["grid_compensation"] = grid
    # Keep the top-level settings in lockstep with the persisted table.  The
    # loader intentionally invalidates a table whose configured shape or target
    # current differs, so custom offline grids must carry their own metadata.
    updated["grid_rows"] = int(grid["rows"])
    updated["grid_cols"] = int(grid["cols"])
    if grid.get("target_current_ma") is not None:
        updated["grid_tension_target_current_ma"] = int(round(float(grid["target_current_ma"])))
    return updated


def save_grid_compensation(
    raw_samples: object,
    calibration: dict | None = None,
    *,
    rows: object = GRID_DEFAULT_ROWS,
    cols: object = GRID_DEFAULT_COLS,
    reference_phase_current_ma: object = None,
    target_current_ma: object = None,
    plane_reference_z_mm: object = None,
    max_fit_error_mm: object = GRID_MAX_FIT_ERROR_MM,
) -> dict:
    """Persist an offline-built table without opening or touching a serial port."""
    current = calibration_data() if calibration is None else calibration
    updated = attach_grid_compensation(
        current,
        raw_samples,
        rows=rows,
        cols=cols,
        reference_phase_current_ma=reference_phase_current_ma,
        target_current_ma=target_current_ma,
        plane_reference_z_mm=plane_reference_z_mm,
        max_fit_error_mm=max_fit_error_mm,
    )
    with STATE_LOCK:
        STATE["calibration"] = copy.deepcopy(updated)
    persist_calibration(updated)
    return updated


