def blank_internal_feedback_calibration() -> dict:
    """Return motor-only repeatability diagnostics for the four-corner model.

    This record is intentionally separate from the Cartesian model.  Encoder
    residuals can certify that the motors replay their own saved targets, but
    they cannot turn an encoder-only self-check into an independent world-frame
    measurement.
    """
    return {
        "version": INTERNAL_FEEDBACK_CALIBRATION_VERSION,
        "status": "pending",
        "method": "four_corner_geometry_encoder_closed_loop",
        "verified": False,
        "sample_count": 0,
        "position_rms_deg": None,
        "position_p95_deg": None,
        "position_max_deg": None,
        "current_spread_ma": None,
        "repeatability_deg": None,
        "reason": "完成四角校准后，可用四角复现检查编码器重复性；不需要相机",
        "updated_at": None,
    }


def has_center_tension_datum(calibration: object) -> bool:
    """Return whether all four absolute curves contain the mechanism-centre knot."""
    if not isinstance(calibration, dict):
        return False
    distances = calibration.get("distance_samples_mm")
    positions = calibration.get("position_samples_deg")
    if not (
        isinstance(distances, list)
        and isinstance(positions, list)
        and len(distances) == len(MOTOR_IDS)
        and len(positions) == len(MOTOR_IDS)
    ):
        return False
    center_x = MECHANISM_CENTER_X_MM
    center_y = MECHANISM_CENTER_Y_MM
    anchor_x, anchor_y = workspace_anchor_coordinates(calibration)
    center_distances = [
        math.hypot(center_x - x, center_y - y)
        for x, y in zip(anchor_x, anchor_y)
    ]
    for index in range(len(MOTOR_IDS)):
        distance_row = distances[index]
        position_row = positions[index]
        if not isinstance(distance_row, list) or not isinstance(position_row, list) or len(distance_row) != len(position_row):
            return False
        try:
            if not any(abs(float(value) - center_distances[index]) <= 1e-6 for value in distance_row):
                return False
        except (TypeError, ValueError):
            return False
    return True


def strip_center_tension_datum(calibration: dict) -> dict:
    """Return a four-corner copy with any persisted centre knot removed."""
    result = copy.deepcopy(calibration)
    distances = result.get("distance_samples_mm")
    positions = result.get("position_samples_deg")
    if not isinstance(distances, list) or not isinstance(positions, list):
        return result
    center_x = MECHANISM_CENTER_X_MM
    center_y = MECHANISM_CENTER_Y_MM
    anchor_x, anchor_y = workspace_anchor_coordinates(result)
    center_distances = [
        math.hypot(center_x - x, center_y - y)
        for x, y in zip(anchor_x, anchor_y)
    ]
    for index in range(min(len(MOTOR_IDS), len(distances), len(positions))):
        distance_row = distances[index]
        position_row = positions[index]
        if not isinstance(distance_row, list) or not isinstance(position_row, list):
            continue
        if len(distance_row) != len(position_row) or len(distance_row) < 2:
            continue
        slot = min(
            range(len(distance_row)),
            key=lambda item: abs(float(distance_row[item]) - center_distances[index]),
        )
        if abs(float(distance_row[slot]) - center_distances[index]) <= 1e-6:
            distances[index] = distance_row[:slot] + distance_row[slot + 1:]
            positions[index] = position_row[:slot] + position_row[slot + 1:]
    return result


