def append_process_log(event: str, **fields: object) -> None:
    """Append a compact JSONL record for later trajectory/calibration analysis."""
    append_process_logs([(event, fields)])


def _append_process_logs_sync(records: list[tuple[str, dict[str, object]]]) -> None:
    """Append high-rate JSONL records in one open/lock operation.

    Grid feedback is decoded at the bus cadence. Opening and closing the log
    file for every frame needlessly competes with serial reads, so high-rate
    callers batch a small number of records while retaining every sample.
    """
    if not records:
        return
    try:
        lines: list[str] = []
        for event, fields in records:
            record = {"ts": round(time.time(), 3), "monotonic": round(time.monotonic(), 3), "event": event}
            record.update(fields)
            lines.append(json.dumps(record, ensure_ascii=False, separators=(",", ":"), default=str))
        with PROCESS_LOG_LOCK:
            with PROCESS_LOG_FILE.open("a", encoding="utf-8", newline="") as handle:
                handle.write("\n".join(lines) + "\n")
        # Mirror every semantic event into the active per-run record.  The
        # recorder is asynchronous, so this does not add disk I/O to the motor
        # control loop.
        for event, fields in records:
            manual_test_emit(event, record_channel="process_log", **fields)
        with STATE_LOCK:
            STATE["process_log_count"] = int(STATE.get("process_log_count", 0)) + len(records)
            STATE["last_process_event"] = records[-1][0]
    except OSError:
        # Logging must never interrupt a motor safety path.
        return


def _process_log_writer() -> None:
    """Drain deferred motion samples away from the 100 Hz serial worker."""
    pending: list[tuple[str, dict[str, object]]] = []
    while True:
        item = PROCESS_LOG_QUEUE.get()
        if item is None:
            return
        pending.append(item)
        # Coalesce records that arrived during the same scheduler slice so the
        # file is opened once instead of once per trajectory sample.
        while len(pending) < 64:
            try:
                next_item = PROCESS_LOG_QUEUE.get_nowait()
            except queue.Empty:
                break
            if next_item is None:
                _append_process_logs_sync(pending)
                return
            pending.append(next_item)
        _append_process_logs_sync(pending)
        pending.clear()


def append_process_logs_async(records: list[tuple[str, dict[str, object]]]) -> None:
    """Queue non-safety trajectory samples without blocking a motor tick."""
    if not records:
        return
    if not PROCESS_LOG_WRITER_STARTED.is_set():
        PROCESS_LOG_WRITER_STARTED.set()
        threading.Thread(
            target=_process_log_writer,
            name="y42-process-log-writer",
            daemon=True,
        ).start()
    for record in records:
        PROCESS_LOG_QUEUE.put(record)


def append_process_logs(records: list[tuple[str, dict[str, object]]]) -> None:
    """Append semantic/safety records synchronously."""
    _append_process_logs_sync(records)


def calibration_model_context(calibration: dict | None = None) -> dict:
    """Describe the reusable geometry while keeping recalibration offsets separate.

    Encoder absolute positions can jump after a new four-corner calibration even
    when the rope geometry is unchanged.  Analysis therefore needs both the raw
    absolute degree values and a zero-referenced rope-length vector.  The model
    family key intentionally excludes intercepts: intercepts are the per-session
    absolute offset, while workspace, direction and slope define the reusable
    kinematic model.
    """
    data = calibration if calibration is not None else calibration_data()
    try:
        slopes = effective_slopes(data)
        intercepts = [float(value) for value in data.get("intercept", [])]
        if len(slopes) != len(MOTOR_IDS) or len(intercepts) != len(MOTOR_IDS):
            raise ValueError
        if any(not math.isfinite(value) for value in slopes + intercepts) or any(abs(value) < 1e-9 for value in slopes):
            raise ValueError
        payload = {
            "frame": data.get("coordinate_frame", "ball_center_workspace"),
            "workspace": [WORKSPACE_WIDTH_MM, WORKSPACE_HEIGHT_MM],
            "motor_frame": [ANCHOR_WIDTH_MM, ANCHOR_HEIGHT_MM],
            "motor_frame_origin": [MOTOR_FRAME_ORIGIN_X_MM, MOTOR_FRAME_ORIGIN_Y_MM],
            "motor_centers": [list(pair) for pair in zip(*motor_center_coordinates(data))],
            "cable_exit_model": CABLE_EXIT_MODEL,
            "spool_radius": SPOOL_WINDING_RADIUS_MM,
            "spool_winding_z_range": [SPOOL_WINDING_Z_MIN_MM, SPOOL_WINDING_Z_MAX_MM],
            "ball_attachment_span": [BALL_ATTACHMENT_SPAN_X_MM, BALL_ATTACHMENT_SPAN_Y_MM],
            "ball_attachment_z": BALL_ATTACHMENT_Z_MM,
            "platform_yaw": PLATFORM_COMMAND_YAW_DEG,
            "direction": list(data.get("encoder_positive_direction", [])),
            "slopes": [round(value, 9) for value in slopes],
        }
        family_key = hashlib.blake2b(
            json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8"),
            digest_size=8,
        ).hexdigest()
        return {
            "model_family_key": family_key,
            "position_reference_deg": [round(value, 6) for value in intercepts],
            "position_reference": "calibrated_intercept_zero",
            "coordinate_frame": "ball_center_workspace",
            "workspace_mm": [WORKSPACE_WIDTH_MM, WORKSPACE_HEIGHT_MM],
            "motor_frame_mm": [ANCHOR_WIDTH_MM, ANCHOR_HEIGHT_MM],
            "motor_frame_origin_mm": [MOTOR_FRAME_ORIGIN_X_MM, MOTOR_FRAME_ORIGIN_Y_MM],
            "motor_center_coordinates_mm": [list(pair) for pair in zip(*motor_center_coordinates(data))],
            "cable_exit_model": CABLE_EXIT_MODEL,
            "cable_exit_coordinates_mm": [list(pair) for pair in zip(*cable_exit_coordinates(data))],
            "ball_attachment_offsets_mm": [list(pair) for pair in zip(*ball_attachment_offsets(data))],
            "effective_center_anchors_mm": [list(pair) for pair in zip(*workspace_anchor_coordinates(data))],
        }
    except (AttributeError, TypeError, ValueError):
        return {
            "model_family_key": None,
            "position_reference_deg": None,
            "position_reference": "unavailable",
            "coordinate_frame": "ball_center_workspace",
            "workspace_mm": [WORKSPACE_WIDTH_MM, WORKSPACE_HEIGHT_MM],
            "motor_frame_mm": [ANCHOR_WIDTH_MM, ANCHOR_HEIGHT_MM],
            "motor_frame_origin_mm": [MOTOR_FRAME_ORIGIN_X_MM, MOTOR_FRAME_ORIGIN_Y_MM],
            "motor_center_coordinates_mm": [list(pair) for pair in zip(*motor_center_coordinates(data))],
            "cable_exit_model": CABLE_EXIT_MODEL,
            "cable_exit_coordinates_mm": [list(pair) for pair in zip(*cable_exit_coordinates(data))],
            "ball_attachment_offsets_mm": [list(pair) for pair in zip(*ball_attachment_offsets(data))],
            "effective_center_anchors_mm": [list(pair) for pair in zip(*workspace_anchor_coordinates(data))],
        }


def calibration_relative_rope_lengths(
    positions: object,
    calibration: dict | None = None,
) -> list[float] | None:
    """Convert absolute encoder positions to per-session zero-referenced lengths.

    This vector is the cross-calibration analysis coordinate.  A new calibration
    may change every encoder intercept, but subtracting that intercept before
    dividing by the current slope preserves the same rope-displacement model.
    """
    data = calibration if calibration is not None else calibration_data()
    if not isinstance(positions, (list, tuple)) or len(positions) != len(MOTOR_IDS):
        return None
    try:
        values = [float(value) for value in positions]
        intercepts = [float(value) for value in data["intercept"]]
        slopes = effective_slopes(data)
        result = [
            (value - intercept) / slope
            for value, intercept, slope in zip(values, intercepts, slopes)
        ]
    except (KeyError, IndexError, TypeError, ValueError, ZeroDivisionError):
        return None
    return [round(value, 6) for value in result] if all(math.isfinite(value) for value in result) else None


def recent_process_log(limit: int = 200) -> list[dict]:
    try:
        wanted = max(1, min(int(limit), 1000))
        with PROCESS_LOG_LOCK:
            # Read backwards in small chunks.  The previous read_text().splitlines()
            # path duplicated the whole history in RAM whenever the UI requested
            # the recent log, which became visible after long 100Hz feedback runs.
            with PROCESS_LOG_FILE.open("rb") as handle:
                handle.seek(0, os.SEEK_END)
                position = handle.tell()
                chunks: list[bytes] = []
                newline_count = 0
                while position > 0 and newline_count <= wanted:
                    size = min(65536, position)
                    position -= size
                    handle.seek(position)
                    chunk = handle.read(size)
                    chunks.append(chunk)
                    newline_count += chunk.count(b"\n")
                raw = b"".join(reversed(chunks))
            lines = raw.decode("utf-8").splitlines()[-wanted:]
        return [json.loads(line) for line in lines if line.strip()]
    except (OSError, ValueError, TypeError):
        return []


def persist_calibration(calibration: dict) -> None:
    """Atomically save calibration/settings so a browser refresh cannot see a half-written file."""
    temporary = CALIBRATION_FILE.with_suffix(".json.tmp")
    temporary.write_text(json.dumps(calibration, ensure_ascii=False, indent=2), encoding="utf-8")
    temporary.replace(CALIBRATION_FILE)


def normalized_slope_trims(calibration: dict | None = None) -> list[float]:
    data = calibration if calibration is not None else calibration_data()
    raw = data.get("slope_trim_percent", [])
    try:
        values = [float(value) for value in raw]
    except (TypeError, ValueError):
        values = []
    if len(values) != len(MOTOR_IDS) or any(not math.isfinite(value) for value in values):
        return [0.0 for _ in MOTOR_IDS]
    return [max(-SLOPE_TRIM_LIMIT_PERCENT, min(SLOPE_TRIM_LIMIT_PERCENT, value)) for value in values]


def effective_slopes(calibration: dict | None = None) -> list[float]:
    data = calibration if calibration is not None else calibration_data()
    try:
        raw = [float(value) for value in data["slope"]]
    except (KeyError, TypeError, ValueError):
        return [0.0 for _ in MOTOR_IDS]
    trims = normalized_slope_trims(data)
    return [value * (1.0 + trim / 100.0) for value, trim in zip(raw, trims)]


def trajectory_current_limit(calibration: dict | None = None) -> int:
    data = calibration if calibration is not None else calibration_data()
    try:
        value = int(data.get("trajectory_current", TRAJECTORY_DEFAULT_CURRENT))
    except (TypeError, ValueError):
        value = TRAJECTORY_DEFAULT_CURRENT
    return max(300, min(OPERATING_CURRENT_MAX_MA, value))


def trajectory_runtime_current() -> int:
    """Return the live drawing current limit, including an in-flight UI change."""
    with STATE_LOCK:
        override = STATE.get("trajectory_current_override")
    try:
        if override is not None:
            value = int(override)
        else:
            calibration = calibration_data()
            value = int(calibration.get("draw_tension_current_ma", calibration.get("trajectory_current", TRAJECTORY_DEFAULT_CURRENT)))
    except (TypeError, ValueError):
        value = trajectory_current_limit()
    return max(TRAJECTORY_TENSION_MIN_CURRENT, min(TRAJECTORY_TENSION_MAX_CURRENT, value))


def trajectory_runtime_current_for_spec(spec: dict | None = None) -> int:
    """Return the live current cap, honoring an explicit UI override.

    The ESP32 compatibility profile keeps its continuous timing parameters and
    uses its gentle 1 A position-current ceiling. A live slider change remains
    authoritative for the current run.
    """

    with STATE_LOCK:
        override = STATE.get("trajectory_current_override")
    if override is not None:
        try:
            value = int(override)
        except (TypeError, ValueError):
            value = ESP32_SMOOTH_MOTION_CURRENT_MA
    elif isinstance(spec, dict) and spec.get("motion_profile") == ESP32_SMOOTH_PROFILE:
        value = ESP32_SMOOTH_MOTION_CURRENT_MA
    else:
        value = trajectory_runtime_current()
    return max(TRAJECTORY_TENSION_MIN_CURRENT, min(TRAJECTORY_TENSION_MAX_CURRENT, value))


def overcurrent_trip_limit(command_limit: int = HARD_CURRENT) -> int:
    """Return the fast-trip threshold for the currently commanded current."""
    try:
        limit = int(command_limit)
    except (TypeError, ValueError):
        limit = HARD_CURRENT
    return min(HARD_CURRENT, max(OVERCURRENT_MIN_TRIP_MA, limit + OVERCURRENT_MARGIN_MA))


def normalized_trajectory_current_limits(current: object) -> list[int]:
    """Normalize one shared or four independent current limits for 0xAA."""
    if isinstance(current, (list, tuple)):
        values = list(current)
    else:
        values = [current for _ in MOTOR_IDS]
    if len(values) != len(MOTOR_IDS):
        raise ValueError("四电机合帧的电流上限必须是一个值或四个值")
    try:
        return [max(300, min(TRAJECTORY_TENSION_MAX_CURRENT, int(value))) for value in values]
    except (TypeError, ValueError):
        raise ValueError("轨迹电流上限必须是有效整数") from None


def auto_balance_trajectory_currents(current_limits: list[int], maximum_limit: int = OPERATING_CURRENT_MAX_MA) -> list[int]:
    """Balance per-motor current caps from phase-current feedback.

    Phase current is a tension proxy, not a calibrated force sensor.  The
    controller therefore uses a deadband and small steps. A low-current motor
    gets a little more holding-current headroom and a high-current motor gets
    a little less. It never changes the geometric target length: changing a
    cable length inside the position transform would visibly turn a circle
    into an ellipse.
    """
    maximum_limit = max(300, min(OPERATING_CURRENT_MAX_MA, int(maximum_limit)))
    with STATE_LOCK:
        telemetry = copy.deepcopy(STATE.get("telemetry", {}))
    currents = []
    for address in MOTOR_IDS:
        value = telemetry.get(str(address), {}).get("phase_current")
        if isinstance(value, (int, float)) and math.isfinite(float(value)):
            currents.append(abs(float(value)))
        else:
            currents.append(float("nan"))
    valid = [value for value in currents if math.isfinite(value)]
    if len(valid) < 3:
        return current_limits
    median = statistics.median(valid)
    updated = list(current_limits)
    changed = []
    for index, value in enumerate(currents):
        if not math.isfinite(value):
            continue
        if value < median - TRAJECTORY_BALANCE_DEADBAND_MA:
            next_value = min(maximum_limit, updated[index] + TRAJECTORY_BALANCE_STEP_MA)
        elif value > median + TRAJECTORY_BALANCE_DEADBAND_MA:
            next_value = max(TRAJECTORY_BALANCE_MIN_LIMIT, updated[index] - TRAJECTORY_BALANCE_STEP_MA)
        else:
            next_value = updated[index]
        if next_value != updated[index]:
            changed.append({"motor": index + 1, "phase_current": round(value, 1), "from": updated[index], "to": next_value})
            updated[index] = next_value
    if changed:
        with STATE_LOCK:
            balance = dict(STATE.get("trajectory_balance", {}))
            balance["adjustments"] = int(balance.get("adjustments", 0)) + len(changed)
            current_text = "、".join(f"M{x['motor']} {x['from']}→{x['to']}mA" for x in changed)
            balance["last"] = f"反馈中位数 {median:.0f}mA：{current_text}；仅调整电流上限，几何目标不变"
            STATE["trajectory_balance"] = balance
        append_process_log(
            "trajectory_tension_balance",
            median_current=round(median, 1),
            currents=currents,
            changes=changed,
        )
    return updated


def adapt_calibration_slope_from_currents(
    currents: object,
    target_current: int = CALIBRATION_TEST_TENSION_TARGET_CURRENT,
) -> tuple[list[float], list[dict]]:
    """Nudge each fitted rope coefficient from absolute phase-current feedback.

    The three-shape calibration pass deliberately follows the operator's rule:
    a loose cable (lower absolute phase current) gets a small negative slope
    trim, while a tight cable gets a small positive trim.  The update is slow,
    bounded, and only runs on a coherent four-motor feedback snapshot.  The
    live STATE copy is changed before the next 0xAA frame, so motor_degrees()
    immediately uses the new coefficient without blocking the 100 Hz loop.
    """
    try:
        desired = max(50.0, min(float(OPERATING_CURRENT_MAX_MA), float(target_current)))
        measured = [
            abs(float(value))
            if value is not None and math.isfinite(float(value))
            else float("nan")
            for value in list(currents)
        ]
    except (TypeError, ValueError):
        return normalized_slope_trims(), []
    if len(measured) != len(MOTOR_IDS) or sum(math.isfinite(value) for value in measured) < len(MOTOR_IDS):
        return normalized_slope_trims(), []

    calibration = calibration_data()
    trims = normalized_slope_trims(calibration)
    changes: list[dict] = []
    for index, value in enumerate(measured):
        if value < desired - CALIBRATION_TEST_CURRENT_DEADBAND_MA:
            # Low absolute current means this rope is loose: reduce its
            # coefficient gradually, exactly as specified for this calibration.
            delta = -CALIBRATION_TEST_SLOPE_STEP_PERCENT
        elif value > desired + CALIBRATION_TEST_CURRENT_DEADBAND_MA:
            # High absolute current means this rope is tight: increase its
            # coefficient gradually, without changing its sign.
            delta = CALIBRATION_TEST_SLOPE_STEP_PERCENT
        else:
            delta = 0.0
        if not delta:
            continue
        next_trim = max(-SLOPE_TRIM_LIMIT_PERCENT, min(SLOPE_TRIM_LIMIT_PERCENT, trims[index] + delta))
        if abs(next_trim - trims[index]) <= 0.000001:
            continue
        previous = trims[index]
        trims[index] = next_trim
        changes.append(
            {
                "motor": index + 1,
                "phase_current_abs_ma": round(value, 1),
                "from_percent": round(previous, 3),
                "to_percent": round(next_trim, 3),
                "reason": "松绳，系数减小" if delta < 0 else "紧绳，系数增加",
            }
        )
    if not changes:
        return trims, []

    calibration["slope_trim_percent"] = trims
    with STATE_LOCK:
        STATE["calibration"] = calibration
        balance = dict(STATE.get("trajectory_balance", {}))
        balance["enabled"] = True
        balance["target_current_ma"] = round(desired, 1)
        balance["current_values_ma"] = [round(value, 1) for value in measured]
        balance["current_spread_ma"] = round(max(measured) - min(measured), 1)
        balance["adjustments"] = int(balance.get("adjustments", 0)) + len(changes)
        balance["last"] = "；".join(
            f"M{item['motor']} {item['phase_current_abs_ma']:.0f}mA：{item['reason']} {item['to_percent']:+.2f}%"
            for item in changes
        )
        STATE["trajectory_balance"] = balance
    append_process_log(
        "calibration_slope_adaptation",
        target_current_ma=round(desired, 1),
        phase_current_abs_ma=[round(value, 1) for value in measured],
        current_spread_ma=round(max(measured) - min(measured), 1),
        changes=changes,
        slope_trim_percent=trims,
    )
    return trims, changes


def adjust_tracking_current_targets(
    targets: list[int], desired_currents_ma: object
) -> tuple[list[int], list[dict]]:
    """Slew all four torque commands toward the geometry-balanced vector.

    The encoder-derived XY pose changes the desired vector.  Phase current is
    retained in each change record and protected independently, but it is not a
    cable-tension sensor and must not be used to invent a length correction.
    """
    if isinstance(desired_currents_ma, (list, tuple)):
        raw_desired = list(desired_currents_ma)
    else:
        raw_desired = [desired_currents_ma for _ in MOTOR_IDS]
    if len(raw_desired) != len(MOTOR_IDS):
        return list(targets), []
    try:
        desired = [
            max(TRACKING_MIN_CURRENT, min(TRACKING_MAX_CURRENT, int(round(float(value)))))
            for value in raw_desired
        ]
    except (TypeError, ValueError):
        return list(targets), []
    with STATE_LOCK:
        telemetry = copy.deepcopy(STATE.get("telemetry", {}))
    updated = list(targets)
    changes: list[dict] = []
    for index, address in enumerate(MOTOR_IDS):
        measured = telemetry.get(str(address), {}).get("phase_current")
        measured_value = (
            abs(float(measured))
            if isinstance(measured, (int, float)) and math.isfinite(float(measured))
            else None
        )
        next_target = slewed_current(
            updated[index], desired[index], TRACKING_CURRENT_SLEW_MA_PER_UPDATE
        )
        if next_target != updated[index]:
            changes.append(
                {
                    "motor": index + 1,
                    "phase_current": round(measured_value, 1) if measured_value is not None else None,
                    "desired": desired[index],
                    "from": updated[index],
                    "to": next_target,
                }
            )
            updated[index] = next_target
    return updated, changes


def analyze_trajectory_feedback(
    target_path: object,
    actual_path: object,
    phase_currents: object = None,
) -> dict:
    """Compare a requested path with raw encoder-reconstructed feedback.

    The two paths do not necessarily have identical sample counts. Measure a
    bidirectional point-to-polyline contour distance instead of comparing array
    indices or assuming a unique time phase. This remains valid for closed
    strokes whose first and last target points are identical, and target-to-
    measured distance exposes missing sections. This is a diagnostic, not a
    controller: it never writes a new slope.
    """
    result = {
        "status": "待反馈",
        "target_points": 0,
        "actual_points": 0,
        "coverage": 0.0,
        "rms_error_mm": None,
        "mean_error_mm": None,
        "max_error_mm": None,
        "endpoint_error_mm": None,
        "current_values_ma": None,
        "current_spread_ma": None,
        "current_source": "轨迹起点/终点安全窗口",
        "recommendation": "没有足够的四电机原始位置反馈，暂不调整斜率",
    }

    def points(value: object) -> list[tuple[float, float]]:
        if not isinstance(value, list):
            return []
        output: list[tuple[float, float]] = []
        for item in value:
            if not isinstance(item, (list, tuple)) or len(item) < 2:
                continue
            try:
                point = (float(item[0]), float(item[1]))
            except (TypeError, ValueError):
                continue
            if all(math.isfinite(part) for part in point):
                output.append(point)
        return output

    def point_segments(value: object) -> list[list[tuple[float, float]]]:
        if not isinstance(value, list) or not value:
            return []
        # Accept both the legacy flat path and the segmented path used by the
        # web renderer. Empty segments are intentionally discarded, but two
        # non-empty segments are never joined for drawing.
        first = value[0]
        if isinstance(first, (list, tuple)) and len(first) >= 2 and all(
            isinstance(part, (int, float)) for part in first[:2]
        ):
            path = points(value)
            return [path] if path else []
        output = []
        for segment in value:
            path = points(segment)
            if path:
                output.append(path)
        return output

    target_segments = point_segments(target_path)
    target = [point for segment in target_segments for point in segment]
    actual_segments = point_segments(actual_path)
    actual = [point for segment in actual_segments for point in segment]
    result["target_points"] = len(target)
    result["actual_points"] = len(actual)
    result["stroke_count"] = len(target_segments)
    result["actual_stroke_count"] = len(actual_segments)
    result["stroke_metrics"] = []
    if target and actual:
        result["coverage"] = round(min(1.0, len(actual) / max(1, len(target))), 3)
    if len(target) >= 4 and len(actual) >= 4:
        # Match each physical pen stroke independently whenever trace breaks
        # correspond to the requested breaks. This prevents a transfer across
        # blank space (or an overlapping later glyph) from making the metric
        # look artificially better. A legacy unsegmented trace retains the
        # old monotonic forward matcher as a fallback.
        pairs = (
            list(zip(target_segments, actual_segments))
            if len(target_segments) == len(actual_segments)
            else [(target, actual)]
        )

        def point_to_polyline_distance(
            point: tuple[float, float],
            polyline: list[tuple[float, float]],
        ) -> float:
            if len(polyline) == 1:
                return math.hypot(
                    point[0] - polyline[0][0],
                    point[1] - polyline[0][1],
                )
            best = float("inf")
            for first, second in zip(polyline, polyline[1:]):
                vx = second[0] - first[0]
                vy = second[1] - first[1]
                denominator = vx * vx + vy * vy
                if denominator <= 1e-12:
                    projected_x, projected_y = first
                else:
                    fraction = max(
                        0.0,
                        min(
                            1.0,
                            (
                                (point[0] - first[0]) * vx
                                + (point[1] - first[1]) * vy
                            )
                            / denominator,
                        ),
                    )
                    projected_x = first[0] + fraction * vx
                    projected_y = first[1] + fraction * vy
                best = min(
                    best,
                    math.hypot(point[0] - projected_x, point[1] - projected_y),
                )
            return best

        # A closed stroke begins and ends at the same point. A global monotonic
        # nearest-point matcher can therefore map the first measured sample to
        # the final target point and report a 20--30 mm error for a visibly
        # correct rectangle. Use a bidirectional point-to-polyline distance:
        # measured->target reports contour deviation, target->measured reports
        # missing coverage. Neither direction depends on resampling density or
        # mistakes a legal closed-loop endpoint for a time correspondence.
        forward_errors: list[float] = []
        reverse_errors: list[float] = []
        coverage_tolerance_mm = 4.0
        covered_target_points = 0
        stroke_metrics: list[dict] = []
        for stroke_index, (stroke_target, stroke_actual) in enumerate(pairs):
            if len(stroke_target) < 2 or len(stroke_actual) < 2:
                continue
            stroke_forward = [
                point_to_polyline_distance(point, stroke_target)
                for point in stroke_actual
            ]
            stroke_reverse = [
                point_to_polyline_distance(point, stroke_actual)
                for point in stroke_target
            ]
            forward_errors.extend(stroke_forward)
            reverse_errors.extend(stroke_reverse)
            stroke_covered = sum(
                error <= coverage_tolerance_mm for error in stroke_reverse
            )
            covered_target_points += stroke_covered
            forward_mse = statistics.mean(value * value for value in stroke_forward)
            reverse_mse = statistics.mean(value * value for value in stroke_reverse)
            stroke_metrics.append(
                {
                    "stroke": stroke_index + 1,
                    "target_points": len(stroke_target),
                    "actual_points": len(stroke_actual),
                    "coverage": round(stroke_covered / len(stroke_target), 3),
                    "coverage_tolerance_mm": coverage_tolerance_mm,
                    "rms_error_mm": round(math.sqrt((forward_mse + reverse_mse) / 2.0), 3),
                    "trace_rms_error_mm": round(math.sqrt(forward_mse), 3),
                    "target_rms_error_mm": round(math.sqrt(reverse_mse), 3),
                    "max_error_mm": round(max(stroke_forward + stroke_reverse), 3),
                    "endpoint_error_mm": round(
                        math.hypot(
                            stroke_actual[-1][0] - stroke_target[-1][0],
                            stroke_actual[-1][1] - stroke_target[-1][1],
                        ),
                        3,
                    ),
                }
            )
        result["stroke_metrics"] = stroke_metrics
        result["coverage_tolerance_mm"] = coverage_tolerance_mm
        result["coverage"] = round(covered_target_points / max(1, len(target)), 3)
        forward_mse = statistics.mean(value * value for value in forward_errors)
        reverse_mse = statistics.mean(value * value for value in reverse_errors)
        result["rms_error_mm"] = round(math.sqrt((forward_mse + reverse_mse) / 2.0), 3)
        result["trace_rms_error_mm"] = round(math.sqrt(forward_mse), 3)
        result["target_rms_error_mm"] = round(math.sqrt(reverse_mse), 3)
        result["mean_error_mm"] = round(
            (statistics.mean(forward_errors) + statistics.mean(reverse_errors)) / 2.0,
            3,
        )
        result["max_error_mm"] = round(max(forward_errors + reverse_errors), 3)
        result["endpoint_error_mm"] = round(
            math.hypot(actual[-1][0] - target[-1][0], actual[-1][1] - target[-1][1]),
            3,
        )
        if result["coverage"] >= 0.80 and result["rms_error_mm"] <= 3.0:
            result["status"] = "反馈拟合正常"
            result["recommendation"] = "轨迹误差较小，不改写校准斜率"
        elif result["coverage"] >= 0.60 and result["rms_error_mm"] <= 8.0:
            result["status"] = "存在轻微跟随误差"
            result["recommendation"] = "先降低速度或增加张力复测；不把运动滞后直接写入斜率"
        else:
            result["status"] = "反馈拟合异常"
            result["recommendation"] = "先检查四电机位置流、几何尺寸和绳路；确认重复出现后再调斜率"
    if isinstance(phase_currents, (list, tuple)):
        try:
            currents = [
                float(value)
                for value in phase_currents
                if value is not None and math.isfinite(float(value))
            ]
        except (TypeError, ValueError):
            currents = []
        if currents:
            result["current_values_ma"] = [round(value, 1) for value in currents]
            result["current_spread_ma"] = round(max(currents) - min(currents), 1)
            if result["current_spread_ma"] > 120.0:
                result["recommendation"] += "；四台相电流差较大，只建议调整张力电流，不自动修改几何斜率"
    return result


def slope_consistency_error(slopes: object) -> str | None:
    if not isinstance(slopes, list) or len(slopes) != len(MOTOR_IDS):
        return "缺少四台电机完整绳长斜率"
    try:
        values = [float(value) for value in slopes]
    except (TypeError, ValueError):
        return "绳长斜率包含无效数字"
    magnitudes = [abs(value) for value in values]
    minimum = min(magnitudes, default=0.0)
    maximum = max(magnitudes, default=0.0)
    if minimum <= 0.05:
        return "四台绳长斜率中存在接近 0 的结果，不能使用"
    ratio = maximum / minimum
    if ratio > MAX_CROSS_MOTOR_SLOPE_RATIO:
        details = "、".join(f"M{index + 1}={value:.4f}°/mm" for index, value in enumerate(values))
        return (
            f"四台绳长斜率不一致：{details}；最大/最小={ratio:.1%}，"
            f"超过 {MAX_CROSS_MOTOR_SLOPE_RATIO - 1:.0%} 允许差异"
        )
    return None


