def load_calibration() -> None:
    try:
        data = json.loads(CALIBRATION_FILE.read_text(encoding="utf-8"))
        # Geometry v4 accidentally collapsed the 150 mm physical cable exits
        # onto the 110 mm user X range.  Its raw torque-corner samples are still
        # valuable because the ball was physically pulled to the real anchors.
        # Refit those samples once, but only when the recovered physical model
        # has the high R² seen in the historical good runs.
        if (
            data.get("geometry_version") == 4
            and data.get("coordinate_frame") == "ball_center_workspace"
            and data.get("workspace_calibration_verified") is True
            and isinstance(data.get("samples"), list)
        ):
            migrated, migration_reason = compute_calibration(
                data["samples"],
                WORKSPACE_WIDTH_MM,
                WORKSPACE_HEIGHT_MM,
                float(data.get("ball", DEFAULT_BALL_DIAMETER_MM)),
            )
            if migrated is not None and min(migrated.get("r2", [0.0])) >= 0.99:
                for key in (
                    "direction_reverse",
                    "encoder_positive_direction",
                    "strong_current",
                    "weak_current",
                    "trajectory_current",
                    "draw_tension_current_ma",
                    "force_position_target_current_ma",
                    "tracking_current_ma",
                    "path_speed_mm_s",
                    "slope_trim_percent",
                    "tracking_pen_up_height_mm",
                    "tracking_pen_down_height_mm",
                    "grid_tension_target_current_ma",
                    "center_tension_target_current_ma",
                    "grid_rows",
                    "grid_cols",
                ):
                    if key in data:
                        migrated[key] = copy.deepcopy(data[key])
                migrated["grid_compensation"] = blank_grid_compensation(
                    migrated.get("grid_rows", GRID_DEFAULT_ROWS),
                    migrated.get("grid_cols", GRID_DEFAULT_COLS),
                )
                old_center = data.get("center_tension_calibration")
                selected = old_center.get("selected") if isinstance(old_center, dict) else None
                if isinstance(selected, dict) and selected.get("passed") is True:
                    with_center, center_reason = apply_center_tension_datum(
                        migrated,
                        selected,
                        copy.deepcopy(old_center),
                    )
                    if with_center is not None:
                        migrated = with_center
                    else:
                        migrated["center_tension_calibration"] = blank_center_tension_calibration()
                        migrated["center_tension_calibration"]["reason"] = center_reason
                migrated["migrated_from_geometry_version"] = 4
                migrated["migration_reason"] = "原始四角样本按 150×150mm 物理锚点重拟合；旧网格已强制失效"
                context = calibration_model_context(migrated)
                migrated["model_family_key"] = context.get("model_family_key")
                migrated["position_reference_deg"] = context.get("position_reference_deg")
                migrated["position_reference"] = context.get("position_reference")
                backup_file = CALIBRATION_FILE.with_name(
                    CALIBRATION_FILE.stem + ".geometry-v4.backup.json"
                )
                if not backup_file.exists():
                    backup_file.write_text(
                        json.dumps(data, ensure_ascii=False, indent=2) + "\n",
                        encoding="utf-8",
                    )
                data = migrated
                persist_calibration(migrated)
                append_process_log(
                    "calibration_geometry_migrated",
                    from_version=4,
                    to_version=GEOMETRY_VERSION,
                    workspace=[WORKSPACE_WIDTH_MM, WORKSPACE_HEIGHT_MM],
                    anchor_frame=[ANCHOR_WIDTH_MM, ANCHOR_HEIGHT_MM],
                    r2=migrated.get("r2"),
                    slope=migrated.get("slope"),
                    center_datum=has_center_tension_datum(migrated),
                )
            elif migrated is None:
                data["quality_error"] = "旧几何样本迁移失败：" + migration_reason
        calibration = blank_calibration()
        calibration.update(data)
        persisted_width = data.get("workspace_width")
        persisted_height = data.get("workspace_height")
        try:
            workspace_matches_pc_frame = (
                math.isclose(float(persisted_width), WORKSPACE_WIDTH_MM, abs_tol=0.0001)
                and math.isclose(float(persisted_height), WORKSPACE_HEIGHT_MM, abs_tol=0.0001)
            )
        except (TypeError, ValueError):
            workspace_matches_pc_frame = False
        # Keep the live UI/solver on the current PC frame. A legacy file may
        # remain on disk for diagnosis, but its fitted values must not be
        # treated as a valid 110x148 ball-center calibration.
        calibration["workspace_width"] = WORKSPACE_WIDTH_MM
        calibration["workspace_height"] = WORKSPACE_HEIGHT_MM
        calibration["anchor_width"] = ANCHOR_WIDTH_MM
        calibration["anchor_height"] = ANCHOR_HEIGHT_MM
        calibration["motor_frame_origin_mm"] = [MOTOR_FRAME_ORIGIN_X_MM, MOTOR_FRAME_ORIGIN_Y_MM]
        calibration["motor_center_coordinates_mm"] = [list(pair) for pair in zip(*motor_center_coordinates())]
        calibration["cable_exit_offset_x_mm"] = MOTOR_CABLE_EXIT_OFFSET_X_MM
        calibration["spool_winding_radius_mm"] = SPOOL_WINDING_RADIUS_MM
        calibration["spool_reference_radius_mm"] = SPOOL_REFERENCE_RADIUS_MM
        calibration["spool_winding_z_range_mm"] = [SPOOL_WINDING_Z_MIN_MM, SPOOL_WINDING_Z_MAX_MM]
        calibration["ball_center_contact_z_mm"] = BALL_CENTER_CONTACT_Z_MM
        calibration["ball_attachment_z_mm"] = BALL_ATTACHMENT_Z_MM
        calibration["ball_attachment_span_x_mm"] = BALL_ATTACHMENT_SPAN_X_MM
        calibration["ball_attachment_span_y_mm"] = BALL_ATTACHMENT_SPAN_Y_MM
        calibration["platform_command_yaw_deg"] = PLATFORM_COMMAND_YAW_DEG
        calibration["cable_exit_model"] = CABLE_EXIT_MODEL
        calibration["geometry_version"] = GEOMETRY_VERSION
        calibration["coordinate_frame"] = "ball_center_workspace"
        calibration["control_architecture"] = CONTROL_ARCHITECTURE
        calibration["platform_pose_model"] = PLATFORM_POSE_MODEL
        calibration["session_calibration_mode"] = SESSION_CALIBRATION_MODE
        calibration["session_id"] = None
        calibration["session_local_verified"] = False
        calibration["session_tension_held"] = False
        calibration["session_invalid_reason"] = (
            "服务启动或电机曾失能；已保留四角几何模型，绘制启动时从当前编码器位置重新接管"
        )
        calibration["fixed_guide_exit_verified"] = bool(data.get("fixed_guide_exit_verified") is True)
        calibration["deterministic_spool_payout_verified"] = bool(
            data.get("deterministic_spool_payout_verified") is True
        )
        calibration["external_pose_verified"] = bool(data.get("external_pose_verified") is True)
        calibration["calibration_source"] = str(data.get("calibration_source") or "torque_corner_initializer")
        raw_reverse = calibration.get("direction_reverse")
        if not isinstance(raw_reverse, list) or len(raw_reverse) != len(MOTOR_IDS):
            calibration["direction_reverse"] = [False for _ in MOTOR_IDS]
        else:
            calibration["direction_reverse"] = [bool(value) for value in raw_reverse]
        raw_position_direction = calibration.get("encoder_positive_direction")
        try:
            position_direction = [int(value) for value in raw_position_direction]
        except (TypeError, ValueError):
            position_direction = []
        calibration["encoder_positive_direction"] = (
            position_direction
            if len(position_direction) == len(MOTOR_IDS) and all(value in (0, 1) for value in position_direction)
            else []
        )
        # A malformed, legacy, or incomplete grid stays visible for diagnosis
        # but is forced disabled.  Loading the base four-corner calibration must
        # never make an old compensation table live by accident.
        calibration["grid_compensation"] = normalize_grid_compensation(data.get("grid_compensation"))
        try:
            grid_target = int(data.get("grid_tension_target_current_ma", GRID_DEFAULT_TENSION_CURRENT_MA))
        except (TypeError, ValueError):
            grid_target = GRID_DEFAULT_TENSION_CURRENT_MA
        calibration["grid_tension_target_current_ma"] = max(
            GRID_TENSION_MIN_CURRENT_MA,
            min(GRID_TENSION_MAX_CURRENT_MA, grid_target),
        )
        try:
            center_target = int(data.get("center_tension_target_current_ma", CENTER_TENSION_DEFAULT_CURRENT_MA))
        except (TypeError, ValueError):
            center_target = CENTER_TENSION_DEFAULT_CURRENT_MA
        calibration["center_tension_target_current_ma"] = max(
            GRID_TENSION_MIN_CURRENT_MA,
            min(GRID_TENSION_MAX_CURRENT_MA, center_target),
        )
        try:
            grid_rows, grid_cols = normalized_grid_shape(
                data.get("grid_rows", GRID_DEFAULT_ROWS),
                data.get("grid_cols", GRID_DEFAULT_COLS),
            )
        except (TypeError, ValueError):
            grid_rows, grid_cols = GRID_DEFAULT_ROWS, GRID_DEFAULT_COLS
        calibration["grid_rows"] = grid_rows
        calibration["grid_cols"] = grid_cols
        loaded_grid = calibration["grid_compensation"]
        if (
            loaded_grid.get("target_current_ma") is not None
            and not math.isclose(
                float(loaded_grid.get("target_current_ma")),
                float(calibration["grid_tension_target_current_ma"]),
                abs_tol=0.0001,
            )
        ):
            loaded_grid["valid"] = False
            loaded_grid["enabled"] = False
            loaded_grid["invalid_reason"] = "网格张力下限已修改，请重新采集网格"
        if (int(loaded_grid.get("rows", GRID_DEFAULT_ROWS)), int(loaded_grid.get("cols", GRID_DEFAULT_COLS))) != (grid_rows, grid_cols):
            loaded_grid["valid"] = False
            loaded_grid["enabled"] = False
            loaded_grid["invalid_reason"] = "网格行列已修改，请重新采集网格"
        raw_trims = calibration.get("slope_trim_percent", [])
        try:
            trims = [float(value) for value in raw_trims]
        except (TypeError, ValueError):
            trims = []
        calibration["slope_trim_percent"] = (
            [max(-SLOPE_TRIM_LIMIT_PERCENT, min(SLOPE_TRIM_LIMIT_PERCENT, value)) for value in trims]
            if len(trims) == len(MOTOR_IDS) and all(math.isfinite(value) for value in trims)
            else [0.0 for _ in MOTOR_IDS]
        )
        for key, default, minimum, maximum in (
            ("strong_current", CALIBRATION_DEFAULT_STRONG_CURRENT, 50, OPERATING_CURRENT_MAX_MA),
            ("weak_current", CALIBRATION_DEFAULT_WEAK_CURRENT, 20, OPERATING_CURRENT_MAX_MA),
            ("trajectory_current", TRAJECTORY_DEFAULT_CURRENT, 300, OPERATING_CURRENT_MAX_MA),
            ("draw_tension_current_ma", DRAW_TENSION_DEFAULT_CURRENT, TRAJECTORY_TENSION_MIN_CURRENT, TRAJECTORY_TENSION_MAX_CURRENT),
            ("force_position_target_current_ma", FORCE_POSITION_TARGET_FLOOR_MA, SESSION_HOLD_CURRENT_MIN_MA, 900),
            ("tracking_current_ma", TRACKING_CURRENT_LIMIT_DEFAULT_MA, TRACKING_MIN_CURRENT, TRACKING_MAX_CURRENT),
        ):
            try:
                value = int(calibration.get(key, default))
            except (TypeError, ValueError):
                value = default
            calibration[key] = max(minimum, min(maximum, value))
        try:
            path_speed = float(calibration.get("path_speed_mm_s", PATH_SPEED_DEFAULT_MM_S))
        except (TypeError, ValueError):
            path_speed = PATH_SPEED_DEFAULT_MM_S
        calibration["path_speed_mm_s"] = max(PATH_SPEED_MIN_MM_S, min(PATH_SPEED_MAX_MM_S, path_speed))
        geometry_error = None
        if calibration.get("valid") and (
            data.get("geometry_version") != GEOMETRY_VERSION
            or data.get("coordinate_frame") != "ball_center_workspace"
            or not workspace_matches_pc_frame
            or not math.isclose(float(data.get("anchor_width", 0.0)), ANCHOR_WIDTH_MM, abs_tol=0.0001)
            or not math.isclose(float(data.get("anchor_height", 0.0)), ANCHOR_HEIGHT_MM, abs_tol=0.0001)
            or data.get("motor_frame_origin_mm") != [MOTOR_FRAME_ORIGIN_X_MM, MOTOR_FRAME_ORIGIN_Y_MM]
            or not math.isclose(float(data.get("cable_exit_offset_x_mm", -1.0)), MOTOR_CABLE_EXIT_OFFSET_X_MM, abs_tol=0.0001)
            or not math.isclose(float(data.get("spool_winding_radius_mm", -1.0)), SPOOL_WINDING_RADIUS_MM, abs_tol=0.0001)
            or data.get("spool_winding_z_range_mm") != [SPOOL_WINDING_Z_MIN_MM, SPOOL_WINDING_Z_MAX_MM]
            or not math.isclose(float(data.get("ball_center_contact_z_mm", -1.0)), BALL_CENTER_CONTACT_Z_MM, abs_tol=0.0001)
            or not math.isclose(float(data.get("ball_attachment_span_x_mm", -1.0)), BALL_ATTACHMENT_SPAN_X_MM, abs_tol=0.0001)
            or not math.isclose(float(data.get("ball_attachment_span_y_mm", -1.0)), BALL_ATTACHMENT_SPAN_Y_MM, abs_tol=0.0001)
            or not math.isclose(float(data.get("platform_command_yaw_deg", 999.0)), PLATFORM_COMMAND_YAW_DEG, abs_tol=0.0001)
            or data.get("cable_exit_model") != CABLE_EXIT_MODEL
            or data.get("workspace_calibration_verified") is not True
        ):
            geometry_error = (
                "当前四角样本不是STEP v7实物几何（卷轴中心198×148mm、"
                "球心z=25mm、可变卷筒切点），旧样本只可诊断，禁止绝对运动"
            )
            calibration["valid"] = False
        saved_quality_error = str(data.get("quality_error") or "")
        quality_error = geometry_error or (
            slope_consistency_error(effective_slopes(calibration)) if calibration.get("valid") else saved_quality_error or None
        )
        if quality_error:
            calibration["valid"] = False
            calibration["quality_error"] = quality_error
        else:
            calibration["quality_error"] = ""
        # Never trust a hand-edited/stale external flag by itself.  A loaded
        # model is allowed to unlock absolute motion only when its independent
        # pose samples, source tag and fitted curve metadata are all present.
        if calibration.get("external_pose_verified") is True:
            pose_samples = calibration.get("pose_reference_samples")
            curve_rows = calibration.get("position_samples_deg")
            r2_values = calibration.get("r2")
            try:
                r2_ok = (
                    isinstance(r2_values, list)
                    and len(r2_values) == len(MOTOR_IDS)
                    and all(
                        math.isfinite(float(value))
                        and float(value) >= EXTERNAL_POSE_MIN_LINEAR_R2
                        for value in r2_values
                    )
                )
            except (TypeError, ValueError):
                r2_ok = False
            metadata_ok = (
                calibration.get("valid") is True
                and str(calibration.get("calibration_source", "")).strip().lower() in EXTERNAL_POSE_SOURCE_KEYS
                and isinstance(pose_samples, list)
                and len(pose_samples) >= EXTERNAL_POSE_MIN_SAMPLES
                and isinstance(curve_rows, list)
                and len(curve_rows) == len(MOTOR_IDS)
                and all(isinstance(row, list) and len(row) >= 4 for row in curve_rows)
                and r2_ok
            )
            if not metadata_ok:
                calibration["external_pose_verified"] = False
                calibration["calibration_source"] = "torque_corner_initializer"
                calibration["external_pose_invalidated_reason"] = (
                    "已加载的外部位姿元数据不完整或过期；必须重新提交独立位姿样本"
                )
        center_state = calibration.get("center_tension_calibration")
        if not isinstance(center_state, dict):
            center_state = blank_center_tension_calibration()
        # v6 briefly allowed a stable equal-current state to become a fifth
        # distance/encoder knot.  That is circular (the same encoder model was
        # then used to "prove" the pose) and can bend all four curves by tens of
        # degrees.  Strip it on load while retaining the measurements as a
        # diagnostic record.  The original file is backed up by the migration
        # procedure before deployment.
        center_datum_removed = False
        if has_center_tension_datum(calibration):
            calibration = strip_center_tension_datum(calibration)
            center_datum_removed = True
            center_state = copy.deepcopy(center_state)
            center_state.update(
                {
                    "status": "diagnostic",
                    "diagnostic_only": True,
                    "pose_verified": False,
                    "model_applied": False,
                    "reason": (
                        "历史等电流第五点已从位置曲线撤销：等电机力矩不能确定真实球心；"
                        "原始扫描仅保留作摩擦/张力诊断"
                    ),
                }
            )
            for diagnostic_level in center_state.get("levels", []):
                if isinstance(diagnostic_level, dict):
                    diagnostic_level["diagnostic_only"] = True
                    diagnostic_level["pose_verified"] = False
                    if diagnostic_level.get("passed") is True:
                        diagnostic_level["reason"] = "等力矩状态稳定；不代表真实球心，也不会写入位置模型"
        if geometry_error:
            center_state = blank_center_tension_calibration()
            center_state["reason"] = "新版出绳点/球端连接点几何生效后，旧中心数据已失效，请在四角校准后重测"
            calibration["center_tension_calibration"] = copy.deepcopy(center_state)
        center_diagnostics_version = f"{GEOMETRY_VERSION}-diagnostic-only"
        center_diagnostics_changed = center_state.get("geometry_diagnostics_version") != center_diagnostics_version
        if center_diagnostics_changed:
            center_state = copy.deepcopy(center_state)
            center_state["expected_xy_mm"] = [MECHANISM_CENTER_X_MM, MECHANISM_CENTER_Y_MM]
            center_base = strip_center_tension_datum(calibration)

            def refresh_center_geometry(level: object) -> None:
                if not isinstance(level, dict):
                    return
                positions = _finite_grid_vector(level.get("absolute_positions_deg"), len(MOTOR_IDS))
                solved = position_to_xyz(positions, center_base) if positions is not None else None
                if solved is None:
                    return
                level["solved_xy_mm"] = [round(float(solved[0]), 3), round(float(solved[1]), 3)]
                level["solved_z_mm"] = round(float(solved[2]), 3)
                level["z_fit_spread_mm"] = round(float(solved[3]), 3)
                level["xy_error_mm"] = round(
                    math.hypot(
                        float(solved[0]) - MECHANISM_CENTER_X_MM,
                        float(solved[1]) - MECHANISM_CENTER_Y_MM,
                    ),
                    3,
                )

            for level in center_state.get("levels", []):
                refresh_center_geometry(level)
            refresh_center_geometry(center_state.get("selected"))
            center_state["geometry_diagnostics_version"] = center_diagnostics_version
        if center_state.get("status") == "error" and has_center_tension_datum(calibration):
            calibration = strip_center_tension_datum(calibration)
            center_state["model_applied"] = False
            center_state["previous_model_preserved"] = False
            persist_calibration(calibration)
        # Older files do not carry the internal readiness flag.  Recompute it
        # from the current four-corner geometry and curve metadata; this does
        # not require or imply an external/camera pose measurement.
        previous_internal_verified = data.get("internal_model_verified")
        calibration = mark_internal_model_ready(calibration)
        internal_model_changed = previous_internal_verified != calibration.get("internal_model_verified")
        with STATE_LOCK:
            STATE["center_tension_calibration"] = copy.deepcopy(center_state)
            STATE["internal_feedback_calibration"] = copy.deepcopy(
                calibration.get("internal_feedback_calibration", blank_internal_feedback_calibration())
            )
        calibration["center_tension_calibration"] = copy.deepcopy(center_state)
        if (center_diagnostics_changed or center_datum_removed or internal_model_changed) and calibration.get("valid"):
            persist_calibration(calibration)
        if (calibration.get("valid") and len(calibration.get("slope", [])) == 4) or raw_reverse is not None:
            with STATE_LOCK:
                STATE["calibration"] = calibration
                STATE["message"] = f"已拒绝本地校准参数：{quality_error}" if quality_error else "已加载电脑本地校准参数"
    except (OSError, ValueError, TypeError):
        return


def read_serial_settings() -> dict:
    """Read the small serial settings file (baud and/or the chosen port)."""

    try:
        data = json.loads(SERIAL_SETTINGS_FILE.read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else {}
    except (OSError, ValueError, TypeError):
        return {}


def write_serial_settings(**updates: object) -> None:
    """Atomically merge settings so baud and port never overwrite each other."""

    data = read_serial_settings()
    for key, value in updates.items():
        if value in (None, ""):
            data.pop(key, None)
        else:
            data[key] = value
    temp_file = SERIAL_SETTINGS_FILE.with_suffix(".json.tmp")
    try:
        temp_file.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        temp_file.replace(SERIAL_SETTINGS_FILE)
    except OSError:
        try:
            temp_file.unlink(missing_ok=True)
        except OSError:
            pass


def load_saved_baud() -> int:
    """Return the last verified motor baud, falling back to the manual default."""

    try:
        baud = int(read_serial_settings().get("baud", direct.DEFAULT_BAUD))
    except (TypeError, ValueError):
        return direct.DEFAULT_BAUD
    return baud if baud in BAUD_TO_CODE else direct.DEFAULT_BAUD


def persist_saved_baud(baud: int) -> None:
    """Atomically remember a baud only after it has been verified on all IDs."""

    if baud not in BAUD_TO_CODE:
        return
    write_serial_settings(baud=baud)


def load_saved_port() -> str:
    """Return the serial port the operator last chose for the RS485 adapter."""

    return str(read_serial_settings().get("port") or "").strip()


def persist_saved_port(port: object) -> None:
    """Remember an operator-chosen port so multi-port PCs stay usable."""

    text = str(port or "").strip()
    if text:
        write_serial_settings(port=text)


# Initialise the server state from the last baud rate that was verified on
# all four IDs.  This must happen before the first browser /api/status poll;
# otherwise that early poll used the old 115200 default and overwrote the
# saved 921600 selection while boot preparation was still in progress.
STATE["baud"] = load_saved_baud()


def load_last_stability() -> None:
    """Restore only the last compact bus benchmark; the full samples stay in JSONL."""
    try:
        with PROCESS_LOG_FILE.open("rb") as handle:
            handle.seek(0, os.SEEK_END)
            size = handle.tell()
            handle.seek(max(0, size - 262144), os.SEEK_SET)
            lines = handle.read().decode("utf-8", errors="ignore").splitlines()
        for line in reversed(lines):
            record = json.loads(line)
            if record.get("event") != "long_stability_complete":
                continue
            restored = {key: value for key, value in record.items() if key not in {"event", "ts", "monotonic"}}
            with STATE_LOCK:
                STATE["last_stability"] = restored
            return
    except (OSError, ValueError, TypeError, UnicodeError):
        return


load_last_stability()


def json_bytes(value: object) -> bytes:
    return json.dumps(value, ensure_ascii=False, separators=(",", ":")).encode("utf-8")


def serial_port_label(port: object) -> dict:
    device = str(getattr(port, "device", ""))
    description = str(getattr(port, "description", "") or "")
    hwid = str(getattr(port, "hwid", "") or "")
    manufacturer = str(getattr(port, "manufacturer", "") or "")
    # A built-in "通信端口 (COM1)" is not the USB-RS485 adapter.  Flag the
    # USB/bridge chips so the selector can preselect the likely adapter
    # instead of blindly taking the first port.
    probe = f"{description} {hwid} {manufacturer}".upper()
    likely_adapter = any(
        token in probe
        for token in ("USB", "CH34", "CH35", "FTDI", "CP210", "SILICON LABS", "PROLIFIC", "PL2303")
    )
    return {
        "device": device,
        "label": f"{device} - {description}" if description else device,
        "description": description,
        "hwid": hwid,
        "likely_adapter": likely_adapter,
    }


def ports_snapshot() -> dict:
    """Serial ports plus the port this PC should preselect."""

    ports = [serial_port_label(port) for port in direct.list_serial_ports()]
    devices = [item["device"] for item in ports]
    saved = load_saved_port()
    recommended = ""
    if saved and saved in devices:
        recommended = saved
    else:
        adapters = [item["device"] for item in ports if item["likely_adapter"]]
        if len(adapters) == 1:
            recommended = adapters[0]
        elif len(ports) == 1:
            recommended = ports[0]["device"]
        elif len(devices) > 1:
            # Several ports and no USB bridge: never silently take COM1.
            recommended = devices[0]
    return {
        "ok": True,
        "ports": ports,
        "recommended": recommended,
        "saved": saved,
        "adapter_count": sum(1 for item in ports if item["likely_adapter"]),
    }


def telemetry_dict(telemetry: direct.Telemetry) -> dict:
    return {
        "id": telemetry.address,
        "voltage": telemetry.voltage,
        "bus_current": telemetry.bus_current,
        "phase_current": telemetry.phase_current,
        "rpm": telemetry.rpm,
        "position": telemetry.position,
        "temperature": telemetry.temperature,
        "flags": telemetry.flags,
        "flags_text": direct.decode_flags(telemetry.flags) if telemetry.flags is not None else "未响应",
        "online": telemetry.flags is not None,
    }


def state_snapshot() -> dict:
    with STATE_LOCK:
        return copy.deepcopy(STATE)


def web_state_snapshot() -> dict:
    """Return the live UI state without copying/encoding offline sample tables.

    The browser only needs the fitted coefficients and calibration status.  The
    63-node grid and raw corner curves remain in ``STATE`` and on disk, but
    serialising them in two browser tabs every 25 ms was stealing several
    milliseconds from the 100 Hz command thread.
    """

    with STATE_LOCK:
        # Exclude large immutable/offline arrays *before* deepcopy so the UI
        # request neither holds STATE_LOCK nor the GIL while cloning them.
        source = dict(STATE)
        source_calibration = STATE.get("calibration")
        calibration = (
            dict(source_calibration) if isinstance(source_calibration, dict) else None
        )
        if isinstance(calibration, dict):
            source["calibration"] = calibration
        grid = calibration.get("grid_compensation") if isinstance(calibration, dict) else None
        if isinstance(grid, dict):
            grid = dict(grid)
            calibration["grid_compensation"] = grid
            samples = grid.pop("samples", None)
            if isinstance(samples, list):
                grid["sample_count"] = len(samples)
        if isinstance(calibration, dict):
            # Storage availability is separate from this powered session's
            # motion readiness. Reuse the small fitted curves, not raw logs.
            model = dict(calibration)
            for key in ("groups", "samples", "pose_reference_samples", "grid_compensation"):
                model.pop(key, None)
            source["saved_model_available"], source["saved_model_reason"] = (
                persisted_calibration_structure_ready(model)
            )
            for key in (
                "groups",
                "samples",
                "distance_samples_mm",
                "position_samples_deg",
                "pose_reference_samples",
            ):
                calibration.pop(key, None)
        return copy.deepcopy(source)


def set_state(**updates: object) -> None:
    with STATE_LOCK:
        if updates.get("auto") == "error" and updates.get("message"):
            previous = STATE.get("last_failure")
            if STATE.get("auto") != "error" or not isinstance(previous, dict):
                recording = STATE.get("manual_test_recording") or {}
                STATE["last_failure"] = {
                    "id": str(time.time_ns()),
                    "run_id": recording.get("run_id"),
                    "message": str(updates["message"]),
                    "worker": str(STATE.get("auto", "unknown")),
                    "occurred_at": time.time(),
                    "acknowledged": False,
                }
            else:
                # Safety cleanup may add a confirmed-disable outcome. Keep
                # the same failure identity, even after preparation returns idle.
                STATE["last_failure"] = {**previous, "message": str(updates["message"])}
        STATE.update(updates)


def _manual_json_default(value: object) -> object:
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, (bytes, bytearray)):
        return {"hex": bytes(value).hex(), "bytes": len(value)}
    return str(value)


def manual_json_snapshot(value: object) -> object:
    """Freeze a test payload before the background writer sees mutations."""

    return json.loads(
        json.dumps(value, ensure_ascii=False, separators=(",", ":"), default=_manual_json_default)
    )


def file_sha256(path: Path) -> str | None:
    try:
        digest = hashlib.sha256()
        with path.open("rb") as handle:
            while True:
                chunk = handle.read(1024 * 1024)
                if not chunk:
                    break
                digest.update(chunk)
        return digest.hexdigest()
    except OSError:
        return None


def _manual_svg_segments(value: object) -> list[list[tuple[float, float]]]:
    segments: list[list[tuple[float, float]]] = []
    if not isinstance(value, (list, tuple)):
        return segments
    raw_segments = value if value and isinstance(value[0], (list, tuple)) and value[0] and isinstance(value[0][0], (list, tuple)) else [value]
    for raw_segment in raw_segments:
        if not isinstance(raw_segment, (list, tuple)):
            continue
        segment: list[tuple[float, float]] = []
        for point in raw_segment:
            if not isinstance(point, (list, tuple)) or len(point) < 2:
                continue
            try:
                x = float(point[0])
                y = float(point[1])
            except (TypeError, ValueError):
                continue
            if math.isfinite(x) and math.isfinite(y):
                segment.append((x, y))
        if segment:
            segments.append(segment)
    return segments


def manual_test_overlay_svg(final_state: dict, manifest: dict) -> str:
    """Create a deterministic, high-resolution visual verdict for one run."""

    calibration = final_state.get("calibration") if isinstance(final_state, dict) else {}
    calibration = calibration if isinstance(calibration, dict) else {}
    width_mm = float(calibration.get("workspace_width", WORKSPACE_WIDTH_MM) or WORKSPACE_WIDTH_MM)
    height_mm = float(calibration.get("workspace_height", WORKSPACE_HEIGHT_MM) or WORKSPACE_HEIGHT_MM)
    canvas_width = 720.0
    plot_width = 620.0
    plot_height = plot_width * height_mm / max(1e-6, width_mm)
    padding_x = 50.0
    padding_y = 48.0
    footer_height = 118.0
    canvas_height = plot_height + padding_y * 2.0 + footer_height

    arguments = manifest.get("arguments", []) if isinstance(manifest, dict) else []
    spec = next(
        (
            item
            for item in arguments
            if isinstance(item, dict)
            and ("operator_input_absolute_segments" in item or "motion_segments" in item)
        ),
        {},
    )
    original = _manual_svg_segments(spec.get("operator_input_absolute_segments", []))
    target = _manual_svg_segments(final_state.get("trajectory_target_path_segments", []))
    actual = _manual_svg_segments(final_state.get("trajectory_actual_path_segments", []))
    raw_feedback = _manual_svg_segments(final_state.get("trajectory_actual_feedback_path_segments", []))

    def path_markup(segments: list[list[tuple[float, float]]], css_class: str) -> str:
        paths: list[str] = []
        for segment in segments:
            commands = []
            for index, (x_mm, y_mm) in enumerate(segment):
                x = padding_x + x_mm / max(1e-6, width_mm) * plot_width
                y = padding_y + (1.0 - y_mm / max(1e-6, height_mm)) * plot_height
                commands.append(("M" if index == 0 else "L") + f"{x:.3f},{y:.3f}")
            if commands:
                paths.append(f'<path class="{css_class}" d="{" ".join(commands)}"/>')
        return "".join(paths)

    diagnostic = final_state.get("trajectory_diagnostic", {})
    diagnostic = diagnostic if isinstance(diagnostic, dict) else {}
    controller = str(
        diagnostic.get("controller")
        or spec.get("controller_mode")
        or manifest.get("controller")
        or ""
    )
    if not controller:
        controller = str(final_state.get("trajectory_controller") or "见 manifest")
    hz = final_state.get("trajectory_hz_actual")
    rms = diagnostic.get("rms_error_mm")
    maximum = diagnostic.get("max_error_mm")
    coverage = diagnostic.get("coverage")
    summary_parts = [f"控制器: {controller}"]
    if isinstance(hz, (int, float)):
        summary_parts.append(f"实测控制频率: {float(hz):.1f} Hz")
    if isinstance(rms, (int, float)):
        summary_parts.append(f"RMS: {float(rms):.2f} mm")
    if isinstance(maximum, (int, float)):
        summary_parts.append(f"最大: {float(maximum):.2f} mm")
    if isinstance(coverage, (int, float)):
        summary_parts.append(f"±4 mm覆盖: {float(coverage) * 100.0:.1f}%")
    summary = "　".join(summary_parts)
    run_id = str(manifest.get("run_id", "unknown"))
    return f'''<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="{canvas_width:.0f}" height="{canvas_height:.0f}" viewBox="0 0 {canvas_width:.0f} {canvas_height:.0f}">
<rect width="100%" height="100%" fill="#f7f9fc"/>
<rect x="{padding_x}" y="{padding_y}" width="{plot_width}" height="{plot_height:.3f}" rx="18" fill="#fff" stroke="#cdd7e6" stroke-width="2"/>
<path d="M{padding_x + plot_width / 2:.3f},{padding_y}V{padding_y + plot_height:.3f} M{padding_x},{padding_y + plot_height / 2:.3f}H{padding_x + plot_width}" stroke="#dbe4f0" stroke-width="1"/>
<style>.original{{fill:none;stroke:#1769e8;stroke-width:3.2;stroke-linejoin:round;stroke-linecap:round}}.target{{fill:none;stroke:#d18b28;stroke-width:2.4;stroke-dasharray:8 7;stroke-linejoin:round;stroke-linecap:round}}.raw{{fill:none;stroke:#7c3aed;stroke-width:1.5;opacity:.38;stroke-linejoin:round;stroke-linecap:round}}.actual{{fill:none;stroke:#d946ef;stroke-width:3.0;stroke-linejoin:round;stroke-linecap:round}}</style>
{path_markup(original, "original")}{path_markup(target, "target")}{path_markup(raw_feedback, "raw")}{path_markup(actual, "actual")}
<g font-family="Segoe UI,Microsoft YaHei,sans-serif" fill="#26354d"><text x="50" y="{padding_y + plot_height + 38:.3f}" font-size="18" font-weight="700">最终轨迹直观对比</text><text x="50" y="{padding_y + plot_height + 66:.3f}" font-size="14">蓝=原始手绘　琥珀虚线=目标　紫细线=原始反馈　洋红=最终反馈轨迹</text><text x="50" y="{padding_y + plot_height + 91:.3f}" font-size="13">{summary}</text><text x="50" y="{padding_y + plot_height + 112:.3f}" font-size="11" fill="#718096">run: {run_id}</text></g>
</svg>'''


def _manual_writer_error(message: str) -> None:
    with STATE_LOCK:
        status = dict(STATE.get("manual_test_recording", {}))
        status["writer_error"] = message
        STATE["manual_test_recording"] = status


def _manual_test_writer() -> None:
    runs: dict[str, dict] = {}
    while True:
        try:
            item = MANUAL_TEST_QUEUE.get(timeout=0.10)
        except queue.Empty:
            for run in runs.values():
                try:
                    run["handle"].flush()
                except OSError:
                    pass
            continue
        try:
            kind = item.get("kind")
            run_id = str(item.get("run_id"))
            if kind == "start":
                directory = Path(str(item["directory"]))
                directory.mkdir(parents=True, exist_ok=False)
                manifest = item["manifest"]
                manifest_path = directory / "manifest.json"
                manifest_path.write_text(
                    json.dumps(manifest, ensure_ascii=False, indent=2, default=_manual_json_default) + "\n",
                    encoding="utf-8",
                )
                source_dir = directory / "source_snapshot"
                source_dir.mkdir(exist_ok=False)
                for raw_path in item.get("snapshot_paths", []):
                    source_path = Path(str(raw_path))
                    if source_path.is_file():
                        shutil.copy2(source_path, source_dir / source_path.name)
                runs[run_id] = {
                    "directory": directory,
                    "manifest": manifest,
                    "handle": (directory / "events.jsonl").open("xb"),
                    "hash": hashlib.sha256(),
                    "bytes": 0,
                    "records": 0,
                }
            elif kind == "event":
                run = runs.get(run_id)
                if run is None:
                    continue
                payload = (
                    json.dumps(item["record"], ensure_ascii=False, separators=(",", ":"), default=_manual_json_default)
                    + "\n"
                ).encode("utf-8")
                run["handle"].write(payload)
                run["hash"].update(payload)
                run["bytes"] += len(payload)
                run["records"] += 1
            elif kind == "end":
                run = runs.pop(run_id, None)
                if run is None:
                    continue
                handle = run["handle"]
                handle.flush()
                os.fsync(handle.fileno())
                handle.close()
                directory = run["directory"]
                final_state = item.get("final_state", {})
                final_state_path = directory / "final_state.json"
                final_state_path.write_text(
                    json.dumps(final_state, ensure_ascii=False, indent=2, default=_manual_json_default) + "\n",
                    encoding="utf-8",
                )
                svg_path = directory / "visual-comparison.svg"
                svg_path.write_text(
                    manual_test_overlay_svg(final_state, run["manifest"]),
                    encoding="utf-8",
                )
                integrity = {
                    "schema": "y42-manual-test-integrity-v1",
                    "run_id": run_id,
                    "completed_unix_ns": time.time_ns(),
                    "events": {
                        "file": "events.jsonl",
                        "records": run["records"],
                        "bytes": run["bytes"],
                        "sha256": run["hash"].hexdigest(),
                    },
                    "manifest_sha256": file_sha256(directory / "manifest.json"),
                    "final_state_sha256": file_sha256(final_state_path),
                    "visual_comparison_sha256": file_sha256(svg_path),
                    "legacy_process_log_end_bytes": PROCESS_LOG_FILE.stat().st_size if PROCESS_LOG_FILE.exists() else None,
                }
                (directory / "integrity.json").write_text(
                    json.dumps(integrity, ensure_ascii=False, indent=2) + "\n",
                    encoding="utf-8",
                )
                with STATE_LOCK:
                    last_run = STATE.get("manual_test_last_run")
                    if isinstance(last_run, dict) and last_run.get("run_id") == run_id:
                        completed_run = dict(last_run)
                        completed_run["writer_pending"] = False
                        completed_run["events_sha256"] = integrity["events"]["sha256"]
                        completed_run["records"] = integrity["events"]["records"]
                        STATE["manual_test_last_run"] = completed_run
        except Exception as exc:
            _manual_writer_error(f"{type(exc).__name__}: {exc}")
            failed = runs.pop(str(item.get("run_id")), None)
            if failed is not None:
                try:
                    failed["handle"].close()
                except OSError:
                    pass
        finally:
            MANUAL_TEST_QUEUE.task_done()


def ensure_manual_test_writer() -> None:
    with MANUAL_TEST_LOCK:
        if MANUAL_TEST_WRITER_STARTED.is_set():
            return
        MANUAL_TEST_WRITER_STARTED.set()
        threading.Thread(target=_manual_test_writer, name="y42-test-recorder", daemon=True).start()


def begin_manual_test_run(worker: object, arguments: tuple) -> dict:
    """Start one append-only, self-contained record for a user-triggered run."""

    global MANUAL_TEST_ACTIVE
    ensure_manual_test_writer()
    worker_name = str(getattr(worker, "__name__", worker))
    started_unix_ns = time.time_ns()
    started_monotonic_ns = time.perf_counter_ns()
    suffix = hashlib.blake2s(
        f"{worker_name}:{started_unix_ns}:{random.random()}".encode("utf-8"), digest_size=4
    ).hexdigest()
    safe_worker = "".join(character if character.isalnum() else "_" for character in worker_name).strip("_") or "run"
    run_id = time.strftime("%Y%m%d_%H%M%S", time.localtime(started_unix_ns / 1e9)) + f"_{started_unix_ns // 1_000_000 % 1000:03d}_{safe_worker}_{suffix}"
    directory = MANUAL_TEST_RUNS_ROOT / run_id
    serial_settings = None
    try:
        serial_settings = json.loads(SERIAL_SETTINGS_FILE.read_text(encoding="utf-8"))
    except (OSError, ValueError, TypeError, UnicodeError):
        serial_settings = None
    source_paths = [Path(__file__), Path(direct.__file__), CALIBRATION_FILE, SERIAL_SETTINGS_FILE]
    if worker_name == "observation_sampling_worker":
        source_paths.append(Path(__file__).with_name("y42_observation_sampler.py"))
    if worker_name == "position_probe_worker":
        source_paths.extend(Path(__file__).with_name(name) for name in
                            ("y42_position_probe.py", "y42_position_probe_io.py"))
    if worker_name in {"position_microprobe_worker", "torque_admission_worker"}:
        source_paths.extend(Path(__file__).with_name(name) for name in
                            ("y42_position_probe.py", "y42_position_probe_io.py",
                             "y42_position_microprobe_io.py"))
    if worker_name == "corner_stop_probe_worker":
        source_paths.extend(Path(__file__).with_name(name) for name in
                            ("y42_corner_stop_probe.py", "y42_position_microprobe_io.py",
                             "y42_position_probe.py", "y42_adapter_versions.py"))
    manifest = {
        "schema": "y42-manual-test-run-v1",
        "run_id": run_id,
        "started_unix_ns": started_unix_ns,
        "started_monotonic_ns": started_monotonic_ns,
        "worker": worker_name,
        "arguments": manual_json_snapshot(arguments),
        "state_before": manual_json_snapshot(state_snapshot()),
        "calibration_before": manual_json_snapshot(calibration_data()),
        "serial_settings": manual_json_snapshot(serial_settings),
        "legacy_process_log": {
            "file": str(PROCESS_LOG_FILE),
            "start_bytes": PROCESS_LOG_FILE.stat().st_size if PROCESS_LOG_FILE.exists() else 0,
        },
        "software": {
            "working_directory": str(Path.cwd()),
            "files": {
                str(path): {"bytes": path.stat().st_size, "sha256": file_sha256(path)}
                for path in source_paths
                if path.is_file()
            },
        },
        "recording_contract": {
            "one_directory_per_run": True,
            "overwrite_existing_run": False,
            "raw_synchronous_serial": True,
            "raw_high_rate_tx": True,
            "raw_valid_timed_feedback": True,
            "semantic_events": True,
            "final_visual_overlay": True,
        },
    }
    context = {
        "run_id": run_id,
        "directory": str(directory),
        "worker": worker_name,
        "sequence": 0,
        "started_unix_ns": started_unix_ns,
    }
    with MANUAL_TEST_LOCK:
        if MANUAL_TEST_ACTIVE is not None:
            raise RuntimeError("上一条实机测试记录尚未关闭")
        MANUAL_TEST_QUEUE.put_nowait(
            {
                "kind": "start",
                "run_id": run_id,
                "directory": str(directory),
                "manifest": manifest,
                "snapshot_paths": [str(path) for path in source_paths],
            }
        )
        MANUAL_TEST_ACTIVE = context
    set_state(
        manual_test_recording={
            "active": True,
            "run_id": run_id,
            "directory": str(directory),
            "records_queued": 0,
            "writer_error": None,
        }
    )
    manual_test_emit("run_start", worker=worker_name, arguments=arguments)
    return context


def manual_test_emit(event: str, **fields: object) -> None:
    global MANUAL_TEST_ACTIVE
    # The high-rate motion path calls this hook once per 0xAA frame.  Most
    # production runs do not record a manual-test artifact; avoid serializing
    # and deep-copying the payload before discovering that the recorder is
    # inactive.  That unnecessary JSON work was visible as long-path deadline
    # misses even though the wire itself was already at 921600 baud.
    with MANUAL_TEST_LOCK:
        if MANUAL_TEST_ACTIVE is None:
            return
    frozen_fields = manual_json_snapshot(fields)
    unix_ns = time.time_ns()
    monotonic_ns = time.perf_counter_ns()
    with MANUAL_TEST_LOCK:
        context = MANUAL_TEST_ACTIVE
        if context is None:
            return
        context["sequence"] = int(context.get("sequence", 0)) + 1
        sequence = int(context["sequence"])
        run_id = str(context["run_id"])
        record = {
            "sequence": sequence,
            "unix_ns": unix_ns,
            "monotonic_ns": monotonic_ns,
            "event": str(event),
        }
        record.update(frozen_fields)
        MANUAL_TEST_QUEUE.put_nowait({"kind": "event", "run_id": run_id, "record": record})
    if sequence == 1 or sequence % 100 == 0:
        with STATE_LOCK:
            status = dict(STATE.get("manual_test_recording", {}))
            if status.get("run_id") == run_id:
                status["records_queued"] = sequence
                STATE["manual_test_recording"] = status


def end_manual_test_run(context: dict | None, result: object = None, error: BaseException | None = None) -> None:
    global MANUAL_TEST_ACTIVE
    if context is None:
        return
    final_state = manual_json_snapshot(state_snapshot())
    manual_test_emit(
        "run_end",
        result=result,
        error=(
            {"type": type(error).__name__, "message": str(error)}
            if error is not None
            else None
        ),
        final_state_summary={
            "auto": final_state.get("auto"),
            "message": final_state.get("message"),
            "trajectory_diagnostic": final_state.get("trajectory_diagnostic"),
            "tracking_samples": final_state.get("tracking_samples"),
        },
    )
    with MANUAL_TEST_LOCK:
        if MANUAL_TEST_ACTIVE is not None and MANUAL_TEST_ACTIVE.get("run_id") == context.get("run_id"):
            records = int(MANUAL_TEST_ACTIVE.get("sequence", 0))
            MANUAL_TEST_ACTIVE = None
        else:
            records = int(context.get("sequence", 0))
    MANUAL_TEST_QUEUE.put_nowait(
        {
            "kind": "end",
            "run_id": str(context["run_id"]),
            "final_state": final_state,
        }
    )
    last_run = {
        "run_id": str(context["run_id"]),
        "directory": str(context["directory"]),
        "worker": str(context["worker"]),
        "records": records,
        "ended_unix_ns": time.time_ns(),
        "writer_pending": True,
        "error": str(error) if error is not None else None,
    }
    set_state(
        manual_test_recording={
            "active": False,
            "run_id": None,
            "directory": None,
            "records_queued": 0,
            "writer_error": None,
        },
        manual_test_last_run=last_run,
    )


def manual_test_serial_transaction(record: dict) -> None:
    manual_test_emit("serial_transaction", **record)


if hasattr(direct, "set_traffic_callback"):
    direct.set_traffic_callback(manual_test_serial_transaction)


def clear_trajectory_cache() -> dict:
    """Clear only the UI/diagnostic trajectory cache; never sends a motor frame."""

    global TRAJECTORY_SPEC
    if active_auto():
        raise RuntimeError("轨迹正在运行，请先急停后再清空轨迹")
    TRAJECTORY_SPEC = None
    set_state(
        auto="idle",
        point=0,
        points=0,
        repeat=False,
        trajectory_hz_actual=0.0,
        trajectory_frames=0,
        trajectory_controller=None,
        trajectory_target_path=[],
        trajectory_target_path_segments=[],
        trajectory_actual_path=[],
        trajectory_actual_feedback_path=[],
        trajectory_actual_path_segments=[],
        trajectory_actual_feedback_path_segments=[],
        trajectory_diagnostic={
            "status": "待反馈",
            "recommendation": "绘制后等待四电机原始位置反馈",
        },
        message="轨迹缓存已清空，可以重新绘制",
    )
    return {"ok": True, "action": "clear-trace", "message": "已清空手绘输入和反馈轨迹"}


def update_telemetry(telemetries: list[direct.Telemetry]) -> None:
    with STATE_LOCK:
        previous = STATE.get("telemetry", {})
        merged: dict[str, dict] = {}
        # A lost field must not make the floating dashboard blink to "--".
        # Keep the last known numeric sample, while leaving flags/online false
        # when the current status frame itself was not received.
        value_fields = ("voltage", "bus_current", "phase_current", "rpm", "position", "temperature")
        for telemetry in telemetries:
            current = telemetry_dict(telemetry)
            old = previous.get(str(telemetry.address), {}) if isinstance(previous, dict) else {}
            for field in value_fields:
                if current.get(field) is None and old.get(field) is not None:
                    current[field] = old[field]
            merged[str(telemetry.address)] = current
        STATE["telemetry"] = merged


def active_auto() -> bool:
    return AUTO_THREAD is not None and AUTO_THREAD.is_alive()


def valid_reply(reply: bytes, address: int, command: int, minimum: int = 4) -> bool:
    return direct.valid_reply(reply, address, command, minimum)


def command_result(address: int, command: int, tx: bytes, rx: bytes) -> dict:
    accepted = direct.command_accepted(rx, address, command)
    return {
        "id": address,
        "ok": accepted or bool(rx),
        "accepted": accepted,
        "tx": direct.hex_bytes(tx),
        "rx": direct.hex_bytes(rx),
    }


def firmware_status_result(address: int, tx: bytes, rx: bytes) -> dict:
    valid = valid_reply(rx, address, 0x1A, 4)
    result = {
        "id": address,
        "label": MOTOR_LABELS[address - 1],
        "ok": valid,
        "tx": direct.hex_bytes(tx),
        "rx": direct.hex_bytes(rx),
        "firmware": None,
        "firmware_code": None,
    }
    if valid:
        firmware_code = (rx[2] >> 1) & 0x01
        result["firmware_code"] = firmware_code
        result["firmware"] = "Emm" if firmware_code else "X"
        result["flags"] = rx[2]
    return result


def read_firmware_status(connection: object, address: int) -> dict:
    config_tx = direct.frame(address, 0x42, 0x6C, direct.FRAME_END)
    # A just-restarted Y42 can leave the half-duplex line quiet for one
    # request while its configuration table is becoming available.  Do not
    # turn one empty reply into a false non-X result; retry the read before
    # falling back to the legacy 0x1A query.
    config_rx = b""
    for attempt in range(3):
        config_rx = direct.transact(connection, config_tx, first_byte_timeout=0.3)
        if valid_reply(config_rx, address, 0x42, 5):
            break
        if attempt < 2:
            time.sleep(0.04)
    result = {
        "id": address,
        "label": MOTOR_LABELS[address - 1],
        "ok": valid_reply(config_rx, address, 0x42, 5),
        "tx": direct.hex_bytes(config_tx),
        "rx": direct.hex_bytes(config_rx),
        "firmware": None,
        "firmware_code": None,
        "detected_by": "0x42 length",
    }
    if result["ok"]:
        if config_rx[2] == 0x25:
            result["firmware_code"] = 0
            result["firmware"] = "X"
            result["detected_by"] = "0x42 length"
            return result
        elif config_rx[2] == 0x21:
            result["firmware_code"] = 1
            result["firmware"] = "Emm"
            result["detected_by"] = "0x42 length"
            return result

    # 0x1A's FwType bit is retained only as a compatibility fallback.  Some
    # Y42 V2.x units report that bit as X even while the active firmware is
    # still Emm, which would make C5/F5 torque commands fail with EE.
    option_tx = direct.frame(address, 0x1A, direct.FRAME_END)
    option_rx = direct.transact(connection, option_tx, first_byte_timeout=0.3)
    fallback = firmware_status_result(address, option_tx, option_rx)
    fallback["fallback_0x42_rx"] = direct.hex_bytes(config_rx)
    if fallback["ok"]:
        fallback["detected_by"] = "0x1A fallback (0x42 unavailable)"
        fallback["message"] = "0x42 配置块不可用，以下固件类型仅作兼容性推断"
        return fallback
    result["message"] = f"无法可靠读取固件类型；0x42 RX={direct.hex_bytes(config_rx)}，0x1A RX={direct.hex_bytes(option_rx)}"
    return result


def firmware_switch_frame(address: int, firmware_code: int = 0, store: bool = True) -> bytes:
    if firmware_code not in (0, 1, 2):
        raise ValueError("固件类型必须是 0=X、1=Emm、2=Emm 狂暴模式")
    return direct.frame(address, 0xD5, 0x69, 0x01 if store else 0x00, firmware_code, direct.FRAME_END)


def firmware_restart_frame(address: int) -> bytes:
    return direct.frame(address, 0x08, 0x97, direct.FRAME_END)


def key_lock_frame(address: int, locked: bool = True, store: bool = True) -> bytes:
    return direct.frame(
        address,
        0xD0,
        0xB3,
        0x01 if store else 0x00,
        0x01 if locked else 0x00,
        direct.FRAME_END,
    )


def key_lock_status(connection: object, address: int) -> dict:
    tx = direct.frame(address, 0x1A, direct.FRAME_END)
    rx = b""
    valid = False
    # The D0 write ACK can arrive before the controller has finished
    # persisting the setting.  A single immediate 0x1A read is therefore
    # occasionally empty on an otherwise healthy RS485 link.
    for attempt in range(4):
        if attempt:
            time.sleep(0.10)
        rx = direct.transact(connection, tx, first_byte_timeout=0.40)
        valid = valid_reply(rx, address, 0x1A, 4)
        if valid:
            break
    return {
        "id": address,
        "ok": valid,
        "tx": direct.hex_bytes(tx),
        "rx": direct.hex_bytes(rx),
        # Y42 V2 returns a reserved/status prefix before the option byte;
        # use the byte immediately before 0x6B so both 4- and 5-byte replies
        # are decoded consistently.
        "locked": bool(rx[-2] & 0x20) if valid else None,
    }


def lock_keys_all(connection: object) -> tuple[bool, list[dict]]:
    results = []
    for address in MOTOR_IDS:
        tx = key_lock_frame(address, locked=True, store=True)
        rx = direct.transact(connection, tx, first_byte_timeout=0.3)
        accepted = direct.command_accepted(rx, address, 0xD0)
        verified = key_lock_status(connection, address)
        results.append({
            "id": address,
            "tx": direct.hex_bytes(tx),
            "rx": direct.hex_bytes(rx),
            "accepted": accepted,
            "verify": verified,
        })
    return all(item["accepted"] and item["verify"].get("locked") is True for item in results), results


def switch_all_to_x(connection: object) -> dict:
    stop_results = stop_all(connection)
    if not all(item["accepted"] for item in stop_results):
        return {"ok": False, "message": "切换 X 固件前四台急停未全部收到 ACK", "stop_results": stop_results}
    results = []
    for address in MOTOR_IDS:
        tx = firmware_switch_frame(address, 0, store=True)
        rx = direct.transact(connection, tx, first_byte_timeout=0.3)
        results.append(command_result(address, 0xD5, tx, rx))
    restart_results = []
    for address in MOTOR_IDS:
        tx = firmware_restart_frame(address)
        rx = direct.transact(connection, tx, first_byte_timeout=0.5)
        restart_results.append(command_result(address, 0x08, tx, rx))
        time.sleep(0.25)
    time.sleep(0.5)
    status = [read_firmware_status(connection, address) for address in MOTOR_IDS]
    accepted = all(item["accepted"] for item in results)
    restarted = all(item["accepted"] for item in restart_results)
    verified = all(item.get("ok") and item.get("firmware_code") == 0 for item in status)
    return {
        "ok": accepted and restarted and verified,
        "accepted": accepted,
        "restarted": restarted,
        "verified": verified,
        "results": results,
        "restart_results": restart_results,
        "status": status,
        "message": "已切换并复核四台 X 固件" if verified else "X 固件切换后复核未全部通过",
    }


def command_frame(address: int, action: str, data: dict) -> bytes:
    if action == "enable":
        return direct.frame(address, 0xF3, 0xAB, 0x01, 0x00, direct.FRAME_END)
    if action == "disable":
        return direct.frame(address, 0xF3, 0xAB, 0x00, 0x00, direct.FRAME_END)
    if action == "stop":
        return direct.frame(address, 0xFE, 0x98, 0x00, direct.FRAME_END)
    if action == "clear":
        return direct.frame(address, 0x0A, 0x6D, direct.FRAME_END)
    if action == "release":
        return direct.frame(address, 0x0E, 0x52, direct.FRAME_END)
    if action == "abort-home":
        return direct.frame(address, 0x9C, 0x48, direct.FRAME_END)
    if action == "set-home":
        return direct.frame(address, 0x93, 0x88, 0x01, direct.FRAME_END)
    if action == "home":
        mode = int(data.get("mode", 0))
        if not 0 <= mode <= 5:
            raise ValueError("回零模式必须是 0..5")
        return direct.frame(address, 0x9A, mode, 0x00, direct.FRAME_END)
    if action == "speed":
        direction = int(data.get("direction", 0))
        rpm = float(data.get("rpm", 0))
        acceleration = int(data.get("acceleration", 100))
        if direction not in (0, 1) or not 0 <= rpm <= 3000 or not 0 <= acceleration <= 65535:
            raise ValueError("速度参数超出范围：方向 0/1，RPM 0..3000，加速度 0..65535")
        return direct.speed_frame(address, direction, rpm, acceleration)
    if action == "torque":
        direction = int(data.get("direction", 0))
        current = int(data.get("current", 100))
        slope = int(data.get("slope", 2000))
        max_rpm = float(data.get("max_rpm", 10))
        if direction not in (0, 1) or not 0 <= current <= OPERATING_CURRENT_MAX_MA:
            raise ValueError(f"力矩电流必须在 0..{OPERATING_CURRENT_MAX_MA}mA")
        return direct.torque_frame(address, direction, current, slope, max_rpm)
    if action == "position":
        degrees = float(data.get("degrees", 0))
        if degrees < 0 or degrees > 429496729.5:
            raise ValueError("角度必须在 0..429496729.5 度")
        return direct.position_frame(
            address,
            int(data.get("direction", 0)),
            float(data.get("rpm", 5)),
            int(data.get("acceleration", 100)),
            degrees,
            int(data.get("mode", 2)),
        )
    raise ValueError(f"未知电机操作: {action}")


def enable_address(connection: object, address: int) -> tuple[bool, bytes, bytes]:
    status = direct.status_query(connection, address)
    if valid_reply(status, address, 0x3A, 4) and (status[2] & 0x01):
        return True, direct.frame(address, 0x3A, direct.FRAME_END), status
    tx = direct.frame(address, 0xF3, 0xAB, 0x01, 0x00, direct.FRAME_END)
    reply = direct.transact(connection, tx, first_byte_timeout=0.3)
    return direct.command_accepted(reply, address, 0xF3), tx, reply


def torque_command(
    connection: object,
    address: int,
    direction: int,
    current: int,
    *,
    slope: int = 2000,
    max_rpm: float = 1000.0,
) -> tuple[bool, bytes, bytes]:
    """Send an X-firmware torque command with a tolerant ACK/retry path."""

    tx = direct.torque_frame(address, direction, current, int(slope), float(max_rpm))
    reply = b""
    for attempt in range(3):
        reply = direct.transact(connection, tx, first_byte_timeout=0.3)
        if direct.command_accepted(reply, address, 0xC5):
            return True, tx, reply
        if attempt < 2:
            time.sleep(0.025)
    return False, tx, reply


def smooth_torque_vector_ramp(
    connection: object,
    start_currents_ma: list[int] | tuple[int, ...],
    target_currents_ma: list[int] | tuple[int, ...],
    *,
    max_rpm: float,
    label: str,
    step_ma: int = CALIBRATION_TORQUE_RAMP_STEP_MA,
    dwell_seconds: float = CALIBRATION_TORQUE_RAMP_DWELL_SECONDS,
    verify_safety: bool = True,
    start_max_rpm: float | None = None,
    max_slew_ma_per_s: float = CALIBRATION_TORQUE_RAMP_MAX_SLEW_MA_PER_S,
    driver_slope_ma_per_s: int = CALIBRATION_TORQUE_DRIVER_SLOPE_MA_PER_S,
) -> list[int]:
    """Cross-fade one four-motor torque vector on a gap-free fixed clock.

    Intermediate levels use one aggregate 0xAA packet.  This removes both the
    tens-of-milliseconds skew of four sequential C5 writes and the half-second
    telemetry pauses that used to occur *inside* the force ramp.  A complete
    telemetry safety read is performed after the final vector unless the caller
    is immediately chaining a second bounded stage.
    """

    if len(start_currents_ma) != len(MOTOR_IDS) or len(target_currents_ma) != len(MOTOR_IDS):
        raise ValueError("四电机张力渐变必须包含四个电流")
    start = [max(0, min(OPERATING_CURRENT_MAX_MA, int(value))) for value in start_currents_ma]
    target = [max(0, min(OPERATING_CURRENT_MAX_MA, int(value))) for value in target_currents_ma]
    plan, plan_meta = calibration_torque_ramp_plan(
        start,
        target,
        step_ma=step_ma,
        dwell_seconds=dwell_seconds,
        max_slew_ma_per_s=max_slew_ma_per_s,
    )
    rpm_start = float(max_rpm if start_max_rpm is None else start_max_rpm)
    if not math.isfinite(rpm_start) or not math.isfinite(float(max_rpm)) or min(rpm_start, float(max_rpm)) <= 0.0:
        raise ValueError("柔性校准的首尾转速上限必须是正有限数值")
    interval = 1.0 / CALIBRATION_TORQUE_RAMP_HZ
    started = time.perf_counter()
    write_stamps: list[float] = []
    timer_resolution = set_high_resolution_timer(True)
    try:
        for frame_index, values in enumerate(plan):
            if STOP_EVENT.is_set():
                raise RuntimeError("用户停止校准")
            if frame_index:
                wait_tracking_deadline(started + frame_index * interval)
            if STOP_EVENT.is_set():
                raise RuntimeError("用户停止校准")
            progress = frame_index / max(1, len(plan) - 1)
            phase = progress ** 3 * (10.0 + progress * (-15.0 + 6.0 * progress))
            rpm_limit = rpm_start + (float(max_rpm) - rpm_start) * phase
            send_fast(
                connection,
                four_motor_torque_frame(
                    values,
                    torque_slope=driver_slope_ma_per_s,
                    torque_max_rpm=rpm_limit,
                ),
            )
            write_stamps.append(time.perf_counter())
        # Reassert the exact endpoint once at the same cadence.  If a USB/RS485
        # collision loses the first final frame, no motor remains one ramp step
        # behind its peers.
        wait_tracking_deadline(started + len(plan) * interval)
        if STOP_EVENT.is_set():
            raise RuntimeError("用户停止校准")
        send_fast(
            connection,
            four_motor_torque_frame(
                target,
                torque_slope=driver_slope_ma_per_s,
                torque_max_rpm=max_rpm,
            ),
        )
        write_stamps.append(time.perf_counter())
    finally:
        if timer_resolution:
            set_high_resolution_timer(False)
    if verify_safety:
        feedback = read_all_reliable(connection, attempts=2)
        fault = safety_error(
            feedback,
            current_limit=max(max(target), SESSION_HOLD_CURRENT_MIN_MA),
        )
        if fault:
            raise RuntimeError(f"{label}：{fault}")
    elapsed = max(0.0, write_stamps[-1] - write_stamps[0]) if len(write_stamps) > 1 else 0.0
    actual_hz = (len(write_stamps) - 1) / elapsed if elapsed > 0.0 else 0.0
    append_process_log(
        "calibration_torque_ramp",
        label=label,
        from_current_ma=start,
        to_current_ma=target,
        max_rpm=float(max_rpm),
        start_max_rpm=rpm_start,
        controller="four-torque-aggregate-quintic",
        frames=len(write_stamps),
        scheduled_hz=CALIBRATION_TORQUE_RAMP_HZ,
        actual_hz=round(actual_hz, 3),
        duration_s=round(elapsed, 6),
        max_command_step_ma=plan_meta["max_command_step_ma"],
        max_slew_ma_per_s=plan_meta["max_slew_ma_per_s"],
        driver_slope_ma_per_s=driver_slope_ma_per_s,
        safety_verified=bool(verify_safety),
    )
    return target


def calibration_torque_ramp_plan(
    start_currents_ma: list[int] | tuple[int, ...],
    target_currents_ma: list[int] | tuple[int, ...],
    *,
    step_ma: int = CALIBRATION_TORQUE_RAMP_STEP_MA,
    dwell_seconds: float = CALIBRATION_TORQUE_RAMP_DWELL_SECONDS,
    max_slew_ma_per_s: float = CALIBRATION_TORQUE_RAMP_MAX_SLEW_MA_PER_S,
) -> tuple[list[list[int]], dict]:
    """Return the deterministic 50 Hz quintic current plan used by calibration."""

    if len(start_currents_ma) != len(MOTOR_IDS) or len(target_currents_ma) != len(MOTOR_IDS):
        raise ValueError("四电机张力渐变必须包含四个电流")
    start = [max(0, min(OPERATING_CURRENT_MAX_MA, int(round(float(value))))) for value in start_currents_ma]
    target = [max(0, min(OPERATING_CURRENT_MAX_MA, int(round(float(value))))) for value in target_currents_ma]
    if not math.isfinite(float(max_slew_ma_per_s)) or float(max_slew_ma_per_s) <= 0.0:
        raise ValueError("校准包络电流变化率必须是正有限数值")
    requested_slew = min(float(max_slew_ma_per_s), float(CALIBRATION_HARD_SWITCH_DRIVER_SLOPE_MA_PER_S))
    try:
        if float(dwell_seconds) > 0.0 and abs(int(step_ma)) > 0:
            requested_slew = min(
                requested_slew,
                abs(float(step_ma)) / float(dwell_seconds),
            )
    except (TypeError, ValueError, ZeroDivisionError):
        pass
    requested_slew = max(1.0, requested_slew)
    maximum_delta = max(abs(end - begin) for begin, end in zip(start, target))
    # The maximum derivative of 6t^5-15t^4+10t^3 is 1.875.  Include that
    # factor when selecting duration, otherwise a nominal 600 mA/s profile can
    # briefly reach 1125 mA/s at its midpoint.
    duration = max(
        CALIBRATION_TORQUE_RAMP_MIN_SECONDS,
        1.875 * maximum_delta / requested_slew,
    )
    intervals = max(1, int(math.ceil(duration * CALIBRATION_TORQUE_RAMP_HZ)))
    plan: list[list[int]] = []
    for index in range(intervals + 1):
        progress = index / intervals
        phase = progress * progress * progress * (10.0 + progress * (-15.0 + 6.0 * progress))
        plan.append([
            int(round(begin + (end - begin) * phase))
            for begin, end in zip(start, target)
        ])
    plan[0] = list(start)
    plan[-1] = list(target)
    max_command_step = max(
        (
            max(abs(current - previous) for current, previous in zip(row, prior))
            for prior, row in zip(plan, plan[1:])
        ),
        default=0,
    )
    return plan, {
        "duration_s": intervals / CALIBRATION_TORQUE_RAMP_HZ,
        "intervals": intervals,
        "frames": len(plan),
        "max_command_step_ma": max_command_step,
        "max_slew_ma_per_s": round(max_command_step * CALIBRATION_TORQUE_RAMP_HZ, 3),
    }


def calibration_transit_current_vector(active_index: int, strong: int, hold: int) -> list[int]:
    """Keep payout drums positively braked while travelling to one corner."""

    active = int(active_index)
    if active not in range(len(MOTOR_IDS)):
        raise ValueError("校准角点索引必须是 0..3")
    hold_current = max(SESSION_HOLD_CURRENT_MIN_MA, min(SESSION_HOLD_CURRENT_MAX_MA, int(hold)))
    strong_current = max(hold_current, min(OPERATING_CURRENT_MAX_MA, int(strong)))
    support = min(
        max(hold_current, CALIBRATION_TRANSIT_SUPPORT_CURRENT_MA),
        max(hold_current, strong_current - 100),
    )
    vector = [support for _ in MOTOR_IDS]
    vector[active] = strong_current
    return vector


def calibration_corner_current_vector(active_index: int, strong: int, hold: int) -> list[int]:
    """Return the exact force datum used at one physical calibration corner."""

    active = int(active_index)
    if active not in range(len(MOTOR_IDS)):
        raise ValueError("校准角点索引必须是 0..3")
    hold_current = max(
        SESSION_HOLD_CURRENT_MIN_MA,
        min(SESSION_HOLD_CURRENT_MAX_MA, int(hold)),
    )
    strong_current = max(
        hold_current + CALIBRATION_TORQUE_RAMP_STEP_MA,
        min(OPERATING_CURRENT_MAX_MA, int(strong)),
    )
    vector = [hold_current for _ in MOTOR_IDS]
    vector[active] = strong_current
    return vector


def switch_calibration_corner_force_vector(
    connection: object,
    previous_currents_ma: list[int] | tuple[int, ...],
    active_index: int,
    strong: int,
    hold: int,
) -> list[int]:
    """Apply one synchronized, non-staged corner-to-corner force switch.

    This is intentionally not a host ramp.  All four C5 records share one 0xAA
    packet, so the new pulling motor rises while the old one returns to hold at
    the same bus instant.  The driver's bounded current slope and RPM ceiling
    remain active, and the caller immediately enters the full telemetry/safety
    loop before accepting a sample.
    """

    if STOP_EVENT.is_set():
        raise RuntimeError("用户停止校准")
    previous = [int(value) for value in previous_currents_ma]
    if len(previous) != len(MOTOR_IDS):
        raise ValueError("上一角点必须包含四台电机电流")
    target = calibration_corner_current_vector(active_index, strong, hold)
    send_fast(
        connection,
        four_motor_torque_frame(
            target,
            torque_slope=CALIBRATION_HARD_SWITCH_DRIVER_SLOPE_MA_PER_S,
            torque_max_rpm=CALIBRATION_CORNER_MAX_RPM,
        ),
    )
    append_process_log(
        "calibration_corner_force_switch",
        corner=int(active_index) + 1,
        from_current_ma=previous,
        to_current_ma=target,
        controller="four-torque-aggregate-single-switch",
        host_ramp=False,
        driver_slope_ma_per_s=CALIBRATION_HARD_SWITCH_DRIVER_SLOPE_MA_PER_S,
        max_rpm=CALIBRATION_CORNER_MAX_RPM,
    )
    return target


def smooth_equal_torque_ramp(
    connection: object,
    from_current_ma: int,
    to_current_ma: int,
    *,
    step_ma: int = 50,
    dwell_seconds: float = 0.025,
) -> int:
    """Ramp all four X-firmware torque commands in small equal-current steps.

    This is used for normal centre-test entry, level changes and completion.
    A user stop or safety fault still takes the immediate stop/disable path.
    """
    start = max(0, min(OPERATING_CURRENT_MAX_MA, int(from_current_ma)))
    target = max(0, min(OPERATING_CURRENT_MAX_MA, int(to_current_ma)))
    step = max(1, abs(int(step_ma)))
    if start == target:
        values = [target]
    else:
        direction = 1 if target > start else -1
        values = list(range(start, target, direction * step))
        values.append(target)
    for value in values:
        if STOP_EVENT.is_set():
            raise RuntimeError("用户停止五点中心张力测试")
        for index, address in enumerate(MOTOR_IDS):
            accepted, _, reply = torque_command(
                connection,
                address,
                pull_directions()[index],
                value,
            )
            if not accepted:
                detail = direct.hex_bytes(reply) if reply else "超时无回包"
                raise RuntimeError(
                    f"中心等力矩平滑调节：M{index + 1} 的 {value}mA 命令未确认，RX={detail}"
                )
        if value != target:
            time.sleep(max(0.0, float(dwell_seconds)))
    return target


def smooth_equal_torque_ramp_stream(
    connection: object,
    from_current_ma: int,
    to_current_ma: int,
    *,
    step_ma: int = 50,
    dwell_seconds: float = 0.025,
) -> int:
    """Ramp equal torque while an unsolicited 0x43 stream is active.

    ACK-based ``transact`` calls are intentionally not used here: they reset
    the RX buffer and would discard fresh feedback frames. Each four-motor
    level is still sent in the same order and at the same 50mA/25ms ramp as
    the acknowledged path; the live 0x43 stream is the acceptance and safety
    evidence for the next level.
    """
    start = max(0, min(OPERATING_CURRENT_MAX_MA, int(from_current_ma)))
    target = max(0, min(OPERATING_CURRENT_MAX_MA, int(to_current_ma)))
    step = max(1, abs(int(step_ma)))
    if start == target:
        values = [target]
    else:
        direction = 1 if target > start else -1
        values = list(range(start, target, direction * step))
        values.append(target)
    for value in values:
        if STOP_EVENT.is_set():
            raise RuntimeError("用户停止五点中心张力测试")
        # The final setpoint matters; intermediate 50 mA ramp points only limit
        # jerk. Send that final setpoint twice so one collision with an
        # unsolicited 0x43 frame cannot leave a motor latched one level behind.
        repeats = 2 if value == target else 1
        for repeat in range(repeats):
            for index, address in enumerate(MOTOR_IDS):
                send_fast(
                    connection,
                    direct.torque_frame(
                        address,
                        pull_directions()[index],
                        value,
                        2000,
                        1000,
                    ),
                )
            if repeat + 1 < repeats:
                time.sleep(0.004)
        if value != target:
            time.sleep(max(0.0, float(dwell_seconds)))
    return target


def stop_accepted(reply: bytes, address: int) -> bool:
    """Accept both generic FE 02 and the Y42 V2 FE E2 stop reply."""

    return direct.command_accepted(reply, address, 0xFE) or (
        valid_reply(reply, address, 0xFE, 4) and reply[2] == 0xE2
    )


def invalidate_session_calibration(reason: str) -> None:
    """Close the live tension claim while retaining the fitted geometry.

    The smooth-drum session flag describes *continuous load*, not whether the
    four-corner geometry fit is still useful.  A stop or a latched driver
    status must therefore not erase the fitted model or force another scan;
    trajectory startup performs a fresh local encoder re-anchor.
    """

    with STATE_LOCK:
        calibration = STATE.get("calibration")
        if not isinstance(calibration, dict):
            return
        was_live = bool(
            calibration.get("session_id") == PROCESS_SESSION_ID
            and calibration.get("session_local_verified") is True
        )
        calibration["session_local_verified"] = False
        calibration["session_tension_held"] = False
        calibration["session_invalid_reason"] = str(reason)
        if was_live:
            if calibration.get("internal_model_verified") is True:
                calibration["internal_model_source"] = "saved_geometry_reuse_after_stop"
    if was_live:
        append_process_log("session_calibration_invalidated", reason=str(reason))


def trajectory_fault_requires_recalibration(error: str | None) -> bool:
    """Separate a recoverable path tolerance stop from a real safety fault.

    Endpoint/start settling can fail because the approximate drum model leaves
    a large residual or a driver needs longer to settle.  Those stops are safe
    to clean up with STOP/DISABLE while retaining the four-corner model.  A
    current, temperature, communication, or enable fault still invalidates the
    live tension claim.  The X driver status byte is retained for diagnostics:
    on this hardware it is latched across STOP/DISABLE and is not, by itself,
    proof that the rope datum changed.
    """
    text = str(error or "")
    hard_markers = (
        "电流",
        "过流",
        "过载",
        "温度",
        "通讯",
        "通信",
        "无回包",
        "回包",
        "无法使能",
        "使能失败",
        "安全阈值",
    )
    return any(marker in text for marker in hard_markers)


def stop_all(connection: object, *, invalidate: bool = True) -> list[dict]:
    results = []
    for address in MOTOR_IDS:
        tx = direct.frame(address, 0xFE, 0x98, 0x00, direct.FRAME_END)
        rx = direct.transact(connection, tx)
        result = command_result(address, 0xFE, tx, rx)
        # Y42 V2 commonly acknowledges the stop frame with FE E2 rather
        # than the generic command ACK byte FE 02.
        result["accepted"] = stop_accepted(rx, address)
        result["ok"] = result["accepted"] or bool(rx)
        results.append(result)
    if invalidate:
        invalidate_session_calibration("电机已停止/失能，四根绳不再保证持续张紧；请重新执行本次上电四角校准")
    return results


def disable_all(connection: object, *, invalidate: bool = True) -> list[dict]:
    results = stop_all(connection, invalidate=invalidate)
    disable_results: list[dict] = []
    for address in MOTOR_IDS:
        tx = command_frame(address, "disable", {})
        disable_results.append(command_result(address, 0xF3, tx, direct.transact(connection, tx)))
    results.extend(disable_results)
    # The disable ACK is authoritative for the command, but it does not carry
    # the full 0x3A status payload. Clear only the cached enabled bit so the
    # floating dashboard cannot briefly show stale "enabled" state before the
    # next real status poll.
    with STATE_LOCK:
        for result in disable_results:
            if not result.get("accepted"):
                continue
            item = STATE["telemetry"].get(str(result["id"]))
            if not isinstance(item, dict) or item.get("flags") is None:
                continue
            item["flags"] = int(item["flags"]) & ~0x01
            item["flags_text"] = direct.decode_flags(item["flags"])
    return results


def disable_one(connection: object, address: int) -> bool:
    stop_tx = command_frame(address, "stop", {})
    stop_rx = direct.transact(connection, stop_tx)
    disable_tx = command_frame(address, "disable", {})
    disable_rx = direct.transact(connection, disable_tx)
    return stop_accepted(stop_rx, address) and direct.command_accepted(disable_rx, address, 0xF3)


def read_all(
    connection: object,
    *,
    first_byte_timeout: float = 0.06,
    inter_byte_quiet: float = 0.004,
    deadline: float | None = None,
) -> list[direct.Telemetry]:
    values = [
        direct.read_telemetry(
            connection,
            address,
            first_byte_timeout=first_byte_timeout,
            inter_byte_quiet=inter_byte_quiet,
            **({"deadline": deadline} if deadline is not None else {}),
        )
        for address in MOTOR_IDS
    ]
    update_telemetry(values)
    return values


def telemetry_ready_for_calibration(values: list[direct.Telemetry]) -> bool:
    """Require the fields used by calibration to be present for every motor."""

    return len(values) == len(MOTOR_IDS) and all(
        t.position is not None
        and t.rpm is not None
        and t.phase_current is not None
        and t.temperature is not None
        for t in values
    )


def read_all_reliable(
    connection: object,
    attempts: int = 2,
    *,
    first_byte_timeout: float = 0.06,
    inter_byte_quiet: float = 0.004,
    deadline: float | None = None,
) -> list[direct.Telemetry]:
    """Retry a complete telemetry pass when a USB-RS485 frame is lost."""

    last: list[direct.Telemetry] = []
    for attempt in range(attempts):
        if deadline is not None:
            calibration_check_deadline(deadline)
        last = read_all(
            connection,
            first_byte_timeout=first_byte_timeout,
            inter_byte_quiet=inter_byte_quiet,
            **({"deadline": deadline} if deadline is not None else {}),
        )
        if deadline is not None:
            calibration_check_deadline(deadline)
        if telemetry_ready_for_calibration(last):
            return last
        if attempt + 1 < attempts:
            time.sleep(0.05 if deadline is None else min(0.05, max(0.0, deadline - time.perf_counter())))
    return last


def read_link_health(connection: object, *, first_byte_timeout: float = 0.08) -> list[direct.Telemetry]:
    """Probe only the four flag registers before requesting full telemetry.

    When the USB adapter is present but the motor bus is unplugged, asking for
    28 telemetry fields per status refresh makes the web request look frozen.
    A four-frame health probe gives a fast, unambiguous link result first.
    """

    values: list[direct.Telemetry] = []
    for address in MOTOR_IDS:
        telemetry = direct.Telemetry(address)
        reply = direct.transact(
            connection,
            direct.frame(address, 0x3A, direct.FRAME_END),
            first_byte_timeout=first_byte_timeout,
            inter_byte_quiet=0.002,
        )
        if valid_reply(reply, address, 0x3A, 4):
            telemetry.flags = reply[2]
        values.append(telemetry)
    return values


def read_all_with_reconnect(
    port: str,
    baud: int,
    attempts: int = 3,
    *,
    first_byte_timeout: float = 0.06,
    inter_byte_quiet: float = 0.004,
    lock_timeout: float | None = None,
) -> tuple[list[direct.Telemetry], bool, str]:
    """Read all four motors, reopening the USB-RS485 handle after a bad pass.

    A pyserial object can remain open after a USB adapter has reset.  Reusing
    that stale handle makes every following query look like an offline motor,
    so status polling gets a bounded fresh-handle retry path too.
    """

    last: list[direct.Telemetry] = []
    last_error = ""
    for attempt in range(1, attempts + 1):
        attempt_error = ""
        acquired = SERIAL_LOCK.acquire() if lock_timeout is None else SERIAL_LOCK.acquire(timeout=lock_timeout)
        if not acquired:
            return last, False, "串口正被其他自动流程占用，状态读取已快速返回"
        try:
            with direct.open_serial(port, baud) as connection:
                # The real adapter's measured response latency is about
                # 31..44 ms, so a 35 ms probe falsely reports M1 offline.
                # Keep the probe short for a dead bus, but above the observed
                # worst-case latency for a live motor.
                health_timeout = max(0.08, min(first_byte_timeout, 0.12))
                health = read_link_health(connection, first_byte_timeout=health_timeout)
                responsive = sum(telemetry.flags is not None for telemetry in health)
                if responsive == 0:
                    last = health
                    update_telemetry(last)
                    attempt_error = "串口已打开，但 ID 1..4 均无 0x3A 状态回包"
                else:
                    last = read_all_reliable(
                        connection,
                        attempts=2,
                        first_byte_timeout=first_byte_timeout,
                        inter_byte_quiet=inter_byte_quiet,
                    )
                    if responsive < len(MOTOR_IDS):
                        attempt_error = f"健康查询只有 {responsive}/{len(MOTOR_IDS)} 台有回包"
        except Exception as exc:
            attempt_error = str(exc)
        finally:
            SERIAL_LOCK.release()
        if telemetry_ready_for_calibration(last):
            schedule_prepare_if_needed(port, baud)
            return last, True, ""
        last_error = attempt_error or "四台遥测字段不完整"
        if attempt < attempts:
            time.sleep(0.08 * attempt)
    return last, False, last_error or "RS485 无有效回包"


def _cached_status_result(port: str, baud: int, *, message: str | None = None) -> dict:
    with STATUS_CACHE_LOCK:
        cached = copy.deepcopy(STATUS_CACHE.get("result"))
        cached_port = STATUS_CACHE.get("port")
        cached_baud = STATUS_CACHE.get("baud")
    if cached is not None and cached_port == port and cached_baud == baud:
        if message:
            cached["message"] = message
        return cached
    snapshot = state_snapshot()
    return {
        "ok": True,
        "action": "status",
        "motors": list(snapshot.get("telemetry", {}).values()),
        "auto": snapshot.get("auto", "idle"),
        "reconnected": False,
        "message": message or "正在建立串口状态连接",
    }


def status_for_web(port: str, baud: int) -> dict:
    """Return a bounded status response without piling up serial requests."""

    now = time.monotonic()
    with STATUS_CACHE_LOCK:
        age = now - float(STATUS_CACHE.get("at", 0.0))
        cached_port = STATUS_CACHE.get("port")
        cached_baud = STATUS_CACHE.get("baud")
        cached_recovered = bool(STATUS_CACHE.get("recovered"))
        has_cache = STATUS_CACHE.get("result") is not None and cached_port == port and cached_baud == baud
    cache_window = STATUS_SUCCESS_CACHE_SECONDS if cached_recovered else STATUS_FAILURE_CACHE_SECONDS
    if has_cache and age < cache_window:
        return _cached_status_result(port, baud)
    if not STATUS_POLL_LOCK.acquire(blocking=False):
        return _cached_status_result(port, baud, message="状态读取正在进行，已显示上一次结果；不会叠加串口请求")
    try:
        # A second browser request may have filled the cache while this one
        # was waiting for the single-flight guard.
        now = time.monotonic()
        with STATUS_CACHE_LOCK:
            age = now - float(STATUS_CACHE.get("at", 0.0))
            cached_port = STATUS_CACHE.get("port")
            cached_baud = STATUS_CACHE.get("baud")
            cached_recovered = bool(STATUS_CACHE.get("recovered"))
            has_cache = STATUS_CACHE.get("result") is not None and cached_port == port and cached_baud == baud
        cache_window = STATUS_SUCCESS_CACHE_SECONDS if cached_recovered else STATUS_FAILURE_CACHE_SECONDS
        if has_cache and age < cache_window:
            return _cached_status_result(port, baud)

        values, recovered, reason = read_all_with_reconnect(
            port,
            baud,
            attempts=1,
            first_byte_timeout=0.08,
            inter_byte_quiet=0.002,
            lock_timeout=0.05,
        )
        deferred = ("串口正被其他自动流程占用" in reason)
        if not recovered and not deferred:
            # A single missed health probe is common on a busy half-duplex
            # adapter. Keep the last good top-level state until two
            # consecutive polls fail, so one transient timeout cannot make
            # all four motors look permanently offline in the UI.
            with STATUS_CACHE_LOCK:
                failure_streak = int(STATUS_CACHE.get("failure_streak", 0)) + 1
                STATUS_CACHE["failure_streak"] = failure_streak
            if failure_streak >= 2:
                set_state(message="状态读取失败：" + reason)
        elif recovered:
            with STATUS_CACHE_LOCK:
                STATUS_CACHE["failure_streak"] = 0
            with STATE_LOCK:
                stale_status_message = str(STATE.get("message", "")).startswith(("状态读取失败：", "状态读取异常："))
            if stale_status_message:
                set_state(message="通讯已恢复：四台遥测正常")
        snapshot = state_snapshot()
        result = {
            "ok": True,
            "action": "status",
            "motors": list(snapshot["telemetry"].values()),
            "auto": snapshot["auto"],
            "reconnected": recovered,
            "status_deferred": deferred,
            "message": "状态读取暂缓：另一个串口操作正在进行，保留上次状态" if deferred else ("四台遥测已自动重连恢复" if recovered else "自动重连未恢复：" + reason),
        }
        with STATUS_CACHE_LOCK:
            STATUS_CACHE.update({"at": time.monotonic(), "port": port, "baud": baud, "recovered": recovered, "result": copy.deepcopy(result)})
        return result
    except Exception as exc:
        reason = str(exc)
        with STATUS_CACHE_LOCK:
            failure_streak = int(STATUS_CACHE.get("failure_streak", 0)) + 1
            STATUS_CACHE["failure_streak"] = failure_streak
        if failure_streak >= 2:
            set_state(message="状态读取异常：" + reason)
        result = _cached_status_result(port, baud, message="状态读取异常：" + reason)
        with STATUS_CACHE_LOCK:
            STATUS_CACHE.update({"at": time.monotonic(), "port": port, "baud": baud, "recovered": False, "failure_streak": failure_streak, "result": copy.deepcopy(result)})
        return result
    finally:
        STATUS_POLL_LOCK.release()


def disable_all_with_reconnect(
    port: str,
    baud: int,
    attempts: int = 3,
    announce: bool = True,
    clear_timed_streams: bool = True,
    preserve_session: bool = False,
) -> dict:
    """Best-effort safety shutdown that retries with a new serial handle.

    It is intentionally used after a motion/telemetry failure.  We never
    resume motion automatically after a link fault; the reconnect is only to
    send and verify STOP + DISABLE for all four motors.
    """

    last_results: list[dict] = []
    last_error = ""
    for attempt in range(1, attempts + 1):
        if announce:
            set_state(message=f"通讯异常：正在重连并失能四台电机（{attempt}/{attempts}）")
        try:
            with SERIAL_LOCK, direct.open_serial(port, baud) as connection:
                # A previous tracking/test process may have left the manual
                # 0x11 periodic return active. Clear both the legacy 0x36 and
                # aggregate 0x43 streams before sending STOP/DISABLE; an
                # unsolicited long frame can otherwise occupy the half-duplex
                # RX path and make a valid disable look like a lost ACK.
                # Calibration/grid workers use synchronous reads and never
                # start an unsolicited stream. Skipping sixteen unnecessary
                # stream-stop transactions makes a safety recovery finish
                # promptly instead of appearing stuck at 1/3.
                timed_stream_stopped = (
                    stop_timed_position_stream(connection)
                    if clear_timed_streams
                    else True
                )
                last_results = disable_all(connection, invalidate=not preserve_session)
            if last_results and all(item.get("accepted") for item in last_results):
                if timed_stream_stopped:
                    return {"ok": True, "attempts": attempt, "results": last_results}
                last_error = "定时反馈流未全部确认关闭"
            else:
                last_error = "四台 STOP/DISABLE 未全部收到 ACK"
        except Exception as exc:
            last_error = str(exc)
        if attempt < attempts:
            time.sleep(0.12 * attempt)
    return {
        "ok": False,
        "attempts": attempts,
        "results": last_results,
        "error": last_error or "RS485 重连失败",
    }


def request_emergency_stop(data: dict | None = None) -> dict:
    """Dispatch STOP independently of the motion worker's teardown window.

    A worker may still appear alive while it is only saving its recording. A
    stop arriving then must not be delegated to a loop that has already exited.
    New preparation/motion stays blocked until a separate shutdown acknowledges
    all four axes. The caller returns promptly; it never claims an ACK early.
    """
    data = data or {}
    SOFT_STOP_EVENT.clear()
    with STATE_LOCK:
        stop_auto = str(STATE.get("auto", ""))
    append_process_log("emergency_stop_requested", source="api_command", active_auto=stop_auto)
    STOP_EVENT.set()
    with EMERGENCY_STOP_LOCK:
        if EMERGENCY_STOP_PENDING.is_set():
            return {"ok": True, "action": "stop", "pending": True,
                    "message": "急停确认正在进行，请勿重复操作；未确认时请使用硬件急停"}
        EMERGENCY_STOP_PENDING.set()
        with STATE_LOCK:
            port_hint = STATE.get("port") or data.get("port")
            baud_hint = int(STATE.get("baud") or data.get("baud") or direct.DEFAULT_BAUD)
        set_state(control_unlocked=False, emergency_stop_pending=True,
                  emergency_stop_acknowledged=None,
                  message="已请求急停，正在独立确认四台停止与失能；尚未确认完成")

        def shutdown() -> None:
            recovery = {"ok": False, "error": "急停尚未执行"}
            try:
                port = resolve_port(port_hint)
                recovery = disable_all_with_reconnect(
                    port,
                    baud_hint,
                    attempts=1,
                    announce=False,
                    clear_timed_streams=False,
                    preserve_session=True,
                )
                if recovery.get("ok") is not True:
                    recovery = disable_all_with_reconnect(
                        port,
                        baud_hint,
                        announce=False,
                        preserve_session=True,
                    )
            except Exception as exc:
                recovery = {"ok": False, "error": str(exc)}
            finally:
                acknowledged = recovery.get("ok") is True
                rearm_ready = False
                rearm_reason = ""
                if acknowledged:
                    rearm_ready, rearm_reason = capture_emergency_stop_rearm_checkpoint(
                        str(port_hint or current_port()),
                        baud_hint,
                    )
                if not acknowledged or not rearm_ready:
                    invalidate_session_calibration(
                        "用户急停后未能记录可恢复位置；请重新执行四角校准"
                    )
                if not active_auto():
                    STOP_EVENT.clear()
                set_state(
                    control_unlocked=False, emergency_stop_pending=False,
                    emergency_stop_acknowledged=acknowledged,
                    auto="idle" if acknowledged else "error",
                    calibration_requires_full=bool(acknowledged and not rearm_ready),
                    calibration_last_error=None if rearm_ready else (rearm_reason or recovery.get("error")),
                    message=("四台急停与失能已确认；保存参数保留，运行前需重新准备"
                             if acknowledged and not rearm_ready else
                             "四台急停与失能已确认；急停位置已记录，点击“校准”将快速原位恢复，无需重新四角标定"
                             if acknowledged and rearm_ready else
                             "急停未能确认四台失能，请立即使用硬件急停或切断动力："
                             + str(recovery.get("error") or "回包不完整")),
                )
                append_process_log("independent_emergency_stop_finished", recovery=recovery)
                EMERGENCY_STOP_PENDING.clear()

        try:
            threading.Thread(target=shutdown, name="y42-independent-stop", daemon=True).start()
        except Exception as exc:
            EMERGENCY_STOP_PENDING.clear()
            set_state(control_unlocked=False, auto="error", emergency_stop_pending=False,
                      emergency_stop_acknowledged=False,
                      message="急停线程启动失败，请立即使用硬件急停或切断动力：" + str(exc))
            raise
    return {"ok": True, "action": "stop", "pending": True,
            "message": "已请求独立急停，正在确认四台失能；未确认时请使用硬件急停"}


def stability_test(port: str, baud: int, rounds: int) -> dict:
    if not 1 <= rounds <= 100:
        raise ValueError("稳定性测试轮数必须是 1..100")
    rows = {address: {"valid": 0, "timeout": 0, "bad": 0, "latencies_ms": [], "bad_frames": []} for address in MOTOR_IDS}
    started = time.perf_counter()
    with SERIAL_LOCK, direct.open_serial(port, baud) as connection:
        for _ in range(rounds):
            for address in MOTOR_IDS:
                t0 = time.perf_counter()
                reply = direct.status_query(connection, address)
                latency = (time.perf_counter() - t0) * 1000.0
                row = rows[address]
                if valid_reply(reply, address, 0x3A, 4):
                    row["valid"] += 1
                    row["latencies_ms"].append(latency)
                elif reply:
                    row["bad"] += 1
                    if len(row["bad_frames"]) < 5:
                        row["bad_frames"].append(direct.hex_bytes(reply))
                else:
                    row["timeout"] += 1
            time.sleep(0.02)
    motors = {}
    for address, row in rows.items():
        latencies = row["latencies_ms"]
        motors[str(address)] = {
            "label": MOTOR_LABELS[address - 1],
            "valid": row["valid"],
            "timeout": row["timeout"],
            "bad": row["bad"],
            "success_rate": round(row["valid"] / rounds * 100.0, 1),
            "latency_ms": {
                "min": round(min(latencies), 2) if latencies else None,
                "avg": round(statistics.mean(latencies), 2) if latencies else None,
                "max": round(max(latencies), 2) if latencies else None,
            },
            "bad_frames": row["bad_frames"],
        }
    return {"ok": True, "action": "stability", "port": port, "baud": baud, "rounds": rounds, "elapsed_s": round(time.perf_counter() - started, 3), "motors": motors, "note": "只发送 0x3A 状态查询，不发送使能、速度、力矩或位置指令"}


class TimingAccumulator:
    """Streaming timing metrics; no timestamp list is retained."""

    __slots__ = ("count", "first", "last", "previous", "interval_count", "interval_sum", "interval_min", "interval_max")

    def __init__(self) -> None:
        self.count = 0
        self.first: float | None = None
        self.last: float | None = None
        self.previous: float | None = None
        self.interval_count = 0
        self.interval_sum = 0.0
        self.interval_min: float | None = None
        self.interval_max: float | None = None

    def add(self, stamp: float) -> None:
        stamp = float(stamp)
        if not math.isfinite(stamp):
            return
        self.count += 1
        self.first = stamp if self.first is None else self.first
        if self.previous is not None:
            interval_ms = max(0.0, (stamp - self.previous) * 1000.0)
            self.interval_count += 1
            self.interval_sum += interval_ms
            self.interval_min = interval_ms if self.interval_min is None else min(self.interval_min, interval_ms)
            self.interval_max = interval_ms if self.interval_max is None else max(self.interval_max, interval_ms)
        self.previous = stamp
        self.last = stamp


class RunningStats:
    """Streaming min/mean/max accumulator for long hardware tests."""

    __slots__ = ("count", "total", "minimum", "maximum")

    def __init__(self) -> None:
        self.count = 0
        self.total = 0.0
        self.minimum: float | None = None
        self.maximum: float | None = None

    def add(self, value: object) -> None:
        try:
            number = float(value)
        except (TypeError, ValueError):
            return
        if not math.isfinite(number):
            return
        self.count += 1
        self.total += number
        self.minimum = number if self.minimum is None else min(self.minimum, number)
        self.maximum = number if self.maximum is None else max(self.maximum, number)

    @property
    def average(self) -> float | None:
        return self.total / self.count if self.count else None


def _timing_stats(stamps: object, started: float, ended: float, target_hz: float) -> dict:
    if isinstance(stamps, TimingAccumulator):
        count = stamps.count
        interval_min = stamps.interval_min
        interval_avg = stamps.interval_sum / stamps.interval_count if stamps.interval_count else None
        interval_max = stamps.interval_max
    else:
        values = [float(value) for value in stamps] if isinstance(stamps, (list, tuple)) else []
        count = len(values)
        intervals = [(b - a) * 1000.0 for a, b in zip(values, values[1:])]
        interval_min = min(intervals) if intervals else None
        interval_avg = statistics.mean(intervals) if intervals else None
        interval_max = max(intervals) if intervals else None
    elapsed = max(0.001, ended - started)
    return {
        "frames": count,
        "elapsed_s": round(elapsed, 3),
        "achieved_hz": round(count / elapsed, 3),
        "target_hz": target_hz,
        "interval_ms": {
            "min": round(interval_min, 3) if interval_min is not None else None,
            "avg": round(interval_avg, 3) if interval_avg is not None else None,
            "max": round(interval_max, 3) if interval_max is not None else None,
        },
    }


def timed_feedback_frame(
    address: int,
    info_code: int = TIMED_FEEDBACK_INFO_CODE,
    interval_ms: int = TIMED_POSITION_INTERVAL_MS,
) -> bytes:
    """Build the Y42 0x11 periodic-return command.

    The manual's field is one information code, but 0x43 is the X-firmware
    aggregate system-status code: its single reply contains both position and
    phase current (plus safety/status fields).  This is the protocol-level
    answer to the four-motor position+current requirement.
    """

    if address not in MOTOR_IDS:
        raise ValueError(f"定时回传只允许 ID {MOTOR_IDS}")
    if int(info_code) not in (0x36, 0x43):
        raise ValueError("定时回传信息码只支持位置 0x36 或 X 固件合并状态 0x43")
    interval = int(interval_ms)
    if not 0 <= interval <= 0xFFFF:
        raise ValueError("定时回传间隔必须是 0..65535ms")
    return direct.frame(
        address,
        0x11,
        0x18,
        int(info_code),
        (interval >> 8) & 0xFF,
        interval & 0xFF,
        direct.FRAME_END,
    )


def timed_position_frame(address: int, interval_ms: int = TIMED_POSITION_INTERVAL_MS) -> bytes:
    """Build the legacy periodic 0x36 position-return command."""

    return timed_feedback_frame(address, 0x36, interval_ms)


def multi_motor_timed_feedback_frame(interval_ms: int, info_code: int = TIMED_FEEDBACK_INFO_CODE) -> bytes:
    """Pack four 0x11 timed-return settings into one documented 0xAA frame."""
    interval = int(interval_ms)
    if not 0 <= interval <= 0xFFFF:
        raise ValueError("定时回传间隔必须是 0..65535ms")
    if int(info_code) not in (0x36, TIMED_FEEDBACK_INFO_CODE):
        raise ValueError("定时回传信息码只支持位置 0x36 或 X 固件合并状态 0x43")
    packet = bytearray((0x00, 0xAA, 0x00, 0x00))
    for address in MOTOR_IDS:
        packet += timed_feedback_frame(address, int(info_code), interval)
    # Y42 V1.1 p.36: total bytes include the four-byte header and final 6B.
    length = len(packet) + 1
    packet[2] = (length >> 8) & 0xFF
    packet[3] = length & 0xFF
    packet.append(direct.FRAME_END)
    expected_length = 4 + len(MOTOR_IDS) * 7 + 1
    if len(packet) != expected_length:
        raise RuntimeError(f"四电机定时回传 0xAA 合帧长度异常: {len(packet)} 字节")
    return bytes(packet)


def _timed_feedback_command(
    connection: object,
    address: int,
    info_code: int,
    interval_ms: int,
    timeout: float = TIMED_POSITION_COMMAND_TIMEOUT,
) -> tuple[bool, bytes]:
    """Send one timed-return setting while tolerating stream frames."""

    connection.reset_input_buffer()
    send_fast(connection, timed_feedback_frame(address, info_code, interval_ms))
    expected_ack = bytes((address, 0x11, 0x02, direct.FRAME_END))
    received = bytearray()
    deadline = time.perf_counter() + max(0.03, timeout)
    while time.perf_counter() < deadline:
        waiting = int(getattr(connection, "in_waiting", 0) or 0)
        chunk = connection.read(min(256, waiting)) if waiting else connection.read(1)
        if chunk:
            received.extend(chunk)
            if expected_ack in received:
                return True, bytes(received)
    return False, bytes(received)


def _multi_motor_timed_feedback_command(
    connection: object,
    info_code: int,
    interval_ms: int,
    timeout: float = TIMED_POSITION_COMMAND_TIMEOUT,
) -> tuple[bool, bytes]:
    """Configure all four timed streams atomically through one 0xAA frame."""
    connection.reset_input_buffer()
    send_fast(connection, multi_motor_timed_feedback_frame(interval_ms, info_code))
    received = bytearray()
    deadline = time.perf_counter() + max(0.03, timeout)
    while time.perf_counter() < deadline:
        waiting = int(getattr(connection, "in_waiting", 0) or 0)
        chunk = connection.read(min(512, waiting)) if waiting else connection.read(1)
        if chunk:
            received.extend(chunk)
            # Y42 returns the acknowledgement for the first sub-command. If
            # an adapter/firmware omits that ACK, accepting only after seeing
            # a valid 0x43 frame from every ID still proves the aggregate took
            # effect, while never accepting a partial one-motor stream.
            if bytes((MOTOR_IDS[0], 0x11, 0x02, direct.FRAME_END)) in received:
                return True, bytes(received)
            if int(info_code) == TIMED_FEEDBACK_INFO_CODE:
                records, _ = _consume_timed_position_buffer(bytearray(received))
                if {record.address for record in records} == set(MOTOR_IDS):
                    return True, bytes(received)
    return False, bytes(received)


def _start_timed_feedback_stream_once(
    connection: object,
    interval_ms: int = TIMED_POSITION_INTERVAL_MS,
    info_code: int = TIMED_FEEDBACK_INFO_CODE,
) -> list[dict]:
    """Start one asynchronous feedback stream per motor without ACK starvation."""

    # Clear both the old position stream and the new aggregate stream. This
    # makes an upgrade/reload safe even if an older worker died mid-session.
    stop_timed_feedback_stream(connection)
    # The documented 0xAA multi-motor frame is used for motion and is tested
    # separately. On this X-firmware sample, putting four 0x11 timer settings
    # in one 0xAA frame does not reliably enable all four streams, so use a
    # quiet per-motor setup followed by a controlled per-motor promotion. No
    # high-rate stream is allowed to starve the next motor's ACK.
    target_interval_ms = int(interval_ms)
    startup_interval_ms = max(target_interval_ms, TIMED_FEEDBACK_START_INTERVAL_MS)
    # All four X-firmware 0x43 replies share one half-duplex RS485 wire.  If
    # their timers use the same period they fire on the same phase and their
    # 37-byte frames collide; the resulting byte stream can look like a valid
    # M1 frame followed by three corrupted payloads.  De-phase them by waiting
    # between the four setup commands, but keep the interval itself identical
    # for every motor.  The previous implementation added 7 ms to each motor's
    # interval, which was not a phase offset: it reduced M2/M3/M4's actual
    # feedback rates and made a nominal 100 Hz snapshot impossible.
    baudrate = float(getattr(connection, "baudrate", direct.DEFAULT_BAUD) or direct.DEFAULT_BAUD)
    phase_step_seconds = max(
        TIMED_FEEDBACK_PHASE_MIN_SECONDS,
        min(
            TIMED_FEEDBACK_PHASE_MAX_SECONDS,
            TIMED_FEEDBACK_FRAME_BYTES * 20.0 / max(1.0, baudrate),
        ),
    )
    staggered = int(info_code) == TIMED_FEEDBACK_INFO_CODE
    results = []
    for address in MOTOR_IDS:
        address_interval_ms = int(startup_interval_ms)
        accepted, reply = _timed_feedback_command(connection, address, info_code, address_interval_ms)
        results.append({
            "id": address,
            "accepted": accepted,
            "aggregate": False,
            "info_code": f"0x{int(info_code):02X}",
            "startup_interval_ms": address_interval_ms,
            "staggered": staggered,
            "phase_step_ms": round(phase_step_seconds * 1000.0, 3),
            "rx": direct.hex_bytes(reply),
        })
        if not accepted:
            stop_timed_feedback_stream(connection)
            raise RuntimeError(
                f"ID {address} 未确认启动定时 0x{int(info_code):02X} 回传，"
                f"RX={direct.hex_bytes(reply) or '超时无回包'}"
            )
        if address != MOTOR_IDS[-1]:
            time.sleep(phase_step_seconds)
    if startup_interval_ms != target_interval_ms:
        for address in MOTOR_IDS:
            address_interval_ms = int(target_interval_ms)
            accepted, reply = _timed_feedback_command(connection, address, info_code, address_interval_ms)
            if not accepted:
                stop_timed_feedback_stream(connection)
                raise RuntimeError(
                    f"ID {address} 未确认切换定时 0x{int(info_code):02X} 到 {address_interval_ms}ms，"
                    f"RX={direct.hex_bytes(reply) or '超时无回包'}"
                )
            if address != MOTOR_IDS[-1]:
                time.sleep(phase_step_seconds)
    # The start ACKs and any first frames are not part of the measurement.
    connection.reset_input_buffer()
    return results


def start_timed_feedback_stream(
    connection: object,
    interval_ms: int = TIMED_POSITION_INTERVAL_MS,
    info_code: int = TIMED_FEEDBACK_INFO_CODE,
) -> list[dict]:
    """Start feedback and negotiate a safe cadence when the bus is busy.

    Motion still uses one simultaneous 0xAA frame.  The four unsolicited
    feedback streams cannot be configured atomically on the tested X firmware,
    so startup is staged.  If a high-rate promotion is rejected while the
    adapter is still draining motion ACKs, retry cleanly at the configured
    safe interval rather than leaving the application in a half-started state.
    """
    requested_interval_ms = int(interval_ms)
    try:
        results = _start_timed_feedback_stream_once(connection, requested_interval_ms, info_code)
        effective_interval_ms = requested_interval_ms
    except Exception as first_error:
        fallback_interval_ms = max(requested_interval_ms, TIMED_FEEDBACK_SAFE_INTERVAL_MS)
        if fallback_interval_ms <= requested_interval_ms:
            raise
        try:
            if not stop_timed_feedback_stream(connection):
                raise RuntimeError("高速反馈失败后的旧流未能全部清除")
            results = _start_timed_feedback_stream_once(connection, fallback_interval_ms, info_code)
            effective_interval_ms = fallback_interval_ms
        except Exception as fallback_error:
            raise RuntimeError(
                f"反馈流启动失败（请求 {requested_interval_ms}ms，安全回退 {fallback_interval_ms}ms 也失败）："
                f"{first_error}；{fallback_error}"
            ) from fallback_error
        append_process_log(
            "timed_feedback_fallback",
            requested_interval_ms=requested_interval_ms,
            effective_interval_ms=effective_interval_ms,
            reason=str(first_error)[:300],
        )
    for item in results:
        item["requested_interval_ms"] = requested_interval_ms
        item["effective_interval_ms"] = effective_interval_ms
    setattr(connection, "_y42_feedback_interval_ms", effective_interval_ms)
    return results


def start_timed_position_stream(connection: object, interval_ms: int = TIMED_POSITION_INTERVAL_MS) -> list[dict]:
    """Compatibility wrapper for the legacy position-only stream."""

    return start_timed_feedback_stream(connection, interval_ms, 0x36)


def stop_timed_feedback_stream(connection: object) -> bool:
    """Stop both possible periodic streams before normal request/response."""

    # The 0xAA multi-motor packing is reliable for motion, but the X-firmware
    # sample used here did not reliably apply four 0x11 timer settings in one
    # frame. Do not use the aggregate form to stop streams either: a false
    # positive here leaves one old unsolicited stream running and then steals
    # the next motor's start ACK. Clear every stream explicitly and verify all
    # sixteen stop acknowledgements before proceeding.
    for attempt in range(4):
        results = []
        for info_code in (0x36, TIMED_FEEDBACK_INFO_CODE):
            for address in MOTOR_IDS:
                accepted, reply = _timed_feedback_command(connection, address, info_code, 0)
                results.append({"id": address, "info_code": info_code, "accepted": accepted, "rx": direct.hex_bytes(reply)})
        connection.reset_input_buffer()
        if all(item["accepted"] for item in results):
            return True
        if attempt < 3:
            time.sleep(0.02 * (attempt + 1))
    return False


def stop_timed_position_stream(connection: object) -> bool:
    """Compatibility wrapper that also clears aggregate 0x43 streams."""

    return stop_timed_feedback_stream(connection)


@dataclass(frozen=True)
class TimedFeedbackRecord:
    """One device-timestamped sample decoded from a Y42 timed-return frame."""

    address: int
    position: float
    phase_current: int | None
    sampled_at: float
    voltage: float | None = None
    bus_current: int | None = None
    rpm: float | None = None
    temperature: int | None = None
    flags: int | None = None
    raw_packet_hex: str | None = None


def time_aligned_feedback_positions(
    snapshot: list[TimedFeedbackRecord] | tuple[TimedFeedbackRecord, ...],
) -> tuple[float, ...]:
    """Return four positions projected to the newest sample's time.

    ``sampled_at`` is the host receive time, not a device-side timestamp.  It
    is nevertheless the correct ordering signal for a timed stream.  A motor
    with no valid RPM (for example the legacy 0x36 position-only frame) is
    retained without extrapolation.  Raw records remain untouched and are
    logged separately by callers.
    """
    if not snapshot:
        return ()
    target_at = max(float(item.sampled_at) for item in snapshot)
    aligned: list[float] = []
    for item in snapshot:
        position = float(item.position)
        delta = target_at - float(item.sampled_at)
        rpm = item.rpm
        if (
            0.0 < delta <= FEEDBACK_TIME_ALIGNMENT_MAX_SECONDS
            and rpm is not None
            and math.isfinite(float(rpm))
        ):
            # RPM -> degrees/second, then advance to the common timestamp.
            position += float(rpm) * 6.0 * delta
        aligned.append(position)
    return tuple(aligned)


class FourMotorFeedbackAssembler:
    """Assemble one time-coherent cycle without mixing adjacent cycles.

    A timed-return stream has no cycle number. The old implementation used
    only duplicate IDs as a boundary, so a dropped packet could leave a stale
    motor in the pending list and combine it with the next cycle. That is the
    exact failure mode that draws a short reversed segment or turns a circle
    into an asymmetric arc. Keep one record per ID and require the complete
    four-ID set to arrive inside the measured wire-time window.
    """

    def __init__(self, coherence_window: float = TRACKING_POSITION_COHERENCE_SECONDS) -> None:
        self.coherence_window = max(0.005, float(coherence_window))
        self.pending: dict[int, TimedFeedbackRecord] = {}

    def _restart(self, record: TimedFeedbackRecord) -> None:
        self.pending = {int(record.address): record}

    def add(self, record: TimedFeedbackRecord) -> list[TimedFeedbackRecord] | None:
        address = int(record.address)
        if address not in MOTOR_IDS:
            return None
        if not self.pending:
            self._restart(record)
            return None
        oldest = min(item.sampled_at for item in self.pending.values())
        if address in self.pending or record.sampled_at - oldest > self.coherence_window:
            # A duplicate or an overlong partial cycle means the previous
            # cycle is incomplete. Start from this fresh record; never carry
            # an old position into the next four-motor solve.
            self._restart(record)
            return None
        self.pending[address] = record
        if len(self.pending) != len(MOTOR_IDS):
            return None
        result = [self.pending[motor_id] for motor_id in MOTOR_IDS]
        self.pending = {}
        return result


def completed_feedback_cycles(assembler, records):
    """Keep every complete cycle, even if a drain ends in a partial cycle."""
    cycles = []
    for record in records:
        snapshot = assembler.add(record)
        if snapshot is not None:
            cycles.append(snapshot)
    return cycles


class RollingFourMotorFeedbackAssembler:
    """Pair the newest four records when independent streams drift in phase.

    During a moving grid the 0xAA command and four unsolicited 0x43 streams
    can make one motor's reply arrive after the next reply from another motor.
    The strict cycle assembler then discards an otherwise valid set. Keep the
    newest record per ID, require all four to be within the measured window,
    and emit at most one time-aligned snapshot per nominal feedback period.
    No stale record can be reused after the window expires.
    """

    __slots__ = (
        "coherence_window",
        "emit_interval",
        "latest",
        "last_emit_clock",
        "last_emitted_sampled_at",
    )

    def __init__(
        self,
        coherence_window: float = TRACKING_POSITION_COHERENCE_SECONDS,
        emit_interval: float = TIMED_POSITION_INTERVAL_MS / 1000.0,
    ) -> None:
        self.coherence_window = max(0.005, float(coherence_window))
        self.emit_interval = max(0.005, float(emit_interval))
        self.latest: dict[int, TimedFeedbackRecord] = {}
        self.last_emit_clock = 0.0
        self.last_emitted_sampled_at: dict[int, float] = {}

    def add(self, record: TimedFeedbackRecord) -> list[TimedFeedbackRecord] | None:
        address = int(record.address)
        if address not in MOTOR_IDS:
            return None
        self.latest[address] = record
        if set(self.latest) != set(MOTOR_IDS):
            return None
        newest = max(item.sampled_at for item in self.latest.values())
        oldest = min(item.sampled_at for item in self.latest.values())
        if newest - oldest > self.coherence_window:
            return None
        # This assembler is an asynchronous observer, not a command gate.
        # At 100 Hz the four unsolicited streams are deliberately phase-shifted;
        # requiring all four IDs to be newer than the previous batch suppresses
        # most valid snapshots whenever one stream arrives a few milliseconds
        # later.  Require at least one fresh record, then reuse the newest
        # coherent record for the other motors.  The coherence-window check
        # above still prevents stale data from entering the displayed pose.
        if not any(
            item.sampled_at > self.last_emitted_sampled_at.get(motor_id, -float("inf"))
            for motor_id, item in self.latest.items()
        ):
            return None
        # Records can be read in one USB chunk with device timestamps that are
        # several milliseconds apart. Throttle on host read time, not on the
        # newest device timestamp, otherwise phase drift suppresses valid
        # snapshots for an entire extra cycle.
        host_now = time.perf_counter()
        if host_now - self.last_emit_clock < self.emit_interval:
            return None
        self.last_emit_clock = host_now
        self.last_emitted_sampled_at = {
            motor_id: self.latest[motor_id].sampled_at for motor_id in MOTOR_IDS
        }
        return [self.latest[motor_id] for motor_id in MOTOR_IDS]


def valid_timed_feedback_43_packet(
    packet: bytes,
    address: int,
    position_history: dict[int, float] | None = None,
) -> bool:
    """Validate the documented X 0x43 fields before publishing a sample."""
    if not valid_reply(packet, address, TIMED_FEEDBACK_INFO_CODE, TIMED_FEEDBACK_FRAME_BYTES):
        return False
    if packet[2:4] != bytes((0x25, 0x0C)):
        return False
    if any(packet[index] not in (0, 1) for index in (14, 19, 22, 27, 32)):
        return False
    if direct.read_u16(packet, 4) > 60_000:
        return False
    if direct.read_u16(packet, 6) > TIMED_FEEDBACK_MAX_CURRENT_MA:
        return False
    if direct.read_u16(packet, 8) > TIMED_FEEDBACK_MAX_CURRENT_MA:
        return False
    if direct.read_u16(packet, 20) > TIMED_FEEDBACK_MAX_RPM_RAW:
        return False
    if packet[35] & ~TIMED_FEEDBACK_STATUS_MASK:
        return False
    raw_position = direct.read_u32(packet, 23) / 10.0
    if raw_position > TIMED_FEEDBACK_MAX_POSITION_DEG:
        return False
    position = -raw_position if packet[22] else raw_position
    if position_history is not None:
        previous = position_history.get(address)
        if previous is not None and abs(position - previous) > TIMED_FEEDBACK_MAX_POSITION_JUMP_DEG:
            return False
    return True


def resync_timed_feedback_buffer(buffer: bytearray) -> None:
    """Drop bytes up to the next possible fixed-length feedback header."""
    for offset in range(1, len(buffer) - 1):
        if buffer[offset] in MOTOR_IDS and buffer[offset + 1] in (0x36, TIMED_FEEDBACK_INFO_CODE):
            del buffer[:offset]
            return
    del buffer[:1]


def _consume_timed_position_buffer(
    buffer: bytearray,
    expected_reply: tuple[int, int, int] | None = None,
    position_history: dict[int, float] | None = None,
    parser_stats: dict[str, int] | None = None,
) -> tuple[list[TimedFeedbackRecord], bytes | None]:
    """Parse Y42 0x36/0x43 frames and optionally return an awaited reply.

    The normal live path uses 0x43.  It is important to parse that frame by
    its fixed 37-byte length before looking for 0x6B: the payload itself may
    contain 0x6B, so delimiter-only parsing would occasionally split a valid
    sample and make one motor appear offline.
    """

    records: list[TimedFeedbackRecord] = []
    response: bytes | None = None
    while len(buffer) >= 2:
        if buffer[0] in MOTOR_IDS and buffer[1] in (0x36, 0x43):
            command = int(buffer[1])
            frame_length = 8 if command == 0x36 else TIMED_FEEDBACK_FRAME_BYTES
            if len(buffer) < frame_length:
                break
            packet = bytes(buffer[:frame_length])
            if valid_reply(packet, buffer[0], command, frame_length):
                address = int(packet[0])
                if command == 0x36:
                    if not valid_reply(packet, buffer[0], command, frame_length) or packet[2] not in (0, 1):
                        if parser_stats is not None:
                            parser_stats["invalid_36"] = parser_stats.get("invalid_36", 0) + 1
                        resync_timed_feedback_buffer(buffer)
                        continue
                    raw = direct.read_u32(packet, 3) / 10.0
                    position = -raw if packet[2] else raw
                    record = TimedFeedbackRecord(
                        address=address,
                        position=position,
                        phase_current=None,
                        sampled_at=time.perf_counter(),
                        raw_packet_hex=packet.hex(),
                    )
                elif valid_timed_feedback_43_packet(packet, buffer[0], position_history):
                    # X firmware 0x43 response layout, manual V1.1 p.77-78:
                    # VBus[4:6], CBus[6:8], CPha[8:10], ... RPM[20:22],
                    # real position sign[22]+value[23:27], temp[33], flags[35].
                    raw_position = direct.read_u32(packet, 23) / 10.0
                    position = -raw_position if packet[22] else raw_position
                    raw_rpm = direct.read_u16(packet, 20) / 10.0
                    rpm = -raw_rpm if packet[19] else raw_rpm
                    record = TimedFeedbackRecord(
                        address=address,
                        position=position,
                        phase_current=direct.read_u16(packet, 8),
                        sampled_at=time.perf_counter(),
                        voltage=direct.read_u16(packet, 4) / 1000.0,
                        bus_current=direct.read_u16(packet, 6),
                        rpm=rpm,
                        temperature=packet[33],
                        flags=packet[35],
                        raw_packet_hex=packet.hex(),
                    )
                else:
                    if parser_stats is not None:
                        parser_stats["invalid_43"] = parser_stats.get("invalid_43", 0) + 1
                    resync_timed_feedback_buffer(buffer)
                    continue
                records.append(record)
                if parser_stats is not None:
                    stats_key = f"valid_{command:02x}"
                    parser_stats[stats_key] = parser_stats.get(stats_key, 0) + 1
                if position_history is not None:
                    position_history[address] = position
                del buffer[:frame_length]
                continue
            resync_timed_feedback_buffer(buffer)
            continue
        # In asynchronous mode, resync to the next fixed-length feedback
        # header before looking for 0x6B.  A stale ACK/partial frame may contain
        # 0x6B and must not swallow the next motor's 0x43 packet.
        if expected_reply is None:
            header = next(
                (
                    offset
                    for offset in range(1, len(buffer) - 1)
                    if buffer[offset] in MOTOR_IDS
                    and buffer[offset + 1] in (0x36, TIMED_FEEDBACK_INFO_CODE)
                ),
                -1,
            )
            if header >= 0:
                del buffer[:header]
                continue
        # ACKs and safety-query replies are variable length but always end in
        # 0x6B. Fixed-length feedback payloads never enter this branch because
        # 0x36/0x43 frames are parsed at their exact lengths first.
        end = buffer.find(bytes((direct.FRAME_END,)))
        if end < 0:
            del buffer[:-1]
            break
        packet = bytes(buffer[: end + 1])
        del buffer[: end + 1]
        if expected_reply is not None:
            address, command, minimum = expected_reply
            if valid_reply(packet, address, command, minimum):
                response = packet
                break
    return records, response


def read_timed_position_records(
    connection: object,
    buffer: bytearray,
    timeout: float = 0.02,
    position_history: dict[int, float] | None = None,
    parser_stats: dict[str, int] | None = None,
) -> list[TimedFeedbackRecord]:
    """Drain asynchronous timed-return frames as decoded feedback records."""

    records: list[TimedFeedbackRecord] = []
    if timeout <= 0.0:
        # The trajectory clock must never wait for the next unsolicited byte.
        # Drain only what is already buffered; a later 100 Hz tick will consume
        # the next frame.  This keeps feedback visible without stealing time
        # from the four-motor 0xAA command schedule.
        while True:
            waiting = int(getattr(connection, "in_waiting", 0) or 0)
            if waiting <= 0:
                break
            chunk = connection.read(min(256, waiting))
            if not chunk:
                break
            buffer.extend(chunk)
            parsed, _ = _consume_timed_position_buffer(
                buffer,
                position_history=position_history,
                parser_stats=parser_stats,
            )
            records.extend(parsed)
        preserve_raw_timed_feedback(records)
        return records
    deadline = time.perf_counter() + max(0.001, timeout)
    while time.perf_counter() < deadline:
        waiting = int(getattr(connection, "in_waiting", 0) or 0)
        chunk = connection.read(min(256, waiting)) if waiting else connection.read(1)
        if chunk:
            buffer.extend(chunk)
        parsed, _ = _consume_timed_position_buffer(
            buffer,
            position_history=position_history,
            parser_stats=parser_stats,
        )
        records.extend(parsed)
        if not chunk and time.perf_counter() >= deadline:
            break
    preserve_raw_timed_feedback(records)
    return records


def preserve_raw_timed_feedback(items: list[TimedFeedbackRecord]) -> None:
    """Queue every valid asynchronous frame in the append-only run record."""

    if not items:
        return
    manual_test_emit(
        "timed_feedback_frames",
        record_channel="raw_serial",
        samples=[
            {
                "address": item.address,
                "position_deg": item.position,
                "phase_current_ma": item.phase_current,
                "sampled_monotonic_s": item.sampled_at,
                "voltage_v": item.voltage,
                "bus_current_ma": item.bus_current,
                "rpm": item.rpm,
                "temperature_c": item.temperature,
                "flags": item.flags,
                "raw_packet_hex": item.raw_packet_hex,
            }
            for item in items
        ],
    )


class AsyncTimedFeedbackReader:
    """Continuously receive 0x43 frames without touching the command clock.

    PySerial supports one reader and one writer on the same Windows handle.  A
    dedicated blocking reader is important here: querying ``in_waiting`` on the
    CH340 from the 100 Hz motion thread was measured at roughly one Windows
    scheduler quantum and collapsed command transmission to about 65 Hz.
    """

    def __init__(self, connection: object, *, on_record: object = None) -> None:
        if on_record is not None and not callable(on_record):
            raise TypeError("原始反馈回调必须可调用")
        self.connection = connection
        self.on_record = on_record
        self.original_timeout = getattr(connection, "timeout", 0.001)
        self.buffer = bytearray()
        self.position_history: dict[int, float] = {}
        self.parser_stats: dict[str, int] = {}
        self.records: queue.Queue[TimedFeedbackRecord] = queue.Queue()
        self.stop_event = threading.Event()
        self.stop_lock = threading.Lock()
        self.stopped = False
        self.failure: BaseException | None = None
        self.thread = threading.Thread(
            target=self._run,
            name="y42-trajectory-feedback",
            daemon=True,
        )

    def _run(self) -> None:
        set_current_thread_priority(WINDOWS_THREAD_PRIORITY_BELOW_NORMAL)
        try:
            # Drain a larger USB batch so the staggered four-motor stream can
            # be reassembled after one collided frame. A dedicated reader can
            # afford this 10 ms timeout without competing with the 100 Hz
            # command clock; the old 37-byte short read left recovery split
            # across too many parser passes and cut complete batches to a few
            # hertz.
            self.connection.timeout = 0.010
            while not self.stop_event.is_set():
                chunk = self.connection.read(512)
                if not chunk:
                    continue
                self.buffer.extend(chunk)
                parsed, _ = _consume_timed_position_buffer(
                    self.buffer,
                    position_history=self.position_history,
                    parser_stats=self.parser_stats,
                )
                if not parsed:
                    continue
                preserve_raw_timed_feedback(parsed)
                for record in parsed:
                    self.records.put_nowait(record)
                    # Preserve the full raw batch and the rejected record before
                    # invoking protection. Callback code must never write serial;
                    # the owning writer observes the latched error/STOP request.
                    if self.on_record is not None:
                        self.on_record(record)
        except BaseException as exc:  # surfaced in the motion thread
            if self.failure is None:
                self.failure = exc
            self.stop_event.set()

    def start(self) -> None:
        self.thread.start()

    def drain(self) -> list[TimedFeedbackRecord]:
        items: list[TimedFeedbackRecord] = []
        while True:
            try:
                items.append(self.records.get_nowait())
            except queue.Empty:
                break
        return items

    def check(self) -> None:
        if self.failure is not None:
            raise RuntimeError(f"轨迹异步反馈线程失败：{self.failure}") from self.failure

    def stop(self) -> list[TimedFeedbackRecord]:
        # The motion worker can leave its serial context before this cleanup
        # runs when an external STOP arrives.  pyserial's Windows backend then
        # clears ``_overlapped_read`` while the reader is still blocked, which
        # surfaces as ``byref(None)``.  Stop is therefore idempotent and treats
        # a closed handle as an already completed reader shutdown.
        with self.stop_lock:
            if not self.stopped:
                self.stopped = True
                self.stop_event.set()
        self.thread.join(timeout=1.0)
        try:
            if bool(getattr(self.connection, "is_open", False)):
                self.connection.timeout = self.original_timeout
        except Exception:
            pass
        if self.thread.is_alive():
            raise RuntimeError("轨迹异步反馈线程未能在 1 秒内停止")
        try:
            self.check()
        except RuntimeError as exc:
            # A STOP can close the pyserial handle before the outer finally
            # reaches this method.  Do not turn that expected teardown race
            # into a second trajectory fault or a false recalibration demand.
            if not self.stop_event.is_set() or "byref(None)" not in str(exc):
                raise
        return self.drain()


class ObservationRawRecordGuard:
    """Latch the first unsafe original 0x43 record; never command a motor."""

    def __init__(self, initial_positions, stop_event, *, emit=None):
        self.initial_positions = tuple(float(value) for value in initial_positions)
        if len(self.initial_positions) != 4 or not all(math.isfinite(value) for value in self.initial_positions):
            raise ValueError("原始记录保护需要四台有限的入口角度")
        self.stop_event = stop_event
        self.emit = emit
        self.failure: dict | None = None
        self.require_enabled = True

    def _trip(self, reason, record):
        if self.failure is None:
            self.failure = {"reason": reason, "detected_at": time.perf_counter(),
                "clock_source": "host_receive_not_device",
                "record": {name: getattr(record, name, None) for name in
                    ("address", "sampled_at", "position", "rpm", "phase_current",
                     "temperature", "flags", "raw_packet_hex")}}
            # Publish a complete, immutable-in-use fault before signaling STOP.
            self.stop_event.set()
            if self.emit is not None:
                try:
                    self.emit("torque_observation_raw_guard_latched", **self.failure)
                except Exception:
                    # Raw records were already preserved by the reader. A
                    # secondary diagnostic failure must not cancel protection.
                    pass
        self.stop_event.set()
        raise RuntimeError(self.failure["reason"])

    def __call__(self, record):
        if self.failure is not None:
            self._trip(self.failure["reason"], record)
        address = getattr(record, "address", None)
        if not isinstance(address, int) or isinstance(address, bool) or address not in (1, 2, 3, 4):
            self._trip("原始0x43记录电机编号缺失或无效", record)
        values = {}
        for field in ("position", "rpm", "phase_current", "temperature", "flags", "sampled_at"):
            value = getattr(record, field, None)
            try:
                finite = value is not None and math.isfinite(float(value))
            except (TypeError, ValueError, OverflowError):
                finite = False
            if not finite:
                self._trip(f"M{address}原始0x43记录{field}缺失或非有限数", record)
            values[field] = float(value)
        flags = int(values["flags"])
        if flags != values["flags"] or flags & ~0x3F:
            self._trip(f"M{address}原始0x43状态字无效", record)
        if flags & 0x08:
            self._trip(f"M{address}原始0x43驱动保护已触发", record)
        if self.require_enabled and not flags & 1:
            self._trip(f"M{address}原始0x43意外失能", record)
        if abs(values["rpm"]) > 25.0:
            self._trip(f"M{address}原始0x43速度{values['rpm']:g}RPM超过25RPM观察保护", record)
        if abs(values["phase_current"]) > 400.0:
            self._trip(f"M{address}原始0x43电流超过400mA观察保护", record)
        if values["temperature"] >= 45.0:
            self._trip(f"M{address}原始0x43温度达到45°C观察保护", record)
        if abs(values["position"] - self.initial_positions[address - 1]) > 90.0:
            self._trip(f"M{address}原始0x43相对入口位移超过90°观察保护", record)


def timed_snapshot_telemetry(
    snapshot: list[TimedFeedbackRecord] | tuple[TimedFeedbackRecord, ...],
) -> list[direct.Telemetry]:
    """Convert one coherent four-motor 0x43 cycle to calibration telemetry.

    The four frames are serialized on RS485, so use the measured RPM to
    project the older positions to the newest frame timestamp before solving
    geometry.  Phase current, temperature and flags remain the values from
    the same physical frame; no cached query result is mixed in.
    """
    if len(snapshot) != len(MOTOR_IDS):
        return []
    by_address = {int(item.address): item for item in snapshot}
    if set(by_address) != set(MOTOR_IDS):
        return []
    aligned = time_aligned_feedback_positions(snapshot)
    if len(aligned) != len(MOTOR_IDS):
        return []
    values: list[direct.Telemetry] = []
    for index, address in enumerate(MOTOR_IDS):
        item = by_address[address]
        values.append(
            direct.Telemetry(
                address=address,
                voltage=item.voltage,
                bus_current=item.bus_current,
                phase_current=item.phase_current,
                rpm=item.rpm,
                position=float(aligned[index]),
                temperature=item.temperature,
                flags=item.flags,
            )
        )
    return values


def read_timed_feedback_snapshots(
    connection: object,
    buffer: bytearray,
    assembler: FourMotorFeedbackAssembler,
    position_history: dict[int, float],
    timeout: float = 0.01,
    parser_stats: dict[str, int] | None = None,
) -> list[tuple[list[direct.Telemetry], float]]:
    """Drain complete, time-coherent 0x43 snapshots without a query round-trip."""
    records = read_timed_position_records(
        connection,
        buffer,
        timeout=max(0.0, float(timeout)),
        position_history=position_history,
        parser_stats=parser_stats,
    )
    snapshots: list[tuple[list[direct.Telemetry], float]] = []
    for record in records:
        snapshot = assembler.add(record)
        if snapshot is None:
            continue
        values = timed_snapshot_telemetry(snapshot)
        if len(values) == len(MOTOR_IDS) and telemetry_ready_for_calibration(values):
            update_telemetry(values)
            sampled_at = max(float(item.sampled_at) for item in snapshot)
            snapshots.append((values, sampled_at))
    return snapshots


def wait_for_timed_absolute_target(
    connection: object,
    targets: list[float],
    current_limits: list[int],
    label: str,
    stream_buffer: bytearray,
    stream_assembler: FourMotorFeedbackAssembler,
    position_history: dict[int, float],
    timeout: float = 6.0,
    rpm: float = GRID_START_RPM,
    tolerance_deg: float = GRID_POSITION_TOLERANCE_DEG,
    feedback_callback: object = None,
    xy_target: tuple[float, float] | None = None,
    xy_tolerance: float = TRAJECTORY_XY_SETTLE_TOLERANCE,
    command_interval: float = TRAJECTORY_INTERVAL,
    parser_stats: dict[str, int] | None = None,
) -> list[float]:
    """Confirm an absolute move using the 100Hz aggregate feedback stream.

    Grid calibration used to call ``read_all_reliable`` here.  That performs
    28 sequential register queries per pass, which both starved the bus and
    made a lagging motor look frozen.  Keep the four-motor 0xAA target alive at
    100Hz while consuming complete 0x43 cycles; a lagging motor receives only
    one bounded promotion toward the 2A motion ceiling, never an unbounded jump.
    """
    deadline = time.monotonic() + max(0.5, float(timeout))
    limits = normalized_trajectory_current_limits(current_limits)
    boosted_motors: set[int] = set()
    last_positions: list[float] | None = None
    last_error: float | None = None
    started = time.perf_counter()
    command_period = max(0.005, float(command_interval))
    next_command = started
    while time.monotonic() < deadline:
        if STOP_EVENT.is_set():
            raise RuntimeError("用户急停")
        now = time.monotonic()
        if now >= next_command:
            send_fast(
                connection,
                four_motor_position_frame(
                    targets,
                    [max(1.0, min(TRAJECTORY_START_RPM, float(rpm)))] * len(MOTOR_IDS),
                    limits,
                ),
            )
            next_command = now + command_period
        snapshots = read_timed_feedback_snapshots(
            connection,
            stream_buffer,
            stream_assembler,
            position_history,
            timeout=min(TIMED_FEEDBACK_READ_WINDOW_SECONDS, max(0.001, deadline - time.monotonic())),
            parser_stats=parser_stats,
        )
        for values, sampled_at in snapshots:
            safety = grid_safety_error(values, limits)
            if safety:
                raise RuntimeError(f"{label}：{safety}")
            last_positions = [float(value.position) for value in values]
            errors = [abs(actual - target) for actual, target in zip(last_positions, targets)]
            last_error = max(errors)
            feedback_adjusted = False
            if callable(feedback_callback):
                feedback_adjusted = bool(feedback_callback(values, last_error, limits, sampled_at))
                if feedback_adjusted:
                    # The callback may have moved the local absolute target by
                    # one small trim step. Re-evaluate against that new target
                    # before declaring the node reached.
                    last_error = max(
                        abs(float(value.position) - target)
                        for value, target in zip(values, targets)
                    )
            if last_error <= max(0.5, float(tolerance_deg)):
                append_process_log(
                    "trajectory_absolute_target_reached",
                    shape=label,
                    target_positions=targets,
                    actual_positions=last_positions,
                    max_error_deg=round(last_error, 3),
                )
                return last_positions
            if xy_target is not None and all(
                abs(float(value.rpm or 0.0)) <= 15.0 for value in values
            ):
                estimate = position_to_xy(last_positions)
                if estimate is not None and math.hypot(
                    estimate[0] - float(xy_target[0]),
                    estimate[1] - float(xy_target[1]),
                ) <= max(1.0, float(xy_tolerance)):
                    append_process_log(
                        "trajectory_absolute_target_near_xy",
                        shape=label,
                        target_positions=targets,
                        actual_positions=last_positions,
                        target_xy=list(xy_target),
                        solved_xy=[round(float(value), 3) for value in estimate],
                        max_error_deg=round(last_error, 3),
                    )
                    return last_positions
            if time.monotonic() - started >= 0.8:
                candidates = [index for index in range(len(errors)) if index not in boosted_motors]
                lagging = max(candidates, key=errors.__getitem__) if candidates else None
                if lagging is not None and errors[lagging] > max(0.5, float(tolerance_deg)):
                    boosted = min(
                        GRID_LAGGING_MOTOR_CURRENT_LIMIT_MA,
                        limits[lagging] + GRID_MOTION_CURRENT_HEADROOM_MA,
                    )
                    boosted_motors.add(lagging)
                    if boosted > limits[lagging]:
                        limits[lagging] = boosted
                        current_limits[:] = limits
                        append_process_log(
                            "trajectory_absolute_target_boost",
                            shape=label,
                            lagging_motor=lagging + 1,
                            max_error_deg=round(last_error, 2),
                            current_limits_ma=limits,
                        )
                        send_fast(
                            connection,
                            four_motor_position_frame(
                                targets,
                                [max(1.0, min(TRAJECTORY_START_RPM, float(rpm)))] * len(MOTOR_IDS),
                                limits,
                            ),
                        )
        if not snapshots:
            # Yield without adding a blocking serial query. The stream parser
            # will pick up the next four-ID cycle on the next 10ms tick.
            time.sleep(0.001)
    append_process_log(
        "trajectory_absolute_target_timeout",
        shape=label,
        target_positions=targets,
        actual_positions=last_positions,
        max_error_deg=round(last_error or 0.0, 3),
        current_limits_ma=limits,
    )
    raise RuntimeError(
        f"{label}：绝对位置未到位，最大误差 {last_error:.1f}°（门槛 {float(tolerance_deg):.1f}°）；已停止继续采样，"
        "避免把未到位点当成校准数据"
    )


def read_timed_safety_reply(
    connection: object,
    buffer: bytearray,
    address: int,
    command: int,
    minimum: int,
    timeout: float = 0.08,
) -> tuple[list[TimedFeedbackRecord], bytes | None]:
    """Read one safety reply without stopping the four asynchronous streams."""

    send_fast(connection, direct.frame(address, command, direct.FRAME_END))
    records: list[tuple[int, float, float]] = []
    deadline = time.perf_counter() + max(0.01, timeout)
    while time.perf_counter() < deadline:
        waiting = int(getattr(connection, "in_waiting", 0) or 0)
        chunk = connection.read(min(256, waiting)) if waiting else connection.read(1)
        if chunk:
            buffer.extend(chunk)
        parsed, response = _consume_timed_position_buffer(buffer, (address, command, minimum))
        records.extend(parsed)
        if response is not None:
            return records, response
    return records, None


def long_stability_test(port: str, baud: int, duration_s: float = 15.0) -> dict:
    """Run the real 15 s bus test used by the web diagnostics button.

    Phase 1 measures the actual 0xAA four-motor write clock with all motors
    disabled and unchanged targets. Phase 2 uses the Y42 0x11 timed-return
    command with X 0x43. Each motor streams a 37-byte frame every 10 ms at
    921600 baud; that
    one frame contains both real position and phase current, so the four-motor
    dual-feedback clock is measured from real frames instead of blocking
    request/response round trips.
    """

    duration_s = max(5.0, min(120.0, float(duration_s)))
    write_stamps = TimingAccumulator()
    feedback_stamps = TimingAccumulator()
    feedback_spans = RunningStats()
    valid_replies = {address: 0 for address in MOTOR_IDS}
    total_replies = {address: 0 for address in MOTOR_IDS}
    current_samples = {address: RunningStats() for address in MOTOR_IDS}
    shutdown_ok = False
    # Always clear a possible stream left by a previous run before measuring.
    timed_stream_stopped = False
    write_stats: dict = {}
    feedback_stats: dict = {}
    feedback_quality_ok = False
    model_context = calibration_model_context()
    feedback_interval_ms = motion_feedback_interval_ms(baud)
    feedback_hz = 1000.0 / feedback_interval_ms
    append_process_log(
        "long_stability_start",
        port=port,
        baud=baud,
        duration_s=duration_s,
        feedback_interval_ms=feedback_interval_ms,
        feedback_target_hz=feedback_hz,
    )
    try:
        with SERIAL_LOCK, direct.open_serial(port, baud) as connection:
            timed_stream_stopped = stop_timed_position_stream(connection)
            # Establish a safe, stationary baseline.  The test never enables
            # a motor and the unchanged targets are only used to exercise the
            # same 61-byte packing/write path as the trajectory worker.
            baseline_disable = disable_all(connection)
            if not all(item.get("accepted") for item in baseline_disable):
                # If the first clear collided with a late feedback frame, clear
                # once more before judging the STOP/DISABLE baseline.
                timed_stream_stopped = stop_timed_position_stream(connection)
                baseline_disable = disable_all(connection)
            if not all(item.get("accepted") for item in baseline_disable):
                raise RuntimeError("长稳定性测试前无法确认四台电机均已失能")
            baseline = read_all_reliable(connection, attempts=2)
            targets = [telemetry.position for telemetry in baseline]
            if len(targets) != len(MOTOR_IDS) or any(position is None for position in targets):
                raise RuntimeError("长稳定性测试前四台位置回读不完整")
            frame = four_motor_position_frame(
                [float(position) for position in targets],
                [1.0 for _ in MOTOR_IDS],
                [300 for _ in MOTOR_IDS],
            )

            timer_resolution = set_high_resolution_timer(True)
            try:
                interval = TRAJECTORY_INTERVAL
                started = time.perf_counter()
                deadline = started + duration_s
                next_tick = started
                while True:
                    remaining = next_tick - time.perf_counter()
                    if remaining > 0.0:
                        wait_tracking_deadline(next_tick)
                    now = time.perf_counter()
                    if now >= deadline:
                        break
                    send_fast(connection, frame)
                    write_stamps.add(time.perf_counter())
                    next_tick += interval
                    if next_tick < time.perf_counter() - interval:
                        next_tick = time.perf_counter() + interval
                write_stats = _timing_stats(write_stamps, started, time.perf_counter(), TRAJECTORY_HZ)
            finally:
                if timer_resolution:
                    set_high_resolution_timer(False)

            # Read-only phase: use one asynchronous X 0x43 stream per motor.
            # Each 37-byte frame contains that motor's real position and phase
            # current, so this measures the actual dual-feedback path rather
            # than combining position frames with stale cached current.
            if baud < TRAJECTORY_LIVE_FEEDBACK_MIN_BAUD:
                raise RuntimeError(
                    f"0x43 四电机位置+相电流实时流需要更高波特率（当前 {baud}，建议 ≥ {TRAJECTORY_LIVE_FEEDBACK_MIN_BAUD}）"
                )
            start_timed_feedback_stream(connection, feedback_interval_ms, TIMED_FEEDBACK_INFO_CODE)
            feedback_interval_ms = int(getattr(connection, "_y42_feedback_interval_ms", feedback_interval_ms))
            feedback_hz = 1000.0 / max(1, feedback_interval_ms)
            timed_stream_stopped = False
            started = time.perf_counter()
            deadline = started + duration_s
            stream_buffer = bytearray()
            stream_assembler = FourMotorFeedbackAssembler(timed_feedback_coherence_window(baud))
            while time.perf_counter() < deadline:
                remaining = deadline - time.perf_counter()
                records = read_timed_position_records(
                    connection,
                    stream_buffer,
                    timeout=min(0.03, max(0.001, remaining)),
                )
                for record in records:
                    address = record.address
                    sampled_at = record.sampled_at
                    total_replies[address] += 1
                    valid_replies[address] += 1
                    if record.phase_current is not None:
                        current_samples[address].add(record.phase_current)
                    snapshot = stream_assembler.add(record)
                    if snapshot is not None:
                        batch_times = [item.sampled_at for item in snapshot]
                        span = max(batch_times) - min(batch_times)
                        feedback_stamps.add(max(batch_times))
                        feedback_spans.add(span)
                        raw_positions = [float(item.position) for item in snapshot]
                        positions = list(time_aligned_feedback_positions(snapshot))
                        append_process_log(
                            "long_stability_feedback_batch",
                                    positions_deg=[round(value, 3) for value in positions],
                            raw_positions_deg=[round(value, 3) for value in raw_positions],
                            relative_rope_lengths_mm=calibration_relative_rope_lengths(positions),
                            phase_current_ma=[
                                round(float(item.phase_current), 3) if item.phase_current is not None else None
                                for item in snapshot
                            ],
                            sampled_at=round(max(batch_times), 6),
                            sample_span_ms=round(span * 1000.0, 3),
                            model_family_key=model_context.get("model_family_key"),
                        )
            # Stop periodic-return settings before ordinary acknowledged
            # STOP/DISABLE commands reuse the half-duplex line.
            timed_stream_stopped = stop_timed_position_stream(connection)
            expected_per_motor = max(1, round(duration_s * feedback_hz))
            # A missing/garbled frame is not yielded by the parser. Use the
            # device-side expected count as the denominator so the reported
            # success rate cannot become 100% merely because only valid
            # records were counted.
            for address in MOTOR_IDS:
                total_replies[address] = expected_per_motor
            feedback_window_start = feedback_stamps.first if feedback_stamps.first is not None else started
            feedback_window_end = feedback_stamps.last if feedback_stamps.last is not None else time.perf_counter()
            feedback_stats = _timing_stats(
                feedback_stamps,
                feedback_window_start,
                feedback_window_end,
                feedback_hz,
            )
            feedback_stats["complete_batches"] = feedback_stamps.count
            feedback_stats["expected_complete_batches"] = expected_per_motor
            feedback_stats["complete_batch_success_rate"] = round(
                min(100.0, feedback_stamps.count / max(1, expected_per_motor) * 100.0),
                3,
            )
            feedback_stats["mode"] = "0x11 定时 0x43 合并回传（位置+相电流）"
            feedback_stats["info_code"] = "0x43"
            feedback_stats["frame_bytes"] = TIMED_FEEDBACK_FRAME_BYTES
            feedback_stats["interval_ms"] = feedback_interval_ms
            feedback_stats["expected_frames_per_motor"] = expected_per_motor
            feedback_stats["received_frames_per_motor"] = {
                str(address): valid_replies[address] for address in MOTOR_IDS
            }
            feedback_stats["coherence_window_ms"] = timed_feedback_coherence_window(baud) * 1000.0
            feedback_stats["batch_span_ms"] = {
                "min": round(feedback_spans.minimum * 1000.0, 3) if feedback_spans.minimum is not None else None,
                "avg": round((feedback_spans.average or 0.0) * 1000.0, 3) if feedback_spans.count else None,
                "max": round(feedback_spans.maximum * 1000.0, 3) if feedback_spans.maximum is not None else None,
            }
            feedback_stats["current_samples_per_motor"] = {
                str(address): current_samples[address].count for address in MOTOR_IDS
            }
            feedback_stats["current_rate_hz_per_motor"] = {
                str(address): round(current_samples[address].count / max(0.001, duration_s), 2)
                for address in MOTOR_IDS
            }
            feedback_stats["current_range_ma"] = {
                str(address): {
                    "min": round(current_samples[address].minimum, 3) if current_samples[address].minimum is not None else None,
                    "avg": round(current_samples[address].average, 1) if current_samples[address].average is not None else None,
                    "max": round(current_samples[address].maximum, 3) if current_samples[address].maximum is not None else None,
                }
                for address in MOTOR_IDS
            }
            feedback_quality_ok = (
                feedback_stats["complete_batch_success_rate"] >= 99.9
                and all(
                    valid_replies[address] / max(1, expected_per_motor) * 100.0 >= 99.9
                    for address in MOTOR_IDS
                )
            )
            shutdown = disable_all(connection)
            shutdown_ok = timed_stream_stopped and all(item.get("accepted") for item in shutdown)
    finally:
        # If an exception interrupted the timed-return phase, the original
        # handle is already leaving its with-block. Reopen the bus once to
        # explicitly clear 0x11 on every motor before the normal safety
        # STOP/DISABLE recovery; closing a serial handle alone must not leave
        # periodic replies running in the drivers.
        if not timed_stream_stopped:
            try:
                with SERIAL_LOCK, direct.open_serial(port, baud) as recovery_connection:
                    timed_stream_stopped = stop_timed_position_stream(recovery_connection)
            except Exception:
                timed_stream_stopped = False
        if not shutdown_ok:
            recovery = disable_all_with_reconnect(port, baud, announce=False)
            shutdown_ok = timed_stream_stopped and bool(recovery.get("ok"))

    result = {
        "ok": bool(write_stats.get("frames")) and feedback_quality_ok and shutdown_ok,
        "action": "stability-long",
        "port": port,
        "baud": baud,
        "duration_s_each_phase": duration_s,
        "motors_disabled_after_test": shutdown_ok,
        "command_write_hz": write_stats,
        "command_write_target_hz": TRAJECTORY_HZ,
        "combined_feedback_0x43": feedback_stats,
        "reply_success": {
            str(address): {
                "valid": valid_replies[address],
                "total": total_replies[address],
                "success_rate": round(
                    min(100.0, valid_replies[address] / max(1, total_replies[address]) * 100.0),
                    3,
                ),
            }
            for address in MOTOR_IDS
        },
        "note": f"控制按真实总线统计（目标 {TRAJECTORY_HZ:.0f}Hz）；反馈使用手册 0x11/0x43，{feedback_interval_ms}ms/台（目标 {feedback_hz:.1f}Hz），每帧同时包含实时位置和相电流，不使用缓存电流冒充新采样。",
    }
    with STATE_LOCK:
        STATE["last_stability"] = copy.deepcopy(result)
    append_process_log("long_stability_complete", **result)
    return result


def sequential_position_transport_test(port: str, baud: int, duration_s: float = 3.0) -> dict:
    """Compare aggregate motion writes with one-motor transport on a safe datum.

    The test keeps all drivers disabled and repeatedly commands their current
    encoder positions, so it measures the RS485/USB scheduling cost without
    moving the mechanism.  The single-motor packet is the documented X 0xFD
    absolute-position command.  Two variants are measured: four TX-only
    packets (the only form that could plausibly fit a motion clock) and four
    request/response transactions (the user's proposed "逐台收发" form).
    """
    duration_s = max(2.0, min(15.0, float(duration_s)))
    target_hz = TRAJECTORY_HZ
    aggregate_cycles = TimingAccumulator()
    sequential_tx_cycles = TimingAccumulator()
    sequential_ack_cycles = TimingAccumulator()
    sequential_tx_spans = RunningStats()
    sequential_ack_spans = RunningStats()
    ack_valid = {address: 0 for address in MOTOR_IDS}
    ack_total = {address: 0 for address in MOTOR_IDS}
    phase_windows: dict[str, tuple[float, float]] = {}
    baseline: list[Telemetry] = []
    try:
        with SERIAL_LOCK, direct.open_serial(port, baud) as connection:
            if not stop_timed_position_stream(connection):
                raise RuntimeError("逐台通信对照测试前无法清理旧的定时反馈流")
            disabled = disable_all(connection)
            if not all(item.get("accepted") for item in disabled):
                disabled = disable_all(connection)
            if not all(item.get("accepted") for item in disabled):
                raise RuntimeError("逐台通信对照测试前无法确认四台电机均已失能")
            baseline = read_all_reliable(connection, attempts=2)
            targets = [item.position for item in baseline]
            if len(targets) != len(MOTOR_IDS) or any(value is None for value in targets):
                raise RuntimeError("逐台通信对照测试前四台位置回读不完整")
            numeric_targets = [float(value) for value in targets]
            aggregate = four_motor_position_frame(
                numeric_targets,
                [1.0 for _ in MOTOR_IDS],
                [300 for _ in MOTOR_IDS],
            )
            singles = [
                direct.position_frame(
                    address,
                    absolute_position_direction(index, target),
                    1000.0,
                    65535,
                    abs(target),
                    1,
                )
                for index, (address, target) in enumerate(zip(MOTOR_IDS, numeric_targets))
            ]

            def run_aggregate() -> None:
                started = time.perf_counter()
                deadline = started + duration_s
                next_tick = started
                while time.perf_counter() < deadline:
                    wait_tracking_deadline(next_tick)
                    if time.perf_counter() >= deadline:
                        break
                    send_fast(connection, aggregate)
                    aggregate_cycles.add(time.perf_counter())
                    next_tick += 1.0 / target_hz
                    if next_tick < time.perf_counter() - 1.0 / target_hz:
                        next_tick = time.perf_counter() + 1.0 / target_hz
                phase_windows["aggregate"] = (started, time.perf_counter())

            def run_sequential_tx() -> None:
                started = time.perf_counter()
                deadline = started + duration_s
                next_tick = started
                while time.perf_counter() < deadline:
                    wait_tracking_deadline(next_tick)
                    if time.perf_counter() >= deadline:
                        break
                    cycle_started = time.perf_counter()
                    for packet in singles:
                        send_fast(connection, packet)
                    cycle_finished = time.perf_counter()
                    sequential_tx_cycles.add(cycle_finished)
                    sequential_tx_spans.add(cycle_finished - cycle_started)
                    next_tick += 1.0 / target_hz
                    if next_tick < time.perf_counter() - 1.0 / target_hz:
                        next_tick = time.perf_counter() + 1.0 / target_hz
                phase_windows["tx"] = (started, time.perf_counter())

            def run_sequential_ack() -> None:
                started = time.perf_counter()
                deadline = started + duration_s
                next_tick = started
                while time.perf_counter() < deadline:
                    wait_tracking_deadline(next_tick)
                    if time.perf_counter() >= deadline:
                        break
                    cycle_started = time.perf_counter()
                    for address, packet in zip(MOTOR_IDS, singles):
                        ack_total[address] += 1
                        reply = direct.transact(
                            connection,
                            packet,
                            first_byte_timeout=0.02,
                            inter_byte_quiet=0.001,
                        )
                        if direct.command_accepted(reply, address, 0xFD):
                            ack_valid[address] += 1
                    cycle_finished = time.perf_counter()
                    sequential_ack_cycles.add(cycle_finished)
                    sequential_ack_spans.add(cycle_finished - cycle_started)
                    next_tick += 1.0 / target_hz
                    if next_tick < time.perf_counter() - 1.0 / target_hz:
                        next_tick = time.perf_counter() + 1.0 / target_hz
                phase_windows["ack"] = (started, time.perf_counter())

            timer_resolution = set_high_resolution_timer(True)
            try:
                run_aggregate()
                run_sequential_tx()
                run_sequential_ack()
            finally:
                if timer_resolution:
                    set_high_resolution_timer(False)
            shutdown = disable_all(connection)
            motors_disabled = all(item.get("accepted") for item in shutdown)
    finally:
        motors_disabled = locals().get("motors_disabled", False)
        if not motors_disabled:
            try:
                recovery = disable_all_with_reconnect(port, baud, announce=False)
                motors_disabled = bool(recovery.get("ok"))
            except Exception:
                motors_disabled = False

    aggregate_window = phase_windows.get("aggregate", (0.0, 0.0))
    tx_window = phase_windows.get("tx", (0.0, 0.0))
    ack_window = phase_windows.get("ack", (0.0, 0.0))
    aggregate_stats = _timing_stats(
        aggregate_cycles,
        aggregate_window[0],
        aggregate_window[1],
        target_hz,
    )
    tx_stats = _timing_stats(
        sequential_tx_cycles,
        tx_window[0],
        tx_window[1],
        target_hz,
    )
    ack_stats = _timing_stats(
        sequential_ack_cycles,
        ack_window[0],
        ack_window[1],
        target_hz,
    )
    result = {
        "ok": bool(motors_disabled and aggregate_stats.get("frames") and tx_stats.get("frames")),
        "action": "sequential-position-transport-test",
        "port": port,
        "baud": baud,
        "duration_s_each_phase": duration_s,
        "motors_disabled_after_test": motors_disabled,
        "aggregate_0xaa_tx_only": aggregate_stats,
        "sequential_0xfd_tx_only": {
            **tx_stats,
            "cycle_wire_span_ms": {
                "min": round(sequential_tx_spans.minimum * 1000.0, 3) if sequential_tx_spans.minimum is not None else None,
                "avg": round((sequential_tx_spans.average or 0.0) * 1000.0, 3) if sequential_tx_spans.count else None,
                "max": round(sequential_tx_spans.maximum * 1000.0, 3) if sequential_tx_spans.maximum is not None else None,
            },
        },
        "sequential_0xfd_request_response": {
            **ack_stats,
            "cycle_wire_span_ms": {
                "min": round(sequential_ack_spans.minimum * 1000.0, 3) if sequential_ack_spans.minimum is not None else None,
                "avg": round((sequential_ack_spans.average or 0.0) * 1000.0, 3) if sequential_ack_spans.count else None,
                "max": round(sequential_ack_spans.maximum * 1000.0, 3) if sequential_ack_spans.maximum is not None else None,
            },
            "ack_success": {
                str(address): {
                    "valid": ack_valid[address],
                    "total": ack_total[address],
                    "success_rate": round(ack_valid[address] / max(1, ack_total[address]) * 100.0, 3),
                }
                for address in MOTOR_IDS
            },
        },
        "note": "所有阶段都对当前编码器目标发送且四台保持失能；逐台收发只用于测量通信代价，不用于运动控制。",
    }
    append_process_log("sequential_position_transport_complete", **result)
    with STATE_LOCK:
        STATE["last_sequential_transport_test"] = copy.deepcopy(result)
    return result


def baud_sweep(port: str, bauds: list[int]) -> dict:
    results = []
    with SERIAL_LOCK:
        for baud in bauds:
            row = {"baud": baud, "valid": [], "replies": {}}
            try:
                with direct.open_serial(port, baud) as connection:
                    for address in MOTOR_IDS:
                        reply = direct.transact(connection, direct.frame(address, 0x3A, direct.FRAME_END), first_byte_timeout=0.3)
                        if valid_reply(reply, address, 0x3A, 4):
                            row["valid"].append(address)
                        if reply:
                            row["replies"][str(address)] = direct.hex_bytes(reply)
            except Exception as exc:
                row["error"] = str(exc)
            row["complete"] = set(row["valid"]) == set(MOTOR_IDS)
            results.append(row)
    complete = [row["baud"] for row in results if row.get("complete")]
    # If more than one rate appears valid, prefer the fastest one.  A real
    # Y42 bus normally has one common rate; the full-ID requirement prevents
    # a single stray reply from being treated as a usable bus setting.
    recommended = max(complete) if complete else None
    if recommended is not None:
        set_state(baud=recommended)
        persist_saved_baud(recommended)
    append_process_log(
        "baud_sweep_complete",
        port=port,
        requested_bauds=list(bauds),
        complete_bauds=complete,
        recommended_baud=recommended,
    )
    return {
        "ok": True,
        "action": "baud-sweep",
        "port": port,
        "results": results,
        "complete_bauds": complete,
        "recommended_baud": recommended,
        "matched": bool(complete),
        "message": (
            f"已找到四台电机共同波特率：{recommended}"
            if recommended
            else "未找到能同时收到 ID 1..4 有效回包的波特率"
        ),
        "note": "每个波特率只向 ID 1..4 发送一次 0x3A 状态查询，不发送运动指令，也不会修改电机内部波特率",
    }


def read_x_configuration(connection: object, address: int) -> bytes:
    """Read the complete X configuration block needed for a safe baud edit."""

    tx = direct.frame(address, 0x42, 0x6C, direct.FRAME_END)
    reply = b""
    for attempt in range(3):
        reply = direct.transact(connection, tx, first_byte_timeout=0.35)
        if len(reply) >= 37 and valid_reply(reply, address, 0x42, 37) and reply[2] == 0x25:
            return reply
        if attempt < 2:
            time.sleep(0.05)
    return b""


def x_baud_config_frame(address: int, config_reply: bytes, target_code: int) -> bytes:
    """Keep every X setting unchanged and replace only config byte 23 (baud)."""

    if len(config_reply) != 37 or config_reply[:4] != bytes((address, 0x42, 0x25, 0x18)) or config_reply[-1] != direct.FRAME_END:
        raise ValueError(f"ID {address} 的 X 配置回包长度无效")
    fields = bytearray(config_reply[4:36])
    if len(fields) != 32:
        raise ValueError(f"ID {address} 的 X 配置字段不完整")
    # Reply index 22 is configuration byte 23; it is payload index 18 after
    # the address/function/subfunction/store prefix of the write command.
    fields[18] = target_code
    # 0x01 is the required "store" byte between D1 and the 32 config fields.
    return direct.frame(address, 0x48, 0xD1, 0x01, *fields, direct.FRAME_END)


def set_all_motor_baud(port: str, host_baud: int, target_baud: int) -> dict:
    """Write one common baud to all four X motors and verify at that rate.

    The complete X configuration is read first and then written back with only
    the baud field changed. Motors are disabled before the write. A missing ACK
    at the old rate is tolerated because some firmware applies the new rate
    before returning its ACK; final verification at the target rate is decisive.
    """

    if target_baud not in BAUD_TO_CODE:
        raise ValueError(f"目标波特率不在 Y42 手册支持列表中: {target_baud}")
    if host_baud not in BAUD_TO_CODE:
        raise ValueError(f"当前电脑端波特率不在 Y42 手册支持列表中: {host_baud}")
    if target_baud == host_baud:
        return {"ok": True, "action": "baud-set", "applied": False, "verified": True, "message": "目标波特率与当前电脑端相同，无需写入"}

    append_process_log("baud_set_start", port=port, host_baud=host_baud, target_baud=target_baud)
    configs: dict[int, bytes] = {}
    write_results: list[dict] = []
    with SERIAL_LOCK, direct.open_serial(port, host_baud) as connection:
        disabled = disable_all(connection)
        if not all(item.get("accepted") for item in disabled):
            raise RuntimeError("写入波特率前四台电机未能全部失能，已取消")
        for address in MOTOR_IDS:
            config = read_x_configuration(connection, address)
            if not config:
                raise RuntimeError(f"ID {address} 未返回完整 X 配置，未执行波特率写入")
            configs[address] = config
        current_codes = {config[22] for config in configs.values()}
        if len(current_codes) != 1:
            raise RuntimeError("四台电机内部波特率不一致，先用自动扫描确认总线状态，未执行写入")
        current_code = next(iter(current_codes))
        detected_baud = CODE_TO_BAUD.get(current_code)
        if detected_baud != host_baud:
            raise RuntimeError(f"配置回读显示电机波特率为 {detected_baud or ('代码 '+str(current_code))}，与电脑端 {host_baud} 不一致，未执行写入")
        for address in MOTOR_IDS:
            tx = x_baud_config_frame(address, configs[address], BAUD_TO_CODE[target_baud])
            rx = direct.transact(connection, tx, first_byte_timeout=0.35)
            write_results.append({
                "id": address,
                "accepted_at_old_baud": direct.command_accepted(rx, address, 0x48),
                "tx": direct.hex_bytes(tx),
                "rx": direct.hex_bytes(rx),
            })

    time.sleep(0.20)
    verify_results: list[dict] = []
    try:
        with SERIAL_LOCK, direct.open_serial(port, target_baud) as connection:
            for address in MOTOR_IDS:
                config = read_x_configuration(connection, address)
                expected = bytearray(configs[address])
                expected[22] = BAUD_TO_CODE[target_baud]
                verified = bool(config and config == bytes(expected))
                verify_results.append({"id": address, "verified": verified, "baud": CODE_TO_BAUD.get(config[22]) if config else None})
    except Exception as exc:
        verify_results = [{"id": address, "verified": False, "error": str(exc)} for address in MOTOR_IDS]

    verified = all(item.get("verified") for item in verify_results)
    append_process_log(
        "baud_set_complete",
        port=port,
        host_baud=host_baud,
        target_baud=target_baud,
        applied=bool(write_results),
        verified=verified,
        write_results=write_results,
        verify_results=verify_results,
    )
    if verified:
        set_state(baud=target_baud)
        persist_saved_baud(target_baud)
        return {
            "ok": True,
            "action": "baud-set",
            "applied": True,
            "verified": True,
            "host_baud": host_baud,
            "target_baud": target_baud,
            "write_results": write_results,
            "verify_results": verify_results,
            "message": f"四台电机内部波特率已统一为 {target_baud}，目标速率回读复核通过；电机保持失能",
        }
    from y42_baud_recovery import restore_baud_snapshot

    def recovery_exchange(recovery_baud, tx):
        with SERIAL_LOCK, direct.open_serial(port, recovery_baud) as connection:
            rx = direct.transact(connection, tx, first_byte_timeout=0.10)
        append_process_log("baud_recovery_transaction", baud=recovery_baud,
                           tx_hex=tx.hex(), rx_hex=rx.hex())
        return bytes(rx)

    try:
        recovery = restore_baud_snapshot(configs, host_baud, target_baud, recovery_exchange)
    except Exception as exc:
        recovery = {"restored": False, "error": str(exc)}
    append_process_log("baud_recovery_complete", **recovery)
    if recovery["restored"]:
        set_state(baud=host_baud)
        persist_saved_baud(host_baud)
    message = (f"目标速率 {target_baud} 验证失败；已自动恢复 {host_baud}，四台完整配置和失能状态复核通过"
               if recovery["restored"] else
               f"目标速率 {target_baud} 验证失败，原速率恢复未能完整确认；控制已锁定，未继续运动")
    set_state(auto="error", control_unlocked=False, message=message)
    return {
        "ok": True,
        "action": "baud-set",
        "applied": bool(write_results),
        "verified": False,
        "host_baud": host_baud,
        "target_baud": target_baud,
        "write_results": write_results,
        "verify_results": verify_results,
        "recovery": recovery,
        "message": message,
    }


def set_single_motor_baud(port: str, host_baud: int, address: int, target_baud: int) -> dict:
    """Change one X motor's baud while leaving the other bus members untouched."""
    address = direct.check_id(address)
    if target_baud not in BAUD_TO_CODE:
        raise ValueError(f"目标波特率不在 Y42 手册支持列表中: {target_baud}")
    if host_baud not in BAUD_TO_CODE:
        raise ValueError(f"当前电脑端波特率不在 Y42 手册支持列表中: {host_baud}")
    if host_baud == target_baud:
        return {"ok": True, "action": "baud-set-single", "id": address, "applied": False,
                "verified": True, "host_baud": host_baud, "target_baud": target_baud,
                "message": "目标波特率与当前电脑端相同，无需写入"}
    with SERIAL_LOCK, direct.open_serial(port, host_baud) as connection:
        config = read_x_configuration(connection, address)
        if not config:
            return {"ok": False, "action": "baud-set-single", "id": address,
                    "host_baud": host_baud, "target_baud": target_baud,
                    "message": f"M{address} 在 {host_baud} 无法读取 X 配置，未写入"}
        disable_tx = direct.frame(address, 0xF3, 0xAB, 0x00, 0x00, direct.FRAME_END)
        disable_rx = direct.transact(connection, disable_tx, first_byte_timeout=0.35)
        write_tx = x_baud_config_frame(address, config, BAUD_TO_CODE[target_baud])
        write_rx = direct.transact(connection, write_tx, first_byte_timeout=0.5)
        restart_tx = firmware_restart_frame(address)
        restart_rx = direct.transact(connection, restart_tx, first_byte_timeout=0.6)
    time.sleep(0.45)
    with SERIAL_LOCK, direct.open_serial(port, target_baud) as connection:
        verify_config = read_x_configuration(connection, address)
    expected = bytearray(config)
    expected[22] = BAUD_TO_CODE[target_baud]
    verified = bool(verify_config and verify_config == bytes(expected))
    result = {
        "ok": verified,
        "action": "baud-set-single",
        "id": address,
        "host_baud": host_baud,
        "target_baud": target_baud,
        "disable_ack": direct.command_accepted(disable_rx, address, 0xF3),
        "disable_rx": direct.hex_bytes(disable_rx),
        "write_ack": direct.command_accepted(write_rx, address, 0x48),
        "write_rx": direct.hex_bytes(write_rx),
        "restart_ack": direct.command_accepted(restart_rx, address, 0x08),
        "restart_rx": direct.hex_bytes(restart_rx),
        "verified": verified,
        "verified_baud": CODE_TO_BAUD.get(verify_config[22]) if verify_config else None,
        "message": f"M{address} 已改为 {target_baud} 并复核通过" if verified else f"M{address} 波特率写入后复核失败",
    }
    if verified:
        set_state(baud=target_baud)
        persist_saved_baud(target_baud)
    return result


def online(telemetry: direct.Telemetry) -> bool:
    return telemetry.position is not None and telemetry.rpm is not None and telemetry.flags is not None


def safety_error(
    values: list[direct.Telemetry],
    current_limit: int = HARD_CURRENT,
    *,
    ignore_driver_protection: bool = False,
) -> str | None:
    """Return a live electrical/communication safety fault.

    Bit 0x08 is still exposed in telemetry and logged, but it is optionally
    ignored by trajectory motion because the installed X drives latch that bit
    through a normal STOP/DISABLE cycle.  Current, temperature and missing
    feedback remain fail-closed in every mode.
    """
    trip_limit = overcurrent_trip_limit(current_limit)
    for index, telemetry in enumerate(values):
        if not online(telemetry):
            return f"电机 M{index + 1}/ID{telemetry.address} 通讯中断"
        if telemetry.temperature is not None and telemetry.temperature >= HARD_TEMPERATURE:
            return f"电机 M{index + 1} 温度达到 {telemetry.temperature}°C"
        if telemetry.phase_current is not None and abs(float(telemetry.phase_current)) > trip_limit:
            return f"电机 M{index + 1} 电流 {abs(float(telemetry.phase_current)):.0f}mA 超过安全阈值 {trip_limit}mA"
        if not ignore_driver_protection and telemetry.flags is not None and telemetry.flags & 0x08:
            return f"电机 M{index + 1} 触发保护"
    return None


def query_position_field(connection: object, index: int) -> tuple[bool, float | None, str]:
    address = MOTOR_IDS[index]
    command = 0x36
    reply = b""
    for attempt in range(2):
        reply = direct.transact(
            connection,
            direct.frame(address, command, direct.FRAME_END),
            first_byte_timeout=TRACKING_POSITION_FIRST_BYTE_TIMEOUT,
            inter_byte_quiet=TRACKING_POSITION_INTER_BYTE_QUIET,
        )
        if valid_reply(reply, address, command, 8):
            break
        if attempt == 0:
            time.sleep(0.003)
    if not valid_reply(reply, address, command, 8):
        return False, None, f"轨迹中电机 M{index + 1} 位置连续两次无有效回包"
    raw = direct.read_u32(reply, 3) / 10.0
    position = -raw if reply[2] else raw
    with STATE_LOCK:
        current = STATE["telemetry"].setdefault(str(address), {"id": address})
        current["position"] = position
        current["online"] = True
    return True, position, ""


def read_position_snapshot(connection: object) -> tuple[list[float] | None, str]:
    """Read one four-motor position snapshot without the 28-field telemetry pass."""
    positions: list[float] = []
    for index in range(len(MOTOR_IDS)):
        ok, position, reason = query_position_field(connection, index)
        if not ok or position is None:
            return None, reason or f"M{index + 1} 位置回读失败"
        positions.append(float(position))
    return positions, ""


def query_safety_field(
    connection: object,
    index: int,
    field: int,
    *,
    current_limit: int = HARD_CURRENT,
) -> tuple[bool, str]:
    address = MOTOR_IDS[index]
    command = (0x27, 0x39, 0x3A)[field]
    # Keep the low-rate safety poll inside the spare part of the 10 ms bus
    # budget. The trajectory itself remains one 0xAA write per tick.
    reply = b""
    # A position frame can still be draining through the USB adapter when the
    # end-window query starts.  Treat one or two empty replies as a transport
    # retry, not as a motor fault; the protection check below remains strict on
    # the first valid current/temperature/flags reply.
    for attempt in range(4):
        reply = direct.transact(
            connection,
            direct.frame(address, command, direct.FRAME_END),
            first_byte_timeout=0.10,
            inter_byte_quiet=0.004,
        )
        minimum = 5 if field < 2 else 4
        if valid_reply(reply, address, command, minimum):
            break
        if attempt < 3:
            time.sleep(0.008)
    minimum = 5 if field < 2 else 4
    if not valid_reply(reply, address, command, minimum):
        return False, f"轨迹中电机 M{index + 1} 安全回读连续四次无有效回包"
    with STATE_LOCK:
        current = STATE["telemetry"].setdefault(str(address), {"id": address})
        if field == 0:
            current["phase_current"] = direct.read_u16(reply, 2)
            trip_limit = overcurrent_trip_limit(current_limit)
            if current["phase_current"] > trip_limit:
                return False, f"运行中电机 M{index + 1} 电流 {current['phase_current']}mA 超过安全阈值 {trip_limit}mA，已请求失能"
        elif field == 1:
            current["temperature"] = reply[3]
            if current["temperature"] >= HARD_TEMPERATURE:
                return False, f"轨迹中电机 M{index + 1} 温度达到 {current['temperature']}°C"
        else:
            current["flags"] = reply[2]
            current["flags_text"] = direct.decode_flags(reply[2])
            if reply[2] & 0x08:
                return False, f"轨迹中电机 M{index + 1} 触发保护"
    return True, ""


def read_trajectory_settle(
    connection: object,
    attempts: int = 2,
    *,
    first_byte_timeout: float = 0.025,
    inter_byte_quiet: float = 0.001,
    include_load: bool = False,
) -> list[direct.Telemetry]:
    """Read only the fields needed while a trajectory endpoint settles.

    A complete telemetry pass asks for 28 replies.  Doing that immediately
    after the last drawing frame made a short path appear to pause for a
    second or more.  The endpoint only needs fresh position, RPM and flags;
    current and temperature remain safety-checked from the latest low-rate
    polls.  This 12-reply pass keeps the endpoint command cadence alive while
    still failing closed on a missing position/RPM/status reply.
    """

    queries = (("rpm", 0x35, 6), ("position", 0x36, 8), ("flags", 0x3A, 4))
    if include_load:
        # The start gate can last seconds while an axis is blocked. Its
        # pre-move cached current is not evidence of the load during that wait.
        queries += (("phase_current", 0x27, 5), ("temperature", 0x39, 5))
    last: list[direct.Telemetry] = []
    for attempt in range(max(1, attempts)):
        with STATE_LOCK:
            cached = copy.deepcopy(STATE.get("telemetry", {}))
        values: list[direct.Telemetry] = []
        for address in MOTOR_IDS:
            telemetry = direct.Telemetry(address)
            old = cached.get(str(address), {}) if isinstance(cached, dict) else {}
            for field in ("voltage", "bus_current", "phase_current", "temperature"):
                if include_load and field in ("phase_current", "temperature"):
                    continue
                value = old.get(field)
                if value is not None:
                    setattr(telemetry, field, value)
            for name, command, minimum in queries:
                reply = direct.transact(
                    connection,
                    direct.frame(address, command, direct.FRAME_END),
                    first_byte_timeout=first_byte_timeout,
                    inter_byte_quiet=inter_byte_quiet,
                )
                if not valid_reply(reply, address, command, minimum):
                    continue
                if name == "rpm":
                    value = direct.read_u16(reply, 3) / 10.0
                    telemetry.rpm = -value if reply[2] else value
                elif name == "position":
                    value = direct.read_u32(reply, 3) / 10.0
                    telemetry.position = -value if reply[2] else value
                elif name == "phase_current":
                    telemetry.phase_current = direct.read_u16(reply, 2)
                elif name == "temperature":
                    telemetry.temperature = reply[3]
                else:
                    telemetry.flags = reply[2]
            values.append(telemetry)
        update_telemetry(values)
        last = values
        if len(values) == len(MOTOR_IDS) and all(
            telemetry.position is not None
            and telemetry.rpm is not None
            and telemetry.flags is not None
            and (not include_load or (telemetry.phase_current is not None and telemetry.temperature is not None))
            for telemetry in values
        ):
            return values
        if attempt + 1 < max(1, attempts):
            time.sleep(0.006)
    return last


def calibration_data() -> dict:
    with STATE_LOCK:
        return copy.deepcopy(STATE["calibration"])


def tracking_pen_thresholds(calibration: dict | None = None) -> tuple[float, float]:
    """Return validated pen-up/pen-down thresholds from saved settings."""

    data = calibration if calibration is not None else calibration_data()
    try:
        pen_up = float(data.get("tracking_pen_up_height_mm", TRACKING_PEN_UP_HEIGHT_MM))
        pen_down = float(data.get("tracking_pen_down_height_mm", TRACKING_PEN_DOWN_HEIGHT_MM))
    except (TypeError, ValueError):
        return TRACKING_PEN_UP_HEIGHT_MM, TRACKING_PEN_DOWN_HEIGHT_MM
    if (
        not math.isfinite(pen_up)
        or not math.isfinite(pen_down)
        or not 1.0 <= pen_up <= 100.0
        or not 0.0 <= pen_down < pen_up
    ):
        return TRACKING_PEN_UP_HEIGHT_MM, TRACKING_PEN_DOWN_HEIGHT_MM
    return pen_up, pen_down


def save_calibration_settings(data: dict) -> dict:
    """Persist geometry/current/slope trims without starting a motor action."""
    calibration = calibration_data()
    try:
        side = float(data.get("side", calibration.get("side", WORKSPACE_HEIGHT_MM)))
        ball = float(data.get("ball", calibration.get("ball", 40.0)))
        requested_strong = int(data.get("strong", calibration.get("strong_current", CALIBRATION_DEFAULT_STRONG_CURRENT)))
        requested_weak = int(data.get("weak", calibration.get("weak_current", CALIBRATION_DEFAULT_WEAK_CURRENT)))
        # The operator-facing calibration profile is fixed to the proven
        # 1500/300mA pair.  The slow current envelope is implemented by the
        # worker below, so stale UI values cannot silently restore 1800/900.
        strong = CALIBRATION_BRUTE_FORCE_STRONG_CURRENT
        weak = CALIBRATION_BRUTE_FORCE_HOLD_CURRENT
        trajectory_current = int(data.get("trajectory_current", calibration.get("trajectory_current", TRAJECTORY_DEFAULT_CURRENT)))
        draw_tension_current = int(data.get("draw_tension_current_ma", calibration.get("draw_tension_current_ma", DRAW_TENSION_DEFAULT_CURRENT)))
        tracking_current = int(data.get("tracking_current_ma", calibration.get("tracking_current_ma", TRACKING_CURRENT_LIMIT_DEFAULT_MA)))
        path_speed = float(data.get("path_speed_mm_s", calibration.get("path_speed_mm_s", PATH_SPEED_DEFAULT_MM_S)))
        raw_trims = data.get("slope_trim_percent", calibration.get("slope_trim_percent", [0.0] * len(MOTOR_IDS)))
        trims = [float(value) for value in raw_trims]
        pen_up = float(data.get("tracking_pen_up_height_mm", calibration.get("tracking_pen_up_height_mm", TRACKING_PEN_UP_HEIGHT_MM)))
        pen_down = float(data.get("tracking_pen_down_height_mm", calibration.get("tracking_pen_down_height_mm", TRACKING_PEN_DOWN_HEIGHT_MM)))
        grid_target_current = int(data.get("grid_tension_target_current_ma", calibration.get("grid_tension_target_current_ma", GRID_DEFAULT_TENSION_CURRENT_MA)))
        center_target_current = int(data.get("center_tension_target_current_ma", calibration.get("center_tension_target_current_ma", CENTER_TENSION_DEFAULT_CURRENT_MA)))
        grid_rows, grid_cols = normalized_grid_shape(
            data.get("grid_rows", calibration.get("grid_rows", GRID_DEFAULT_ROWS)),
            data.get("grid_cols", calibration.get("grid_cols", GRID_DEFAULT_COLS)),
        )
    except (TypeError, ValueError) as exc:
        raise ValueError("校准参数必须是有效数字") from exc
    # ``side`` and ``ball`` are retained as physical metadata for the UI, but
    # the PC direct-control frame is fixed by the measured ball-center area.
    # Never derive the horizontal span as ``side - ball``: 110 mm already
    # includes the ball's collision geometry and must not be cropped again.
    if (
        not math.isclose(side, WORKSPACE_HEIGHT_MM, abs_tol=0.0001)
        or not math.isclose(ball, DEFAULT_BALL_DIAMETER_MM, abs_tol=0.0001)
    ):
        raise ValueError("本机电脑直连工作区固定为球心 110×148mm；球径元数据固定为 40mm")
    width = WORKSPACE_WIDTH_MM
    height = WORKSPACE_HEIGHT_MM
    if not 50 <= strong <= OPERATING_CURRENT_MAX_MA or not 20 <= weak < strong:
        raise ValueError(f"校准电流范围无效：强电流 50..{OPERATING_CURRENT_MAX_MA}mA，张力电流 20..强电流")
    if not 300 <= trajectory_current <= OPERATING_CURRENT_MAX_MA:
        raise ValueError(f"轨迹位置电流上限必须在 300..{OPERATING_CURRENT_MAX_MA}mA")
    if not TRAJECTORY_TENSION_MIN_CURRENT <= draw_tension_current <= TRAJECTORY_TENSION_MAX_CURRENT:
        raise ValueError(f"绘制张力上限必须在 {TRAJECTORY_TENSION_MIN_CURRENT}..{TRAJECTORY_TENSION_MAX_CURRENT}mA")
    if not TRACKING_MIN_CURRENT <= tracking_current <= TRACKING_MAX_CURRENT:
        raise ValueError(f"张力跟踪电流必须在 {TRACKING_MIN_CURRENT}..{TRACKING_MAX_CURRENT}mA")
    if not math.isfinite(path_speed) or not PATH_SPEED_MIN_MM_S <= path_speed <= PATH_SPEED_MAX_MM_S:
        raise ValueError(f"手绘速度必须在 {PATH_SPEED_MIN_MM_S:.0f}..{PATH_SPEED_MAX_MM_S:.0f}mm/s")
    if len(trims) != len(MOTOR_IDS) or any(not math.isfinite(value) or not -SLOPE_TRIM_LIMIT_PERCENT <= value <= SLOPE_TRIM_LIMIT_PERCENT for value in trims):
        raise ValueError(f"四台斜率微调必须分别填写 {-SLOPE_TRIM_LIMIT_PERCENT:.0f}%..+{SLOPE_TRIM_LIMIT_PERCENT:.0f}%")
    if not math.isfinite(pen_up) or not math.isfinite(pen_down) or not 1.0 <= pen_up <= 100.0 or not 0.0 <= pen_down < pen_up:
        raise ValueError("抬笔阈值必须是 1..100mm，落笔阈值必须是 0..抬笔阈值以内且小于抬笔阈值")
    if not GRID_TENSION_MIN_CURRENT_MA <= grid_target_current <= GRID_TENSION_MAX_CURRENT_MA:
        raise ValueError(
            f"网格张力下限必须在 {GRID_TENSION_MIN_CURRENT_MA}..{GRID_TENSION_MAX_CURRENT_MA}mA"
        )
    if not GRID_TENSION_MIN_CURRENT_MA <= center_target_current <= GRID_TENSION_MAX_CURRENT_MA:
        raise ValueError(
            f"五点中心校准电流必须在 {GRID_TENSION_MIN_CURRENT_MA}..{GRID_TENSION_MAX_CURRENT_MA}mA"
        )
    old_side = float(calibration.get("side", side))
    old_ball = float(calibration.get("ball", ball))
    geometry_changed = abs(old_side - side) > 0.0001 or abs(old_ball - ball) > 0.0001
    old_grid_target = int(calibration.get("grid_tension_target_current_ma", GRID_DEFAULT_TENSION_CURRENT_MA))
    old_grid_shape = (
        int(calibration.get("grid_rows", GRID_DEFAULT_ROWS)),
        int(calibration.get("grid_cols", GRID_DEFAULT_COLS)),
    )
    grid_settings_changed = old_grid_target != grid_target_current or old_grid_shape != (grid_rows, grid_cols)
    old_trims = normalized_slope_trims(calibration)
    slope_trim_changed = any(abs(before - after) > 0.0001 for before, after in zip(old_trims, trims))
    # Trims are intentionally allowed to be tuned independently.  The hard
    # percentage bound protects the fitted scale from a sign flip while not
    # preventing the operator from making repeated 1% corrections.
    calibration.update(
        {
            "side": height,
            "ball": DEFAULT_BALL_DIAMETER_MM,
            "effective_side": height,
            "workspace_width": width,
            "workspace_height": height,
            "anchor_width": ANCHOR_WIDTH_MM,
            "anchor_height": ANCHOR_HEIGHT_MM,
            "motor_frame_origin_mm": [MOTOR_FRAME_ORIGIN_X_MM, MOTOR_FRAME_ORIGIN_Y_MM],
            "motor_center_coordinates_mm": [list(pair) for pair in zip(*motor_center_coordinates())],
            "cable_exit_offset_x_mm": MOTOR_CABLE_EXIT_OFFSET_X_MM,
            "spool_winding_radius_mm": SPOOL_WINDING_RADIUS_MM,
            "spool_reference_radius_mm": SPOOL_REFERENCE_RADIUS_MM,
            "spool_winding_z_range_mm": [SPOOL_WINDING_Z_MIN_MM, SPOOL_WINDING_Z_MAX_MM],
            "ball_center_contact_z_mm": BALL_CENTER_CONTACT_Z_MM,
            "ball_attachment_z_mm": BALL_ATTACHMENT_Z_MM,
            "ball_attachment_span_x_mm": BALL_ATTACHMENT_SPAN_X_MM,
            "ball_attachment_span_y_mm": BALL_ATTACHMENT_SPAN_Y_MM,
            "platform_command_yaw_deg": PLATFORM_COMMAND_YAW_DEG,
            "cable_exit_model": CABLE_EXIT_MODEL,
            "geometry_version": GEOMETRY_VERSION,
            "coordinate_frame": "ball_center_workspace",
            "control_architecture": CONTROL_ARCHITECTURE,
            "platform_pose_model": PLATFORM_POSE_MODEL,
            "strong_current": strong,
            "weak_current": weak,
            "trajectory_current": trajectory_current,
            "draw_tension_current_ma": draw_tension_current,
            "tracking_current_ma": tracking_current,
            "path_speed_mm_s": path_speed,
            "slope_trim_percent": trims,
            "tracking_pen_up_height_mm": pen_up,
            "tracking_pen_down_height_mm": pen_down,
            "grid_tension_target_current_ma": grid_target_current,
            "center_tension_target_current_ma": center_target_current,
            "grid_rows": grid_rows,
            "grid_cols": grid_cols,
        }
    )
    if grid_settings_changed:
        grid = blank_grid_compensation(grid_rows, grid_cols)
        grid["valid"] = False
        grid["enabled"] = False
        grid["invalid_reason"] = "网格目标或采样密度已修改，请重新采集网格"
        calibration["grid_compensation"] = grid
    if geometry_changed and calibration.get("valid"):
        calibration["valid"] = False
        calibration["quality_error"] = "几何尺寸已修改，请用新尺寸重新完成四角校准"
        calibration["workspace_calibration_verified"] = False
        calibration["internal_model_verified"] = False
        calibration["internal_model_source"] = "none"
    elif calibration.get("valid") is True and calibration.get("workspace_calibration_verified") is not True:
        # Keep the persisted invariant explicit even if an older or manually
        # edited in-memory state claims validity without the new verification.
        calibration["valid"] = False
        calibration["quality_error"] = "当前四角样本尚未通过新版 110×148mm 球心工作区复验"
    elif calibration.get("valid") is not True:
        # Runtime/settings edits must not accidentally certify an unverified
        # calibration file. Conversely, a verified calibration keeps its
        # verification flag when only current/speed/threshold settings change.
        calibration["workspace_calibration_verified"] = False
        calibration["internal_model_verified"] = False
        calibration["internal_model_source"] = "none"
    if calibration.get("external_pose_verified") is True and (geometry_changed or slope_trim_changed):
        calibration["external_pose_verified"] = False
        calibration["calibration_source"] = "torque_corner_initializer"
        calibration["external_pose_invalidated_reason"] = (
            "斜率/几何参数已修改；原外部位姿样本保留作历史记录，必须重新拟合后才能运行绝对轨迹"
        )
    with STATE_LOCK:
        STATE["calibration"] = calibration
        STATE["internal_feedback_calibration"] = copy.deepcopy(
            calibration.get("internal_feedback_calibration", blank_internal_feedback_calibration())
        )
        STATE["message"] = "校准参数已保存；几何尺寸变化时需要重新做四角校准" if geometry_changed else "校准参数已保存"
    persist_calibration(calibration)
    append_process_log(
        "calibration_settings_saved",
        side=side,
        ball=ball,
        strong_current=strong,
        weak_current=weak,
        trajectory_current=trajectory_current,
        draw_tension_current_ma=draw_tension_current,
        tracking_current_ma=tracking_current,
        path_speed_mm_s=path_speed,
        slope_trim_percent=trims,
        tracking_pen_up_height_mm=pen_up,
        tracking_pen_down_height_mm=pen_down,
        grid_tension_target_current_ma=grid_target_current,
        grid_rows=grid_rows,
        grid_cols=grid_cols,
        geometry_changed=geometry_changed,
        grid_settings_changed=grid_settings_changed,
    )
    return {
        "ok": True,
        "action": "calibration-settings",
        "calibration": calibration,
        "message": "校准参数已保存" + ("；几何尺寸已变化，请重新校准" if geometry_changed else ""),
    }


def reset_default_parameters() -> dict:
    """Restore editable runtime defaults while preserving fitted calibration data."""
    with STATE_LOCK:
        running = str(STATE.get("auto", "idle"))
    if running not in {"", "idle", "error"}:
        raise RuntimeError("自动流程运行中，请先停止后再恢复默认参数")
    current = calibration_data()
    calibration = copy.deepcopy(current)
    external_was_verified = calibration.get("external_pose_verified") is True
    calibration.update(
        {
            "strong_current": CALIBRATION_DEFAULT_STRONG_CURRENT,
            "weak_current": CALIBRATION_DEFAULT_WEAK_CURRENT,
            "trajectory_current": TRAJECTORY_DEFAULT_CURRENT,
            "draw_tension_current_ma": DRAW_TENSION_DEFAULT_CURRENT,
            "force_position_target_current_ma": FORCE_POSITION_TARGET_FLOOR_MA,
            "tracking_current_ma": TRACKING_CURRENT_LIMIT_DEFAULT_MA,
            "path_speed_mm_s": PATH_SPEED_DEFAULT_MM_S,
            "slope_trim_percent": [0.0 for _ in MOTOR_IDS],
            "tracking_pen_up_height_mm": TRACKING_PEN_UP_HEIGHT_MM,
            "tracking_pen_down_height_mm": TRACKING_PEN_DOWN_HEIGHT_MM,
            "grid_tension_target_current_ma": GRID_DEFAULT_TENSION_CURRENT_MA,
            "center_tension_target_current_ma": CENTER_TENSION_DEFAULT_CURRENT_MA,
            "grid_rows": GRID_DEFAULT_ROWS,
            "grid_cols": GRID_DEFAULT_COLS,
        }
    )
    grid = normalize_grid_compensation(calibration.get("grid_compensation"))
    grid["valid"] = False
    grid["enabled"] = False
    grid["invalid_reason"] = "已恢复默认参数，请重新采集网格张力地图"
    calibration["grid_compensation"] = grid
    if external_was_verified:
        calibration["external_pose_verified"] = False
        calibration["calibration_source"] = "torque_corner_initializer"
        calibration["external_pose_invalidated_reason"] = (
            "运行默认参数重置了斜率微调；原外部位姿样本保留作历史记录，必须重新拟合后才能运行绝对轨迹"
        )
    with STATE_LOCK:
        STATE["calibration"] = calibration
        STATE["internal_feedback_calibration"] = copy.deepcopy(
            calibration.get("internal_feedback_calibration", blank_internal_feedback_calibration())
        )
        STATE["trajectory_current_override"] = None
        STATE["tracking_current_ma"] = TRACKING_CURRENT_LIMIT_DEFAULT_MA
        STATE["tracking_current_limit_ma"] = TRACKING_CURRENT_LIMIT_DEFAULT_MA
        STATE["tracking_tension_floor_ma"] = TRACKING_AUTO_FLOOR_CURRENT_MA
        STATE["message"] = "已恢复运行默认参数；已保留几何校准系数和电机方向"
    persist_calibration(calibration)
    append_process_log(
        "parameters_reset_defaults",
        strong_current=CALIBRATION_DEFAULT_STRONG_CURRENT,
        weak_current=CALIBRATION_DEFAULT_WEAK_CURRENT,
        trajectory_current=TRAJECTORY_DEFAULT_CURRENT,
        draw_tension_current_ma=DRAW_TENSION_DEFAULT_CURRENT,
        tracking_current_ma=TRACKING_CURRENT_LIMIT_DEFAULT_MA,
        path_speed_mm_s=PATH_SPEED_DEFAULT_MM_S,
        slope_trim_percent=[0.0 for _ in MOTOR_IDS],
        tracking_pen_up_height_mm=TRACKING_PEN_UP_HEIGHT_MM,
        tracking_pen_down_height_mm=TRACKING_PEN_DOWN_HEIGHT_MM,
        grid_tension_target_current_ma=GRID_DEFAULT_TENSION_CURRENT_MA,
        center_tension_target_current_ma=CENTER_TENSION_DEFAULT_CURRENT_MA,
        grid_rows=GRID_DEFAULT_ROWS,
        grid_cols=GRID_DEFAULT_COLS,
        calibration_preserved=True,
    )
    return {
        "ok": True,
        "action": "reset-defaults",
        "calibration": calibration,
        "message": "已恢复运行默认参数；已保留几何校准系数和电机方向",
    }


def direction_reversal_flags(calibration: dict | None = None) -> tuple[bool, ...]:
    data = calibration if calibration is not None else calibration_data()
    raw = data.get("direction_reverse", [])
    if not isinstance(raw, list) or len(raw) != len(MOTOR_IDS):
        return tuple(False for _ in MOTOR_IDS)
    return tuple(bool(value) for value in raw)


def pull_directions() -> tuple[int, ...]:
    return tuple(
        int(base) ^ int(reversed_direction)
        for base, reversed_direction in zip(PULL_DIRECTIONS, direction_reversal_flags())
    )


def encoder_positive_directions(calibration: dict | None = None) -> tuple[int, ...]:
    """Return the driver direction bit that increases each encoder position.

    Prefer the mapping learned by the direction test.  Older calibration files
    do not contain it, so derive it from the fitted rope-length slope: the
    pull direction shortens the rope, hence its encoder sign is opposite to
    the slope sign.
    """
    data = calibration if calibration is not None else calibration_data()
    raw = data.get("encoder_positive_direction")
    if isinstance(raw, list) and len(raw) == len(MOTOR_IDS):
        try:
            values = tuple(int(value) for value in raw)
            if all(value in (0, 1) for value in values):
                return values
        except (TypeError, ValueError):
            pass
    slopes = data.get("slope", [])
    pull = pull_directions() if calibration is None else tuple(
        int(base) ^ int(reversed_direction)
        for base, reversed_direction in zip(PULL_DIRECTIONS, direction_reversal_flags(data))
    )
    result = []
    for index, direction in enumerate(pull):
        try:
            slope = float(slopes[index])
        except (IndexError, TypeError, ValueError):
            slope = 0.0
        if abs(slope) < 0.05:
            result.append(direction)
            continue
        encoder_sign_for_pull = -1 if slope > 0 else 1
        result.append(direction if encoder_sign_for_pull > 0 else direction ^ 1)
    return tuple(result)


def position_direction_for_delta(index: int, delta: float) -> int:
    positive_direction = encoder_positive_directions()[index]
    return positive_direction if delta >= 0 else positive_direction ^ 1


def absolute_position_direction(index: int, target: float) -> int:
    """Encode an absolute target in the installed driver's coordinate frame.

    The calibration position is the signed encoder coordinate, while X
    position mode 1/AA-CB interprets ``direction + abs(angle)`` in the
    driver's coordinate frame.  For a motor whose encoder-positive driver bit
    is 1 (the saved M3/M4 mapping), that coordinate is mirrored.
    """

    positive_direction = encoder_positive_directions()[index]
    driver_target = target if positive_direction == 0 else -target
    return 1 if driver_target < 0.0 else 0


def workspace_dimensions(calibration: dict | None = None) -> tuple[float, float]:
    """Return the ball-center rectangle as ``(width, height)`` in mm.

    The PC direct-control frame is fixed at 110×148 mm. Older calibration
    files are kept readable for diagnostics, but missing/legacy dimensions
    must never silently turn the live solver back into a square workspace.
    """

    # Do not trust caller-supplied or legacy metadata here. The PC direct
    # protocol has one fixed ball-center frame; accepting any positive pair
    # would let an old 150x150 or side-minus-ball value leak back into the
    # solver through a diagnostic/custom-calibration call.
    return WORKSPACE_WIDTH_MM, WORKSPACE_HEIGHT_MM


def drawable_workspace_dimensions(calibration: dict | None = None) -> tuple[float, float]:
    """Return the calibrated ball-center drawing rectangle.

    The encoder slope/intercept fit is tied to the four saved ball-center
    corner samples. Keep the canvas, controller and solver on this persisted
    workspace size; legacy anchor metadata must not replace it.
    """

    return workspace_dimensions(calibration)


def drawable_workspace(calibration: dict | None = None) -> tuple[float, float, float, float]:
    """Return ``(left, bottom, width, height)`` in the 110×148 user frame.

    Keep model and feedback coordinates in the original calibrated frame.
    """
    width, height = drawable_workspace_dimensions(calibration)
    return 0.0, 0.0, width, height


def drawing_target_bounds(calibration: dict | None = None) -> tuple[float, float, float, float]:
    """Inset requested drawing only; never translate calibration or feedback."""
    width, height = drawable_workspace_dimensions(calibration)
    scale = DRAW_WORKSPACE_SCALE
    return width*(1-scale)/2, height*(1-scale)/2, width*scale, height*scale


def workspace_corner_coordinates(
    calibration: dict | None = None,
) -> tuple[tuple[float, ...], tuple[float, ...]]:
    """Return the four *measured ball-centre* corner poses, M1..M4 order.

    The user's dimensioned CAD view defines these points as a 110 x 148 mm
    rectangle.  They are not the motor axes and not the equivalent cable
    anchors.  Confusing the two previously shifted every calibration point by
    as much as 16 mm even though the resulting line fit looked plausible.
    """

    width, height = workspace_dimensions(calibration)
    return (
        (0.0, width, width, 0.0),
        (height, height, 0.0, 0.0),
    )


def motor_center_coordinates(
    calibration: dict | None = None,
) -> tuple[tuple[float, ...], tuple[float, ...]]:
    """Return STEP-derived M1..M4 spool axes in the 110x148 user frame.

    CAD axes are ``(-99,+74)``, ``(+99,+74)``, ``(+99,-74)`` and
    ``(-99,-74)`` mm.  Adding the workspace offset ``(+55,+74)`` gives the
    coordinates below.  Keeping the negative/outside X coordinates is
    essential; forcing the frame to 150x150 moved its centre 20 mm right.
    """
    return (
        MOTOR_CENTER_X_MM,
        MOTOR_CENTER_Y_MM,
    )


def cable_exit_coordinates(
    calibration: dict | None = None,
) -> tuple[tuple[float, ...], tuple[float, ...]]:
    """Return nominal horizontal drum-reference points for M1..M4.

    These points retain the user's observed 12.5 mm lateral radius for offline
    initialisation only.  They are *not* physical fixed fairleads: the STEP
    shows a 12 mm smooth vertical drum, so the real peel point changes azimuth
    and z with endpoint direction and winding history.  Readiness gates prevent
    this nominal approximation from driving absolute motion.
    """
    center_x, center_y = motor_center_coordinates(calibration)
    inward = MOTOR_CABLE_EXIT_OFFSET_X_MM
    return (
        (center_x[0] + inward, center_x[1] - inward, center_x[2] - inward, center_x[3] + inward),
        center_y,
    )


def ball_attachment_offsets(
    calibration: dict | None = None,
) -> tuple[tuple[float, ...], tuple[float, ...]]:
    """Return fixed M1..M4 cable attachments relative to the ball centre.

    The CAD dimensions are 30.534 mm left-to-right and 22.823 mm top-to-bottom.
    M1 is the top-left cable, followed clockwise by M2..M4.  The platform is
    commanded at zero yaw because the mechanism has no independent yaw sensor.
    """
    return (
        (-BALL_ATTACHMENT_HALF_X_MM, BALL_ATTACHMENT_HALF_X_MM, BALL_ATTACHMENT_HALF_X_MM, -BALL_ATTACHMENT_HALF_X_MM),
        (BALL_ATTACHMENT_HALF_Y_MM, BALL_ATTACHMENT_HALF_Y_MM, -BALL_ATTACHMENT_HALF_Y_MM, -BALL_ATTACHMENT_HALF_Y_MM),
    )


def cylindrical_spool_free_span_mm(
    motor: int,
    endpoint_x_mm: float,
    endpoint_y_mm: float,
    endpoint_z_mm: float,
    spool_exit_z_mm: float,
    radius_mm: float = SPOOL_WINDING_RADIUS_MM,
    calibration: dict | None = None,
) -> float:
    """Return the straight 3-D span tangent to one vertical cylindrical drum.

    This is the only part of the present winch path that the STEP geometry
    determines without knowing winding history.  It intentionally excludes the
    changing wrapped arc and therefore serves as an uncertainty diagnostic, not
    as the encoder-to-length control law.
    """
    index = int(motor)
    if index not in range(len(MOTOR_IDS)):
        raise ValueError("卷筒索引必须是 0..3")
    radius = float(radius_mm)
    if not math.isfinite(radius) or radius <= 0.0:
        raise ValueError("卷筒半径无效")
    center_x, center_y = motor_center_coordinates(calibration)
    dx = float(endpoint_x_mm) - center_x[index]
    dy = float(endpoint_y_mm) - center_y[index]
    planar_squared = dx * dx + dy * dy
    if planar_squared <= radius * radius:
        raise ValueError("绳端进入卷筒半径，圆柱切线不存在")
    dz = float(endpoint_z_mm) - float(spool_exit_z_mm)
    return math.sqrt(planar_squared - radius * radius + dz * dz)


def spool_height_length_uncertainty_mm(
    x: float,
    y: float,
    yaw_deg: float = PLATFORM_COMMAND_YAW_DEG,
    calibration: dict | None = None,
) -> list[float]:
    """Length ambiguity caused solely by the STEP drum's unknown exit height.

    The result is ``max(free_span)-min(free_span)`` over z=5..16 mm for each
    cable.  Unknown tangent wrap and layer-radius errors are additional, so this
    is a strict lower bound on the present unobserved payout error.
    """
    attachment_x, attachment_y = ball_attachment_offsets(calibration)
    angle = math.radians(float(yaw_deg))
    cosine, sine = math.cos(angle), math.sin(angle)
    ambiguity: list[float] = []
    for motor in range(len(MOTOR_IDS)):
        endpoint_x = float(x) + cosine * attachment_x[motor] - sine * attachment_y[motor]
        endpoint_y = float(y) + sine * attachment_x[motor] + cosine * attachment_y[motor]
        low = cylindrical_spool_free_span_mm(
            motor,
            endpoint_x,
            endpoint_y,
            BALL_ATTACHMENT_Z_MM,
            SPOOL_WINDING_Z_MAX_MM,
            calibration=calibration,
        )
        high = cylindrical_spool_free_span_mm(
            motor,
            endpoint_x,
            endpoint_y,
            BALL_ATTACHMENT_Z_MM,
            SPOOL_WINDING_Z_MIN_MM,
            calibration=calibration,
        )
        ambiguity.append(max(0.0, high - low))
    return ambiguity


def workspace_anchor_coordinates(
    calibration: dict | None = None,
) -> tuple[tuple[float, ...], tuple[float, ...]]:
    """Return nominal equivalent anchors for offline zero-yaw diagnostics.

    Motor order is M1 top-left, M2 top-right, M3 bottom-right, M4
    bottom-left.  For a fixed attachment offset ``bᵢ`` and cable exit ``Aᵢ``,
    the free length is ``||(x,y) - (Aᵢ-bᵢ)||``.  Returning those four
    equivalent centre anchors lets the existing four-sphere forward solver
    remain exact for the commanded zero-yaw pose while still retaining the
    real endpoints for wrench/moment balancing.

    This v8 reference uses the STEP spool-axis frame and the observed 12.5 mm
    lateral radius.  Without fixed fairleads it is a session-local approximation:
    live motion is allowed only after a fresh four-corner fit while all four
    ropes stay tensioned; a stop, disable, power loss or service restart expires it.
    """
    exit_x, exit_y = cable_exit_coordinates(calibration)
    attachment_x, attachment_y = ball_attachment_offsets(calibration)
    return (
        tuple(x - offset for x, offset in zip(exit_x, attachment_x)),
        tuple(y - offset for y, offset in zip(exit_y, attachment_y)),
    )


def _coalesce_rope_curve(
    distances: list[float],
    positions: list[float],
    tolerance: float = 1e-6,
) -> list[tuple[float, float]]:
    """Merge equal geometric distances using the median encoder position.

    A square anchor frame gives each motor two adjacent corners at the same
    distance.  Those weak-cable readings differ slightly through friction and
    hysteresis; treating them as separate X coordinates makes a piecewise
    curve invalid.  Their median is the unbiased datum for that rope length.
    """
    ordered = sorted(zip(distances, positions), key=lambda pair: pair[0])
    groups: list[list[tuple[float, float]]] = []
    for distance, position in ordered:
        if groups and abs(distance - statistics.median(item[0] for item in groups[-1])) <= tolerance:
            groups[-1].append((distance, position))
        else:
            groups.append([(distance, position)])
    return [
        (
            float(statistics.median(item[0] for item in group)),
            float(statistics.median(item[1] for item in group)),
        )
        for group in groups
    ]


def rope_curve_quality_error(
    calibration: dict, index: int, curve: list[tuple[float, float]] | None = None,
) -> str:
    """Reject physically impossible raw corner interpolation, without refitting.

    A nearly flat monotonic segment can otherwise pass R2 and invert a 0.1deg
    encoder change into several millimetres. Reject the observation/model
    mismatch; do not clamp its slope or silently substitute a different model.
    """
    if calibration.get("geometry_version") != GEOMETRY_VERSION:
        return ""
    if not calibration.get("calibration_source"):
        return f"M{index + 1} 当前CAD标定缺少来源，禁止运行"
    if calibration.get("calibration_source") != "torque_corner_initializer":
        return ""
    try:
        if curve is None:
            distances = [float(v) for v in calibration["distance_samples_mm"][index]]
            positions = [float(v) for v in calibration["position_samples_deg"][index]]
            if len(distances) != len(positions) or len(distances) < 2:
                return f"M{index + 1} 四角曲线数据不完整"
            curve = _coalesce_rope_curve(distances, positions)
        if len(curve) < 2 or any(not math.isfinite(v) for point in curve for v in point):
            return f"M{index + 1} 四角曲线缺失或包含无效数值"
        direction = curve[-1][1] - curve[0][1]
        for (x0, y0), (x1, y1) in zip(curve, curve[1:]):
            delta = y1 - y0
            if x1 - x0 <= 1e-6:
                return f"M{index + 1} 四角曲线不单调，角点/绳路与CAD模型不一致"
            # A small zero-slope plateau is expected when encoder resolution
            # quantises two nearby lengths to the same angle.  It is safe for
            # forward interpolation; only a meaningful reversal is rejected.
            if abs(delta) <= ROPE_CURVE_FLAT_TOLERANCE_DEG:
                continue
            if delta * direction <= 0.0:
                if (
                    (x1 - x0) <= ROPE_CURVE_LOCAL_REVERSAL_DISTANCE_MM
                    and abs(delta) <= ROPE_CURVE_LOCAL_REVERSAL_TOLERANCE_DEG
                ):
                    continue
                return f"M{index + 1} 四角曲线不单调，角点/绳路与CAD模型不一致"
            # Do not reject a measured segment solely because its equivalent
            # radius disagrees with the CAD drum radius.  That radius assumes
            # a fixed fairlead and single winding layer, while this hardware
            # has a smooth drum, changing peel point and stacked cable.  The
            # measured monotonic curve is retained and the discrepancy is
            # reported as a diagnostic warning by the calibration result.
        return ""
    except (KeyError, IndexError, TypeError, ValueError, ZeroDivisionError):
        return f"M{index + 1} 四角曲线数据无效"


def uses_independent_linear_rope_model(calibration: dict) -> bool:
    """Torque corner observations are fit samples, not exact payout knots.

    The live M4 samples contained only 1.2 degrees across 10.8 mm. Passing
    through that pair made a moving cable command nearly stationary. Keep the
    observed samples for diagnostics, but use each motor's global fitted gain
    for both forward and inverse kinematics. Do not add corner residuals back.
    """
    return calibration.get("calibration_source") in {
        "brute_force_four_corner_torque", "safe_four_corner_position_feedback",
    }


def calibrated_rope_curve(
    calibration: dict,
    index: int,
) -> list[tuple[float, float]] | None:
    """Return an explicitly eligible diagnostic payout curve."""
    if uses_independent_linear_rope_model(calibration):
        return None
    try:
        distances = [float(value) for value in calibration["distance_samples_mm"][index]]
        positions = [float(value) for value in calibration["position_samples_deg"][index]]
        # Four corners are the minimum geometric fit. A successful centre
        # tension sweep appends a fifth absolute knot; do not silently reject
        # that datum just because the old implementation assumed exactly four
        # samples.
        if len(distances) != len(positions) or len(distances) < 2:
            return None
        curve = _coalesce_rope_curve(distances, positions)
        if any(not math.isfinite(a) or not math.isfinite(b) for a, b in curve):
            return None
        if len(curve) < 2:
            return None
        if any(curve[n + 1][0] - curve[n][0] <= 1e-6 for n in range(len(curve) - 1)):
            return None
        direction = curve[-1][1] - curve[0][1]
        if abs(direction) <= 1e-6:
            return None
        for n in range(len(curve) - 1):
            delta = curve[n + 1][1] - curve[n][1]
            if abs(delta) <= ROPE_CURVE_FLAT_TOLERANCE_DEG:
                continue
            if delta * direction <= 0.0:
                if (
                    (curve[n + 1][0] - curve[n][0])
                    <= ROPE_CURVE_LOCAL_REVERSAL_DISTANCE_MM
                    and abs(delta) <= ROPE_CURVE_LOCAL_REVERSAL_TOLERANCE_DEG
                ):
                    continue
                return None
        return None if rope_curve_quality_error(calibration, index, curve) else curve
    except (KeyError, IndexError, TypeError, ValueError):
        return None


def internal_model_readiness(calibration: object) -> tuple[bool, str]:
    """Check whether the known-geometry/encoder model may drive motion.

    Four known corners identify the angle/length map for the current winding
    state, but cannot make that map durable after slack changes the layers or the
    ball rotates.  The current smooth-drum build is therefore accepted only in
    the same process that performed the fit and only while all ropes remain
    tensioned.  A deterministic future build may instead pass the persistent
    fairlead, payout, orientation and redundant-closure checks below.
    """
    if not isinstance(calibration, dict):
        return False, "校准结构缺失"
    if calibration.get("valid") is not True:
        return False, str(calibration.get("quality_error") or "请先完成四角几何校准")
    if calibration.get("workspace_calibration_verified") is not True:
        return False, "四角样本尚未通过 110×148mm 球心工作区校验"
    same_tensioned_session = bool(
        calibration.get("session_calibration_mode") == SESSION_CALIBRATION_MODE
        and calibration.get("session_id") == PROCESS_SESSION_ID
        and calibration.get("session_local_verified") is True
        and calibration.get("session_tension_held") is True
    )
    if not same_tensioned_session and not ALLOW_SAVED_GEOMETRY_REUSE_AFTER_STOP:
        # Keep the old strict route available as a compile-time policy switch,
        # but do not use it for this installed smooth-drum controller: the
        # trajectory worker re-anchors from the current encoder positions.
        if calibration.get("fixed_guide_exit_verified") is not True:
            return False, str(
                calibration.get("session_invalid_reason")
                or calibration.get("spool_geometry_reason")
                or "当前卷筒已松绳或服务已重启；请重新执行本次上电四角校准"
            )
        if calibration.get("deterministic_spool_payout_verified") is not True:
            return False, "卷筒尚未证明为恒定半径单层排线；叠层/乱绕状态不能跨松绳复用"
        if calibration.get("orientation_mechanical_decoupling_verified") is not True:
            return False, str(
                calibration.get("orientation_mechanical_reason")
                or "球端连接点姿态未机械解耦；请重新执行本次上电四角校准"
            )
        if (
            calibration.get("redundant_closure_verified") is not True
            and calibration.get("external_pose_verified") is not True
        ):
            return False, str(
                calibration.get("redundant_closure_reason")
                or "尚未通过冗余闭合验收"
            )
    if calibration.get("internal_model_verified") is not True:
        return False, "四角编码器模型尚未完成内部校准"
    if calibration.get("geometry_version") != GEOMETRY_VERSION:
        return False, f"几何模型版本不是 v{GEOMETRY_VERSION}，请重新完成四角校准"
    try:
        slopes = [float(value) for value in calibration.get("slope", [])]
        intercepts = [float(value) for value in calibration.get("intercept", [])]
        r2_values = [float(value) for value in calibration.get("r2", [])]
    except (TypeError, ValueError):
        return False, "四角模型斜率/截距/R² 不完整"
    if len(slopes) != len(MOTOR_IDS) or len(intercepts) != len(MOTOR_IDS) or len(r2_values) != len(MOTOR_IDS):
        return False, "四角模型没有保存四台电机的完整参数"
    if any(not math.isfinite(value) for value in slopes + intercepts + r2_values):
        return False, "四角模型包含非有限参数"
    if any(abs(value) <= 0.05 for value in slopes):
        return False, "存在接近零的绳长斜率"
    if any(value < INTERNAL_MODEL_MIN_R2 for value in r2_values):
        return False, f"四角模型 R² 低于 {INTERNAL_MODEL_MIN_R2:.2f}"
    if uses_independent_linear_rope_model(calibration):
        return True, ""
    for index in range(len(MOTOR_IDS)):
        curve_error = rope_curve_quality_error(calibration, index)
        if curve_error:
            return False, curve_error
    curves = [calibrated_rope_curve(calibration, index) for index in range(len(MOTOR_IDS))]
    if any(curve is None or len(curve) < INTERNAL_MODEL_MIN_CURVE_POINTS for curve in curves):
        return False, "四台绳长曲线点数不足或不单调"
    return True, ""


def is_same_tensioned_session(calibration: object) -> bool:
    return bool(
        isinstance(calibration, dict)
        and calibration.get("session_calibration_mode") == SESSION_CALIBRATION_MODE
        and calibration.get("session_id") == PROCESS_SESSION_ID
        and calibration.get("session_local_verified") is True
        and calibration.get("session_tension_held") is True
    )


def persisted_calibration_structure_ready(calibration: object) -> tuple[bool, str]:
    """Validate the saved model without claiming that cable tension survived."""

    if not isinstance(calibration, dict):
        return False, "没有保存的标定"
    probe = copy.deepcopy(calibration)
    probe["session_calibration_mode"] = SESSION_CALIBRATION_MODE
    probe["session_id"] = PROCESS_SESSION_ID
    probe["session_local_verified"] = True
    probe["session_tension_held"] = True
    probe["internal_model_verified"] = True
    return internal_model_readiness(probe)


def persist_tension_checkpoint(
    calibration: dict,
    telemetries: list[direct.Telemetry],
    source: str,
    xy_mm: object = None,
    *,
    passive_index: int | None = None,
    controller: str | None = None,
    command_positions: object = None,
    force_contraction_mm: object = None,
    publish: bool = True,
) -> dict:
    """Save the encoder state of a verified stationary, tensioned hand-off."""

    if len(telemetries) != len(MOTOR_IDS) or any(
        telemetry.position is None or telemetry.phase_current is None
        for telemetry in telemetries
    ):
        return calibration
    updated = copy.deepcopy(calibration)
    updated["tension_checkpoint_positions_deg"] = [
        round(float(telemetry.position), 3) for telemetry in telemetries
    ]
    updated["tension_checkpoint_currents_ma"] = [
        round(abs(float(telemetry.phase_current)), 1) for telemetry in telemetries
    ]
    updated["tension_checkpoint_source"] = str(source)
    updated["tension_checkpoint_saved_at"] = round(time.time(), 3)
    if controller != TENSION_CHECKPOINT_CONTROLLER_FOUR_POSITION_FORCE:
        updated.pop("tension_checkpoint_command_positions_deg", None)
        updated.pop("tension_checkpoint_force_contraction_mm", None)
    if controller == TENSION_CHECKPOINT_CONTROLLER_FOUR_POSITION_FORCE:
        updated["tension_checkpoint_controller"] = TENSION_CHECKPOINT_CONTROLLER_FOUR_POSITION_FORCE
        updated["tension_checkpoint_passive_motor"] = None
        try:
            commands = [round(float(value), 3) for value in command_positions]
        except (TypeError, ValueError):
            commands = []
        if len(commands) == len(MOTOR_IDS) and all(math.isfinite(value) for value in commands):
            updated["tension_checkpoint_command_positions_deg"] = commands
        try:
            contraction = float(force_contraction_mm)
        except (TypeError, ValueError):
            contraction = float("nan")
        if math.isfinite(contraction):
            updated["tension_checkpoint_force_contraction_mm"] = round(
                max(0.0, min(FORCE_POSITION_CONTRACTION_MAX_MM, contraction)),
                5,
            )
    elif isinstance(passive_index, int) and 0 <= passive_index < len(MOTOR_IDS):
        updated["tension_checkpoint_controller"] = TENSION_CHECKPOINT_CONTROLLER_THREE_PLUS_ONE
        updated["tension_checkpoint_passive_motor"] = MOTOR_IDS[passive_index]
    else:
        updated["tension_checkpoint_controller"] = TENSION_CHECKPOINT_CONTROLLER_FOUR_TORQUE
        updated["tension_checkpoint_passive_motor"] = None
    try:
        checkpoint_xy = [float(xy_mm[0]), float(xy_mm[1])] if isinstance(xy_mm, (list, tuple)) and len(xy_mm) >= 2 else None
    except (TypeError, ValueError):
        checkpoint_xy = None
    if checkpoint_xy is not None and all(math.isfinite(value) for value in checkpoint_xy):
        width, height = workspace_dimensions(updated)
        if -2.0 <= checkpoint_xy[0] <= width + 2.0 and -2.0 <= checkpoint_xy[1] <= height + 2.0:
            updated["tension_checkpoint_xy_mm"] = [round(checkpoint_xy[0], 3), round(checkpoint_xy[1], 3)]
        else:
            updated.pop("tension_checkpoint_xy_mm", None)
    else:
        # Encoder positions and XY must describe the same instant.  Retaining a
        # stale XY beside a fresh encoder checkpoint creates a false incremental
        # origin after a gentle re-tension or full recalibration.
        updated.pop("tension_checkpoint_xy_mm", None)
    persist_calibration(updated)
    if publish:
        with STATE_LOCK:
            STATE["calibration"] = updated
    append_process_log(
        "tension_checkpoint_saved",
        source=str(source),
        positions_deg=updated["tension_checkpoint_positions_deg"],
        phase_current_ma=updated["tension_checkpoint_currents_ma"],
        xy_mm=updated.get("tension_checkpoint_xy_mm"),
        controller=updated["tension_checkpoint_controller"],
        passive_motor=updated["tension_checkpoint_passive_motor"],
        command_positions_deg=updated.get("tension_checkpoint_command_positions_deg"),
        force_contraction_mm=updated.get("tension_checkpoint_force_contraction_mm"),
    )
    return updated


def persisted_checkpoint_tension_evidence(
    calibration: object,
    currents_ma: object,
) -> tuple[bool, str]:
    """Recognize a loaded four-torque or 3+1 stationary checkpoint.

    In 3+1 mode the three position axes may report little phase current once
    their position error reaches zero.  The continuously loaded torque axis,
    together with the encoder checkpoint and stationary gate checked by the
    caller, is the correct evidence that the controller hand-off survived.
    """

    if not isinstance(calibration, dict) or not isinstance(currents_ma, (list, tuple)):
        return False, "张力检查点数据不完整"
    if len(currents_ma) != len(MOTOR_IDS):
        return False, "四台实时电流不完整"
    try:
        currents = [abs(float(value)) for value in currents_ma]
    except (TypeError, ValueError):
        return False, "四台实时电流无效"
    if any(not math.isfinite(value) for value in currents):
        return False, "四台实时电流包含非有限数值"
    controller = calibration.get(
        "tension_checkpoint_controller",
        TENSION_CHECKPOINT_CONTROLLER_FOUR_TORQUE,
    )
    if controller == TENSION_CHECKPOINT_CONTROLLER_THREE_PLUS_ONE:
        try:
            passive_id = int(calibration.get("tension_checkpoint_passive_motor"))
            passive_index = MOTOR_IDS.index(passive_id)
        except (TypeError, ValueError):
            return False, "3+1检查点缺少有效的恒张力电机编号"
        passive_current = currents[passive_index]
        saved_currents = calibration.get("tension_checkpoint_currents_ma")
        saved_passive_current = None
        if isinstance(saved_currents, list) and len(saved_currents) == len(MOTOR_IDS):
            try:
                saved_passive_current = abs(float(saved_currents[passive_index]))
            except (TypeError, ValueError):
                saved_passive_current = None
        required_current = float(PERSISTED_CALIBRATION_MIN_HOLD_CURRENT_MA)
        if saved_passive_current is not None and saved_passive_current > 0:
            # Y42 reports instantaneous phase current.  At the same stationary
            # torque command it can be roughly half the checkpoint sample as
            # electrical angle changes, so compare against a conservative
            # fraction while retaining an absolute disabled-vs-loaded floor.
            required_current = max(
                float(PERSISTED_CALIBRATION_MIN_HYBRID_HOLD_CURRENT_MA),
                min(
                    float(PERSISTED_CALIBRATION_MIN_HOLD_CURRENT_MA),
                    saved_passive_current * PERSISTED_CALIBRATION_MIN_HYBRID_CURRENT_RATIO,
                ),
            )
        if passive_current < required_current:
            return False, (
                f"3+1恒张力轴 M{passive_id} 未持续带载（{passive_current:.0f}mA，"
                f"恢复门槛 {required_current:.0f}mA）"
            )
        return True, f"3+1恒张力轴 M{passive_id} 持续带载 {passive_current:.0f}mA"
    if controller == TENSION_CHECKPOINT_CONTROLLER_FOUR_POSITION_FORCE:
        saved_currents = calibration.get("tension_checkpoint_currents_ma")
        saved = []
        if isinstance(saved_currents, list) and len(saved_currents) == len(MOTOR_IDS):
            try:
                saved = [abs(float(value)) for value in saved_currents]
            except (TypeError, ValueError):
                saved = []
        required = [
            max(
                float(PERSISTED_CALIBRATION_MIN_HYBRID_HOLD_CURRENT_MA),
                min(
                    float(PERSISTED_CALIBRATION_MIN_HOLD_CURRENT_MA),
                    value * 0.35,
                ),
            )
            for value in saved
        ] if len(saved) == len(MOTOR_IDS) else [
            float(PERSISTED_CALIBRATION_MIN_HYBRID_HOLD_CURRENT_MA)
            for _ in MOTOR_IDS
        ]
        failures = [
            MOTOR_IDS[index]
            for index, (value, threshold) in enumerate(zip(currents, required))
            if value < threshold
        ]
        if failures:
            return False, (
                "四位置力位保持未持续带载（低于恢复门槛："
                + "/".join(f"M{motor}" for motor in failures)
                + "）"
            )
        return True, (
            "四位置力位保持持续带载（实时峰值 "
            + "/".join(f"{value:.0f}" for value in currents)
            + "mA）"
        )
    if controller != TENSION_CHECKPOINT_CONTROLLER_FOUR_TORQUE:
        return False, f"未知张力检查点控制模式：{controller}"
    minimum = min(currents)
    if minimum < PERSISTED_CALIBRATION_MIN_HOLD_CURRENT_MA:
        return False, (
            f"四绳力矩保持未持续带载（最低 {minimum:.0f}mA，"
            f"恢复门槛 {PERSISTED_CALIBRATION_MIN_HOLD_CURRENT_MA}mA）"
        )
    return True, f"四绳力矩保持持续带载（最低 {minimum:.0f}mA）"


def calibration_check_deadline(deadline: float) -> None:
    """One wall-clock budget shared by lock acquisition and every query."""

    if STOP_EVENT.is_set():
        raise RuntimeError("用户停止启用已保存标定")
    if time.perf_counter() >= deadline:
        raise TimeoutError(
            f"启用已保存标定超过 {PERSISTED_CALIBRATION_TARGET_SECONDS:.0f} 秒检查预算，请检查通讯后重试；未运行四角"
        )


def calibration_feedback_error(
    values: list[direct.Telemetry],
    *,
    current_limit: int = OPERATING_CURRENT_MAX_MA,
    require_enabled: bool = True,
) -> str | None:
    """Reject incomplete/nonfinite feedback before declaring a valid datum."""

    if len(values) != len(MOTOR_IDS):
        return "四台实时反馈不完整"
    for address, value in zip(MOTOR_IDS, values):
        if value.address != address:
            return "四台反馈电机编号不完整或顺序异常"
        fields = (value.position, value.phase_current, value.rpm, value.temperature, value.flags)
        if any(field is None for field in fields):
            return f"M{address} 位置/电流/转速/温度/状态反馈不完整"
        try:
            finite = all(math.isfinite(float(field)) for field in fields)
        except (TypeError, ValueError, OverflowError):
            finite = False
        if not finite:
            return f"M{address} 实时反馈包含无效数值"
        if require_enabled and not int(value.flags) & 1:
            return f"M{address} 已失能，持续张紧基准已中断；保存参数保留，请重新建立四角基准"
    return safety_error(values, current_limit=current_limit)


def adopt_persisted_tensioned_calibration(
    connection: object,
    *,
    deadline: float | None = None,
) -> tuple[bool, str]:
    try:
        enabled, reason = _check_tensioned_saved_datum(connection, deadline=deadline)
    except Exception as exc:
        invalidate_session_calibration("标定核验失败：" + str(exc))
        raise
    if not enabled:
        invalidate_session_calibration("标定核验失败：" + reason)
    return enabled, reason


def _check_tensioned_saved_datum(
    connection: object,
    *,
    deadline: float | None = None,
) -> tuple[bool, str]:
    """Read-only check of a live datum, including a guarded hot restart resume.

    A saved file alone cannot prove a smooth drum was not rewound.  The resume
    path therefore requires the saved encoder checkpoint plus fresh four-motor
    enabled, stationary, and loaded feedback; a disabled or power-cycled
    mechanism still fails and must run the full four-corner calibration.
    """

    calibration = calibration_data()
    ready, reason = persisted_calibration_structure_ready(calibration)
    if not ready:
        return False, reason
    same_tensioned_session = is_same_tensioned_session(calibration)
    # A process restart does not by itself change the drum datum.  The saved
    # checkpoint is intentionally usable across a hot service restart when the
    # four drives are still enabled, stationary, and carrying the recorded
    # holding load.  A real disable/power loss/slack state still fails below
    # through the live enabled/current/position checks and falls back to a full
    # four-corner calibration.
    if not same_tensioned_session:
        checkpoint_probe = _finite_grid_vector(
            calibration.get("tension_checkpoint_positions_deg"), len(MOTOR_IDS)
        )
        if checkpoint_probe is None:
            return False, (
                "标定参数已保存，但没有可用于热恢复的四电机张力检查点；"
                "请执行一次完整四角标定"
            )
    checkpoint = _finite_grid_vector(calibration.get("tension_checkpoint_positions_deg"), len(MOTOR_IDS))
    if checkpoint is None:
        return False, "保存的编码器检查点缺失或数值无效，不能启用旧零点"
    query_kwargs = {"deadline": deadline} if deadline is not None else {}
    if deadline is not None:
        calibration_check_deadline(deadline)
    values = read_all_reliable(connection, attempts=1, **query_kwargs)
    if deadline is not None:
        calibration_check_deadline(deadline)
    fault = calibration_feedback_error(values)
    if fault:
        return False, fault
    current_observations = [[abs(float(telemetry.phase_current)) for telemetry in values]]
    rpm_observations = [[abs(float(telemetry.rpm)) for telemetry in values]]
    # A single instantaneous phase-current query can land near a sinusoidal
    # minimum even while the torque axis remains loaded. Sample a short 80 ms
    # window; this is read-only and does not move or re-command the mechanism.
    for _ in range(2):
        if deadline is not None:
            calibration_check_deadline(deadline)
        time.sleep(0.04 if deadline is None else min(0.04, max(0.0, deadline - time.perf_counter())))
        probe = read_all_reliable(connection, attempts=1, **query_kwargs)
        if deadline is not None:
            calibration_check_deadline(deadline)
        probe_fault = calibration_feedback_error(probe)
        if probe_fault:
            return False, probe_fault
        if max(abs(float(new.position) - float(old.position)) for new, old in zip(probe, values)) > CALIBRATION_CORNER_POSITION_SETTLE_DEG:
            return False, "检查期间编码器仍在变化，请等待当前动作结束后重试"
        current_observations.append([abs(float(telemetry.phase_current)) for telemetry in probe])
        rpm_observations.append([abs(float(telemetry.rpm)) for telemetry in probe])
    currents = [max(sample[index] for sample in current_observations) for index in range(len(MOTOR_IDS))]
    rpms = [max(sample[index] for sample in rpm_observations) for index in range(len(MOTOR_IDS))]
    deltas = [abs(float(telemetry.position) - reference) for telemetry, reference in zip(values, checkpoint)]
    if max(deltas) > PERSISTED_CALIBRATION_MAX_CHECKPOINT_DELTA_DEG:
        return False, f"编码器已偏离最近张力检查点 {max(deltas):.1f}°，不能自动接管旧零点"
    if max(rpms) > PERSISTED_CALIBRATION_MAX_RESUME_RPM:
        return False, f"电机仍在运动（最高 {max(rpms):.1f}RPM），不接管旧标定"
    loaded, loaded_reason = persisted_checkpoint_tension_evidence(calibration, currents)
    if not loaded:
        return False, loaded_reason
    calibration["session_calibration_mode"] = SESSION_CALIBRATION_MODE
    calibration["session_id"] = PROCESS_SESSION_ID
    calibration["session_local_verified"] = True
    calibration["session_tension_held"] = True
    calibration["session_invalid_reason"] = ""
    calibration["session_resumed_from_saved_model"] = True
    calibration["session_resume_currents_ma"] = [round(value, 1) for value in currents]
    calibration["session_resume_positions_deg"] = [
        round(float(telemetry.position), 3) for telemetry in values
    ]
    calibration = mark_internal_model_ready(calibration)
    if calibration.get("internal_model_verified") is not True:
        return False, str(
            calibration.get("internal_feedback_calibration", {}).get("reason")
            or "保存的标定结构未通过复核"
        )
    with STATE_LOCK:
        STATE["calibration"] = calibration
    # The saved fit and existing motor controller are unchanged by this read.
    append_process_log(
        "calibration_hot_resumed",
        positions_deg=calibration["session_resume_positions_deg"],
        phase_current_ma=calibration["session_resume_currents_ma"],
        rule=calibration.get("tension_checkpoint_controller", TENSION_CHECKPOINT_CONTROLLER_FOUR_TORQUE),
        tension_evidence=loaded_reason,
    )
    return True, "已启用已保存标定；本次连续张紧基准检查通过，原位置控制保持不变"


def mark_internal_model_ready(calibration: dict) -> dict:
    """Normalize the internal readiness flags on a calibration copy."""
    updated = copy.deepcopy(calibration)
    curve_error = next(
        (reason for index in range(len(MOTOR_IDS)) if (reason := rope_curve_quality_error(updated, index))),
        "",
    )
    if curve_error:
        updated["valid"] = False
        updated["quality_error"] = str(updated.get("quality_error") or curve_error)
    # Probe the structural model before deciding the flag itself; otherwise a
    # legacy file with no ``internal_model_verified`` field could never be
    # upgraded on load.
    probe = copy.deepcopy(updated)
    probe["internal_model_verified"] = True
    ready, reason = internal_model_readiness(probe)
    updated["internal_model_verified"] = bool(ready)
    if ready and updated.get("session_id") == PROCESS_SESSION_ID and updated.get("session_local_verified") is True:
        updated["internal_model_source"] = "same_session_tensioned_four_corner"
    elif ready and updated.get("redundant_closure_verified") is True:
        updated["internal_model_source"] = "motor_only_redundant_closure"
    elif ready and updated.get("external_pose_verified") is True:
        updated["internal_model_source"] = "external_pose_geometry_encoder"
    else:
        updated["internal_model_source"] = "none"
    diagnostics = updated.get("internal_feedback_calibration")
    if not isinstance(diagnostics, dict):
        diagnostics = blank_internal_feedback_calibration()
    diagnostics = {**blank_internal_feedback_calibration(), **copy.deepcopy(diagnostics)}
    if ready and diagnostics.get("status") in {"pending", "error"}:
        diagnostics["status"] = "ready"
        diagnostics["verified"] = True
        diagnostics["reason"] = (
            "本次上电四角已知位置已建立，且四绳持续保持张力；失能后自动作废"
            if updated.get("session_id") == PROCESS_SESSION_ID
            else "两定位绳XY解算 + 两张力绳冗余闭合已通过"
            if updated.get("redundant_closure_verified") is True
            else "独立外部位姿模型已通过"
        )
    elif not ready:
        diagnostics["verified"] = False
        if reason:
            diagnostics["reason"] = reason
    updated["internal_feedback_calibration"] = diagnostics
    return updated


def interpolate_curve(
    curve: list[tuple[float, float]],
    query: float,
    extrapolate: bool = False,
) -> float:
    """Linearly interpolate or conservatively extrapolate a monotonic curve."""
    if len(curve) < 2:
        raise ValueError("标定曲线点数不足")
    value = float(query)
    if value <= curve[0][0]:
        pair = (curve[0], curve[1])
    elif value >= curve[-1][0]:
        pair = (curve[-2], curve[-1])
    else:
        pair = next(
            (curve[n], curve[n + 1])
            for n in range(len(curve) - 1)
            if curve[n][0] <= value <= curve[n + 1][0]
        )
    (x0, y0), (x1, y1) = pair
    if not extrapolate:
        value = max(curve[0][0], min(curve[-1][0], value))
    return y0 + (value - x0) * (y1 - y0) / (x1 - x0)


def invert_curve(
    curve: list[tuple[float, float]],
    query: float,
) -> float:
    """Invert a monotonic distance→position curve without losing sign."""
    ordered = sorted((position, distance) for distance, position in curve)
    # A quantised plateau creates duplicate encoder positions.  Collapse those
    # knots before interpolation so the inverse remains finite and deterministic.
    by_position: list[tuple[float, float]] = []
    for position, distance in ordered:
        if by_position and abs(position - by_position[-1][0]) <= ROPE_CURVE_FLAT_TOLERANCE_DEG:
            previous_position, previous_distance = by_position[-1]
            by_position[-1] = (
                (previous_position + position) / 2.0,
                (previous_distance + distance) / 2.0,
            )
        else:
            by_position.append((position, distance))
    if len(by_position) < 2:
        raise ValueError("标定曲线反解点数不足")
    return interpolate_curve(by_position, float(query), extrapolate=True)


def _nominal_motor_degrees(index: int, x: float, y: float, calibration: dict) -> float:
    ax, ay = workspace_anchor_coordinates(calibration)
    length = max(
        0.0,
        math.hypot(float(x) - ax[index], float(y) - ay[index]) - TRAJECTORY_PRETENSION_MM,
    )
    session_pose = calibration.get("_trial_fixed_yaw_datum")
    if isinstance(session_pose, dict):
        # A session-only differential experiment: preserve the observed start
        # exactly, but translate the same rigid attachment geometry thereafter.
        # This is never written into the durable four-corner calibration.
        yaw = float(session_pose["yaw_deg"])
        sx, sy = session_pose["start_xy"]
        here = planar_platform_cable_lengths(float(x), float(y), yaw, calibration)
        zero = planar_platform_cable_lengths(float(x), float(y), 0.0, calibration)
        start = planar_platform_cable_lengths(float(sx), float(sy), yaw, calibration)
        start_zero = planar_platform_cable_lengths(float(sx), float(sy), 0.0, calibration)
        length += here[index] - zero[index] - start[index] + start_zero[index]
    curve = calibrated_rope_curve(calibration, index)
    if curve is not None:
        position = interpolate_curve(curve, length, extrapolate=True)
        # Keep the nonlinear measured curve, but let the existing bounded
        # slope-trim control act as a gain around the calibrated encoder zero.
        # With a zero trim this is bit-for-bit the measured curve; nonzero trim
        # changes only displacement from the per-motor intercept and never
        # changes the geometric cable length or sign.
        trims = normalized_slope_trims(calibration)
        if index < len(trims) and abs(trims[index]) > 1e-9:
            try:
                reference = float(calibration.get("intercept", [])[index])
            except (IndexError, TypeError, ValueError):
                reference = float(curve[0][1])
            position = reference + (position - reference) * (1.0 + trims[index] / 100.0)
        return position
    slopes = effective_slopes(calibration)
    # The old ESP32 path used the four independent linear fits directly.  Keep
    # that robust fallback for drawing: a stale/partial nonlinear diagnostic
    # curve must not turn an otherwise valid saved model into a red stop.
    return float(calibration["intercept"][index]) + slopes[index] * length


def _corner_position_residuals(
    x: float,
    y: float,
    calibration: dict,
) -> list[float] | None:
    """Interpolate the absolute encoder residual measured at the four corners.

    The line fit gives a stable global slope, but its least-squares intercept is
    not guaranteed to pass through every physical corner.  Replaying that
    intercept pushed M4 about 28° past the actually measured corner in the live
    test.  The stored four-corner samples are therefore the absolute position
    anchors; a bilinear residual fixes the corners without turning live motion
    into relative commands or smoothing the requested path.
    """
    if uses_independent_linear_rope_model(calibration):
        return None
    samples = calibration.get("samples")
    if not isinstance(samples, list) or len(samples) != len(MOTOR_IDS):
        return None
    try:
        points = [[float(value) for value in row] for row in samples]
        if any(len(row) != len(MOTOR_IDS) for row in points):
            return None
        ax, ay = workspace_anchor_coordinates(calibration)
        corner_xy = tuple(zip(*workspace_corner_coordinates(calibration)))
        residuals = [
            [
                points[corner][index]
                - _nominal_motor_degrees(index, corner_xy[corner][0], corner_xy[corner][1], calibration)
                for index in range(len(MOTOR_IDS))
            ]
            for corner in range(len(MOTOR_IDS))
        ]
        u = max(0.0, min(1.0, (float(x) - ax[3]) / (ax[2] - ax[3])))
        v = max(0.0, min(1.0, (float(y) - ay[3]) / (ay[0] - ay[3])))
        # Corner order: top-left, top-right, bottom-right, bottom-left.
        return [
            # y=0 is the bottom edge (corner 4 -> corner 3); y=height is the
            # top edge (corner 1 -> corner 2). The old weights were inverted,
            # so a bottom-left request received the top-left M4 correction.
            (residuals[3][index] * (1.0 - u) + residuals[2][index] * u) * (1.0 - v)
            + (residuals[0][index] * (1.0 - u) + residuals[1][index] * u) * v
            for index in range(len(MOTOR_IDS))
        ]
    except (IndexError, TypeError, ValueError, ZeroDivisionError):
        return None


def apply_center_tension_datum(
    calibration: dict,
    level: dict,
    sweep_summary: dict,
) -> tuple[dict | None, str]:
    """Reject equal-current data as an absolute pose datum.

    Equal commanded/observed motor current establishes neither equal cable
    tension nor a known platform pose.  In particular, effective spool radius,
    winding layers, transmission friction and unmeasured platform yaw are all
    absent from the current reading.  Keeping this hard gate in the model layer
    prevents any API/UI regression from reintroducing the circular
    ``encoder -> centre -> encoder`` calibration.
    """
    return None, (
        "已拒绝写入：等电流只表示近似等电机力矩，不能独立确定球心 XY/偏航；"
        "请使用四角已知几何 + 编码器闭环模型，中心测试仅保留为张力/摩擦诊断"
    )


def motor_degrees(index: int, x: float, y: float, calibration: dict | None = None) -> float:
    calibration = calibration if calibration is not None else calibration_data()
    nominal = _nominal_motor_degrees(index, x, y, calibration)
    if all(calibrated_rope_curve(calibration, motor) is not None for motor in range(len(MOTOR_IDS))):
        return nominal
    residuals = _corner_position_residuals(float(x), float(y), calibration)
    # Keep the kinematic transform pure. Tension balancing is applied through
    # the per-motor current cap; position residuals only correct the measured
    # absolute encoder frame captured by the four-corner calibration.
    return nominal + (residuals[index] if residuals is not None else 0.0)


MOTOR_TARGET_XY_MAX_ITERATIONS = 60
MOTOR_TARGET_XY_FINITE_DIFFERENCE_STEP_MM = 0.05
MOTOR_TARGET_XY_STEP_TOLERANCE_MM = 1.0e-5
MOTOR_TARGET_XY_RESIDUAL_TOLERANCE_DEG = 0.20
MOTOR_TARGET_XY_MAX_STEP_MM = 15.0


def motor_targets_to_xy(
    targets: object,
    calibration: dict | None = None,
    *,
    initial_xy: object = None,
    max_iterations: int = MOTOR_TARGET_XY_MAX_ITERATIONS,
    finite_difference_step_mm: float = MOTOR_TARGET_XY_FINITE_DIFFERENCE_STEP_MM,
    step_tolerance_mm: float = MOTOR_TARGET_XY_STEP_TOLERANCE_MM,
    residual_tolerance_deg: float = MOTOR_TARGET_XY_RESIDUAL_TOLERANCE_DEG,
    max_step_mm: float = MOTOR_TARGET_XY_MAX_STEP_MM,
) -> dict:
    """Diagnose XY for motor targets by inverting the exact grid-aware map.

    This is intentionally separate from ``position_to_xy`` and from every
    safety/calibration admission path.  Its forward callable is literally
    ``grid_motor_positions_at(x, y, data)``; therefore corner residuals in
    ``motor_degrees`` and an enabled/valid bilinear grid compensation are both
    included in the same numerical map that creates commanded targets.  The
    report is diagnostic only and never changes ``data`` or its ``valid`` flag.
    """
    data = calibration if calibration is not None else calibration_data()
    try:
        target_positions = [float(value) for value in targets]  # type: ignore[arg-type]
    except (TypeError, ValueError):
        target_positions = []
    if len(target_positions) != len(MOTOR_IDS) or any(not math.isfinite(value) for value in target_positions):
        return {
            "ok": False,
            "valid": False,
            "numerical_valid": False,
            "diagnostic_only": True,
            "finite": False,
            "converged": False,
            "forward_model": "grid_motor_positions_at",
            "target_positions_deg": target_positions if target_positions else None,
            "x_mm": None,
            "y_mm": None,
            "xy_mm": None,
            "predicted_positions_deg": None,
            "residuals_deg": None,
            "residual_rms_deg": None,
            "residual_max_deg": None,
            "calibration_valid": bool(isinstance(data, dict) and data.get("valid") is True),
            "grid_compensation_applied": False,
            "grid_compensation": None,
            "termination": "invalid_target",
            "reason": "四台电机目标必须是有限角度",
        }

    if initial_xy is None:
        seed = (MECHANISM_CENTER_X_MM, MECHANISM_CENTER_Y_MM)
    elif isinstance(initial_xy, dict):
        seed = (initial_xy.get("x_mm", initial_xy.get("x")), initial_xy.get("y_mm", initial_xy.get("y")))
    else:
        seed = initial_xy

    try:
        solved = solve_fixed_plane_xy(
            target_positions,
            lambda query_x, query_y: grid_motor_positions_at(query_x, query_y, data),
            initial_xy=seed,
            bounds=((0.0, WORKSPACE_WIDTH_MM), (0.0, WORKSPACE_HEIGHT_MM)),
            max_iterations=max_iterations,
            finite_difference_step=finite_difference_step_mm,
            step_tolerance=step_tolerance_mm,
            residual_tolerance=residual_tolerance_deg,
            max_step=max_step_mm,
        )
    except Exception as exc:  # Keep a diagnostic API from masking a model defect.
        solved = {
            "ok": False,
            "valid": False,
            "finite": False,
            "converged": False,
            "x": None,
            "y": None,
            "xy": None,
            "predicted": None,
            "residuals": None,
            "residual_rms": None,
            "residual_max": None,
            "iterations": 0,
            "evaluations": 0,
            "step_norm": None,
            "normal_determinant": None,
            "jacobian": None,
            "termination": "solver_exception",
            "reason": f"逆解器异常 {type(exc).__name__}: {exc}",
        }

    result = dict(solved)
    x_value = result.get("x")
    y_value = result.get("y")
    x_mm = float(x_value) if isinstance(x_value, (int, float)) and math.isfinite(float(x_value)) else None
    y_mm = float(y_value) if isinstance(y_value, (int, float)) and math.isfinite(float(y_value)) else None
    predicted = result.get("predicted")
    residuals = result.get("residuals")
    result.update(
        {
            "diagnostic_only": True,
            "forward_model": "grid_motor_positions_at",
            "forward_includes_motor_degrees": True,
            "forward_includes_grid_position_compensation": True,
            "coordinate_frame": "ball_center_workspace",
            "target_positions_deg": list(target_positions),
            "x_mm": x_mm,
            "y_mm": y_mm,
            "xy_mm": [x_mm, y_mm] if x_mm is not None and y_mm is not None else None,
            "predicted_positions_deg": list(predicted) if isinstance(predicted, list) else None,
            "residuals_deg": list(residuals) if isinstance(residuals, list) else None,
            "residual_rms_deg": result.get("residual_rms"),
            "residual_max_deg": result.get("residual_max"),
            # This is an observation of the source object, never an assignment
            # and never a substitute for the model's safety/readiness gates.
            "calibration_valid": bool(isinstance(data, dict) and data.get("valid") is True),
            "grid_compensation_applied": False,
            "grid_compensation": None,
        }
    )
    if x_mm is not None and y_mm is not None:
        try:
            grid_report = interpolate_grid_compensation(
                data.get("grid_compensation") if isinstance(data, dict) else None,
                x_mm,
                y_mm,
            )
            result["grid_compensation"] = grid_report
            result["grid_compensation_applied"] = bool(grid_report.get("apply_allowed") is True)
        except Exception as exc:  # Keep malformed offline maps visible as diagnostics.
            result["grid_compensation"] = {
                "ok": False,
                "apply_allowed": False,
                "reason": f"网格诊断异常 {type(exc).__name__}: {exc}",
            }
    # Keep the numerical result separate from an overall ``valid`` claim.  A
    # mathematically converged diagnostic must not turn an invalid calibration
    # into a motion-ready result.
    try:
        report_tolerance = float(residual_tolerance_deg)
    except (TypeError, ValueError):
        report_tolerance = float("nan")
    result["numerical_valid"] = bool(
        result.get("ok") is True
        and result.get("converged") is True
        and result.get("finite") is True
        and isinstance(result.get("residual_max_deg"), (int, float))
        and math.isfinite(float(result["residual_max_deg"]))
        and math.isfinite(report_tolerance)
        and float(result["residual_max_deg"]) <= report_tolerance
    )
    result["valid"] = bool(result["numerical_valid"] and result["calibration_valid"])
    return result


def encoder_positions_to_lengths(
    positions: list[float], calibration: dict | None = None
) -> list[float] | None:
    """Convert signed encoder positions to calibrated rope lengths in mm."""

    if len(positions) != len(MOTOR_IDS):
        return None
    calibration = calibration if calibration is not None else calibration_data()
    if any(rope_curve_quality_error(calibration, index) for index in range(len(MOTOR_IDS))):
        return None
    try:
        curves = [calibrated_rope_curve(calibration, index) for index in range(len(MOTOR_IDS))]
        if all(curve is not None for curve in curves):
            lengths = [
                max(0.0, invert_curve(curve, float(position)))
                for curve, position in zip(curves, positions)
            ]
            return lengths if all(math.isfinite(length) for length in lengths) else None
        slopes = effective_slopes(calibration)
        intercepts = [float(value) for value in calibration["intercept"]]
        lengths = [
            abs((float(position) - intercepts[index]) / slopes[index] + TRAJECTORY_PRETENSION_MM)
            for index, position in enumerate(positions)
        ]
    except (KeyError, IndexError, TypeError, ValueError, ZeroDivisionError):
        return None
    return lengths if all(math.isfinite(length) for length in lengths) else None


def z_squared_estimates(
    lengths: list[float], x: float, y: float, calibration: dict
) -> list[float] | None:
    """Return one vertical-distance-squared estimate per rope.

    The absolute four-sphere fit contains a small, repeatable per-rope bias
    from encoder quantisation and anchor placement.  Tracking removes that
    fixed bias using the board-contact snapshot captured at startup, instead
    of interpreting it as a lift.  Keeping the individual values also lets
    the caller reject a mixed-time or corrupted four-motor sample.
    """
    if len(lengths) != len(MOTOR_IDS):
        return None
    ax, ay = workspace_anchor_coordinates(calibration)
    values = [
        length * length - (x - anchor_x) ** 2 - (y - anchor_y) ** 2
        for length, anchor_x, anchor_y in zip(lengths, ax, ay)
    ]
    return values if all(math.isfinite(value) for value in values) else None


def absolute_pose_consistency(
    lengths: list[float], x: float, y: float, calibration: dict
) -> dict:
    """Diagnose whether absolute lengths can physically meet at ``x/y``.

    The XY difference equations can still return a plausible point when every
    cable is shorter than its in-plane distance.  Clamping the resulting
    negative ``z²`` to zero hides that contradiction.  Keep XY available for
    diagnostics, but expose the signed median and a separate physical-validity
    flag so an impossible sample can never certify a calibration datum.
    """
    values = z_squared_estimates(lengths, x, y, calibration)
    if values is None:
        return {
            "physically_possible": False,
            "z_squared_mm2": None,
            "median_z_squared_mm2": None,
            "z_fit_spread_mm": None,
        }
    median_value = float(statistics.median(values))
    spread_mm = math.sqrt(max(0.0, max(values) - min(values)))
    return {
        "physically_possible": bool(
            median_value >= -(TRACKING_HEIGHT_NOISE_FLOOR_MM**2)
        ),
        "z_squared_mm2": [round(float(value), 3) for value in values],
        "median_z_squared_mm2": round(median_value, 3),
        "z_fit_spread_mm": round(spread_mm, 3),
    }


def planar_z_squared_bias(x: float, y: float, calibration: dict) -> list[float]:
    """Interpolate the repeatable board-plane residual from the four corners.

    A straight four-corner fit is not perfectly linear because encoder counts
    are quantised and the real anchor geometry has small mounting errors.  The
    resulting residual changes with X/Y; subtracting only the startup value
    therefore made an in-plane move look like a lift.  The saved corner samples
    provide a conservative bilinear correction without smoothing the user's
    actual trajectory.
    """
    zeros = [0.0 for _ in MOTOR_IDS]
    samples = calibration.get("samples")
    if not isinstance(samples, list) or len(samples) != len(MOTOR_IDS):
        return zeros
    ax, ay = workspace_anchor_coordinates(calibration)
    left, right = ax[3], ax[2]
    bottom, top = ay[3], ay[0]
    width, height = right - left, top - bottom
    if width <= 0.0 or height <= 0.0:
        return zeros
    corner_xy = tuple(zip(*workspace_corner_coordinates(calibration)))
    corner_bias: list[list[float]] = []
    try:
        for corner_index, point in enumerate(samples):
            if not isinstance(point, list) or len(point) != len(MOTOR_IDS):
                return zeros
            lengths = encoder_positions_to_lengths([float(value) for value in point], calibration)
            if lengths is None:
                return zeros
            solved = solve_position_from_lengths(lengths, calibration)
            expected_x, expected_y = corner_xy[corner_index]
            if (
                solved is None
                or math.hypot(solved[0] - expected_x, solved[1] - expected_y)
                > PLANAR_CORRECTION_MAX_CORNER_ERROR_MM
                or abs(solved[2]) > PLANAR_CORRECTION_MAX_CORNER_HEIGHT_MM
                or solved[3] > TRACKING_MAX_Z_FIT_SPREAD_MM
            ):
                # These samples are not reliable enough to define a board
                # plane. Returning zero is intentional: relative height then
                # uses the startup contact snapshot and cannot be made worse
                # by an invalid corner interpolation.
                return zeros
            bias = z_squared_estimates(lengths, *corner_xy[corner_index], calibration)
            if bias is None:
                return zeros
            corner_bias.append(bias)
        u = max(0.0, min(1.0, (float(x) - left) / width))
        v = max(0.0, min(1.0, (float(y) - bottom) / height))
        return [
            # Corner order is top-left, top-right, bottom-right, bottom-left;
            # y=0 must therefore use corners 4/3 and y=height corners 1/2.
            ((corner_bias[3][index] * (1.0 - u) + corner_bias[2][index] * u) * (1.0 - v))
            + ((corner_bias[0][index] * (1.0 - u) + corner_bias[1][index] * u) * v)
            for index in range(len(MOTOR_IDS))
        ]
    except (IndexError, TypeError, ValueError, ZeroDivisionError):
        return zeros


def correct_planar_z_squared(values: list[float] | None, x: float, y: float, calibration: dict) -> list[float] | None:
    if values is None or len(values) != len(MOTOR_IDS):
        return None
    bias = planar_z_squared_bias(x, y, calibration)
    corrected = [float(value) - float(offset) for value, offset in zip(values, bias)]
    return corrected if all(math.isfinite(value) for value in corrected) else None


def relative_height_from_z_squared(
    current_z_squared: list[float] | None,
    baseline_z_squared: list[float] | None,
    *,
    baseline_vertical_distance_mm: float | list[float] | tuple[float, ...] | None = None,
) -> dict:
    """Estimate lift from a change in the four ropes' vertical-distance squares.

    ``current_z_squared`` and ``baseline_z_squared`` are the values *after*
    ``correct_planar_z_squared``.  The corner correction removes the board
    plane's absolute residual, so their difference is

    ``delta = (h0 + lift)² - h0² = 2*h0*lift + lift²``.

    The old implementation treated ``sqrt(delta)`` as ``lift``.  That is only
    correct when the cable's baseline vertical separation ``h0`` is exactly
    zero.  This mechanism does not currently measure that separation: the
    drum exit height changes with winding position and the ball attachment is
    above the board.  Therefore a caller must provide an independently known
    per-rope ``baseline_vertical_distance_mm`` before this function publishes a
    millimetre height.  Without it, this function still reports the signed z²
    diagnostic and fit quality, but deliberately returns ``height_mm=None``;
    this prevents an unknown h0 from becoming a fake height or a false pen
    event.

    A board-level sample can legitimately produce a slightly negative median
    after encoder quantisation, so that small negative band is retained for
    diagnostics. The four-rope spread remains a separate confidence test; an
    inconsistent snapshot is never used for pen state changes.
    """
    empty = {
        "valid": False,
        "deltas": None,
        "median_z_squared": None,
        "height_mm": None,
        "height_candidates_mm": None,
        "height_available": False,
        "height_reason": "invalid_input",
        "baseline_vertical_distance_mm": None,
        "spread_mm": float("inf"),
        "confidence": 0.0,
        "z_squared_confidence": 0.0,
    }
    if (
        not isinstance(current_z_squared, list)
        or not isinstance(baseline_z_squared, list)
        or len(current_z_squared) != len(MOTOR_IDS)
        or len(baseline_z_squared) != len(MOTOR_IDS)
    ):
        return empty
    try:
        deltas = [
            float(current) - float(baseline)
            for current, baseline in zip(current_z_squared, baseline_z_squared)
        ]
    except (TypeError, ValueError):
        return empty
    if not all(math.isfinite(value) for value in deltas):
        return empty
    median_z_squared = float(statistics.median(deltas))
    z_squared_spread_mm = math.sqrt(max(0.0, max(deltas) - min(deltas)))
    negative_tolerance = TRACKING_HEIGHT_NOISE_FLOOR_MM**2
    # Retain the old z² guard for the no-h0 diagnostic branch. It is not used
    # to accept a known-h0 height: with four different h0 values, equal lifts
    # produce different z² deltas and this spread measures the wrong quantity.
    z_squared_valid = bool(
        median_z_squared <= TRACKING_MAX_HEIGHT_ESTIMATE_MM**2
        and z_squared_spread_mm <= TRACKING_HEIGHT_ACCEPT_SPREAD_MM
    )
    z_squared_strict_valid = bool(
        z_squared_valid and z_squared_spread_mm <= TRACKING_MAX_Z_FIT_SPREAD_MM
    )

    # A corrected z² delta cannot be converted to millimetres without h0.  A
    # scalar reference is convenient for a symmetric fixed guide; a four-item
    # reference is needed once the four winding heights are measured
    # independently.  Do not silently use sqrt(baseline_z_squared): after the
    # planar correction that value is intentionally close to zero and is not a
    # physical cable/ball vertical separation.
    reference: list[float] | None = None
    reference_reason = "baseline_vertical_distance_unknown"
    if baseline_vertical_distance_mm is not None:
        try:
            if isinstance(baseline_vertical_distance_mm, (int, float)) and not isinstance(
                baseline_vertical_distance_mm, bool
            ):
                scalar = float(baseline_vertical_distance_mm)
                reference = [scalar for _ in MOTOR_IDS]
            elif isinstance(baseline_vertical_distance_mm, (list, tuple)):
                if len(baseline_vertical_distance_mm) != len(MOTOR_IDS):
                    raise ValueError("baseline reference must contain four values")
                reference = [float(value) for value in baseline_vertical_distance_mm]
            else:
                raise ValueError("baseline reference type is invalid")
        except (TypeError, ValueError):
            reference = None
            reference_reason = "baseline_vertical_distance_invalid"
        if reference is not None and (
            not all(math.isfinite(value) and value >= 0.0 for value in reference)
        ):
            reference = None
            reference_reason = "baseline_vertical_distance_invalid"

    height_candidates: list[float] | None = None
    height_mm: float | None = None
    height_radicands: list[float] | None = None
    height_spread_mm = z_squared_spread_mm
    height_valid = False
    if reference is not None:
        # Solve h0 + lift = sqrt(h0² + delta) independently for each rope,
        # then aggregate only after the root. Taking a median of delta first is
        # wrong when the four winding heights differ.
        height_radicands = [
            base_height * base_height + delta
            for base_height, delta in zip(reference, deltas)
        ]
        if any(radicand < -negative_tolerance for radicand in height_radicands):
            # A small negative value can be encoder/rounding noise. A value
            # below that band is physically impossible and must not become a
            # zero-height candidate through sqrt(max(0, ...)).
            reference_reason = "negative_vertical_radicand"
        else:
            height_candidates = [
                max(
                    0.0,
                    math.sqrt(max(0.0, radicand)) - base_height,
                )
                for base_height, radicand in zip(reference, height_radicands)
            ]
            height_spread_mm = max(height_candidates) - min(height_candidates)
            height_valid = bool(
                all(
                    math.isfinite(candidate)
                    and 0.0 <= candidate <= TRACKING_MAX_HEIGHT_ESTIMATE_MM
                    for candidate in height_candidates
                )
                and height_spread_mm <= TRACKING_HEIGHT_ACCEPT_SPREAD_MM
            )
            if height_valid:
                height_mm = float(statistics.median(height_candidates))
                reference_reason = "ok"
            elif height_spread_mm > TRACKING_HEIGHT_ACCEPT_SPREAD_MM:
                reference_reason = "height_spread_exceeded"
            else:
                reference_reason = "height_out_of_range"

    # In the known-h0 branch ``valid`` and ``spread_mm`` refer to physical
    # height candidates. With no h0 they retain the old z² diagnostic meaning
    # for compatibility, while height_valid remains false and height_mm is
    # never published.
    valid = height_valid if reference is not None else z_squared_valid
    strict_valid = bool(
        (height_valid and height_spread_mm <= TRACKING_MAX_Z_FIT_SPREAD_MM)
        if reference is not None
        else z_squared_strict_valid
    )
    height_available = bool(height_valid and height_mm is not None)
    z_squared_confidence = 0.0
    if z_squared_valid:
        spread_confidence = max(
            0.0, 1.0 - z_squared_spread_mm / TRACKING_HEIGHT_ACCEPT_SPREAD_MM
        )
        negative_confidence = 1.0 if median_z_squared >= 0.0 else max(
            0.15,
            1.0
            + median_z_squared
            / max(negative_tolerance, TRACKING_HEIGHT_ACCEPT_SPREAD_MM**2),
        )
        z_squared_confidence = min(1.0, spread_confidence * negative_confidence)
    confidence = 0.0
    if height_available:
        height_spread_confidence = max(
            0.0, 1.0 - height_spread_mm / TRACKING_HEIGHT_ACCEPT_SPREAD_MM
        )
        confidence = min(1.0, height_spread_confidence)
    return {
        "valid": valid,
        "strict_valid": strict_valid,
        "height_valid": height_valid,
        "deltas": deltas,
        "median_z_squared": median_z_squared,
        "height_mm": height_mm if valid else None,
        "height_candidates_mm": height_candidates if valid else None,
        "height_available": bool(height_available and height_mm is not None),
        "height_reason": reference_reason,
        "baseline_vertical_distance_mm": reference,
        "height_radicands_mm2": height_radicands,
        "spread_mm": height_spread_mm,
        "z_squared_spread_mm": z_squared_spread_mm,
        # ``confidence`` is the confidence of a millimetre height, so keep it
        # at zero while h0 is unknown. The z² fit quality remains available
        # separately for diagnostics and logging.
        "confidence": confidence,
        "z_squared_confidence": z_squared_confidence,
    }


def solve_position_from_lengths(lengths: list[float], calibration: dict) -> tuple[float, float, float, float] | None:
    """Solve the ball-center ``X/Y/Z`` from four measured rope lengths.

    With the commanded platform yaw fixed at zero, subtracting each platform
    attachment offset from its cable exit produces an equivalent rectangular
    ball-centre anchor ``Cᵢ=Aᵢ-bᵢ``.  In coordinates relative to the effective
    lower-left anchor, the equations remain::

        l4² = x² + y² + z²
        l3² = (W-x)² + y² + z²
        l2² = (W-x)² + (H-y)² + z²
        l1² = x² + (H-y)² + z²

    Subtracting opposite equations gives the closed form::

        x = (W² + l4² - l3²) / (2W)
        y = (H² + l4² - l1²) / (2H)
        z² = l4² - x² - y²

    Here W/H are the effective-anchor spans, not the 150 mm motor-centre span.
    Global X/Y are restored with the effective lower-left offset.  The user may
    command only the configured 110×148 frame; no second ball-diameter crop is
    applied.  The fourth return value is the spread of the four independent z²
    estimates and diagnoses mixed or inconsistent feedback.
    """

    if len(lengths) != len(MOTOR_IDS):
        return None
    lengths = [abs(float(length)) for length in lengths]
    if not all(math.isfinite(length) for length in lengths):
        return None
    width, height = workspace_dimensions(calibration)
    if width <= 0.0 or height <= 0.0:
        return None
    ax, ay = workspace_anchor_coordinates(calibration)
    left_x, right_x = ax[3], ax[2]
    bottom_y, top_y = ay[3], ay[0]
    span_x = right_x - left_x
    span_y = top_y - bottom_y
    if span_x <= 0.000001 or span_y <= 0.000001:
        return None

    # Use both horizontal and vertical opposite-pair equations.  Averaging
    # the two algebraically equivalent estimates reduces encoder quantisation
    # without smoothing or changing the user's trajectory.
    x_from_bottom = left_x + (lengths[3] ** 2 - lengths[2] ** 2 + span_x ** 2) / (2.0 * span_x)
    x_from_top = left_x + (lengths[0] ** 2 - lengths[1] ** 2 + span_x ** 2) / (2.0 * span_x)
    y_from_left = bottom_y + (lengths[3] ** 2 - lengths[0] ** 2 + span_y ** 2) / (2.0 * span_y)
    y_from_right = bottom_y + (lengths[2] ** 2 - lengths[1] ** 2 + span_y ** 2) / (2.0 * span_y)
    x = (x_from_bottom + x_from_top) / 2.0
    y = (y_from_left + y_from_right) / 2.0
    z_squared = z_squared_estimates(lengths, x, y, calibration)
    if z_squared is None:
        return None
    if not all(math.isfinite(value) for value in z_squared):
        return None
    # A small negative value is normal at z=0 because of encoder quantisation;
    # a large negative value is still represented as z=0 so XY remains useful
    # while the fit spread in the log exposes the bad geometry.
    z_squared_median = statistics.median(z_squared)
    # Near the board, encoder quantisation can turn a true z≈0 sample into a
    # small positive z². Treat that floor as board contact instead of making
    # the pen-height indicator chatter around the lift threshold.
    z = (
        0.0
        if z_squared_median <= TRACKING_HEIGHT_NOISE_FLOOR_MM**2
        else math.sqrt(max(0.0, z_squared_median))
    )
    spread = max(z_squared) - min(z_squared)
    return x, y, z, math.sqrt(max(0.0, spread))


def solve_fixed_yaw_xy_from_pair(
    lengths: list[float] | tuple[float, ...],
    position_indices: list[int] | tuple[int, ...],
    calibration: dict | None = None,
    *,
    initial_xy: object = None,
) -> dict | None:
    """Solve fixed-yaw XY from two position cables and audit the other two.

    The two circle intersections are disambiguated only by the known 110x148
    workspace and trajectory continuity.  Passive-cable lengths never select
    the branch; they remain genuinely independent closure measurements.
    """
    if len(lengths) != len(MOTOR_IDS):
        return None
    try:
        measured = [abs(float(value)) for value in lengths]
        active = tuple(int(index) for index in position_indices)
    except (TypeError, ValueError):
        return None
    if (
        len(active) != 2
        or len(set(active)) != 2
        or any(index not in range(len(MOTOR_IDS)) for index in active)
        or any(not math.isfinite(value) or value <= 0.0 for value in measured)
    ):
        return None
    anchors_x, anchors_y = workspace_anchor_coordinates(calibration)
    first, second = active
    x0, y0 = anchors_x[first], anchors_y[first]
    x1, y1 = anchors_x[second], anchors_y[second]
    dx, dy = x1 - x0, y1 - y0
    distance = math.hypot(dx, dy)
    r0, r1 = measured[first], measured[second]
    if distance <= 1e-9 or distance > r0 + r1 + 1e-7 or distance < abs(r0 - r1) - 1e-7:
        return None
    along = (r0 * r0 - r1 * r1 + distance * distance) / (2.0 * distance)
    height_squared = r0 * r0 - along * along
    if height_squared < -1e-6:
        return None
    height = math.sqrt(max(0.0, height_squared))
    unit_x, unit_y = dx / distance, dy / distance
    base_x, base_y = x0 + along * unit_x, y0 + along * unit_y
    candidates = [
        (base_x - height * unit_y, base_y + height * unit_x),
        (base_x + height * unit_y, base_y - height * unit_x),
    ]
    width, workspace_height = workspace_dimensions(calibration)
    in_workspace = [
        point
        for point in candidates
        if -1e-6 <= point[0] <= width + 1e-6 and -1e-6 <= point[1] <= workspace_height + 1e-6
    ]
    if not in_workspace:
        return None
    try:
        if isinstance(initial_xy, dict):
            reference = (float(initial_xy.get("x_mm", initial_xy.get("x"))), float(initial_xy.get("y_mm", initial_xy.get("y"))))
        elif isinstance(initial_xy, (list, tuple)) and len(initial_xy) >= 2:
            reference = (float(initial_xy[0]), float(initial_xy[1]))
        else:
            reference = (MECHANISM_CENTER_X_MM, MECHANISM_CENTER_Y_MM)
        if not all(math.isfinite(value) for value in reference):
            reference = (MECHANISM_CENTER_X_MM, MECHANISM_CENTER_Y_MM)
    except (TypeError, ValueError):
        reference = (MECHANISM_CENTER_X_MM, MECHANISM_CENTER_Y_MM)
    selected = min(in_workspace, key=lambda point: math.hypot(point[0] - reference[0], point[1] - reference[1]))
    predicted = [
        math.hypot(selected[0] - anchor_x, selected[1] - anchor_y)
        for anchor_x, anchor_y in zip(anchors_x, anchors_y)
    ]
    residuals = [predicted[index] - measured[index] for index in range(len(MOTOR_IDS))]
    passive = [index for index in range(len(MOTOR_IDS)) if index not in active]
    closure = [residuals[index] for index in passive]
    return {
        "x_mm": selected[0],
        "y_mm": selected[1],
        "position_indices": list(active),
        "position_motor_ids": [MOTOR_IDS[index] for index in active],
        "torque_indices": passive,
        "torque_motor_ids": [MOTOR_IDS[index] for index in passive],
        "predicted_lengths_mm": predicted,
        "residuals_mm": residuals,
        "redundant_residuals_mm": closure,
        "closure_rms_mm": math.sqrt(sum(value * value for value in closure) / len(closure)),
        "closure_max_mm": max(abs(value) for value in closure),
        "branch_candidates": [list(point) for point in in_workspace],
    }


def solve_ball_center_xy_from_active_lengths(
    lengths: list[float] | tuple[float, ...],
    active_indices: list[int] | tuple[int, ...],
    calibration: dict | None = None,
    *,
    initial_xy: object = None,
) -> dict | None:
    """Least-squares XY from the three position ropes in session 3+1 mode.

    The passive torque rope is excluded from the estimate so its take-up motion
    cannot feed back as a false position.  This is an encoder-consistency value,
    not an independent measurement of the physical ball centre.
    """

    if len(lengths) != len(MOTOR_IDS):
        return None
    try:
        measured = [abs(float(value)) for value in lengths]
        active = tuple(int(index) for index in active_indices)
    except (TypeError, ValueError):
        return None
    if len(active) != 3 or len(set(active)) != 3 or any(index not in range(len(MOTOR_IDS)) for index in active):
        return None
    if any(not math.isfinite(measured[index]) or measured[index] <= 0.0 for index in active):
        return None
    width, height = workspace_dimensions(calibration)
    try:
        if isinstance(initial_xy, dict):
            x = float(initial_xy.get("x_mm", initial_xy.get("x")))
            y = float(initial_xy.get("y_mm", initial_xy.get("y")))
        elif isinstance(initial_xy, (list, tuple)) and len(initial_xy) >= 2:
            x, y = float(initial_xy[0]), float(initial_xy[1])
        else:
            x, y = MECHANISM_CENTER_X_MM, MECHANISM_CENTER_Y_MM
    except (TypeError, ValueError):
        x, y = MECHANISM_CENTER_X_MM, MECHANISM_CENTER_Y_MM
    x = max(-20.0, min(width + 20.0, x))
    y = max(-20.0, min(height + 20.0, y))
    anchors_x, anchors_y = workspace_anchor_coordinates(calibration)
    converged = False
    determinant = 0.0
    for _ in range(30):
        j00 = j01 = j11 = b0 = b1 = 0.0
        for index in active:
            dx, dy = x - anchors_x[index], y - anchors_y[index]
            distance = math.hypot(dx, dy)
            if distance <= 1e-8:
                return None
            residual = distance - measured[index]
            gx, gy = dx / distance, dy / distance
            j00 += gx * gx
            j01 += gx * gy
            j11 += gy * gy
            b0 += gx * residual
            b1 += gy * residual
        determinant = j00 * j11 - j01 * j01
        if determinant <= 1e-10:
            return None
        step_x = (-j11 * b0 + j01 * b1) / determinant
        step_y = (j01 * b0 - j00 * b1) / determinant
        norm = math.hypot(step_x, step_y)
        if norm > 12.0:
            scale = 12.0 / norm
            step_x *= scale
            step_y *= scale
        x += step_x
        y += step_y
        if math.hypot(step_x, step_y) <= 1e-5:
            converged = True
            break
    residuals = [
        math.hypot(x - anchors_x[index], y - anchors_y[index]) - measured[index]
        for index in active
    ]
    if not all(math.isfinite(value) for value in residuals):
        return None
    return {
        "x_mm": x,
        "y_mm": y,
        "active_indices": list(active),
        "active_motor_ids": [MOTOR_IDS[index] for index in active],
        "residuals_mm": residuals,
        "residual_rms_mm": math.sqrt(sum(value * value for value in residuals) / len(residuals)),
        "residual_max_mm": max(abs(value) for value in residuals),
        "normal_determinant": determinant,
        "converged": converged,
    }


def active_motor_positions_to_xy(
    positions: list[float] | tuple[float, ...],
    active_indices: list[int] | tuple[int, ...],
    calibration: dict | None = None,
    *,
    initial_xy: object = None,
) -> tuple[float, float] | None:
    data = calibration if calibration is not None else calibration_data()
    lengths = encoder_positions_to_lengths(list(positions), data)
    if lengths is None:
        return None
    solved = solve_ball_center_xy_from_active_lengths(
        lengths,
        active_indices,
        data,
        initial_xy=initial_xy,
    )
    if solved is None:
        return None
    return float(solved["x_mm"]), float(solved["y_mm"])


def position_to_xyz(
    positions: list[float], calibration: dict | None = None
) -> tuple[float, float, float, float] | None:
    """Estimate ball-center X/Y and height Z from four encoder positions."""

    if len(positions) != len(MOTOR_IDS):
        return None
    calibration = calibration if calibration is not None else calibration_data()
    lengths = encoder_positions_to_lengths(positions, calibration)
    if lengths is None:
        return None
    return solve_position_from_lengths(lengths, calibration)


def position_to_xy(
    positions: list[float], calibration: dict | None = None
) -> tuple[float, float] | None:
    """Estimate board-plane X/Y without confusing platform yaw with height."""

    pose = motor_positions_to_planar_pose(positions, calibration)
    if pose is None:
        return None
    left, bottom, _, _ = drawable_workspace(calibration)
    return float(pose["x_mm"]) - left, float(pose["y_mm"]) - bottom


def solve_relative_tracking_xy(
    lengths: list[float] | tuple[float, ...],
    baseline_lengths: list[float] | tuple[float, ...],
    anchor_xy: list[float] | tuple[float, ...],
    calibration: dict | None = None,
    *,
    initial_xy: object = None,
) -> dict | None:
    """Recover board-plane XY from rope-length changes around a known anchor.

    Absolute winch length is not observable on the present smooth, unguided
    drums: taking up one slack wrap can change an encoder length without moving
    the ball.  Subtracting the post-tension baseline cancels that fixed offset.
    A small Huber loss then prevents one rope changing layer from dragging the
    whole XY estimate with it.
    """

    data = calibration if calibration is not None else calibration_data()
    try:
        measured = [float(value) for value in lengths]
        baseline = [float(value) for value in baseline_lengths]
        anchor_local = [float(anchor_xy[0]), float(anchor_xy[1])]
    except (IndexError, TypeError, ValueError):
        return None
    if (
        len(measured) != len(MOTOR_IDS)
        or len(baseline) != len(MOTOR_IDS)
        or not all(math.isfinite(value) for value in measured + baseline + anchor_local)
    ):
        return None
    left, bottom, width, height = drawable_workspace(data)
    anchor_global = [anchor_local[0] + left, anchor_local[1] + bottom]
    anchors_x, anchors_y = workspace_anchor_coordinates(data)
    anchor_nominal = [
        math.hypot(anchor_global[0] - anchor_x, anchor_global[1] - anchor_y)
        for anchor_x, anchor_y in zip(anchors_x, anchors_y)
    ]
    observed_delta = [value - reference for value, reference in zip(measured, baseline)]
    try:
        if isinstance(initial_xy, dict):
            x = float(initial_xy.get("x_mm", initial_xy.get("x"))) + left
            y = float(initial_xy.get("y_mm", initial_xy.get("y"))) + bottom
        elif isinstance(initial_xy, (list, tuple)) and len(initial_xy) >= 2:
            x, y = float(initial_xy[0]) + left, float(initial_xy[1]) + bottom
        else:
            x, y = anchor_global
    except (TypeError, ValueError):
        x, y = anchor_global
    x = max(left - 8.0, min(left + width + 8.0, x))
    y = max(bottom - 8.0, min(bottom + height + 8.0, y))
    determinant = 0.0
    residuals = [0.0 for _ in MOTOR_IDS]
    for iteration in range(20):
        j00 = j01 = j11 = b0 = b1 = 0.0
        for index, (anchor_x, anchor_y) in enumerate(zip(anchors_x, anchors_y)):
            dx, dy = x - anchor_x, y - anchor_y
            distance = math.hypot(dx, dy)
            if distance <= 1e-8:
                return None
            residual = (distance - anchor_nominal[index]) - observed_delta[index]
            residuals[index] = residual
            weight = min(1.0, TRACKING_RELATIVE_SOLVER_HUBER_MM / max(1e-9, abs(residual)))
            gx, gy = dx / distance, dy / distance
            j00 += weight * gx * gx
            j01 += weight * gx * gy
            j11 += weight * gy * gy
            b0 += weight * gx * residual
            b1 += weight * gy * residual
        determinant = j00 * j11 - j01 * j01
        if determinant <= 1e-10:
            return None
        step_x = (-j11 * b0 + j01 * b1) / determinant
        step_y = (j01 * b0 - j00 * b1) / determinant
        step_norm = math.hypot(step_x, step_y)
        if step_norm > 8.0:
            scale = 8.0 / step_norm
            step_x *= scale
            step_y *= scale
        x = max(left - 8.0, min(left + width + 8.0, x + step_x))
        y = max(bottom - 8.0, min(bottom + height + 8.0, y + step_y))
        if math.hypot(step_x, step_y) <= 1e-5:
            break
    for index, (anchor_x, anchor_y) in enumerate(zip(anchors_x, anchors_y)):
        residuals[index] = (
            math.hypot(x - anchor_x, y - anchor_y)
            - anchor_nominal[index]
            - observed_delta[index]
        )
    return {
        "x_mm": x - left,
        "y_mm": y - bottom,
        "residuals_mm": residuals,
        "residual_rms_mm": math.sqrt(sum(value * value for value in residuals) / len(residuals)),
        "residual_max_mm": max(abs(value) for value in residuals),
        "normal_determinant": determinant,
        "anchor_xy_mm": list(anchor_local),
    }


def _trajectory_trace_segments_key(name: str) -> str:
    return name + "_segments"


def append_trajectory_trace(name: str, point: tuple[float, float]) -> None:
    """Append a feedback point without joining across invalid samples."""

    try:
        x = float(point[0])
        y = float(point[1])
    except (IndexError, TypeError, ValueError):
        return
    if not math.isfinite(x) or not math.isfinite(y):
        return
    _, _, width, height = drawable_workspace()
    # Keep a tiny physical tolerance for encoder quantisation, then clamp the
    # visible point so an out-of-frame solver result cannot draw past the canvas.
    if x < -2.0 or y < -2.0 or x > width + 2.0 or y > height + 2.0:
        with STATE_LOCK:
            STATE[name + "_gap_pending"] = True
        return
    x = max(0.0, min(width, x))
    y = max(0.0, min(height, y))
    point_value = [round(x, 2), round(y, 2)]
    segments_key = _trajectory_trace_segments_key(name)
    with STATE_LOCK:
        segments = [list(segment) for segment in STATE.get(segments_key, [])]
        gap_pending = bool(STATE.get(name + "_gap_pending", False))
        last = segments[-1][-1] if segments and segments[-1] else None
        jump = math.hypot(point_value[0] - last[0], point_value[1] - last[1]) if last else 0.0
        if gap_pending or not segments or not segments[-1] or jump > TRAJECTORY_TRACE_MAX_JUMP_MM:
            segments.append([])
        segments[-1].append(point_value)
        STATE[name + "_gap_pending"] = False
        total = sum(len(segment) for segment in segments)
        while total > TRAJECTORY_TRACE_MAX_POINTS and segments:
            removed = segments.pop(0)
            total -= len(removed)
        STATE[segments_key] = segments
        STATE[name] = [point for segment in segments for point in segment]


def force_trajectory_trace_endpoint(name: str, point: tuple[float, float]) -> None:
    """Persist the final observed point so the rendered path cannot stop short."""
    try:
        _, _, width, height = drawable_workspace()
        endpoint = [
            round(max(0.0, min(width, float(point[0]))), 2),
            round(max(0.0, min(height, float(point[1]))), 2),
        ]
    except (TypeError, ValueError):
        return
    segments_key = _trajectory_trace_segments_key(name)
    with STATE_LOCK:
        segments = [list(segment) for segment in STATE.get(segments_key, [])]
        if segments and segments[-1]:
            segments[-1][-1] = endpoint
        else:
            segments.append([endpoint])
        STATE[segments_key] = segments
        STATE[name] = [item for segment in segments for item in segment]
        STATE[name + "_gap_pending"] = False


def sampled_trajectory_target_segments(kind: str, spec: dict) -> list[list[list[float]]]:
    """Build only requested drawing strokes for display and error analysis.

    Custom multi-stroke motion also contains fast transfer phases.  Those
    phases are physically executed because this machine has no Z axis, but are
    deliberately absent here so a pen-up transfer can never become a fake
    drawn line or improve/worsen the drawing metric.
    """

    raw_segments = spec.get("draw_segments") if kind == "custom" else None
    if isinstance(raw_segments, list) and raw_segments:
        usable: list[list[tuple[float, float]]] = []
        for raw_segment in raw_segments:
            if not isinstance(raw_segment, list):
                continue
            segment: list[tuple[float, float]] = []
            for item in raw_segment:
                try:
                    point = (float(item[0]), float(item[1]))
                except (IndexError, TypeError, ValueError):
                    continue
                if all(math.isfinite(value) for value in point):
                    segment.append(point)
            if len(segment) >= 2:
                usable.append(segment)
        if usable:
            total_points = sum(len(segment) for segment in usable)
            ratio = min(1.0, TRAJECTORY_TRACE_MAX_POINTS / max(1, total_points))
            output: list[list[list[float]]] = []
            for segment in usable:
                count = min(len(segment), max(2, int(round(len(segment) * ratio))))
                if count >= len(segment):
                    selected = segment
                else:
                    last = len(segment) - 1
                    selected = [segment[round(index * last / (count - 1))] for index in range(count)]
                output.append([[round(point[0], 2), round(point[1], 2)] for point in selected])
            return output

    try:
        source_count = int(spec.get("point_count", 2))
    except (TypeError, ValueError):
        source_count = 2
    count = max(2, min(source_count, TRAJECTORY_TRACE_MAX_POINTS))
    denominator = max(1, count - 1)
    return [[
        [round(float(x), 2), round(float(y), 2)]
        for x, y in (sample_path(kind, index / denominator, spec) for index in range(count))
    ]]


def sampled_trajectory_target_path(kind: str, spec: dict) -> list[list[float]]:
    """Legacy flat target field; segmented consumers must use the new field."""

    return [
        point
        for segment in sampled_trajectory_target_segments(kind, spec)
        for point in segment
    ]


def append_tracking_trace(point: tuple[float, float], *, new_segment: bool = False) -> None:
    """Append a tracked point while preserving pen-up breaks between strokes."""

    with STATE_LOCK:
        segments = [list(segment) for segment in STATE.get("tracking_trace_segments", [])]
        if new_segment or not segments:
            segments.append([])
        segments[-1].append([round(float(point[0]), 2), round(float(point[1]), 2)])
        total = sum(len(segment) for segment in segments)
        while total > TRAJECTORY_TRACE_MAX_POINTS and segments:
            removed = segments.pop(0)
            total -= len(removed)
        STATE["tracking_trace_segments"] = segments
        # Keep the old flat field for external readers; the web UI uses the
        # segmented field so pen-up motion is never joined by a line.
        STATE["tracking_trace"] = [point for segment in segments for point in segment]


def smooth_tracking_point(
    point: tuple[float, float], previous: tuple[float, float] | None
) -> tuple[float, float]:
    """Low-pass only the live tracking display; never alter motor commands."""

    if previous is None:
        return point
    alpha = TRACKING_FILTER_ALPHA
    return (
        previous[0] + alpha * (point[0] - previous[0]),
        previous[1] + alpha * (point[1] - previous[1]),
    )


def limited_position_frame(address: int, direction: int, degrees: float) -> bytes:
    """Build an absolute target using the installed motor's calibrated sign."""

    packet = bytearray((address, 0xCD, direction))
    packet += direct.u16(1000) + direct.u16(1000) + direct.u16(4000)
    packet += direct.u32(round(abs(degrees) * 10.0))
    packet += bytes((0x01, 0x01)) + direct.u16(2000) + bytes((direct.FRAME_END,))
    return bytes(packet)


def four_motor_position_frame(
    targets: list[float],
    rpms: list[float] | None = None,
    current: object = None,
    calibration: dict | None = None,
) -> bytes:
    """Build one 0xAA absolute-position frame for M1..M4 together."""

    if len(targets) != len(MOTOR_IDS):
        raise ValueError("四电机合帧必须包含 4 个目标位置")
    speeds = rpms if rpms is not None else [1000.0 for _ in MOTOR_IDS]
    if len(speeds) != len(MOTOR_IDS):
        raise ValueError("四电机合帧必须包含 4 个目标转速")
    current_limits = normalized_trajectory_current_limits(
        trajectory_current_limit() if current is None else current
    )
    positive_directions = encoder_positive_directions(calibration)
    packet = bytearray((0x00, 0xAA, 0x00, 0x00))
    for index, address in enumerate(MOTOR_IDS):
        rpm = max(1.0, min(TRAJECTORY_MAX_RPM, float(speeds[index])))
        target = float(targets[index])
        driver_target = target if positive_directions[index] == 0 else -target
        packet += bytes((address, 0xCB, 1 if driver_target < 0.0 else 0))
        packet += direct.u16(round(rpm * 10.0)) + direct.u32(round(abs(target) * 10.0))
        packet += bytes((0x01, 0x00)) + direct.u16(current_limits[index]) + bytes((direct.FRAME_END,))
    length = len(packet) + 1  # Full on-wire length, including the final 6B.
    packet[2] = (length >> 8) & 0xFF
    packet[3] = length & 0xFF
    packet.append(direct.FRAME_END)
    if len(packet) != 61:
        raise RuntimeError(f"四电机 0xAA 合帧长度异常: {len(packet)} 字节")
    return bytes(packet)


def four_motor_torque_frame(
    currents_ma: object,
    *,
    torque_slope: int = TRACKING_TORQUE_SLOPE_MA_PER_S,
    torque_max_rpm: float = TRACKING_TORQUE_MAX_RPM,
) -> bytes:
    """Build one synchronized 0xAA frame containing four X/0xC5 commands."""

    if isinstance(currents_ma, (list, tuple)):
        raw_currents = list(currents_ma)
    else:
        raw_currents = [currents_ma for _ in MOTOR_IDS]
    if len(raw_currents) != len(MOTOR_IDS):
        raise ValueError("四电机张力合帧必须包含 4 个电流")
    try:
        currents = [int(round(float(value))) for value in raw_currents]
    except (TypeError, ValueError):
        raise ValueError("四电机张力电流无效") from None
    if any(not 0 <= value <= OPERATING_CURRENT_MAX_MA for value in currents):
        raise ValueError(f"四电机张力电流必须在 0..{OPERATING_CURRENT_MAX_MA}mA")
    packet = bytearray((0x00, 0xAA, 0x00, 0x00))
    directions = pull_directions()
    for index, address in enumerate(MOTOR_IDS):
        packet += direct.torque_frame(
            address,
            directions[index],
            currents[index],
            int(torque_slope),
            float(torque_max_rpm),
        )
    length = len(packet) + 1  # Full on-wire length, including the final 6B.
    packet[2] = (length >> 8) & 0xFF
    packet[3] = length & 0xFF
    packet.append(direct.FRAME_END)
    expected_length = 5 + 11 * len(MOTOR_IDS)
    if len(packet) != expected_length:
        raise RuntimeError(f"四电机张力 0xAA 合帧长度异常: {len(packet)} 字节")
    return bytes(packet)


def smooth_four_torque_transition(
    connection: object,
    start_currents_ma: object,
    target_currents_ma: object,
    *,
    label: str,
) -> list[int]:
    """Synchronously cross-fade four torque targets without a stop/release gap."""

    start = [
        max(TRACKING_MIN_CURRENT, min(TRACKING_MAX_CURRENT, int(round(float(value)))))
        for value in list(start_currents_ma)
    ]
    target = [
        max(TRACKING_MIN_CURRENT, min(TRACKING_MAX_CURRENT, int(round(float(value)))))
        for value in list(target_currents_ma)
    ]
    if len(start) != len(MOTOR_IDS) or len(target) != len(MOTOR_IDS):
        raise ValueError("四电机张力渐变必须包含 4 个电流")
    values = list(start)
    step_count = 0
    while True:
        if STOP_EVENT.is_set():
            raise RuntimeError(f"用户停止{label}")
        next_values = [
            slewed_current(value, desired, TRACKING_START_CURRENT_STEP_MA)
            for value, desired in zip(values, target)
        ]
        send_fast(connection, four_motor_torque_frame(next_values))
        values = next_values
        step_count += 1
        if step_count % 10 == 0 or values == target:
            feedback = read_all_reliable(connection, attempts=2)
            fault = safety_error(feedback, current_limit=OPERATING_CURRENT_MAX_MA)
            if fault:
                raise RuntimeError(f"{label}：{fault}")
        if values == target:
            break
        time.sleep(TRACKING_START_CURRENT_DWELL_SECONDS)
    append_process_log(
        "four_torque_transition",
        label=label,
        from_current_ma=start,
        to_current_ma=target,
        steps=step_count,
        slope_ma_per_s=TRACKING_TORQUE_SLOPE_MA_PER_S,
        max_rpm=TRACKING_TORQUE_MAX_RPM,
    )
    return values


def three_position_one_torque_frame(
    targets: list[float] | tuple[float, ...],
    passive_index: int,
    passive_current_ma: object,
    rpms: list[float] | tuple[float, ...] | None = None,
    position_current: object = None,
    *,
    torque_slope: int = 2000,
    torque_max_rpm: float = 1000.0,
) -> bytes:
    """Build one synchronized 0xAA frame for the motor-only 3+1 controller.

    Three 0xCB records constrain the rigid platform's x/y/yaw pose.  The omitted
    motor receives a 0xC5 pull-torque command, maintaining positive cable
    tension without adding a fourth incompatible position constraint.  Its
    encoder remains available as the independent closure/calibration channel.
    """
    if len(targets) != len(MOTOR_IDS):
        raise ValueError("3+1 合帧必须包含 4 个几何目标")
    try:
        passive = int(passive_index)
        passive_current = int(round(float(passive_current_ma)))
    except (TypeError, ValueError):
        raise ValueError("3+1 张力电机或电流无效") from None
    if passive not in range(len(MOTOR_IDS)):
        raise ValueError("3+1 张力电机索引必须是 0..3")
    return mixed_position_torque_frame(
        targets,
        tuple(index for index in range(len(MOTOR_IDS)) if index != passive),
        [passive_current if index == passive else 0 for index in range(len(MOTOR_IDS))],
        rpms,
        position_current,
        torque_slope=torque_slope,
        torque_max_rpm=torque_max_rpm,
    )


def mixed_position_torque_frame(
    targets: list[float] | tuple[float, ...],
    position_indices: list[int] | tuple[int, ...],
    torque_currents_ma: object,
    rpms: list[float] | tuple[float, ...] | None = None,
    position_current: object = None,
    *,
    torque_slope: int = 2000,
    torque_max_rpm: float = 1000.0,
) -> bytes:
    """Build one synchronized frame with an arbitrary position/torque split."""
    if len(targets) != len(MOTOR_IDS):
        raise ValueError("混合合帧必须包含 4 个几何目标")
    try:
        position_set = {int(index) for index in position_indices}
    except (TypeError, ValueError):
        raise ValueError("位置电机索引无效") from None
    if not position_set or len(position_set) >= len(MOTOR_IDS) or any(
        index not in range(len(MOTOR_IDS)) for index in position_set
    ):
        raise ValueError("混合控制必须包含 1..3 台位置电机")
    if isinstance(torque_currents_ma, (list, tuple)):
        raw_torque = list(torque_currents_ma)
    else:
        raw_torque = [torque_currents_ma for _ in MOTOR_IDS]
    if len(raw_torque) != len(MOTOR_IDS):
        raise ValueError("混合合帧必须包含 4 个张力电流槽位")
    try:
        torque_currents = [int(round(float(value))) for value in raw_torque]
    except (TypeError, ValueError):
        raise ValueError("张力电流无效") from None
    if any(not 0 <= value <= OPERATING_CURRENT_MAX_MA for value in torque_currents):
        raise ValueError(f"张力电流必须在 0..{OPERATING_CURRENT_MAX_MA}mA")
    speeds = list(rpms) if rpms is not None else [1000.0 for _ in MOTOR_IDS]
    if len(speeds) != len(MOTOR_IDS):
        raise ValueError("混合合帧必须包含 4 个目标转速")
    current_limits = normalized_trajectory_current_limits(
        trajectory_current_limit() if position_current is None else position_current
    )
    packet = bytearray((0x00, 0xAA, 0x00, 0x00))
    for index, address in enumerate(MOTOR_IDS):
        if index not in position_set:
            packet += direct.torque_frame(
                address,
                pull_directions()[index],
                torque_currents[index],
                torque_slope,
                torque_max_rpm,
            )
            continue
        rpm = max(1.0, min(TRAJECTORY_MAX_RPM, float(speeds[index])))
        target = float(targets[index])
        packet += bytes((address, 0xCB, absolute_position_direction(index, target)))
        packet += direct.u16(round(rpm * 10.0)) + direct.u32(round(abs(target) * 10.0))
        packet += bytes((0x01, 0x00)) + direct.u16(current_limits[index]) + bytes((direct.FRAME_END,))
    length = len(packet) + 1  # Full on-wire length, including the final 6B.
    packet[2] = (length >> 8) & 0xFF
    packet[3] = length & 0xFF
    packet.append(direct.FRAME_END)
    expected_length = 5 + 14 * len(position_set) + 11 * (len(MOTOR_IDS) - len(position_set))
    if len(packet) != expected_length:
        raise RuntimeError(f"混合位置/张力 0xAA 合帧长度异常: {len(packet)} 字节")
    return bytes(packet)


def two_position_two_torque_frame(
    targets: list[float] | tuple[float, ...],
    position_indices: list[int] | tuple[int, ...],
    torque_currents_ma: object,
    rpms: list[float] | tuple[float, ...] | None = None,
    position_current: object = None,
    *,
    torque_slope: int = 2000,
    torque_max_rpm: float = 1000.0,
) -> bytes:
    """Build the selected fixed-yaw 2-position + 2-torque control frame."""
    try:
        active = tuple(int(index) for index in position_indices)
    except (TypeError, ValueError):
        raise ValueError("2+2 位置电机索引无效") from None
    if len(active) != 2 or len(set(active)) != 2:
        raise ValueError("2+2 必须恰好选择两台不同的位置电机")
    return mixed_position_torque_frame(
        targets,
        active,
        torque_currents_ma,
        rpms,
        position_current,
        torque_slope=torque_slope,
        torque_max_rpm=torque_max_rpm,
    )


def hybrid_trajectory_frame(
    x: float,
    y: float,
    next_x: float,
    next_y: float,
    lookahead: float,
    passive_index: int,
    passive_current_ma: object,
    position_current: object = None,
    calibration: dict | None = None,
    target_overrides: list[float] | tuple[float, ...] | None = None,
) -> bytes:
    """Build a 3-position + 1-torque Cartesian trajectory frame."""
    targets_now = grid_motor_positions_at(x, y, calibration)
    targets_next = grid_motor_positions_at(next_x, next_y, calibration)
    if target_overrides is not None:
        if len(target_overrides) != len(MOTOR_IDS):
            raise ValueError("3+1 轨迹目标修正必须包含四台电机")
        overridden_next = [float(value) for value in target_overrides]
        # Session-local winding/yaw offsets are absolute-position corrections,
        # not motion. Apply the same correction to the segment start before
        # deriving RPM; otherwise a constant 20 degree offset is incorrectly
        # treated as 20 degrees of travel on every 10 ms control tick.
        corrections = [
            override - nominal
            for override, nominal in zip(overridden_next, targets_next)
        ]
        targets_now = [
            target + correction
            for target, correction in zip(targets_now, corrections)
        ]
        targets_next = overridden_next
    speeds = [
        trajectory_target_rpm(current_target, target, lookahead)
        for current_target, target in zip(targets_now, targets_next)
    ]
    return three_position_one_torque_frame(
        targets_next,
        passive_index,
        passive_current_ma,
        speeds,
        position_current,
        torque_max_rpm=HYBRID_PATH_PASSIVE_MAX_RPM,
    )


def trajectory_target_rpm(
    current: float,
    target: float,
    lookahead: float,
    profile: str | None = None,
) -> float:
    """Convert one Cartesian target segment to the X-firmware RPM field."""
    # A small 10 ms position segment must use its own velocity. A fixed
    # 1000 RPM on every manual-path point produces a reach/wait command
    # profile even if the serial frame cadence is exactly 100 Hz.
    rpm_ceiling = min(TRAJECTORY_MAX_RPM, ESP32_SMOOTH_MOTION_RPM) if profile == ESP32_SMOOTH_PROFILE else TRAJECTORY_MAX_RPM
    if lookahead <= 0.0001:
        return 1.0
    return max(
        1.0,
        min(
            rpm_ceiling,
            abs(float(target) - float(current))
            / (float(lookahead) * 6.0)
            * TRAJECTORY_FEEDFORWARD,
        ),
    )


def update_encoder_feedback_lead(
    lead_deg: list[float],
    nominal_targets: list[float] | tuple[float, ...],
    feedback_positions: tuple[float, ...] | list[float] | None,
    feedback_sampled_at: float | None,
    now: float | None = None,
) -> list[float]:
    """Return a bounded motor-space lead from one fresh complete feedback set.

    The absolute target remains the geometric inverse-kinematic point.  This
    helper only adds a small catch-up term when the motor encoder is trailing
    that target, which removes a loaded-rope lag without introducing a second
    Cartesian reference or waiting at every path subdivision.  A stale,
    incomplete, or non-finite snapshot causes a smooth decay back to zero.
    """
    count = len(MOTOR_IDS)
    try:
        current = [float(value) for value in lead_deg]
    except (TypeError, ValueError):
        current = []
    if len(current) != count:
        current = [0.0 for _ in MOTOR_IDS]
    try:
        targets = [float(value) for value in nominal_targets]
    except (TypeError, ValueError):
        targets = []
    try:
        positions = [float(value) for value in feedback_positions] if feedback_positions is not None else []
    except (TypeError, ValueError):
        positions = []
    clock = time.perf_counter() if now is None else float(now)
    try:
        sampled_at = float(feedback_sampled_at) if feedback_sampled_at is not None else float("nan")
    except (TypeError, ValueError):
        sampled_at = float("nan")
    fresh = bool(
        len(targets) == count
        and len(positions) == count
        and math.isfinite(sampled_at)
        and all(math.isfinite(value) for value in targets + positions)
    )
    if fresh:
        age = clock - sampled_at
        # perf_counter/monotonic share the same Windows clock in practice, but
        # tolerate a few milliseconds of cross-clock ordering uncertainty.
        fresh = -0.05 <= age <= TRAJECTORY_ENCODER_LEAD_MAX_AGE_SECONDS
    if fresh:
        desired = [
            max(
                -TRAJECTORY_ENCODER_LEAD_MAX_DEG,
                min(
                    TRAJECTORY_ENCODER_LEAD_MAX_DEG,
                    (target - position) * TRAJECTORY_ENCODER_LEAD_GAIN,
                ),
            )
            for target, position in zip(targets, positions)
        ]
    else:
        desired = [0.0 for _ in MOTOR_IDS]
    rate = max(0.05, float(TRAJECTORY_ENCODER_LEAD_RATE_DEG_PER_TICK))
    updated = [
        previous + max(-rate, min(rate, target - previous))
        for previous, target in zip(current, desired)
    ]
    return [
        round(max(-TRAJECTORY_ENCODER_LEAD_MAX_DEG, min(TRAJECTORY_ENCODER_LEAD_MAX_DEG, value)), 4)
        for value in updated
    ]


def trajectory_frame(
    x: float,
    y: float,
    next_x: float,
    next_y: float,
    lookahead: float,
    current_limits: object = None,
    calibration: dict | None = None,
    target_overrides: list[float] | tuple[float, ...] | None = None,
    profile: str | None = None,
) -> bytes:
    """Build one 0xAA frame containing all four motor targets.

    The frame is written once per control tick.  Do not replace this with
    four 0xCB writes: that introduces up to one control tick of skew between
    the first and last motor.
    """
    targets = []
    speeds = []
    current_targets = grid_motor_positions_at(x, y, calibration)
    targets_with_grid = grid_motor_positions_at(next_x, next_y, calibration)
    if target_overrides is not None:
        if len(target_overrides) != len(MOTOR_IDS):
            raise ValueError("轨迹目标修正必须包含四台电机")
        overridden_targets = [float(value) for value in target_overrides]
        corrections = [
            override - nominal
            for override, nominal in zip(overridden_targets, targets_with_grid)
        ]
        current_targets = [
            target + correction
            for target, correction in zip(current_targets, corrections)
        ]
        targets_with_grid = overridden_targets
    for index, address in enumerate(MOTOR_IDS):
        current_target = current_targets[index]
        target = targets_with_grid[index]
        rpm = trajectory_target_rpm(current_target, target, lookahead, profile=profile)
        # 0xCB encodes positions in 0.1 degree and speed in 0.1 RPM.
        # A rounded 0.1 degree step at 1 RPM takes 16.67 ms, longer than
        # one 10 ms tick. Keep the continuous speed estimate, but ensure
        # its on-wire value can cover the actual quantized displacement.
        if lookahead > 0.0001:
            encoded_delta = abs(round(target * 10.0) - round(current_target * 10.0)) / 10.0
            encoded_speed_floor = math.ceil(encoded_delta / (lookahead * 6.0) * 10.0 - 1e-9) / 10.0
            rpm = min(TRAJECTORY_MAX_RPM, max(rpm, encoded_speed_floor))
        targets.append(target)
        speeds.append(rpm)
    return four_motor_position_frame(
        targets,
        speeds,
        current_limits,
        calibration=calibration,
    )


def _send_fast_sync(connection: object, packet: bytes) -> None:
    """Write one already-packed frame without waiting for an application ACK.

    Do not reset/drain the RX buffer on every 0xAA tick: on Windows some
    CH340 adapters make that ioctl take several milliseconds, collapsing the
    100 Hz schedule.  The next acknowledged query clears stale RX first.
    """
    started_monotonic_ns = time.perf_counter_ns()
    direction_mode = getattr(connection, "_y42_direction_mode", "auto")
    if direction_mode == "rts-high":
        connection.rts = True
    elif direction_mode == "rts-low":
        connection.rts = False
    connection.write(packet)
    # In ``auto`` direction mode the USB-RS485 adapter owns DE/RE and the
    # write call already places the complete frame in the driver queue. A
    # per-tick flush waits for the wire to drain and was the largest avoidable
    # source of deadline misses at 100 Hz. Keep flush only for explicit RTS
    # direction control, where it is required before toggling the line.
    if direction_mode in {"rts-high", "rts-low"}:
        connection.flush()
    if direction_mode in {"rts-high", "rts-low"}:
        baudrate = float(getattr(connection, "baudrate", direct.DEFAULT_BAUD) or direct.DEFAULT_BAUD)
        time.sleep(max(0.001, len(packet) * 10.0 / baudrate))
        connection.rts = direction_mode == "rts-low"
    manual_test_emit(
        "high_rate_tx_frame",
        record_channel="raw_serial",
        port=str(getattr(connection, "port", "") or ""),
        baud=int(getattr(connection, "baudrate", direct.DEFAULT_BAUD) or direct.DEFAULT_BAUD),
        direction_mode=str(direction_mode),
        raw_packet_hex=packet.hex(),
        packet_bytes=len(packet),
        writer_thread=threading.current_thread().name,
        started_monotonic_ns=started_monotonic_ns,
        completed_monotonic_ns=time.perf_counter_ns(),
    )


def next_trajectory_deadline(previous_deadline, write_started, write_finished, interval):
    deadline = previous_deadline + interval
    if deadline <= write_finished:
        deadline = max(write_finished, write_started + interval)
    return deadline


class TrajectoryFrameWriter:
    """Queue position frames so USB write latency cannot stretch the 10 ms tick."""

    def __init__(self, connection: object) -> None:
        self.connection = connection
        self.frames: queue.Queue[bytes | None] = queue.Queue(maxsize=8)
        self.pending = 0
        self.pending_lock = threading.Lock()
        self.flushed = threading.Event()
        self.flushed.set()
        self.sent_frames = 0
        self.first_sent_at: float | None = None
        self.last_sent_at: float | None = None
        self.error: BaseException | None = None
        self.closed = False
        self.thread = threading.Thread(
            target=self._run,
            name="y42-trajectory-frame-writer",
            daemon=True,
        )
        self.thread.start()

    def _run(self) -> None:
        next_start = time.perf_counter()
        while True:
            packet = self.frames.get()
            try:
                if packet is None:
                    return
                if STOP_EVENT.is_set() and self.error is None:
                    self.error = RuntimeError("急停已请求，取消尚未发送的轨迹目标")
                if self.error is None:
                    # The producer may briefly queue several frames after a
                    # Windows scheduler hiccup.  Drain them at the same 100 Hz
                    # wire cadence instead of bursting them back-to-back and
                    # making the physical ball jump through old targets.
                    while True:
                        remaining = next_start - time.perf_counter()
                        if remaining <= 0.0:
                            break
                        if remaining > 0.002:
                            time.sleep(min(0.001, remaining - 0.001))
                    if STOP_EVENT.is_set():
                        raise RuntimeError("急停已请求，取消尚未发送的轨迹目标")
                    write_started_at = time.perf_counter()
                    _send_fast_sync(self.connection, packet)
                    sent_at = time.perf_counter()
                    with self.pending_lock:
                        self.sent_frames += 1
                        self.first_sent_at = self.first_sent_at or sent_at
                        self.last_sent_at = sent_at
                    # Space starts, not completions. A 15ms blocking write
                    # already consumed the 10ms period; adding another 10ms
                    # after it caused a needless 25ms gap. This also prevents
                    # a late wakeup from triggering back-to-back catch-up.
                    next_start = next_trajectory_deadline(next_start, write_started_at, sent_at, TRAJECTORY_INTERVAL)
            except BaseException as exc:  # propagate on the next submit/flush
                self.error = exc
            finally:
                if packet is not None:
                    with self.pending_lock:
                        self.pending = max(0, self.pending - 1)
                        if self.pending == 0:
                            self.flushed.set()

    def submit(self, packet: bytes) -> None:
        if self.closed:
            raise RuntimeError("轨迹帧写入器已关闭")
        if self.error is not None:
            raise RuntimeError(f"串口位置帧写入失败：{self.error}")
        # Bounded backpressure preserves every ordinary target while preventing
        # arbitrary seconds of stale commands from accumulating behind USB.
        with self.pending_lock:
            self.pending += 1
            self.flushed.clear()
        try:
            self.frames.put(packet, timeout=0.25)
        except queue.Full:
            with self.pending_lock:
                self.pending -= 1
                if self.pending == 0:
                    self.flushed.set()
            raise RuntimeError("串口发送持续阻塞，轨迹暂停；未跳过目标继续运动") from None

    def flush(self) -> None:
        if not self.flushed.wait(timeout=2.0):
            raise RuntimeError("轨迹发送收尾超时，不能宣布绘制完成")
        if self.error is not None:
            raise RuntimeError(f"串口位置帧写入失败：{self.error}")

    def actual_hz(self) -> float:
        with self.pending_lock:
            first = self.first_sent_at
            last = self.last_sent_at
            count = self.sent_frames
        if first is None or last is None or count < 2:
            return 0.0
        return (count - 1) / max(0.001, last - first)

    def close(self) -> None:
        if self.closed:
            return
        try:
            self.flush()
        except BaseException as exc:
            self.error = exc
        finally:
            self.closed = True
            self.frames.put(None, timeout=0.25)
            self.thread.join(timeout=1.0)
        if self.error is not None:
            raise RuntimeError(f"串口位置帧写入失败：{self.error}")


def send_fast(connection: object, packet: bytes) -> None:
    writer = getattr(connection, "_y42_trajectory_writer", None)
    if writer is not None:
        writer.submit(packet)
        return
    _send_fast_sync(connection, packet)


def chaikin_path(vertices: list[tuple[float, float]], *, closed: bool, passes: int = 2) -> list[tuple[float, float]]:
    """Round polygon/polyline corners without overshooting the calibrated rectangle."""
    current = list(vertices)
    if len(current) < 2:
        return current
    for _ in range(max(1, passes)):
        if closed:
            unique = current[:-1] if current[0] == current[-1] else current
            rounded: list[tuple[float, float]] = []
            for index, point in enumerate(unique):
                following = unique[(index + 1) % len(unique)]
                rounded.append((point[0] * 0.75 + following[0] * 0.25, point[1] * 0.75 + following[1] * 0.25))
                rounded.append((point[0] * 0.25 + following[0] * 0.75, point[1] * 0.25 + following[1] * 0.75))
            current = rounded + [rounded[0]]
        else:
            rounded = [current[0]]
            for first, second in zip(current, current[1:]):
                rounded.extend(
                    (
                        (first[0] * 0.75 + second[0] * 0.25, first[1] * 0.75 + second[1] * 0.25),
                        (first[0] * 0.25 + second[0] * 0.75, first[1] * 0.25 + second[1] * 0.75),
                    )
                )
            rounded.append(current[-1])
            current = rounded
    return current


def resample_polyline(
    path: list[tuple[float, float]],
    spacing_mm: float = CUSTOM_PATH_RESAMPLE_STEP_MM,
    max_points: int = CUSTOM_PATH_MAX_POINTS,
) -> list[tuple[float, float]]:
    """Insert evenly spaced points without changing the drawn polyline."""
    if len(path) < 2:
        return list(path)
    spacing = max(0.05, float(spacing_mm))
    limit = max(2, int(max_points))
    if len(path) > limit:
        raise ValueError("原始点数超过上限；禁止抽点改变手绘轨迹")
    desired = [max(1, int(math.ceil(math.hypot(b[0]-a[0], b[1]-a[1]) / spacing)))
               for a, b in zip(path, path[1:])]
    if sum(desired) > limit - 1:
        # Spend the insertion budget proportionally. Every original vertex,
        # including repeated coordinates, remains at its exact input value.
        budget = limit - len(path)
        extras = [steps - 1 for steps in desired]
        total = sum(extras)
        allocated = [budget * extra // total for extra in extras]
        remaining = budget - sum(allocated)
        order = sorted(range(len(extras)), key=lambda i: -(budget * extras[i] % total))
        for index in order[:remaining]:
            allocated[index] += 1
        desired = [1 + extra for extra in allocated]
    result = [tuple(path[0])]
    for (first, second), steps in zip(zip(path, path[1:]), desired):
        dx = second[0] - first[0]
        dy = second[1] - first[1]
        for index in range(1, steps):
            fraction = index / steps
            result.append((first[0] + dx * fraction, first[1] + dy * fraction))
        result.append(tuple(second))
    return result


def path_with_cumulative(path: list[tuple[float, float]]) -> tuple[list[tuple[float, float]], list[float]]:
    cumulative = [0.0]
    for first, second in zip(path, path[1:]):
        cumulative.append(cumulative[-1] + math.hypot(second[0] - first[0], second[1] - first[1]))
    return path, cumulative


def time_parameterized_path(
    path: list[tuple[float, float]],
    cruise_speed_mm_s: float,
    acceleration_mm_s2: float = CUSTOM_PATH_ACCELERATION_MM_S2,
    *,
    start_speed_mm_s: float | None = None,
    end_speed_mm_s: float | None = None,
) -> tuple[list[float], list[float]]:
    """Return cumulative seconds and per-point speeds without changing XY.

    A forward/backward pass enforces the Cartesian acceleration bound.  At a
    geometric corner the admissible speed falls with turn angle; this keeps an
    exact drawn corner while avoiding an impossible instantaneous direction
    reversal.  The caller has already resampled ordinary strokes, so the speed
    ramps contain enough points to be represented at the 100 Hz command clock.
    """

    if len(path) < 2:
        return [0.0 for _ in path], [0.0 for _ in path]
    cruise = max(0.1, float(cruise_speed_mm_s))
    acceleration = max(1.0, float(acceleration_mm_s2))
    # Reserve vector acceleration for both changing speed and changing
    # direction. Bounding only the tangential component misses curved nodes.
    component_acceleration = acceleration / math.sqrt(2.0)
    minimum = min(cruise, CUSTOM_PATH_CORNER_MIN_SPEED_MM_S)
    lengths = [
        math.hypot(second[0] - first[0], second[1] - first[1])
        for first, second in zip(path, path[1:])
    ]
    arc_distance = [0.0]
    for distance in lengths:
        arc_distance.append(arc_distance[-1] + distance)
    speeds = [cruise for _ in path]
    speeds[0] = minimum if start_speed_mm_s is None else max(0.0, min(cruise, float(start_speed_mm_s)))
    speeds[-1] = minimum if end_speed_mm_s is None else max(0.0, min(cruise, float(end_speed_mm_s)))
    threshold = math.radians(CUSTOM_PATH_CORNER_THRESHOLD_DEG)
    for index in range(1, len(path) - 1):
        # Scalar speed continuity is insufficient at a literal sharp corner:
        # changing direction at 20 mm/s in one 10 ms frame demanded almost
        # 3000 mm/s² in the recorded rectangle despite the 450 limit. Reach
        # zero at genuine corners (not at collinear subdivision points), then
        # accelerate away immediately. The original XY vertices stay intact.
        incoming_local = (path[index][0]-path[index-1][0], path[index][1]-path[index-1][1])
        outgoing_local = (path[index+1][0]-path[index][0], path[index+1][1]-path[index][1])
        local_norm = math.hypot(*incoming_local) * math.hypot(*outgoing_local)
        if local_norm > 1e-12:
            local_cosine = max(-1.0, min(1.0, sum(a*b for a,b in zip(incoming_local,outgoing_local))/local_norm))
            local_turn = math.acos(local_cosine)
            if local_turn >= threshold:
                speeds[index] = 0.0
                continue
            if local_turn > 1e-8:
                adjacent_span = min(math.hypot(*incoming_local),math.hypot(*outgoing_local))
                turn_factor = 2.0*math.sin(local_turn/2.0)
                speeds[index] = min(speeds[index],
                                    math.sqrt(component_acceleration*adjacent_span/turn_factor),
                                    component_acceleration*TRAJECTORY_INTERVAL/turn_factor)
        before = index - 1
        while (
            before > 0
            and arc_distance[index] - arc_distance[before]
            < CUSTOM_PATH_CORNER_LOOKAHEAD_MM
        ):
            before -= 1
        after = index + 1
        while (
            after < len(path) - 1
            and arc_distance[after] - arc_distance[index]
            < CUSTOM_PATH_CORNER_LOOKAHEAD_MM
        ):
            after += 1
        incoming = (
            path[index][0] - path[before][0],
            path[index][1] - path[before][1],
        )
        outgoing = (
            path[after][0] - path[index][0],
            path[after][1] - path[index][1],
        )
        first_length = math.hypot(*incoming)
        second_length = math.hypot(*outgoing)
        if first_length <= 1e-9 or second_length <= 1e-9:
            speeds[index] = minimum
            continue
        cosine = max(
            -1.0,
            min(
                1.0,
                (incoming[0] * outgoing[0] + incoming[1] * outgoing[1])
                / (first_length * second_length),
            ),
        )
        turn = math.acos(cosine)
        if turn >= threshold:
            corner_ratio = max(0.0, 1.0 - turn / math.pi) ** 2
            speeds[index] = min(speeds[index], max(minimum, cruise * corner_ratio))
    for index, distance in enumerate(lengths, start=1):
        speeds[index] = min(
            speeds[index],
            math.sqrt(max(0.0, speeds[index - 1] ** 2 + 2.0 * component_acceleration * distance)),
        )
    for index in range(len(path) - 2, -1, -1):
        distance = lengths[index]
        speeds[index] = min(
            speeds[index],
            math.sqrt(max(0.0, speeds[index + 1] ** 2 + 2.0 * component_acceleration * distance)),
        )
    cumulative = [0.0]
    for index, distance in enumerate(lengths):
        average_speed = (speeds[index] + speeds[index + 1]) * 0.5
        if average_speed > 1e-9:
            segment_seconds = distance / average_speed
        elif distance > 1e-9:
            # A very short stroke/transfer may have just two zero-speed nodes.
            # Use a symmetric triangular profile, not an artificial 0.1 mm/s
            # crawl. Its peak speed and acceleration obey the same limits.
            segment_seconds = max(2.0 * math.sqrt(distance / component_acceleration), 2.0 * distance / cruise)
        else:
            segment_seconds = 0.0
        cumulative.append(cumulative[-1] + segment_seconds)
    return cumulative, speeds


def constant_speed_path_profile(
    path: list[tuple[float, float]],
    cruise_speed_mm_s: float,
) -> tuple[list[float], list[float]]:
    """Time a literal polyline like the proven ESP32 drawing loop.

    The ESP32 firmware sent the next absolute point at a fixed cadence and
    let the driver's position loop chase it.  There is no host-side
    rest-to-rest stop at each inserted point and no corner cutting.  Keeping
    every original vertex while using an arc-length clock reproduces that
    behaviour and leaves the four-motor frame builder in charge of the actual
    position command speed.
    """

    if len(path) < 2:
        return [0.0 for _ in path], [0.0 for _ in path]
    cruise = max(0.1, float(cruise_speed_mm_s))
    cumulative = [0.0]
    for first, second in zip(path, path[1:]):
        cumulative.append(
            cumulative[-1] + math.hypot(second[0] - first[0], second[1] - first[1]) / cruise
        )
    # The command stream itself derives the instantaneous motor speed from
    # the next segment.  Equal speeds make sample_cumulative_path linear in
    # time and, unlike exact_vertex_profile, do not pause at every subdivision.
    return cumulative, [cruise for _ in path]


def sample_cumulative_path(
    path: list[tuple[float, float]],
    cumulative: list[float],
    u: float,
    speeds: list[float] | None = None,
) -> tuple[float, float]:
    if not path:
        return 0.0, 0.0
    if len(path) == 1 or not cumulative or cumulative[-1] <= 1e-12:
        return tuple(path[0])
    target = max(0.0, min(1.0, u)) * cumulative[-1]
    high = 1
    while high < len(cumulative) and cumulative[high] < target:
        high += 1
    if high >= len(path):
        return tuple(path[-1])
    if abs(target - cumulative[high]) <= 1e-10:
        return tuple(path[high])
    low = high - 1
    if abs(target - cumulative[low]) <= 1e-10:
        return tuple(path[low])
    span = cumulative[high] - cumulative[low]
    fraction = (target - cumulative[low]) / span if span > 1e-12 else 0.0
    if speeds is not None and len(speeds) == len(path) and span > 1e-12:
        start_speed, end_speed = float(speeds[low]), float(speeds[high])
        speed_sum = start_speed + end_speed
        if speed_sum > 1e-9:
            # Integrate constant tangential acceleration on this segment.
            # Linear interpolation in time would jump immediately to the
            # average speed even when the boundary node explicitly says zero.
            fraction = (2.0 * start_speed * fraction + (end_speed - start_speed) * fraction * fraction) / speed_sum
        else:
            # Match the zero-to-zero triangular segment above, including the
            # two-node case without adding or moving the operator's vertices.
            fraction = 2.0 * fraction * fraction if fraction <= 0.5 else 1.0 - 2.0 * (1.0 - fraction) ** 2
        fraction = max(0.0, min(1.0, fraction))
    return (
        path[low][0] + (path[high][0] - path[low][0]) * fraction,
        path[low][1] + (path[high][1] - path[low][1]) * fraction,
    )


def custom_motion_phase(u: float, spec: dict) -> dict:
    """Return XY plus draw/travel metadata for one custom-motion instant."""

    phases = spec.get("motion_segments")
    if not isinstance(phases, list) or not phases:
        point = sample_cumulative_path(spec.get("path", []), spec.get("cumulative", []), u)
        return {"xy": point, "drawing": True, "stroke_index": 0, "kind": "draw"}
    try:
        duration = float(spec.get("duration_ms", 0.0)) / 1000.0
    except (TypeError, ValueError):
        duration = 0.0
    if duration <= 0.0:
        duration = max(float(phase.get("end_s", 0.0)) for phase in phases)
    target_time = max(0.0, min(1.0, float(u))) * max(0.0, duration)
    selected = phases[-1]
    for phase in phases:
        if target_time <= float(phase.get("end_s", 0.0)) + 1e-9:
            selected = phase
            break
    start_s = float(selected.get("start_s", 0.0))
    end_s = float(selected.get("end_s", start_s))
    local_u = (target_time - start_s) / max(1e-9, end_s - start_s)
    point = sample_cumulative_path(
        selected.get("path", []),
        selected.get("cumulative", []),
        max(0.0, min(1.0, local_u)),
        selected.get("speeds"),
    )
    return {
        "xy": point,
        "drawing": selected.get("kind") in {"draw", "draw_hold"},
        "stroke_index": int(selected.get("stroke_index", 0)),
        "kind": str(selected.get("kind", "draw")),
    }


def plan_custom_motion_segments(
    draw_segments: list[list[tuple[float, float]]],
    draw_speed_mm_s: float,
    travel_speed_mm_s: float,
    *, exact_vertices: bool = False, control_tick_s: float = 0.01,
    profile: str | None = None,
) -> tuple[list[dict], list[float], float, float]:
    """Plan exact strokes and pen-up transfers, with no fixed handoff dwell.

    Four-position modes do not switch a passive motor. Each physical phase
    instead reaches zero speed at its exact endpoint, then immediately ramps
    into the next phase under its existing acceleration limit. Raw strokes are
    not rounded or joined into ink.
    """
    phases: list[dict] = []
    profile_speeds: list[float] = []
    elapsed = 0.0
    travel_total = 0.0
    previous_endpoint: tuple[float, float] | None = None

    def append_phase(kind: str, stroke_index: int, path: list[tuple[float, float]], cruise: float, acceleration: float) -> None:
        nonlocal elapsed
        if exact_vertices:
            # Conservative literal-polyline mode: each node is an exact clock
            # endpoint. Rest-to-rest motion stays on its original line segment;
            # only timing changes. A triangle of duration T obeys peak v=2d/T
            # and a=4d/T^2. Rounding T up cannot increase either limit.
            from y42_exact_path import exact_vertex_profile
            cumulative, speeds, _ = exact_vertex_profile(path, cruise, acceleration, tick=control_tick_s)
        else:
            cumulative, speeds = time_parameterized_path(
                path, cruise, acceleration, start_speed_mm_s=0.0, end_speed_mm_s=0.0,
            )
        duration = cumulative[-1]
        phases.append({
            "kind": kind, "stroke_index": stroke_index, "path": path,
            "cumulative": cumulative, "speeds": speeds,
            "acceleration_mm_s2": acceleration, "cruise_speed_mm_s": cruise,
            "start_s": elapsed, "end_s": elapsed + duration,
        })
        elapsed += duration
        profile_speeds.extend(speeds)

    for stroke_index, segment in enumerate(draw_segments):
        if previous_endpoint is not None:
            transfer_distance = math.hypot(segment[0][0] - previous_endpoint[0], segment[0][1] - previous_endpoint[1])
            if transfer_distance > 1e-9:
                transfer = resample_polyline(
                    [previous_endpoint, segment[0]],
                    spacing_mm=CUSTOM_PATH_RESAMPLE_STEP_MM,
                    max_points=CUSTOM_PATH_MAX_POINTS,
                )
                append_phase("travel", stroke_index, transfer, travel_speed_mm_s, CUSTOM_PATH_TRAVEL_ACCELERATION_MM_S2)
                travel_total += transfer_distance
        append_phase("draw", stroke_index, segment, draw_speed_mm_s, CUSTOM_PATH_ACCELERATION_MM_S2)
        previous_endpoint = segment[-1]
    return phases, profile_speeds, elapsed, travel_total


def precompute_position_trajectory(kind, spec, calibration, offsets, current_limits, interval):
    """Freeze geometry, speed and all four-axis bytes before the first draw tick."""
    duration = max(0.028, float(spec["duration_ms"]) / 1000.0)
    plan = []
    frame = 0
    while frame * interval < duration:
        if STOP_EVENT.is_set():
            raise RuntimeError("用户停止轨迹预计算")
        elapsed = frame * interval
        following = min(duration, elapsed + interval)
        x, y = sample_path(kind, elapsed / duration, spec)
        nx, ny = sample_path(kind, following / duration, spec)
        phase = trajectory_motion_phase(kind, following / duration, spec)
        targets = [v + offsets[i] for i, v in enumerate(grid_motor_positions_at(nx, ny, calibration))]
        packet = trajectory_frame(x, y, nx, ny, max(0.001, following-elapsed), current_limits, calibration,
                                  target_overrides=targets, profile=spec.get("motion_profile"))
        plan.append((packet, (nx, ny), phase["drawing"], phase["stroke_index"], phase["kind"]))
        frame += 1
    return plan


def trajectory_motion_phase(kind: str, u: float, spec: dict) -> dict:
    if kind == "custom" and spec.get("motion_segments"):
        return custom_motion_phase(u, spec)
    return {"xy": sample_path(kind, u, spec), "drawing": True, "stroke_index": 0, "kind": "draw"}


def sample_path(kind: str, u: float, spec: dict) -> tuple[float, float]:
    u = max(0.0, min(1.0, u))
    outer_width = float(spec.get("width", WORKSPACE_WIDTH_MM))
    outer_height = float(spec.get("height", WORKSPACE_HEIGHT_MM))
    width = float(spec.get("draw_width", outer_width))
    height = float(spec.get("draw_height", outer_height))
    origin_x = float(spec.get("origin_x", 0.0))
    origin_y = float(spec.get("origin_y", 0.0))

    def shift(point: tuple[float, float]) -> tuple[float, float]:
        return point[0] + origin_x, point[1] + origin_y

    center_x = width / 2.0
    center_y = height / 2.0
    if kind == "custom" and spec.get("motion_segments"):
        return tuple(custom_motion_phase(u, spec)["xy"])
    if kind == "circle":
        angle = 2.0 * math.pi * u
        radius = min(width, height) * 0.40
        return shift((center_x + radius * math.cos(angle), center_y + radius * math.sin(angle)))
    if kind in {"triangle", "rectangle", "square", "cross", "line", "snake", "custom"} and spec.get("path") and spec.get("cumulative"):
        point = sample_cumulative_path(spec["path"], spec["cumulative"], u)
        return point if spec.get("path_absolute") else shift(point)
    if kind == "triangle":
        vertices = ((center_x, height * 0.10), (width * 0.90, height * 0.85), (width * 0.10, height * 0.85))
        q = min(2.999999, u * 3.0)
        segment = int(q)
        fraction = q - segment
        a = vertices[segment]
        b = vertices[(segment + 1) % 3]
        return shift((a[0] + (b[0] - a[0]) * fraction, a[1] + (b[1] - a[1]) * fraction))
    if kind in {"rectangle", "cross"}:
        if kind == "rectangle":
            vertices = (
                (0.0, 0.0),
                (width, 0.0),
                (width, height),
                (0.0, height),
                (0.0, 0.0),
            )
        else:
            vertices = (
                (width * 0.18, height * 0.18),
                (width * 0.82, height * 0.82),
                (center_x, center_y),
                (width * 0.82, height * 0.18),
                (width * 0.18, height * 0.82),
            )
        # Preserve the exact last vertex. The old epsilon made the final
        # cross/rectangle sample technically short of its endpoint.
        q = min(float(len(vertices) - 1), u * (len(vertices) - 1))
        segment = int(q)
        if segment >= len(vertices) - 1:
            return shift(vertices[-1])
        fraction = q - segment
        a = vertices[segment]
        b = vertices[segment + 1]
        return shift((a[0] + (b[0] - a[0]) * fraction, a[1] + (b[1] - a[1]) * fraction))
    return sample_cumulative_path(spec["path"], spec["cumulative"], u)


def draw_targets_reached(values: list[direct.Telemetry], targets: list[float]) -> bool:
    return all(
        t.position is not None
        and t.rpm is not None
        and abs(t.position - target) <= TRAJECTORY_POSITION_TOLERANCE
        and abs(t.rpm) <= 15.0
        for t, target in zip(values, targets)
    )


def selected_targets_reached(
    values: list[direct.Telemetry],
    targets: list[float],
    indices: list[int] | tuple[int, ...],
) -> bool:
    """Check only the position-controlled motors in a mixed 3+1 frame."""

    try:
        selected = tuple(int(index) for index in indices)
    except (TypeError, ValueError):
        return False
    if (
        len(values) != len(MOTOR_IDS)
        or len(targets) != len(MOTOR_IDS)
        or not selected
        or any(index not in range(len(MOTOR_IDS)) for index in selected)
    ):
        return False
    return all(
        values[index].position is not None
        and values[index].rpm is not None
        and abs(float(values[index].position) - float(targets[index]))
        <= TRAJECTORY_POSITION_TOLERANCE
        and abs(float(values[index].rpm)) <= 15.0
        for index in selected
    )


def selected_max_target_error(
    values: list[direct.Telemetry],
    targets: list[float],
    indices: list[int] | tuple[int, ...],
) -> float | None:
    try:
        selected = tuple(int(index) for index in indices)
        errors = [
            abs(float(values[index].position) - float(targets[index]))
            for index in selected
            if values[index].position is not None
        ]
    except (IndexError, TypeError, ValueError):
        return None
    return max(errors) if len(errors) == len(selected) and errors else None


def active_target_xy_near_and_stopped(
    values: list[direct.Telemetry],
    target_xy: tuple[float, float],
    active_indices: list[int] | tuple[int, ...],
    calibration: dict,
    *,
    initial_xy: object = None,
    position_offsets_deg: object = None,
) -> tuple[bool, tuple[float, float] | None]:
    """Session-local XY check using only the three position ropes.

    The fourth encoder is excluded because its torque-mode take-up is not a
    position constraint.  The returned XY remains an encoder/model consistency
    estimate, not an independent measurement of the physical ball centre.
    """

    try:
        active = tuple(int(index) for index in active_indices)
    except (TypeError, ValueError):
        return False, None
    if (
        len(values) != len(MOTOR_IDS)
        or len(active) != 3
        or any(index not in range(len(MOTOR_IDS)) for index in active)
        or any(values[index].position is None or values[index].rpm is None for index in active)
        or any(abs(float(values[index].rpm)) > 15.0 for index in active)
        or any(item.position is None for item in values)
    ):
        return False, None
    positions = [float(item.position) for item in values]
    if position_offsets_deg is not None:
        try:
            offsets = [float(value) for value in position_offsets_deg]
        except (TypeError, ValueError):
            return False, None
        if len(offsets) != len(MOTOR_IDS) or any(not math.isfinite(value) for value in offsets):
            return False, None
        positions = [position - offsets[index] for index, position in enumerate(positions)]
    estimate = active_motor_positions_to_xy(
        positions,
        active,
        calibration,
        initial_xy=initial_xy if initial_xy is not None else target_xy,
    )
    if estimate is None:
        return False, None
    return (
        math.hypot(estimate[0] - target_xy[0], estimate[1] - target_xy[1])
        <= TRAJECTORY_SESSION_XY_SETTLE_TOLERANCE,
        estimate,
    )


def trajectory_feedback_target_reached(
    positions: tuple[float | None, ...] | None,
    rpms: tuple[float | None, ...] | None,
    flags: tuple[int | None, ...] | None,
    targets: list[float],
) -> bool:
    """Require the manual's position-reached bit before advancing a target.

    The 0x43 stream is the only feedback path that can support this check
    without inserting a blocking query into the 100 Hz command clock. Position
    and speed bounds remain alongside the driver's Prf_TF bit so a stale or
    contradictory status sample cannot authorize the next target.
    """
    if not positions or not rpms or not flags or len(positions) != len(targets):
        return False
    if len(rpms) != len(targets) or len(flags) != len(targets):
        return False
    return all(
        position is not None
        and rpm is not None
        and status is not None
        and abs(float(position) - target) <= TRAJECTORY_POSITION_TOLERANCE
        and abs(float(rpm)) <= 15.0
        and bool(int(status) & TRAJECTORY_TARGET_REACHED_FLAG)
        for position, rpm, status, target in zip(positions, rpms, flags, targets)
    )


def exact_xy_residual_motor_correction(
    target_xy: tuple[float, float] | list[float],
    actual_xy: tuple[float, float] | list[float],
    calibration: dict,
    *,
    max_step_deg: float = TRAJECTORY_RESIDUAL_CORRECTION_MAX_DEG,
    max_total_deg: float = TRAJECTORY_RESIDUAL_CORRECTION_TOTAL_MAX_DEG,
    total_used_deg: float = 0.0,
) -> dict:
    """Convert one raw Cartesian residual into a bounded absolute correction.

    The requested point is left untouched.  We evaluate the same nonlinear,
    per-corner/grid-aware inverse map at the requested point and at the fresh
    measured point; their difference is the motor correction for the next
    absolute frame.  There is no EMA, spline, corner rounding, or path rewrite.
    """
    try:
        tx, ty = float(target_xy[0]), float(target_xy[1])
        ax, ay = float(actual_xy[0]), float(actual_xy[1])
        step_limit = abs(float(max_step_deg))
        total_limit = abs(float(max_total_deg))
        used = max(0.0, float(total_used_deg))
    except (TypeError, ValueError, IndexError):
        return {"ok": False, "correction_deg": [0.0] * len(MOTOR_IDS), "reason": "XY残差无效"}
    if not all(math.isfinite(v) for v in (tx, ty, ax, ay, step_limit, total_limit, used)):
        return {"ok": False, "correction_deg": [0.0] * len(MOTOR_IDS), "reason": "XY残差非有限"}
    if step_limit <= 0.0 or total_limit <= 0.0 or used >= total_limit:
        return {"ok": True, "correction_deg": [0.0] * len(MOTOR_IDS), "residual_mm": math.hypot(tx - ax, ty - ay), "saturated": True}
    try:
        target_positions = grid_motor_positions_at(tx, ty, calibration)
        actual_positions = grid_motor_positions_at(ax, ay, calibration)
        raw = [float(t) - float(a) for t, a in zip(target_positions, actual_positions)]
    except (TypeError, ValueError, IndexError, KeyError, ZeroDivisionError):
        return {"ok": False, "correction_deg": [0.0] * len(MOTOR_IDS), "reason": "XY残差无法映射到四轴"}
    if len(raw) != len(MOTOR_IDS) or any(not math.isfinite(value) for value in raw):
        return {"ok": False, "correction_deg": [0.0] * len(MOTOR_IDS), "reason": "XY残差映射非有限"}
    remaining = max(0.0, total_limit - used)
    correction = [max(-step_limit, min(step_limit, value)) for value in raw]
    correction_norm = sum(abs(value) for value in correction)
    if correction_norm > remaining > 0.0:
        scale = remaining / correction_norm
        correction = [value * scale for value in correction]
    elif remaining <= 0.0:
        correction = [0.0 for _ in correction]
    return {
        "ok": True,
        "correction_deg": correction,
        "raw_correction_deg": raw,
        "residual_mm": math.hypot(tx - ax, ty - ay),
        "saturated": bool(remaining <= 1e-9 or any(abs(value) >= step_limit - 1e-9 for value in correction)),
    }


def trajectory_feedback_target_reached_xy(
    positions: tuple[float | None, ...] | None,
    rpms: tuple[float | None, ...] | None,
    flags: tuple[int | None, ...] | None,
    targets: list[float],
    actual_xy: tuple[float, float] | None,
    target_xy: tuple[float, float],
    *,
    xy_tolerance_mm: float = TRAJECTORY_TARGET_XY_TOLERANCE_MM,
    allow_cartesian_fallback: bool = False,
) -> bool:
    """Require a settled four-axis target and fresh Cartesian error.

    At 115200 baud the X firmware often leaves the per-motor ``reached`` bit
    low while the motor is already stationary at the commanded centre.  The
    live worker may opt into a bounded Cartesian fallback for that bus; the
    public/default helper remains strict for offline safety tests.
    """
    if actual_xy is None:
        return False
    xy_error = math.hypot(
        float(actual_xy[0]) - float(target_xy[0]),
        float(actual_xy[1]) - float(target_xy[1]),
    )
    if xy_error > float(xy_tolerance_mm):
        if not allow_cartesian_fallback or xy_error > max(float(xy_tolerance_mm), 3.0):
            return False
    if trajectory_feedback_target_reached(positions, rpms, flags, targets):
        return True
    if not allow_cartesian_fallback or not positions or not rpms or len(positions) != len(targets):
        return False
    return all(
        position is not None
        and rpm is not None
        and abs(float(rpm)) <= 15.0
        for position, rpm in zip(positions, rpms)
    )


def draw_targets_near_and_stopped(values: list[direct.Telemetry], targets: list[float]) -> bool:
    """Return true only for a small, bounded residual error with no motion.

    This is a hand-off condition, not a replacement for the normal 8°
    reached check.  It covers the common closed-loop case where one motor
    reports zero RPM a little short of the absolute target after the cable
    tension settles.  A large error still times out and triggers the normal
    safe shutdown.
    """
    return len(values) == len(targets) == len(MOTOR_IDS) and all(
        t.position is not None
        and t.rpm is not None
        and abs(t.position - target) <= TRAJECTORY_NEAR_POSITION_TOLERANCE
        and abs(t.rpm) <= 15.0
        for t, target in zip(values, targets)
    )


def draw_target_xy_near_and_stopped(
    values: list[direct.Telemetry],
    target_xy: tuple[float, float],
    calibration: dict | None = None,
    *,
    position_offsets_deg: object = None,
) -> bool:
    """Accept a stopped ball-centre pose using only geometry and encoders.

    Four lengths observe x/y plus the ball's free in-plane rotation, with one
    redundant closure scalar. Rotation is deliberately *not* a gate: the
    present spherical tool can yaw and the user only commands its centre. A
    small Cartesian error, low closure residual and stopped encoders are the
    observable conditions that matter. Optional session offsets remove the
    constant winding/yaw state captured at trajectory start without modifying
    the persisted calibration or raw feedback record.
    """

    if len(values) != len(MOTOR_IDS) or any(t.position is None or t.rpm is None for t in values):
        return False
    if any(abs(float(t.rpm)) > 15.0 for t in values):
        return False
    offsets = [0.0 for _ in MOTOR_IDS]
    if position_offsets_deg is not None:
        try:
            offsets = [float(value) for value in position_offsets_deg]
        except (TypeError, ValueError):
            return False
        if len(offsets) != len(MOTOR_IDS) or any(not math.isfinite(value) for value in offsets):
            return False
    snapshot = [float(t.position) - offsets[index] for index, t in enumerate(values)]
    pose = motor_positions_to_planar_pose(snapshot, calibration)
    if pose is None:
        return False
    estimate = (float(pose["x_mm"]), float(pose["y_mm"]))
    return bool(
        math.hypot(estimate[0] - target_xy[0], estimate[1] - target_xy[1])
        <= TRAJECTORY_XY_SETTLE_TOLERANCE
        and float(pose["closure_rms_mm"]) <= TRAJECTORY_PLANAR_CLOSURE_RMS_TOLERANCE_MM
        and float(pose["closure_max_mm"]) <= TRAJECTORY_PLANAR_CLOSURE_MAX_TOLERANCE_MM
    )


def max_target_error(values: list[direct.Telemetry], targets: list[float]) -> float | None:
    errors = [abs(t.position - target) for t, target in zip(values, targets) if t.position is not None]
    return max(errors) if len(errors) == len(targets) else None


def validate_trajectory_bounds(kind: str, spec: dict) -> tuple[float, float]:
    width = float(spec.get("width", WORKSPACE_WIDTH_MM))
    height = float(spec.get("height", WORKSPACE_HEIGHT_MM))
    if (
        not math.isclose(width, WORKSPACE_WIDTH_MM, abs_tol=0.0001)
        or not math.isclose(height, WORKSPACE_HEIGHT_MM, abs_tol=0.0001)
    ):
        raise RuntimeError("电脑直连轨迹工作区固定为球心 110×148mm")
    if width <= 0.0 or height <= 0.0:
        raise RuntimeError("轨迹工作区尺寸无效")
    for sample_index in range(101):
        x, y = sample_path(kind, sample_index / 100.0, spec)
        if not 0.0 <= x <= width or not 0.0 <= y <= height:
            raise RuntimeError(
                f"{kind_label(kind)}轨迹超出工作区 {width:.1f}×{height:.1f}mm：({x:.1f},{y:.1f})mm"
            )
    return width, height


def quintic_ease(value: float) -> float:
    value = max(0.0, min(1.0, value))
    return value * value * value * (value * (value * 6.0 - 15.0) + 10.0)


def move_to_start_smooth(
    connection: object,
    current_positions: list[float],
    targets: list[float],
    label: str,
    current: object = None,
    rpm: float = TRAJECTORY_START_RPM,
    current_start: object = None,
    feedback_drain: object = None,
) -> None:
    """Ramp all four absolute targets together before checking the start point.

    A single large AA target makes the driver choose a sharp acceleration
    profile and is the main reason a following test shape can appear stuck at
    its start.  This sends a bounded, synchronized ramp instead.
    """
    if len(current_positions) != len(MOTOR_IDS) or len(targets) != len(MOTOR_IDS):
        raise RuntimeError("轨迹起点需要四台电机的完整位置")
    max_delta = max(abs(target - current) for current, target in zip(current_positions, targets))
    # Leave headroom for the quintic ramp's peak velocity.  The old formula
    # commanded the first frame at 140 RPM and could still undershoot the
    # later absolute target, which felt like a sharp tug followed by a catch-up.
    start_rpm = max(1.0, min(TRAJECTORY_START_RPM, float(rpm)))
    duration = max(0.40, min(8.0, max_delta / max(start_rpm * 6.0, 1.0) * 1.80))
    steps = max(4, int(math.ceil(duration / TRAJECTORY_START_TICK)))
    end_current_limits = (
        normalized_trajectory_current_limits(current)
        if current is not None
        else None
    )
    start_current_limits = (
        normalized_trajectory_current_limits(current_start)
        if current_start is not None
        else end_current_limits
    )
    if end_current_limits is not None and start_current_limits is not None:
        start_current_limits = [
            min(start_value, end_value)
            for start_value, end_value in zip(start_current_limits, end_current_limits)
        ]
    started = time.monotonic()
    append_process_log(
        "trajectory_start_ramp",
        shape=label,
        current_positions=current_positions,
        target_positions=targets,
        max_delta_deg=round(max_delta, 2),
        duration_s=round(duration, 3),
        steps=steps,
        current_start_ma=start_current_limits,
        current_end_ma=end_current_limits,
    )
    for step in range(1, steps + 1):
        if STOP_EVENT.is_set():
            raise RuntimeError("用户急停")
        phase = quintic_ease(step / steps)
        ramp_targets = [current + (target - current) * phase for current, target in zip(current_positions, targets)]
        ramp_rpm = start_rpm * 1.10
        ramp_current = None
        if start_current_limits is not None and end_current_limits is not None:
            ramp_current = [
                round(start_value + (end_value - start_value) * phase)
                for start_value, end_value in zip(start_current_limits, end_current_limits)
            ]
        send_fast(
            connection,
            four_motor_position_frame(
                ramp_targets,
                [ramp_rpm] * len(MOTOR_IDS),
                ramp_current if ramp_current is not None else None,
            ),
        )
        deadline = started + step * TRAJECTORY_START_TICK
        wait = deadline - time.perf_counter()
        if wait > 0.0:
            # Keep an already-running unsolicited stream drained while the
            # 100Hz motion ramp waits. Polling every few ms preserves all
            # 100Hz feedback without increasing the motion command rate.
            while True:
                if callable(feedback_drain):
                    feedback_drain()
                wait = deadline - time.perf_counter()
                if wait <= 0.0:
                    break
                time.sleep(min(wait, 0.005))
        elif callable(feedback_drain):
            feedback_drain()
    # Reassert the exact endpoint once, at the same bounded speed, then let
    # the normal feedback settle check decide whether it is really reached.
    if STOP_EVENT.is_set():
        raise RuntimeError("用户急停")
    send_fast(
        connection,
        four_motor_position_frame(
            targets,
            [start_rpm] * len(MOTOR_IDS),
            end_current_limits if end_current_limits is not None else None,
        ),
    )
    append_process_log("trajectory_start_ramp_complete", shape=label, elapsed_s=round(time.perf_counter() - started, 3))


def move_to_start_smooth_three_plus_one(
    connection: object,
    current_positions: list[float],
    targets: list[float],
    passive_index: int,
    passive_current_ma: int,
    label: str,
    *,
    position_current: object,
    rpm: float = TRAJECTORY_START_RPM,
) -> None:
    """Quintic hand-off from four-rope torque hold to session 3+1 control."""

    if len(current_positions) != len(MOTOR_IDS) or len(targets) != len(MOTOR_IDS):
        raise RuntimeError("3+1 起点需要四台电机的完整位置")
    passive = int(passive_index)
    if passive not in range(len(MOTOR_IDS)):
        raise RuntimeError("3+1 张力电机索引无效")
    active = tuple(index for index in range(len(MOTOR_IDS)) if index != passive)
    max_delta = max(abs(targets[index] - current_positions[index]) for index in active)
    start_rpm = max(1.0, min(TRAJECTORY_START_RPM, float(rpm)))
    duration = max(0.40, min(8.0, max_delta / max(start_rpm * 6.0, 1.0) * 1.8))
    steps = max(4, int(math.ceil(duration / TRAJECTORY_START_TICK)))
    # First switch modes at the current encoder positions.  No position target
    # changes in this frame, while the fourth cable retains its low pull torque.
    send_fast(
        connection,
        three_position_one_torque_frame(
            current_positions,
            passive,
            passive_current_ma,
            [start_rpm] * len(MOTOR_IDS),
            position_current,
            torque_max_rpm=HYBRID_PATH_PASSIVE_MAX_RPM,
        ),
    )
    time.sleep(0.08)
    started = time.perf_counter()
    for step in range(1, steps + 1):
        if STOP_EVENT.is_set():
            raise RuntimeError("用户急停")
        phase = quintic_ease(step / steps)
        ramp_targets = [
            current + (target - current) * phase
            for current, target in zip(current_positions, targets)
        ]
        send_fast(
            connection,
            three_position_one_torque_frame(
                ramp_targets,
                passive,
                passive_current_ma,
                [start_rpm * 1.1] * len(MOTOR_IDS),
                position_current,
                torque_max_rpm=HYBRID_PATH_PASSIVE_MAX_RPM,
            ),
        )
        deadline = started + step * TRAJECTORY_START_TICK
        if deadline > time.perf_counter():
            wait_trajectory_deadline(deadline)
    send_fast(
        connection,
        three_position_one_torque_frame(
            targets,
            passive,
            passive_current_ma,
            [start_rpm] * len(MOTOR_IDS),
            position_current,
            torque_max_rpm=HYBRID_PATH_PASSIVE_MAX_RPM,
        ),
    )
    append_process_log(
        "trajectory_start_ramp_complete",
        shape=label,
        controller="3-position-1-torque",
        passive_motor=MOTOR_IDS[passive],
        max_delta_deg=round(max_delta, 3),
        elapsed_s=round(time.perf_counter() - started, 3),
    )


def wait_for_absolute_target(
    connection: object,
    targets: list[float],
    current_limits: list[int] | int | None,
    label: str,
    timeout: float = 3.0,
    rpm: float = GRID_START_RPM,
    tolerance_deg: float = GRID_POSITION_TOLERANCE_DEG,
    feedback_callback: object = None,
) -> list[float]:
    """Confirm a synchronous absolute move before a grid sample is accepted."""
    deadline = time.monotonic() + max(0.5, float(timeout))
    last_positions: list[float] | None = None
    last_error: float | None = None
    limits = normalized_trajectory_current_limits(current_limits)
    boosted_motors: set[int] = set()
    while time.monotonic() < deadline:
        if STOP_EVENT.is_set():
            raise RuntimeError("用户急停")
        values = read_all_reliable(connection, attempts=2)
        safety = grid_safety_error(values, normalized_trajectory_current_limits(current_limits))
        if safety:
            raise RuntimeError(f"{label}：{safety}")
        if any(value.position is None for value in values):
            raise RuntimeError(f"{label}：四台电机绝对位置反馈不完整")
        last_positions = [float(value.position) for value in values]
        errors = [abs(actual - target) for actual, target in zip(last_positions, targets)]
        last_error = max(errors)
        if callable(feedback_callback):
            feedback_callback(values, last_error, limits)
        if last_error <= max(0.5, float(tolerance_deg)):
            append_process_log(
                "trajectory_absolute_target_reached",
                shape=label,
                target_positions=targets,
                actual_positions=last_positions,
                max_error_deg=round(last_error, 3),
            )
            return last_positions
        if time.monotonic() - (deadline - max(0.5, float(timeout))) >= 0.8:
            candidates = [index for index in range(len(errors)) if index not in boosted_motors]
            lagging = max(candidates, key=errors.__getitem__) if candidates else None
            if lagging is None or errors[lagging] <= max(0.5, float(tolerance_deg)):
                lagging = None
            if lagging is None:
                # Every motor that is still outside the gate has already had
                # its bounded headroom attempt; keep holding and let the
                # timeout report the complete final error vector.
                time.sleep(0.08)
                continue
            # Give the one lagging motor the configured headroom in one
            # bounded step.  A single +300mA bump left M4 at 1800mA even
            # though the safety-tested per-motor ceiling is 2000mA, so a
            # repeatable corner could still time out before the ceiling was
            # ever exercised.  The other three limits remain unchanged.
            boosted = min(
                GRID_LAGGING_MOTOR_CURRENT_LIMIT_MA,
                limits[lagging] + GRID_MOTION_CURRENT_HEADROOM_MA,
            )
            if boosted > limits[lagging]:
                limits[lagging] = boosted
                boosted_motors.add(lagging)
                if isinstance(current_limits, list) and len(current_limits) == len(limits):
                    current_limits[:] = limits
                append_process_log(
                    "trajectory_absolute_target_boost",
                    shape=label,
                    lagging_motor=lagging + 1,
                    max_error_deg=round(last_error, 3),
                    current_limits_ma=limits,
                )
                # Never relax the other three motors while the ball is held.
                # That earlier relief/overshoot frame visibly released the
                # platform and could make the last motor trip protection.
                # Reassert the same absolute target with only the lagging
                # motor's bounded ceiling raised.
                append_process_log(
                    "trajectory_absolute_target_reassert",
                    shape=label,
                    lagging_motor=lagging + 1,
                    current_limits_ma=limits,
                )
                send_fast(
                    connection,
                    four_motor_position_frame(
                        targets,
                        [max(1.0, min(TRAJECTORY_START_RPM, float(rpm)))] * len(MOTOR_IDS),
                        limits,
                    ),
                )
                time.sleep(0.25)
        # Reassert the same absolute endpoint at the bounded start speed. This
        # is a hold-to-target correction, not a relative increment.
        send_fast(
            connection,
            four_motor_position_frame(
                targets,
                [max(1.0, min(TRAJECTORY_START_RPM, float(rpm)))] * len(MOTOR_IDS),
                limits,
            ),
        )
        time.sleep(0.08)
    append_process_log(
        "trajectory_absolute_target_timeout",
        shape=label,
        target_positions=targets,
        actual_positions=last_positions,
        max_error_deg=round(last_error or 0.0, 3),
        current_limits_ma=limits,
    )
    raise RuntimeError(
        f"{label}：绝对位置未到位，最大误差 {last_error:.1f}°（门槛 {float(tolerance_deg):.1f}°）；已停止继续采样，"
        "避免把未到位点当成校准数据"
    )


def compute_calibration(
    samples: list[list[float]],
    width: float,
    height: float,
    ball: float,
) -> tuple[dict | None, str]:
    """Fit each motor against the measured rigid-platform cable geometry.

    ``width``/``height`` validate the exact 110×148 user ball-centre travel.
    The four measured rows correspond to the four physical ball-centre corners
    ``(0,148), (110,148), (110,0), (0,0)``.  Equivalent anchors
    ``exit - attachment`` are used only to calculate each rope's geometric
    distance at those centres; they are never substituted for sample positions.
    """
    try:
        width = float(width)
        height = float(height)
        ball = float(ball)
    except (TypeError, ValueError):
        return None, "电脑直连四角校准参数必须是有效数字"
    if (
        not math.isclose(width, WORKSPACE_WIDTH_MM, abs_tol=0.0001)
        or not math.isclose(height, WORKSPACE_HEIGHT_MM, abs_tol=0.0001)
    ):
        return None, "电脑直连四角校准固定使用球心工作区 110×148mm"
    if not math.isclose(ball, DEFAULT_BALL_DIAMETER_MM, abs_tol=0.0001):
        return None, "电脑直连校准球径元数据固定为 40mm"
    if (
        not isinstance(samples, list)
        or len(samples) != len(MOTOR_IDS)
        or any(not isinstance(row, (list, tuple)) or len(row) != len(MOTOR_IDS) for row in samples)
    ):
        return None, "四角校准必须提供四组完整的四电机位置样本"
    try:
        samples = [[float(value) for value in row] for row in samples]
    except (TypeError, ValueError):
        return None, "四角校准样本包含无效编码器位置"
    if any(not math.isfinite(value) for row in samples for value in row):
        return None, "四角校准样本包含非有限编码器位置"
    frame = {
        "workspace_width": width,
        "workspace_height": height,
        "anchor_width": ANCHOR_WIDTH_MM,
        "anchor_height": ANCHOR_HEIGHT_MM,
        "ball": float(ball),
    }
    ax, ay = workspace_anchor_coordinates(frame)
    corner_x, corner_y = workspace_corner_coordinates(frame)
    previous = calibration_data()
    slope = []
    intercept = []
    r2 = []
    groups = []
    spread = []
    # Every motor sees the same four known geometric distances, but its
    # encoder has its own zero and gain.  Fit both terms independently.  The
    # former implementation forced the intercept to the motor's own corner;
    # one noisy sample then tilted the other three points and made the
    # resulting XY path visibly crooked.
    all_distances = {
        motor: [
            math.hypot(corner_x[corner] - ax[motor], corner_y[corner] - ay[motor])
            for corner in range(4)
        ]
        for motor in range(4)
    }
    for motor in range(4):
        motor_distances = all_distances[motor]
        motor_values = [float(samples[corner][motor]) for corner in range(4)]
        mean_distance = statistics.mean(motor_distances)
        mean_value = statistics.mean(motor_values)
        denominator = sum((value - mean_distance) ** 2 for value in motor_distances)
        numerator = sum(
            (distance - mean_distance) * (value - mean_value)
            for distance, value in zip(motor_distances, motor_values)
        )
        fitted = numerator / denominator if denominator > 0.000001 else 0.0
        own_intercept = mean_value - fitted * mean_distance
        local = []
        for corner in range(4):
            length = motor_distances[corner]
            if length <= 0.000001:
                continue
            value = (motor_values[corner] - own_intercept) / length
            local.append(value)
        ss_total = sum((value - mean_value) ** 2 for value in motor_values)
        ss_residual = sum(
            (
                motor_values[corner]
                - (own_intercept + fitted * motor_distances[corner])
            )
            ** 2
            for corner in range(4)
        )
        score = 1.0 - ss_residual / ss_total if ss_total > 0.001 else 0.0
        max_spread = max((abs(value - fitted) for value in local), default=0.0)
        intercept.append(own_intercept)
        slope.append(fitted)
        r2.append(score)
        groups.append(local)
        spread.append(max_spread)
        signs_agree = all(value * local[0] > 0 for value in local[1:]) if local else False
        if abs(fitted) < 0.05 or not signs_agree or score < 0.85 or max_spread > MAX_SLOPE_SPREAD:
            return None, f"电机 M{motor + 1} 拟合质量不足：R²={score:.3f}，系数偏差={max_spread:.3f}°/mm"
    quality_error = slope_consistency_error(slope)
    if quality_error:
        return None, quality_error + "；请优先检查 M3/M4 绳路、绕线方向、编码器零点和角点采样，不保存本次校准"
    # Keep each motor's own fitted coefficient.  The consistency check above
    # still rejects a clearly abnormal rope path, but it must never replace
    # four measured coefficients with their average.
    raw_slope = list(slope)
    merged_curves = [
        _coalesce_rope_curve(
            list(all_distances[motor]),
            [float(samples[corner][motor]) for corner in range(len(MOTOR_IDS))],
        )
        for motor in range(len(MOTOR_IDS))
    ]
    if any(len(curve) < 2 for curve in merged_curves):
        return None, "四角样本无法生成单调绳长曲线"
    curve_warnings: list[str] = []
    for motor, curve in enumerate(merged_curves):
        for (distance0, position0), (distance1, position1) in zip(curve, curve[1:]):
            segment_slope = abs((position1 - position0) / max(1.0e-9, distance1 - distance0))
            equivalent_radius = 180.0 / (math.pi * segment_slope) if segment_slope > 1.0e-9 else float("inf")
            if equivalent_radius > SPOOL_OUTER_RADIUS_MM + 1.0e-6:
                curve_warnings.append(
                    f"M{motor + 1} {distance0:.2f}..{distance1:.2f}mm段等效半径{equivalent_radius:.1f}mm，按实测曲线保留"
                )
    result = {
        "valid": True,
        "side": height,
        "ball": ball,
        "effective_side": height,
        "workspace_width": width,
        "workspace_height": height,
        "anchor_width": ANCHOR_WIDTH_MM,
        "anchor_height": ANCHOR_HEIGHT_MM,
        "motor_frame_origin_mm": [MOTOR_FRAME_ORIGIN_X_MM, MOTOR_FRAME_ORIGIN_Y_MM],
        "motor_center_coordinates_mm": [list(pair) for pair in zip(*motor_center_coordinates())],
        "cable_exit_offset_x_mm": MOTOR_CABLE_EXIT_OFFSET_X_MM,
        "spool_winding_radius_mm": SPOOL_WINDING_RADIUS_MM,
        "spool_reference_radius_mm": SPOOL_REFERENCE_RADIUS_MM,
        "spool_winding_z_range_mm": [SPOOL_WINDING_Z_MIN_MM, SPOOL_WINDING_Z_MAX_MM],
        "ball_center_contact_z_mm": BALL_CENTER_CONTACT_Z_MM,
        "ball_attachment_z_mm": BALL_ATTACHMENT_Z_MM,
        "ball_attachment_span_x_mm": BALL_ATTACHMENT_SPAN_X_MM,
        "ball_attachment_span_y_mm": BALL_ATTACHMENT_SPAN_Y_MM,
        "platform_command_yaw_deg": PLATFORM_COMMAND_YAW_DEG,
        "cable_exit_model": CABLE_EXIT_MODEL,
        "geometry_version": GEOMETRY_VERSION,
        "coordinate_frame": "ball_center_workspace",
        "control_architecture": CONTROL_ARCHITECTURE,
        "platform_pose_model": PLATFORM_POSE_MODEL,
        "session_calibration_mode": SESSION_CALIBRATION_MODE,
        "session_id": PROCESS_SESSION_ID,
        "session_local_verified": True,
        "session_tension_held": True,
        "session_invalid_reason": "",
        "fixed_guide_exit_verified": False,
        "deterministic_spool_payout_verified": False,
        "spool_geometry_reason": (
            "STEP与视频确认光滑卷筒半径12mm、绕线高度z=5..16mm；当前无固定导绳眼，且排线、叠层和有效半径不可由编码器观测"
        ),
        "orientation_mechanical_decoupling_verified": False,
        "orientation_mechanical_reason": (
            "四角初始化不能独立识别球的滚转/俯仰；当前精度限于本次持续张紧状态"
        ),
        "workspace_calibration_verified": True,
        "redundant_closure_verified": False,
        "redundant_closure_reason": (
            "本次会话采用三台位置控制与解算，第四台只作低力矩收绳；"
            "第四台编码器不冒充独立位置观测，持续校准由会话张力状态保证"
        ),
        "external_pose_verified": False,
        "calibration_source": "torque_corner_initializer",
        "slope": slope,
        "raw_slope": raw_slope,
        "intercept": intercept,
        "r2": r2,
        "groups": groups,
        "spread": spread,
        "rope_curve_warnings": curve_warnings,
        "samples": samples,
        # Preserve the measured nonlinear spool curve. The four-corner fit is
        # still retained for diagnostics, but live target generation and
        # inverse kinematics use these per-motor absolute anchors.
        "distance_samples_mm": [
            [pair[0] for pair in curve]
            for curve in merged_curves
        ],
        "position_samples_deg": [
            [pair[1] for pair in curve]
            for curve in merged_curves
        ],
        "direction_reverse": list(direction_reversal_flags()),
        "encoder_positive_direction": list(
            encoder_positive_directions({"slope": slope, "direction_reverse": list(direction_reversal_flags())})
        ),
        "strong_current": int(previous.get("strong_current", CALIBRATION_DEFAULT_STRONG_CURRENT)),
        "weak_current": int(previous.get("weak_current", CALIBRATION_DEFAULT_WEAK_CURRENT)),
        "trajectory_current": int(previous.get("trajectory_current", TRAJECTORY_DEFAULT_CURRENT)),
        "draw_tension_current_ma": int(previous.get("draw_tension_current_ma", DRAW_TENSION_DEFAULT_CURRENT)),
        "force_position_target_current_ma": int(
            previous.get("force_position_target_current_ma", FORCE_POSITION_TARGET_FLOOR_MA)
        ),
        "tracking_current_ma": int(previous.get("tracking_current_ma", TRACKING_CURRENT_LIMIT_DEFAULT_MA)),
        "path_speed_mm_s": float(previous.get("path_speed_mm_s", PATH_SPEED_DEFAULT_MM_S)),
        "slope_trim_percent": normalized_slope_trims(previous),
        "tracking_pen_up_height_mm": float(previous.get("tracking_pen_up_height_mm", TRACKING_PEN_UP_HEIGHT_MM)),
        "tracking_pen_down_height_mm": float(previous.get("tracking_pen_down_height_mm", TRACKING_PEN_DOWN_HEIGHT_MM)),
        # A new four-corner fit changes the position baseline.  Do not carry an
        # old multi-point table across that geometry change.
        "grid_compensation": blank_grid_compensation(),
        "center_tension_calibration": blank_center_tension_calibration(),
        "internal_feedback_calibration": blank_internal_feedback_calibration(),
        "quality_error": "",
    }
    for index in range(len(MOTOR_IDS)):
        curve_error = rope_curve_quality_error(result, index)
        if curve_error:
            return None, curve_error
    model_context = calibration_model_context(result)
    result["model_family_key"] = model_context.get("model_family_key")
    result["position_reference_deg"] = model_context.get("position_reference_deg")
    result["position_reference"] = model_context.get("position_reference")
    return mark_internal_model_ready(result), ""


def _isotonic_non_decreasing(values: list[float]) -> list[float]:
    """Project noisy samples onto a non-decreasing sequence (PAVA)."""
    blocks: list[list[float]] = []
    for value in values:
        blocks.append([float(value), 1.0])
        while len(blocks) >= 2:
            left, right = blocks[-2], blocks[-1]
            if left[0] / left[1] <= right[0] / right[1]:
                break
            blocks[-2] = [left[0] + right[0], left[1] + right[1]]
            blocks.pop()
    projected: list[float] = []
    for total, count in blocks:
        projected.extend([total / count] * int(count))
    return projected


def planar_platform_cable_lengths(
    x: float, y: float, yaw_deg: float, calibration: dict | None = None
) -> list[float]:
    """Return M1..M4 lengths for one rigid board-plane platform pose.

    ``x``/``y`` locate the platform centre.  Each cable ends at its own fixed
    body-frame attachment ``b_i`` and starts at the measured base exit ``A_i``::

        L_i = || A_i - (p + R(yaw) b_i) ||

    Keeping yaw in this equation is essential: treating the four attachments
    as one point turns a real in-plane rotation into a fictitious Z motion.
    """
    data = calibration if calibration is not None else calibration_data()
    exit_x, exit_y = cable_exit_coordinates(data)
    attachment_x, attachment_y = ball_attachment_offsets(data)
    angle = math.radians(float(yaw_deg))
    cosine, sine = math.cos(angle), math.sin(angle)
    lengths = []
    for motor in range(len(MOTOR_IDS)):
        rotated_x = cosine * attachment_x[motor] - sine * attachment_y[motor]
        rotated_y = sine * attachment_x[motor] + cosine * attachment_y[motor]
        endpoint_x = float(x) + rotated_x
        endpoint_y = float(y) + rotated_y
        lengths.append(math.hypot(exit_x[motor] - endpoint_x, exit_y[motor] - endpoint_y))
    return lengths


def _external_pose_cable_lengths(
    x: float, y: float, yaw_deg: float, calibration: dict
) -> list[float]:
    """Compatibility alias for the rigid-platform cable model."""
    return planar_platform_cable_lengths(x, y, yaw_deg, calibration)


def _planar_pose_residual_jacobian(
    x: float,
    y: float,
    yaw_rad: float,
    measured_lengths: list[float],
    calibration: dict,
) -> tuple[list[float], list[list[float]], list[float]] | None:
    """Return all residuals and the analytic 4x3 cable-length Jacobian."""
    exit_x, exit_y = cable_exit_coordinates(calibration)
    attachment_x, attachment_y = ball_attachment_offsets(calibration)
    cosine, sine = math.cos(yaw_rad), math.sin(yaw_rad)
    residuals: list[float] = []
    jacobian: list[list[float]] = []
    predicted: list[float] = []
    for motor in range(len(MOTOR_IDS)):
        body_x = attachment_x[motor]
        body_y = attachment_y[motor]
        rotated_x = cosine * body_x - sine * body_y
        rotated_y = sine * body_x + cosine * body_y
        derivative_x = -sine * body_x - cosine * body_y
        derivative_y = cosine * body_x - sine * body_y
        delta_x = float(x) + rotated_x - exit_x[motor]
        delta_y = float(y) + rotated_y - exit_y[motor]
        length = math.hypot(delta_x, delta_y)
        if length <= 1e-9 or not math.isfinite(length):
            return None
        predicted.append(length)
        residuals.append(length - measured_lengths[motor])
        jacobian.append(
            [
                delta_x / length,
                delta_y / length,
                (delta_x * derivative_x + delta_y * derivative_y) / length,
            ]
        )
    return residuals, jacobian, predicted


def _normal_matrix_determinant(matrix: list[list[float]]) -> float:
    """Return the determinant of a 3x3 matrix for observability diagnostics."""
    if len(matrix) != 3 or any(len(row) != 3 for row in matrix):
        return 0.0
    return (
        matrix[0][0] * (matrix[1][1] * matrix[2][2] - matrix[1][2] * matrix[2][1])
        - matrix[0][1] * (matrix[1][0] * matrix[2][2] - matrix[1][2] * matrix[2][0])
        + matrix[0][2] * (matrix[1][0] * matrix[2][1] - matrix[1][1] * matrix[2][0])
    )


def solve_planar_platform_pose(
    lengths: list[float] | tuple[float, ...],
    calibration: dict | None = None,
    *,
    active_indices: list[int] | tuple[int, ...] | None = None,
    initial_pose: object = None,
) -> dict | None:
    """Solve rigid-platform ``x/y/yaw`` using three or four cable lengths.

    With all four cables the least-squares pose has one redundant scalar, so
    ``closure_*`` is an independent geometry/encoder consistency measurement.
    With exactly three active position-controlled cables, their equations set
    the pose and every omitted cable is reported separately in
    ``redundant_residuals_mm``.  That is the basis of the motor-only 3+1
    calibration and runtime architecture.
    """
    if len(lengths) != len(MOTOR_IDS):
        return None
    try:
        measured = [abs(float(value)) for value in lengths]
    except (TypeError, ValueError):
        return None
    if not all(math.isfinite(value) and value > 0.0 for value in measured):
        return None
    data = calibration if calibration is not None else calibration_data()
    if active_indices is None:
        active = tuple(range(len(MOTOR_IDS)))
    else:
        try:
            active = tuple(int(index) for index in active_indices)
        except (TypeError, ValueError):
            return None
    if len(active) not in (3, 4) or len(set(active)) != len(active) or any(index not in range(4) for index in active):
        return None

    seed_xy = solve_position_from_lengths(measured, data)
    base_x = float(seed_xy[0]) if seed_xy is not None else WORKSPACE_WIDTH_MM / 2.0
    base_y = float(seed_xy[1]) if seed_xy is not None else WORKSPACE_HEIGHT_MM / 2.0
    parsed_initial: tuple[float, float, float] | None = None
    try:
        if isinstance(initial_pose, dict):
            parsed_initial = (
                float(initial_pose.get("x_mm", initial_pose.get("x"))),
                float(initial_pose.get("y_mm", initial_pose.get("y"))),
                math.radians(float(initial_pose.get("yaw_deg", initial_pose.get("yaw", 0.0)))),
            )
        elif isinstance(initial_pose, (list, tuple)) and len(initial_pose) >= 3:
            parsed_initial = (float(initial_pose[0]), float(initial_pose[1]), math.radians(float(initial_pose[2])))
        if parsed_initial is not None and not all(math.isfinite(value) for value in parsed_initial):
            parsed_initial = None
    except (TypeError, ValueError):
        parsed_initial = None

    yaw_limit = math.radians(PLANAR_POSE_MAX_YAW_DEG)
    seeds: list[tuple[float, float, float]] = []
    if parsed_initial is not None:
        seeds.append(parsed_initial)
    for yaw_deg in (0.0, -15.0, 15.0, -30.0, 30.0, -45.0, 45.0):
        seeds.append((base_x, base_y, math.radians(yaw_deg)))

    width, height = workspace_dimensions(data)
    x_bounds = (-35.0, width + 35.0)
    y_bounds = (-35.0, height + 35.0)
    best: dict | None = None
    for seed in seeds:
        state = [
            max(x_bounds[0], min(x_bounds[1], float(seed[0]))),
            max(y_bounds[0], min(y_bounds[1], float(seed[1]))),
            max(-yaw_limit, min(yaw_limit, float(seed[2]))),
        ]
        damping = 1e-4
        accepted = False
        iterations = 0
        for iterations in range(1, PLANAR_POSE_SOLVER_MAX_ITERATIONS + 1):
            evaluated = _planar_pose_residual_jacobian(*state, measured, data)
            if evaluated is None:
                break
            residuals, jacobian, _ = evaluated
            cost = sum(residuals[index] ** 2 for index in active)
            normal = [[0.0] * 3 for _ in range(3)]
            gradient = [0.0] * 3
            for index in active:
                row = jacobian[index]
                residual = residuals[index]
                for column in range(3):
                    gradient[column] += row[column] * residual
                    for other in range(3):
                        normal[column][other] += row[column] * row[other]
            damped = [row[:] for row in normal]
            for diagonal in range(3):
                damped[diagonal][diagonal] += damping * max(1.0, normal[diagonal][diagonal])
            step = _solve_square_linear_system(damped, [-value for value in gradient])
            if step is None:
                damping *= 10.0
                continue
            step[0] = max(-12.0, min(12.0, step[0]))
            step[1] = max(-12.0, min(12.0, step[1]))
            step[2] = max(-math.radians(12.0), min(math.radians(12.0), step[2]))
            improved = False
            for fraction in (1.0, 0.5, 0.25, 0.125, 0.0625):
                candidate = [
                    max(x_bounds[0], min(x_bounds[1], state[0] + fraction * step[0])),
                    max(y_bounds[0], min(y_bounds[1], state[1] + fraction * step[1])),
                    max(-yaw_limit, min(yaw_limit, state[2] + fraction * step[2])),
                ]
                candidate_eval = _planar_pose_residual_jacobian(*candidate, measured, data)
                if candidate_eval is None:
                    continue
                candidate_cost = sum(candidate_eval[0][index] ** 2 for index in active)
                if candidate_cost < cost - 1e-12:
                    state = candidate
                    damping = max(1e-9, damping * 0.35)
                    accepted = True
                    improved = True
                    break
            if not improved:
                damping *= 10.0
                if damping > 1e9:
                    break
            if max(abs(step[0]), abs(step[1]), abs(step[2]) * 20.0) < 1e-8:
                break

        evaluated = _planar_pose_residual_jacobian(*state, measured, data)
        if evaluated is None:
            continue
        residuals, jacobian, predicted = evaluated
        active_cost = sum(residuals[index] ** 2 for index in active)
        continuity = 0.0
        if parsed_initial is not None:
            continuity = (
                (state[0] - parsed_initial[0]) ** 2
                + (state[1] - parsed_initial[1]) ** 2
                + (20.0 * (state[2] - parsed_initial[2])) ** 2
            )
        candidate_result = {
            "x_mm": state[0],
            "y_mm": state[1],
            "yaw_deg": math.degrees(state[2]),
            "predicted_lengths_mm": predicted,
            "residuals_mm": residuals,
            "active_indices": list(active),
            "redundant_indices": [index for index in range(4) if index not in active],
            "redundant_residuals_mm": [residuals[index] for index in range(4) if index not in active],
            "active_rms_mm": math.sqrt(active_cost / len(active)),
            "closure_rms_mm": math.sqrt(sum(value * value for value in residuals) / len(residuals)),
            "closure_max_mm": max(abs(value) for value in residuals),
            "iterations": iterations,
            "converged": bool(accepted or active_cost <= 1e-12),
            "continuity_score": continuity,
            "jacobian": jacobian,
        }
        if best is None:
            best = candidate_result
            continue
        best_cost = float(best["active_rms_mm"]) ** 2 * len(active)
        if active_cost < best_cost - 1e-10 or (
            abs(active_cost - best_cost) <= 1e-10
            and continuity < float(best.get("continuity_score", float("inf")))
        ):
            best = candidate_result

    if best is None:
        return None
    normal = [[0.0] * 3 for _ in range(3)]
    for index in active:
        row = best["jacobian"][index]
        # Normalise yaw to roughly one platform-radius of edge motion so the
        # determinant is comparable across poses and useful as a singularity gate.
        scaled = [row[0], row[1], row[2] / max(BALL_ATTACHMENT_HALF_X_MM, BALL_ATTACHMENT_HALF_Y_MM)]
        for column in range(3):
            for other in range(3):
                normal[column][other] += scaled[column] * scaled[other]
    best["observability_det"] = abs(_normal_matrix_determinant(normal))
    best.pop("jacobian", None)
    best.pop("continuity_score", None)
    return best


def motor_positions_to_planar_pose(
    positions: list[float] | tuple[float, ...],
    calibration: dict | None = None,
    *,
    active_indices: list[int] | tuple[int, ...] | None = None,
    initial_pose: object = None,
) -> dict | None:
    """Convert four encoder positions into the rigid board-plane pose."""
    data = calibration if calibration is not None else calibration_data()
    lengths = encoder_positions_to_lengths(list(positions), data)
    if lengths is None:
        return None
    return solve_planar_platform_pose(
        lengths,
        data,
        active_indices=active_indices,
        initial_pose=initial_pose,
    )


def planar_active_set_observability(
    x: float,
    y: float,
    passive_index: int,
    calibration: dict | None = None,
    yaw_deg: float = PLATFORM_COMMAND_YAW_DEG,
) -> float:
    """Return a scaled determinant for the three position-cable Jacobian."""
    data = calibration if calibration is not None else calibration_data()
    passive = int(passive_index)
    if passive not in range(len(MOTOR_IDS)):
        return 0.0
    lengths = planar_platform_cable_lengths(x, y, yaw_deg, data)
    evaluated = _planar_pose_residual_jacobian(
        float(x), float(y), math.radians(float(yaw_deg)), lengths, data
    )
    if evaluated is None:
        return 0.0
    jacobian = evaluated[1]
    normal = [[0.0] * 3 for _ in range(3)]
    scale = max(BALL_ATTACHMENT_HALF_X_MM, BALL_ATTACHMENT_HALF_Y_MM)
    for index in range(len(MOTOR_IDS)):
        if index == passive:
            continue
        row = [jacobian[index][0], jacobian[index][1], jacobian[index][2] / scale]
        for column in range(3):
            for other in range(3):
                normal[column][other] += row[column] * row[other]
    return abs(_normal_matrix_determinant(normal))


def planar_xy_pair_observability(
    x: float,
    y: float,
    position_indices: list[int] | tuple[int, ...],
    calibration: dict | None = None,
) -> dict:
    """Return the fixed-yaw 2x2 Jacobian conditioning for one cable pair."""
    try:
        active = tuple(int(index) for index in position_indices)
    except (TypeError, ValueError):
        return {"ok": False, "condition": float("inf"), "minimum_singular": 0.0}
    if len(active) != 2 or len(set(active)) != 2 or any(index not in range(4) for index in active):
        return {"ok": False, "condition": float("inf"), "minimum_singular": 0.0}
    data = calibration if calibration is not None else calibration_data()
    lengths = planar_platform_cable_lengths(x, y, PLATFORM_COMMAND_YAW_DEG, data)
    evaluated = _planar_pose_residual_jacobian(
        float(x), float(y), math.radians(PLATFORM_COMMAND_YAW_DEG), lengths, data
    )
    if evaluated is None:
        return {"ok": False, "condition": float("inf"), "minimum_singular": 0.0}
    rows = [[evaluated[1][index][0], evaluated[1][index][1]] for index in active]
    a = sum(row[0] * row[0] for row in rows)
    b = sum(row[0] * row[1] for row in rows)
    c = sum(row[1] * row[1] for row in rows)
    discriminant = math.sqrt(max(0.0, (a - c) ** 2 + 4.0 * b * b))
    maximum_eigenvalue = max(0.0, 0.5 * (a + c + discriminant))
    minimum_eigenvalue = max(0.0, 0.5 * (a + c - discriminant))
    minimum_singular = math.sqrt(minimum_eigenvalue)
    maximum_singular = math.sqrt(maximum_eigenvalue)
    condition = maximum_singular / minimum_singular if minimum_singular > 1e-9 else float("inf")
    return {
        "ok": math.isfinite(condition),
        "position_indices": list(active),
        "motor_ids": [MOTOR_IDS[index] for index in active],
        "condition": condition,
        "minimum_singular": minimum_singular,
        "determinant_abs": abs(rows[0][0] * rows[1][1] - rows[0][1] * rows[1][0]),
    }


def select_position_pair_for_path(
    path: list[tuple[float, float]],
    calibration: dict | None = None,
) -> dict:
    """Choose the best-conditioned 2+2 position pair for a complete path.

    A single pair is retained during continuous motion to avoid a position/
    torque mode discontinuity.  Pair changes are permitted only between paths
    after speed reaches zero.
    """
    data = calibration if calibration is not None else calibration_data()
    if not path:
        return {"ok": False, "position_indices": None, "reason": "路径为空", "candidates": []}
    samples: list[tuple[float, float]] = []
    if len(path) == 1:
        samples.append((float(path[0][0]), float(path[0][1])))
    else:
        for first, second in zip(path, path[1:]):
            for step in range(9):
                fraction = step / 8.0
                samples.append(
                    (
                        float(first[0]) + (float(second[0]) - float(first[0])) * fraction,
                        float(first[1]) + (float(second[1]) - float(first[1])) * fraction,
                    )
                )
        samples.append((float(path[-1][0]), float(path[-1][1])))
    candidates: list[dict] = []
    for first in range(len(MOTOR_IDS)):
        for second in range(first + 1, len(MOTOR_IDS)):
            checks = [planar_xy_pair_observability(x, y, (first, second), data) for x, y in samples]
            worst_condition = max((float(item["condition"]) for item in checks), default=float("inf"))
            minimum_singular = min((float(item["minimum_singular"]) for item in checks), default=0.0)
            candidates.append(
                {
                    "position_indices": [first, second],
                    "motor_ids": [MOTOR_IDS[first], MOTOR_IDS[second]],
                    "worst_condition": worst_condition,
                    "minimum_singular": minimum_singular,
                    "score": minimum_singular / max(1.0, worst_condition),
                }
            )
    viable = [
        item
        for item in candidates
        if math.isfinite(float(item["worst_condition"]))
        and float(item["worst_condition"]) <= TWO_POSITION_MAX_CONDITION
    ]
    if not viable:
        return {"ok": False, "position_indices": None, "reason": "路径存在两绳XY奇异区", "candidates": candidates}
    selected = max(viable, key=lambda item: (float(item["score"]), -float(item["worst_condition"])))
    return {"ok": True, **selected, "candidates": candidates}


def select_session_passive_motor_for_path(
    path: list[tuple[float, float]],
    calibration: dict | None = None,
) -> dict:
    """Choose one passive rope by the worst 3x2 ball-centre Jacobian."""

    data = calibration if calibration is not None else calibration_data()
    if not path:
        return {"ok": False, "reason": "路径为空"}
    if len(path) <= 41:
        samples = [(float(x), float(y)) for x, y in path]
    else:
        samples = [
            (float(path[round(index * (len(path) - 1) / 40)][0]), float(path[round(index * (len(path) - 1) / 40)][1]))
            for index in range(41)
        ]
    anchors_x, anchors_y = workspace_anchor_coordinates(data)
    try:
        fit_r2 = [float(value) for value in data.get("r2", [1.0] * len(MOTOR_IDS))]
    except (TypeError, ValueError):
        fit_r2 = [1.0] * len(MOTOR_IDS)
    candidates: list[dict] = []
    for passive in range(len(MOTOR_IDS)):
        active = tuple(index for index in range(len(MOTOR_IDS)) if index != passive)
        worst_condition = 0.0
        minimum_singular = float("inf")
        for x, y in samples:
            a = b = c = 0.0
            valid = True
            for index in active:
                dx, dy = x - anchors_x[index], y - anchors_y[index]
                length = math.hypot(dx, dy)
                if length <= 1e-9:
                    valid = False
                    break
                gx, gy = dx / length, dy / length
                a += gx * gx
                b += gx * gy
                c += gy * gy
            if not valid:
                worst_condition = float("inf")
                minimum_singular = 0.0
                break
            disc = math.sqrt(max(0.0, (a - c) ** 2 + 4.0 * b * b))
            upper = math.sqrt(max(0.0, 0.5 * (a + c + disc)))
            lower = math.sqrt(max(0.0, 0.5 * (a + c - disc)))
            condition = upper / lower if lower > 1e-9 else float("inf")
            worst_condition = max(worst_condition, condition)
            minimum_singular = min(minimum_singular, lower)
        active_fit_floor = min((fit_r2[index] for index in active), default=0.0)
        score = minimum_singular * max(0.1, active_fit_floor) / max(1.0, worst_condition)
        candidates.append(
            {
                "passive_index": passive,
                "passive_motor": MOTOR_IDS[passive],
                "active_indices": list(active),
                "active_motors": [MOTOR_IDS[index] for index in active],
                "worst_condition": worst_condition,
                "minimum_singular": minimum_singular,
                "active_fit_r2_floor": active_fit_floor,
                "score": score,
            }
        )
    viable = [item for item in candidates if math.isfinite(float(item["worst_condition"])) and item["minimum_singular"] > 0.2]
    if not viable:
        return {"ok": False, "reason": "路径上的三绳球心解算接近奇异", "candidates": candidates}
    selected = max(viable, key=lambda item: (float(item["score"]), float(item["active_fit_r2_floor"])))
    return {"ok": True, **selected, "candidates": candidates}


def select_passive_motor_for_path(
    path: list[tuple[float, float]],
    calibration: dict | None = None,
    tension_floor_ma: object = TRACKING_DEFAULT_CURRENT,
) -> dict:
    """Choose one torque cable for a path without mode-switching mid-motion.

    Every candidate is scored on its worst three-cable observability and its
    worst required equilibrium current over a dense path sample.  Holding one
    choice for the full continuous path avoids a position/torque mode jerk.
    Calibration sweeps deliberately rotate this role across all four motors.
    """
    data = calibration if calibration is not None else calibration_data()
    if len(path) < 1:
        return {"ok": False, "passive_index": None, "reason": "路径为空", "candidates": []}
    # A hand-drawn path can contain thousands of 0.35 mm points.  Forty-one
    # evenly spaced samples preserve the path envelope while keeping selection
    # fast enough to happen before the gentle start move.
    if len(path) > 41:
        path = [
            path[round(index * (len(path) - 1) / 40)]
            for index in range(41)
        ]
    samples: list[tuple[float, float]] = []
    if len(path) == 1:
        samples.append(tuple(path[0]))
    else:
        for first, second in zip(path, path[1:]):
            for step in range(9):
                fraction = step / 8.0
                samples.append(
                    (
                        first[0] + (second[0] - first[0]) * fraction,
                        first[1] + (second[1] - first[1]) * fraction,
                    )
                )
        samples.append(tuple(path[-1]))
    candidates = []
    for passive in range(len(MOTOR_IDS)):
        determinants = [
            planar_active_set_observability(x, y, passive, data)
            for x, y in samples
        ]
        passive_currents: list[float] = []
        for x, y in samples:
            targets = equilibrium_current_targets(x, y, tension_floor_ma, data)
            values = targets.get("target_currents_ma") if targets.get("ok") else None
            if isinstance(values, list) and len(values) == len(MOTOR_IDS):
                passive_currents.append(float(values[passive]))
            else:
                passive_currents.append(float(OPERATING_CURRENT_MAX_MA))
        minimum_det = min(determinants, default=0.0)
        maximum_current = max(passive_currents, default=float(OPERATING_CURRENT_MAX_MA))
        # Current is a soft ranking term; a near-singular active trio is always
        # rejected even if that cable would otherwise need little tension.
        score = minimum_det / max(1.0, maximum_current / max(1.0, float(tension_floor_ma)))
        candidates.append(
            {
                "passive_index": passive,
                "motor_id": MOTOR_IDS[passive],
                "minimum_observability_det": minimum_det,
                "maximum_passive_current_ma": maximum_current,
                "score": score,
            }
        )
    viable = [item for item in candidates if item["minimum_observability_det"] >= HYBRID_MIN_OBSERVABILITY_DET]
    if not viable:
        return {"ok": False, "passive_index": None, "reason": "路径存在三绳奇异区", "candidates": candidates}
    # Prefer M4 on an exact score tie because it is the redundant cable in the
    # first validation run; otherwise use the measurable path-wide score.
    selected = max(viable, key=lambda item: (item["score"], item["passive_index"] == 3))
    return {"ok": True, **selected, "candidates": candidates}


def compute_external_pose_calibration(
    pose_samples: list[dict],
    base_calibration: dict | None = None,
    *,
    source: str = "camera",
) -> tuple[dict | None, str]:
    """Fit spool curves from externally measured ball poses.

    Each sample must contain ``xy_mm=[x,y]``, ``positions_deg=[M1..M4]`` and
    optionally ``yaw_deg``.  The pose is deliberately not reconstructed from
    the encoder values: the camera/fixture measurement is the independent
    observation that breaks the circular centre-calibration loop.  Small
    encoder noise is projected monotonically per motor; large reversals are
    rejected instead of silently bending the model.
    """
    base = copy.deepcopy(base_calibration) if isinstance(base_calibration, dict) else calibration_data()
    source_key = str(source or "").strip().lower()
    if source_key not in EXTERNAL_POSE_SOURCE_KEYS:
        return None, "外部位姿标定只接受 camera/AprilTag/ArUco/量具来源，拒绝编码器或等电流自证"
    if not isinstance(pose_samples, list) or len(pose_samples) < EXTERNAL_POSE_MIN_SAMPLES:
        return None, f"外部位姿标定至少需要 {EXTERNAL_POSE_MIN_SAMPLES} 个独立位姿样本"
    width, height = workspace_dimensions(base)
    parsed: list[dict] = []
    try:
        for index, item in enumerate(pose_samples):
            if not isinstance(item, dict):
                return None, f"外部位姿样本 {index + 1} 不是对象"
            point = item.get("xy_mm") or item.get("position_mm")
            if point is None and "x_mm" in item and "y_mm" in item:
                point = [item.get("x_mm"), item.get("y_mm")]
            positions = item.get("positions_deg") or item.get("encoder_positions_deg")
            if not isinstance(point, (list, tuple)) or len(point) != 2:
                return None, f"外部位姿样本 {index + 1} 缺少 xy_mm=[x,y]"
            if not isinstance(positions, (list, tuple)) or len(positions) != len(MOTOR_IDS):
                return None, f"外部位姿样本 {index + 1} 缺少四台 positions_deg"
            x, y = float(point[0]), float(point[1])
            yaw = float(item.get("yaw_deg", 0.0))
            motor_positions = [float(value) for value in positions]
            if not all(math.isfinite(value) for value in [x, y, yaw, *motor_positions]):
                return None, f"外部位姿样本 {index + 1} 含非有限数字"
            if not (-5.0 <= x <= width + 5.0 and -5.0 <= y <= height + 5.0):
                return None, f"外部位姿样本 {index + 1} 超出 110×148mm 工作区"
            if abs(yaw) > EXTERNAL_POSE_MAX_YAW_DEG:
                return None, f"外部位姿样本 {index + 1} 偏航 {yaw:.1f}° 超过 ±{EXTERNAL_POSE_MAX_YAW_DEG:.1f}°，请先把球面标记方向对齐"
            parsed.append({"xy_mm": [x, y], "yaw_deg": yaw, "positions_deg": motor_positions})
    except (TypeError, ValueError):
        return None, "外部位姿样本包含无法解析的数字"
    if max(item["xy_mm"][0] for item in parsed) - min(item["xy_mm"][0] for item in parsed) < 40.0:
        return None, "外部位姿样本 X 覆盖不足，至少要横向分散 40mm"
    if max(item["xy_mm"][1] for item in parsed) - min(item["xy_mm"][1] for item in parsed) < 60.0:
        return None, "外部位姿样本 Y 覆盖不足，至少要纵向分散 60mm"

    base_slopes = effective_slopes(base)
    if len(base_slopes) != len(MOTOR_IDS):
        base_slopes = [-1.0, 1.0, -1.0, 1.0]
    curves: list[list[tuple[float, float]]] = []
    slopes: list[float] = []
    intercepts: list[float] = []
    r2_values: list[float] = []
    groups: list[list[float]] = []
    spreads: list[float] = []
    for motor in range(len(MOTOR_IDS)):
        pairs = sorted(
            (
                _external_pose_cable_lengths(item["xy_mm"][0], item["xy_mm"][1], item["yaw_deg"], base)[motor],
                item["positions_deg"][motor],
            )
            for item in parsed
        )
        merged = _coalesce_rope_curve(
            [pair[0] for pair in pairs], [pair[1] for pair in pairs], tolerance=0.5
        )
        if len(merged) < 4 or merged[-1][0] - merged[0][0] < EXTERNAL_POSE_MIN_DISTANCE_SPAN_MM:
            return None, f"M{motor + 1} 外部样本绳长覆盖不足，至少需要 {EXTERNAL_POSE_MIN_DISTANCE_SPAN_MM:.0f}mm 且 4 个有效距离"
        direction = 1.0 if float(base_slopes[motor]) >= 0.0 else -1.0
        signed = [direction * pair[1] for pair in merged]
        projected_signed = _isotonic_non_decreasing(signed)
        max_adjust = max(
            (abs(projected - observed) for projected, observed in zip(projected_signed, signed)),
            default=0.0,
        )
        if max_adjust > EXTERNAL_POSE_MAX_MONOTONIC_ADJUST_DEG:
            return None, f"M{motor + 1} 外部样本编码器顺序反转 {max_adjust:.1f}°，请检查方向/照片时间同步"
        projected = [direction * value for value in projected_signed]
        for index in range(1, len(projected)):
            if (projected[index] - projected[index - 1]) * direction <= 0.0:
                projected[index] = projected[index - 1] + direction * 0.001
        curve = [(merged[index][0], projected[index]) for index in range(len(merged))]
        if calibrated_rope_curve(
            {
                "distance_samples_mm": [[pair[0] for pair in curve]],
                "position_samples_deg": [[pair[1] for pair in curve]],
            },
            0,
        ) is None:
            return None, f"M{motor + 1} 外部样本无法生成单调绳长曲线"
        distances = [pair[0] for pair in curve]
        values = [pair[1] for pair in curve]
        mean_distance, mean_value = statistics.mean(distances), statistics.mean(values)
        denominator = sum((value - mean_distance) ** 2 for value in distances)
        fitted = sum((distance - mean_distance) * (value - mean_value) for distance, value in zip(distances, values)) / denominator
        own_intercept = mean_value - fitted * mean_distance
        residual = sum((value - (own_intercept + fitted * distance)) ** 2 for distance, value in zip(distances, values))
        total = sum((value - mean_value) ** 2 for value in values)
        score = 1.0 - residual / total if total > 0.001 else 0.0
        if abs(fitted) < 0.05 or score < EXTERNAL_POSE_MIN_LINEAR_R2:
            return None, f"M{motor + 1} 外部位姿拟合质量不足：R²={score:.3f}"
        slopes.append(fitted)
        intercepts.append(own_intercept)
        r2_values.append(score)
        groups.append([
            (values[index + 1] - values[index]) / (distances[index + 1] - distances[index])
            for index in range(len(curve) - 1)
        ])
        spreads.append(max_adjust)
        curves.append(curve)

    result = copy.deepcopy(base)
    result.update(
        {
            "valid": True,
            "workspace_width": width,
            "workspace_height": height,
            "side": height,
            "effective_side": height,
            "ball": DEFAULT_BALL_DIAMETER_MM,
            "geometry_version": GEOMETRY_VERSION,
            "coordinate_frame": "ball_center_workspace",
            "control_architecture": CONTROL_ARCHITECTURE,
            "platform_pose_model": PLATFORM_POSE_MODEL,
            "fixed_guide_exit_verified": False,
            "deterministic_spool_payout_verified": False,
            "orientation_mechanical_decoupling_verified": False,
            "orientation_mechanical_reason": (
                "外部 XY/偏航样本也没有观测球的滚转/俯仰；系绳点必须先与球姿态机械解耦"
            ),
            "workspace_calibration_verified": True,
            "external_pose_verified": True,
            "calibration_source": source_key,
            "slope": slopes,
            "raw_slope": list(slopes),
            "intercept": intercepts,
            "r2": r2_values,
            "groups": groups,
            "spread": spreads,
            "samples": [],
            "pose_reference_samples": parsed,
            "distance_samples_mm": [[pair[0] for pair in curve] for curve in curves],
            "position_samples_deg": [[pair[1] for pair in curve] for curve in curves],
            "grid_compensation": blank_grid_compensation(),
            "center_tension_calibration": blank_center_tension_calibration(),
            "internal_feedback_calibration": blank_internal_feedback_calibration(),
            "quality_error": "",
        }
    )
    model_context = calibration_model_context(result)
    result["model_family_key"] = model_context.get("model_family_key")
    result["position_reference_deg"] = model_context.get("position_reference_deg")
    result["position_reference"] = model_context.get("position_reference")
    return mark_internal_model_ready(result), ""


def read_motor_position(connection: object, address: int) -> float | None:
    reply = direct.transact(connection, direct.frame(address, 0x36, direct.FRAME_END))
    if not valid_reply(reply, address, 0x36, 8):
        return None
    value = direct.read_u32(reply, 3) / 10.0
    return -value if reply[2] else value


def relative_position_command(connection: object, address: int, direction: int, degrees: float = DIRECTION_TEST_DEGREES) -> tuple[bytes, bytes]:
    """Send a bounded relative move for the direction check.

    X firmware mode 2 means "relative to the current real-time position".
    It must receive the move amount (45 degrees), never the encoder's absolute
    position value.  Keeping this helper relative makes the test independent
    of the encoder's accumulated angle and avoids any reset move.
    """
    if degrees != DIRECTION_TEST_DEGREES:
        raise ValueError("正方向测试只允许发送 45° 相对位移")
    tx = direct.position_frame(address, direction, DIRECTION_TEST_RPM, 100, degrees, 2)
    reply = direct.transact(connection, tx, first_byte_timeout=0.3)
    if not direct.command_accepted(reply, address, 0xFD):
        detail = direct.hex_bytes(reply) if reply else "超时无回包"
        raise RuntimeError(f"电机 ID {address} 位置命令未确认，RX={detail}")
    return tx, reply


def wait_motor_travel(
    connection: object,
    address: int,
    origin: float,
    timeout: float = DIRECTION_TEST_TIMEOUT,
) -> float:
    """Wait for 45° of actual encoder travel without assuming its sign.

    The driver direction bit (CW/CCW) is not guaranteed to match the encoder
    position sign after a motor is installed with a different cable/winding
    orientation.  Direction confirmation is a physical check, so both +45°
    and -45° are valid observations; only the travel magnitude is bounded.
    """
    started = time.monotonic()
    last: float | None = None
    while time.monotonic() - started < timeout:
        if STOP_EVENT.is_set():
            raise RuntimeError("用户急停")
        for field in range(3):
            ok, reason = query_safety_field(connection, MOTOR_IDS.index(address), field)
            if not ok:
                raise RuntimeError(reason)
        current = read_motor_position(connection, address)
        if current is not None:
            last = current
            travel = abs(current - origin)
            if travel > DIRECTION_TEST_MAX_TRAVEL:
                raise RuntimeError(
                    f"电机 ID {address} 单次位移已达 {travel:.1f}°，超过 {DIRECTION_TEST_DEGREES:.0f}°测试上限，已停止"
                )
            if abs(travel - DIRECTION_TEST_DEGREES) <= DIRECTION_TEST_TOLERANCE or travel >= DIRECTION_TEST_DEGREES - DIRECTION_TEST_TOLERANCE:
                return current
        time.sleep(0.08)
    suffix = "" if last is None else f"，最后位置 {last:.1f}°"
    raise RuntimeError(
        f"电机 ID {address} 未在 {timeout:.0f} 秒内完成 {DIRECTION_TEST_DEGREES:.0f}° 实际位移{suffix}"
    )


def direction_test_worker(address: int) -> None:
    index = MOTOR_IDS.index(address)
    direction = pull_directions()[index]
    error: str | None = None
    try:
        set_state(auto="direction-test", direction_motor=address, message=f"M{index + 1} 正方向测试：检查 X 固件并读取原位置")
        with SERIAL_LOCK, direct.open_serial(current_port(), current_baud()) as connection:
            cleared = disable_all(connection)
            if not all(item["accepted"] for item in cleared):
                raise RuntimeError("方向测试启动前四台电机未能全部失能，已取消运动")
            firmware = read_firmware_status(connection, address)
            if firmware.get("firmware") != "X":
                raise RuntimeError(f"M{index + 1}/ID{address} 不是可确认的 X 固件，已取消运动")
            enabled, _, _ = enable_address(connection, address)
            if not enabled:
                raise RuntimeError(f"M{index + 1}/ID{address} 自动使能失败")
            original = read_motor_position(connection, address)
            if original is None:
                raise RuntimeError(f"M{index + 1}/ID{address} 读取当前位置失败，已取消运动")
            set_state(message=f"M{index + 1} 正方向测试：驱动器方向 {direction}，仅发送 {DIRECTION_TEST_DEGREES:.0f}° 相对位移")
            relative_position_command(connection, address, direction)
            observed = wait_motor_travel(connection, address, original)
            delta = observed - original
            set_state(message=f"M{index + 1} 已完成 {DIRECTION_TEST_DEGREES:.0f}° 测试（实际位置变化 {delta:+.1f}°），保持当前位置并失能")
            if not disable_one(connection, address):
                raise RuntimeError(f"M{index + 1}/ID{address} 测试后失能未收到 ACK")
            with STATE_LOCK:
                ready = copy.deepcopy(STATE.get("direction_ready", {}))
                ready[str(address)] = {
                    "id": address,
                    "direction": direction,
                    "original": round(original, 1),
                    "target": round(observed, 1),
                    "delta": round(delta, 1),
                    "completed": True,
                }
                STATE["direction_ready"] = ready
            set_state(auto="idle", direction_motor=None, message=f"M{index + 1} 已转 45° 并停在当前位置；请选择方向后保存")
    except Exception as exc:
        error = str(exc)
        set_state(auto="error", direction_motor=address, message=f"M{index + 1} 正方向测试失败：{error}")
    finally:
        if error or STOP_EVENT.is_set():
            recovery = disable_all_with_reconnect(
                current_port(), current_baud(), announce=True, clear_timed_streams=False
            )
            if not recovery["ok"]:
                set_state(
                    auto="error",
                    message=f"M{index + 1} 测试异常，RS485 重连后仍无法确认四台失能；请立即切断电机动力或使用硬件急停（{recovery['error']}）",
                )
        if STOP_EVENT.is_set() and not error:
            set_state(auto="idle", message="已停止，电机已发送急停")
        STOP_EVENT.clear()


def save_direction_choice(address: int, reverse: bool) -> dict:
    with STATE_LOCK:
        ready = copy.deepcopy(STATE.get("direction_ready", {})).get(str(address))
        calibration = copy.deepcopy(STATE["calibration"])
    if not ready or not ready.get("completed"):
        raise RuntimeError(f"请先完成 M{MOTOR_IDS.index(address) + 1} 的 45°正方向测试")
    reversals = list(direction_reversal_flags(calibration))
    if reverse:
        reversals[MOTOR_IDS.index(address)] = not reversals[MOTOR_IDS.index(address)]
    previous_reversals = list(calibration.get("direction_reverse", []))
    calibration["direction_reverse"] = reversals
    external_was_verified = calibration.get("external_pose_verified") is True
    internal_was_verified = calibration.get("internal_model_verified") is True
    previous_position_directions = list(encoder_positive_directions(calibration))
    position_directions = list(previous_position_directions)
    try:
        tested_direction = int(ready.get("direction"))
        observed_delta = float(ready.get("delta"))
        if tested_direction in (0, 1) and abs(observed_delta) >= 1.0:
            position_directions[MOTOR_IDS.index(address)] = tested_direction if observed_delta > 0 else tested_direction ^ 1
    except (TypeError, ValueError):
        pass
    calibration["encoder_positive_direction"] = position_directions
    direction_changed = reversals != previous_reversals or position_directions != previous_position_directions
    if internal_was_verified and direction_changed and calibration.get("valid") is True:
        # Direction changes alter the sign of every stored encoder sample.  A
        # previously fitted curve must not remain motion-ready until the four
        # physical corners have been rescanned.
        calibration["valid"] = False
        calibration["workspace_calibration_verified"] = False
        calibration["internal_model_verified"] = False
        calibration["internal_model_source"] = "none"
        calibration["quality_error"] = "电机方向已修改，请重新完成四角几何校准"
    if external_was_verified and direction_changed:
        calibration["external_pose_verified"] = False
        calibration["calibration_source"] = "torque_corner_initializer"
        calibration["external_pose_invalidated_reason"] = (
            "电机方向/编码器正方向已修改；原外部位姿样本保留作历史记录，必须重新拟合"
        )
    with STATE_LOCK:
        STATE["calibration"] = calibration
        STATE["direction_ready"] = {
            key: value for key, value in STATE.get("direction_ready", {}).items() if key != str(address)
        }
    chosen = pull_directions()[MOTOR_IDS.index(address)]
    persist_calibration(calibration)
    append_process_log("direction_saved", motor=address, reverse=reverse, direction=chosen)
    return {
        "ok": True,
        "action": "direction-save",
        "id": address,
        "reverse": reverse,
        "direction": chosen,
        "message": f"M{MOTOR_IDS.index(address) + 1} 正方向已保存为驱动器方向 {chosen}",
    }


def wait_calibration_hold(
    connection: object,
    hold: int,
    *,
    label: str,
    minimum_current_ma: float | None = None,
    maximum_rpm: float | None = None,
) -> list[direct.Telemetry]:
    """Reject obvious unload/drift; current is not a calibrated tension sensor."""

    started = time.perf_counter()
    deadline = started + CALIBRATION_HOLD_CHECK_SECONDS
    previous: list[float] | None = None
    previous_at: float | None = None
    previous_loaded = False
    stable_since: float | None = None
    stable_samples = 0
    overcurrent_since: float | None = None
    minimum_current = 0.0
    highest_rpm = 0.0
    while time.perf_counter() < deadline:
        if STOP_EVENT.is_set():
            raise RuntimeError("用户停止校准")
        try:
            values = read_all_reliable(connection, attempts=1, deadline=deadline)
        except TimeoutError:
            break
        if STOP_EVENT.is_set():
            raise RuntimeError("用户停止校准")
        # Keep the hard protection ceiling active, but do not treat one
        # driver-current sample above the small 300mA hold band as a fault.
        # Direct C5 hand-offs can produce a short, harmless current spike;
        # only a sustained spike is rejected below.
        fault = calibration_feedback_error(values, current_limit=OPERATING_CURRENT_MAX_MA)
        if fault:
            raise RuntimeError(label + "：" + fault)
        positions = [float(value.position) for value in values]
        currents = [abs(float(value.phase_current)) for value in values]
        now = time.perf_counter()
        hold_trip_limit = overcurrent_trip_limit(hold)
        high = [index for index, current in enumerate(currents) if current > hold_trip_limit]
        if high:
            overcurrent_since = overcurrent_since or now
            if now - overcurrent_since >= CALIBRATION_HOLD_OVERCURRENT_GRACE_SECONDS:
                detail = "、".join(
                    f"M{index + 1} {currents[index]:.0f}mA" for index in high
                )
                raise RuntimeError(
                    f"{label}：保持电流持续超过 {hold_trip_limit}mA（{detail}）"
                )
        else:
            overcurrent_since = None
        minimum_current = min(currents)
        highest_rpm = max(abs(float(value.rpm)) for value in values)
        # USB/driver feedback is quantized and can report one or two mA below
        # the commanded floor.  Keep the explicit floor, but tolerate that
        # small sampling error so a valid 300mA hold is not rejected at 299mA.
        if minimum_current_ma is None:
            loaded_floor = max(
                PERSISTED_CALIBRATION_MIN_HOLD_CURRENT_MA,
                float(hold) - CALIBRATION_HOLD_MIN_CURRENT_TOLERANCE_MA,
            )
        else:
            loaded_floor = max(PERSISTED_CALIBRATION_MIN_HOLD_CURRENT_MA, float(minimum_current_ma))
        loaded = minimum_current >= loaded_floor
        stationary = highest_rpm <= (
            CALIBRATION_HOLD_MAX_RPM if maximum_rpm is None else float(maximum_rpm)
        )
        # The hold command itself is the datum here.  Encoder position can
        # legitimately jump a few degrees as the driver changes from the last
        # corner's 1500mA to the 300mA floor, so do not reject a valid hold on
        # that one-shot position change; require two consecutive loaded,
        # stationary feedback samples instead.
        stable = loaded and previous_loaded and stationary and previous is not None
        stable_samples = stable_samples + 1 if stable else 0
        stable_since = (previous_at if stable_since is None else stable_since) if stable else None
        set_state(message=f"{label}：最低电流 {minimum_current:.0f}mA，最高转速 {highest_rpm:.1f}RPM")
        if stable_since is not None and now - stable_since >= CALIBRATION_HOLD_STABLE_SECONDS and stable_samples >= 3:
            append_process_log(
                "calibration_hold_checked", label=label,
                hold_current_ma=hold, phase_currents_ma=currents,
                positions_deg=positions, max_rpm=highest_rpm,
                elapsed_s=round(now - started, 6),
                evidence="stationary_encoder_and_current_floor_not_direct_tension_measurement",
            )
            return values
        previous, previous_at, previous_loaded = positions, now, loaded and stationary
        time.sleep(min(0.03, max(0.0, deadline - time.perf_counter())))
    raise RuntimeError(
        f"{label}在 {CALIBRATION_HOLD_CHECK_SECONDS:.1f} 秒内未通过："
        f"最低电流 {minimum_current:.0f}mA、最高转速 {highest_rpm:.1f}RPM；"
        f"{hold}mA 保持效果未确认，不能发布标定成功"
    )


def smooth_calibration_release(connection: object, active_index: int, strong: int, weak: int) -> list[direct.Telemetry]:
    """Use one smooth end envelope from the final corner into four-rope hold."""

    hold = max(SESSION_HOLD_CURRENT_MIN_MA, min(SESSION_HOLD_CURRENT_MAX_MA, int(weak)))
    start = calibration_corner_current_vector(active_index, strong, hold)
    set_state(calibration_stage="final_soft_hold")
    # One quintic envelope is enough here.  The former balanced intermediate
    # vector created a second perceptible pause after the last corner.
    smooth_torque_vector_ramp(
        connection,
        start,
        [hold for _ in MOTOR_IDS],
        max_rpm=CALIBRATION_TAKEUP_MAX_RPM,
        start_max_rpm=CALIBRATION_CORNER_MAX_RPM,
        max_slew_ma_per_s=CALIBRATION_ENTRY_EXIT_SLEW_MA_PER_S,
        driver_slope_ma_per_s=CALIBRATION_HARD_SWITCH_DRIVER_SLOPE_MA_PER_S,
        label="校准完成柔性降到保持",
        verify_safety=False,
    )
    return wait_calibration_hold(connection, hold, label="结束保持检查")


def capture_emergency_stop_rearm_checkpoint(port: str, baud: int) -> tuple[bool, str]:
    """Record the real encoder state after an acknowledged emergency stop.

    The motors remain disabled.  This checkpoint is only a bounded recovery
    datum for the next explicit calibration click; it does not re-enable or
    move anything by itself.
    """
    try:
        with SERIAL_LOCK, direct.open_serial(port, baud) as connection:
            values = read_all_reliable(
                connection,
                attempts=2,
                first_byte_timeout=0.12,
                inter_byte_quiet=0.004,
            )
        if not telemetry_ready_for_calibration(values):
            return False, "急停后无法完整读取四台编码器位置"
        positions = [float(value.position) for value in values]
        currents = [abs(float(value.phase_current)) for value in values]
        with STATE_LOCK:
            calibration = copy.deepcopy(STATE.get("calibration"))
        if not isinstance(calibration, dict) or calibration.get("valid") is not True:
            return False, "当前没有可恢复的有效四角模型"
        if calibration.get("internal_model_verified") is not True:
            return False, "当前四角模型尚未通过内部校验"
        calibration["session_local_verified"] = False
        calibration["session_tension_held"] = False
        calibration["session_invalid_reason"] = (
            "用户急停后电机保持失能；已保存急停位置，可原位快速恢复张力"
        )
        calibration["emergency_stop_rearm_available"] = True
        calibration["emergency_stop_checkpoint_positions_deg"] = [
            round(value, 3) for value in positions
        ]
        calibration["emergency_stop_checkpoint_currents_ma"] = [
            round(value, 1) for value in currents
        ]
        calibration["internal_model_source"] = "emergency_stop_rearmable"
        persist_calibration(calibration)
        with STATE_LOCK:
            STATE["calibration"] = calibration
        append_process_log(
            "emergency_stop_rearm_checkpoint",
            positions_deg=calibration["emergency_stop_checkpoint_positions_deg"],
            phase_current_ma=calibration["emergency_stop_checkpoint_currents_ma"],
        )
        return True, "急停位置已记录；下次点校准将原位快速恢复，无需重新采四角"
    except Exception as exc:
        return False, "急停后编码器位置记录失败：" + str(exc)


def rearm_emergency_stop_datum(
    connection: object,
    calibration: dict,
    *,
    deadline: float,
) -> tuple[bool, str]:
    """Re-enable at the captured stop positions and verify a bounded hold."""
    raw_positions = calibration.get("emergency_stop_checkpoint_positions_deg")
    try:
        positions = [float(value) for value in raw_positions]
    except (TypeError, ValueError):
        return False, "急停恢复位置检查点无效"
    if len(positions) != len(MOTOR_IDS) or any(not math.isfinite(value) for value in positions):
        return False, "急停恢复位置检查点不完整"
    succeeded = False
    try:
        for address in MOTOR_IDS:
            calibration_check_deadline(deadline)
            enabled, _, reply = enable_address(connection, address)
            if not enabled:
                return False, f"M{address} 急停后重新使能未确认（RX={direct.hex_bytes(reply) if reply else '空'}）"
        calibration_check_deadline(deadline)
        before = read_all_reliable(
            connection,
            attempts=2,
            first_byte_timeout=0.10,
            inter_byte_quiet=0.004,
            deadline=deadline,
        )
        start_currents = [
            max(0, min(OPERATING_CURRENT_MAX_MA, int(abs(float(value.phase_current)))))
            for value in before
        ]
        smooth_torque_vector_ramp(
            connection,
            start_currents,
            [CALIBRATION_BRUTE_FORCE_HOLD_CURRENT for _ in MOTOR_IDS],
            max_rpm=CALIBRATION_TAKEUP_MAX_RPM,
            start_max_rpm=CALIBRATION_TAKEUP_MAX_RPM,
            label="急停后原位恢复张力",
            verify_safety=True,
            max_slew_ma_per_s=CALIBRATION_ENTRY_EXIT_SLEW_MA_PER_S,
            driver_slope_ma_per_s=CALIBRATION_HARD_SWITCH_DRIVER_SLOPE_MA_PER_S,
        )
        values = wait_calibration_hold(
            connection,
            CALIBRATION_BRUTE_FORCE_HOLD_CURRENT,
            label="急停后原位恢复保持",
            # The rearm still commands the proven 300mA vector.  This relaxed
            # feedback gate only accounts for the X driver's current
            # quantisation and the short post-enable settling pulse; the final
            # 50mA/12RPM/20° checks below remain mandatory.
            minimum_current_ma=EMERGENCY_REARM_MIN_CURRENT_MA,
            maximum_rpm=PERSISTED_CALIBRATION_MAX_RESUME_RPM,
        )
        deltas = [
            abs(float(value.position) - target)
            for value, target in zip(values, positions)
        ]
        rpms = [abs(float(value.rpm)) for value in values]
        currents = [abs(float(value.phase_current)) for value in values]
        if max(deltas, default=0.0) > EMERGENCY_REARM_MAX_POSITION_DRIFT_DEG:
            return False, f"急停恢复时位置偏移 {max(deltas):.1f}°，超过安全上限"
        if max(rpms, default=0.0) > PERSISTED_CALIBRATION_MAX_RESUME_RPM:
            return False, f"急停恢复时仍在运动（最高 {max(rpms):.1f}RPM）"
        if min(currents, default=0.0) < EMERGENCY_REARM_MIN_CURRENT_MA:
            return False, (
                f"急停恢复后最低保持电流 {min(currents, default=0.0):.0f}mA，"
                f"低于 {EMERGENCY_REARM_MIN_CURRENT_MA:.0f}mA"
            )
        updated = copy.deepcopy(calibration)
        updated["session_calibration_mode"] = SESSION_CALIBRATION_MODE
        updated["session_id"] = PROCESS_SESSION_ID
        updated["session_local_verified"] = True
        updated["session_tension_held"] = True
        updated["session_invalid_reason"] = ""
        updated["session_rearmed_from_emergency_stop"] = True
        updated["emergency_stop_rearm_available"] = False
        updated["session_resume_positions_deg"] = [
            round(float(value.position), 3) for value in values
        ]
        updated["session_resume_currents_ma"] = [round(value, 1) for value in currents]
        updated["tension_checkpoint_positions_deg"] = [
            round(float(value.position), 3) for value in values
        ]
        updated["tension_checkpoint_currents_ma"] = [round(value, 1) for value in currents]
        updated["tension_checkpoint_source"] = "emergency_stop_rearm"
        updated["tension_checkpoint_saved_at"] = round(time.time(), 3)
        updated["tension_checkpoint_controller"] = TENSION_CHECKPOINT_CONTROLLER_FOUR_POSITION_FORCE
        updated["tension_checkpoint_command_positions_deg"] = [round(value, 3) for value in positions]
        updated["tension_checkpoint_force_contraction_mm"] = 0.0
        updated = mark_internal_model_ready(updated)
        if updated.get("internal_model_verified") is not True:
            return False, "急停恢复后四角模型复核未通过"
        persist_calibration(updated)
        with STATE_LOCK:
            STATE["calibration"] = updated
        append_process_log(
            "emergency_stop_rearmed",
            positions_deg=updated["session_resume_positions_deg"],
            phase_current_ma=updated["session_resume_currents_ma"],
        )
        succeeded = True
        return True, "急停后原位恢复完成；四台已重新张紧，无需重新四角校准"
    finally:
        if not succeeded:
            try:
                disable_all(connection, invalidate=False)
            except Exception:
                pass


def try_enable_saved_calibration_datum() -> tuple[bool, str]:
    """Use a bounded budget for a saved-model check or emergency re-arm."""

    started = time.perf_counter()
    deadline = started + PERSISTED_CALIBRATION_TARGET_SECONDS
    lock_acquired = False
    emergency_rearm = False
    motion_commands_sent = False
    try:
        calibration = calibration_data()
        ready, reason = persisted_calibration_structure_ready(calibration)
        if not ready:
            return False, reason
        emergency_rearm = bool(calibration.get("emergency_stop_rearm_available"))
        if not is_same_tensioned_session(calibration) and not emergency_rearm:
            return False, (
                "参数已保存，但当前没有连续张紧的有效基准；断电、失能或服务重启后，"
                "需重新建立四角基准，相电流不能证明旧卷绕零点有效"
            )
        calibration_check_deadline(deadline)
        set_state(
            auto="calibration",
            calibration_run_mode="enable_saved",
            calibration_stage="precheck",
            calibration_expected_seconds=PERSISTED_CALIBRATION_TARGET_SECONDS,
            calibration_requires_full=False,
            calibration_last_error=None,
            calibration_auto_fallback=False,
            message=(
                f"正在执行急停后原位快速恢复：{PERSISTED_CALIBRATION_TARGET_SECONDS:.0f} 秒检查预算，不重新采四角"
                if emergency_rearm else
                f"正在启用已保存标定：{PERSISTED_CALIBRATION_TARGET_SECONDS:.0f} 秒检查预算，保持当前电机控制"
            ),
        )
        while not lock_acquired:
            calibration_check_deadline(deadline)
            lock_acquired = SERIAL_LOCK.acquire(timeout=min(0.02, max(0.0, deadline - time.perf_counter())))
            if not lock_acquired and time.perf_counter() >= deadline:
                return False, (
                    f"串口被其他流程占用，{PERSISTED_CALIBRATION_TARGET_SECONDS:.0f} 秒内无法完成检查；"
                    "请等待当前动作结束后重试"
                )
        calibration_check_deadline(deadline)
        with direct.open_serial(current_port(), current_baud()) as connection:
            calibration_check_deadline(deadline)
            if emergency_rearm:
                motion_commands_sent = True
                enabled, reason = rearm_emergency_stop_datum(
                    connection,
                    calibration,
                    deadline=deadline,
                )
            else:
                enabled, reason = adopt_persisted_tensioned_calibration(connection, deadline=deadline)
            calibration_check_deadline(deadline)
        if not enabled:
            return False, reason
        set_state(
            auto="idle",
            calibration_run_mode="enable_saved",
            calibration_stage="complete",
            calibration_requires_full=False,
            calibration_last_error=None,
            calibration_auto_fallback=False,
            message=reason,
        )
        return True, reason
    except Exception as exc:
        reason = str(exc)
        append_process_log("saved_calibration_enable_rejected", reason=reason)
        # This operation wrote only queries.  A failed query must not suddenly
        # disable or replace the four-position hold that was already running.
        return False, reason
    finally:
        if lock_acquired:
            SERIAL_LOCK.release()
        elapsed = max(0.0, time.perf_counter() - started)
        set_state(calibration_elapsed_seconds=round(elapsed, 3))
        append_process_log(
            "saved_calibration_check_finished",
            elapsed_s=round(elapsed, 6),
            target_seconds=PERSISTED_CALIBRATION_TARGET_SECONDS,
            read_only=not emergency_rearm,
            motion_commands_sent=int(motion_commands_sent),
        )


def enable_saved_calibration_worker() -> None:
    """Run only the fast saved-model check; never fall through into motion."""

    enabled, reason = try_enable_saved_calibration_datum()
    if STOP_EVENT.is_set():
        # The API delegates an explicit emergency stop to the active worker.
        # Ordinary read-only failure preserves hold, but STOP must never be
        # swallowed merely because this worker sent no motion commands itself.
        invalidate_session_calibration("用户停止启用已保存标定，持续张紧基准已终止")
        try:
            recovery = disable_all_with_reconnect(current_port(), current_baud(), announce=False)
        except Exception as exc:
            recovery = {"ok": False, "error": str(exc)}
        acknowledged = recovery.get("ok") is True
        set_state(
            auto="idle" if acknowledged else "error",
            calibration_run_mode="enable_saved",
            calibration_stage="stopped" if acknowledged else "failed",
            calibration_requires_full=True,
            calibration_last_error=None if acknowledged else str(recovery.get("error") or "失能未确认"),
            calibration_auto_fallback=False,
            message=(
                "已按急停结束标定检查，四台失能已确认；保存参数保留"
                if acknowledged else
                "急停已请求，但无法确认四台失能；请立即使用硬件急停或切断动力："
                + str(recovery.get("error") or "没有可靠回包")
            ),
        )
        append_process_log("saved_calibration_check_stopped", disable_acknowledged=acknowledged)
        STOP_EVENT.clear()
        return
    if not enabled:
        invalidate_session_calibration("启用已保存标定未通过：" + reason)
        append_process_log(
            "saved_calibration_enable_failed",
            reason=reason,
            automatic_full_calibration_started=False,
        )
        set_state(
            auto="error",
            calibration_run_mode="enable_saved",
            calibration_stage="failed",
            calibration_requires_full=True,
            calibration_last_error=reason,
            calibration_auto_fallback=False,
            message=(
                "启用已保存标定失败："
                + reason
                + "；已保留保存的几何模型，未自动执行大力四角校准。请确认机构无人接触、急停已释放且四台保持失能；"
                "急停恢复可用时可直接再次点击‘校准’，如按钮仍灰再点击‘连接’后重试；需要重采四角时请展开高级调试并显式启动完整校准"
            ),
        )
    STOP_EVENT.clear()


def position_probe_worker(zero_current_takeover: bool = False) -> dict:
    """Diagnostic in fresh encoder coordinates, never an XY calibration bypass."""
    set_state(auto="position-probe", repeat=False, control_unlocked=False,
              message=("实机位置验证：零电流包络内接管当前位置；暂不增加电流或发送位移轨迹"
                       if zero_current_takeover else
                       "实机位置验证：先检查失能态当前位置指令握手；不使用旧绳长零点"))
    try:
        from y42_position_probe_io import run_hardware_position_probe
        if zero_current_takeover is not False and zero_current_takeover is not True:
            raise ValueError("接管阶段必须为固定布尔选项")
        outcome = (run_hardware_position_probe(sys.modules[__name__], zero_current_takeover=True)
                   if zero_current_takeover else run_hardware_position_probe(sys.modules[__name__]))
        if not isinstance(outcome, dict):
            raise RuntimeError("实测适配器没有返回可核验的结果")
    except Exception as exc:
        # Unexpected adapter failures must not strand the UI in a running,
        # unlocked state. Do not assume unknown temporary limits were restored.
        STOP_EVENT.set()
        set_state(auto="error", control_unlocked=False,
                  message="位置验证异常，正在请求失能；恢复状态未知：" + str(exc))
        try:
            recovery = disable_all_with_reconnect(current_port(), current_baud(), announce=True,
                                                 clear_timed_streams=False)
        except Exception as cleanup_error:
            recovery = {"ok": False, "error": str(cleanup_error)}
        outcome = {"success": False, "reason": str(exc), "disable_recovery": recovery,
                   "final_disabled_confirmed": False, "configuration_restored": False,
                   "cleanup_unknown": True, "xyz_precision_measured": False}
        manual_test_emit("position_probe_unexpected_failure", **outcome)
    axes = outcome.get("axis_results", [])
    passed = (all(outcome.get(key) is True for key in
                  ("success", "final_hold_verified", "final_disabled_confirmed", "configuration_restored"))
              and isinstance(axes, list) and len(axes) == 4
              and all(isinstance(row, dict) and row.get("id") == index + 1
                      for index, row in enumerate(axes)))
    if not passed and outcome.get("success") is True:
        outcome.update(success=False, reason="实测或安全收尾证据不完整，未判通过")
    handshake_only = (outcome.get("stage") == "disabled_cb_handshake_only"
                      and all(outcome.get(key) is True for key in
                              ("handshake_passed", "final_disabled_confirmed", "configuration_restored")))
    zero_takeover_only = (outcome.get("stage") == "zero_current_takeover"
                          and all(outcome.get(key) is True for key in
                                  ("takeover_passed", "final_disabled_confirmed", "configuration_restored")))
    summary = {key: value for key, value in outcome.items()
               if key not in {"commands", "feedback", "snapshots", "raw_batches"}}
    set_state(auto="idle" if passed or handshake_only or zero_takeover_only else "error", control_unlocked=False,
              position_probe=summary,
              message=("四轴位置微幅验证通过，已停稳失能并恢复原配置；这不是小球XY精度证明"
                       if passed else "当前位置握手检查完成并恢复原配置；本轮未使能、未执行位移验证"
                       if handshake_only else "零电流当前位置接管检查完成，已停稳失能并恢复原配置；尚未验证轨迹"
                       if zero_takeover_only else "实机位置验证未通过：" + str(outcome.get("reason", "收尾未完整确认"))))
    return outcome


def position_microprobe_worker() -> dict:
    """Fixed encoder-only diagnostic; never publish a cable-length calibration."""
    set_state(auto="position-microprobe", repeat=False, control_unlocked=False,
              message="四轴半度往返验证：先低电流使能落稳，再升至150mA；逐帧检查实际反馈")
    try:
        from y42_adapter_versions import load_microprobe_adapter
        adapter, source_sha256 = load_microprobe_adapter()
        manual_test_emit("position_microprobe_adapter_version", source_sha256=source_sha256,
                         activation="new_worker_only", file=adapter.__file__)
        outcome = adapter.run_hardware_position_microprobe(sys.modules[__name__])
        if not isinstance(outcome, dict):
            raise RuntimeError("微幅实测适配器未返回可核验结果")
    except Exception as exc:
        STOP_EVENT.set()
        set_state(auto="error", control_unlocked=False,
                  message="微幅位置验证异常，正在请求失能；恢复状态未知：" + str(exc))
        try:
            recovery = disable_all_with_reconnect(current_port(), current_baud(),
                                                 announce=True, clear_timed_streams=True)
        except Exception as cleanup_error:
            recovery = {"ok": False, "error": str(cleanup_error)}
        outcome = {"success": False, "reason": str(exc), "disable_recovery": recovery,
                   "final_disabled_confirmed": False, "configuration_restored": False,
                   "cleanup_unknown": True, "xyz_precision_measured": False}
        manual_test_emit("position_microprobe_unexpected_failure", **outcome)
    if outcome.get("final_disabled_confirmed") is not True and "disable_recovery" not in outcome:
        # The adapter also returns structured failures. Its failed cleanup must
        # trigger the independent STOP/DISABLE path just like an exception does.
        STOP_EVENT.set()
        set_state(control_unlocked=False,
                  message="微幅验证收尾未确认，正在独立重连失能；原配置尚未恢复")
        try:
            recovery = disable_all_with_reconnect(current_port(), current_baud(),
                                                 announce=True, clear_timed_streams=True)
        except Exception as cleanup_error:
            recovery = {"ok": False, "error": str(cleanup_error)}
        outcome["disable_recovery"] = recovery
        # ACKs from the recovery helper do not establish fresh zero RPM or
        # restoration of the temporary envelope. Preserve both original flags.
        manual_test_emit("position_microprobe_structured_failure_recovery",
                         recovery=recovery, configuration_restored=outcome.get("configuration_restored"),
                         final_disabled_confirmed=outcome.get("final_disabled_confirmed"))
    axes = outcome.get("axis_results", [])
    passed = (all(outcome.get(key) is True for key in
                  ("success", "final_hold_verified", "final_disabled_confirmed", "configuration_restored"))
              and isinstance(axes, list) and len(axes) == 4
              and all(isinstance(row, dict) and row.get("id") == index + 1
                      for index, row in enumerate(axes)))
    if not passed and outcome.get("success") is True:
        outcome.update(success=False, reason="微幅运动或安全收尾证据不完整，未判通过")
    outcome["xyz_precision_measured"] = False
    summary = {key: value for key, value in outcome.items()
               if key not in {"commands", "feedback", "snapshots", "raw_batches", "probe_result"}}
    if isinstance(summary.get("cadence"), dict):
        summary["cadence"] = {key: value for key, value in summary["cadence"].items()
                              if key != "commands"}
    set_state(auto="idle" if passed else "error", control_unlocked=False,
              position_probe=summary,
              message=("四轴半度往返实测通过，已停稳失能并恢复原配置；这不是球心XY精度验收"
                       if passed else "四轴半度往返验证未通过：" + str(outcome.get("reason", "收尾证据不完整"))))
    return outcome


def torque_admission_worker() -> dict:
    """Fixed20mA/1RPM handoff test; never enables the old corner worker."""
    set_state(auto="torque-admission", control_unlocked=False, repeat=False,
              message="机械四角前置检查：逐轴20mA低力矩短时接管，随后恢复原位置")
    try:
        from y42_adapter_versions import load_microprobe_adapter
        adapter, source_sha256 = load_microprobe_adapter()
        manual_test_emit("torque_admission_adapter_version", source_sha256=source_sha256,
                         activation="new_worker_only", file=adapter.__file__)
        outcome = adapter.run_hardware_torque_admission(sys.modules[__name__])
        if not isinstance(outcome, dict):
            raise RuntimeError("低力矩验证未返回有效结果")
    except Exception as exc:
        STOP_EVENT.set()
        outcome = dict(success=False, reason=str(exc), final_disabled_confirmed=False,
                       configuration_restored=False)
    if outcome.get("final_disabled_confirmed") is not True:
        STOP_EVENT.set()
        try:
            outcome["disable_recovery"] = disable_all_with_reconnect(
                current_port(), current_baud(), announce=True, clear_timed_streams=True)
        except Exception as exc:
            outcome["disable_recovery"] = dict(ok=False, error=str(exc))
    axes = outcome.get("axis_results", [])
    passed = (all(outcome.get(key) is True for key in
                  ("success", "final_hold_verified", "final_disabled_confirmed", "configuration_restored"))
              and isinstance(axes, list) and len(axes) == 4
              and [row.get("id") for row in axes if isinstance(row, dict)] == [1, 2, 3, 4])
    outcome.update(success=bool(passed), calibration_published=False, xyz_precision_measured=False)
    manual_test_emit("torque_admission_result", result=outcome)
    summary = {key: outcome.get(key) for key in
               ("success", "reason", "stage", "axis_results", "final_hold_verified",
                "final_disabled_confirmed", "configuration_restored", "cleanup_errors",
                "calibration_published", "xyz_precision_measured", "elapsed_seconds")}
    set_state(auto="idle" if passed else "error", control_unlocked=False,
              torque_admission=summary,
              message=("四轴低力矩接管检查通过，已停稳失能并恢复配置；机械四角尚未执行" if passed else
                       "低力矩接管检查未通过：" + str(outcome.get("reason", "收尾证据不足"))))
    return outcome


def corner_stop_probe_worker() -> dict:
    """Bounded precursor to mechanical corner sampling, never a calibration."""
    set_state(auto="corner-stop-probe", control_unlocked=False, repeat=False,
              message="正在检查受限短行程与停滞特征；不将未动视为到达角点")
    try:
        from y42_adapter_versions import load_corner_probe_adapter
        adapter, digest = load_corner_probe_adapter()
        manual_test_emit("corner_stop_probe_adapter_version", source_sha256=digest)
        outcome = adapter.run_hardware_corner_stop_probe(sys.modules[__name__])
        if not isinstance(outcome, dict):
            raise RuntimeError("角点短行程检查未返回有效结果")
    except Exception as exc:
        STOP_EVENT.set()
        outcome = dict(success=False, reason=str(exc), final_disabled_confirmed=False)
    if outcome.get("final_disabled_confirmed") is not True:
        STOP_EVENT.set()
        try:
            outcome["disable_recovery"] = disable_all_with_reconnect(
                current_port(), current_baud(), announce=True, clear_timed_streams=True)
        except Exception as exc:
            outcome["disable_recovery"] = dict(ok=False, error=str(exc))
    outcome["calibration_published"] = False
    outcome["xyz_precision_measured"] = False
    passed = all(outcome.get(key) is True for key in
                 ("success", "final_disabled_confirmed", "configuration_restored"))
    outcome["success"] = passed
    manual_test_emit("corner_stop_probe_result", result=outcome)
    set_state(auto="idle" if passed else "error", control_unlocked=False,
              corner_stop_probe=outcome,
              message="角点短行程检查结束：" + str(outcome.get("reason", "请查看原始记录")))
    return outcome


def observation_sampling_worker() -> dict:
    """One bounded bench observation, never a calibration or pose command."""
    from y42_observation_sampler import ObservationConfig, run_observation_sampler

    started = time.perf_counter()
    outcome: dict = {"status": "not_started", "calibration_published": False}
    reader = None
    raw_guard = None
    stream_started = False
    owns_motor_commands = False
    original_configs: dict[int, bytes] = {}
    verified_configs: dict[int, bytes] = {}
    envelope_touched = False
    restore_attempted = False
    restore_failed = False
    restored: list[int] = []
    restore_unknown: list[int] = []
    restore_not_attempted: list[int] = []
    configuration_uncertain_axes: set[int] = set()
    final_disabled_confirmed = False
    error = None

    def envelope_reply(original, current):
        expected = bytearray(original)
        expected[16:18] = int(current).to_bytes(2, "big")
        expected[18:20] = (8).to_bytes(2, "big")
        return bytes(expected)

    def config_transaction(connection, address, tx, phase, *, write=False):
        nonlocal envelope_touched
        if not phase.startswith("restore"):
            if STOP_EVENT.is_set():
                raise RuntimeError("用户停止观察")
            if time.perf_counter() >= started + 14.0:
                raise RuntimeError("观察安全包络准备超过预算")
        if write:
            # A lost ACK does not mean that a volatile setting was not applied.
            envelope_touched = True
            configuration_uncertain_axes.add(address)
        reply = b""
        failure = None
        try:
            reply = direct.transact(connection, tx, first_byte_timeout=0.12,
                inter_byte_quiet=0.001,
                deadline=min(time.perf_counter() + 0.45, started + 14.0)
                    if not phase.startswith("restore") else time.perf_counter() + 0.45)
            return bytes(reply)
        except Exception as exc:
            failure = str(exc)
            raise
        finally:
            append_process_log("torque_observation_configuration_io", phase=phase,
                id=address, write=write, volatile=True, tx_hex=bytes(tx).hex(),
                rx_hex=bytes(reply).hex(), error=failure)

    def read_config(connection, address, phase):
        reply = config_transaction(connection, address,
            direct.frame(address, 0x42, 0x6C, direct.FRAME_END), phase)
        if (len(reply) != 37 or not valid_reply(reply, address, 0x42, 37)
                or reply[2] != 0x25 or reply[3] != 0x18):
            raise RuntimeError(f"M{address}完整X配置回包无效")
        return reply

    def verify_disabled(connection, phase):
        nonlocal final_disabled_confirmed
        final_disabled_confirmed = False
        rows = []
        for address in MOTOR_IDS:
            tx = direct.frame(address, 0x3A, direct.FRAME_END)
            reply = config_transaction(connection, address, tx, phase)
            rows.append({"id": address, "rx_hex": reply.hex(),
                "disabled": bool(len(reply) == 4 and valid_reply(reply, address, 0x3A, 4)
                                 and not reply[2] & ~0x3F and not reply[2] & 1)})
        append_process_log("torque_observation_disabled_confirmation", phase=phase, motors=rows)
        if not all(row["disabled"] for row in rows):
            raise RuntimeError("未获新鲜四台失能状态，禁止恢复或提高全量配置上限")
        final_disabled_confirmed = True

    def write_config_verified(connection, address, expected, phase, *, current_only=False):
        before = read_config(connection, address, phase + "_before")
        if before != verified_configs[address]:
            raise RuntimeError(f"M{address}配置在操作前发生变化，未覆盖未知设置")
        tx = (direct.frame(address, 0x45, 0x66, 0x00, *expected[16:18], direct.FRAME_END)
              if current_only else
              direct.frame(address, 0x48, 0xD1, 0x00, *expected[4:36], direct.FRAME_END))
        append_process_log("torque_observation_configuration_change", phase=phase, id=address,
            original_hex=original_configs[address].hex(), before_hex=before.hex(),
            expected_hex=expected.hex(), tx_hex=bytes(tx).hex(), store=0,
            current_only=current_only)
        reply = config_transaction(connection, address, tx, phase + "_write", write=True)
        if not direct.command_accepted(reply, address, 0x45 if current_only else 0x48):
            raise RuntimeError(f"M{address}{phase}配置写入未获ACK，应用结果未知")
        after = read_config(connection, address, phase + "_readback")
        append_process_log("torque_observation_configuration_readback", phase=phase, id=address,
            expected_hex=expected.hex(), actual_hex=after.hex(), exact_match=after == expected)
        if after != expected:
            raise RuntimeError(f"M{address}{phase}完整配置读回不一致，禁止继续")
        verified_configs[address] = after
        configuration_uncertain_axes.discard(address)

    def restore_original_configs(connection):
        nonlocal restore_attempted, restore_failed, restore_not_attempted, final_disabled_confirmed
        restore_attempted = True
        restore_not_attempted = list(original_configs)
        try:
            for address in original_configs:
                # Never infer disabled state from a STOP/DISABLE ACK or cache.
                verify_disabled(connection, "restore_disabled_gate")
                restore_not_attempted.remove(address)
                restore_unknown.append(address)
                # Failed earlier cap changes may have applied despite a lost ACK.
                # Read the real temporary config; then restore only while disabled.
                current = read_config(connection, address, "restore_current")
                original = original_configs[address]
                if current[:16] + current[20:] != original[:16] + original[20:]:
                    raise RuntimeError(f"M{address}限流限速之外的配置发生变化，拒绝覆盖未知设置")
                verified_configs[address] = current
                write_config_verified(connection, address, original_configs[address], "restore_original")
                restore_unknown.remove(address)
                restored.append(address)
            verify_disabled(connection, "restore_final_disabled")
        except Exception:
            restore_failed = True
            final_disabled_confirmed = False
            raise
        finally:
            append_process_log("torque_observation_configuration_restore", failed=restore_failed,
                restored=list(restored), unknown=list(restore_unknown),
                not_attempted=list(restore_not_attempted),
                originals_hex={str(k): value.hex() for k, value in original_configs.items()})

    try:
        set_state(auto="observation-sampling", repeat=False,
                  message="低力观察：先验证临时20mA/8RPM硬包络；结束失能后恢复原配置，不写标定")
        with SERIAL_LOCK, direct.open_serial(current_port(), current_baud()) as connection:
            try:
                connection.write_timeout = 0.1
                firmware = [read_firmware_status(connection, address) for address in MOTOR_IDS]
                if any(item.get("firmware") != "X" for item in firmware):
                    raise RuntimeError("观察启动：四台X固件回包不完整")
                initial = read_all_reliable(connection, attempts=2)
                if not telemetry_ready_for_calibration(initial):
                    raise RuntimeError("观察启动：完整遥测缺失")
                fault = calibration_feedback_error(initial, require_enabled=False)
                if fault:
                    raise RuntimeError(fault)
                if any(t.flags & 1 for t in initial):
                    raise RuntimeError("观察启动要求四台先处于已确认失能状态，不能抢占现有保持")
                initial_positions = [float(t.position) for t in initial]
                if time.perf_counter() - started > 5.0:
                    raise RuntimeError("只读启动检查超时，未启动采样")
                for address in MOTOR_IDS:
                    config = read_config(connection, address, "original_read")
                    original_configs[address] = config
                    verified_configs[address] = config
                    append_process_log("torque_observation_original_configuration", id=address,
                        reply_hex=config.hex(), mode=config[5],
                        closed_max_current_ma=int.from_bytes(config[16:18], "big"),
                        closed_max_rpm=int.from_bytes(config[18:20], "big"))
                    if (config[5] != 1 or int.from_bytes(config[16:18], "big") < 220
                            or int.from_bytes(config[18:20], "big") < 8):
                        raise RuntimeError(f"M{address}原配置不是闭环或已有上限更低，拒绝提高原有安全限制")
                verify_disabled(connection, "envelope_disabled_gate")
                owns_motor_commands = True
                restore_not_attempted = list(original_configs)
                for address in MOTOR_IDS:
                    write_config_verified(connection, address,
                        envelope_reply(original_configs[address], 20), "entry_envelope")
                verify_disabled(connection, "envelope_all_verified_disabled")
                # This device rejected disabled C5 in the recorded bench test.
                # Readback confirms configured limits, not physical compliance
                # or clearing an old target. This worker remains API-quarantined
                # after the recorded overspeed; do not infer safe enable here.
                for index, address in enumerate(MOTOR_IDS):
                    if STOP_EVENT.is_set():
                        raise RuntimeError("用户停止观察")
                    final_disabled_confirmed = False
                    enable_tx = direct.frame(address, 0xF3, 0xAB, 0x01, 0x00, direct.FRAME_END)
                    enable_rx = config_transaction(connection, address, enable_tx, "bounded_enable")
                    ok = direct.command_accepted(enable_rx, address, 0xF3)
                    append_process_log("torque_observation_bounded_enable", id=address,
                        tx_hex=bytes(enable_tx).hex(), rx_hex=bytes(enable_rx).hex(),
                        accepted=ok, driver_current_cap_ma=20, driver_rpm_cap=8)
                    if not ok:
                        raise RuntimeError(f"M{address}硬包络内使能失败")
                    tx = direct.torque_frame(address, pull_directions()[index], 20, 400, 8.0)
                    reply = config_transaction(connection, address, tx, "enabled_torque_20")
                    if not direct.command_accepted(reply, address, 0xC5):
                        raise RuntimeError(f"M{address}使能后20mA力矩未确认，禁止提高硬上限")
                for address in MOTOR_IDS:
                    write_config_verified(connection, address,
                        envelope_reply(original_configs[address], 220), "sampling_current_cap",
                        current_only=True)
                # All four known C5 targets remain 20 mA while feedback is
                # negotiated. Raising the current cap does not raise the target.
                stream_started = True  # Also clean a partially started stream.
                start_timed_feedback_stream(connection, 10, TIMED_FEEDBACK_INFO_CODE)
                if time.perf_counter() - started > 14.0:
                    raise RuntimeError("反馈准备超过低力观察入口预算")
                raw_guard = ObservationRawRecordGuard(initial_positions, STOP_EVENT, emit=append_process_log)
                reader = AsyncTimedFeedbackReader(connection, on_record=raw_guard)
                reader.start()
                assembler = FourMotorFeedbackAssembler(0.065)

                class ObservationClock:
                    @staticmethod
                    def now():
                        return time.perf_counter()

                    @staticmethod
                    def wait_until(deadline):
                        while time.perf_counter() < deadline:
                            if STOP_EVENT.is_set():
                                raise RuntimeError("用户停止观察")
                            time.sleep(min(0.005, max(0.0, deadline - time.perf_counter())))

                class ObservationIO:
                    def send_torque(self, currents_ma, *, max_rpm, deadline):
                        if raw_guard.failure is not None:
                            raise RuntimeError(raw_guard.failure["reason"])
                        reader.check()
                        if STOP_EVENT.is_set() or time.perf_counter() >= deadline:
                            raise RuntimeError("观察写入取消或超时")
                        send_fast(connection, four_motor_torque_frame(
                            currents_ma, torque_slope=400, torque_max_rpm=max_rpm))

                    def read_snapshot(self, *, deadline):
                        requested = time.perf_counter()
                        while time.perf_counter() < deadline:
                            if raw_guard.failure is not None:
                                raise RuntimeError(raw_guard.failure["reason"])
                            reader.check()
                            if STOP_EVENT.is_set():
                                raise RuntimeError("用户停止观察")
                            newest = None
                            for record in reader.drain():
                                packet = assembler.add(record)
                                if packet is not None:
                                    newest = packet
                            if newest is not None and min(item.sampled_at for item in newest) >= requested - 0.08:
                                # NO time projection, cached telemetry, or model
                                # inversion: these are the actual 0x43 fields.
                                values = [direct.Telemetry(
                                    address=item.address, position=item.position,
                                    rpm=item.rpm, phase_current=item.phase_current,
                                    temperature=item.temperature, flags=item.flags,
                                    voltage=item.voltage, bus_current=item.bus_current,
                                ) for item in newest]
                                update_telemetry(values)
                                return {"captured_start": min(item.sampled_at for item in newest),
                                        "captured_end": max(item.sampled_at for item in newest),
                                        "motors": values, "clock_source": "host_receive_not_device"}
                            time.sleep(0.002)
                        raise RuntimeError("观察缺少新鲜完整四台0x43反馈")

                    @staticmethod
                    def emit(event, **fields):
                        append_process_log(event, **fields)

                    @staticmethod
                    def emergency_stop(reason):
                        raw_guard.require_enabled = False
                        STOP_EVENT.set()
                        # Send protective commands immediately on the already
                        # owned handle; the outer cleanup then confirms disable.
                        for address in MOTOR_IDS:
                            for action in ("stop", "disable"):
                                try:
                                    send_fast(connection, command_frame(address, action, {}))
                                except Exception:
                                    pass
                        return {"disable_requested": True, "confirmed": False, "reason": reason}

                observation_io = ObservationIO()

                def entry_snapshot(phase, deadline):
                    batch = observation_io.read_snapshot(deadline=deadline)
                    values = batch["motors"]
                    append_process_log("torque_observation_raw_batch", phase=phase,
                        captured_start=batch["captured_start"], captured_end=batch["captured_end"],
                        motors=[{name: getattr(item, name) for name in
                            ("address", "position", "rpm", "phase_current", "temperature", "flags")}
                            for item in values])
                    fault = calibration_feedback_error(values, require_enabled=False)
                    if fault:
                        raise RuntimeError(fault)
                    if any(abs(t.rpm) > 25 or abs(t.phase_current) > 400 or t.temperature >= 45
                           or abs(t.position - initial_positions[i]) > 90 for i, t in enumerate(values)):
                        raise RuntimeError("观察入口超过速度/电流/温度/位移边界")
                    return values

                # From stream start to shutdown, only the reader consumes RX.
                # Reconfirm the bounded synchronous enables using fresh flags.
                enable_started = time.perf_counter()
                while True:
                    enabled_values = entry_snapshot("enable_confirmation", enable_started + 0.65)
                    if all(t.flags & 1 for t in enabled_values):
                        break
                    if time.perf_counter() >= enable_started + 0.60:
                        raise RuntimeError("观察使能未获新鲜四台状态确认")
                    time.sleep(0.01)
                known_hold = smooth_torque_vector_ramp(
                    connection, [20] * 4, [150] * 4, max_rpm=8.0,
                    label="仅观察的柔性入口", step_ma=8, dwell_seconds=0.02,
                    max_slew_ma_per_s=400.0, driver_slope_ma_per_s=400,
                    verify_safety=False,
                )
                startup = entry_snapshot("baseline_entry", time.perf_counter() + 0.25)
                fault = calibration_feedback_error(startup, require_enabled=True)
                if fault:
                    raise RuntimeError(fault)
                vectors = [(220,150,150,220), (150,220,220,150),
                           (220,220,150,150), (150,150,220,220),
                           (220,150,220,150), (150,220,150,220)]
                budget = min(15.0, 20.0 - (time.perf_counter() - started))
                if budget < 6.0:
                    raise RuntimeError("观察入口已耗尽预算，未尝试力矩向量")
                config = ObservationConfig(total_budget_s=budget, command_interval_s=0.02,
                    feedback_interval_s=0.10, maximum_feedback_age_s=0.20,
                    maximum_batch_span_s=0.065, io_timeout_s=0.25)
                outcome = run_observation_sampler(vectors, observation_io, ObservationClock(),
                    STOP_EVENT.is_set, initial_torque_currents_ma=known_hold, config=config)
                if outcome.get("status") == "safety_stopped":
                    raise RuntimeError(str(outcome.get("reason", "观察保护停止")))
                if not outcome.get("final_hold_verified"):
                    raise RuntimeError("观察结束没有获得连续静止窗口")
                outcome["sampling_hold_verified"] = True
                # End this diagnostic session disabled; do not silently leave a
                # low but possibly slack holding mode active. RX remains owned
                # by the reader throughout this gentle down-ramp.
                smooth_torque_vector_ramp(connection, [150] * 4, [20] * 4,
                    max_rpm=8.0, label="观察完成后柔降至20mA再失能", step_ma=8,
                    dwell_seconds=0.02, max_slew_ma_per_s=400.0,
                    driver_slope_ma_per_s=400, verify_safety=False)
                raw_guard.require_enabled = False
                for address in MOTOR_IDS:
                    for action in ("stop", "disable"):
                        send_fast(connection, command_frame(address, action, {}))
            except Exception:
                # Stop on the owned handle before potentially slow stream cleanup.
                if raw_guard is not None:
                    raw_guard.require_enabled = False
                if owns_motor_commands:
                    for address in MOTOR_IDS:
                        for action in ("stop", "disable"):
                            try:
                                send_fast(connection, command_frame(address, action, {}))
                            except Exception:
                                pass
                raise
            finally:
                if reader is not None:
                    reader.stop()
                    reader = None
                if stream_started:
                    if not stop_timed_feedback_stream(connection):
                        raise RuntimeError("观察结束后无法确认停止反馈流")
                    stream_started = False
            final_values = read_all_reliable(connection, attempts=2)
            if not telemetry_ready_for_calibration(final_values):
                raise RuntimeError("观察结束保持遥测缺失")
            fault = calibration_feedback_error(final_values, require_enabled=False)
            if fault:
                raise RuntimeError(fault)
            if any(t.flags & 1 or abs(t.rpm) > 0.6 or abs(t.phase_current) > 400 or t.temperature >= 45
                   for t in final_values):
                raise RuntimeError("观察结束未确认四台停稳失能，禁止恢复原上限")
            verify_disabled(connection, "restore_post_stream_disabled")
            final_disabled_confirmed = True
            if STOP_EVENT.is_set():
                raise RuntimeError("用户停止观察")
            restore_original_configs(connection)
            outcome.update(final_hold_verified=False, final_disabled_confirmed=True,
                           final_state="disabled_original_configuration_restored")
            count = len(outcome.get("samples", []))
            set_state(auto="idle", control_unlocked=False, observation_sampling={k: v for k, v in outcome.items()
                if k not in ("snapshots", "raw_batches", "samples")},
                message=f"观察结束：{count}个静止窗口，已柔降并确认四台失能，原配置已恢复；未写标定")
    except Exception as exc:
        error = raw_guard.failure["reason"] if raw_guard is not None and raw_guard.failure is not None else str(exc)
        outcome.update(status="safety_stopped", reason=error,
                       final_hold_verified=False, calibration_published=False)
        set_state(auto="error", control_unlocked=False, message="观察采样停止：" + error)
    finally:
        if (error or STOP_EVENT.is_set()) and owns_motor_commands:
            outcome.update(status="safety_stopped", reason=error or "用户停止观察",
                           final_hold_verified=False, calibration_published=False)
            try:
                recovery = disable_all_with_reconnect(current_port(), current_baud(), announce=True,
                                                     clear_timed_streams=False)
            except Exception as recovery_error:
                recovery = {"ok": False, "error": str(recovery_error)}
            outcome["disable_recovery"] = recovery
            try:
                # ACK alone is insufficient. Reopen only for shutdown/verification;
                # never resume observation or increase a cap with unknown enables.
                final_disabled_confirmed = False
                with SERIAL_LOCK, direct.open_serial(current_port(), current_baud()) as recovery_connection:
                    recovery_connection.write_timeout = 0.1
                    if not stop_timed_feedback_stream(recovery_connection):
                        raise RuntimeError("恢复前未确认关闭反馈流")
                    verify_disabled(recovery_connection, "restore_recovery_disabled")
                    final_disabled_confirmed = True
                    if envelope_touched and not restore_attempted:
                        restore_original_configs(recovery_connection)
            except Exception as cleanup_error:
                outcome["cleanup_error"] = str(cleanup_error)
                restore_failed = True
            if restore_failed or not final_disabled_confirmed:
                outcome.update(status="cleanup_failed")
                set_state(auto="error", control_unlocked=False,
                    message=("观察已停止，配置恢复未全部确认；已恢复M" + str(restored)
                        + "，未知M" + str(restore_unknown) + "，未尝试M" + str(restore_not_attempted)
                        + "。未恢复/未知轴的限制需按归档核对，不能假定仍低限值；请勿运行。"
                        + ("" if final_disabled_confirmed else "未确认四台失能，请切断动力或硬件急停。")))
            else:
                set_state(auto="error", control_unlocked=False,
                          message="观察已停止并确认四台失能，原配置已恢复：" + str(error or "用户停止"))
        outcome.update(final_disabled_confirmed=final_disabled_confirmed,
            configuration_restore={"attempted": restore_attempted, "failed": restore_failed,
                "restored": list(restored), "unknown": list(restore_unknown),
                "not_attempted": list(restore_not_attempted),
                "unconfirmed_limit_axes": sorted(configuration_uncertain_axes)},
            original_configurations_hex={str(k): value.hex() for k, value in original_configs.items()})
        outcome["raw_guard_fault"] = copy.deepcopy(raw_guard.failure) if raw_guard is not None else None
        append_process_log("torque_observation_end", elapsed_s=time.perf_counter() - started,
            status=outcome.get("status"), error=error, calibration_published=False,
            sample_count=len(outcome.get("samples", [])), envelope_touched=envelope_touched,
            final_disabled_confirmed=final_disabled_confirmed,
            configuration_restore=outcome["configuration_restore"],
            original_configurations_hex=outcome["original_configurations_hex"],
            raw_guard_fault=outcome["raw_guard_fault"])
        STOP_EVENT.clear()
    return outcome


def safe_four_corner_calibration_worker(
    width: float,
    height: float,
    ball: float,
    strong: int,
    weak: int,
) -> None:
    """Acquire four known XY corners with bounded absolute position control.

    The previous worker drove open-ended C5 force vectors and was quarantined
    after an overspeed.  This replacement keeps one serial owner, sends one
    four-motor absolute frame at a time, requires fresh complete telemetry and
    a stopped window at every known corner, and publishes only after all four
    rows pass ``compute_calibration``.  The prior model remains active until
    that final fit succeeds.
    """
    started = time.perf_counter()
    old_calibration = copy.deepcopy(calibration_data())
    samples: list[list[float]] = []
    error: str | None = None
    enabled = False
    candidate: dict | None = None
    hold = max(SESSION_HOLD_CURRENT_MIN_MA, min(SESSION_HOLD_CURRENT_MAX_MA, int(weak)))
    position_current = max(300, min(900, int(strong)))
    try:
        if not math.isclose(float(width), WORKSPACE_WIDTH_MM, abs_tol=0.0001) or not math.isclose(float(height), WORKSPACE_HEIGHT_MM, abs_tol=0.0001):
            raise RuntimeError("四角校准固定使用球心工作区110×148mm")
        corner_axes = workspace_corner_coordinates({"workspace_width": width, "workspace_height": height})
        corners = list(zip(*corner_axes))
        # A previous session may be explicitly invalid after disable/power
        # loss. Its four finite encoder rows are still a bounded *motion seed*
        # and are never treated as the new calibration result.
        corner_targets = calibration_corner_targets(old_calibration)
        if any(len(targets) != len(MOTOR_IDS) or any(not math.isfinite(float(v)) for v in targets) for targets in corner_targets):
            raise RuntimeError("四角几何目标无法生成，未启动电机")
        set_state(
            auto="calibration",
            calibration_run_mode="safe_four_corner_position",
            calibration_stage="precheck",
            calibration_requires_full=False,
            calibration_last_error=None,
            calibration_candidate=None,
            corner=0,
            point=0,
            points=4,
            repeat=False,
            message="安全四角采样：四电机绝对位置合帧，等待每个已知球心角点的新鲜停稳反馈",
        )
        with SERIAL_LOCK, direct.open_serial(current_port(), current_baud()) as connection:
            values = read_all_reliable(connection, attempts=2)
            fault = calibration_feedback_error(values, require_enabled=False)
            if fault:
                raise RuntimeError("四角采样启动检查：" + fault)
            current_positions = [float(item.position) for item in values]
            for address in MOTOR_IDS:
                ok, _, reply = enable_address(connection, address)
                if not ok:
                    raise RuntimeError(f"M{address}使能未确认：{direct.hex_bytes(reply) if reply else '无回包'}")
            enabled = True
            for corner_index, ((corner_x, corner_y), targets) in enumerate(zip(corners, corner_targets)):
                if STOP_EVENT.is_set():
                    raise RuntimeError("用户停止四角采样")
                set_state(
                    corner=corner_index + 1,
                    calibration_stage="corner_move",
                    message=f"安全四角采样 {corner_index + 1}/4：移动到球心 ({float(corner_x):.1f},{float(corner_y):.1f})mm",
                )
                max_delta = max(abs(float(target) - current) for target, current in zip(targets, current_positions))
                if max_delta > 900.0:
                    raise RuntimeError(f"角点 {corner_index + 1} 目标跨度 {max_delta:.1f}° 超过安全上限，未继续")
                move_to_start_smooth(
                    connection,
                    current_positions,
                    [float(target) for target in targets],
                    f"安全四角 {corner_index + 1}",
                    current=[position_current for _ in MOTOR_IDS],
                    # 2 RPM made a 480° corner transfer take over 35 s and
                    # guaranteed a timeout.  Ten RPM is still far below the
                    # configured driver ceiling, while the ramp remains
                    # bounded and all four axes stay in one absolute frame.
                    rpm=min(10.0, TRAJECTORY_START_RPM),
                )
                stable_since: float | None = None
                previous: list[float] | None = None
                stable_rows: list[list[float]] = []
                settle_started = time.perf_counter()
                while time.perf_counter() - settle_started < 10.0:
                    if STOP_EVENT.is_set():
                        raise RuntimeError("用户停止四角采样")
                    fresh = read_all_reliable(connection, attempts=1)
                    fault = calibration_feedback_error(fresh, current_limit=position_current, require_enabled=True)
                    if fault:
                        raise RuntimeError(f"角点 {corner_index + 1} 反馈保护：{fault}")
                    positions = [float(item.position) for item in fresh]
                    rpms = [abs(float(item.rpm)) for item in fresh]
                    stable = previous is not None and max(abs(a - b) for a, b in zip(positions, previous)) <= 0.20 and max(rpms) <= 0.60
                    if stable:
                        stable_since = stable_since or time.perf_counter()
                        stable_rows.append(positions)
                    else:
                        stable_since = None
                        stable_rows = []
                    previous = positions
                    set_state(message=f"角点 {corner_index + 1}/4：等待停稳（最高转速 {max(rpms):.2f}RPM）")
                    if stable_since is not None and time.perf_counter() - stable_since >= 0.40 and len(stable_rows) >= 3:
                        captured = [sum(row[index] for row in stable_rows[-5:]) / len(stable_rows[-5:]) for index in range(len(MOTOR_IDS))]
                        samples.append(captured)
                        append_process_log(
                            "safe_calibration_corner_sample",
                            corner=corner_index + 1,
                            xy=[float(corner_x), float(corner_y)],
                            target_positions=[round(float(value), 4) for value in targets],
                            measured_positions=[round(float(value), 4) for value in captured],
                            feedback_rows=len(stable_rows),
                            method="known_xy_absolute_position_feedback",
                        )
                        current_positions = captured
                        break
                    time.sleep(0.04)
                else:
                    raise RuntimeError(f"角点 {corner_index + 1} 在10秒内未形成新鲜停稳窗口")
            candidate, reason = compute_calibration(samples, width, height, ball)
            if candidate is None:
                raise RuntimeError("四角样本拟合未通过：" + reason)
            candidate["calibration_source"] = "safe_four_corner_position_feedback"
            candidate["calibration_method"] = "known_xy_corner_absolute_position"
            candidate["strong_current"] = position_current
            candidate["weak_current"] = hold
            candidate["session_hold_current_ma"] = hold
            candidate["calibration_persisted"] = False
            with STATE_LOCK:
                STATE["calibration_candidate"] = copy.deepcopy(candidate)
            append_process_log("safe_calibration_fit_candidate", samples=samples, r2=candidate.get("r2"), source=candidate.get("calibration_source"))
            # Keep the four motors at a conservative hold long enough to verify
            # the candidate; only then write the atomic calibration file.
            hold_values = read_all_reliable(connection, attempts=2)
            hold_fault = calibration_feedback_error(hold_values, current_limit=position_current, require_enabled=True)
            if hold_fault:
                raise RuntimeError("候选标定发布前保持检查失败：" + hold_fault)
            candidate["calibration_persisted"] = True
            persist_calibration(candidate)
            with STATE_LOCK:
                STATE["calibration"] = copy.deepcopy(candidate)
                STATE["calibration_candidate"] = None
            append_process_log("safe_calibration_published", samples=samples, source=candidate.get("calibration_source"), elapsed_s=round(time.perf_counter() - started, 6))
            set_state(auto="idle", calibration_stage="complete", calibration_run_mode="safe_four_corner_position", calibration_requires_full=False, calibration_last_error=None, last_failure=None, message="安全四角采样完成，四角拟合通过并已保存")
    except Exception as exc:
        error = str(exc)
        append_process_log("safe_calibration_error", error=error, samples=samples)
        set_state(auto="error", calibration_stage="failed", calibration_requires_full=True, calibration_last_error=error, message="安全四角采样停止：" + error)
    finally:
        keep_tensioned_session = bool(candidate and candidate.get("calibration_persisted") and not error)
        if (enabled or error) and not keep_tensioned_session:
            try:
                recovery = disable_all_with_reconnect(current_port(), current_baud(), announce=True)
            except Exception as exc:
                recovery = {"ok": False, "error": str(exc)}
            append_process_log("safe_calibration_cleanup", recovery=recovery, published=bool(candidate and candidate.get("calibration_persisted")), samples=len(samples))
        elif keep_tensioned_session:
            append_process_log(
                "safe_calibration_cleanup_skipped",
                published=True,
                reason="保留四轴绝对位置保持，供本次会话直接进入轨迹控制",
            )
            set_state(
                auto="idle",
                calibration_stage="complete",
                calibration_run_mode="safe_four_corner_position",
                calibration_requires_full=False,
                calibration_last_error=None,
                last_failure=None,
                message="安全四角采样完成，四角拟合通过、保持四台张紧，可直接运行实测轨迹",
            )
        if error:
            # The old persisted calibration stays intact; a failed candidate is
            # diagnostic evidence only and cannot silently invalidate the model.
            with STATE_LOCK:
                STATE["calibration_candidate"] = None
        set_state(calibration_elapsed_seconds=round(time.perf_counter() - started, 3))
        STOP_EVENT.clear()


def calibration_worker(
    width: float,
    height: float,
    ball: float,
    strong: int,
    weak: int,
) -> None:
    flow_started = time.perf_counter()
    samples: list[list[float]] = []
    error: str | None = None
    stop_requested = False
    published = False
    hold = max(CALIBRATION_BRUTE_FORCE_HOLD_CURRENT, min(SESSION_HOLD_CURRENT_MAX_MA, int(weak)))
    strong = max(CALIBRATION_BRUTE_FORCE_STRONG_CURRENT, min(OPERATING_CURRENT_MAX_MA, int(strong)))
    try:
        if STOP_EVENT.is_set():
            raise RuntimeError("用户停止校准")
        set_state(
            auto="calibration",
            calibration_run_mode="brute_force_four_corner",
            calibration_stage="precheck",
            calibration_expected_seconds=CALIBRATION_EXPECTED_SECONDS,
            calibration_requires_full=False,
            calibration_last_error=None,
            calibration_auto_fallback=False,
            corner=0,
            point=0,
            points=4,
            repeat=False,
            message=f"原始大力四角校准：强拉 {strong}mA、全绳保持 {hold}mA；保留急停和过流保护",
        )
        with SERIAL_LOCK, direct.open_serial(current_port(), current_baud()) as connection:
            initial_disable = disable_all(connection)
            if not all(item.get("accepted") for item in initial_disable):
                raise RuntimeError("大力校准启动前四台电机未能全部失能，已取消")
            firmware_results = [read_firmware_status(connection, address) for address in MOTOR_IDS]
            non_x = [
                f"M{result['id']}={result.get('firmware') or '无可靠回包'}"
                for result in firmware_results
                if result.get("firmware") != "X"
            ]
            if non_x:
                raise RuntimeError("启动检查失败：实际固件不是全 X（" + "、".join(non_x) + "）")
            values = read_all_reliable(connection)
            fault = calibration_feedback_error(values, require_enabled=False)
            if fault:
                raise RuntimeError("启动检查失败：" + fault)
            for corner in range(4):
                if STOP_EVENT.is_set():
                    raise RuntimeError("用户停止校准")
                set_state(
                    corner=corner + 1,
                    calibration_stage="brute_force_corner",
                    message=(
                        f"大力四角 {corner + 1}/4：M{corner + 1} 强拉 {strong}mA，"
                        f"其余三台保持 {hold}mA；保持四台使能"
                    ),
                )
                if corner == 0:
                    command_order = tuple(range(4))
                    for index, address in enumerate(MOTOR_IDS):
                        ok, _, reply = enable_address(connection, address)
                        if not ok:
                            detail = direct.hex_bytes(reply) if reply else "超时无回包"
                            raise RuntimeError(f"电机 M{index + 1} 使能未确认，RX={detail}")
                else:
                    # Pull the next corner hard before relaxing the previous
                    # one. This is the original brute-force hand-off that keeps
                    # the ball loaded instead of releasing the whole mechanism.
                    command_order = (corner, corner - 1)
                for index in command_order:
                    current = strong if index == corner else hold
                    accepted, _, reply = torque_command(
                        connection,
                        MOTOR_IDS[index],
                        pull_directions()[index],
                        current,
                        slope=CALIBRATION_HARD_SWITCH_DRIVER_SLOPE_MA_PER_S,
                        max_rpm=CALIBRATION_BRUTE_FORCE_MAX_RPM,
                    )
                    if not accepted:
                        detail = direct.hex_bytes(reply) if reply else "超时无回包"
                        raise RuntimeError(f"M{index + 1} 大力张紧命令未确认，RX={detail}")
                started = time.monotonic()
                previous: list[float] | None = None
                stable_started: float | None = None
                stable_positions: list[list[float]] = []
                previous_corner = samples[-1] if samples else None
                while True:
                    if STOP_EVENT.is_set():
                        raise RuntimeError("用户停止校准")
                    values = read_all_reliable(connection)
                    fault = calibration_feedback_error(values, current_limit=strong, require_enabled=True)
                    if fault:
                        raise RuntimeError(f"大力四角 {corner + 1}/4 反馈保护：{fault}")
                    positions = [float(item.position) for item in values]
                    rpms = [float(item.rpm) for item in values]
                    currents = [abs(int(item.phase_current)) for item in values]
                    if previous_corner is not None:
                        min_travel = max(CALIBRATION_CORNER_MIN_TRAVEL_DEG, max(width, height) * 1.4)
                        movement_ok = (
                            any(abs(positions[i] - previous_corner[i]) >= min_travel for i in range(4))
                            and abs(positions[corner] - previous_corner[corner]) >= min_travel
                        )
                    else:
                        movement_ok = time.monotonic() - started > 0.8
                    stable = (
                        currents[corner] >= max(300, int(strong * 0.25))
                        and abs(rpms[corner]) < CALIBRATION_CORNER_ACTIVE_SETTLE_RPM
                        and max(abs(rpm) for rpm in rpms) < CALIBRATION_CORNER_ALL_SETTLE_RPM
                        and previous is not None
                        and max(abs(positions[i] - previous[i]) for i in range(4)) <= CALIBRATION_CORNER_POSITION_SETTLE_DEG
                        and movement_ok
                    )
                    previous = positions
                    if stable:
                        stable_started = stable_started or time.monotonic()
                        stable_positions.append(positions)
                    else:
                        stable_started = None
                        stable_positions = []
                    set_state(
                        message=(
                            f"大力四角 {corner + 1}/4：M{corner + 1} 电流 {currents[corner]}mA，"
                            f"转速 {rpms[corner]:.1f}RPM，"
                            + ("确认绳路已绷直" if stable_started else "持续强拉")
                        )
                    )
                    if stable_started and time.monotonic() - stable_started >= CALIBRATION_CORNER_STABLE_SECONDS and len(stable_positions) >= 2:
                        captured = [sum(row[i] for row in stable_positions) / len(stable_positions) for i in range(4)]
                        samples.append(captured)
                        append_process_log(
                            "brute_force_calibration_corner",
                            corner=corner + 1,
                            samples=captured,
                            strong_current=strong,
                            hold_current=hold,
                        )
                        break
                    if time.monotonic() - started > CALIBRATION_BRUTE_FORCE_TIMEOUT_SECONDS:
                        raise RuntimeError(f"大力四角 {corner + 1} 在 {CALIBRATION_BRUTE_FORCE_TIMEOUT_SECONDS:.0f} 秒内未稳定到位")
                    time.sleep(0.05)
            result, reason = compute_calibration(samples, width, height, ball)
            if result is None:
                raise RuntimeError(reason)
            result["calibration_source"] = "brute_force_four_corner_torque"
            result["calibration_method"] = "original_strong_corner_pull_with_four_rope_hold"
            result["strong_current"] = strong
            result["weak_current"] = hold
            result["session_hold_current_ma"] = hold
            result["calibration_persisted"] = False
            append_process_log(
                "brute_force_calibration_fit_candidate",
                samples=samples,
                r2=result.get("r2"),
                strong_current=strong,
                hold_current=hold,
            )
            # Leave all four ropes loaded at the real holding floor.  This is
            # the original direct hand-off: M4 drops to the proven 300mA hold
            # after the fit, while the hold checker below filters only brief
            # driver-current spikes.
            accepted, _, reply = torque_command(
                connection,
                MOTOR_IDS[3],
                pull_directions()[3],
                hold,
                slope=CALIBRATION_HARD_SWITCH_DRIVER_SLOPE_MA_PER_S,
                max_rpm=CALIBRATION_BRUTE_FORCE_MAX_RPM,
            )
            if not accepted:
                detail = direct.hex_bytes(reply) if reply else "超时无回包"
                raise RuntimeError(f"末段四绳保持命令未确认，RX={detail}")
            final_values = wait_calibration_hold(connection, hold, label="大力四角完成后的四绳保持检查")
            result = persist_tension_checkpoint(
                result,
                final_values,
                "brute_force_four_corner_calibration_complete",
                publish=False,
            )
            result["calibration_persisted"] = True
            persist_calibration(result)
            with STATE_LOCK:
                STATE["calibration"] = copy.deepcopy(result)
            published = True
            append_process_log(
                "brute_force_calibration_complete",
                samples=samples,
                strong_current=strong,
                hold_current=hold,
                hold_feedback_verified=True,
                elapsed_s=round(time.perf_counter() - flow_started, 6),
            )
            set_state(
                auto="idle",
                calibration_run_mode="brute_force_four_corner",
                calibration_stage="complete",
                calibration_expected_seconds=CALIBRATION_EXPECTED_SECONDS,
                calibration_requires_full=False,
                calibration_last_error=None,
                calibration_auto_fallback=False,
                last_failure=None,
                message=(
                    f"大力四角校准完成：强拉 {strong}mA、四绳保持 {hold}mA，"
                    "四角拟合通过，绳路保持绷直，可直接运行轨迹"
                ),
            )
    except Exception as exc:
        error = str(exc)
        append_process_log("brute_force_calibration_error", error=error, corner=STATE.get("corner"), samples=samples)
        set_state(
            auto="error",
            calibration_run_mode="brute_force_four_corner",
            calibration_stage="failed",
            calibration_requires_full=True,
            calibration_last_error=error,
            calibration_auto_fallback=False,
            message="大力四角校准已停止：" + error,
            repeat=False,
        )
    finally:
        stop_requested = STOP_EVENT.is_set()
        if error or STOP_EVENT.is_set():
            invalidate_session_calibration(error or "用户停止大力校准")
            try:
                recovery = disable_all_with_reconnect(current_port(), current_baud(), announce=True)
            except Exception as exc:
                recovery = {"ok": False, "error": str(exc)}
            if not recovery["ok"]:
                set_state(
                    auto="error",
                    message="大力校准/通讯异常，自动重连后仍无法确认四台失能；请立即切断电机动力或使用硬件急停（" + recovery["error"] + "）",
                    repeat=False,
                )
        elif published:
            append_process_log("brute_force_calibration_hold_kept", hold_current=hold)
        STOP_EVENT.clear()
        elapsed = max(0.0, time.perf_counter() - flow_started)
        set_state(calibration_elapsed_seconds=round(elapsed, 3))
        append_process_log(
            "brute_force_calibration_finished",
            elapsed_s=round(elapsed, 6),
            success=published and not error and not stop_requested,
            corner_samples=len(samples),
            stopped=stop_requested,
        )


def grid_current_limits_from_feedback(
    current_limits: list[int],
    phase_currents: list[float | None],
    target_current: float,
    maximum_limit: int,
    minimum_limit: int = 300,
) -> list[int]:
    """Make small, bounded cap changes while a grid node is held.

    The returned values are command limits, not force measurements. A low
    phase-current reading gets a little more headroom; a persistently high
    reading gives some headroom back. The geometric motor target is untouched.
    """
    updated = list(current_limits)
    maximum = max(300, min(OPERATING_CURRENT_MAX_MA, int(maximum_limit)))
    floor = max(300, min(maximum, int(minimum_limit)))
    updated = [max(floor, min(maximum, int(value))) for value in updated]
    low_mark = max(float(GRID_TENSION_MIN_CURRENT_MA), target_current - GRID_TENSION_BAND_MA)
    high_mark = target_current + GRID_TENSION_BAND_MA
    for index, value in enumerate(phase_currents):
        if value is None or not math.isfinite(float(value)):
            continue
        observed = abs(float(value))
        if observed < low_mark:
            updated[index] = min(maximum, updated[index] + GRID_CURRENT_ADJUST_STEP_MA)
        elif observed > high_mark:
            updated[index] = max(floor, updated[index] - GRID_CURRENT_ADJUST_STEP_MA)
    return updated


def grid_position_bias_from_feedback(
    position_bias_deg: list[float],
    phase_currents: list[float | None],
    target_current: float,
    calibration: dict,
    step_deg: float = 1.0,
    limit_deg: float = 45.0,
) -> list[float]:
    """Nudge the local absolute target to keep each rope near 150±50mA.

    A phase-current value is only a tension proxy. When a node is stationary,
    a low value means reel in a small amount; a high value means give a small
    amount of rope back. The calibrated slope converts that length direction
    into the correct encoder direction for each motor. This local trim is
    stored in that node's position compensation, never applied as a global
    slope rewrite and never allowed to grow without bound.
    """
    if len(position_bias_deg) != len(MOTOR_IDS) or len(phase_currents) != len(MOTOR_IDS):
        return list(position_bias_deg)
    try:
        target = float(target_current)
        step = max(0.1, abs(float(step_deg)))
        limit = max(step, abs(float(limit_deg)))
    except (TypeError, ValueError):
        return list(position_bias_deg)
    low_mark = max(float(GRID_TENSION_MIN_CURRENT_MA), target - GRID_TENSION_BAND_MA)
    high_mark = min(float(GRID_TENSION_MAX_CURRENT_MA), target + GRID_TENSION_BAND_MA)
    raw_slopes = calibration.get("slope", calibration.get("raw_slope", [])) if isinstance(calibration, dict) else []
    try:
        slopes = [float(value) for value in raw_slopes]
    except (TypeError, ValueError):
        slopes = []
    updated = [float(value) for value in position_bias_deg]
    for index, value in enumerate(phase_currents):
        if value is None or not math.isfinite(float(value)):
            continue
        observed = abs(float(value))
        slope = slopes[index] if index < len(slopes) and math.isfinite(slopes[index]) else 1.0
        direction = 1.0 if slope >= 0.0 else -1.0
        if observed < low_mark:
            # Shorten the rope: position moves opposite to d(position)/d(length).
            updated[index] -= direction * step
        elif observed > high_mark:
            # Lengthen the rope to release an over-tight cable.
            updated[index] += direction * step
        updated[index] = max(-limit, min(limit, updated[index]))
    return [round(value, 3) for value in updated]


def grid_safety_error(values: list[direct.Telemetry], current_limits: list[int]) -> str | None:
    """Check a grid sample against its per-motor command caps."""
    if len(current_limits) != len(MOTOR_IDS):
        return "网格采样的四台电机电流上限不完整"
    for index, telemetry in enumerate(values):
        if not online(telemetry):
            return f"网格采样：电机 M{index + 1}/ID{telemetry.address} 通讯中断"
        if telemetry.temperature is not None and telemetry.temperature >= HARD_TEMPERATURE:
            return f"网格采样：电机 M{index + 1} 温度达到 {telemetry.temperature}°C"
        transient_limit = min(
            HARD_CURRENT,
            overcurrent_trip_limit(current_limits[index]) + GRID_OVERCURRENT_TRANSIENT_MARGIN_MA,
        )
        if telemetry.phase_current is not None and abs(float(telemetry.phase_current)) > transient_limit:
            return (
                f"网格采样：电机 M{index + 1} 电流 {abs(float(telemetry.phase_current)):.0f}mA "
                f"超过安全阈值 {transient_limit}mA"
            )
        if telemetry.flags is not None and telemetry.flags & 0x08:
            return f"网格采样：电机 M{index + 1} 触发驱动器保护"
    return None


def summarize_center_tension_level(
    confirmations: list[list[direct.Telemetry]],
    calibration: dict,
    command_current_ma: int,
    requested_floor_ma: int,
) -> dict:
    """Summarize one equal-current centre level without retaining raw samples."""
    position_rows = [
        [float(item.position) for item in values]
        for values in confirmations
        if telemetry_ready_for_calibration(values)
    ]
    current_rows = [
        [abs(float(item.phase_current)) for item in values]
        for values in confirmations
        if telemetry_ready_for_calibration(values)
    ]
    solved_rows = [
        position_to_xyz(row, calibration)
        for row in position_rows
    ]
    solved_rows = [row for row in solved_rows if row is not None]
    result = {
        "command_current_ma": int(command_current_ma),
        "sample_count": len(position_rows),
        "absolute_positions_deg": None,
        "phase_current_ma": None,
        "solved_xy_mm": None,
        "solved_z_mm": None,
        "z_fit_spread_mm": None,
        "xy_error_mm": None,
        "current_spread_ma": None,
        "position_jitter_deg": None,
        "median_z_squared_mm2": None,
        "absolute_lengths_physically_possible": False,
        "diagnostic_only": True,
        "pose_verified": False,
        "tension_floor_met": False,
        "current_balanced": False,
        "center_stable": False,
        "passed": False,
        "reason": "中心样本不足或四台位置/电流不完整",
    }
    if not position_rows or len(current_rows) != len(position_rows):
        return result
    median_positions = [statistics.median(row[index] for row in position_rows) for index in range(len(MOTOR_IDS))]
    median_currents = [statistics.median(row[index] for row in current_rows) for index in range(len(MOTOR_IDS))]
    result["absolute_positions_deg"] = [round(value, 3) for value in median_positions]
    result["phase_current_ma"] = [round(value, 1) for value in median_currents]
    result["current_spread_ma"] = round(max(median_currents) - min(median_currents), 1)
    result["position_jitter_deg"] = round(
        max(
            max(row[index] for row in position_rows) - min(row[index] for row in position_rows)
            for index in range(len(MOTOR_IDS))
        ),
        3,
    )
    # The driver's current feedback is quantised and may report 1--2mA below
    # the requested setpoint even when all four torque commands are equal.
    # Treat only a material shortfall as a failed floor, not that quantisation.
    result["tension_floor_met"] = min(median_currents) >= (
        float(requested_floor_ma) - CENTER_TENSION_CURRENT_FLOOR_TOLERANCE_MA
    )
    result["current_balanced"] = result["current_spread_ma"] <= CENTER_TENSION_MAX_CURRENT_SPREAD_MA
    if solved_rows:
        solved_xy = [
            statistics.median(row[index] for row in solved_rows)
            for index in range(2)
        ]
        solved_z = statistics.median(row[2] for row in solved_rows)
        z_spread = statistics.median(row[3] for row in solved_rows)
        expected_x = MECHANISM_CENTER_X_MM
        expected_y = MECHANISM_CENTER_Y_MM
        result["solved_xy_mm"] = [round(value, 3) for value in solved_xy]
        result["solved_z_mm"] = round(float(solved_z), 3)
        result["z_fit_spread_mm"] = round(float(z_spread), 3)
        result["xy_error_mm"] = round(
            math.hypot(solved_xy[0] - expected_x, solved_xy[1] - expected_y),
            3,
        )
        median_lengths = encoder_positions_to_lengths(median_positions, calibration)
        if median_lengths is not None:
            consistency = absolute_pose_consistency(
                median_lengths, solved_xy[0], solved_xy[1], calibration
            )
            result["median_z_squared_mm2"] = consistency["median_z_squared_mm2"]
            result["absolute_lengths_physically_possible"] = consistency["physically_possible"]
        # XY/Z is produced by the same encoder model under examination, so it is
        # diagnostic only and cannot verify a known centre.  The independent
        # facts available here are merely torque feedback and whether motion has
        # settled; neither is an absolute pose measurement.
        result["center_stable"] = bool(
            float(result["position_jitter_deg"]) <= CENTER_TENSION_MAX_POSITION_JITTER_DEG
        )
    result["passed"] = bool(
        result["tension_floor_met"]
        and result["current_balanced"]
        and result["center_stable"]
    )
    if result["passed"]:
        result["reason"] = (
            "等力矩静止状态稳定；仅作摩擦/张力诊断，不代表真实中心，也不会写入位置模型"
        )
    elif not result["tension_floor_met"]:
        result["reason"] = (
            f"最低实测相电流低于允许下限 "
            f"{requested_floor_ma - CENTER_TENSION_CURRENT_FLOOR_TOLERANCE_MA:.0f}mA"
        )
    elif not result["current_balanced"]:
        result["reason"] = f"四台实测相电流差 {result['current_spread_ma']:.1f}mA，仍不均衡"
    else:
        result["reason"] = "等力矩静止状态或绝对位置抖动未通过"
    return result


def select_center_tension_level(
    level_results: list[dict],
    requested_floor_ma: int,
) -> tuple[dict | None, str]:
    """Require consecutive high-current holds before accepting the centre.

    The encoder positions are compared between adjacent *increasing* torque
    levels. A level that is individually quiet can still be held by friction,
    so only a run of stable levels is eligible. The returned position is taken
    from the operator-selected floor level in that validated run; higher levels
    are stress checks and must not overwrite the 1500mA fifth datum.
    """
    validation_floor = max(int(requested_floor_ma), CENTER_TENSION_CONFIRM_START_MA)
    stable_run: list[dict] = []
    previous_positions: list[float] | None = None
    selected: dict | None = None
    for level in level_results:
        try:
            command_current = int(level.get("command_current_ma"))
        except (AttributeError, TypeError, ValueError):
            continue
        if command_current < validation_floor:
            continue
        positions = level.get("absolute_positions_deg")
        if not isinstance(positions, list) or len(positions) != len(MOTOR_IDS):
            stable_run = []
            previous_positions = None
            level["cross_level_drift_deg"] = None
            level["stable_high_level_count"] = 0
            continue
        try:
            current_positions = [float(value) for value in positions]
        except (TypeError, ValueError):
            stable_run = []
            previous_positions = None
            level["cross_level_drift_deg"] = None
            level["stable_high_level_count"] = 0
            continue
        drift = (
            None
            if previous_positions is None
            else max(abs(current - previous) for current, previous in zip(current_positions, previous_positions))
        )
        level["cross_level_drift_deg"] = round(drift, 3) if drift is not None else None
        cross_level_stable = drift is None or drift <= CENTER_TENSION_MAX_CROSS_LEVEL_DRIFT_DEG
        if level.get("passed") is True and cross_level_stable:
            stable_run.append(level)
        else:
            stable_run = []
        level["stable_high_level_count"] = len(stable_run)
        level["cross_level_stable"] = bool(cross_level_stable)
        previous_positions = (
            current_positions
            if level.get("passed") is True and cross_level_stable
            else None
        )
        if len(stable_run) >= CENTER_TENSION_MIN_STABLE_LEVELS:
            # The increasing-current run is validation only. The fifth datum
            # must represent the operator-selected calibration current (1500mA
            # in the normal workflow), not a higher stress-test level.
            calibration_level = next(
                (
                    item
                    for item in stable_run
                    if int(item.get("command_current_ma", -1)) == validation_floor
                ),
                stable_run[0],
            )
            selected = copy.deepcopy(calibration_level)
            selected["stability_run_levels_ma"] = [
                int(item["command_current_ma"]) for item in stable_run
            ]
            selected["stability_run_count"] = len(stable_run)
            selected["validation_floor_ma"] = validation_floor
            selected["terminal_level_absolute_positions_deg"] = list(
                stable_run[-1]["absolute_positions_deg"]
            )
            selected["calibration_level_ma"] = int(calibration_level["command_current_ma"])
    if selected is None:
        return (
            None,
            f"从 {validation_floor}mA 起没有连续 {CENTER_TENSION_MIN_STABLE_LEVELS} 个递增档位保持绝对位置不再漂移"
            f"（跨档位允许 ≤ {CENTER_TENSION_MAX_CROSS_LEVEL_DRIFT_DEG:.1f}°）",
        )
    return selected, ""


def center_tension_sweep_worker(
    requested_floor_ma: int | None = None,
    levels: tuple[int, ...] = CENTER_TENSION_SWEEP_LEVELS_MA,
) -> bool:
    """Find the lowest safe equal-current centre hold and add its fifth datum."""
    error: str | None = None
    stop_requested = False
    completed = False
    selected: dict | None = None
    level_results: list[dict] = []
    safety_stop_reason = ""
    timed_stream_active = False
    try:
        calibration = calibration_data()
        if not calibration.get("valid"):
            raise RuntimeError("请先完成四角几何校准，再进行五点中心张力测试")
        # A new multi-level verification supersedes any centre datum produced
        # by the older single-level rule.  Start from the trusted four-corner
        # model; only a newly proven stable run may write the fifth knot back.
        if has_center_tension_datum(calibration):
            calibration = strip_center_tension_datum(calibration)
            persist_calibration(calibration)
            with STATE_LOCK:
                STATE["calibration"] = copy.deepcopy(calibration)
        try:
            requested = int(
                requested_floor_ma
                if requested_floor_ma is not None
                else calibration.get("center_tension_target_current_ma", CENTER_TENSION_DEFAULT_CURRENT_MA)
            )
        except (TypeError, ValueError):
            raise RuntimeError("中心张力下限必须是有效整数") from None
        if not GRID_TENSION_MIN_CURRENT_MA <= requested <= GRID_TENSION_MAX_CURRENT_MA:
            raise RuntimeError(
                f"中心张力下限必须在 {GRID_TENSION_MIN_CURRENT_MA}..{GRID_TENSION_MAX_CURRENT_MA}mA"
            )
        sweep_levels = tuple(sorted({
            max(GRID_TENSION_MIN_CURRENT_MA, min(OPERATING_CURRENT_MAX_MA, int(value)))
            for value in levels
            if int(value) >= requested
        }))
        if not sweep_levels:
            raise RuntimeError("中心张力扫描没有有效电流档位")
        center_x = MECHANISM_CENTER_X_MM
        center_y = MECHANISM_CENTER_Y_MM
        center_targets = grid_motor_positions_at(center_x, center_y, calibration)
        state = blank_center_tension_calibration()
        state.update(
            {
                "status": "running",
                "expected_xy_mm": [center_x, center_y],
                "requested_floor_ma": requested,
                "levels": [],
                "scan_levels_ma": list(sweep_levels),
                "current_level_ma": None,
                "recommended_current_ma": None,
                "model_applied": False,
                "reason": f"正在用 X 固件 0xC5 等力矩从 {requested}→{OPERATING_CURRENT_MAX_MA}mA 逐档测试；连续3档确认不再转动",
            }
        )
        set_state(
            center_tension_calibration=state,
            auto="center-tension-sweep",
            message="五点中心张力测试：四台等电流，正在平滑移动到中心",
        )
        append_process_log(
            "center_tension_sweep_start",
            expected_xy_mm=[center_x, center_y],
            requested_floor_ma=requested,
            scan_levels_ma=list(sweep_levels),
            coordinate_frame="ball_center_workspace",
            model_family_key=calibration_model_context(calibration).get("model_family_key"),
        )
        with SERIAL_LOCK, direct.open_serial(current_port(), current_baud()) as connection:
            firmware = [read_firmware_status(connection, address) for address in MOTOR_IDS]
            non_x = [
                f"M{item['id']}={item.get('firmware') or '无可靠回包'}"
                for item in firmware
                if item.get("firmware") != "X"
            ]
            if non_x:
                raise RuntimeError("中心张力测试启动失败：实际固件不是全 X（" + "、".join(non_x) + ")")
            stopped = stop_all(connection)
            if not all(item.get("ok") for item in stopped):
                raise RuntimeError("中心张力测试启动前四台急停未全部收到 ACK")
            for index, address in enumerate(MOTOR_IDS):
                enabled, _, reply = enable_address(connection, address)
                if not enabled:
                    detail = direct.hex_bytes(reply) if reply else "超时无回包"
                    raise RuntimeError(f"中心张力测试：M{index + 1} 使能失败，RX={detail}")
            initial_values = read_all_reliable(connection, attempts=2)
            if not telemetry_ready_for_calibration(initial_values):
                raise RuntimeError("中心张力测试启动时四台位置/电流反馈不完整")
            approach_current = max(
                900,
                min(
                    OPERATING_CURRENT_MAX_MA,
                    int(calibration.get("strong_current", CALIBRATION_DEFAULT_STRONG_CURRENT)),
                ),
            )
            approach_limits = [approach_current for _ in MOTOR_IDS]
            approach_start_current = max(
                300,
                min(
                    approach_current,
                    int(calibration.get("weak_current", CALIBRATION_DEFAULT_WEAK_CURRENT)),
                ),
            )
            approach_start_limits = [approach_start_current for _ in MOTOR_IDS]
            safety = grid_safety_error(initial_values, approach_limits)
            if safety:
                raise RuntimeError("中心张力测试启动检查：" + safety)
            current_positions = [float(item.position) for item in initial_values]
            move_to_start_smooth(
                connection,
                current_positions,
                center_targets,
                "五点中心",
                current=approach_limits,
                rpm=GRID_START_RPM,
                current_start=approach_start_limits,
            )
            current_positions = wait_for_absolute_target(
                connection,
                center_targets,
                approach_limits,
                "五点中心到位确认",
                timeout=8.0,
                rpm=GRID_START_RPM,
                tolerance_deg=CENTER_TENSION_POSITION_TOLERANCE_DEG,
            )
            # Torque setpoints share the same half-duplex bus with four 0x43
            # streams. The 20 ms loaded-motion cadence leaves deterministic
            # gaps for those commands; the earlier 10 ms stream occasionally
            # dropped one motor's final command and left it exactly one or more
            # 100 mA levels behind.
            feedback_interval_ms = motion_feedback_interval_ms(current_baud())
            stream_buffer = bytearray()
            stream_position_history: dict[int, float] = {}
            stream_assembler = FourMotorFeedbackAssembler(
                timed_feedback_coherence_window(current_baud())
            )
            start_timed_feedback_stream(
                connection,
                feedback_interval_ms,
                TIMED_FEEDBACK_INFO_CODE,
            )
            feedback_interval_ms = int(
                getattr(connection, "_y42_feedback_interval_ms", feedback_interval_ms)
            )
            timed_stream_active = True
            previous_torque_current = approach_current
            center_feedback_times: list[float] = []
            center_feedback_count = 0
            for command_current in sweep_levels:
                if STOP_EVENT.is_set():
                    raise RuntimeError("用户停止五点中心张力测试")
                limits = [command_current for _ in MOTOR_IDS]
                level_error = ""
                # 0xCB's current field is only a position-mode ceiling and
                # produced 20..57mA on the real bus even when its field was
                # raised to 1500mA. Use the documented X-firmware 0xC5
                # torque command for this equal-force experiment. Commands
                # are sent back-to-back at the start of each level; the
                # command remains latched while telemetry is sampled.
                previous_torque_current = smooth_equal_torque_ramp_stream(
                    connection,
                    previous_torque_current,
                    command_current,
                )
                # The four ACKs only confirm that the commands were accepted;
                # the first current feedback frame can still be the previous
                # level. Give all four drivers one bounded settle window before
                # judging the 1500mA centre hold or the next ramp.
                settle_started = time.monotonic()
                settle_ready_count = 0
                previous_settle_positions: list[float] | None = None
                last_command_reassert_at = settle_started
                while time.monotonic() - settle_started < CENTER_TENSION_LEVEL_SETTLE_SECONDS:
                    if STOP_EVENT.is_set():
                        raise RuntimeError("用户停止五点中心张力测试")
                    snapshots = read_timed_feedback_snapshots(
                        connection,
                        stream_buffer,
                        stream_assembler,
                        stream_position_history,
                        timeout=0.005,
                    )
                    for values, sampled_at in snapshots:
                        safety = grid_safety_error(values, limits)
                        if safety:
                            level_error = safety
                            safety_stop_reason = f"{command_current}mA 档：{safety}"
                            break
                        center_feedback_count += 1
                        now = sampled_at
                        center_feedback_times.append(now)
                        center_feedback_times = [
                            stamp for stamp in center_feedback_times if now - stamp <= 1.0
                        ]
                        positions = [float(item.position) for item in values]
                        currents = [abs(float(item.phase_current)) for item in values]
                        position_step = (
                            max(
                                abs(current - previous)
                                for current, previous in zip(positions, previous_settle_positions)
                            )
                            if previous_settle_positions is not None
                            else 0.0
                        )
                        current_spread = max(currents) - min(currents)
                        current_ready = min(currents) >= (
                            float(command_current) - CENTER_TENSION_CURRENT_FLOOR_TOLERANCE_MA
                        ) and current_spread <= CENTER_TENSION_MAX_CURRENT_SPREAD_MA
                        reasserted_motors: list[int] = []
                        reassert_clock = time.monotonic()
                        if (
                            not current_ready
                            and reassert_clock - last_command_reassert_at
                            >= CENTER_TENSION_COMMAND_REASSERT_INTERVAL_SECONDS
                        ):
                            lagging = [
                                index
                                for index, current in enumerate(currents)
                                if current < float(command_current) - CENTER_TENSION_CURRENT_FLOOR_TOLERANCE_MA
                            ]
                            for index in lagging:
                                send_fast(
                                    connection,
                                    direct.torque_frame(
                                        MOTOR_IDS[index],
                                        pull_directions()[index],
                                        command_current,
                                        2000,
                                        1000,
                                    ),
                                )
                                reasserted_motors.append(index + 1)
                            last_command_reassert_at = reassert_clock
                            if reasserted_motors:
                                append_process_log(
                                    "center_tension_command_reassert",
                                    command_current_ma=command_current,
                                    motors=reasserted_motors,
                                    phase_current_ma=[round(value, 1) for value in currents],
                                )
                        if current_ready and position_step <= CENTER_TENSION_SETTLE_POSITION_STEP_DEG:
                            settle_ready_count += 1
                        else:
                            settle_ready_count = 0
                        previous_settle_positions = positions
                        feedback_hz = (
                            (len(center_feedback_times) - 1)
                            / max(center_feedback_times[-1] - center_feedback_times[0], 1e-6)
                            if len(center_feedback_times) > 1
                            else 0.0
                        )
                        set_state(
                            center_tension_calibration={
                                **state,
                                "levels": copy.deepcopy(level_results),
                                "current_level_ma": command_current,
                                "feedback_position_deg": [round(value, 2) for value in positions],
                                "feedback_phase_current_ma": [round(value, 1) for value in currents],
                                "feedback_hz_actual": round(feedback_hz, 1),
                                "feedback_sample_count": center_feedback_count,
                                "settle_elapsed_s": round(time.monotonic() - settle_started, 3),
                                "settle_ready_count": settle_ready_count,
                            },
                            message=(
                                f"五点中心 {command_current}mA：实时电流 "
                                f"{'/'.join(f'{value:.0f}' for value in currents)}mA，"
                                f"反馈 {feedback_hz:.1f}Hz，平稳确认 "
                                f"{settle_ready_count}/{CENTER_TENSION_SETTLE_CONSECUTIVE_SAMPLES}"
                            ),
                        )
                        append_process_log(
                            "center_tension_feedback",
                            command_current_ma=command_current,
                            phase="settle",
                            absolute_positions_deg=[round(value, 3) for value in positions],
                            phase_current_ma=[round(value, 1) for value in currents],
                            feedback_hz_actual=round(feedback_hz, 1),
                            settle_ready_count=settle_ready_count,
                        )
                        if settle_ready_count >= CENTER_TENSION_SETTLE_CONSECUTIVE_SAMPLES:
                            break
                    if level_error or settle_ready_count >= CENTER_TENSION_SETTLE_CONSECUTIVE_SAMPLES:
                        break
                    time.sleep(0.001)
                if level_error:
                    break
                confirmations: list[list[direct.Telemetry]] = []
                level_started = time.monotonic()
                while time.monotonic() - level_started < CENTER_TENSION_SWEEP_LEVEL_SECONDS:
                    if STOP_EVENT.is_set():
                        raise RuntimeError("用户停止五点中心张力测试")
                    snapshots = read_timed_feedback_snapshots(
                        connection,
                        stream_buffer,
                        stream_assembler,
                        stream_position_history,
                        timeout=0.005,
                    )
                    for values, sampled_at in snapshots:
                        safety = grid_safety_error(values, limits)
                        if safety:
                            level_error = safety
                            safety_stop_reason = f"{command_current}mA 档：{safety}"
                            break
                        confirmations.append(values)
                        center_feedback_count += 1
                        now = sampled_at
                        center_feedback_times.append(now)
                        center_feedback_times = [
                            stamp for stamp in center_feedback_times if now - stamp <= 1.0
                        ]
                        positions = [float(item.position) for item in values]
                        currents = [abs(float(item.phase_current)) for item in values]
                        feedback_hz = (
                            (len(center_feedback_times) - 1)
                            / max(center_feedback_times[-1] - center_feedback_times[0], 1e-6)
                            if len(center_feedback_times) > 1
                            else 0.0
                        )
                        set_state(
                            center_tension_calibration={
                                **state,
                                "levels": copy.deepcopy(level_results),
                                "current_level_ma": command_current,
                                "feedback_position_deg": [round(value, 2) for value in positions],
                                "feedback_phase_current_ma": [round(value, 1) for value in currents],
                                "feedback_hz_actual": round(feedback_hz, 1),
                                "feedback_sample_count": center_feedback_count,
                                "settle_ready_count": CENTER_TENSION_SETTLE_CONSECUTIVE_SAMPLES,
                            },
                            message=(
                                f"五点中心 {command_current}mA：实时电流 "
                                f"{'/'.join(f'{value:.0f}' for value in currents)}mA，"
                                f"反馈 {feedback_hz:.1f}Hz，正在记录稳定样本"
                            ),
                        )
                        append_process_log(
                            "center_tension_sample",
                            command_current_ma=command_current,
                            absolute_positions_deg=[round(float(item.position), 3) for item in values],
                            phase_current_ma=[round(abs(float(item.phase_current)), 1) for item in values],
                            solved_xyz=position_to_xyz(
                                [float(item.position) for item in values], calibration
                            ),
                        )
                    if level_error:
                        break
                    time.sleep(0.001)
                level = summarize_center_tension_level(
                    confirmations,
                    calibration,
                    command_current,
                    requested,
                )
                if level_error:
                    level["reason"] = level_error
                    level["passed"] = False
                level_results.append(level)
                with STATE_LOCK:
                    live_state = copy.deepcopy(state)
                    live_state.update(
                        {
                            "levels": copy.deepcopy(level_results),
                            "current_level_ma": command_current,
                            "reason": level.get("reason", ""),
                        }
                    )
                stable_count = int(level.get("stable_high_level_count", 0))
                set_state(
                    center_tension_calibration=live_state,
                    message=(
                        f"五点中心张力测试：{command_current}mA，"
                        f"实测电流差 {level.get('current_spread_ma', '—')}mA，"
                        f"跨档位漂移 {level.get('cross_level_drift_deg', '—')}°，"
                        f"连续稳定 {stable_count}/{CENTER_TENSION_MIN_STABLE_LEVELS}"
                    ),
                )
                append_process_log("center_tension_level", **level)
                if level_error:
                    break
                early_selected, _ = select_center_tension_level(level_results, requested)
                if early_selected is not None:
                    # Three consecutive stable increasing levels are enough to
                    # reject friction-only balance. Higher levels are a stress
                    # test, not part of the fifth calibration datum; stop here
                    # to shorten the real calibration cycle.
                    append_process_log(
                        "center_tension_sweep_early_complete",
                        stable_run_levels_ma=early_selected.get("stability_run_levels_ma", []),
                    )
                    break
            selected, selection_reason = select_center_tension_level(level_results, requested)
            if selected is None:
                reason = safety_stop_reason or (
                    selection_reason
                    or (level_results[-1].get("reason") if level_results else "没有完成有效档位")
                )
                raise RuntimeError("没有找到经过多档位确认的中心位置：" + str(reason))
            # Normal completion ramps the latched torque down before the
            # regular stop/disable recovery. Abort and fault paths remain
            # immediate for safety.
            if not STOP_EVENT.is_set():
                smooth_equal_torque_ramp(connection, previous_torque_current, 0)
        summary = {
            "status": "pass",
            "expected_xy_mm": [center_x, center_y],
            "requested_floor_ma": requested,
            "levels": level_results,
            "scan_levels_ma": list(sweep_levels),
            "recommended_current_ma": int(selected["command_current_ma"]),
            "stability_run_levels_ma": list(selected.get("stability_run_levels_ma", [])),
            "validation_floor_ma": int(selected.get("validation_floor_ma", requested)),
            "selected": copy.deepcopy(selected),
            "model_applied": False,
            "reason": "",
        }
        updated, apply_reason = apply_center_tension_datum(calibration, selected, summary)
        if updated is None:
            raise RuntimeError(apply_reason)
        persist_calibration(updated)
        with STATE_LOCK:
            STATE["calibration"] = updated
        summary["model_applied"] = True
        summary["reason"] = (
            f"连续递增档位 {summary.get('stability_run_levels_ma', [])} 的绝对位置稳定，"
            "其位置中值已并入五点绝对绳长曲线"
        )
        set_state(center_tension_calibration=summary)
        append_process_log(
            "center_tension_sweep_complete",
            recommended_current_ma=summary["recommended_current_ma"],
            selected=selected,
            levels=level_results,
            model_applied=True,
        )
        completed = True
    except Exception as exc:
        error = str(exc)
        append_process_log("center_tension_sweep_error", error=error, levels=level_results)
        current = calibration_data()
        failed = {
            "status": "error",
            "expected_xy_mm": [MECHANISM_CENTER_X_MM, MECHANISM_CENTER_Y_MM],
            "requested_floor_ma": requested_floor_ma,
            "validation_floor_ma": CENTER_TENSION_CONFIRM_START_MA,
            "min_stable_levels": CENTER_TENSION_MIN_STABLE_LEVELS,
            "max_cross_level_drift_deg": CENTER_TENSION_MAX_CROSS_LEVEL_DRIFT_DEG,
            "levels": level_results,
            "recommended_current_ma": selected.get("command_current_ma") if selected else None,
            "model_applied": False,
            "reason": error,
        }
        if current.get("valid"):
            current["center_tension_calibration"] = copy.deepcopy(failed)
            persist_calibration(current)
            with STATE_LOCK:
                STATE["calibration"] = current
        set_state(center_tension_calibration=failed, auto="error", message="五点中心张力测试失败：" + error)
    finally:
        stop_requested = STOP_EVENT.is_set()
        stream_stop_ok = True
        if timed_stream_active:
            try:
                with SERIAL_LOCK, direct.open_serial(current_port(), current_baud()) as stream_connection:
                    stream_stop_ok = stop_timed_feedback_stream(stream_connection)
            except Exception:
                stream_stop_ok = False
            timed_stream_active = False
        if not stream_stop_ok:
            error = error or "五点中心校准结束时 0x43 实时反馈流未能全部停止"
        recovery = disable_all_with_reconnect(
            current_port(), current_baud(), announce=bool(error or stop_requested), clear_timed_streams=not stream_stop_ok
        )
        if not recovery.get("ok"):
            set_state(
                auto="error",
                message="五点中心张力测试结束，但重连后仍无法确认四台失能；请立即切断动力或使用硬件急停（" + recovery.get("error", "未知错误") + ")",
            )
            completed = False
        elif error:
            set_state(auto="error", message="五点中心张力测试已安全停止，四台已重连并失能：" + error)
        elif stop_requested:
            set_state(auto="idle", message="五点中心张力测试已停止，四台已自动重连并失能")
            completed = False
        else:
            with STATE_LOCK:
                final_center = copy.deepcopy(STATE.get("center_tension_calibration", {}))
            set_state(
                auto="idle",
                message=(
                    f"五点中心张力测试通过：推荐稳定等电流档位 {final_center.get('recommended_current_ma')}mA；"
                    "第五中心数据已写入绝对绳长曲线，四台已自动重连并失能"
                ),
            )
        STOP_EVENT.clear()
    return bool(completed and not error and not stop_requested)


def grid_calibration_worker(
    target_current: int | None = None,
    rows: int | None = None,
    cols: int | None = None,
) -> bool:
    """Sample a boundary-inclusive serpentine grid and gate its live use.

    This worker records absolute encoder positions and phase-current readings
    at every node.  Phase current remains a diagnostic/safety signal: position
    mode exposes a current ceiling, not an independently commanded cable
    tension, so the sampler never chases a current band by changing rope length.
    """
    error: str | None = None
    stop_requested = False
    completed = False
    raw_samples: list[dict] = []
    grid_feedback_pending: list[tuple[str, dict[str, object]]] = []
    timed_stream_active = False

    def flush_grid_feedback_logs() -> None:
        nonlocal grid_feedback_pending
        if grid_feedback_pending:
            pending = grid_feedback_pending
            grid_feedback_pending = []
            append_process_logs(pending)

    try:
        calibration = calibration_data()
        if not calibration.get("valid"):
            raise RuntimeError("请先完成四角几何校准，再进行多点网格校准")
        try:
            normalized_rows, normalized_cols = normalized_grid_shape(
                rows if rows is not None else calibration.get("grid_rows", GRID_DEFAULT_ROWS),
                cols if cols is not None else calibration.get("grid_cols", GRID_DEFAULT_COLS),
            )
            requested_current = int(
                target_current
                if target_current is not None
                else calibration.get("grid_tension_target_current_ma", GRID_DEFAULT_TENSION_CURRENT_MA)
            )
        except (TypeError, ValueError):
            raise RuntimeError("网格行列或张力下限参数无效") from None
        if not GRID_TENSION_MIN_CURRENT_MA <= requested_current <= GRID_TENSION_MAX_CURRENT_MA:
            raise RuntimeError(
                f"网格张力下限必须在 {GRID_TENSION_MIN_CURRENT_MA}..{GRID_TENSION_MAX_CURRENT_MA}mA"
            )
        points = grid_sampling_points(normalized_rows, normalized_cols)
        try:
            proven_strong_current = int(
                calibration.get("strong_current", CALIBRATION_DEFAULT_STRONG_CURRENT)
            )
        except (TypeError, ValueError):
            proven_strong_current = CALIBRATION_DEFAULT_STRONG_CURRENT
        # The fifth centre point establishes the coarse *geometry* and the
        # 1500mA equal-torque operating point.  It must not become the travel
        # ceiling for a far corner: a corner can require more position-mode
        # headroom even though the final grid tension correction is small.
        # Keep the motion cap at the already-configured draw limit (normally
        # 2A), while the independent transient guard still remains active.
        base_limit = max(
            GRID_MOTION_MIN_CURRENT_MA,
            min(OPERATING_CURRENT_MAX_MA, trajectory_current_limit(calibration)),
        )
        current_limits = [base_limit for _ in MOTOR_IDS]
        # Invalidate any previous live map before touching the bus. A redo is
        # never allowed to keep using yesterday's compensation while its new
        # samples are incomplete.
        pending_calibration = copy.deepcopy(calibration)
        pending_calibration["grid_tension_target_current_ma"] = requested_current
        pending_calibration["grid_rows"] = normalized_rows
        pending_calibration["grid_cols"] = normalized_cols
        pending_calibration["grid_compensation"] = blank_grid_compensation(normalized_rows, normalized_cols)
        persist_calibration(pending_calibration)
        with STATE_LOCK:
            STATE["calibration"] = pending_calibration
        grid_state = {
            "status": "running",
            "row": 0,
            "col": 0,
            "point": 0,
            "points": len(points),
            "rows": normalized_rows,
            "cols": normalized_cols,
            "target_current_ma": requested_current,
            "current_ma": [None for _ in MOTOR_IDS],
            "current_limits_ma": list(current_limits),
            "quality": {},
        }
        set_state(grid_calibration=grid_state, auto="grid-calibration", message="多点网格校准准备中：将沿 110×148mm 边界蛇形采样")
        append_process_log(
            "grid_calibration_start",
            rows=normalized_rows,
            cols=normalized_cols,
            points=len(points),
            workspace=[WORKSPACE_WIDTH_MM, WORKSPACE_HEIGHT_MM],
            target_current_ma=requested_current,
            command_current_limit_ma=base_limit,
            proven_strong_current_ma=proven_strong_current,
            coordinate_frame="ball_center_workspace",
            model_family_key=calibration_model_context(calibration).get("model_family_key"),
            position_reference_deg=calibration_model_context(calibration).get("position_reference_deg"),
        )
        with SERIAL_LOCK, direct.open_serial(current_port(), current_baud()) as connection:
            firmware_results = [read_firmware_status(connection, address) for address in MOTOR_IDS]
            non_x = [
                f"M{result['id']}={result.get('firmware') or '无可靠回包'}"
                for result in firmware_results
                if result.get("firmware") != "X"
            ]
            if non_x:
                raise RuntimeError("网格校准启动失败：实际固件不是全 X（" + "、".join(non_x) + ")")
            initial_disable = disable_all(connection)
            if not all(item.get("accepted") for item in initial_disable):
                raise RuntimeError("网格校准启动前四台电机未能全部失能")
            for index, address in enumerate(MOTOR_IDS):
                ok, _, reply = enable_address(connection, address)
                if not ok:
                    detail = direct.hex_bytes(reply) if reply else "超时无回包"
                    raise RuntimeError(f"网格校准：M{index + 1} 使能失败，RX={detail}")
            initial_values = read_all_reliable(connection, attempts=2)
            safety = grid_safety_error(initial_values, current_limits)
            if safety:
                raise RuntimeError("网格校准启动检查：" + safety)
            current_positions = [float(item.position) for item in initial_values if item.position is not None]
            if len(current_positions) != len(MOTOR_IDS):
                raise RuntimeError("网格校准启动时四台绝对位置反馈不完整")
            feedback_interval_ms = motion_feedback_interval_ms(current_baud())
            stream_buffer = bytearray()
            stream_position_history: dict[int, float] = {}
            stream_assembler = RollingFourMotorFeedbackAssembler(
                GRID_ROLLING_FEEDBACK_WINDOW_SECONDS
            )
            start_timed_feedback_stream(
                connection,
                feedback_interval_ms,
                TIMED_FEEDBACK_INFO_CODE,
            )
            feedback_interval_ms = int(
                getattr(connection, "_y42_feedback_interval_ms", feedback_interval_ms)
            )
            timed_stream_active = True
            set_state(
                grid_calibration={
                    **grid_state,
                    "current_limits_ma": list(current_limits),
                    "feedback_hz_target": round(1000.0 / max(1, feedback_interval_ms), 1),
                    "feedback_hz_actual": 0.0,
                    "feedback_sample_count": 0,
                },
                message=(
                    f"多点网格校准：已开启四台合并实时反馈，目标 "
                    f"{1000.0 / max(1, feedback_interval_ms):.0f}Hz；开始平滑蛇形采样"
                ),
            )
            grid_feedback_times: list[float] = []
            grid_feedback_count = 0
            last_grid_feedback: dict = {}
            grid_feedback_ui_last_update = 0.0
            grid_parser_stats: dict[str, int] = {}

            def drain_grid_feedback() -> None:
                # The approach ramp can last several seconds. Keep consuming
                # the stream while it moves. These are live diagnostic frames,
                # not calibration nodes, so publish them at the same 100Hz
                # cadence instead of silently throwing them away. This keeps
                # the page/log useful during a long smooth approach and makes
                # the displayed rate describe the real stream rather than only
                # the three confirmation samples at a node.
                snapshots = read_timed_feedback_snapshots(
                    connection,
                    stream_buffer,
                    stream_assembler,
                    stream_position_history,
                    timeout=0.0,
                    parser_stats=grid_parser_stats,
                )
                for values, sampled_at in snapshots:
                    safety = grid_safety_error(values, current_limits)
                    if safety:
                        raise RuntimeError(safety)
                    publish_grid_feedback(
                        values,
                        max_target_error(values, nominal_positions) or 0.0,
                        current_limits,
                        sampled_at,
                    )

            for point in points:
                if STOP_EVENT.is_set():
                    raise RuntimeError("用户停止网格校准")
                x = float(point["x_mm"])
                y = float(point["y_mm"])
                nominal_positions = [motor_degrees(index, x, y, calibration) for index in range(len(MOTOR_IDS))]
                nominal_position_base = list(nominal_positions)
                force_balance = equilibrium_current_limits_at(
                    x,
                    y,
                    calibration,
                    fallback_current=base_limit,
                )
                hold_limits = normalized_trajectory_current_limits(
                    force_balance.get("current_limits_ma")
                    if isinstance(force_balance, dict)
                    else base_limit
                )
                # Position travel must not inherit the low force-balance
                # targets. A position-mode current field is a ceiling, not a
                # commanded physical tension; using 375..600mA here caused
                # the exact point-13 stall seen in the real log. Keep a
                # common, already-tested motion ceiling for the whole move.
                current_limits = [base_limit for _ in MOTOR_IDS]
                node_position_trim = [0.0 for _ in MOTOR_IDS]
                node_last_adjust_at = 0.0
                set_state(
                    grid_calibration={
                        **grid_state,
                        "row": point["row"] + 1,
                        "col": point["col"] + 1,
                        "point": point["index"] + 1,
                        "current_limits_ma": list(current_limits),
                        "hold_current_limits_ma": list(hold_limits),
                        "force_target_currents_ma": force_balance.get("target_currents_ma") if isinstance(force_balance, dict) else None,
                    },
                    message=f"网格校准 {point['index'] + 1}/{len(points)}：移动到 ({x:.1f}, {y:.1f})mm，采集四台位置/电流",
                )

                def publish_grid_feedback(
                    values: list[direct.Telemetry],
                    max_error_deg: float,
                    live_limits: list[int],
                    sampled_at: float | None = None,
                ) -> bool:
                    nonlocal grid_feedback_count, last_grid_feedback, node_last_adjust_at
                    if not telemetry_ready_for_calibration(values):
                        return False
                    grid_feedback_count += 1
                    now = float(sampled_at) if sampled_at is not None else time.perf_counter()
                    grid_feedback_times.append(now)
                    grid_feedback_times[:] = [
                        stamp for stamp in grid_feedback_times if now - stamp <= 1.0
                    ]
                    positions = [float(item.position) for item in values]
                    currents = [abs(float(item.phase_current)) for item in values]
                    parameters_changed = False
                    feedback_hz = (
                        (len(grid_feedback_times) - 1)
                        / max(grid_feedback_times[-1] - grid_feedback_times[0], 1e-6)
                        if len(grid_feedback_times) > 1
                        else 0.0
                    )
                    raw_feedback_frames = sum(
                        value for key, value in grid_parser_stats.items() if key.startswith("valid_")
                    )
                    invalid_feedback_frames = sum(
                        value for key, value in grid_parser_stats.items() if key.startswith("invalid_")
                    )
                    live = {
                        **grid_state,
                        "row": point["row"] + 1,
                        "col": point["col"] + 1,
                        "point": point["index"] + 1,
                        "current_ma": [round(value, 1) for value in currents],
                        "current_limits_ma": list(live_limits),
                        "tension_band_ma": [
                            max(GRID_TENSION_MIN_CURRENT_MA, requested_current - GRID_TENSION_BAND_MA),
                            min(GRID_TENSION_MAX_CURRENT_MA, requested_current + GRID_TENSION_BAND_MA),
                        ],
                        "position_trim_deg": list(node_position_trim),
                        "hold_current_limits_ma": list(hold_limits),
                        "force_target_currents_ma": force_balance.get("target_currents_ma") if isinstance(force_balance, dict) else None,
                        "target_positions_deg": [round(value, 2) for value in nominal_positions],
                        "feedback_position_deg": [round(value, 2) for value in positions],
                        "feedback_hz_actual": round(feedback_hz, 1),
                        "feedback_sample_count": grid_feedback_count,
                        "raw_feedback_frame_count": raw_feedback_frames,
                        "invalid_feedback_frame_count": invalid_feedback_frames,
                        "max_error_deg": round(float(max_error_deg), 2),
                    }
                    last_grid_feedback = copy.deepcopy(live)
                    nonlocal grid_feedback_ui_last_update
                    if now - grid_feedback_ui_last_update >= GRID_FEEDBACK_UI_INTERVAL_SECONDS:
                        grid_feedback_ui_last_update = now
                        set_state(
                            grid_calibration=live,
                            message=(
                                f"网格校准 {point['index'] + 1}/{len(points)}：实时反馈 "
                                f"{'/'.join(f'{value:.0f}' for value in currents)}mA，"
                                f"位置误差 {max_error_deg:.1f}°，反馈 {feedback_hz:.1f}Hz"
                            ),
                        )
                    grid_feedback_pending.append(
                        (
                            "grid_calibration_feedback",
                            {
                                "index": point["index"],
                                "target_xy": [x, y],
                                "absolute_positions_deg": [round(value, 3) for value in positions],
                                "phase_current_ma": [round(value, 1) for value in currents],
                                "current_limits_ma": list(live_limits),
                                "max_error_deg": round(float(max_error_deg), 3),
                                "feedback_hz_actual": round(feedback_hz, 1),
                            },
                        )
                    )
                    if len(grid_feedback_pending) >= 25:
                        flush_grid_feedback_logs()
                    return parameters_changed
                move_to_start_smooth(
                    connection,
                    current_positions,
                    nominal_positions,
                    f"网格点 {point['index'] + 1}",
                    current=current_limits,
                    rpm=GRID_START_RPM,
                    feedback_drain=drain_grid_feedback,
                )
                # Do not sample a point merely because the ramp finished. The
                # previous live run sampled M4 28° short of its target and then
                # drove the next point into protection. Every grid node must
                # first be confirmed in the absolute encoder frame.
                current_positions = wait_for_timed_absolute_target(
                    connection,
                    nominal_positions,
                    current_limits,
                    f"网格点 {point['index'] + 1} 到位确认",
                    stream_buffer,
                    stream_assembler,
                        stream_position_history,
                        timeout=GRID_TARGET_TIMEOUT_SECONDS,
                    rpm=GRID_START_RPM,
                    tolerance_deg=GRID_POSITION_TOLERANCE_DEG,
                    feedback_callback=publish_grid_feedback,
                        xy_target=(x, y),
                        command_interval=GRID_POSITION_COMMAND_INTERVAL,
                        parser_stats=grid_parser_stats,
                    )
                # Keep any bounded lagging-motor promotion for the short
                # confirmation window. Lowering a cap immediately after the
                # move makes a cable relax before its sample is recorded.
                # Force-balance values remain diagnostics until a full map
                # passes its quality gates.
                send_fast(
                    connection,
                    four_motor_position_frame(
                        nominal_positions,
                        [GRID_START_RPM] * len(MOTOR_IDS),
                        current_limits,
                    ),
                )
                confirmations: list[list[direct.Telemetry]] = []
                deadline = time.monotonic() + GRID_SAMPLE_SETTLE_SECONDS
                while len(confirmations) < GRID_SAMPLE_CONFIRM_COUNT:
                    if STOP_EVENT.is_set():
                        raise RuntimeError("用户停止网格校准")
                    snapshots = read_timed_feedback_snapshots(
                        connection,
                        stream_buffer,
                        stream_assembler,
                        stream_position_history,
                        timeout=min(TIMED_FEEDBACK_READ_WINDOW_SECONDS, max(0.001, deadline - time.monotonic())),
                        parser_stats=grid_parser_stats,
                    )
                    for values, sampled_at in snapshots:
                        safety = grid_safety_error(values, current_limits)
                        if safety:
                            raise RuntimeError(safety)
                        publish_grid_feedback(
                            values,
                            max_target_error(values, nominal_positions) or 0.0,
                            current_limits,
                            sampled_at,
                        )
                        confirmations.append(values)
                        if len(confirmations) >= GRID_SAMPLE_CONFIRM_COUNT:
                            break
                    if not snapshots:
                        time.sleep(0.001)
                positions = [
                    statistics.median(float(values[index].position) for values in confirmations)
                    for index in range(len(MOTOR_IDS))
                ]
                currents = [
                    statistics.median(abs(float(values[index].phase_current)) for values in confirmations)
                    for index in range(len(MOTOR_IDS))
                ]
                solved = position_to_xyz(positions, calibration)
                solved_xy = [float(solved[0]), float(solved[1])] if solved is not None else None
                solved_z = float(solved[2]) if solved is not None else None
                z_spread = float(solved[3]) if solved is not None else None
                xy_error = (
                    math.hypot(float(solved_xy[0]) - x, float(solved_xy[1]) - y)
                    if solved_xy is not None else None
                )
                raw_samples.append(
                    {
                        "index": point["index"],
                        "row": point["row"],
                        "col": point["col"],
                        "x_mm": x,
                        "y_mm": y,
                        "absolute_positions_deg": positions,
                        # Compensation is always relative to the untouched
                        # kinematic target.  Saving an adjusted target here
                        # would discard the very correction being calibrated.
                        "nominal_positions_deg": nominal_position_base,
                        "phase_current_ma": currents,
                        "relative_rope_lengths_mm": calibration_relative_rope_lengths(positions, calibration),
                        "solved_xy_mm": solved_xy,
                        "solved_z_mm": solved_z,
                        "z_fit_spread_mm": z_spread,
                        "xy_error_mm": xy_error,
                        "current_limits_ma": list(current_limits),
                    }
                )
                current_positions = positions
                append_process_log(
                    "grid_calibration_sample",
                    index=point["index"],
                    row=point["row"],
                    col=point["col"],
                    target_xy=[x, y],
                    absolute_positions_deg=positions,
                    relative_rope_lengths_mm=calibration_relative_rope_lengths(positions, calibration),
                    phase_current_ma=currents,
                    current_limits_ma=list(current_limits),
                    solved_xyz=[solved[0], solved[1], solved[2], solved[3]] if solved is not None else None,
                    xy_error_mm=xy_error,
                )
            solved_z_values = [float(item["solved_z_mm"]) for item in raw_samples if item.get("solved_z_mm") is not None]
            flush_grid_feedback_logs()
            plane_reference = statistics.median(solved_z_values) if solved_z_values else None
            for item in raw_samples:
                item["plane_reference_z_mm"] = plane_reference
                if item.get("solved_z_mm") is not None and plane_reference is not None:
                    item["height_error_mm"] = abs(float(item["solved_z_mm"]) - plane_reference)
                    item["fit_error_mm"] = max(
                        float(item.get("xy_error_mm") or 0.0),
                        float(item["height_error_mm"]),
                        float(item.get("z_fit_spread_mm") or 0.0),
                    )
            grid = build_grid_compensation(
                raw_samples,
                calibration,
                rows=normalized_rows,
                cols=normalized_cols,
                target_current_ma=requested_current,
                plane_reference_z_mm=plane_reference,
                reference_phase_current_ma=[float(requested_current) for _ in MOTOR_IDS],
                max_fit_error_mm=GRID_MAX_FIT_ERROR_MM,
            )
            schema_ok, schema_reason = validate_grid_compensation(grid)
            if not schema_ok:
                grid["valid"] = False
                grid["enabled"] = False
                grid["invalid_reason"] = schema_reason
            grid["enabled"] = bool(grid.get("valid") is True and schema_ok)
            updated_calibration = calibration_data()
            updated_calibration["grid_tension_target_current_ma"] = requested_current
            updated_calibration["grid_rows"] = normalized_rows
            updated_calibration["grid_cols"] = normalized_cols
            updated_calibration["grid_plane_reference_z_mm"] = plane_reference
            updated_calibration["grid_compensation"] = grid
            persist_calibration(updated_calibration)
            with STATE_LOCK:
                STATE["calibration"] = updated_calibration
            quality = {
                "valid": bool(grid.get("valid")),
                "valid_points": int(grid.get("valid_sample_count", 0)),
                "total_points": len(points),
                "min_current_ma": grid.get("min_phase_current_ma"),
                "max_height_error_mm": grid.get("max_height_error_observed_mm"),
                "max_xy_error_mm": grid.get("max_xy_error_observed_mm"),
                "target_current_ma": requested_current,
                "plane_reference_z_mm": plane_reference,
            }
            completed = bool(grid.get("valid") is True and grid.get("enabled") is True)
            append_process_log(
                "grid_calibration_complete" if completed else "grid_calibration_rejected",
                quality=quality,
                invalid_reason=grid.get("invalid_reason"),
                map_enabled=completed,
            )
            set_state(
                grid_calibration={**grid_state, "status": "pass" if completed else "fail", "quality": quality, "reason": grid.get("invalid_reason", "")},
                message=(
                    f"多点网格校准通过：{len(points)}点，最低相电流 {quality['min_current_ma']}mA，"
                    f"高度偏差≤{quality['max_height_error_mm']}mm，XY误差≤{quality['max_xy_error_mm']}mm；补偿已启用"
                    if completed
                    else "多点网格校准未通过：地图已保存但未启用；" + str(grid.get("invalid_reason", "请检查采样数据"))
                ),
            )
    except Exception as exc:
        error = str(exc)
        append_process_log("grid_calibration_error", error=error, samples=len(raw_samples))
        set_state(
            grid_calibration={
                "status": "error",
                "point": len(raw_samples),
                "points": len(raw_samples),
                "target_current_ma": (
                    int(target_current)
                    if isinstance(target_current, (int, float))
                    else GRID_DEFAULT_TENSION_CURRENT_MA
                ),
                "quality": {},
                "reason": error,
            },
            auto="error",
            message="多点网格校准失败：" + error,
        )
    finally:
        stop_requested = STOP_EVENT.is_set()
        stream_stop_ok = True
        if timed_stream_active:
            # The serial context is already closed on an exception. Reopen a
            # clean handle and stop the four unsolicited streams before any
            # ACK-based recovery; otherwise the first recovery ACK can be
            # interleaved with a stale 0x43 frame.
            try:
                with SERIAL_LOCK, direct.open_serial(current_port(), current_baud()) as stream_connection:
                    stream_stop_ok = stop_timed_feedback_stream(stream_connection)
            except Exception:
                stream_stop_ok = False
            timed_stream_active = False
        if not stream_stop_ok:
            error = error or "网格校准结束时 0x43 实时反馈流未能全部停止"
        recovery = disable_all_with_reconnect(
            current_port(),
            current_baud(),
            announce=bool(error or stop_requested),
            clear_timed_streams=not stream_stop_ok,
        )
        if not recovery.get("ok"):
            set_state(
                auto="error",
                message="网格校准结束，但自动重连后仍无法确认四台失能；请立即切断动力或使用硬件急停（" + recovery.get("error", "未知错误") + ")",
            )
            completed = False
        elif error:
            # Recovery itself is successful, but the worker failed before
            # completing the map.  Do not leave the UI on the transient
            # "reconnect 1/3" progress message; report the real cause while
            # making the safe disabled state explicit.
            set_state(
                auto="error",
                message="多点网格校准已安全停止，四台电机已重连并失能：" + error,
            )
        elif stop_requested:
            set_state(auto="idle", message="多点网格校准已停止，四台已自动重连并失能")
            completed = False
        else:
            # A completed sample set may still fail the quality gates.  It is
            # not an active worker anymore: return the UI to idle while
            # preserving the rejection reason and the final live feedback.
            with STATE_LOCK:
                final_grid = copy.deepcopy(STATE.get("grid_calibration", {}))
            if last_grid_feedback:
                final_grid.update(last_grid_feedback)
            final_grid["status"] = "pass" if completed else "fail"
            set_state(
                grid_calibration=final_grid,
                auto="idle",
                message=(
                    "多点网格校准通过，四台已自动重连并失能"
                    if completed
                    else "多点网格采样已完成但未通过质量门槛，地图未启用；四台已自动重连并失能"
                ),
            )
        STOP_EVENT.clear()
    return bool(completed and not error and not stop_requested)


def wait_trajectory_deadline(deadline: float) -> None:
    """Wait for one absolute 100 Hz QPC deadline without a Windows short sleep.

    ``time.monotonic()`` is backed by GetTickCount64 in the bundled Windows
    Python and advances only every 15.625 ms.  That silently quantised a 10 ms
    command period to about 64 Hz.  ``perf_counter()`` uses QPC here and is the
    only clock suitable for the motor deadline.
    """

    while True:
        remaining = float(deadline) - time.perf_counter()
        if remaining <= 0.0 or STOP_EVENT.is_set():
            return
        # Keep sleeping in short slices and leave a QPC tail so serial feedback
        # and the next all-motor frame land on the absolute deadline without
        # drift. This also avoids the 15.625 ms Windows scheduler quantum.
        if remaining > 0.016:
            time.sleep(0.010)


def trajectory_controller_mode(spec: dict) -> str:
    """Select one four-axis controller; exact path position wins by default.

    The force-position mode remains available for dedicated tension trials, but
    its self-stress position bias intentionally is not the default drawing
    controller because any bias is a geometric path change.
    """

    requested = str(spec.get("controller_mode", "four_position"))
    # The operator-facing open-loop drawing mode still uses the same four-axis
    # absolute-position frame; it only disables the motion-time feedback path.
    # Normalize it here so all downstream frame builders stay four-position.
    if requested == "four_position_open_loop":
        return "four_position"
    if requested not in {"four_position", "four_position_force"}:
        raise RuntimeError("当前生产方案只允许四电机位置或四电机力位控制，不再切换 3+1")
    return requested


def trajectory_worker(
    kind: str,
    spec: dict,
    keep_enabled: bool = False,
    balance_tension: bool = True,
    adaptive_slope: bool = False,
    tension_target_current: int = CALIBRATION_TEST_TENSION_TARGET_CURRENT,
) -> bool:
    completed = False
    error: str | None = None
    timer_resolution = False
    previous_gil_switch_interval = sys.getswitchinterval()
    previous_thread_priority: int | None = None
    timed_stream_active = False
    trajectory_feedback_reader: AsyncTimedFeedbackReader | None = None
    trajectory_frame_writer: TrajectoryFrameWriter | None = None
    tensioned_session = False
    controller_mode = "four_position"
    force_position_enabled = False
    session_hybrid = False
    passive_index: int | None = None
    active_indices: tuple[int, ...] = tuple(range(len(MOTOR_IDS)))
    stroke_passive_plan: dict[int, int] = {}
    passive_current = SESSION_HOLD_CURRENT_MIN_MA
    passive_current_command = passive_current
    session_hold_floor = SESSION_HOLD_CURRENT_MIN_MA
    trajectory_ignore_driver_protection = True
    try:
        controller_mode = trajectory_controller_mode(spec)
        force_position_enabled = controller_mode == "four_position_force"
        # The command, browser and serial-reader threads share one interpreter.
        # A 5 ms default GIL slice lets either JSON encoding or a feedback burst
        # consume half of a 10 ms motor period.  A 1 ms slice keeps the command
        # deadline responsive without changing any motor target.
        sys.setswitchinterval(0.001)
        previous_thread_priority = set_current_thread_priority(
            WINDOWS_THREAD_PRIORITY_HIGHEST
        )
        # Windows' default timer quantum rounds short sleeps to roughly
        # 15.6 ms.  That was the concrete reason the nominal fixed-rate path was
        # observed around 60 Hz and felt sticky near the end.  Keep a 1 ms
        # timer only while a trajectory worker owns the motion session.
        timer_resolution = set_high_resolution_timer(True)
        workspace_width, workspace_height = validate_trajectory_bounds(kind, spec)
        with STATE_LOCK:
            sequence_running = STATE.get("auto") in {"shape-sequence", "all-test-patterns"}
        if not sequence_running:
            set_state(auto="trajectory", repeat=bool(spec.get("repeat")), message=f"{kind_label(kind)}轨迹准备启动")
        with SERIAL_LOCK, direct.open_serial(current_port(), current_baud()) as connection:
            live_baud = current_baud()
            # The requested production clock is 100 Hz, but the installed
            # COM5/115200 bus cannot carry that clock and a complete four-axis
            # feedback stream at the same time. Keep the 100 Hz path enabled
            # for 512000+ bps, and use a measured 25 Hz closed-loop fallback on
            # the current bus so a real demonstration remains feedback-backed.
            # The 115200 bus must leave wire time for four staggered 0x43
            # feedback streams; 15 Hz is the measured stable closed-loop rate.
            open_loop = bool(
                spec.get("open_loop")
                or spec.get("feedback") is False
                or spec.get("feedback_during_motion") is False
                or str(spec.get("controller_mode", "")) == "four_position_open_loop"
            )
            smooth_profile = bool(spec.get("motion_profile") == ESP32_SMOOTH_PROFILE)
            command_hz = (
                ESP32_SMOOTH_COMMAND_HZ
                if smooth_profile and open_loop
                else TRAJECTORY_HZ
                if (open_loop or live_baud >= 512000)
                else 15.0
            )
            command_interval = 1.0 / command_hz
            # At high baud the trajectory keeps a read-only 0x43 observer.  The
            # four-motor command remains one aggregate 0xAA frame at 100 Hz;
            # feedback confirms what the drives really executed and never
            # blocks the next target.
            trajectory_feedback_info_code = TIMED_FEEDBACK_INFO_CODE
            trajectory_feedback_frame_bytes = TIMED_FEEDBACK_FRAME_BYTES
            # Feedback is a diagnostic overlay, not part of the command clock.
            # Operator trajectories opt out of the live 0x43 stream so the
            # half-duplex RS485 reader cannot steal time from the 100Hz 0xAA
            # command frames. Start/end safety windows still read all motors.
            timed_stream_supported = bool(
                (not open_loop)
                and bool(spec.get("feedback_during_motion", True))
                and live_baud >= TRAJECTORY_LIVE_FEEDBACK_MIN_BAUD
            )
            feedback_interval_ms = motion_feedback_interval_ms(live_baud)
            feedback_hz_target = 1000.0 / feedback_interval_ms
            # A complete timed 0x43 snapshot gates the next point for a custom
            # hand-drawn path. If the snapshot is incomplete, the same
            # absolute target is held; no old point is skipped or invented.
            target_gate_enabled = bool(
                (not open_loop)
                and timed_stream_supported
                and (kind == "custom" or bool(spec.get("exact_polyline")))
                and bool(spec.get("target_gate", True))
            )
            trajectory_feedback_buffer = bytearray()
            trajectory_feedback_positions: list[float | None] = [None for _ in MOTOR_IDS]
            trajectory_feedback_times = [0.0 for _ in MOTOR_IDS]
            trajectory_feedback_position_history: dict[int, float] = {}
            trajectory_feedback_coherence_window = timed_feedback_coherence_window(live_baud)
            if feedback_interval_ms >= 90:
                # At 115200 the 100/107/114/121 ms streams can arrive over more
                # than the nominal 60 ms wire window once a 100 Hz command
                # occupies the adapter. Widen only this rolling pairing window;
                # the assembler still requires one new record from every motor
                # before emitting, so adjacent cycles cannot be mixed.
                trajectory_feedback_coherence_window = max(
                    trajectory_feedback_coherence_window,
                    0.12,
                )
            # The four timer periods are phase-walked on the shared RS485 bus.
            # Use the rolling pairer here so a slightly faster motor cannot make
            # the strict duplicate-ID assembler discard an otherwise fresh set.
            trajectory_feedback_assembler = RollingFourMotorFeedbackAssembler(
                trajectory_feedback_coherence_window,
                emit_interval=max(0.010, feedback_interval_ms / 1000.0),
            )

            def begin_trajectory_feedback() -> None:
                nonlocal timed_stream_active, trajectory_feedback_assembler, feedback_interval_ms, feedback_hz_target
                nonlocal trajectory_feedback_reader
                if not timed_stream_supported:
                    return
                trajectory_feedback_buffer.clear()
                trajectory_feedback_assembler = RollingFourMotorFeedbackAssembler(
                    trajectory_feedback_coherence_window,
                    emit_interval=max(0.010, feedback_interval_ms / 1000.0),
                )
                for index in range(len(MOTOR_IDS)):
                    trajectory_feedback_positions[index] = None
                    trajectory_feedback_times[index] = 0.0
                start_timed_feedback_stream(
                    connection,
                    feedback_interval_ms,
                    trajectory_feedback_info_code,
                )
                feedback_interval_ms = int(getattr(connection, "_y42_feedback_interval_ms", feedback_interval_ms))
                feedback_hz_target = 1000.0 / max(1, feedback_interval_ms)
                timed_stream_active = True
                trajectory_feedback_reader = AsyncTimedFeedbackReader(connection)
                trajectory_feedback_reader.start()
                append_process_log(
                    "trajectory_feedback_stream_start",
                    shape=kind,
                    baud=live_baud,
                    interval_ms=feedback_interval_ms,
                    target_hz=feedback_hz_target,
                    info_code=f"0x{trajectory_feedback_info_code:02X}",
                    frame_bytes=trajectory_feedback_frame_bytes,
                    mode="0x11 定时 0x43 合并回传（独立接收线程，位置+相电流）",
                )

            def drain_trajectory_feedback() -> list[TimedFeedbackRecord]:
                if trajectory_feedback_reader is not None:
                    trajectory_feedback_reader.check()
                    return trajectory_feedback_reader.drain()
                return read_timed_position_records(
                    connection,
                    trajectory_feedback_buffer,
                    timeout=0.0,
                    position_history=trajectory_feedback_position_history,
                )

            def end_trajectory_feedback() -> list[TimedFeedbackRecord]:
                nonlocal timed_stream_active, trajectory_feedback_reader
                if not timed_stream_active:
                    return []
                pending: list[TimedFeedbackRecord] = []
                if trajectory_feedback_reader is not None:
                    pending = trajectory_feedback_reader.stop()
                    trajectory_feedback_reader = None
                if not stop_timed_feedback_stream(connection):
                    timed_stream_active = False
                    raise RuntimeError("绘制反馈流停止失败，已停止继续运动以避免串口帧冲突")
                timed_stream_active = False
                append_process_log("trajectory_feedback_stream_stop", shape=kind)
                return pending

            for address in MOTOR_IDS:
                ok, _, _ = enable_address(connection, address)
                if not ok:
                    raise RuntimeError(f"轨迹启动：电机 ID {address} 无法使能")
            initial_values = read_all_reliable(connection)
            if not telemetry_ready_for_calibration(initial_values):
                raise RuntimeError("轨迹启动：四台电机实时位置读取不完整")
            # The X drive's 0x08 flag can remain latched after the previous
            # STOP/DISABLE.  Keep it visible in telemetry, but do not turn a
            # quiet diagnostic bit into a new trajectory failure.
            error = safety_error(
                initial_values,
                current_limit=trajectory_runtime_current_for_spec(spec),
                ignore_driver_protection=trajectory_ignore_driver_protection,
            )
            if error:
                raise RuntimeError("轨迹启动：" + error)
            current_positions = [float(t.position) for t in initial_values]
            if any(t.position is None for t in initial_values) or len(current_positions) != len(MOTOR_IDS):
                raise RuntimeError("轨迹启动：四台电机当前位置不可用")
            calibration_snapshot = calibration_data()
            tensioned_session = is_same_tensioned_session(calibration_snapshot)
            # The physical platform has three planar pose DOF (x/y/yaw) plus
            # one redundant cable direction.  All four axes therefore stay in
            # absolute position mode; only that redundant self-stress scalar is
            # adjusted from current feedback.  A requested legacy 3+1 mode is
            # rejected by trajectory_controller_mode instead of being silently
            # re-enabled from a persisted browser payload.
            session_hybrid = False
            target_path_preview = sampled_trajectory_target_path(kind, spec)
            target_path_segments_preview = sampled_trajectory_target_segments(kind, spec)
            if session_hybrid:
                session_hold_floor = max(
                    SESSION_HOLD_CURRENT_MIN_MA,
                    min(
                        SESSION_HOLD_CURRENT_MAX_MA,
                        int(
                            calibration_snapshot.get(
                                "session_hold_current_ma",
                                calibration_snapshot.get("weak_current", CALIBRATION_DEFAULT_WEAK_CURRENT),
                            )
                        ),
                    ),
                )
                # Pick the passive cable for each physical pen stroke. A fixed
                # passive motor over a multi-stroke drawing made M3 fight the
                # geometry throughout an upper-right rectangle. Switch only in
                # the pen-up transfer, atomically rebasing the newly active
                # position axis to its measured encoder value.
                raw_draw_segments = spec.get("draw_segments")
                if kind == "custom" and isinstance(raw_draw_segments, list):
                    for stroke_index, raw_segment in enumerate(raw_draw_segments):
                        if not isinstance(raw_segment, list):
                            continue
                        stroke_path = [
                            (float(point[0]), float(point[1]))
                            for point in raw_segment
                            if isinstance(point, (list, tuple)) and len(point) >= 2
                        ]
                        passive_choice = select_session_passive_motor_for_path(
                            stroke_path,
                            calibration_snapshot,
                        )
                        if passive_choice.get("ok") is not True:
                            raise RuntimeError(
                                f"3+1 控制无法为第 {stroke_index + 1} 笔选出稳定的张力电机："
                                + str(passive_choice.get("reason", "几何条件不足"))
                            )
                        stroke_passive_plan[stroke_index] = int(
                            passive_choice["passive_index"]
                        )
                if not stroke_passive_plan:
                    selection_source = spec.get("selection_path", target_path_preview)
                    selection_path = [
                        (float(point[0]), float(point[1]))
                        for point in selection_source
                    ]
                    passive_choice = select_session_passive_motor_for_path(
                        selection_path,
                        calibration_snapshot,
                    )
                    if passive_choice.get("ok") is not True:
                        raise RuntimeError(
                            "3+1 控制无法为当前路径选出稳定的张力电机："
                            + str(passive_choice.get("reason", "几何条件不足"))
                        )
                    stroke_passive_plan[0] = int(passive_choice["passive_index"])
                passive_index = stroke_passive_plan[min(stroke_passive_plan)]
                active_indices = tuple(index for index in range(len(MOTOR_IDS)) if index != passive_index)
                passive_current = session_hold_floor
                passive_current_command = passive_current
                if adaptive_slope:
                    raise RuntimeError("同一上电会话的 3+1 控制不使用电流自改绳长系数")
            model_context = calibration_model_context(calibration_snapshot)
            grid_map = calibration_snapshot.get("grid_compensation")
            grid_map_enabled = False
            if isinstance(grid_map, dict) and grid_map.get("enabled") is True and grid_map.get("valid") is True:
                grid_map_enabled, _ = validate_grid_compensation(grid_map)
            grid_map_status = "网格位置/张力补偿已启用" if grid_map_enabled else "未启用网格补偿"
            trajectory_command_offsets = [0.0 for _ in MOTOR_IDS]
            try:
                force_position_target_floor = int(
                    calibration_snapshot.get(
                        "force_position_target_current_ma",
                        FORCE_POSITION_TARGET_FLOOR_MA,
                    )
                )
            except (TypeError, ValueError):
                force_position_target_floor = FORCE_POSITION_TARGET_FLOOR_MA
            force_position_target_floor = max(
                SESSION_HOLD_CURRENT_MIN_MA,
                min(900, force_position_target_floor),
            )
            force_position_contraction = (
                FORCE_POSITION_CONTRACTION_MIN_MM
                if force_position_enabled
                else 0.0
            )
            force_position_current_ema: list[float | None] = [None for _ in MOTOR_IDS]
            force_position_feedback_bias_deg = [0.0 for _ in MOTOR_IDS]
            force_position_last_feedback_at = 0.0
            force_position_last_update: dict = {
                "updated": False,
                "reason": (
                    "等待四电机相电流反馈"
                    if force_position_enabled
                    else "纯四位置模式：在线张力外环关闭"
                ),
            }

            def feedback_xy_estimate(
                positions: list[float] | tuple[float, ...],
                hint_xy: tuple[float, float],
            ) -> tuple[float, float] | None:
                local_positions = [
                    float(position)
                    - trajectory_command_offsets[index]
                    - force_position_feedback_bias_deg[index]
                    for index, position in enumerate(positions)
                ]
                if session_hybrid:
                    return active_motor_positions_to_xy(
                        local_positions,
                        active_indices,
                        calibration_snapshot,
                        initial_xy=hint_xy,
                    )
                # Production drawing commands yaw=0 on all four position axes.
                # Use the corresponding closed-form four-cable XY solve in the
                # hard 10 ms loop (about 0.05 ms on this PC).  The general
                # x/y/yaw nonlinear audit costs 4--6 ms *per call* and used to
                # run twice per tick, which directly collapsed a nominal 100 Hz
                # path to 37--65 Hz.  Full pose/closure checks remain in the
                # bounded start and finish windows, outside the command clock.
                solved = position_to_xyz(local_positions, calibration_snapshot)
                if solved is None:
                    return None
                left, bottom, _, _ = drawable_workspace(calibration_snapshot)
                return float(solved[0]) - left, float(solved[1]) - bottom

            start_x, start_y = sample_path(kind, 0.0, spec)
            targets = grid_motor_positions_at(start_x, start_y, calibration_snapshot)
            move_current = (
                max(
                    TRAJECTORY_TENSION_MIN_CURRENT,
                    min(TRAJECTORY_TENSION_MAX_CURRENT, CALIBRATION_TEST_CURRENT_LIMIT),
                )
                if adaptive_slope
                else trajectory_runtime_current_for_spec(spec)
            )
            append_process_log(
                "trajectory_open",
                shape=kind,
                workspace=[workspace_width, workspace_height],
                start_xy=[round(start_x, 2), round(start_y, 2)],
                current_positions=current_positions,
                initial_phase_current=[telemetry.phase_current for telemetry in initial_values],
                target_positions=targets,
                trajectory_current=move_current,
                position_mode="absolute_coordinate_zero",
                aggregate_command="0xAA/0xCB",
                requested_speed_mm_s=spec.get("requested_speed_mm_s"),
                effective_speed_mm_s=spec.get("speed_mm_s"),
                target_gate=bool(target_gate_enabled),
                target_gate_timeout_s=TRAJECTORY_TARGET_GATE_TIMEOUT_SECONDS if target_gate_enabled else None,
                raw_point_count=spec.get("raw_point_count"),
                filtered_point_count=spec.get("filtered_point_count"),
                refined_point_count=spec.get("refined_point_count"),
                command_path_point_count=spec.get("command_path_point_count"),
                model_family_key=model_context.get("model_family_key"),
                position_reference_deg=model_context.get("position_reference_deg"),
                position_reference=model_context.get("position_reference"),
                controller=("4-position-force" if force_position_enabled else "4-position"),
                active_motors=[MOTOR_IDS[index] for index in active_indices],
                passive_motor=MOTOR_IDS[passive_index] if passive_index is not None else None,
                passive_current_ma=passive_current_command if session_hybrid else None,
                passive_current_mode="encoder_xy_geometry_balance_slewed" if session_hybrid else None,
                stroke_passive_plan={
                    str(index + 1): MOTOR_IDS[value]
                    for index, value in stroke_passive_plan.items()
                }
                if session_hybrid
                else None,
            )
            if session_hybrid:
                assert passive_index is not None
                move_to_start_smooth_three_plus_one(
                    connection,
                    current_positions,
                    targets,
                    passive_index,
                    passive_current,
                    kind_label(kind),
                    position_current=move_current,
                )
            else:
                move_to_start_smooth(
                    connection,
                    current_positions,
                    targets,
                    kind_label(kind),
                    current=move_current,
                )
            set_state(
                trajectory_controller=("4-position-force" if force_position_enabled else "4-position"),
                trajectory_target_path=target_path_preview,
                trajectory_target_path_segments=target_path_segments_preview,
                trajectory_actual_path=[],
                trajectory_actual_feedback_path=[],
                trajectory_actual_path_segments=[],
                trajectory_actual_feedback_path_segments=[],
                trajectory_actual_path_gap_pending=False,
                trajectory_actual_feedback_path_gap_pending=False,
                message=(
                    f"正在柔和移动到{kind_label(kind)}起点（3位置+1动态张力，M{passive_index + 1} 从 {passive_current_command}mA 柔和接管）"
                    if session_hybrid and passive_index is not None
                    else f"正在移动到{kind_label(kind)}起点（四电机 0xAA 合帧）"
                ),
            )
            started = time.perf_counter()
            next_start_safety = started
            next_start_command = started + 0.15
            start_settled_since: float | None = None
            start_near_settled_since: float | None = None
            start_progress_positions = None
            start_progress_since = started
            start_feedback_failures = 0
            start_safety_failures = 0
            if adaptive_slope:
                # 200 mA is the measured tension target.  Send a 300 mA
                # command cap so the driver has headroom to settle around the
                # target instead of clipping every low-current cable at 200.
                current_base = move_current
            else:
                current_base = trajectory_runtime_current_for_spec(spec)
            current_limits = [current_base for _ in MOTOR_IDS]
            with STATE_LOCK:
                STATE["trajectory_current_limits"] = list(current_limits)
                STATE["trajectory_balance"] = {
                    "enabled": force_position_enabled,
                    "mode": "four_position_self_stress" if force_position_enabled else "pure_four_position",
                    "adaptive_slope": bool(adaptive_slope),
                    "target_current_ma": force_position_target_floor,
                    "protection_limit_ma": current_base,
                    "contraction_mm": force_position_contraction,
                    "adjustments": 0,
                    "last": (
                        grid_map_status + "；等待四台完整相电流反馈"
                        if force_position_enabled
                        else "纯位置轨迹：四台同步绝对位置，限流上限 1.5A（默认 1A）"
                    ),
                }
            while True:
                if STOP_EVENT.is_set():
                    raise RuntimeError("用户停止轨迹")
                now = time.perf_counter()
                if now >= next_start_command:
                    # Keep reasserting the exact endpoint while the driver
                    # settles; this is only a low-rate keep-alive, not a new
                    # jump to the next shape.
                    if session_hybrid:
                        assert passive_index is not None
                        send_fast(
                            connection,
                            three_position_one_torque_frame(
                                targets,
                                passive_index,
                                passive_current,
                                [TRAJECTORY_START_RPM] * len(MOTOR_IDS),
                                move_current,
                                torque_max_rpm=HYBRID_PATH_PASSIVE_MAX_RPM,
                            ),
                        )
                    else:
                        send_fast(
                            connection,
                            four_motor_position_frame(
                                targets,
                                [TRAJECTORY_START_RPM] * len(MOTOR_IDS),
                                move_current,
                            ),
                        )
                    next_start_command = now + 0.15
                # Endpoint settling needs fresh position/RPM/flags, not a slow
                # 28-query telemetry sweep. The full current/temperature safety
                # pass was completed immediately before this bounded move.
                if now >= next_start_safety:
                    values = read_trajectory_settle(connection, attempts=2, include_load=True)
                    if any(t.phase_current is None or t.temperature is None for t in values):
                        start_feedback_failures += 1
                        if start_feedback_failures >= 8:
                            raise RuntimeError("起点接管时电流/温度反馈连续缺失，已停止")
                        set_state(message=f"起点反馈暂时不完整，正在重试（{start_feedback_failures}/8）")
                        next_start_safety = now + 0.12
                        time.sleep(0.02)
                        continue
                    start_feedback_failures = 0
                    error = safety_error(
                        values,
                        current_limit=current_base,
                        ignore_driver_protection=trajectory_ignore_driver_protection,
                    )
                    if error:
                        # A busy half-duplex bus can expose one stale flag or a
                        # short current overshoot while the endpoint is being
                        # reasserted.  Retry a few fresh cycles before stopping;
                        # persistent faults still fail closed.
                        start_safety_failures += 1
                        if start_safety_failures >= 6:
                            raise RuntimeError(error)
                        set_state(message=f"起点反馈瞬时异常，正在重试（{start_safety_failures}/6）：{error}")
                        next_start_safety = now + 0.12
                        time.sleep(0.02)
                        continue
                    start_safety_failures = 0
                    if session_hybrid:
                        reached = selected_targets_reached(values, targets, active_indices)
                        xy_near, active_xy = active_target_xy_near_and_stopped(
                            values,
                            (start_x, start_y),
                            active_indices,
                            calibration_snapshot,
                            initial_xy=(start_x, start_y),
                        )
                        pose = None
                        pose_log = (
                            {
                                "x_mm": round(active_xy[0], 3),
                                "y_mm": round(active_xy[1], 3),
                                "controller": "3-position-1-torque",
                            }
                            if active_xy is not None
                            else None
                        )
                    else:
                        reached = draw_targets_reached(values, targets)
                        pose = motor_positions_to_planar_pose(
                            [float(t.position) for t in values]
                            if all(t.position is not None for t in values)
                            else [],
                            calibration_snapshot,
                        )
                        pose_log = {
                            key: round(float(pose[key]), 3)
                            for key in ("x_mm", "y_mm", "yaw_deg", "closure_rms_mm", "closure_max_mm")
                        } if pose is not None else None
                        xy_near = draw_target_xy_near_and_stopped(
                            values,
                            (start_x, start_y),
                            calibration_snapshot,
                        )
                    append_process_log(
                        "trajectory_start_sample",
                        shape=kind,
                        reached=reached,
                        planar_pose_ok=xy_near,
                        solved_planar_pose=pose_log,
                        positions=[t.position for t in values],
                        rpms=[t.rpm for t in values],
                        phase_current_ma=[t.phase_current for t in values],
                        temperatures_c=[t.temperature for t in values],
                    )
                    if reached and xy_near:
                        start_settled_since = start_settled_since or now
                        start_near_settled_since = None
                        if now - start_settled_since >= TRAJECTORY_START_SETTLE_SECONDS:
                            break
                        set_state(message=f"已到{kind_label(kind)}起点，等待 3+1 张力稳定" if session_hybrid else f"已到{kind_label(kind)}起点，等待四绳张力稳定")
                    elif xy_near:
                        start_settled_since = None
                        start_near_settled_since = start_near_settled_since or now
                        if now - start_near_settled_since >= TRAJECTORY_NEAR_SETTLE_SECONDS:
                            append_process_log(
                                "trajectory_start_xy_settle" if xy_near else "trajectory_start_soft_settle",
                                shape=kind,
                                tolerance_mm=TRAJECTORY_SESSION_XY_SETTLE_TOLERANCE
                                if session_hybrid and xy_near
                                else TRAJECTORY_XY_SETTLE_TOLERANCE
                                if xy_near
                                else TRAJECTORY_NEAR_POSITION_TOLERANCE,
                            )
                            set_state(message="起点已到位，正在开始轨迹")
                            break
                        set_state(message="起点已到位，正在平滑接管")
                    else:
                        start_settled_since = None
                        start_near_settled_since = None
                        # Do not keep reissuing an unreachable endpoint while all
                        # encoders have stopped. Small valid pose errors still use
                        # the bounded local hand-off above.
                        if all(t.position is not None and t.rpm is not None for t in values):
                            positions_now = [float(t.position) for t in values]
                            moving = any(abs(float(t.rpm)) > 1.0 for t in values)
                            progressed = start_progress_positions is None or any(
                                abs(a - b) > 0.5 for a, b in zip(positions_now, start_progress_positions)
                            )
                            if moving or progressed:
                                start_progress_positions = positions_now
                                start_progress_since = now
                            elif now - start_progress_since >= 2.0:
                                append_process_log(
                                    "trajectory_start_no_progress", shape=kind,
                                    targets=targets, positions=positions_now,
                                    solved_planar_pose=pose_log,
                                )
                                raise RuntimeError("起点位置与当前标定不一致，电机已停止前进；已结束等待，请检查绳索位置或重新校准")
                        else:
                            start_progress_positions = None
                            start_progress_since = now
                        if not session_hybrid and pose is not None and (
                            float(pose["closure_rms_mm"]) > TRAJECTORY_PLANAR_CLOSURE_RMS_TOLERANCE_MM
                            or float(pose["closure_max_mm"]) > TRAJECTORY_PLANAR_CLOSURE_MAX_TOLERANCE_MM
                        ):
                            set_state(
                                message=(
                                    f"正在核对起点四绳反馈"
                                    f"（闭合残差 {float(pose['closure_rms_mm']):.2f}mm）"
                                )
                            )
                        else:
                            set_state(message=f"正在移动到{kind_label(kind)}起点")
                    next_start_safety = now + 0.10
                if now - started > TRAJECTORY_START_TIMEOUT_SECONDS:
                    append_process_log("trajectory_start_timeout", shape=kind, targets=targets)
                    raise RuntimeError("移动到轨迹起点超时")
                time.sleep(0.01)
            # The smooth drums have no level-wind guide and the spherical tool
            # can retain a harmless in-plane rotation. Once absolute geometry
            # has brought the centre inside the strict Cartesian start gate,
            # rebase the commanded position axes to the measured start. This
            # prevents one axis from sitting at its current ceiling trying to
            # remove an uncommanded yaw/winding offset. The raw absolute sample
            # and its centre error remain recorded; persisted calibration is not
            # edited.
            start_anchor_error_mm: float | None = None
            start_xy_estimate = active_xy if session_hybrid else (
                (float(pose["x_mm"]), float(pose["y_mm"])) if pose is not None else None
            )
            if start_xy_estimate is None:
                raise RuntimeError("轨迹起点局部重基准缺少有效 XY 解")
            start_anchor_error_mm = math.hypot(
                start_xy_estimate[0] - start_x,
                start_xy_estimate[1] - start_y,
            )
            rebase_indices = active_indices if session_hybrid else tuple(range(len(MOTOR_IDS)))
            for index in rebase_indices:
                if values[index].position is None:
                    raise RuntimeError("轨迹起点局部重基准缺少位置反馈")
                trajectory_command_offsets[index] = float(values[index].position) - float(targets[index])
            append_process_log(
                "trajectory_start_local_rebase",
                shape=kind,
                controller=("4-position-force" if force_position_enabled else "4-position"),
                active_motors=[MOTOR_IDS[index] for index in rebase_indices],
                offsets_deg=[round(value, 3) for value in trajectory_command_offsets],
                absolute_start_xy=[round(start_xy_estimate[0], 3), round(start_xy_estimate[1], 3)],
                absolute_start_error_mm=round(start_anchor_error_mm, 3),
                observed_yaw_deg=round(float(pose["yaw_deg"]), 3) if pose is not None else None,
                feedback_frame="absolute_calibrated_model",
                command_frame="session_local_incremental",
            )
            set_state(
                trajectory_session_offset_deg=list(trajectory_command_offsets),
                trajectory_start_anchor_error_mm=round(start_anchor_error_mm, 3),
            )
            if spec.get("session_yaw_trial") is True:
                if not open_loop or session_hybrid or force_position_enabled or grid_map_enabled:
                    raise RuntimeError("会话几何试验只用于无网格的纯位置预计算")
                if pose is None or not uses_independent_linear_rope_model(calibration_snapshot):
                    raise RuntimeError("会话几何试验缺少线性标定和起点姿态记录")
                yaw = float(pose["yaw_deg"])
                if not math.isfinite(yaw) or abs(yaw) > 60.0 or float(pose["closure_max_mm"]) > 2.0:
                    raise RuntimeError("会话几何试验起点模型不满足有限范围条件")
                calibration_snapshot = copy.deepcopy(calibration_snapshot)
                calibration_snapshot["_trial_fixed_yaw_datum"] = {
                    "yaw_deg": yaw, "start_xy": [start_x, start_y],
                }
                append_process_log("session_yaw_geometry_trial", yaw_estimate_deg=yaw,
                                   start_xy=[start_x,start_y], optical_pose_verified=False,
                                   calibration_persisted=False)
            if open_loop:
                # USB write latency is independent of the motor command clock.
                # Queue the already-packed four-axis frames so a 4–7 ms driver
                # hiccup cannot turn one 10 ms target into a visible hold.
                trajectory_frame_writer = TrajectoryFrameWriter(connection)
                connection._y42_trajectory_writer = trajectory_frame_writer
            if open_loop:
                append_process_log(
                    "trajectory_open_loop_motion",
                    shape=kind,
                    baud=live_baud,
                    command_hz=command_hz,
                    feedback_stream=False,
                    target_gate=False,
                    mode="four_position_absolute_no_motion_feedback",
                )
                feedback_mode_text = "纯位置开环（运动中不读取反馈、不等待到位）"
            elif timed_stream_supported:
                begin_trajectory_feedback()
                feedback_mode_text = f"实时位置+相电流反馈已开启（0x43，{feedback_hz_target:.0f}Hz/台；异步确认不阻塞命令）"
            else:
                append_process_log(
                    "trajectory_feedback_stream_skipped",
                    shape=kind,
                    baud=live_baud,
                    required_baud=TRAJECTORY_LIVE_FEEDBACK_MIN_BAUD,
                    reason=(
                        "运动期间主动关闭反馈流，优先保证100Hz位置命令"
                        if not bool(spec.get("feedback_during_motion", True))
                        else "当前波特率低于实时四电机反馈所需下限"
                    ),
                )
                feedback_mode_text = (
                    "运动期间关闭回传以保证丝滑；起止安全窗口仍确认四台反馈"
                    if not bool(spec.get("feedback_during_motion", True))
                    else f"实时位置+相电流反馈未开启（当前 {live_baud}，需 ≥ {TRAJECTORY_LIVE_FEEDBACK_MIN_BAUD}）"
                )
            if adaptive_slope and not timed_stream_supported:
                raise RuntimeError(
                    f"三图形自适应校准需要四电机 0x43 实时反馈；当前波特率 {live_baud} 未达到 {TRAJECTORY_LIVE_FEEDBACK_MIN_BAUD}"
                )
            while True:
                with STATE_LOCK:
                    repeat = bool(STATE.get("repeat")) and bool(spec.get("repeat"))
                cycle = 1
                duration = max(0.028, float(spec["duration_ms"]) / 1000.0)
                compiled_plan = None
                if open_loop and not session_hybrid and not force_position_enabled and not adaptive_slope:
                    set_state(message="正在预计算整条轨迹：坐标、四电机速度和命令帧；尚未开始绘制")
                    compile_started = time.perf_counter()
                    compiled_plan = precompute_position_trajectory(kind, spec, calibration_snapshot, trajectory_command_offsets, current_limits, command_interval)
                    compile_ms = (time.perf_counter()-compile_started)*1000.0
                    set_state(trajectory_precomputed_frames=len(compiled_plan), trajectory_precompute_ms=round(compile_ms,3))
                    append_process_log("trajectory_precomputed", frames=len(compiled_plan), packet_bytes=sum(len(item[0]) for item in compiled_plan), elapsed_ms=round(compile_ms,3), current_limits_ma=list(current_limits), all_geometry_before_motion=True)
                # Use an absolute fixed-rate command clock. Each tick contains
                # exactly one 0xAA frame with M1..M4 together; never split a
                # trajectory tick into four address frames.
                tick = time.perf_counter()
                frame_index = 0
                sent_frames = 0
                next_safety = tick + TRAJECTORY_SAFETY_INTERVAL
                next_balance = tick + TRAJECTORY_BALANCE_INTERVAL
                last_rate_report = tick
                last_process_log = tick
                last_tick_skip_log = tick
                skipped_frames_total = 0
                deadline_missed_total = 0
                control_phase_samples: list[dict[str, float]] = []
                safety_motor = 0
                # Current is the feedback used by the bounded tension
                # balancer. Poll one motor every 250 ms so all four currents
                # are refreshed about once per second. Temperature/flags stay
                # on the slower spare safety cycle below.
                current_feedback_motor = 0
                next_current_feedback = tick + TRAJECTORY_CURRENT_FEEDBACK_INTERVAL
                next_adaptive_slope = tick + CALIBRATION_TEST_SLOPE_ADAPT_INTERVAL
                last_adaptive_persist = tick
                adaptive_current_ema: list[float | None] = [None for _ in MOTOR_IDS]
                adaptive_snapshot_currents: tuple[float | None, ...] | None = None
                safety_field = 1
                set_state(
                    trajectory_hz_target=command_hz,
                    trajectory_hz_actual=0.0,
                    trajectory_frame_bytes=58 if session_hybrid else 61,
                    trajectory_frames=0,
                    trajectory_target_path=sampled_trajectory_target_path(kind, spec),
                    trajectory_target_path_segments=sampled_trajectory_target_segments(kind, spec),
                    trajectory_actual_path=[],
                    trajectory_actual_feedback_path=[],
                    trajectory_actual_path_segments=[],
                    trajectory_actual_feedback_path_segments=[],
                    trajectory_actual_path_gap_pending=False,
                    trajectory_actual_feedback_path_gap_pending=False,
                    trajectory_fit_error_mm=None,
                    trajectory_feedback_hz_actual=0.0,
                    trajectory_feedback_batches=0,
                    trajectory_feedback_reads=0,
                    trajectory_feedback_span_ms=None,
                    trajectory_feedback_raw_hz_actual=0.0,
                    trajectory_feedback_raw_updates=0,
                    trajectory_encoder_lead_deg=[0.0 for _ in MOTOR_IDS],
                    trajectory_residual_correction_deg=[0.0 for _ in MOTOR_IDS],
                    trajectory_residual_correction_total_deg=0.0,
                    trajectory_residual_correction_mm=0.0,
                    trajectory_passive_plan={
                        str(index + 1): MOTOR_IDS[value]
                        for index, value in stroke_passive_plan.items()
                    }
                    if session_hybrid
                    else {},
                    trajectory_diagnostic={
                        "status": "纯位置开环发送中" if open_loop else "采集中",
                        "recommendation": (
                            "运动中不读取反馈；仅记录电脑发送的目标轨迹"
                            if open_loop
                            else "正在等待四电机原始位置反馈"
                        ),
                    },
                    trajectory_balance={
                        "enabled": force_position_enabled,
                        "mode": "four_position_self_stress" if force_position_enabled else "pure_four_position",
                        "adaptive_slope": bool(adaptive_slope),
                        "target_current_ma": force_position_target_floor,
                        "protection_limit_ma": current_base,
                        "contraction_mm": force_position_contraction,
                        "adjustments": 0,
                        "last": "四位置闭环已接管；等待相电流后仅沿自应力方向柔和预紧",
                    },
                    message=(
                        f"{kind_label(kind)}轨迹准备发送：3位置+1恒张力合帧，控制目标 {command_hz:.0f}Hz · {feedback_mode_text}"
                        if session_hybrid
                        else f"{kind_label(kind)}轨迹准备发送：{'四电机力位' if force_position_enabled else '四电机纯位置'}合帧，控制目标 {command_hz:.0f}Hz · {feedback_mode_text}"
                    ),
                )
                if TRAJECTORY_COMMAND_PRIORITY and not timed_stream_active:
                    append_process_log(
                        "trajectory_feedback_deferred",
                        shape=kind,
                        reason=f"{live_baud} 半双工串口优先保证 0xAA 控制时钟；位置/电流诊断放到起点和终点安全窗口",
                    )
                position_index = 0
                actual_positions: list[float | None] = [None for _ in MOTOR_IDS]
                actual_position_times: list[float] = [0.0 for _ in MOTOR_IDS]
                filtered_actual: tuple[float, float] | None = None
                feedback_first_stamp: float | None = None
                feedback_last_stamp: float | None = None
                feedback_reads = 0
                feedback_batches = 0
                feedback_hz = 0.0
                feedback_raw_first_stamp: float | None = None
                feedback_raw_last_stamp: float | None = None
                feedback_raw_updates = 0
                feedback_raw_hz = 0.0
                feedback_snapshot: tuple[float, ...] | None = None
                feedback_rpm_snapshot: tuple[float | None, ...] | None = None
                feedback_flags_snapshot: tuple[int | None, ...] | None = None
                feedback_snapshot_at = 0.0
                feedback_snapshot_span = 0.0
                feedback_snapshot_last_at = 0.0
                feedback_batch_log_at = 0.0
                encoder_lead_deg = [0.0 for _ in MOTOR_IDS]
                feedback_display_first_stamp: float | None = None
                feedback_display_last_stamp: float | None = None
                last_command_xy = (start_x, start_y)
                last_command_phase = 0.0
                trace_recording = bool(trajectory_motion_phase(kind, 0.0, spec)["drawing"])
                active_stroke_index = int(trajectory_motion_phase(kind, 0.0, spec)["stroke_index"])
                fit_error_mm: float | None = None
                fit_error_since: float | None = None
                gate_target_signature: tuple[float, ...] | None = None
                gate_baseline_updates = 0
                gate_wait_started: float | None = None
                gate_hold_logged_at = 0.0
                residual_correction_deg = [0.0 for _ in MOTOR_IDS]
                residual_correction_total_deg = 0.0
                residual_correction_mm = 0.0
                # A strict hand-drawn target must be held until fresh feedback
                # reaches it, but holding must still respect the 100 Hz command
                # clock.  Without this separate retry deadline, decrementing
                # ``frame_index`` makes the same target execute in a tight
                # loop (the 61-byte 0xAA frame then saturates a 115200 bus and
                # starves the very feedback needed to release the gate).
                target_hold_retry_deadline = 0.0
                if compiled_plan is not None:
                    # No IK, sampling, speed calculation or packet packing in
                    # this playback path. Only bounded handoff and UI progress.
                    last_preview_at = 0.0
                    for packet, xy, drawing, stroke, motion_kind in compiled_plan:
                        if STOP_EVENT.is_set():
                            raise RuntimeError("用户停止轨迹")
                        trajectory_frame_writer.submit(packet)
                        frame_index += 1
                        sent_frames += 1
                        last_command_xy = xy
                        last_command_phase = min(1.0, frame_index*command_interval/duration)
                        active_stroke_index = stroke
                        if drawing != trace_recording:
                            with STATE_LOCK:
                                STATE["trajectory_actual_path_gap_pending"] = True
                            trace_recording = drawing
                        if drawing:
                            append_trajectory_trace("trajectory_actual_path", xy)
                        preview_now = time.perf_counter()
                        if preview_now-last_preview_at >= 0.1:
                            set_state(point=min(spec["point_count"]-1,round(last_command_phase*(spec["point_count"]-1))), trajectory_frames=trajectory_frame_writer.sent_frames,
                                      trajectory_hz_actual=round(trajectory_frame_writer.actual_hz(),2),
                                      message=f"预计算轨迹播放 · 第 {stroke+1} 笔 · 100Hz四轴合帧 · 不在运动中解算")
                            last_preview_at=preview_now
                while frame_index * command_interval < duration:
                    if STOP_EVENT.is_set():
                        raise RuntimeError("用户停止轨迹")
                    if target_hold_retry_deadline > 0.0:
                        wait_trajectory_deadline(target_hold_retry_deadline)
                        target_hold_retry_deadline = 0.0
                    scheduled_elapsed = frame_index * command_interval
                    deadline = tick + scheduled_elapsed
                    # The bounded serial writer owns the open-loop clock.
                    # A second deadline/spin here starves that thread of the
                    # GIL and lets the queue run dry. Prepare ahead instead;
                    # bounded submit supplies backpressure without skipping XY.
                    if trajectory_frame_writer is None:
                        wait_trajectory_deadline(deadline)
                    frame_started_perf = time.perf_counter()
                    deadline_late_ms = max(
                        0.0,
                        (time.perf_counter() - deadline) * 1000.0,
                    )
                    now = time.perf_counter()
                    phase = scheduled_elapsed / duration
                    next_elapsed = min(duration, scheduled_elapsed + command_interval)
                    next_phase = next_elapsed / duration
                    x, y = sample_path(kind, phase, spec)
                    next_x, next_y = sample_path(kind, next_phase, spec)
                    motion_phase = trajectory_motion_phase(kind, next_phase, spec)
                    next_trace_recording = bool(motion_phase["drawing"])
                    active_stroke_index = int(motion_phase["stroke_index"])
                    motion_label = (
                        "绘制"
                        if motion_phase["kind"] == "draw"
                        else "笔画收尾"
                        if motion_phase["kind"] == "draw_hold"
                        else "快速换位"
                        if motion_phase["kind"] == "travel"
                        else "笔尖就位"
                    )
                    if next_trace_recording != trace_recording:
                        with STATE_LOCK:
                            STATE["trajectory_actual_path_gap_pending"] = True
                            STATE["trajectory_actual_feedback_path_gap_pending"] = True
                        if next_trace_recording:
                            filtered_actual = None
                            fit_error_mm = None
                        trace_recording = next_trace_recording
                    command_ready_perf = time.perf_counter()
                    if session_hybrid:
                        assert passive_index is not None
                        desired_passive_index = stroke_passive_plan.get(
                            active_stroke_index,
                            passive_index,
                        )
                        if desired_passive_index != passive_index:
                            feedback_age = time.perf_counter() - feedback_snapshot_at
                            feedback_fresh = bool(
                                feedback_snapshot is not None
                                and len(feedback_snapshot) == len(MOTOR_IDS)
                                and -0.05
                                <= feedback_age
                                <= TRACKING_POSITION_STALE_SECONDS
                            )
                            if feedback_fresh:
                                assert feedback_snapshot is not None
                                handoff_local_positions = [
                                    float(position)
                                    - trajectory_command_offsets[index]
                                    for index, position in enumerate(feedback_snapshot)
                                ]
                                handoff_xy = active_motor_positions_to_xy(
                                    handoff_local_positions,
                                    active_indices,
                                    calibration_snapshot,
                                    initial_xy=(x, y),
                                )
                                if handoff_xy is None:
                                    raise RuntimeError(
                                        f"第 {active_stroke_index} 笔收尾无法反算位置，"
                                        "为避免换轴突拉已停止"
                                    )
                                handoff_error_mm = math.hypot(
                                    handoff_xy[0] - x,
                                    handoff_xy[1] - y,
                                )
                                if handoff_error_mm > TRAJECTORY_SESSION_XY_SETTLE_TOLERANCE:
                                    raise RuntimeError(
                                        f"第 {active_stroke_index} 笔终点尚差 {handoff_error_mm:.1f}mm，"
                                        "未切换张力电机；为避免把跟随误差隐藏到换位中已停止"
                                    )
                                old_passive_index = passive_index
                                nominal_at_switch = grid_motor_positions_at(
                                    x,
                                    y,
                                    calibration_snapshot,
                                )
                                new_active_indices = tuple(
                                    index
                                    for index in range(len(MOTOR_IDS))
                                    if index != desired_passive_index
                                )
                                # A motor moving from torque to position mode
                                # must receive its present encoder value as its
                                # first absolute target. Rebase every new active
                                # axis at the same instant so the 0xAA switch is
                                # a zero-step hand-off rather than a tug.
                                for index in new_active_indices:
                                    trajectory_command_offsets[index] = (
                                        float(feedback_snapshot[index])
                                        - float(nominal_at_switch[index])
                                    )
                                passive_index = desired_passive_index
                                active_indices = new_active_indices
                                passive_current = session_hold_floor
                                passive_current_command = session_hold_floor
                                encoder_lead_deg = [0.0 for _ in MOTOR_IDS]
                                append_process_log(
                                    "trajectory_passive_switch",
                                    shape=kind,
                                    stroke=active_stroke_index + 1,
                                    at_xy=[round(x, 3), round(y, 3)],
                                    from_motor=MOTOR_IDS[old_passive_index],
                                    to_motor=MOTOR_IDS[passive_index],
                                    feedback_age_ms=round(feedback_age * 1000.0, 2),
                                    endpoint_error_mm=round(handoff_error_mm, 3),
                                    active_motors=[
                                        MOTOR_IDS[index] for index in active_indices
                                    ],
                                    offsets_deg=[
                                        round(value, 3)
                                        for value in trajectory_command_offsets
                                    ],
                                    handoff="atomic_zero_step_during_pen_up",
                                )
                                with STATE_LOCK:
                                    STATE["trajectory_passive_current_ma"] = (
                                        passive_current_command
                                    )
                                    STATE["trajectory_session_offset_deg"] = list(
                                        trajectory_command_offsets
                                    )
                            elif next_trace_recording:
                                raise RuntimeError(
                                    f"第 {active_stroke_index + 1} 笔开始前没有收到新鲜的四电机位置反馈，"
                                    "为避免换轴突拉已停止"
                                )
                    nominal_targets = tuple(
                        target + trajectory_command_offsets[index]
                        for index, target in enumerate(
                            grid_motor_positions_at(next_x, next_y, calibration_snapshot)
                        )
                    )
                    live_base = (
                        current_base
                        if adaptive_slope
                        else trajectory_runtime_current_for_spec(spec)
                    )
                    if live_base != current_base:
                        current_base = live_base
                        current_limits = [current_base for _ in MOTOR_IDS]
                        append_process_log("trajectory_current_changed", shape=kind, current_ma=current_base)
                    force_target_vector = [0.0 for _ in MOTOR_IDS]
                    if force_position_enabled:
                        force_current_plan = equilibrium_current_targets(
                            next_x,
                            next_y,
                            force_position_target_floor,
                            calibration_snapshot,
                        )
                        force_target_vector = force_current_plan.get("target_currents_ma")
                        if not isinstance(force_target_vector, list) or len(force_target_vector) != len(MOTOR_IDS):
                            force_target_vector = [float(force_position_target_floor) for _ in MOTOR_IDS]
                        if (
                            adaptive_snapshot_currents is not None
                            and feedback_snapshot_at > force_position_last_feedback_at
                            and time.perf_counter() - feedback_snapshot_at
                            <= FORCE_POSITION_FEEDBACK_STALE_SECONDS
                        ):
                            force_position_current_ema = update_force_position_current_ema(
                                force_position_current_ema,
                                adaptive_snapshot_currents,
                            )
                            force_dt = (
                                feedback_snapshot_at - force_position_last_feedback_at
                                if force_position_last_feedback_at > 0.0
                                else feedback_interval_ms / 1000.0
                            )
                            force_position_contraction, force_position_last_update = (
                                update_force_position_contraction(
                                    force_position_contraction,
                                    force_position_current_ema,
                                    force_target_vector,
                                    force_dt,
                                    current_base,
                                )
                            )
                            force_position_last_feedback_at = feedback_snapshot_at
                    force_profile = force_position_self_stress_bias(
                        next_x,
                        next_y,
                        force_position_contraction,
                        calibration_snapshot,
                    )
                    force_bias_deg = list(force_profile["position_bias_deg"])
                    force_position_feedback_bias_deg[:] = force_bias_deg
                    next_targets = tuple(
                        target + force_bias_deg[index]
                        for index, target in enumerate(nominal_targets)
                    )
                    # Convert the newest raw Cartesian residual into a small
                    # absolute motor correction. The requested point remains
                    # exactly (next_x,next_y); only this frame is compensated.
                    residual_report = {"ok": False}
                    feedback_age_for_correction = time.perf_counter() - feedback_snapshot_at
                    if (
                        timed_stream_active
                        and feedback_snapshot is not None
                        and -0.05 <= feedback_age_for_correction <= TRACKING_POSITION_STALE_SECONDS
                    ):
                        measured_xy = feedback_xy_estimate(feedback_snapshot, (next_x, next_y))
                        if measured_xy is not None:
                            residual_report = exact_xy_residual_motor_correction(
                                (next_x, next_y), measured_xy, calibration_snapshot,
                                total_used_deg=residual_correction_total_deg,
                            )
                            if residual_report.get("ok") is True:
                                residual_correction_deg = [
                                    float(value) for value in residual_report.get(
                                        "correction_deg", [0.0] * len(MOTOR_IDS)
                                    )
                                ]
                                residual_correction_total_deg += sum(
                                    abs(value) for value in residual_correction_deg
                                )
                                residual_correction_mm = float(
                                    residual_report.get("residual_mm", 0.0)
                                )
                    else:
                        residual_correction_deg = [0.0 for _ in MOTOR_IDS]
                        residual_correction_mm = 0.0
                    if target_gate_enabled and gate_target_signature != next_targets:
                        gate_target_signature = next_targets
                        gate_baseline_updates = feedback_raw_updates
                        gate_wait_started = now
                    command_targets = [
                        float(target) + residual_correction_deg[index]
                        for index, target in enumerate(next_targets)
                    ]
                    if TRAJECTORY_ENCODER_LEAD_ENABLED and force_position_enabled:
                        encoder_lead_deg = update_encoder_feedback_lead(
                            encoder_lead_deg,
                            next_targets,
                            feedback_snapshot,
                            feedback_snapshot_at if feedback_snapshot is not None else None,
                            time.perf_counter(),
                        )
                        command_targets = [
                            float(target) + residual_correction_deg[index] + lead
                            for index, (target, lead) in enumerate(zip(next_targets, encoder_lead_deg))
                        ]
                    force_target_currents = None
                    force_balance = None
                    force_local_caps = None
                    if grid_map_enabled:
                        force_balance = equilibrium_current_limits_at(
                            next_x,
                            next_y,
                            calibration_snapshot,
                            current_base,
                        )
                        force_target_currents = force_balance.get("target_currents_ma")
                        force_local_caps = force_balance.get("current_limits_ma")
                        # 0xCB's current field is a protection/actuation ceiling,
                        # not a requested cable tension.  Per-motor caps made the
                        # highly loaded axes saturate and visibly bow the path.
                        # Keep all four ceilings at the operator's 2 A limit;
                        # the bounded self-stress position bias above is the only
                        # live tension actuator.  Preserve the old map as a
                        # diagnostic prediction, never as a command cap.
                        if force_balance:
                            with STATE_LOCK:
                                balance = dict(STATE.get("trajectory_balance", {}))
                                balance["force_equilibrium"] = {
                                    "weights": [round(float(value), 5) for value in (force_balance.get("model") or {}).get("weights", [])],
                                    "target_currents_ma": force_target_currents,
                                    "resultant": [round(float(value), 6) for value in (force_balance.get("model") or {}).get("resultant", (0.0, 0.0))],
                                    "residual": round(float((force_balance.get("model") or {}).get("residual", 0.0)), 6),
                                }
                    if session_hybrid:
                        assert passive_index is not None
                        passive_targets, passive_balance = balanced_torque_current_targets(
                            next_x,
                            next_y,
                            session_hold_floor,
                            calibration_snapshot,
                            maximum_current_ma=min(
                                HYBRID_PASSIVE_TORQUE_MAX_CURRENT_MA,
                                max(session_hold_floor, current_base),
                            ),
                        )
                        nominal_now = grid_motor_positions_at(x, y, calibration_snapshot)
                        passive_delta_deg = float(next_targets[passive_index]) - float(
                            nominal_now[passive_index]
                            + trajectory_command_offsets[passive_index]
                        )
                        passive_slope = float(
                            effective_slopes(calibration_snapshot)[passive_index]
                        )
                        # target_delta * slope has the sign of rope-length
                        # change. Positive means payout, where extra pull only
                        # brakes the move. Negative means take-up, where a
                        # modest boost helps gather cable without fighting the
                        # three position axes.
                        taking_up = passive_delta_deg * passive_slope < -0.02
                        desired_passive_current = (
                            min(
                                int(passive_targets[passive_index]),
                                max(
                                    session_hold_floor,
                                    HYBRID_PATH_PASSIVE_TAKEUP_MAX_CURRENT_MA,
                                ),
                            )
                            if taking_up
                            else session_hold_floor
                        )
                        passive_current_command = slewed_current(
                            passive_current_command,
                            desired_passive_current,
                            PASSIVE_TENSION_SLEW_MA_PER_TICK,
                        )
                        with STATE_LOCK:
                            STATE["trajectory_passive_current_ma"] = passive_current_command
                            balance = dict(STATE.get("trajectory_balance", {}))
                            balance["passive_tension"] = {
                                "motor": MOTOR_IDS[passive_index],
                                "floor_ma": session_hold_floor,
                                "target_ma": desired_passive_current,
                                "command_ma": passive_current_command,
                                "mode": "takeup" if taking_up else "payout_or_hold",
                                "geometric_delta_deg": round(passive_delta_deg, 4),
                                "geometry_balance_ok": bool(passive_balance.get("ok")),
                            }
                            STATE["trajectory_balance"] = balance
                        send_fast(
                            connection,
                            hybrid_trajectory_frame(
                                x,
                                y,
                                next_x,
                                next_y,
                                max(0.001, next_elapsed - scheduled_elapsed),
                                passive_index,
                                passive_current_command,
                                current_limits,
                                calibration_snapshot,
                                target_overrides=command_targets,
                            ),
                        )
                    else:
                        send_fast(
                            connection,
                            trajectory_frame(
                                x,
                                y,
                                next_x,
                                next_y,
                                max(0.001, next_elapsed - scheduled_elapsed),
                                current_limits,
                                calibration_snapshot,
                                target_overrides=command_targets,
                                profile=spec.get("motion_profile"),
                            ),
                        )
                    command_sent_perf = time.perf_counter()
                    sent_frames += 1
                    frame_index += 1
                    last_command_xy = (next_x, next_y)
                    last_command_phase = next_phase
                    with STATE_LOCK:
                        STATE["trajectory_encoder_lead_deg"] = list(encoder_lead_deg)
                        STATE["trajectory_residual_correction_deg"] = list(residual_correction_deg)
                        STATE["trajectory_residual_correction_total_deg"] = round(residual_correction_total_deg, 4)
                        STATE["trajectory_residual_correction_mm"] = round(residual_correction_mm, 4)
                    now = time.perf_counter()
                    if timed_stream_active:
                        records = drain_trajectory_feedback()
                        feedback_reads += len(records)
                        for record in records:
                            address = record.address
                            position = record.position
                            sampled_at = record.sampled_at
                            if address not in MOTOR_IDS:
                                continue
                            index = MOTOR_IDS.index(address)
                            if (
                                record.phase_current is not None
                                and abs(float(record.phase_current))
                                > overcurrent_trip_limit(current_base)
                            ):
                                raise RuntimeError(
                                    f"力位控制实时相电流过大（M{index + 1}："
                                    f"{record.phase_current}mA，保护阈值 "
                                    f"{overcurrent_trip_limit(current_base)}mA）"
                                )
                            if record.temperature is not None and record.temperature >= HARD_TEMPERATURE:
                                raise RuntimeError(
                                    f"力位控制实时温度过高（M{index + 1}：{record.temperature}°C）"
                                )
                            if record.flags is not None and record.flags & 0x08:
                                append_process_log(
                                    "trajectory_driver_protection_flag",
                                    motor=MOTOR_IDS[index],
                                    phase_current_ma=record.phase_current,
                                    rpm=record.rpm,
                                    temperature_c=record.temperature,
                                    action="diagnostic_only",
                                )
                            actual_positions[index] = position
                            actual_position_times[index] = sampled_at
                            trajectory_feedback_positions[index] = position
                            trajectory_feedback_times[index] = sampled_at
                            with STATE_LOCK:
                                telemetry = STATE["telemetry"].setdefault(str(address), {"id": address})
                                telemetry["position"] = position
                                if record.phase_current is not None:
                                    telemetry["phase_current"] = record.phase_current
                                if record.voltage is not None:
                                    telemetry["voltage"] = record.voltage
                                if record.bus_current is not None:
                                    telemetry["bus_current"] = record.bus_current
                                if record.rpm is not None:
                                    telemetry["rpm"] = record.rpm
                                if record.temperature is not None:
                                    telemetry["temperature"] = record.temperature
                                if record.flags is not None:
                                    telemetry["flags"] = record.flags
                                    telemetry["flags_text"] = direct.decode_flags(record.flags)
                                telemetry["online"] = True
                        # A partial next cycle must not overwrite a complete
                        # cycle from the same serial drain. Retain all complete
                        # cycles; the command loop can still use the newest.
                        completed_snapshots = completed_feedback_cycles(
                            trajectory_feedback_assembler, records
                        )
                        for completed_snapshot in completed_snapshots:
                            sample_span = max(item.sampled_at for item in completed_snapshot) - min(item.sampled_at for item in completed_snapshot)
                            batch_at = max(item.sampled_at for item in completed_snapshot)
                            if (
                                all(item.position is not None for item in completed_snapshot)
                                and sample_span <= trajectory_feedback_coherence_window
                            ):
                                raw_feedback_snapshot = tuple(float(item.position) for item in completed_snapshot)
                                feedback_snapshot = time_aligned_feedback_positions(completed_snapshot)
                                feedback_rpm_snapshot = tuple(item.rpm for item in completed_snapshot)
                                feedback_flags_snapshot = tuple(item.flags for item in completed_snapshot)
                                adaptive_snapshot_currents = tuple(
                                    abs(float(item.phase_current))
                                    if item.phase_current is not None and math.isfinite(float(item.phase_current))
                                    else None
                                    for item in completed_snapshot
                                )
                                feedback_snapshot_at = batch_at
                                feedback_snapshot_span = sample_span
                                feedback_raw_updates += 1
                                feedback_raw_first_stamp = feedback_raw_first_stamp or batch_at
                                feedback_raw_last_stamp = batch_at
                                feedback_raw_hz = (
                                    (feedback_raw_updates - 1)
                                    / max(0.001, feedback_raw_last_stamp - feedback_raw_first_stamp)
                                    if feedback_raw_updates > 1
                                    and feedback_raw_first_stamp is not None
                                    and feedback_raw_last_stamp is not None
                                    else 0.0
                                )
                                if batch_at - feedback_batch_log_at >= RAW_FEEDBACK_LOG_INTERVAL_SECONDS:
                                    append_process_log(
                                        "trajectory_feedback_batch",
                                        shape=kind,
                                        positions_deg=[round(value, 3) for value in feedback_snapshot],
                                        raw_positions_deg=[round(value, 3) for value in raw_feedback_snapshot],
                                        relative_rope_lengths_mm=calibration_relative_rope_lengths(
                                            feedback_snapshot,
                                            calibration_snapshot,
                                        ),
                                        phase_current_ma=[
                                            round(float(item.phase_current), 3)
                                            if item.phase_current is not None
                                            else None
                                            for item in completed_snapshot
                                        ],
                                        rpm=[item.rpm for item in completed_snapshot],
                                        flags=[item.flags for item in completed_snapshot],
                                        sampled_at=round(batch_at, 6),
                                        sample_span_ms=round(sample_span * 1000.0, 3),
                                        model_family_key=model_context.get("model_family_key"),
                                    )
                                    feedback_batch_log_at = batch_at
                                raw_estimate = feedback_xy_estimate(feedback_snapshot, (next_x, next_y))
                                if raw_estimate is not None and trace_recording:
                                    append_trajectory_trace("trajectory_actual_feedback_path", raw_estimate)

                        # Rendering the same cached position on every command
                        # tick is not another measurement. Count only fresh
                        # complete encoder cycles, using their sample clock.
                        feedback_age = time.perf_counter() - feedback_snapshot_at
                        if (
                            completed_snapshots
                            and feedback_snapshot is not None
                            and -0.05 <= feedback_age <= TRACKING_POSITION_STALE_SECONDS
                        ):
                            estimate = feedback_xy_estimate(feedback_snapshot, (next_x, next_y))
                            if estimate is not None:
                                actual_x, actual_y = estimate
                                feedback_batches = feedback_raw_updates
                                feedback_first_stamp = feedback_raw_first_stamp
                                feedback_last_stamp = feedback_raw_last_stamp
                                feedback_hz = feedback_raw_hz
                                if trace_recording:
                                    fit_error_mm = math.hypot(actual_x - next_x, actual_y - next_y)
                                    filtered_actual = (actual_x, actual_y)
                                    append_trajectory_trace("trajectory_actual_path", filtered_actual)
                                with STATE_LOCK:
                                    if fit_error_mm is not None:
                                        STATE["trajectory_fit_error_mm"] = round(fit_error_mm, 2)
                                    STATE["trajectory_feedback_hz_actual"] = round(feedback_hz, 1)
                                    STATE["trajectory_feedback_batches"] = feedback_batches
                                    STATE["trajectory_feedback_reads"] = feedback_reads
                                    STATE["trajectory_feedback_span_ms"] = round(feedback_snapshot_span * 1000.0, 2)
                                    STATE["trajectory_feedback_raw_hz_actual"] = round(feedback_raw_hz, 1)
                                    STATE["trajectory_feedback_raw_updates"] = feedback_raw_updates
                    feedback_done_perf = time.perf_counter()
                    target_held = False
                    if target_gate_enabled:
                        # A complete four-motor feedback cycle is deliberately
                        # slower than the 100 Hz command clock on the 115200
                        # baud bus.  Requiring a *new* aggregate cycle for each
                        # fine polyline point therefore creates a false timeout:
                        # the cached cycle is still fresh and already proves the
                        # mechanism is at the target, but the command loop keeps
                        # waiting for another cycle that the wire cannot deliver
                        # at 100 Hz.  Gate on the latest complete cycle instead;
                        # the first point still requires at least one cycle and a
                        # cycle older than the stale threshold is never accepted.
                        feedback_age = (
                            time.perf_counter() - feedback_snapshot_at
                            if feedback_snapshot_at > 0.0
                            else float("inf")
                        )
                        if (
                            feedback_snapshot is None
                            or feedback_raw_updates <= 0
                            or feedback_age > TRACKING_POSITION_STALE_SECONDS
                        ):
                            target_held = True
                        else:
                            gate_xy = feedback_xy_estimate(
                                feedback_snapshot, (next_x, next_y)
                            )
                            target_held = not trajectory_feedback_target_reached_xy(
                                feedback_snapshot,
                                feedback_rpm_snapshot,
                                feedback_flags_snapshot,
                                list(command_targets),
                                gate_xy,
                                (next_x, next_y),
                                allow_cartesian_fallback=(live_baud < 512000),
                            )
                        if target_held:
                            gate_wait_started = gate_wait_started or now
                            if now - gate_wait_started > TRAJECTORY_TARGET_GATE_TIMEOUT_SECONDS:
                                raise RuntimeError(
                                    f"手绘轨迹当前目标未到位（等待超过 {TRAJECTORY_TARGET_GATE_TIMEOUT_SECONDS:.2f}s），已停止，不前往下一个目标"
                                )
                            frame_index -= 1
                            if now - gate_hold_logged_at >= 0.20:
                                append_process_log(
                                    "trajectory_target_hold",
                                    shape=kind,
                                    target_xy=[round(next_x, 2), round(next_y, 2)],
                                    target_positions=list(command_targets),
                                    residual_correction_deg=[round(value, 4) for value in residual_correction_deg],
                                    residual_correction_mm=round(residual_correction_mm, 3),
                                    feedback_age_s=round(feedback_age, 3),
                                    feedback_updates=feedback_raw_updates,
                                    waited_s=round(now - gate_wait_started, 3),
                                )
                                gate_hold_logged_at = now
                            # Keep the original point pending, but do not
                            # resend it faster than the commanded 100 Hz.  This
                            # leaves wire time for the four 0x43 streams and
                            # makes the subsequent acceptance decision based
                            # on a real, fresh batch instead of a self-induced
                            # serial-bus starvation loop.
                            target_hold_retry_deadline = (
                                time.perf_counter() + command_interval
                            )
                        else:
                            gate_wait_started = None
                            gate_hold_logged_at = 0.0
                    if adaptive_slope and now >= next_adaptive_slope and adaptive_snapshot_currents is not None:
                        valid_currents = [
                            value for value in adaptive_snapshot_currents
                            if value is not None and math.isfinite(float(value))
                        ]
                        if len(valid_currents) == len(MOTOR_IDS):
                            # The EMA is only for deciding whether a rope is
                            # persistently loose/tight.  The command/feedback
                            # path remains on its fixed-rate clock and the current
                            # values written to the log remain raw absolute
                            # readings.
                            for index, value in enumerate(adaptive_snapshot_currents):
                                assert value is not None
                                previous_value = adaptive_current_ema[index]
                                adaptive_current_ema[index] = (
                                    float(value)
                                    if previous_value is None
                                    else previous_value * 0.75 + float(value) * 0.25
                                )
                            _, slope_changes = adapt_calibration_slope_from_currents(
                                adaptive_current_ema,
                                tension_target_current,
                            )
                            if slope_changes and now - last_adaptive_persist >= CALIBRATION_TEST_SLOPE_PERSIST_INTERVAL:
                                persist_calibration(calibration_data())
                                last_adaptive_persist = now
                            with STATE_LOCK:
                                balance = dict(STATE.get("trajectory_balance", {}))
                                balance["current_values_ma"] = [
                                    round(float(value), 1) if value is not None else None
                                    for value in adaptive_current_ema
                                ]
                                values = [float(value) for value in adaptive_current_ema if value is not None]
                                if len(values) == len(MOTOR_IDS):
                                    balance["current_spread_ma"] = round(max(values) - min(values), 1)
                                STATE["trajectory_balance"] = balance
                        next_adaptive_slope += CALIBRATION_TEST_SLOPE_ADAPT_INTERVAL
                        while next_adaptive_slope <= now:
                            next_adaptive_slope += CALIBRATION_TEST_SLOPE_ADAPT_INTERVAL
                    if not TRAJECTORY_COMMAND_PRIORITY and now >= next_current_feedback:
                        ok, reason = query_safety_field(
                            connection,
                            current_feedback_motor,
                            0,
                            current_limit=current_base,
                        )
                        if not ok:
                            raise RuntimeError(reason)
                        current_feedback_motor = (current_feedback_motor + 1) % len(MOTOR_IDS)
                        next_current_feedback += TRAJECTORY_CURRENT_FEEDBACK_INTERVAL
                        while next_current_feedback <= now:
                            next_current_feedback += TRAJECTORY_CURRENT_FEEDBACK_INTERVAL
                    if balance_tension and not TRAJECTORY_COMMAND_PRIORITY and now >= next_balance:
                        # 0xCB carries a current ceiling, not a requested cable
                        # tension. Keep that ceiling fixed; reducing it from
                        # phase-current feedback makes loaded motors saturate
                        # and lag their position targets.
                        if not grid_map_enabled:
                            current_limits = [current_base for _ in MOTOR_IDS]
                        with STATE_LOCK:
                            STATE["trajectory_current_limits"] = list(current_limits)
                        next_balance += TRAJECTORY_BALANCE_INTERVAL
                        while next_balance <= now:
                            next_balance += TRAJECTORY_BALANCE_INTERVAL
                    if not timed_stream_active and not TRAJECTORY_COMMAND_PRIORITY and frame_index % TRAJECTORY_POSITION_SAMPLE_EVERY_FRAMES == 0:
                        ok, position, reason = query_position_field(connection, position_index)
                        if not ok or position is None:
                            raise RuntimeError(reason)
                        actual_positions[position_index] = position
                        actual_position_times[position_index] = time.perf_counter()
                        position_index = (position_index + 1) % len(MOTOR_IDS)
                        if position_index == 0 and all(value is not None for value in actual_positions):
                            sample_span = max(actual_position_times) - min(actual_position_times)
                            # The four position queries are intentionally
                            # interleaved with the 100 Hz command stream. A
                            # full set may therefore describe different
                            # instants; keep it as diagnostic data, but never
                            # stop a valid trajectory because stale feedback
                            # appears far behind the current target.
                            estimate = (
                                feedback_xy_estimate(
                                    [float(value) for value in actual_positions],
                                    (x, y),
                                )
                                if sample_span <= 1.25
                                else None
                            )
                            if estimate is not None and trace_recording:
                                actual_x, actual_y = estimate
                                append_trajectory_trace("trajectory_actual_feedback_path", (actual_x, actual_y))
                                fit_error_mm = math.hypot(actual_x - x, actual_y - y)
                                with STATE_LOCK:
                                    STATE["trajectory_fit_error_mm"] = round(fit_error_mm, 2)
                                # The measured overlay is raw; do not smooth or
                                # interpolate it for acceptance/review.
                                filtered_actual = (actual_x, actual_y)
                                append_trajectory_trace("trajectory_actual_path", (actual_x, actual_y))
                    # Poll one safety field after sending the control frame;
                    # this avoids putting a query in front of a scheduled
                    # 0xAA tick and records any adapter-induced delay.
                    if not TRAJECTORY_COMMAND_PRIORITY and now >= next_safety:
                        ok, reason = query_safety_field(
                            connection,
                            safety_motor,
                            safety_field,
                            current_limit=current_base,
                        )
                        if not ok:
                            raise RuntimeError(reason)
                        if safety_field == 2:
                            safety_field = 1
                            safety_motor = (safety_motor + 1) % 4
                        else:
                            safety_field = 2
                        next_safety += TRAJECTORY_SAFETY_INTERVAL
                        while next_safety <= now:
                            next_safety += TRAJECTORY_SAFETY_INTERVAL
                    # A blocking diagnostic query can make the deadline fall
                    # behind. This check must run *after* all serial queries;
                    # placing it before them lets the next loop replay an old
                    # tick immediately, which creates a visible target jump.
                    now = time.perf_counter()
                    schedule_checked_perf = time.perf_counter()
                    next_frame_index = int(max(0.0, (now - tick)) / command_interval) + 1
                    if trajectory_frame_writer is None and not target_held and next_frame_index > frame_index:
                        missed = next_frame_index - frame_index
                        # Every trajectory is a literal sampled path. A late
                        # serial transaction must never advance frame_index
                        # into the future: doing that changes all four rope
                        # targets at once and can unload the payout side.
                        # Keep the pending point, extend wall-clock duration,
                        # and record the miss for timing diagnostics. This
                        # applies equally to generated and hand-drawn paths.
                        skipped_frames_total += missed
                        deadline_missed_total += missed
                        # Keep the timing path cheap: append_process_log opens
                        # the JSONL file, so aggregate deadline misses and
                        # emit at most twice per second.
                        if now - last_tick_skip_log >= 0.50:
                            append_process_logs_async([
                                (
                                "trajectory_deadline_missed",
                                {
                                    "shape": kind,
                                    "pending_frame": frame_index,
                                    "points_delayed": skipped_frames_total,
                                    "total_points_delayed": deadline_missed_total,
                                    "action": "retain_pending_point_extend_duration",
                                },
                            )])
                            skipped_frames_total = 0
                            last_tick_skip_log = now
                    runtime = max(0.001, now - tick)
                    actual_hz = sent_frames / runtime
                    if trajectory_frame_writer is not None:
                        wire_hz = trajectory_frame_writer.actual_hz()
                        if wire_hz > 0.0:
                            actual_hz = wire_hz
                    if now - last_process_log >= TRAJECTORY_LOG_INTERVAL:
                        with STATE_LOCK:
                            live_telemetry = copy.deepcopy(STATE.get("telemetry", {}))
                            balance_state = dict(STATE.get("trajectory_balance", {}))
                            balance_state.update(
                                {
                                    "enabled": force_position_enabled,
                                    "mode": "four_position_self_stress" if force_position_enabled else "pure_four_position",
                                    "target_current_ma": force_position_target_floor,
                                    "target_currents_ma": [round(float(value), 1) for value in force_target_vector],
                                    "current_values_ma": [
                                        round(float(value), 1) if value is not None else None
                                        for value in force_position_current_ema
                                    ],
                                    "contraction_mm": round(force_position_contraction, 4),
                                    "position_bias_deg": [round(float(value), 3) for value in force_bias_deg],
                                    "protection_limit_ma": current_base,
                                    "last": str(force_position_last_update.get("reason", "张力外环运行中")),
                                }
                            )
                            STATE["trajectory_balance"] = balance_state
                        append_process_logs_async([
                            (
                                "trajectory_sample",
                                {
                                    "shape": kind,
                                    "frame": sent_frames,
                                    "target_xy": [round(x, 2), round(y, 2)],
                                    "nominal_target_positions": [round(float(value), 3) for value in nominal_targets],
                                    "force_position_targets": [round(float(value), 3) for value in next_targets],
                                    "commanded_target_positions": [round(float(value), 3) for value in command_targets],
                                    "residual_correction_deg": [round(float(value), 4) for value in residual_correction_deg],
                                    "residual_correction_total_deg": round(residual_correction_total_deg, 4),
                                    "residual_correction_mm": round(residual_correction_mm, 4),
                                    "encoder_lead_deg": [round(float(value), 3) for value in encoder_lead_deg],
                                    "force_position_contraction_mm": round(force_position_contraction, 5),
                                    "force_position_bias_deg": [round(float(value), 4) for value in force_bias_deg],
                                    "force_position_target_currents_ma": [round(float(value), 1) for value in force_target_vector],
                                    "force_position_current_ema_ma": [
                                        round(float(value), 1) if value is not None else None
                                        for value in force_position_current_ema
                                    ],
                                    "force_position_update": force_position_last_update,
                                    "actual_positions": actual_positions,
                                    "phase_current": [live_telemetry.get(str(address), {}).get("phase_current") for address in MOTOR_IDS],
                                    "current_limits": list(current_limits),
                                    "passive_motor": MOTOR_IDS[passive_index] if passive_index is not None else None,
                                    "passive_current_command_ma": passive_current_command if session_hybrid else None,
                                    "rpm": [live_telemetry.get(str(address), {}).get("rpm") for address in MOTOR_IDS],
                                    "hz": round(actual_hz, 2),
                                },
                            ),
                        ])
                        last_process_log = now
                    if now - last_rate_report >= 0.2 or frame_index == 1:
                        fit_text = ""
                        if fit_error_mm is not None:
                            fit_text = f" · 实际偏差 {fit_error_mm:.1f}mm"
                        feedback_text = (
                            f" · 同步反算显示 {feedback_hz:.1f}Hz/{feedback_batches}组（原始四电机更新 {feedback_raw_hz:.1f}Hz/{feedback_raw_updates}组）"
                            if timed_stream_active
                            else ""
                        )
                        set_state(
                            point=int(round(phase * (spec["point_count"] - 1))),
                            points=spec["point_count"],
                            trajectory_hz_actual=round(actual_hz, 1),
                            trajectory_frames=sent_frames,
                            message=(
                                f"{kind_label(kind)}第 {active_stroke_index + 1} 笔{motion_label} · 3+1 合帧目标 {command_hz:.0f}Hz（实测发送 {actual_hz:.1f}Hz）· ({x:.1f}, {y:.1f})mm{fit_text} · {feedback_mode_text}{feedback_text}"
                                if session_hybrid
                                else f"{kind_label(kind)}第 {active_stroke_index + 1} 笔{motion_label} · {'四电机力位' if force_position_enabled else '四电机纯位置'}控制 {command_hz:.0f}Hz（实测 {actual_hz:.1f}Hz）" + (f" · 预紧 {force_position_contraction:.2f}mm" if force_position_enabled else "") + f" · ({x:.1f}, {y:.1f})mm{fit_text} · {feedback_mode_text}{feedback_text}"
                            ),
                        )
                        last_rate_report = now
                    loop_done_perf = time.perf_counter()
                    control_phase_samples.append(
                        {
                            "deadline_late_ms": deadline_late_ms,
                            "pre_send_ms": (command_ready_perf - frame_started_perf) * 1000.0,
                            "send_ms": (command_sent_perf - command_ready_perf) * 1000.0,
                            "feedback_ms": (feedback_done_perf - command_sent_perf) * 1000.0,
                            "housekeeping_ms": (loop_done_perf - feedback_done_perf) * 1000.0,
                            "loop_work_ms": (loop_done_perf - frame_started_perf) * 1000.0,
                            "schedule_check_ms": (schedule_checked_perf - frame_started_perf) * 1000.0,
                        }
                    )
                end_x, end_y = sample_path(kind, 1.0, spec)
                previous_x, previous_y = last_command_xy
                if last_command_phase < 1.0 - 0.000001:
                    # The scheduled loop normally reaches phase 1.0 itself.
                    # If the final sample was delayed, send only the remaining
                    # partial segment; never replay the previous segment,
                    # which caused a visible hitch at the end of some paths.
                    remaining = max(0.001, (1.0 - last_command_phase) * duration)
                    final_partial_force_bias = force_position_self_stress_bias(
                        end_x,
                        end_y,
                        force_position_contraction,
                        calibration_snapshot,
                    )["position_bias_deg"]
                    final_partial_targets = [
                        target
                        + trajectory_command_offsets[index]
                        + float(final_partial_force_bias[index])
                        for index, target in enumerate(
                            grid_motor_positions_at(end_x, end_y, calibration_snapshot)
                        )
                    ]
                    if session_hybrid:
                        assert passive_index is not None
                        send_fast(
                            connection,
                            hybrid_trajectory_frame(
                                previous_x,
                                previous_y,
                                end_x,
                                end_y,
                                remaining,
                                passive_index,
                                passive_current_command,
                                current_limits,
                                calibration_snapshot,
                                target_overrides=final_partial_targets,
                            ),
                        )
                    else:
                        send_fast(
                            connection,
                            trajectory_frame(
                                previous_x,
                                previous_y,
                                end_x,
                                end_y,
                                remaining,
                                current_limits,
                                calibration_snapshot,
                                target_overrides=final_partial_targets,
                            ),
                        )
                    sent_frames += 1
                    last_command_xy = (end_x, end_y)
                    last_command_phase = 1.0
                if trajectory_frame_writer is not None:
                    # The scheduler can finish as soon as the final frame is
                    # queued; wait for the wire handoff before endpoint/release
                    # logic so no later query can overtake the last target.
                    trajectory_frame_writer.flush()
                control_finished = time.perf_counter()
                control_runtime = max(0.001, control_finished - tick)
                control_hz = sent_frames / control_runtime
                if trajectory_frame_writer is not None:
                    wire_hz = trajectory_frame_writer.actual_hz()
                    if wire_hz > 0.0:
                        control_hz = wire_hz
                set_state(trajectory_hz_actual=round(control_hz, 1), trajectory_frames=sent_frames)
                # The target polyline was populated before the first command,
                # so the browser can render the entire calibration-validation
                # goal without waiting for the motion to reach each sample.
                final_force_profile = force_position_self_stress_bias(
                    end_x,
                    end_y,
                    force_position_contraction,
                    calibration_snapshot,
                )
                force_position_feedback_bias_deg[:] = list(
                    final_force_profile["position_bias_deg"]
                )
                final_targets = [
                    target
                    + trajectory_command_offsets[index]
                    + float(final_force_profile["position_bias_deg"][index])
                    for index, target in enumerate(
                        grid_motor_positions_at(end_x, end_y, calibration_snapshot)
                    )
                ]
                previous_force_bias = force_position_self_stress_bias(
                    previous_x,
                    previous_y,
                    force_position_contraction,
                    calibration_snapshot,
                )["position_bias_deg"]
                previous_targets = [
                    target
                    + trajectory_command_offsets[index]
                    + float(previous_force_bias[index])
                    for index, target in enumerate(
                        grid_motor_positions_at(previous_x, previous_y, calibration_snapshot)
                    )
                ]
                final_speeds = [
                    trajectory_target_rpm(previous, target, command_interval)
                    for target, previous in zip(final_targets, previous_targets)
                ]
                last_final_error: float | None = None
                actual_endpoint_xy: tuple[float, float] | None = None
                actual_endpoint_error_mm: float | None = None

                def consume_final_feedback(records: list[TimedFeedbackRecord]) -> None:
                    """Drain real 0x43 position+current samples during hand-off."""
                    nonlocal feedback_snapshot
                    nonlocal feedback_snapshot_at, feedback_snapshot_span
                    nonlocal feedback_raw_first_stamp, feedback_raw_last_stamp
                    nonlocal feedback_raw_updates, feedback_raw_hz
                    nonlocal feedback_snapshot_last_at
                    nonlocal filtered_actual, actual_endpoint_xy, actual_endpoint_error_mm
                    for record in records:
                        address = record.address
                        position = record.position
                        sampled_at = record.sampled_at
                        if address not in MOTOR_IDS:
                            continue
                        index = MOTOR_IDS.index(address)
                        trajectory_feedback_positions[index] = position
                        trajectory_feedback_times[index] = sampled_at
                        with STATE_LOCK:
                            telemetry = STATE["telemetry"].setdefault(str(address), {"id": address})
                            telemetry["position"] = position
                            if record.phase_current is not None:
                                telemetry["phase_current"] = record.phase_current
                            if record.voltage is not None:
                                telemetry["voltage"] = record.voltage
                            if record.bus_current is not None:
                                telemetry["bus_current"] = record.bus_current
                            if record.rpm is not None:
                                telemetry["rpm"] = record.rpm
                            if record.temperature is not None:
                                telemetry["temperature"] = record.temperature
                            if record.flags is not None:
                                telemetry["flags"] = record.flags
                                telemetry["flags_text"] = direct.decode_flags(record.flags)
                            telemetry["online"] = True
                        completed_snapshot = trajectory_feedback_assembler.add(record)
                        if completed_snapshot is None:
                            continue
                        sample_span = max(item.sampled_at for item in completed_snapshot) - min(item.sampled_at for item in completed_snapshot)
                        feedback_snapshot_at = max(item.sampled_at for item in completed_snapshot)
                        if feedback_snapshot_at <= feedback_snapshot_last_at or sample_span > trajectory_feedback_coherence_window:
                            continue
                        feedback_snapshot = time_aligned_feedback_positions(completed_snapshot)
                        feedback_snapshot_span = sample_span
                        feedback_snapshot_last_at = feedback_snapshot_at
                        feedback_raw_updates += 1
                        feedback_raw_first_stamp = feedback_raw_first_stamp or feedback_snapshot_at
                        feedback_raw_last_stamp = feedback_snapshot_at
                        feedback_raw_hz = (
                            (feedback_raw_updates - 1)
                            / max(0.001, feedback_raw_last_stamp - feedback_raw_first_stamp)
                            if feedback_raw_updates > 1
                            and feedback_raw_first_stamp is not None
                            and feedback_raw_last_stamp is not None
                            else 0.0
                        )
                        estimate = feedback_xy_estimate(feedback_snapshot, (end_x, end_y))
                        if estimate is None:
                            continue
                        actual_endpoint_xy = estimate
                        actual_endpoint_error_mm = math.hypot(estimate[0] - end_x, estimate[1] - end_y)
                        append_trajectory_trace("trajectory_actual_feedback_path", estimate)
                        filtered_actual = estimate
                        append_trajectory_trace("trajectory_actual_path", estimate)

                # Keep the real feedback stream alive while the endpoint
                # command hands off to the safety/readback phase. This removes
                # the visible pause that used to appear before the final small
                # segment was added to the purple trace.
                if timed_stream_active:
                    bridge_started = time.perf_counter()
                    next_bridge_command = bridge_started
                    while time.perf_counter() - bridge_started < TRAJECTORY_FINAL_FEEDBACK_BRIDGE_SECONDS:
                        if STOP_EVENT.is_set():
                            raise RuntimeError("用户停止轨迹")
                        now = time.perf_counter()
                        if now < next_bridge_command:
                            time.sleep(min(0.001, next_bridge_command - now))
                            continue
                        if session_hybrid:
                            assert passive_index is not None
                            send_fast(
                                connection,
                                three_position_one_torque_frame(
                                    final_targets,
                                    passive_index,
                                    passive_current_command,
                                    final_speeds,
                                    current_limits,
                                    torque_max_rpm=HYBRID_PATH_PASSIVE_MAX_RPM,
                                ),
                            )
                        else:
                            send_fast(
                                connection,
                                four_motor_position_frame(
                                    final_targets,
                                    final_speeds,
                                    current_limits,
                                ),
                            )
                        consume_final_feedback(
                            drain_trajectory_feedback()
                        )
                        next_bridge_command += TRAJECTORY_FINAL_REASSERT_INTERVAL
                        while next_bridge_command <= now:
                            next_bridge_command += TRAJECTORY_FINAL_REASSERT_INTERVAL
                    consume_final_feedback(
                        drain_trajectory_feedback()
                    )
                consume_final_feedback(end_trajectory_feedback())
                # The explicit end-window read is useful for closed-loop
                # diagnostics, but open-loop mode intentionally leaves the bus
                # quiet after the last position frame.
                end_currents: list[int | None] = [None for _ in MOTOR_IDS]
                if not open_loop:
                    for index in range(len(MOTOR_IDS)):
                        ok, reason = query_safety_field(
                            connection,
                            index,
                            0,
                            current_limit=current_base,
                        )
                        if not ok:
                            raise RuntimeError(reason)
                        with STATE_LOCK:
                            end_currents[index] = (
                                STATE.get("telemetry", {})
                                .get(str(MOTOR_IDS[index]), {})
                                .get("phase_current")
                            )
                append_process_log(
                    "trajectory_current_snapshot",
                    shape=kind,
                    phase_current=end_currents,
                    source="轨迹结束安全窗口",
                )
                final_started = time.perf_counter()
                final_settled = bool(open_loop)
                final_near_settled_since: float | None = None
                next_final_command = final_started
                next_final_read = final_started
                if open_loop:
                    # Reassert the endpoint briefly without opening a query /
                    # response round trip. This keeps the last absolute target
                    # present while the driver accepts the final frame.
                    for _ in range(3):
                        send_fast(
                            connection,
                            four_motor_position_frame(
                                final_targets,
                                final_speeds,
                                current_limits,
                            ),
                        )
                        time.sleep(max(0.001, TRAJECTORY_FINAL_REASSERT_INTERVAL))
                while (not open_loop) and time.perf_counter() - final_started < TRAJECTORY_FINAL_TIMEOUT_SECONDS:
                    if STOP_EVENT.is_set():
                        raise RuntimeError("用户停止轨迹")
                    now = time.perf_counter()
                    if now >= next_final_command:
                        # Reassert the exact endpoint during the bounded
                        # finish window at the same control cadence.  This is
                        # a continuous hold, not a second jump to the target.
                        if session_hybrid:
                            assert passive_index is not None
                            send_fast(
                                connection,
                                three_position_one_torque_frame(
                                    final_targets,
                                    passive_index,
                                    passive_current_command,
                                    final_speeds,
                                    current_limits,
                                    torque_max_rpm=HYBRID_PATH_PASSIVE_MAX_RPM,
                                ),
                            )
                        else:
                            send_fast(
                                connection,
                                four_motor_position_frame(
                                    final_targets,
                                    final_speeds,
                                    current_limits,
                                ),
                            )
                        next_final_command += TRAJECTORY_FINAL_REASSERT_INTERVAL
                        while next_final_command <= now:
                            next_final_command += TRAJECTORY_FINAL_REASSERT_INTERVAL
                    if now >= next_final_read:
                        values = read_trajectory_settle(connection)
                        sampled_at = time.perf_counter()
                        next_final_read = sampled_at + TRAJECTORY_FINAL_READ_INTERVAL
                        if len(values) != len(MOTOR_IDS) or any(
                            telemetry.position is None
                            or telemetry.rpm is None
                            or telemetry.flags is None
                            for telemetry in values
                        ):
                            raise RuntimeError("轨迹收尾位置、转速或状态回读不完整")
                        error = safety_error(
                            values,
                            current_limit=current_base,
                            ignore_driver_protection=trajectory_ignore_driver_protection,
                        )
                        if error:
                            raise RuntimeError(error)
                        live_positions = [t.position for t in values]
                        if all(value is not None for value in live_positions):
                            estimate = feedback_xy_estimate(
                                [float(value) for value in live_positions],
                                (end_x, end_y),
                            )
                            if estimate is not None:
                                actual_x, actual_y = estimate
                                actual_endpoint_xy = (actual_x, actual_y)
                                actual_endpoint_error_mm = math.hypot(actual_x - end_x, actual_y - end_y)
                                append_trajectory_trace("trajectory_actual_feedback_path", (actual_x, actual_y))
                                filtered_actual = (actual_x, actual_y)
                                append_trajectory_trace("trajectory_actual_path", (actual_x, actual_y))
                        now = sampled_at
                        if session_hybrid:
                            pose = None
                            xy_near, active_xy = active_target_xy_near_and_stopped(
                                values,
                                (end_x, end_y),
                                active_indices,
                                calibration_snapshot,
                                initial_xy=(end_x, end_y),
                                position_offsets_deg=trajectory_command_offsets,
                            )
                            pose_log = (
                                {
                                    "x_mm": round(active_xy[0], 3),
                                    "y_mm": round(active_xy[1], 3),
                                    "controller": "3-position-1-torque",
                                }
                                if active_xy is not None
                                else None
                            )
                            reached = selected_targets_reached(values, final_targets, active_indices)
                        else:
                            session_positions = [
                                float(value)
                                - trajectory_command_offsets[index]
                                - force_position_feedback_bias_deg[index]
                                for index, value in enumerate(live_positions)
                            ] if all(value is not None for value in live_positions) else []
                            pose = motor_positions_to_planar_pose(
                                session_positions,
                                calibration_snapshot,
                            )
                            pose_log = {
                                key: round(float(pose[key]), 3)
                                for key in ("x_mm", "y_mm", "yaw_deg", "closure_rms_mm", "closure_max_mm")
                            } if pose is not None else None
                            xy_near = draw_target_xy_near_and_stopped(
                                values,
                                (end_x, end_y),
                                calibration_snapshot,
                                position_offsets_deg=[
                                    trajectory_command_offsets[index]
                                    + force_position_feedback_bias_deg[index]
                                    for index in range(len(MOTOR_IDS))
                                ],
                            )
                            reached = draw_targets_reached(values, final_targets)
                        if reached and xy_near:
                            final_settled = True
                            break
                        if xy_near:
                            final_near_settled_since = final_near_settled_since or now
                            if now - final_near_settled_since >= TRAJECTORY_NEAR_SETTLE_SECONDS:
                                last_final_error = (
                                    selected_max_target_error(values, final_targets, active_indices)
                                    if session_hybrid
                                    else max_target_error(values, final_targets)
                                )
                                append_process_log(
                                    "trajectory_finish_soft_settle",
                                    shape=kind,
                                    max_error_deg=round(last_final_error or 0.0, 2),
                                    tolerance_deg=TRAJECTORY_NEAR_POSITION_TOLERANCE,
                                    planar_pose_ok=True,
                                    solved_planar_pose=pose_log,
                                )
                                set_state(message=f"终点已接近（最大误差 {last_final_error:.1f}°），平滑结束")
                                final_settled = True
                                break
                            set_state(message="终点坐标已接近，等待张力稳定")
                        else:
                            final_near_settled_since = None
                            if not session_hybrid and pose is not None and (
                                float(pose["closure_rms_mm"]) > TRAJECTORY_PLANAR_CLOSURE_RMS_TOLERANCE_MM
                                or float(pose["closure_max_mm"]) > TRAJECTORY_PLANAR_CLOSURE_MAX_TOLERANCE_MM
                            ):
                                set_state(
                                    message=(
                                        f"终点已接近，正在核对四绳反馈"
                                        f"（闭合残差 {float(pose['closure_rms_mm']):.2f}mm）"
                                    )
                                )
                        last_final_error = (
                            selected_max_target_error(values, final_targets, active_indices)
                            if session_hybrid
                            else max_target_error(values, final_targets)
                        )
                    time.sleep(0.001)
                if not final_settled:
                    if bool(spec.get("allow_endpoint_timeout")):
                        # The one-click visual run is an observation pass.  A
                        # loaded edge cable can still be settling after the
                        # final polyline point; keep the measured overlay and
                        # finish the pass so the operator can see every shape.
                        # Safety teardown below still disables all four axes.
                        append_process_log(
                            "trajectory_finish_timeout_tolerated",
                            shape=kind,
                            max_error_deg=round(last_final_error, 2)
                            if last_final_error is not None
                            else None,
                            reason="all-test visual pass keeps measured endpoint and disables safely",
                        )
                        set_state(
                            message=(
                                f"终点反馈仍有 {last_final_error:.1f}° 误差；已保留实测轨迹并安全结束"
                                if last_final_error is not None
                                else "终点反馈未完整；已保留已采集轨迹并安全结束"
                            )
                        )
                        final_settled = True
                    else:
                        raise RuntimeError(
                            f"轨迹终点 {TRAJECTORY_FINAL_TIMEOUT_SECONDS:.0f} 秒内未稳定到位（最大误差 {last_final_error:.1f}°），已停止并失能"
                            if last_final_error is not None
                            else f"轨迹终点 {TRAJECTORY_FINAL_TIMEOUT_SECONDS:.0f} 秒内未收到完整位置反馈，已停止并失能"
                        )
                # The final settle read is the authoritative observed end
                # position. Persist it explicitly so the rendered feedback
                # path cannot stop one sample short of the endpoint.
                if actual_endpoint_xy is not None:
                    force_trajectory_trace_endpoint("trajectory_actual_feedback_path", actual_endpoint_xy)
                    force_trajectory_trace_endpoint("trajectory_actual_path", actual_endpoint_xy)
                if actual_endpoint_error_mm is not None:
                    with STATE_LOCK:
                        STATE["trajectory_fit_error_mm"] = round(actual_endpoint_error_mm, 2)
                with STATE_LOCK:
                    diagnostic_target = copy.deepcopy(
                        STATE.get("trajectory_target_path_segments")
                        or STATE.get("trajectory_target_path", [])
                    )
                    diagnostic_actual = copy.deepcopy(
                        STATE.get(
                            "trajectory_actual_feedback_path_segments",
                            STATE.get("trajectory_actual_feedback_path", []),
                        )
                    )
                    diagnostic_currents = list(end_currents)
                trajectory_diagnostic = analyze_trajectory_feedback(
                    diagnostic_target,
                    diagnostic_actual,
                    diagnostic_currents,
                )
                if open_loop:
                    trajectory_diagnostic = {
                        "status": f"纯位置开环{command_hz:.0f}Hz运行完成",
                        "target_points": sum(
                            len(segment) for segment in diagnostic_target
                        ) if diagnostic_target and isinstance(diagnostic_target[0], list) and diagnostic_target[0] and isinstance(diagnostic_target[0][0], list) else len(diagnostic_target),
                        "actual_points": 0,
                        "coverage": None,
                        "rms_error_mm": None,
                        "mean_error_mm": None,
                        "max_error_mm": None,
                        "endpoint_error_mm": None,
                        "current_values_ma": end_currents,
                        "recommendation": (
                            f"无反馈模式只证明电脑按{command_hz:.0f}Hz发送了目标轨迹；"
                            "真实球心误差需要重新开启反馈测量"
                        ),
                    }
                elif not timed_stream_supported and not force_position_enabled:
                    # One end-point read cannot describe the shape of a whole
                    # stroke.  Never turn sparse pure-position readback into a
                    # misleading large/small RMS figure.
                    trajectory_diagnostic = {
                        "status": f"纯位置{command_hz:.0f}Hz运行完成",
                        "target_points": sum(
                            len(segment) for segment in diagnostic_target
                        ) if diagnostic_target and isinstance(diagnostic_target[0], list) and diagnostic_target[0] and isinstance(diagnostic_target[0][0], list) else len(diagnostic_target),
                        "actual_points": sum(
                            len(segment) for segment in diagnostic_actual
                        ) if diagnostic_actual and isinstance(diagnostic_actual[0], list) and diagnostic_actual[0] and isinstance(diagnostic_actual[0][0], list) else len(diagnostic_actual),
                        "coverage": None,
                        "rms_error_mm": None,
                        "mean_error_mm": None,
                        "max_error_mm": None,
                        "endpoint_error_mm": round(actual_endpoint_error_mm, 3)
                        if actual_endpoint_error_mm is not None
                        else None,
                        "current_values_ma": diagnostic_currents,
                        "recommendation": "生产运行优先保证四电机100Hz同步位置；每个目标等待完整反馈，终点回读有效",
                    }
                trajectory_diagnostic["controller"] = (
                    "4-position-force" if force_position_enabled else "4-position"
                )
                trajectory_diagnostic["motion_feedback"] = not open_loop
                trajectory_diagnostic["start_anchor_error_mm"] = (
                    round(start_anchor_error_mm, 3)
                    if start_anchor_error_mm is not None
                    else None
                )
                trajectory_diagnostic["session_command_offsets_deg"] = [
                    round(value, 3) for value in trajectory_command_offsets
                ]
                trajectory_diagnostic["precision_frame"] = "session_local_incremental"
                def control_timing_summary(field: str) -> dict[str, float] | None:
                    values = sorted(
                        float(item[field])
                        for item in control_phase_samples
                        if field in item and math.isfinite(float(item[field]))
                    )
                    if not values:
                        return None
                    return {
                        "p50": round(values[len(values) // 2], 4),
                        "p95": round(values[min(len(values) - 1, int(len(values) * 0.95))], 4),
                        "max": round(values[-1], 4),
                    }
                trajectory_diagnostic["control_timing_ms"] = {
                    field: control_timing_summary(field)
                    for field in (
                        "deadline_late_ms",
                        "pre_send_ms",
                        "send_ms",
                        "feedback_ms",
                        "housekeeping_ms",
                        "loop_work_ms",
                        "schedule_check_ms",
                    )
                }
                trajectory_diagnostic["deadline_missed_points"] = int(deadline_missed_total)
                trajectory_diagnostic["cadence_owner"] = "serial_writer" if trajectory_frame_writer is not None else "trajectory_worker"
                trajectory_diagnostic["force_position"] = {
                    "enabled": force_position_enabled,
                    "target_floor_ma": force_position_target_floor,
                    "protection_limit_ma": current_base,
                    "contraction_mm": round(force_position_contraction, 5),
                    "position_bias_deg": [
                        round(float(value), 4)
                        for value in final_force_profile["position_bias_deg"]
                    ],
                    "filtered_currents_ma": [
                        round(float(value), 1) if value is not None else None
                        for value in force_position_current_ema
                    ],
                    "last_update": force_position_last_update,
                }
                with STATE_LOCK:
                    STATE["trajectory_diagnostic"] = trajectory_diagnostic
                if session_hybrid:
                    persist_tension_checkpoint(
                        calibration_data(),
                        values,
                        "trajectory_three_plus_one_complete",
                        actual_endpoint_xy or (end_x, end_y),
                        passive_index=passive_index,
                    )
                elif tensioned_session:
                    # The last 0xCB frame remains active inside every driver.
                    # Reassert it at a low speed field and persist the observed
                    # loaded encoder state; there is no mode switch and no
                    # deliberate release of any cable after the drawing ends.
                    force_hold_frame = four_motor_position_frame(
                        final_targets,
                        [FORCE_POSITION_HOLD_RPM for _ in MOTOR_IDS],
                        current_limits,
                    )
                    send_fast(connection, force_hold_frame)
                    time.sleep(0.02)
                    send_fast(connection, force_hold_frame)
                    with STATE_LOCK:
                        will_repeat = bool(STATE.get("repeat")) and bool(spec.get("repeat"))
                    if not will_repeat and not force_position_enabled:
                        # Retain the endpoint and the position mode, but do not
                        # leave a model residual pushing at the drawing limit.
                        # Slew the current ceiling to the user's 300mA hold.
                        hold_limits = [min(int(v), CALIBRATION_BRUTE_FORCE_HOLD_CURRENT) for v in current_limits]
                        for hold_step in range(1, 9):
                            if STOP_EVENT.is_set():
                                raise RuntimeError("用户停止轨迹收尾")
                            limits = [round(a + (b-a)*hold_step/8) for a,b in zip(current_limits,hold_limits)]
                            send_fast(connection, four_motor_position_frame(final_targets, [FORCE_POSITION_HOLD_RPM]*len(MOTOR_IDS), limits))
                            if trajectory_frame_writer is not None:
                                trajectory_frame_writer.flush()
                            if STOP_EVENT.wait(0.05):
                                raise RuntimeError("用户停止轨迹收尾")
                        values = read_trajectory_settle(connection, attempts=2, include_load=True)
                        append_process_log("trajectory_hold_current_slew", current_limits_ma=hold_limits, endpoint=list((end_x,end_y)), phase_currents_ma=[v.phase_current for v in values])
                    persist_tension_checkpoint(
                        calibration_data(),
                        values,
                        "trajectory_four_position_force_complete",
                        actual_endpoint_xy or (end_x, end_y),
                        controller=TENSION_CHECKPOINT_CONTROLLER_FOUR_POSITION_FORCE,
                        command_positions=final_targets,
                        force_contraction_mm=force_position_contraction,
                    )
                with STATE_LOCK:
                    repeat = bool(STATE.get("repeat")) and bool(spec.get("repeat"))
                if not repeat and open_loop and not tensioned_session:
                    # A completed open-loop draw used to jump straight from a
                    # 2.5A endpoint frame to DISABLE, which made the platform
                    # visibly drop.  Keep the exact endpoint while stepping
                    # the position-current ceiling down to the 300mA hold
                    # floor, then let the normal safety disable finish.
                    release_start = max(
                        TRAJECTORY_TENSION_MIN_CURRENT,
                        max(int(value) for value in current_limits),
                    )
                    release_floor = TRAJECTORY_TENSION_MIN_CURRENT
                    if release_start > release_floor:
                        release_limits = []
                        for fraction in (0.75, 0.50, 0.25, 0.0):
                            limit = int(round(release_floor + (release_start - release_floor) * fraction))
                            release_limits.append(limit)
                            send_fast(
                                connection,
                                four_motor_position_frame(
                                    final_targets,
                                    [FORCE_POSITION_HOLD_RPM] * len(MOTOR_IDS),
                                    [limit] * len(MOTOR_IDS),
                                ),
                            )
                            time.sleep(0.08)
                        append_process_log(
                            "trajectory_soft_release",
                            shape=kind,
                            endpoint=[round(end_x, 2), round(end_y, 2)],
                            current_limits_ma=release_limits,
                            hold_current_ma=release_floor,
                        )
                if not repeat:
                    append_process_log(
                        "trajectory_complete",
                        shape=kind,
                        frames=sent_frames,
                        hz=round(control_hz, 2),
                        control_s=round(control_runtime, 3),
                        final_settle_s=round(time.perf_counter() - final_started, 3),
                        endpoint=[round(end_x, 2), round(end_y, 2)],
                        actual_endpoint_xy=[round(value, 2) for value in actual_endpoint_xy] if actual_endpoint_xy else None,
                        actual_endpoint_error_mm=round(actual_endpoint_error_mm, 2) if actual_endpoint_error_mm is not None else None,
                        feedback_mode=(
                            f"0x11 定时 0x{trajectory_feedback_info_code:02X}（位置异步确认）"
                            if timed_stream_supported
                            else "deferred"
                        ),
                        feedback_hz=round(feedback_hz, 2) if timed_stream_supported else 0.0,
                        feedback_batches=feedback_batches if timed_stream_supported else 0,
                        feedback_raw_hz=round(feedback_raw_hz, 2) if timed_stream_supported else 0.0,
                        feedback_raw_updates=feedback_raw_updates if timed_stream_supported else 0,
                        feedback_reads=feedback_reads if timed_stream_supported else 0,
                        trajectory_diagnostic=trajectory_diagnostic,
                        target_path_points=sum(
                            len(segment)
                            for segment in STATE.get("trajectory_target_path_segments", [])
                        ) or len(STATE.get("trajectory_target_path", [])),
                        actual_path_points=len(STATE.get("trajectory_actual_path", [])),
                        target_endpoint=[round(end_x, 2), round(end_y, 2)],
                        actual_path_endpoint=[round(value, 2) for value in actual_endpoint_xy] if actual_endpoint_xy else None,
                        controller=("4-position-force" if force_position_enabled else "4-position"),
                        active_motors=[MOTOR_IDS[index] for index in active_indices],
                        passive_motor=MOTOR_IDS[passive_index] if passive_index is not None else None,
                        passive_current_command_ma=passive_current_command if session_hybrid else None,
                        session_command_offsets_deg=[round(value, 3) for value in trajectory_command_offsets],
                        force_position_contraction_mm=round(force_position_contraction, 5),
                        force_position_bias_deg=[
                            round(float(value), 4)
                            for value in final_force_profile["position_bias_deg"]
                        ],
                        force_position_target_floor_ma=force_position_target_floor,
                        force_position_protection_limit_ma=current_base,
                        start_anchor_error_mm=round(start_anchor_error_mm, 3)
                        if start_anchor_error_mm is not None
                        else None,
                    )
                    feedback_summary = (
                        f"；同步反算显示 {feedback_hz:.1f}Hz、{feedback_batches} 组；原始四电机更新 {feedback_raw_hz:.1f}Hz、{feedback_raw_updates} 组"
                        if timed_stream_supported
                        else ("；纯位置开环未占用反馈总线，运动中不回读"
                              if open_loop else "；纯位置运行未占用反馈总线，终点已独立回读")
                    )
                    endpoint_summary = f"；终点误差 {actual_endpoint_error_mm:.2f}mm" if actual_endpoint_error_mm is not None else ""
                    anchor_summary = (
                        f"；本轮绝对起点不确定度 {start_anchor_error_mm:.2f}mm"
                        if start_anchor_error_mm is not None
                        else ""
                    )
                    set_state(
                        auto="idle",
                        point=spec["point_count"] - 1,
                        message=(
                            f"{kind_label(kind)}轨迹完成{feedback_summary}{endpoint_summary}{anchor_summary}；保持 3+1 低张力，当前会话可继续运行"
                            if session_hybrid
                            else f"{kind_label(kind)}轨迹完成{feedback_summary}{endpoint_summary}；四电机继续{'力位' if force_position_enabled else '纯位置'}闭环保持"
                            if tensioned_session
                            else f"{kind_label(kind)}轨迹完成{feedback_summary}{endpoint_summary}，四台电机已自动失能"
                        ),
                        repeat=False,
                    )
                    completed = True
                    if trajectory_frame_writer is not None:
                        trajectory_frame_writer.close()
                        connection._y42_trajectory_writer = None
                        trajectory_frame_writer = None
                    return True
                next_start_x, next_start_y = sample_path(kind, 0.0, spec)
                next_start_force_bias = force_position_self_stress_bias(
                    next_start_x,
                    next_start_y,
                    force_position_contraction,
                    calibration_snapshot,
                )["position_bias_deg"]
                next_start_targets = [
                    target
                    + trajectory_command_offsets[index]
                    + float(next_start_force_bias[index])
                    for index, target in enumerate(
                        grid_motor_positions_at(
                            next_start_x,
                            next_start_y,
                            calibration_snapshot,
                        )
                    )
                ]
                next_start_positions = [t.position for t in values]
                if any(position is None for position in next_start_positions):
                    raise RuntimeError("循环换轨时四台电机位置反馈不完整")
                set_state(
                    message=f"第 {cycle} 轮完成，正在平滑移动到下一轮起点 ({next_start_x:.1f}, {next_start_y:.1f})mm"
                )
                if session_hybrid:
                    assert passive_index is not None
                    if trajectory_frame_writer is not None:
                        trajectory_frame_writer.flush()
                        connection._y42_trajectory_writer = None
                    move_to_start_smooth_three_plus_one(
                        connection,
                        [float(position) for position in next_start_positions],
                        next_start_targets,
                        passive_index,
                        passive_current_command,
                        f"{kind_label(kind)}第 {cycle} 轮→下一轮起点",
                        position_current=current_limits,
                    )
                else:
                    if trajectory_frame_writer is not None:
                        trajectory_frame_writer.flush()
                        connection._y42_trajectory_writer = None
                    move_to_start_smooth(
                        connection,
                        [float(position) for position in next_start_positions],
                        next_start_targets,
                        f"{kind_label(kind)}第 {cycle} 轮→下一轮起点",
                    )
                if trajectory_frame_writer is not None:
                    connection._y42_trajectory_writer = trajectory_frame_writer
                append_process_log(
                    "trajectory_loop_transition",
                    shape=kind,
                    from_xy=[round(end_x, 2), round(end_y, 2)],
                    to_xy=[round(next_start_x, 2), round(next_start_y, 2)],
                )
                set_state(message=f"已平滑到达第 {cycle + 1} 轮起点，准备继续绘制")
    except Exception as exc:
        error = str(exc)
        append_process_log("trajectory_error", shape=kind, error=error)
        if trajectory_fault_requires_recalibration(error):
            set_state(
                control_unlocked=False,
                auto="error",
                message="已紧急停止：" + error + "；正在自动重连并失能四台电机",
                repeat=False,
            )
        else:
            set_state(
                control_unlocked=False,
                auto="stopping",
                message="轨迹跟随误差超出当前容差，正在安全收尾并保留四角基准：" + error,
                repeat=False,
            )
    finally:
        if trajectory_frame_writer is not None:
            try:
                trajectory_frame_writer.close()
            except Exception as writer_error:
                append_process_log(
                    "trajectory_frame_writer_cleanup",
                    error=str(writer_error),
                )
            trajectory_frame_writer = None
        if trajectory_feedback_reader is not None:
            try:
                trajectory_feedback_reader.stop()
            except Exception as reader_error:
                append_process_log(
                    "trajectory_feedback_reader_cleanup",
                    error=str(reader_error),
                )
            trajectory_feedback_reader = None
        with STATE_LOCK:
            STATE["trajectory_encoder_lead_deg"] = [0.0 for _ in MOTOR_IDS]
        # A four-shape test uses one continuous enabled session: disabling
        # here after every shape unloads the cables and makes the next shape's
        # start move prone to stalling. Any error or user stop still forces
        # the safety shutdown even when the caller requests keep_enabled.
        must_disable = bool(
            error
            or STOP_EVENT.is_set()
            or (not keep_enabled and not (completed and tensioned_session))
        )
        # The motion loop turns the stop flag into a short "用户急停"
        # exception while unwinding.  Use the independent-stop latch as the
        # source of truth so that exception text cannot invalidate a recoverable
        # emergency-stop checkpoint before the shutdown thread captures it.
        user_emergency_stop = bool(EMERGENCY_STOP_PENDING.is_set())
        hard_trajectory_fault = trajectory_fault_requires_recalibration(error)
        recoverable_trajectory_stop = bool(
            error and not hard_trajectory_fault and not user_emergency_stop
        )
        if must_disable and tensioned_session and not user_emergency_stop and hard_trajectory_fault:
            invalidate_session_calibration(
                "轨迹出现电流/温度/通信/驱动保护故障；电机已失能，光滑卷筒的排线基准不再可复用"
            )
        recovery = (
            disable_all_with_reconnect(
                current_port(),
                current_baud(),
                announce=bool(error or STOP_EVENT.is_set()),
                preserve_session=user_emergency_stop or recoverable_trajectory_stop,
            )
            if must_disable
            else {"ok": True, "error": ""}
        )
        if not recovery["ok"]:
            set_state(
                control_unlocked=False,
                auto="error",
                message="轨迹已停止，但 RS485 自动重连后仍无法确认四台失能；请立即切断电机动力或使用硬件急停（" + recovery["error"] + "）",
                repeat=False,
            )
        elif STOP_EVENT.is_set():
            set_state(auto="idle", message="已停止，已自动重连并确认四台电机急停/失能", repeat=False)
        elif recoverable_trajectory_stop:
            set_state(
                auto="idle",
                control_unlocked=True,
                last_failure=None,
                message=(
                    "轨迹已停止：起点/终点跟随误差超出本次容差；四台已安全重连并失能，"
                    "四角基准已保留，可直接重新绘制，无需重新校准"
                ),
                repeat=False,
            )
        elif error:
            set_state(control_unlocked=False, auto="error", message="已紧急停止：" + error + "；已自动重连并确认四台电机失能", repeat=False)
        elif keep_enabled:
            set_state(
                message=(
                    f"{kind_label(kind)}完成，保持 3+1 低张力，准备下一个测试图形"
                    if session_hybrid
                    else f"{kind_label(kind)}完成，四台保持使能，准备下一个测试图形"
                )
            )
        if timer_resolution:
            set_high_resolution_timer(False)
        if previous_thread_priority is not None:
            set_current_thread_priority(previous_thread_priority)
        sys.setswitchinterval(previous_gil_switch_interval)
        STOP_EVENT.clear()
    return completed


def shape_sequence_worker() -> None:
    """Run circle/square/triangle, then the snake gate.

    This is intentionally one pass.  The previous worker looped forever and
    never had a final acceptance result, so it could report that the shapes
    were usable while the height solver had not been checked at all.  A fully
    valid grid is used when available; otherwise the calibrated base geometry
    remains independently testable.
    """
    error: str | None = None
    stopped = False
    cycle = 0
    completed_shapes: list[str] = []
    snake_summary: dict = {}
    snake_finished = False
    try:
        calibration = calibration_data()
        if not calibration.get("valid"):
            raise RuntimeError("请先完成四角自动校准")
        grid_candidate = calibration.get("grid_compensation")
        grid = grid_candidate if isinstance(grid_candidate, dict) else {}
        grid_ok, _ = validate_grid_compensation(grid)
        grid_enabled = bool(grid_ok and grid.get("valid") is True and grid.get("enabled") is True)
        tension_target = int(calibration.get("grid_tension_target_current_ma", GRID_DEFAULT_TENSION_CURRENT_MA))
        grid_mode = "已启用多点补偿地图" if grid_enabled else "使用基础几何（网格未启用）"
        width, height = drawable_workspace_dimensions(calibration)
        set_state(
            auto="shape-sequence",
            repeat=False,
            shape_sequence={
                "status": "running",
                "cycle": 0,
                "shape": "",
                "shapes": list(TRAJECTORY_SHAPE_SEQUENCE),
                "tension_target_ma": tension_target,
                "grid_enabled": grid_enabled,
                "adaptive_slope": False,
                "snake_gate": "pending",
            },
            trajectory_balance={
                "enabled": True,
                "adaptive_slope": False,
                "target_current_ma": tension_target,
                "adjustments": 0,
                "last": "等待四台完整绝对相电流反馈",
            },
            message=(
                "自动校准测试准备：圆形 → 正方形 → 三角形；" + grid_mode
            ),
        )
        append_process_log(
            "shape_sequence_start",
            shapes=list(TRAJECTORY_SHAPE_SEQUENCE),
            workspace=[width, height],
            target_current_ma=tension_target,
            grid_enabled=grid_enabled,
            current_limit_ma=CALIBRATION_TEST_CURRENT_LIMIT,
            adaptive_slope=False,
        )
        cycle = 1
        for kind in TRAJECTORY_SHAPE_SEQUENCE:
            if STOP_EVENT.is_set():
                stopped = True
                return
            spec = test_shape_spec(kind, width, height)
            # The standalone visual-pattern buttons intentionally use the
            # ESP32-compatible open-loop feed.  This acceptance sequence is
            # different: it must exercise the repaired 100 Hz 0x43 feedback
            # stream, so run the same geometric samples with the closed-loop
            # observer enabled.
            spec["open_loop"] = False
            spec["feedback"] = True
            spec["controller_mode"] = "four_position"
            with STATE_LOCK:
                STATE["shape_sequence"] = {
                    "status": "running",
                    "cycle": cycle,
                    "shape": kind,
                    "shapes": list(TRAJECTORY_SHAPE_SEQUENCE),
                    "tension_target_ma": tension_target,
                    "grid_enabled": grid_enabled,
                    "adaptive_slope": False,
                    "snake_gate": "pending",
                }
            completed = trajectory_worker(
                kind,
                spec,
                keep_enabled=True,
                balance_tension=True,
                adaptive_slope=False,
                tension_target_current=tension_target,
            )
            if not completed:
                with STATE_LOCK:
                    inner_message = str(STATE.get("message", "连续测试图形失败"))
                if "用户停止" in inner_message or "已停止" in inner_message or "急停" in inner_message or STOP_EVENT.is_set():
                    stopped = True
                else:
                    error = inner_message
                return
            # Keep each completed shape's live trim even if the process is
            # closed after this point.  The next shape immediately uses the
            # same STATE copy, so this write is not in the 100 Hz loop.
            persist_calibration(calibration_data())
            current_calibration = calibration_data()
            completed_shapes.append(kind)
            set_state(
                auto="shape-sequence",
                repeat=False,
                shape_sequence={
                    "status": "running",
                    "cycle": cycle,
                    "shape": kind,
                    "completed": list(completed_shapes),
                    "shapes": list(TRAJECTORY_SHAPE_SEQUENCE),
                    "tension_target_ma": tension_target,
                    "grid_enabled": grid_enabled,
                    "adaptive_slope": False,
                    "slope_trim_percent": current_calibration.get("slope_trim_percent"),
                    "snake_gate": "pending",
                },
                message=(
                    f"自动校准测试：{kind_label(kind)}完成，已保存实时系数；"
                    "保持四绳张力继续下一个图形"
                ),
            )

        if STOP_EVENT.is_set():
            stopped = True
            return
        set_state(
            auto="shape-sequence",
            repeat=False,
            shape_sequence={
                "status": "running",
                "cycle": cycle,
                "shape": "planar-snake",
                "shapes": list(TRAJECTORY_SHAPE_SEQUENCE),
                "tension_target_ma": tension_target,
                "grid_enabled": grid_enabled,
                "adaptive_slope": False,
                "snake_gate": "running",
            },
            message="三图形验收完成，开始 20mm 内缩平面蛇形高度/XY验收",
        )
        planar_snake_target = tension_target
        planar_snake_test_worker(
            PLANAR_SNAKE_TEST_CURRENT,
            planar_snake_target,
        )
        snake_finished = True
        with STATE_LOCK:
            snake_summary = copy.deepcopy(STATE.get("planar_snake_test", {}))
        if snake_summary.get("status") != "pass":
            error = (
                "蛇形验收未达标："
                f"高度最大 {snake_summary.get('height_max_mm', '—')}mm，"
                f"XY最大误差 {snake_summary.get('xy_error_max_mm', '—')}mm"
            )
        else:
            append_process_log(
                "calibration_auto_validation_complete",
                shapes=list(TRAJECTORY_SHAPE_SEQUENCE),
                slope_trim_percent=calibration_data().get("slope_trim_percent"),
                snake_summary=snake_summary,
            )
    except Exception as exc:
        error = str(exc)
        append_process_log("shape_sequence_error", error=error, cycle=cycle)
    finally:
        recovery = disable_all_with_reconnect(current_port(), current_baud(), announce=bool(error or stopped))
        if not recovery["ok"]:
            set_state(
                auto="error",
                message="自动校准测试结束，但 RS485 重连后仍无法确认四台失能；请立即切断动力或使用硬件急停（" + recovery["error"] + "）",
                shape_sequence={"status": "error", "cycle": cycle, "shape": "", "error": recovery["error"]},
            )
        elif error:
            set_state(
                auto="error",
                message="自动校准测试未通过：" + error + "；四台已自动重连并失能",
                shape_sequence={
                    "status": "error",
                    "cycle": cycle,
                    "shape": "",
                    "shapes": list(TRAJECTORY_SHAPE_SEQUENCE),
                    "error": error,
                    "snake_gate": "fail" if snake_finished else "not-run",
                    "snake_summary": snake_summary,
                },
            )
        elif stopped or STOP_EVENT.is_set():
            set_state(
                auto="idle",
                repeat=False,
                message="自动校准测试已停止，四台电机已自动重连并失能",
                shape_sequence={"status": "stopped", "cycle": cycle, "shape": "", "shapes": list(TRAJECTORY_SHAPE_SEQUENCE)},
            )
        else:
            set_state(
                auto="idle",
                repeat=False,
                message=(
                    "自动校准完成：圆形、正方形、三角形张力系数已保存；"
                    "蛇形验收达到高度≤5mm、XY≤1mm，四台已自动重连并失能"
                ),
                shape_sequence={
                    "status": "complete",
                    "cycle": cycle,
                    "shape": "",
                    "shapes": list(TRAJECTORY_SHAPE_SEQUENCE),
                    "tension_target_ma": tension_target,
                    "grid_enabled": grid_enabled,
                    "adaptive_slope": False,
                    "snake_gate": "pass",
                    "snake_summary": snake_summary,
                    "slope_trim_percent": calibration_data().get("slope_trim_percent"),
                },
            )
        STOP_EVENT.clear()


def calibration_corner_targets(calibration: dict) -> list[list[float]]:
    """Return the four encoder snapshots captured during geometry calibration."""

    raw = calibration.get("samples")
    if not isinstance(raw, list) or len(raw) != len(MOTOR_IDS):
        raise RuntimeError("当前校准没有保存完整的四角编码器位置")
    targets: list[list[float]] = []
    for corner, row in enumerate(raw):
        if not isinstance(row, list) or len(row) != len(MOTOR_IDS):
            raise RuntimeError(f"校准角点 {corner + 1} 的编码器位置不完整")
        try:
            values = [float(value) for value in row]
        except (TypeError, ValueError):
            raise RuntimeError(f"校准角点 {corner + 1} 含有无效编码器位置") from None
        if any(not math.isfinite(value) for value in values):
            raise RuntimeError(f"校准角点 {corner + 1} 含有无效编码器位置")
        targets.append(values)
    return targets


def update_internal_feedback_calibration(
    calibration: dict, results: list[dict]
) -> dict:
    """Store encoder-only corner replay quality without changing geometry.

    The replay compares each measured encoder position with the corresponding
    saved corner target.  It is a useful repeatability/backlash check and a
    safe place to record current spread, but it intentionally never feeds the
    derived XY back into the kinematic model.
    """
    updated = copy.deepcopy(calibration)
    diagnostics = {**blank_internal_feedback_calibration(), **copy.deepcopy(updated.get("internal_feedback_calibration", {}))}
    errors: list[float] = []
    currents: list[float] = []
    for result in results:
        targets = result.get("target_positions") if isinstance(result, dict) else None
        actual = result.get("actual_positions") if isinstance(result, dict) else None
        if isinstance(targets, list) and isinstance(actual, list) and len(targets) == len(actual) == len(MOTOR_IDS):
            for target, observed in zip(targets, actual):
                try:
                    error = abs(float(observed) - float(target))
                except (TypeError, ValueError):
                    continue
                if math.isfinite(error):
                    errors.append(error)
        raw_currents = result.get("phase_current_ma") if isinstance(result, dict) else None
        if isinstance(raw_currents, list):
            for value in raw_currents:
                try:
                    current = abs(float(value))
                except (TypeError, ValueError):
                    continue
                if math.isfinite(current):
                    currents.append(current)
    if errors:
        ordered = sorted(errors)
        p95_index = min(len(ordered) - 1, max(0, math.ceil(len(ordered) * 0.95) - 1))
        diagnostics.update(
            {
                "status": "pass" if ordered[p95_index] <= 3.0 else "diagnostic",
                "sample_count": len(errors),
                "position_rms_deg": round(math.sqrt(sum(value * value for value in errors) / len(errors)), 4),
                "position_p95_deg": round(ordered[p95_index], 4),
                "position_max_deg": round(ordered[-1], 4),
                "repeatability_deg": round(ordered[p95_index], 4),
                "verified": updated.get("internal_model_verified") is True,
                "reason": (
                    "四角编码器目标复现通过；仅证明电机重复性，不证明未知外部坐标"
                    if ordered[p95_index] <= 3.0
                    else "四角编码器复现存在偏差；保持基础模型，先检查回差/绳路"
                ),
            }
        )
    if currents:
        diagnostics["current_spread_ma"] = round(max(currents) - min(currents), 3)
    diagnostics["updated_at"] = round(time.time(), 3)
    updated["internal_feedback_calibration"] = diagnostics
    return updated


def corner_check_worker() -> None:
    """Revisit the four saved calibration corners for a visual squareness check."""

    error: str | None = None
    results: list[dict] = []
    try:
        calibration = calibration_data()
        targets = calibration_corner_targets(calibration)
        width, height = workspace_dimensions(calibration)
        weak_current = int(calibration.get("weak_current", CALIBRATION_DEFAULT_WEAK_CURRENT))
        position_current = trajectory_current_limit(calibration)
        set_state(
            auto="corner-check",
            corner=0,
            message="正在准备四角复现：使用校准时保存的四组实际位置，不重新校准编码器",
            corner_check={"status": "running", "corner": 0, "total": 4, "results": []},
        )
        append_process_log(
            "corner_check_start",
            workspace=[width, height],
            targets=targets,
            position_current=position_current,
        )
        with SERIAL_LOCK, direct.open_serial(current_port(), current_baud()) as connection:
            firmware = [read_firmware_status(connection, address) for address in MOTOR_IDS]
            non_x = [
                f"M{item['id']}={item.get('firmware') or '无可靠回包'}"
                for item in firmware
                if item.get("firmware") != "X"
            ]
            if non_x:
                raise RuntimeError("四角复现已取消：实际固件不是全 X（" + "、".join(non_x) + "）")
            stopped = stop_all(connection)
            if not all(item.get("accepted") for item in stopped):
                raise RuntimeError("四角复现启动前四台急停未全部收到 ACK")
            for index, address in enumerate(MOTOR_IDS):
                enabled, _, reply = enable_address(connection, address)
                if not enabled:
                    detail = direct.hex_bytes(reply) if reply else "超时无回包"
                    raise RuntimeError(f"四角复现：M{index + 1} 自动使能失败，RX={detail}")

            values = read_all_reliable(connection, attempts=2)
            safety = safety_error(values, current_limit=position_current)
            if safety:
                raise RuntimeError("四角复现启动检查：" + safety)
            for corner, target in enumerate(targets):
                if STOP_EVENT.is_set():
                    raise RuntimeError("用户停止四角复现")
                current_positions = [item.position for item in values]
                if any(position is None for position in current_positions):
                    raise RuntimeError(f"四角复现角点 {corner + 1} 前四台位置反馈不完整")
                label = CORNER_CHECK_LABELS[corner]
                set_state(
                    corner=corner + 1,
                    message=f"四角复现 {corner + 1}/4（{label}）：平滑移动到校准保存位置",
                    corner_check={"status": "running", "corner": corner + 1, "total": 4, "results": copy.deepcopy(results)},
                )
                move_to_start_smooth(
                    connection,
                    [float(position) for position in current_positions],
                    target,
                    f"四角复现·{label}",
                )
                settle_started: float | None = None
                started = time.monotonic()
                last_values = values
                while True:
                    if STOP_EVENT.is_set():
                        raise RuntimeError("用户停止四角复现")
                    values = read_all_reliable(connection, attempts=1)
                    safety = safety_error(values, current_limit=position_current)
                    if safety:
                        raise RuntimeError("四角复现：" + safety)
                    max_error = max_target_error(values, target)
                    rpms = [abs(float(item.rpm)) for item in values if item.rpm is not None]
                    max_rpm = max(rpms, default=float("inf"))
                    error_text = "待回读" if max_error is None else f"最大位置偏差 {max_error:.1f}°"
                    set_state(
                        message=f"四角复现 {corner + 1}/4（{label}）：{error_text}，最大转速 {max_rpm:.1f}RPM",
                        corner_check={"status": "running", "corner": corner + 1, "total": 4, "results": copy.deepcopy(results)},
                    )
                    last_values = values
                    settled = max_error is not None and max_error <= CORNER_CHECK_POSITION_TOLERANCE and max_rpm <= CORNER_CHECK_MAX_RPM
                    if settled:
                        settle_started = settle_started or time.monotonic()
                        if time.monotonic() - settle_started >= CORNER_CHECK_STABLE_SECONDS:
                            break
                    else:
                        settle_started = None
                    if time.monotonic() - started > CORNER_CHECK_TIMEOUT_SECONDS:
                        raise RuntimeError(
                            f"四角复现 {label} 未在 {CORNER_CHECK_TIMEOUT_SECONDS:.0f} 秒内到位，最后偏差 {max_error if max_error is not None else float('nan'):.1f}°"
                        )
                    time.sleep(0.08)

                hold_until = time.monotonic() + CORNER_CHECK_HOLD_SECONDS
                while time.monotonic() < hold_until:
                    if STOP_EVENT.is_set():
                        raise RuntimeError("用户停止四角复现")
                    last_values = read_all_reliable(connection, attempts=1)
                    safety = safety_error(last_values, current_limit=position_current)
                    if safety:
                        raise RuntimeError("四角复现保持期间：" + safety)
                    time.sleep(0.10)
                actual = [round(float(item.position), 2) if item.position is not None else None for item in last_values]
                max_error = max_target_error(last_values, target)
                estimate = position_to_xy([float(item.position) for item in last_values]) if all(item.position is not None for item in last_values) else None
                result = {
                    "corner": corner + 1,
                    "label": label,
                    "target_positions": [round(value, 2) for value in target],
                    "actual_positions": actual,
                    "phase_current_ma": [
                        round(abs(float(item.phase_current)), 1)
                        if item.phase_current is not None
                        else None
                        for item in last_values
                    ],
                    "max_error_deg": round(max_error, 2) if max_error is not None else None,
                    "estimated_xy": [round(estimate[0], 2), round(estimate[1], 2)] if estimate is not None else None,
                    "ok": max_error is not None and max_error <= CORNER_CHECK_POSITION_TOLERANCE,
                }
                results.append(result)
                append_process_log("corner_check_corner", **result)
                set_state(
                    corner_check={"status": "running", "corner": corner + 1, "total": 4, "results": copy.deepcopy(results)},
                    message=f"四角复现 {corner + 1}/4（{label}）完成：最大位置偏差 {result['max_error_deg'] if result['max_error_deg'] is not None else '待回读'}°，停留观察中",
                )
                values = last_values

            # Equalize the four pulls before the normal stop/disable so the
            # last corner does not release the ball with a sudden imbalance.
            for index, address in enumerate(MOTOR_IDS):
                accepted, _, reply = torque_command(connection, address, pull_directions()[index], weak_current)
                if not accepted:
                    detail = direct.hex_bytes(reply) if reply else "超时无回包"
                    raise RuntimeError(f"四角复现结束均衡张力：M{index + 1} 未确认 {weak_current}mA，RX={detail}")
            time.sleep(0.45)
            disable_results = disable_all(connection)
            if not all(item.get("accepted") for item in disable_results):
                raise RuntimeError("四角复现结束失能未全部收到 ACK")
            updated_calibration = update_internal_feedback_calibration(calibration, results)
            persist_calibration(updated_calibration)
            with STATE_LOCK:
                STATE["calibration"] = copy.deepcopy(updated_calibration)
                STATE["internal_feedback_calibration"] = copy.deepcopy(
                    updated_calibration["internal_feedback_calibration"]
                )
            append_process_log(
                "corner_check_complete",
                results=results,
                internal_feedback_calibration=updated_calibration.get("internal_feedback_calibration"),
            )
            set_state(
                auto="idle",
                corner=4,
                message="四角复现完成：请观察小球四个角点是否对称；四台电机已失能",
                corner_check={"status": "complete", "corner": 4, "total": 4, "results": copy.deepcopy(results)},
            )
    except Exception as exc:
        error = str(exc)
        append_process_log("corner_check_error", error=error, corner=STATE.get("corner"), results=results)
        set_state(
            auto="error",
            message="四角复现已停止：" + error,
            corner_check={"status": "error", "corner": STATE.get("corner", 0), "total": 4, "results": copy.deepcopy(results), "error": error},
        )
    finally:
        recovery = disable_all_with_reconnect(current_port(), current_baud(), announce=bool(error))
        if not recovery["ok"]:
            set_state(
                auto="error",
                message="四角复现结束，但 RS485 重连后仍无法确认四台失能；请立即切断电机动力或使用硬件急停（" + recovery["error"] + "）",
                corner_check={"status": "error", "corner": STATE.get("corner", 0), "total": 4, "results": copy.deepcopy(results), "error": recovery["error"]},
            )
        elif STOP_EVENT.is_set() and not error:
            set_state(auto="idle", message="四角复现已停止，四台电机已自动重连确认失能")
        elif error:
            set_state(auto="error", message="四角复现已停止：" + error + "；已自动重连确认四台失能")
        STOP_EVENT.clear()


def clear_tracking_cache() -> dict:
    """Clear the encoder-feedback diagnostic path without touching the motors."""

    pen_up_threshold, pen_down_threshold = tracking_pen_thresholds()
    with STATE_LOCK:
        running = STATE.get("auto") == "tracking"
        STATE["tracking_trace_generation"] = int(STATE.get("tracking_trace_generation", 0)) + 1
        generation = STATE["tracking_trace_generation"]
        STATE["tracking_trace"] = []
        STATE["tracking_trace_segments"] = []
        STATE["tracking_xy"] = None
        STATE["tracking_reference_xy"] = None
        STATE["tracking_reference_error_mm"] = None
        STATE["tracking_samples"] = 0
        STATE["tracking_xyz"] = None
        STATE["tracking_height_mm"] = None
        STATE["tracking_height_raw_mm"] = None
        STATE["tracking_height_confidence"] = 0.0
        STATE["tracking_height_z2_delta"] = None
        STATE["tracking_hz_target"] = TRACKING_HZ
        STATE["tracking_hz_actual"] = 0.0
        STATE["tracking_feedback_hz_actual"] = 0.0
        STATE["tracking_feedback_batches"] = 0
        STATE["tracking_feedback_span_ms"] = None
        STATE["tracking_feedback_age_ms"] = None
        STATE["tracking_feedback_recoveries"] = 0
        STATE["tracking_z_fit_spread_mm"] = None
        STATE["tracking_frames"] = 0
        STATE["tracking_position_reads"] = 0
        STATE["tracking_pen_state"] = {
            "enabled": running,
            "pen_up": bool(STATE.get("tracking_pen_state", {}).get("pen_up", False)),
            "streak": 0,
            "total_mm": 0.0,
            "height_mm": 0.0,
            "threshold_mm": pen_up_threshold,
            "down_threshold_mm": pen_down_threshold,
        }
    append_process_log("tracking_clear", running=running, generation=generation)
    return {
        "ok": True,
        "action": "tracking-clear",
        "message": "已清空编码器反算轨迹和参考点；张力跟踪继续运行，从新采样点开始" if running else "已清空编码器反算轨迹和参考点",
    }


def set_tracking_reference(point: object) -> dict:
    """Save a clicked physical reference point for visual comparison only."""

    if not isinstance(point, (list, tuple)) or len(point) != 2:
        raise ValueError("跟踪参考点必须是 [x,y] 画布坐标")
    try:
        nx, ny = float(point[0]), float(point[1])
    except (TypeError, ValueError):
        raise ValueError("跟踪参考点坐标无效") from None
    if not all(math.isfinite(value) and 0.0 <= value <= 1.0 for value in (nx, ny)):
        raise ValueError("跟踪参考点必须位于画布范围内")
    # Tracking and drawing share the same 110×148 ball-center frame.
    width, height = workspace_dimensions()
    reference = [round(width * nx, 2), round(height * (1.0 - ny), 2)]
    with STATE_LOCK:
        estimate = STATE.get("tracking_xy")
        error = None
        if isinstance(estimate, (list, tuple)) and len(estimate) == 2:
            error = math.hypot(float(estimate[0]) - reference[0], float(estimate[1]) - reference[1])
        STATE["tracking_reference_xy"] = reference
        STATE["tracking_reference_error_mm"] = round(error, 2) if error is not None else None
    append_process_log("tracking_reference", reference_xy=reference, estimate_xy=estimate)
    with STATE_LOCK:
        saved_error = STATE.get("tracking_reference_error_mm")
    return {
        "ok": True,
        "action": "tracking-reference",
        "reference_xy": reference,
        "error_mm": saved_error,
        "message": f"已设置实际参考点 ({reference[0]:.1f}, {reference[1]:.1f})mm",
    }


def read_tracking_position(connection: object, address: int) -> float | None:
    """Read only one encoder position with the short tracking timeout."""

    packet = direct.frame(address, 0x36, direct.FRAME_END)
    reply = b""
    for attempt in range(2):
        reply = direct.transact(
            connection,
            packet,
            first_byte_timeout=TRACKING_POSITION_FIRST_BYTE_TIMEOUT,
            inter_byte_quiet=TRACKING_POSITION_INTER_BYTE_QUIET,
            max_rx=16,
        )
        if valid_reply(reply, address, 0x36, 8):
            raw = direct.read_u32(reply, 3) / 10.0
            position = -raw if reply[2] else raw
            with STATE_LOCK:
                current = STATE["telemetry"].setdefault(str(address), {"id": address})
                current["position"] = position
                current["online"] = True
            return position
        if attempt == 0:
            time.sleep(0.001)
    return None


def wait_tracking_deadline(deadline: float) -> None:
    """Wait accurately enough for a sub-10 ms tick on Windows USB serial."""

    while True:
        remaining = deadline - time.perf_counter()
        if remaining <= 0.0 or STOP_EVENT.is_set():
            return
        # ``perf_counter`` is high resolution on Windows. Sleep only while
        # there is a full timer quantum ahead; spin for the final few ms so
        # short deadlines are not rounded up by the Windows scheduler.
        if remaining > 0.016:
            time.sleep(0.010)


def set_high_resolution_timer(enabled: bool) -> bool:
    """Use a 1 ms Windows timer while a fixed-rate worker is active."""

    if os.name != "nt":
        return False
    try:
        result = ctypes.windll.winmm.timeBeginPeriod(TRACKING_TIMER_RESOLUTION_MS) if enabled else ctypes.windll.winmm.timeEndPeriod(TRACKING_TIMER_RESOLUTION_MS)
        return int(result) == 0
    except (AttributeError, OSError):
        return False


def set_current_thread_priority(priority: int) -> int | None:
    """Set one worker's Windows priority and return its previous value."""

    if os.name != "nt":
        return None
    try:
        kernel32 = ctypes.windll.kernel32
        # ctypes otherwise assumes a 32-bit integer return value and truncates
        # the pseudo HANDLE on 64-bit Python, making both calls silently fail.
        kernel32.GetCurrentThread.restype = ctypes.c_void_p
        kernel32.GetThreadPriority.argtypes = [ctypes.c_void_p]
        kernel32.GetThreadPriority.restype = ctypes.c_int
        kernel32.SetThreadPriority.argtypes = [ctypes.c_void_p, ctypes.c_int]
        kernel32.SetThreadPriority.restype = ctypes.c_int
        handle = kernel32.GetCurrentThread()
        previous = int(kernel32.GetThreadPriority(handle))
        if not bool(kernel32.SetThreadPriority(handle, int(priority))):
            return None
        return previous
    except (AttributeError, OSError, TypeError, ValueError):
        return None


def tracking_io_loop(
    connection: object,
    current: int,
    directions: tuple[int, ...],
    shared: dict,
    shared_lock: threading.Lock,
    io_stop: threading.Event,
    serial_lock: threading.Lock,
    calibration: dict | None = None,
) -> None:
    """Read the asynchronous 0x43 position+current stream without queries."""

    stream_buffer = bytearray()
    latest_positions: list[float | None] = [None for _ in MOTOR_IDS]
    latest_times = [0.0 for _ in MOTOR_IDS]
    position_history: dict[int, float] = {}
    feedback_interval_ms = timed_feedback_interval_ms(getattr(connection, "baudrate", None))
    coherence_window = timed_feedback_coherence_window(getattr(connection, "baudrate", None))
    batch_assembler = FourMotorFeedbackAssembler(coherence_window)
    stream_started = time.perf_counter()
    last_recovery = stream_started - TRACKING_POSITION_RECOVER_COOLDOWN_SECONDS
    last_batch_log_at = 0.0

    def publish(records: list[TimedFeedbackRecord]) -> None:
        nonlocal last_batch_log_at
        if not records:
            return
        now = time.perf_counter()
        batch_log: dict | None = None
        with STATE_LOCK:
            for record in records:
                address = record.address
                position = record.position
                item = STATE["telemetry"].setdefault(str(address), {"id": address})
                item["position"] = position
                if record.phase_current is not None:
                    item["phase_current"] = record.phase_current
                if record.voltage is not None:
                    item["voltage"] = record.voltage
                if record.bus_current is not None:
                    item["bus_current"] = record.bus_current
                if record.rpm is not None:
                    item["rpm"] = record.rpm
                if record.temperature is not None:
                    item["temperature"] = record.temperature
                if record.flags is not None:
                    item["flags"] = record.flags
                    item["flags_text"] = direct.decode_flags(record.flags)
                item["online"] = True
        with shared_lock:
            for record in records:
                address = record.address
                position = record.position
                sampled_at = record.sampled_at
                index = MOTOR_IDS.index(address)
                latest_positions[index] = position
                latest_times[index] = sampled_at
                shared["position_reads"] += 1
                shared["missed"][index] = 0
                current_targets = shared.get("current_targets", [current for _ in MOTOR_IDS])
                current_limit = int(current_targets[index]) if index < len(current_targets) else current
                if now < float(shared.get("overcurrent_grace_until", 0.0)):
                    current_limit = OPERATING_CURRENT_MAX_MA
                if record.phase_current is not None and abs(float(record.phase_current)) > overcurrent_trip_limit(current_limit):
                    shared["error"] = (
                        f"实时相电流过大（M{index + 1}：{record.phase_current}mA，"
                        f"阈值 {overcurrent_trip_limit(current_limit)}mA），已停止保护"
                    )
                if record.temperature is not None and record.temperature >= HARD_TEMPERATURE:
                    shared["error"] = f"实时温度过高（M{index + 1}：{record.temperature}°C），已停止保护"
                if record.flags is not None and record.flags & 0x08:
                    shared["error"] = f"M{index + 1} 实时状态触发堵转/保护，已停止保护"
                snapshot = batch_assembler.add(record)
                # Only publish a complete, time-coherent four-ID snapshot.
                # Never solve from three new records plus one stale record:
                # that creates the reversed/segmented feedback line and also
                # contaminates the height estimate.
                if snapshot is not None:
                    batch_span = max(item.sampled_at for item in snapshot) - min(item.sampled_at for item in snapshot)
                    shared["last_batch_span"] = batch_span
                    if batch_span <= coherence_window:
                        by_address = {item.address: item for item in snapshot}
                        raw_snapshot_positions = [float(by_address[motor_id].position) for motor_id in MOTOR_IDS]
                        snapshot_positions = list(time_aligned_feedback_positions(snapshot))
                        snapshot_currents = [by_address[motor_id].phase_current for motor_id in MOTOR_IDS]
                        shared["positions"] = snapshot_positions
                        shared["position_times"] = [by_address[motor_id].sampled_at for motor_id in MOTOR_IDS]
                        shared["batch_id"] = int(shared.get("batch_id", 0)) + 1
                        shared["last_batch_at"] = max(item.sampled_at for item in snapshot)
                        shared["batch_times"] = [by_address[motor_id].sampled_at for motor_id in MOTOR_IDS]
                        batch_log = {
                            "positions_deg": snapshot_positions,
                            "raw_positions_deg": raw_snapshot_positions,
                            "phase_current_ma": snapshot_currents,
                            "sampled_at": max(item.sampled_at for item in snapshot),
                            "sample_span_ms": batch_span * 1000.0,
                        }
                    else:
                        shared["coherent_misses"] = int(shared.get("coherent_misses", 0)) + 1
        if (
            batch_log is not None
            and float(batch_log["sampled_at"]) - last_batch_log_at
            >= RAW_FEEDBACK_LOG_INTERVAL_SECONDS
        ):
            append_process_log(
                "tracking_feedback_batch",
                positions_deg=[round(float(value), 3) for value in batch_log["positions_deg"]],
                raw_positions_deg=[round(float(value), 3) for value in batch_log["raw_positions_deg"]],
                relative_rope_lengths_mm=calibration_relative_rope_lengths(
                    batch_log["positions_deg"],
                    calibration,
                ),
                phase_current_ma=[
                    round(float(value), 3) if value is not None else None
                    for value in batch_log["phase_current_ma"]
                ],
                sampled_at=round(float(batch_log["sampled_at"]), 6),
                sample_span_ms=round(float(batch_log["sample_span_ms"]), 3),
                model_family_key=calibration_model_context(calibration).get("model_family_key"),
            )
            last_batch_log_at = float(batch_log["sampled_at"])
    try:
        while not STOP_EVENT.is_set() and not io_stop.is_set():
            # The drivers push real 0x43 frames every 10ms. Drain them in
            # short slices instead of sleeping for a synthetic low-rate poll.
            with serial_lock:
                records = read_timed_position_records(
                    connection,
                    stream_buffer,
                    timeout=0.005,
                    position_history=position_history,
                )
            publish(records)
            # ``publish`` only runs the per-record bookkeeping. Check again
            # even when the adapter returns an empty slice, otherwise a total
            # stream loss could remain invisible indefinitely.
            now = time.perf_counter()
            with shared_lock:
                stale_indices = [
                    index
                    for index, sampled_at in enumerate(latest_times)
                    if (sampled_at <= 0.0 and now - stream_started > TRACKING_POSITION_RECOVER_SECONDS)
                    or (sampled_at > 0.0 and now - sampled_at > TRACKING_POSITION_RECOVER_SECONDS)
                ]
                failed_indices = [
                    index
                    for index, sampled_at in enumerate(latest_times)
                    if (sampled_at <= 0.0 and now - stream_started > TRACKING_POSITION_FAIL_SECONDS)
                    or (sampled_at > 0.0 and now - sampled_at > TRACKING_POSITION_FAIL_SECONDS)
                ]
                old_positions = list(shared.get("positions", latest_positions))
            if stale_indices and not failed_indices and now - last_recovery >= TRACKING_POSITION_RECOVER_COOLDOWN_SECONDS:
                # The timed stream is a device-side setting. Re-arming it here
                # is safe because this I/O thread owns the serial transaction
                # while the worker keeps the motors in their existing torque
                # mode. This absorbs a USB/RS485 adapter hiccup without making
                # the operator stop and restart tracking manually.
                append_process_log(
                    "tracking_feedback_recover",
                    stale_motors=[index + 1 for index in stale_indices],
                    gap_ms=round(max(now - sampled_at for sampled_at in latest_times if sampled_at > 0.0) * 1000.0, 1)
                    if any(sampled_at > 0.0 for sampled_at in latest_times)
                    else round((now - stream_started) * 1000.0, 1),
                )
                try:
                    with serial_lock:
                        start_timed_feedback_stream(connection, feedback_interval_ms, TIMED_FEEDBACK_INFO_CODE)
                        feedback_interval_ms = int(getattr(connection, "_y42_feedback_interval_ms", feedback_interval_ms))
                        feedback_hz_target = 1000.0 / max(1, feedback_interval_ms)
                        stream_buffer.clear()
                    position_history.clear()
                    latest_positions = [float(value) if value is not None else None for value in old_positions]
                    latest_times = [0.0 for _ in MOTOR_IDS]
                    batch_assembler = FourMotorFeedbackAssembler(coherence_window)
                    stream_started = time.perf_counter()
                    last_recovery = stream_started
                    with shared_lock:
                        shared["positions"] = list(latest_positions)
                        shared["position_times"] = [0.0 for _ in MOTOR_IDS]
                        shared["last_batch_at"] = 0.0
                        shared["batch_times"] = [0.0 for _ in MOTOR_IDS]
                        shared["feedback_recoveries"] = int(shared.get("feedback_recoveries", 0)) + 1
                except Exception as exc:
                    last_recovery = now
                    append_process_log("tracking_feedback_recover_error", error=str(exc))
            with shared_lock:
                failed_indices = [
                    index
                    for index, sampled_at in enumerate(latest_times)
                    if (sampled_at <= 0.0 and time.perf_counter() - stream_started > TRACKING_POSITION_FAIL_SECONDS)
                    or (sampled_at > 0.0 and time.perf_counter() - sampled_at > TRACKING_POSITION_FAIL_SECONDS)
                ]
                if failed_indices:
                    index = failed_indices[0]
                    shared["missed"][index] = int(TRACKING_POSITION_FAIL_SECONDS / TRACKING_INTERVAL)
                    shared["error"] = (
                        f"位置反馈持续丢失（M{index + 1}，超过 {TRACKING_POSITION_FAIL_SECONDS:.2f}s），已停止保护"
                    )
            with shared_lock:
                if shared.get("error"):
                    io_stop.set()
                    return
            # The 0x43 stream already carries phase current, temperature and
            # flags with each position. Do not inject synchronous 0x27/0x39/
            # 0x3A queries into it: on this half-duplex bus they collide with
            # the long 0x43 frames and recreate false offline/timeout stops.
            time.sleep(0.001)
    except Exception as exc:
        with shared_lock:
            shared["error"] = str(exc)
        io_stop.set()


def restore_three_plus_one_session_hold(
    connection: object,
    calibration: dict,
    fallback_positions: object,
) -> dict:
    """Hand four-torque tracking back to a no-jump 3+1 stationary hold."""

    values = read_all_reliable(connection, attempts=3)
    positions = [telemetry.position for telemetry in values]
    if not telemetry_ready_for_calibration(values) or any(value is None for value in positions):
        try:
            positions = [float(value) for value in list(fallback_positions)]
        except (TypeError, ValueError):
            positions = []
    if len(positions) != len(MOTOR_IDS):
        raise RuntimeError("结束跟踪时无法取得四台当前位置，不能安全交接 3+1 保持")
    positions = [float(value) for value in positions]
    with STATE_LOCK:
        state_xy = copy.deepcopy(STATE.get("tracking_xy"))
    if isinstance(state_xy, (list, tuple)) and len(state_xy) == 2:
        estimated_xy = (float(state_xy[0]), float(state_xy[1]))
    else:
        estimated_xy = position_to_xy(positions, calibration)
        if estimated_xy is None:
            estimated_xy = (MECHANISM_CENTER_X_MM, MECHANISM_CENTER_Y_MM)
    hold_floor = max(
        SESSION_HOLD_CURRENT_MIN_MA,
        min(
            SESSION_HOLD_CURRENT_MAX_MA,
            int(calibration.get("session_hold_current_ma", CALIBRATION_DEFAULT_WEAK_CURRENT)),
        ),
    )
    choice = select_session_passive_motor_for_path([estimated_xy], calibration)
    if choice.get("ok") is not True:
        raise RuntimeError("结束跟踪时无法选出稳定的 3+1 张力电机：" + str(choice.get("reason", "几何条件不足")))
    passive_index = int(choice["passive_index"])
    targets, balance = balanced_torque_current_targets(
        estimated_xy[0],
        estimated_xy[1],
        hold_floor,
        calibration,
        maximum_current_ma=HYBRID_PASSIVE_TORQUE_MAX_CURRENT_MA,
    )
    passive_current = targets[passive_index]
    frame = three_position_one_torque_frame(
        positions,
        passive_index,
        passive_current,
        [TRAJECTORY_START_RPM] * len(MOTOR_IDS),
        min(trajectory_runtime_current(), SESSION_HOLD_POSITION_CURRENT_MA),
        torque_slope=TRACKING_TORQUE_SLOPE_MA_PER_S,
        torque_max_rpm=CALIBRATION_TAKEUP_MAX_RPM,
    )
    # The active position targets are the encoder values sampled immediately
    # above, so the mode switch has zero commanded position step.
    send_fast(connection, frame)
    time.sleep(0.04)
    send_fast(connection, frame)
    time.sleep(0.18)
    verified = read_all_reliable(connection, attempts=2)
    fault = safety_error(
        verified,
        current_limit=max(trajectory_runtime_current(), passive_current),
    )
    if fault:
        raise RuntimeError("跟踪结束交接：" + fault)
    if is_same_tensioned_session(calibration):
        calibration = persist_tension_checkpoint(
            calibration,
            verified,
            "tracking_three_plus_one_handoff",
            estimated_xy,
            passive_index=passive_index,
        )
    with STATE_LOCK:
        live_calibration = STATE.get("calibration")
        if isinstance(live_calibration, dict) and is_same_tensioned_session(live_calibration):
            live_calibration["session_tension_held"] = True
            live_calibration["session_invalid_reason"] = ""
        STATE["trajectory_passive_current_ma"] = passive_current
    result = {
        "xy_mm": [round(estimated_xy[0], 3), round(estimated_xy[1], 3)],
        "positions_deg": [round(value, 3) for value in positions],
        "passive_index": passive_index,
        "passive_motor": MOTOR_IDS[passive_index],
        "passive_current_ma": passive_current,
        "geometry_balance_ok": bool(balance.get("ok")),
    }
    append_process_log("tracking_three_plus_one_handoff", **result)
    return result


def restore_four_position_force_session_hold(
    connection: object,
    calibration: dict,
    fallback_positions: object,
) -> dict:
    """Hand a moving/torque session to four position loops without a jump."""

    values = read_all_reliable(connection, attempts=3)
    positions = [telemetry.position for telemetry in values]
    if not telemetry_ready_for_calibration(values) or any(value is None for value in positions):
        try:
            positions = [float(value) for value in list(fallback_positions)]
        except (TypeError, ValueError):
            positions = []
    if len(positions) != len(MOTOR_IDS):
        raise RuntimeError("结束跟踪时无法取得四台当前位置，不能安全交接四位置力位保持")
    positions = [float(value) for value in positions]
    with STATE_LOCK:
        state_xy = copy.deepcopy(STATE.get("tracking_xy"))
    if isinstance(state_xy, (list, tuple)) and len(state_xy) == 2:
        estimated_xy = (float(state_xy[0]), float(state_xy[1]))
    else:
        estimated_xy = position_to_xy(positions, calibration)
        if estimated_xy is None:
            estimated_xy = (MECHANISM_CENTER_X_MM, MECHANISM_CENTER_Y_MM)
    current_limit = trajectory_runtime_current()
    try:
        saved_contraction = float(
            calibration.get(
                "tension_checkpoint_force_contraction_mm",
                0.24,
            )
        )
    except (TypeError, ValueError):
        saved_contraction = 0.24
    target_contraction = max(
        0.16,
        min(0.35, saved_contraction),
    )
    # The first aggregate command is the exact encoder pose plus only the
    # minimum self-stress bias.  Every later update increases that one scalar at
    # 0.4 mm/s; no cable receives a target step or a torque-to-position jerk.
    started = time.perf_counter()
    contraction = FORCE_POSITION_CONTRACTION_MIN_MM
    final_targets = list(positions)
    while True:
        profile = force_position_self_stress_bias(
            estimated_xy[0],
            estimated_xy[1],
            contraction,
            calibration,
        )
        final_targets = [
            position + float(profile["position_bias_deg"][index])
            for index, position in enumerate(positions)
        ]
        send_fast(
            connection,
            four_motor_position_frame(
                final_targets,
                [FORCE_POSITION_HOLD_RPM for _ in MOTOR_IDS],
                current_limit,
            ),
        )
        if contraction >= target_contraction - 1e-9:
            break
        time.sleep(0.025)
        contraction = min(target_contraction, contraction + 0.01)
    time.sleep(0.15)
    verified = read_all_reliable(connection, attempts=3)
    fault = safety_error(verified, current_limit=current_limit)
    if fault:
        raise RuntimeError("跟踪结束四位置交接：" + fault)
    if not telemetry_ready_for_calibration(verified):
        raise RuntimeError("跟踪结束四位置交接：四台位置/电流反馈不完整")
    if is_same_tensioned_session(calibration):
        persist_tension_checkpoint(
            calibration,
            verified,
            "tracking_four_position_force_handoff",
            estimated_xy,
            controller=TENSION_CHECKPOINT_CONTROLLER_FOUR_POSITION_FORCE,
            command_positions=final_targets,
            force_contraction_mm=contraction,
        )
    result = {
        "xy_mm": [round(estimated_xy[0], 3), round(estimated_xy[1], 3)],
        "positions_deg": [round(value, 3) for value in positions],
        "command_positions_deg": [round(value, 3) for value in final_targets],
        "force_contraction_mm": round(contraction, 5),
        "current_limit_ma": current_limit,
        "transition_s": round(time.perf_counter() - started, 3),
    }
    append_process_log("tracking_four_position_force_handoff", **result)
    return result


def tracking_worker(current: int, preserve_trace: bool = False) -> None:
    """Hold all four ropes and reconstruct the hand-moved ball on a fixed 100 Hz clock."""

    current_limit = max(TRACKING_MIN_CURRENT, min(TRACKING_MAX_CURRENT, int(current)))
    tension_floor = min(current_limit, TRACKING_AUTO_FLOOR_CURRENT_MA)
    error: str | None = None
    timer_resolution = False
    timed_stream_stopped = True
    soft_handoff: dict | None = None
    last_positions_for_handoff: list[float] = []
    pen_up_threshold, pen_down_threshold = tracking_pen_thresholds()
    try:
        calibration = calibration_data()
        require_internal_model_ready(calibration, "张力跟踪")
        model_context = calibration_model_context(calibration)
        pen_up_threshold, pen_down_threshold = tracking_pen_thresholds(calibration)
        timer_resolution = set_high_resolution_timer(True)
        directions = pull_directions()
        with STATE_LOCK:
            old_tracking_trace = copy.deepcopy(STATE.get("tracking_trace", []))
            old_tracking_segments = copy.deepcopy(STATE.get("tracking_trace_segments", []))
            requested_reference = copy.deepcopy(STATE.get("tracking_reference_xy"))
            prior_trajectory = copy.deepcopy(STATE.get("trajectory_actual_path", []))
            prior_trajectory_segments = copy.deepcopy(STATE.get("trajectory_actual_path_segments", []))
        trace_updates = (
            {}
            if preserve_trace and (old_tracking_trace or old_tracking_segments)
            else {"tracking_trace": [], "tracking_trace_segments": []}
        )
        set_state(
            auto="tracking",
            **trace_updates,
            tracking_xy=None,
            tracking_reference_xy=requested_reference,
            tracking_reference_error_mm=None,
            tracking_anchor_xy=None,
            tracking_anchor_source=None,
            tracking_relative_residual_mm=None,
            tracking_samples=0,
            tracking_current_ma=current_limit,
            tracking_current_limit_ma=current_limit,
            tracking_tension_floor_ma=tension_floor,
            tracking_current_targets=[tension_floor for _ in MOTOR_IDS],
            tracking_balance_adjustments=0,
            tracking_hz_target=TRACKING_HZ,
            tracking_hz_actual=0.0,
            tracking_feedback_hz_actual=0.0,
            tracking_feedback_batches=0,
            tracking_feedback_span_ms=None,
            tracking_feedback_age_ms=None,
            tracking_feedback_recoveries=0,
            tracking_z_fit_spread_mm=None,
            tracking_frames=0,
            tracking_position_reads=0,
            tracking_trace_generation=0,
            tracking_xyz=None,
            tracking_height_mm=None,
            tracking_height_raw_mm=None,
            tracking_height_confidence=0.0,
            tracking_height_z2_delta=None,
            tracking_height_zero_mm=None,
            tracking_pen_state={
                "enabled": True,
                "pen_up": False,
                "streak": 0,
                "total_mm": 0.0,
                "height_mm": 0.0,
                "threshold_mm": pen_up_threshold,
                "down_threshold_mm": pen_down_threshold,
            },
            message=f"四绳张力跟踪启动：保护上限 {current_limit}mA，正在从 {tension_floor}mA 自动张紧并同步接管",
        )
        with SERIAL_LOCK, direct.open_serial(current_port(), current_baud()) as connection:
            feedback_interval_ms = timed_feedback_interval_ms(getattr(connection, "baudrate", None))
            feedback_hz_target = 1000.0 / feedback_interval_ms
            firmware = [read_firmware_status(connection, address) for address in MOTOR_IDS]
            non_x = [
                f"M{item['id']}={item.get('firmware') or '无可靠回包'}"
                for item in firmware
                if item.get("firmware") != "X"
            ]
            if non_x:
                raise RuntimeError("张力跟踪已取消：实际固件不是全 X（" + "、".join(non_x) + "）")
            for index, address in enumerate(MOTOR_IDS):
                enabled, _, reply = enable_address(connection, address)
                if not enabled:
                    detail = direct.hex_bytes(reply) if reply else "超时无回包"
                    raise RuntimeError(f"张力跟踪：M{index + 1} 自动使能失败，RX={detail}")
            initial_values = read_all_reliable(connection, attempts=2)
            safety = safety_error(initial_values, current_limit=OPERATING_CURRENT_MAX_MA)
            if safety:
                raise RuntimeError("张力跟踪：" + safety)
            immediate_positions = [telemetry.position for telemetry in initial_values]
            if any(position is None for position in immediate_positions):
                raise RuntimeError("张力跟踪：启动时四台编码器位置反馈不完整")
            immediate_positions = [float(position) for position in immediate_positions]
            last_positions_for_handoff = list(immediate_positions)
            model_start_xy = position_to_xy(immediate_positions, calibration)
            trajectory_endpoint = None
            if prior_trajectory_segments and isinstance(prior_trajectory_segments[-1], list) and prior_trajectory_segments[-1]:
                trajectory_endpoint = prior_trajectory_segments[-1][-1]
            elif prior_trajectory:
                trajectory_endpoint = prior_trajectory[-1]
            anchor_candidates = (
                ("manual_reference", requested_reference),
                ("last_trajectory_endpoint", trajectory_endpoint),
                ("saved_tension_checkpoint", calibration.get("tension_checkpoint_xy_mm")),
                ("absolute_encoder_model", model_start_xy),
                ("workspace_center", (MECHANISM_CENTER_X_MM, MECHANISM_CENTER_Y_MM)),
            )
            start_xy = (MECHANISM_CENTER_X_MM, MECHANISM_CENTER_Y_MM)
            tracking_anchor_source = "workspace_center"
            workspace_width, workspace_height = workspace_dimensions(calibration)
            for source, candidate in anchor_candidates:
                try:
                    candidate_xy = (float(candidate[0]), float(candidate[1]))
                except (IndexError, TypeError, ValueError):
                    continue
                if (
                    all(math.isfinite(value) for value in candidate_xy)
                    and -2.0 <= candidate_xy[0] <= workspace_width + 2.0
                    and -2.0 <= candidate_xy[1] <= workspace_height + 2.0
                ):
                    start_xy = candidate_xy
                    tracking_anchor_source = source
                    break
            append_process_log(
                "tracking_relative_anchor",
                source=tracking_anchor_source,
                anchor_xy_mm=[round(value, 3) for value in start_xy],
                absolute_model_xy_mm=[round(value, 3) for value in model_start_xy] if model_start_xy is not None else None,
            )
            set_state(
                tracking_anchor_xy=[round(value, 3) for value in start_xy],
                tracking_anchor_source=tracking_anchor_source,
            )
            desired_start_currents, start_force_balance = balanced_torque_current_targets(
                start_xy[0],
                start_xy[1],
                tension_floor,
                calibration,
                maximum_current_ma=min(TRACKING_BALANCE_MAX_CURRENT_MA, current_limit),
            )
            initial_current_targets: list[int] = []
            for index, telemetry in enumerate(initial_values):
                measured = telemetry.phase_current
                measured_abs = (
                    abs(int(measured))
                    if measured is not None and math.isfinite(float(measured))
                    else desired_start_currents[index]
                )
                initial_current_targets.append(
                    max(
                        tension_floor,
                        min(
                            current_limit,
                            max(measured_abs, desired_start_currents[index]),
                        ),
                    )
                )
            set_state(
                message=(
                    f"四绳跟踪：从当前受力 {initial_current_targets}mA 平滑切换到"
                    f"几何平衡 {desired_start_currents}mA（自动基准 {tension_floor}mA / 保护上限 {current_limit}mA）"
                )
            )
            tracking_current_targets = smooth_four_torque_transition(
                connection,
                initial_current_targets,
                desired_start_currents,
                label="张力跟踪同步接管",
            )
            set_state(tracking_current_targets=list(tracking_current_targets))
            append_process_log(
                "tracking_force_balance_start",
                xy_mm=[round(start_xy[0], 3), round(start_xy[1], 3)],
                requested_limit_ma=current_limit,
                automatic_floor_ma=tension_floor,
                initial_targets_ma=initial_current_targets,
                balanced_targets_ma=tracking_current_targets,
                geometry_balance_ok=bool(start_force_balance.get("ok")),
            )
            # Do not use the first read as the height zero. Once the four
            # motors enter torque mode, the loaded ropes settle and their
            # encoder positions move. A short multi-frame median after that
            # settling motion prevents a stationary ball from looking like a
            # negative-height or invalid four-rope fit.
            set_state(
                message=f"四绳跟踪：同步张力已稳定，正在建立当前贴板高度零点……"
            )
            baseline_samples: list[list[float]] = []
            baseline_started = time.perf_counter()
            while time.perf_counter() - baseline_started < TRACKING_BASELINE_SETTLE_SECONDS:
                if STOP_EVENT.is_set():
                    raise RuntimeError("用户停止张力跟踪")
                settled_positions, reason = read_position_snapshot(connection)
                if settled_positions is None:
                    raise RuntimeError("张力跟踪：建立高度零点时位置回读失败：" + reason)
                baseline_samples.append(settled_positions)
                time.sleep(TRACKING_BASELINE_SAMPLE_INTERVAL)
            if len(baseline_samples) < TRACKING_BASELINE_MIN_SAMPLES:
                raise RuntimeError(
                    f"张力跟踪：张力稳定采样不足（{len(baseline_samples)}/{TRACKING_BASELINE_MIN_SAMPLES}）"
                )
            last_positions = [
                float(statistics.median(sample[index] for sample in baseline_samples))
                for index in range(len(MOTOR_IDS))
            ]
            baseline_span = [
                round(max(sample[index] for sample in baseline_samples) - min(sample[index] for sample in baseline_samples), 2)
                for index in range(len(MOTOR_IDS))
            ]
            append_process_log(
                "tracking_baseline_settle",
                current_limit_ma=current_limit,
                automatic_floor_ma=tension_floor,
                immediate_positions=immediate_positions,
                settled_positions=last_positions,
                immediate_relative_rope_lengths_mm=calibration_relative_rope_lengths(immediate_positions, calibration),
                settled_relative_rope_lengths_mm=calibration_relative_rope_lengths(last_positions, calibration),
                position_span=baseline_span,
                samples=len(baseline_samples),
                duration_s=round(time.perf_counter() - baseline_started, 3),
                model_family_key=model_context.get("model_family_key"),
                position_reference_deg=model_context.get("position_reference_deg"),
            )
            last_positions_for_handoff = list(last_positions)
            frame_width, frame_height = workspace_dimensions(calibration)
            workspace_left, workspace_bottom, workspace_width, workspace_height = drawable_workspace(calibration)
            initial_lengths = encoder_positions_to_lengths(last_positions, calibration)
            anchor_global_x = start_xy[0] + workspace_left
            anchor_global_y = start_xy[1] + workspace_bottom
            baseline_z_raw = (
                z_squared_estimates(initial_lengths, anchor_global_x, anchor_global_y, calibration)
                if initial_lengths is not None
                else None
            )
            baseline_z_squared = (
                correct_planar_z_squared(
                    baseline_z_raw,
                    anchor_global_x,
                    anchor_global_y,
                    calibration,
                )
                if baseline_z_raw is not None
                else None
            )
            if initial_lengths is None or baseline_z_squared is None:
                raise RuntimeError("张力跟踪：启动时无法建立四根绳增量基线")
            baseline_z_spread = math.sqrt(max(0.0, max(baseline_z_squared) - min(baseline_z_squared)))
            if baseline_z_spread > TRACKING_MAX_Z_FIT_SPREAD_MM:
                append_process_log(
                    "tracking_start_height_uncertain",
                    z_fit_spread_mm=round(baseline_z_spread, 2),
                    message="启动时四绳绝对长度存在固定偏差；XY与高度均已改用本次张紧后的增量基线",
                )
            # The planar z² correction makes the board-contact residual zero;
            # it does not reveal the physical vertical separation from each
            # drum exit to the ball attachment.  Keep an independently measured
            # reference, if one is ever added to the calibration record, and
            # otherwise let the height diagnostic remain explicitly unavailable
            # instead of treating sqrt(delta z²) as millimetres.
            baseline_vertical_distance_mm = calibration.get(
                "tracking_baseline_vertical_distance_mm"
            )
            initial_xy = start_xy
            if not (
                -TRACKING_FRAME_MARGIN_MM <= initial_xy[0] <= workspace_width + TRACKING_FRAME_MARGIN_MM
                and -TRACKING_FRAME_MARGIN_MM <= initial_xy[1] <= workspace_height + TRACKING_FRAME_MARGIN_MM
            ):
                raise RuntimeError(
                    f"张力跟踪：启动位置 ({initial_xy[0]:.1f}, {initial_xy[1]:.1f})mm 超出 "
                    f"{workspace_width:.1f}×{workspace_height:.1f}mm 工作框，请先把小球放回板面范围"
                )
            # The board-contact position is zero in the corrected z² frame. A
            # physical height in millimetres is only enabled when the saved
            # calibration also contains an independently measured baseline
            # vertical distance; the relative-height helper rejects the
            # otherwise underdetermined conversion.
            height_zero = 0.0
            set_state(
                tracking_height_zero_mm=round(height_zero, 2),
                message=f"四绳张力跟踪启动：自动基准 {tension_floor}mA / 保护上限 {current_limit}mA，已将当前板面高度零点设为 {height_zero:.1f}mm；请手动移动小球",
            )

            start_timed_feedback_stream(connection, feedback_interval_ms, TIMED_FEEDBACK_INFO_CODE)
            feedback_interval_ms = int(getattr(connection, "_y42_feedback_interval_ms", feedback_interval_ms))
            feedback_hz_target = 1000.0 / max(1, feedback_interval_ms)
            timed_stream_stopped = False
            set_state(message=f"四绳张力跟踪启动：已开启手册 0x11/0x43 定时位置+相电流回传（{feedback_hz_target:.0f}Hz/台），自动基准 {tension_floor}mA / 保护上限 {current_limit}mA")
            shared_lock = threading.Lock()
            shared = {
                "positions": last_positions,
                "position_times": [time.perf_counter() for _ in MOTOR_IDS],
                "missed": [0 for _ in MOTOR_IDS],
                "position_reads": 0,
                "error": None,
                "batch_id": 0,
                "last_batch_at": 0.0,
                "batch_times": [0.0 for _ in MOTOR_IDS],
                "feedback_recoveries": 0,
                "current_targets": list(tracking_current_targets),
                "overcurrent_grace_until": time.perf_counter() + TRACKING_START_SAFETY_GRACE_SECONDS,
            }
            io_stop = threading.Event()
            serial_io_lock = threading.Lock()
            io_thread = threading.Thread(
                target=tracking_io_loop,
                args=(connection, current_limit, directions, shared, shared_lock, io_stop, serial_io_lock, calibration),
                name="y42-tracking-io",
                daemon=True,
            )
            io_thread.start()
            try:
                started = time.perf_counter()
                next_tick = started
                last_log = started
                last_ui = started
                frames = 0
                samples = 0
                filtered_estimate: tuple[float, float] | None = None
                filtered_height: float | None = None
                height_samples: list[float] = []
                contact_rezero_streak = 0
                lift_streak = 0
                down_streak = 0
                trace_generation = 0
                pen_up = False
                new_segment = True
                feedback_batch_seen = 0
                # The I/O worker can receive several complete 0x43 batches
                # between two 100 Hz UI/解算 ticks.  Keep the batch id together
                # with the newest timestamp so the displayed rate counts all
                # batches instead of counting only one observation per tick.
                feedback_rate_samples: list[tuple[int, float]] = []
                last_feedback_batch_at = 0.0
                next_threshold_refresh = started
                next_tracking_current_adjustment = started + 0.20
                tracking_balance_adjustments = 0
                while not STOP_EVENT.is_set():
                    with shared_lock:
                        io_error = shared.get("error")
                    if io_error:
                        raise RuntimeError("张力跟踪：" + str(io_error))
                    wait_tracking_deadline(next_tick)
                    if STOP_EVENT.is_set():
                        break
                    tick_now = time.perf_counter()
                    if tick_now >= next_threshold_refresh:
                        pen_up_threshold, pen_down_threshold = tracking_pen_thresholds()
                        next_threshold_refresh = tick_now + 0.10
                    with shared_lock:
                        io_error = shared.get("error")
                        positions = list(shared["positions"])
                        position_times = list(shared["position_times"])
                        position_reads = int(shared["position_reads"])
                        feedback_batch_id = int(shared.get("batch_id", 0))
                        feedback_batch_at = float(shared.get("last_batch_at", 0.0))
                        feedback_batch_span = float(shared.get("last_batch_span", 0.0))
                        feedback_recoveries = int(shared.get("feedback_recoveries", 0))
                    if io_error:
                        raise RuntimeError("张力跟踪：" + str(io_error))
                    if any(position is None for position in positions):
                        raise RuntimeError("张力跟踪：四台编码器位置反馈不完整")
                    last_positions_for_handoff = [float(position) for position in positions]

                    with STATE_LOCK:
                        current_generation = int(STATE.get("tracking_trace_generation", 0))
                    if current_generation != trace_generation:
                        # A live clear starts a fresh displayed trace without
                        # interrupting torque mode or the 100 Hz I/O worker.
                        trace_generation = current_generation
                        samples = 0
                        filtered_estimate = None
                        filtered_height = None
                        height_samples = []
                        lift_streak = 0
                        down_streak = 0
                        new_segment = True

                    position_span = max(position_times) - min(position_times) if position_times else float("inf")
                    position_age = time.perf_counter() - min(position_times) if position_times and min(position_times) > 0.0 else float("inf")
                    position_fresh = (
                        bool(position_times)
                        and min(position_times) > 0.0
                        and position_span <= TRACKING_POSITION_COHERENCE_SECONDS
                        and position_age <= TRACKING_POSITION_STALE_SECONDS
                    )
                    current_lengths = (
                        encoder_positions_to_lengths([float(position) for position in positions], calibration)
                        if position_fresh
                        else None
                    )
                    relative_pose = (
                        solve_relative_tracking_xy(
                            current_lengths,
                            initial_lengths,
                            start_xy,
                            calibration,
                            initial_xy=filtered_estimate or start_xy,
                        )
                        if current_lengths is not None
                        else None
                    )
                    workspace_xy = (
                        (float(relative_pose["x_mm"]), float(relative_pose["y_mm"]))
                        if relative_pose is not None
                        else None
                    )
                    xy_valid = bool(
                        workspace_xy is not None
                        and -TRACKING_FRAME_MARGIN_MM <= workspace_xy[0] <= workspace_width + TRACKING_FRAME_MARGIN_MM
                        and -TRACKING_FRAME_MARGIN_MM <= workspace_xy[1] <= workspace_height + TRACKING_FRAME_MARGIN_MM
                    )
                    height_valid = bool(xy_valid and current_lengths is not None)
                    current_global_x = workspace_xy[0] + workspace_left if workspace_xy is not None else None
                    current_global_y = workspace_xy[1] + workspace_bottom if workspace_xy is not None else None
                    current_z_squared = (
                        correct_planar_z_squared(
                            z_squared_estimates(current_lengths, current_global_x, current_global_y, calibration),
                            current_global_x,
                            current_global_y,
                            calibration,
                        )
                        if height_valid and current_global_x is not None and current_global_y is not None
                        else None
                    )
                    height_fit = relative_height_from_z_squared(
                        current_z_squared if height_valid else None,
                        baseline_z_squared if height_valid else None,
                        baseline_vertical_distance_mm=baseline_vertical_distance_mm,
                    )
                    relative_z_squared = height_fit["deltas"]
                    relative_height_squared = height_fit["median_z_squared"]
                    height_fit_spread_mm = float(height_fit["spread_mm"])
                    fit_consistent = bool(height_valid and height_fit["valid"])
                    raw_estimate = workspace_xy if xy_valid and workspace_xy is not None else None
                    raw_absolute_height = (
                        float(height_fit["height_mm"])
                        if fit_consistent and height_fit["height_mm"] is not None
                        else None
                    )
                    if feedback_batch_id > feedback_batch_seen and feedback_batch_at > 0.0:
                        feedback_batch_seen = feedback_batch_id
                        feedback_rate_samples.append((feedback_batch_id, feedback_batch_at))
                        cutoff = feedback_batch_at - TRACKING_FEEDBACK_HZ_WINDOW_SECONDS
                        feedback_rate_samples = [
                            sample for sample in feedback_rate_samples if sample[1] >= cutoff
                        ]
                        last_feedback_batch_at = feedback_batch_at
                    if not position_fresh and frames % 25 == 0:
                        append_process_log(
                            "tracking_incoherent_sample",
                            position_span_ms=round(position_span * 1000.0, 1),
                            max_allowed_ms=round(TRACKING_POSITION_COHERENCE_SECONDS * 1000.0, 1),
                            age_ms=round(position_age * 1000.0, 1),
                            max_age_ms=round(TRACKING_POSITION_STALE_SECONDS * 1000.0, 1),
                        )
                    if relative_pose is not None and not fit_consistent and frames % 25 == 0:
                        append_process_log(
                            "tracking_height_fit_warning",
                            raw_xy=[round(workspace_xy[0], 2), round(workspace_xy[1], 2)] if workspace_xy else None,
                            z_fit_spread_mm=round(height_fit_spread_mm, 2),
                            relative_xy_residual_mm=round(float(relative_pose["residual_rms_mm"]), 2),
                            frame=[round(frame_width, 2), round(frame_height, 2)],
                            height_used=False,
                        )
                    raw_height = max(0.0, raw_absolute_height - height_zero) if raw_absolute_height is not None else None
                    if raw_height is not None and raw_absolute_height is not None:
                        # When the ball is on the board, slowly follow the
                        # current four-rope z² values. This removes the small
                        # baseline shift caused by applying holding torque and
                        # by moving across a calibration surface with slightly
                        # different rope fits. Never adapt while lifted, so a
                        # real pen-up event cannot be learned away.
                        if (
                            not pen_up
                            and raw_height <= TRACKING_HEIGHT_NOISE_FLOOR_MM
                            and current_z_squared is not None
                            and height_fit["valid"]
                        ):
                            baseline_z_squared = [
                                baseline + TRACKING_HEIGHT_ZERO_ALPHA * (current - baseline)
                                for baseline, current in zip(baseline_z_squared, current_z_squared)
                            ]
                        # Only re-zero after a sustained, genuinely board-level
                        # contact. The former rule re-zeroed up to the whole
                        # pen-down band (5--6mm), which masked slow lifts and
                        # made the height indicator appear stuck around 5mm.
                        if not pen_up and raw_height <= TRACKING_HEIGHT_NOISE_FLOOR_MM:
                            contact_rezero_streak += 1
                            if contact_rezero_streak >= TRACKING_PEN_CONFIRM_FRAMES * 3:
                                previous_zero = height_zero
                                zero_delta = TRACKING_HEIGHT_ZERO_ALPHA * (raw_absolute_height - height_zero)
                                zero_delta = max(-0.08, min(0.08, zero_delta))
                                height_zero += zero_delta
                                zero_shift = height_zero - previous_zero
                                if abs(zero_shift) > 0.0001:
                                    height_samples = [max(0.0, sample - zero_shift) for sample in height_samples]
                                    if filtered_height is not None:
                                        filtered_height = max(0.0, filtered_height - zero_shift)
                                    raw_height = max(0.0, raw_absolute_height - height_zero)
                                    with STATE_LOCK:
                                        STATE["tracking_height_zero_mm"] = round(height_zero, 2)
                        else:
                            contact_rezero_streak = 0
                    if raw_height is not None:
                        height_samples.append(raw_height)
                        if len(height_samples) > TRACKING_HEIGHT_MEDIAN_WINDOW:
                            del height_samples[0]
                        robust_height = statistics.median(height_samples)
                        if filtered_height is None:
                            filtered_height = robust_height
                        else:
                            # A real hand lift cannot change the inferred
                            # height by tens of millimetres in one 10 ms tick.
                            # Bound the candidate before the low-pass filter so
                            # one bad but geometrically plausible sample cannot
                            # create a false 40–50 mm pen-up event.
                            bounded_height = max(
                                filtered_height - TRACKING_HEIGHT_MAX_STEP_MM,
                                min(filtered_height + TRACKING_HEIGHT_MAX_STEP_MM, robust_height),
                            )
                            filtered_height += TRACKING_HEIGHT_FILTER_ALPHA * (bounded_height - filtered_height)
                        if not pen_up and filtered_height >= pen_up_threshold:
                            lift_streak += 1
                            down_streak = 0
                            if lift_streak >= TRACKING_PEN_CONFIRM_FRAMES:
                                pen_up = True
                                new_segment = True
                                filtered_estimate = None
                                append_process_log(
                                    "tracking_pen_up",
                                    height_mm=round(filtered_height, 2),
                                    threshold_mm=pen_up_threshold,
                                    confirm_frames=lift_streak,
                                    z_fit_spread_mm=round(height_fit_spread_mm, 2) if math.isfinite(height_fit_spread_mm) else None,
                                )
                        elif pen_up and filtered_height <= pen_down_threshold:
                            down_streak += 1
                            lift_streak = 0
                            if down_streak >= TRACKING_PEN_CONFIRM_FRAMES:
                                pen_up = False
                                new_segment = True
                                append_process_log(
                                    "tracking_pen_down",
                                    height_mm=round(filtered_height, 2),
                                    threshold_mm=pen_down_threshold,
                                    confirm_frames=down_streak,
                                    z_fit_spread_mm=round(height_fit_spread_mm, 2) if math.isfinite(height_fit_spread_mm) else None,
                                )
                        else:
                            lift_streak = 0
                            down_streak = 0
                    else:
                        # An invalid asynchronous four-position snapshot is
                        # never evidence of a lift.  Require fresh, coherent
                        # samples before changing the writing state.
                        lift_streak = 0
                        down_streak = 0

                    estimate = None
                    if raw_estimate is not None:
                        filtered_estimate = smooth_tracking_point(raw_estimate, filtered_estimate)
                        estimate = filtered_estimate
                    if estimate is not None and not pen_up:
                        append_tracking_trace(estimate, new_segment=new_segment)
                        new_segment = False
                        samples += 1
                    with STATE_LOCK:
                        STATE["tracking_pen_state"] = {
                            "enabled": True,
                            "pen_up": pen_up,
                            "streak": max(lift_streak, down_streak),
                            "total_mm": 0.0,
                            "height_mm": round(filtered_height, 1) if filtered_height is not None else 0.0,
                            "threshold_mm": pen_up_threshold,
                            "down_threshold_mm": pen_down_threshold,
                        }
                    frames += 1
                    now = time.perf_counter()
                    with STATE_LOCK:
                        reference = copy.deepcopy(STATE.get("tracking_reference_xy"))
                        reference_error = None
                        if estimate is not None and isinstance(reference, (list, tuple)) and len(reference) == 2:
                            reference_error = math.hypot(estimate[0] - float(reference[0]), estimate[1] - float(reference[1]))
                        STATE["tracking_xy"] = [round(estimate[0], 2), round(estimate[1], 2)] if estimate is not None else None
                        STATE["tracking_relative_residual_mm"] = round(float(relative_pose["residual_rms_mm"]), 3) if relative_pose is not None else None
                        STATE["tracking_xyz"] = [round(estimate[0], 2), round(estimate[1], 2), round(filtered_height, 2), round(height_fit_spread_mm, 2)] if estimate is not None and filtered_height is not None and math.isfinite(height_fit_spread_mm) else None
                        STATE["tracking_height_mm"] = round(filtered_height, 2) if filtered_height is not None and raw_height is not None else None
                        STATE["tracking_height_raw_mm"] = round(raw_height, 2) if raw_height is not None else None
                        STATE["tracking_height_confidence"] = round(float(height_fit["confidence"]), 3)
                        STATE["tracking_height_z2_delta"] = [round(float(value), 2) for value in relative_z_squared] if relative_z_squared is not None else None
                        STATE["tracking_reference_error_mm"] = round(reference_error, 2) if reference_error is not None else None
                        STATE["tracking_samples"] = samples
                        STATE["tracking_frames"] = frames
                        STATE["tracking_position_reads"] = position_reads
                        feedback_elapsed = (
                            feedback_rate_samples[-1][1] - feedback_rate_samples[0][1]
                            if len(feedback_rate_samples) >= 2
                            else 0.0
                        )
                        feedback_hz = (
                            (feedback_rate_samples[-1][0] - feedback_rate_samples[0][0]) / feedback_elapsed
                            if feedback_elapsed > 0.001
                            else 0.0
                        )
                        STATE["tracking_feedback_hz_actual"] = round(feedback_hz, 1)
                        STATE["tracking_feedback_batches"] = feedback_batch_seen
                        STATE["tracking_feedback_span_ms"] = round(feedback_batch_span * 1000.0, 1)
                        STATE["tracking_feedback_age_ms"] = round(max(0.0, now - last_feedback_batch_at) * 1000.0, 1) if last_feedback_batch_at else None
                        STATE["tracking_feedback_recoveries"] = feedback_recoveries
                        STATE["tracking_z_fit_spread_mm"] = round(float(height_fit_spread_mm), 2) if math.isfinite(height_fit_spread_mm) else None
                        live_telemetry = copy.deepcopy(STATE.get("telemetry", {}))
                    if now >= next_tracking_current_adjustment:
                        balance_xy = raw_estimate or filtered_estimate or start_xy
                        desired_tracking_currents, tracking_force_balance = balanced_torque_current_targets(
                            balance_xy[0],
                            balance_xy[1],
                            tension_floor,
                            calibration,
                            maximum_current_ma=min(TRACKING_BALANCE_MAX_CURRENT_MA, current_limit),
                        )
                        tracking_current_targets, changes = adjust_tracking_current_targets(
                            tracking_current_targets, desired_tracking_currents
                        )
                        if changes:
                            # One aggregate frame changes all four torques at the
                            # same bus instant.  Four sequential C5 writes made
                            # the ball twitch toward the motor written first.
                            # Do not wait for ACKs while the 0x43 stream is live.
                            with serial_io_lock:
                                send_fast(
                                    connection,
                                    four_motor_torque_frame(tracking_current_targets),
                                )
                            tracking_balance_adjustments += len(changes)
                            append_process_log(
                                "tracking_tension_balance",
                                requested_limit_ma=current_limit,
                                automatic_floor_ma=tension_floor,
                                xy_mm=[round(balance_xy[0], 3), round(balance_xy[1], 3)],
                                geometry_balance_ok=bool(tracking_force_balance.get("ok")),
                                desired_currents=list(desired_tracking_currents),
                                measured_currents=[
                                    live_telemetry.get(str(address), {}).get("phase_current")
                                    for address in MOTOR_IDS
                                ],
                                current_targets=list(tracking_current_targets),
                                changes=changes,
                            )
                        next_tracking_current_adjustment += 0.10
                        while next_tracking_current_adjustment <= now:
                            next_tracking_current_adjustment += 0.10
                        with STATE_LOCK:
                            STATE["tracking_current_targets"] = list(tracking_current_targets)
                            STATE["tracking_balance_adjustments"] = tracking_balance_adjustments
                        with shared_lock:
                            shared["current_targets"] = list(tracking_current_targets)
                    if now - last_log >= TRACKING_LOG_INTERVAL:
                        actual_hz = frames / max(0.001, now - started)
                        append_process_log(
                            "tracking_sample",
                            current_limit_ma=current_limit,
                            automatic_floor_ma=tension_floor,
                            directions=list(directions),
                            positions=[round(float(position), 2) for position in positions],
                            relative_rope_lengths_mm=calibration_relative_rope_lengths(positions, calibration),
                            raw_xy=[round(raw_estimate[0], 2), round(raw_estimate[1], 2)] if raw_estimate is not None else None,
                            raw_absolute_height_mm=round(raw_absolute_height, 2) if raw_absolute_height is not None else None,
                            raw_height_mm=round(raw_height, 2) if raw_height is not None else None,
                            height_zero_mm=round(height_zero, 2),
                            height_mm=round(filtered_height, 2) if filtered_height is not None else None,
                            z_fit_spread_mm=round(height_fit_spread_mm, 2) if math.isfinite(height_fit_spread_mm) else None,
                            xy=[round(estimate[0], 2), round(estimate[1], 2)] if estimate is not None else None,
                            reference_xy=reference,
                            reference_error_mm=round(reference_error, 2) if reference_error is not None else None,
                            phase_current=[live_telemetry.get(str(address), {}).get("phase_current") for address in MOTOR_IDS],
                            rpm=[live_telemetry.get(str(address), {}).get("rpm") for address in MOTOR_IDS],
                            position_reads=position_reads,
                            position_span_ms=round(position_span * 1000.0, 1),
                            position_coherent=position_fresh,
                            feedback_batch_id=feedback_batch_seen,
                            feedback_hz=round(feedback_hz, 2),
                            feedback_batch_span_ms=round(feedback_batch_span * 1000.0, 1),
                            feedback_age_ms=round(max(0.0, now - last_feedback_batch_at) * 1000.0, 1) if last_feedback_batch_at else None,
                            hz=round(actual_hz, 2),
                        )
                        last_log = now
                    if now - last_ui >= 0.10:
                        actual_hz = frames / max(0.001, now - started)
                        phase_current = [live_telemetry.get(str(address), {}).get("phase_current") for address in MOTOR_IDS]
                        current_text = "/".join(str(value) if value is not None else "?" for value in phase_current)
                        target_text = "/".join(str(value) for value in tracking_current_targets)
                        xy_text = "等待坐标解算" if estimate is None else f"({estimate[0]:.1f}, {estimate[1]:.1f})mm"
                        pen_text = "抬笔，暂停记录" if pen_up else "落笔，正在记录"
                        height_text = "高度待测" if filtered_height is None else f"高度 {filtered_height:.1f}mm"
                        set_state(
                            tracking_hz_actual=round(actual_hz, 1),
                            message=f"四绳跟踪中 · {pen_text} · {height_text} · 实测电流 {current_text}mA / 各台目标 {target_text}mA · 解算显示 {TRACKING_HZ:.0f}Hz / 原始完整位置反馈 {feedback_hz:.1f}Hz · 自动恢复 {feedback_recoveries} 次 · 阈值 抬笔≥{pen_up_threshold:.1f}mm、落笔≤{pen_down_threshold:.1f}mm · 反算位置 {xy_text}",
                        )
                        last_ui = now
                    next_tick += TRACKING_INTERVAL
                    while next_tick <= time.perf_counter():
                        next_tick += TRACKING_INTERVAL
            finally:
                io_stop.set()
                io_thread.join(timeout=2.0)
                timed_stream_stopped = stop_timed_position_stream(connection)
                with shared_lock:
                    handoff_io_error = shared.get("error")
                if (
                    SOFT_STOP_EVENT.is_set()
                    and timed_stream_stopped
                    and not handoff_io_error
                ):
                    soft_handoff = restore_four_position_force_session_hold(
                        connection,
                        calibration,
                        last_positions_for_handoff,
                    )
    except Exception as exc:
        error = str(exc)
        append_process_log("tracking_error", error=error)
        set_state(control_unlocked=False, auto="error", message="张力跟踪已停止：" + error + "；正在自动重连并失能四台电机")
    finally:
        if not timed_stream_stopped:
            try:
                with SERIAL_LOCK, direct.open_serial(current_port(), current_baud()) as recovery_connection:
                    timed_stream_stopped = stop_timed_position_stream(recovery_connection)
            except Exception:
                timed_stream_stopped = False
        soft_stop_complete = bool(
            SOFT_STOP_EVENT.is_set()
            and not error
            and timed_stream_stopped
            and isinstance(soft_handoff, dict)
        )
        recovery = (
            {"ok": True, "error": ""}
            if soft_stop_complete
            else disable_all_with_reconnect(current_port(), current_baud(), announce=bool(error or STOP_EVENT.is_set()))
        )
        if not recovery["ok"] or not timed_stream_stopped:
            detail = recovery.get("error", "定时反馈流停止未全部确认") if not recovery["ok"] else "定时反馈流停止未全部确认"
            set_state(
                control_unlocked=False,
                auto="error",
                message="张力跟踪结束，但未能确认定时回传/四台失能；请立即切断电机动力或使用硬件急停（" + detail + "）",
            )
        elif soft_stop_complete:
            set_state(
                auto="idle",
                message=(
                    "张力跟踪已柔和结束；当前位置无跳变交接为四电机位置闭环，"
                    f"自应力预紧 {float(soft_handoff['force_contraction_mm']):.2f}mm，"
                    "本次校准继续有效"
                ),
            )
        elif STOP_EVENT.is_set() and not error:
            set_state(auto="idle", message="张力跟踪已急停，四台电机已自动重连确认失能；本次校准已作废")
        elif error:
            set_state(control_unlocked=False, auto="error", message="张力跟踪已停止：" + error + "；已自动重连确认四台失能")
        set_state(
            tracking_pen_state={
                "enabled": False,
                "pen_up": False,
                "streak": 0,
                "total_mm": 0.0,
                "height_mm": 0.0,
                "threshold_mm": pen_up_threshold,
                "down_threshold_mm": pen_down_threshold,
            }
        )
        if timer_resolution:
            set_high_resolution_timer(False)
        STOP_EVENT.clear()
        SOFT_STOP_EVENT.clear()


def planar_snake_path(calibration: dict) -> tuple[list[tuple[float, float]], tuple[float, float, float, float]]:
    """Build a bounded in-plane rectangle/serpentine path for diagnostics."""
    _, _, width, height = drawable_workspace(calibration)
    if width < 60.0 or height < 60.0:
        raise RuntimeError("平面蛇形自测需要至少 60×60mm 的有效工作区")
    margin_x = min(PLANAR_SNAKE_TEST_MARGIN_MM, width * 0.20)
    margin_y = min(PLANAR_SNAKE_TEST_MARGIN_MM, height * 0.20)
    # Keep a small 4 mm boundary clearance and centre the test on the STEP/user
    # frame centre (55,74).  The exact 110×148 corner layout supersedes the old
    # inferred 150 mm square.
    draw_width = width - 2.0 * margin_x
    draw_height = height - 2.0 * margin_y
    center_x = MECHANISM_CENTER_X_MM
    center_y = MECHANISM_CENTER_Y_MM
    x0 = max(0.0, min(width - draw_width, center_x - draw_width / 2.0))
    x1 = x0 + draw_width
    y0 = max(0.0, min(height - draw_height, center_y - draw_height / 2.0))
    y1 = y0 + draw_height
    rows = max(4, PLANAR_SNAKE_TEST_ROWS)
    path: list[tuple[float, float]] = []
    for row in range(rows):
        fraction = row / max(1, rows - 1)
        y = y0 + (y1 - y0) * fraction
        path.extend(((x0, y), (x1, y)) if row % 2 == 0 else ((x1, y), (x0, y)))
    # The diagnostic must exercise the full rectangle but should not inject an
    # instantaneous 90-degree velocity reversal that is unrelated to height
    # solving.  One Chaikin pass keeps every point in bounds and rounds only
    # the reversals; the normal user-drawn path remains untouched.
    # Keep the snake's original straight rows and exact turning vertices.
    return path, (x0, y0, x1, y1)


def _percentile(values: list[float], fraction: float) -> float | None:
    if not values:
        return None
    ordered = sorted(float(value) for value in values)
    index = min(len(ordered) - 1, max(0, int(round((len(ordered) - 1) * fraction))))
    return ordered[index]


class BoundedReservoir:
    """Keep bounded-memory statistics while every raw sample stays on disk."""

    __slots__ = ("capacity", "seen", "values", "random")

    def __init__(self, capacity: int = 2048) -> None:
        self.capacity = max(16, int(capacity))
        self.seen = 0
        self.values: list[float] = []
        self.random = random.Random(0x42)

    def add(self, value: float) -> None:
        value = float(value)
        if not math.isfinite(value):
            return
        self.seen += 1
        if len(self.values) < self.capacity:
            self.values.append(value)
            return
        slot = self.random.randrange(self.seen)
        if slot < self.capacity:
            self.values[slot] = value


def planar_snake_test_worker(
    current: int = PLANAR_SNAKE_TEST_CURRENT,
    tension_target_current: int | None = None,
    passive_index_override: int | None = None,
) -> None:
    """Exercise the real motion/feedback path while the ball stays on the board.

    This is a bounded 3+1 controller acceptance run: three motors command the
    rigid platform x/y/yaw pose, one motor supplies pull torque, and that fourth
    encoder is the independent closure channel.  Any stale feedback, poor
    closure, protection flag or over-current stops the test; the outer recovery
    path always disables every motor.
    """
    error: str | None = None
    stopped = False
    timer_resolution = False
    timed_stream_active = False
    summary: dict = {}
    # Raw samples are streamed to the JSONL process log immediately. Keep only
    # a short tail for the UI/error summary so a long real test cannot grow the
    # worker's memory with one dict per feedback frame.
    sample_records: list[dict] = []
    sample_count = 0
    valid_pose_count = 0
    yaw_values = BoundedReservoir()
    closure_rms_values = BoundedReservoir()
    closure_max_values = BoundedReservoir()
    redundant_residual_values = BoundedReservoir()
    xy_errors = BoundedReservoir()
    last_feedback_diagnostics: dict = {}
    last_target_xy: tuple[float, float] | None = None
    frame_count = 0
    try:
        calibration = calibration_data()
        if not calibration.get("valid"):
            raise RuntimeError("请先完成四角几何校准，才能进行平面蛇形自测")
        model_context = calibration_model_context(calibration)
        current = max(300, min(OPERATING_CURRENT_MAX_MA, int(current)))
        target_current = int(
            tension_target_current
            if tension_target_current is not None
            else calibration.get("grid_tension_target_current_ma", PLANAR_SNAKE_TENSION_TARGET_CURRENT)
        )
        if not GRID_TENSION_MIN_CURRENT_MA <= target_current <= GRID_TENSION_MAX_CURRENT_MA:
            raise RuntimeError(
                f"平面蛇形张力下限必须在 {GRID_TENSION_MIN_CURRENT_MA}..{GRID_TENSION_MAX_CURRENT_MA}mA"
            )
        grid_map = calibration.get("grid_compensation")
        grid_map_enabled = bool(
            isinstance(grid_map, dict)
            and grid_map.get("valid") is True
            and grid_map.get("enabled") is True
            and validate_grid_compensation(grid_map)[0]
        )
        workspace_left, workspace_bottom, workspace_width, workspace_height = drawable_workspace(calibration)
        path, bounds = planar_snake_path(calibration)
        path, cumulative = path_with_cumulative(path)
        passive_choice = select_passive_motor_for_path(path, calibration, target_current)
        if not passive_choice.get("ok"):
            raise RuntimeError("平面蛇形自测：" + str(passive_choice.get("reason") or "无法选择张力电机"))
        if passive_index_override is not None:
            requested_passive = int(passive_index_override)
            candidate = next(
                (
                    item
                    for item in passive_choice.get("candidates", [])
                    if int(item.get("passive_index", -1)) == requested_passive
                ),
                None,
            )
            if candidate is None or float(candidate.get("minimum_observability_det", 0.0)) < HYBRID_MIN_OBSERVABILITY_DET:
                raise RuntimeError(f"平面蛇形自测：指定 M{requested_passive + 1} 后三绳存在奇异区")
            passive_choice = {"ok": True, **candidate, "candidates": passive_choice.get("candidates", [])}
        passive_index = int(passive_choice["passive_index"])
        active_indices = tuple(index for index in range(len(MOTOR_IDS)) if index != passive_index)
        path_length = cumulative[-1]
        duration = path_length / PLANAR_SNAKE_TEST_SPEED_MM_S
        if duration > PLANAR_SNAKE_TEST_MAX_SECONDS:
            raise RuntimeError(f"蛇形自测预计 {duration:.1f}s，超过安全上限 {PLANAR_SNAKE_TEST_MAX_SECONDS:.0f}s")
        set_state(
            auto="planar-snake-test",
            repeat=False,
            planar_snake_test={
                "status": "preparing",
                "current_ma": current,
                "tension_target_ma": target_current,
                "workspace": [round(value, 2) for value in bounds],
                "speed_mm_s": PLANAR_SNAKE_TEST_SPEED_MM_S,
                "controller": "3-position-1-torque",
                "passive_motor": MOTOR_IDS[passive_index],
            },
            message=(
                f"平面刚体3+1验收准备中：M{MOTOR_IDS[passive_index]}恒张力，其余三台控制 x/y/yaw，"
                f"{PLANAR_SNAKE_TEST_SPEED_MM_S:.0f}mm/s，结束后四台自动失能"
            ),
        )
        append_process_log(
            "planar_snake_test_start",
            current_ma=current,
            speed_mm_s=PLANAR_SNAKE_TEST_SPEED_MM_S,
            workspace=[round(value, 2) for value in bounds],
            path=[list(point) for point in path],
            duration_s=round(duration, 3),
            controller="3-position-1-torque",
            passive_motor=MOTOR_IDS[passive_index],
            passive_choice=passive_choice,
            baud=current_baud(),
            model_family_key=model_context.get("model_family_key"),
            position_reference_deg=model_context.get("position_reference_deg"),
        )
        timer_resolution = set_high_resolution_timer(True)
        with SERIAL_LOCK, direct.open_serial(current_port(), current_baud()) as connection:
            feedback_interval_ms = motion_feedback_interval_ms(getattr(connection, "baudrate", None))
            feedback_hz_target = 1000.0 / feedback_interval_ms
            firmware = [read_firmware_status(connection, address) for address in MOTOR_IDS]
            non_x = [
                f"M{item['id']}={item.get('firmware') or '无可靠回包'}"
                for item in firmware
                if item.get("firmware") != "X"
            ]
            if non_x:
                raise RuntimeError("平面蛇形自测已取消：实际固件不是全 X（" + "、".join(non_x) + "）")
            stopped_results = stop_all(connection)
            if not all(item.get("accepted") for item in stopped_results):
                raise RuntimeError("平面蛇形自测启动前四台急停未全部收到 ACK")
            for index, address in enumerate(MOTOR_IDS):
                enabled, _, reply = enable_address(connection, address)
                if not enabled:
                    detail = direct.hex_bytes(reply) if reply else "超时无回包"
                    raise RuntimeError(f"平面蛇形自测：M{index + 1} 使能失败，RX={detail}")
            initial_values = read_all_reliable(connection, attempts=2)
            safety = safety_error(initial_values, current_limit=current)
            if safety:
                raise RuntimeError("平面蛇形自测启动检查：" + safety)
            current_positions = [item.position for item in initial_values]
            if any(position is None for position in current_positions):
                raise RuntimeError("平面蛇形自测：启动时四台位置反馈不完整")
            start_xy = path[0]
            start_targets = grid_motor_positions_at(start_xy[0], start_xy[1], calibration)
            move_to_start_smooth(
                connection,
                [float(position) for position in current_positions],
                start_targets,
                "平面蛇形自测起点",
                current=current,
            )
            stream_buffer = bytearray()
            feedback_position_history: dict[int, float] = {}
            parser_stats: dict[str, int] = {}
            stream_positions: list[float | None] = [None for _ in MOTOR_IDS]
            stream_currents: list[int | None] = [None for _ in MOTOR_IDS]
            stream_times = [0.0 for _ in MOTOR_IDS]
            stream_coherence_window = timed_feedback_coherence_window(getattr(connection, "baudrate", None))
            stream_assembler = FourMotorFeedbackAssembler(stream_coherence_window)
            complete_snapshots: list[tuple[tuple[float, ...], tuple[int | None, ...], float, float]] = []
            last_snapshot_at = 0.0
            # Do not throw away faster complete snapshots. A half-period guard
            # only prevents duplicate timestamps from being processed twice
            # when USB delivers two reads back-to-back.
            snapshot_min_period = max(0.001, feedback_interval_ms / 2000.0)

            def consume_feedback(records: list[TimedFeedbackRecord]) -> None:
                nonlocal last_feedback_diagnostics, last_snapshot_at
                for record in records:
                    if record.address not in MOTOR_IDS:
                        continue
                    index = MOTOR_IDS.index(record.address)
                    last_feedback_diagnostics = {
                        "id": record.address,
                        "position": round(float(record.position), 2),
                        "phase_current_ma": record.phase_current,
                        "rpm": record.rpm,
                        "temperature": record.temperature,
                        "flags": record.flags,
                        "flags_text": direct.decode_flags(record.flags) if record.flags is not None else None,
                    }
                    if record.phase_current is not None and abs(float(record.phase_current)) > overcurrent_trip_limit(current):
                        raise RuntimeError(
                            f"平面蛇形自测：M{index + 1} 电流 {abs(float(record.phase_current)):.0f}mA 超过安全阈值 "
                            f"{overcurrent_trip_limit(current)}mA"
                        )
                    if record.temperature is not None and record.temperature >= HARD_TEMPERATURE:
                        raise RuntimeError(f"平面蛇形自测：M{index + 1} 温度达到 {record.temperature}°C")
                    if record.flags is not None and record.flags & 0x08:
                        raise RuntimeError(f"平面蛇形自测：M{index + 1} 触发驱动器保护")
                    stream_positions[index] = float(record.position)
                    stream_currents[index] = record.phase_current
                    stream_times[index] = record.sampled_at
                    with STATE_LOCK:
                        telemetry = STATE["telemetry"].setdefault(str(record.address), {"id": record.address})
                        telemetry.update(
                            {
                                "position": record.position,
                                "phase_current": record.phase_current,
                                "voltage": record.voltage,
                                "bus_current": record.bus_current,
                                "rpm": record.rpm,
                                "temperature": record.temperature,
                                "flags": record.flags,
                                "flags_text": direct.decode_flags(record.flags) if record.flags is not None else None,
                                "online": True,
                            }
                        )
                    # Use only a complete four-ID cycle. A dropped frame must
                    # create one missing diagnostic sample, never a fabricated
                    # point assembled from adjacent cycles.
                    snapshot = stream_assembler.add(record)
                    if snapshot is not None:
                        by_address = {item.address: item for item in snapshot}
                        newest = max(item.sampled_at for item in snapshot)
                        span = newest - min(item.sampled_at for item in snapshot)
                        if (
                            newest > last_snapshot_at
                            and newest - last_snapshot_at >= snapshot_min_period
                            and span <= stream_coherence_window
                        ):
                            aligned_positions = time_aligned_feedback_positions(snapshot)
                            complete_snapshots.append(
                                (
                                    aligned_positions,
                                    tuple(by_address[motor_id].phase_current for motor_id in MOTOR_IDS),
                                    newest,
                                    span,
                                )
                            )
                            last_snapshot_at = newest

            start_timed_feedback_stream(connection, feedback_interval_ms, TIMED_FEEDBACK_INFO_CODE)
            feedback_interval_ms = int(getattr(connection, "_y42_feedback_interval_ms", feedback_interval_ms))
            feedback_hz_target = 1000.0 / max(1, feedback_interval_ms)
            timed_stream_active = True
            # Engage the redundant cable gently and let it take up slack before
            # the path starts.  The commanded equilibrium tension is ramped only
            # after this low-force dwell; the 50 mA hardware handshake showed
            # that a previously position-held cable may contain substantial slack.
            passive_current = int(min(current, HYBRID_PASSIVE_ENGAGE_CURRENT_MA))
            baseline_deadline = time.perf_counter() + PLANAR_SNAKE_TEST_SETTLE_SECONDS
            baseline_next_command = time.perf_counter()
            baseline_samples: list[tuple[tuple[float, ...], tuple[int | None, ...], float, float]] = []
            baseline_index = 0
            while time.perf_counter() < baseline_deadline:
                if STOP_EVENT.is_set():
                    stopped = True
                    raise RuntimeError("用户急停")
                now = time.perf_counter()
                if now >= baseline_next_command:
                    send_fast(
                        connection,
                        three_position_one_torque_frame(
                            start_targets,
                            passive_index,
                            passive_current,
                            [25.0] * len(MOTOR_IDS),
                            [current] * len(MOTOR_IDS),
                        ),
                    )
                    baseline_next_command += TRAJECTORY_INTERVAL
                consume_feedback(
                    read_timed_position_records(
                        connection,
                        stream_buffer,
                        timeout=0.005,
                        position_history=feedback_position_history,
                        parser_stats=parser_stats,
                    )
                )
                if baseline_index < len(complete_snapshots):
                    baseline_samples.extend(complete_snapshots[baseline_index:])
                    baseline_index = len(complete_snapshots)
                time.sleep(0.001)
            if len(baseline_samples) < 3:
                raise RuntimeError(f"平面蛇形自测：建立板面零点时完整反馈不足（{len(baseline_samples)}组）")
            baseline_positions = [
                float(statistics.median(sample[0][index] for sample in baseline_samples))
                for index in range(len(MOTOR_IDS))
            ]
            baseline_pose = motor_positions_to_planar_pose(
                baseline_positions,
                calibration,
                active_indices=active_indices,
                initial_pose=(start_xy[0], start_xy[1], PLATFORM_COMMAND_YAW_DEG),
            )
            if baseline_pose is None:
                raise RuntimeError("平面蛇形自测：3+1 板面位姿无法解算")
            append_process_log(
                "planar_snake_test_baseline",
                samples=len(baseline_samples),
                positions=[round(value, 2) for value in baseline_positions],
                planar_pose={
                    key: round(float(baseline_pose[key]), 4)
                    for key in ("x_mm", "y_mm", "yaw_deg", "closure_rms_mm", "closure_max_mm")
                },
                passive_motor=MOTOR_IDS[passive_index],
                passive_current_ma=passive_current,
            )
            set_state(
                planar_snake_test={
                    "status": "running",
                    "current_ma": current,
                    "workspace": [round(value, 2) for value in bounds],
                    "speed_mm_s": PLANAR_SNAKE_TEST_SPEED_MM_S,
                    "samples": 0,
                    "controller": "3-position-1-torque",
                    "passive_motor": MOTOR_IDS[passive_index],
                },
                message=f"平面刚体3+1自测进行中：M{MOTOR_IDS[passive_index]}恒张力并独立校验闭合误差",
            )
            processed_index = baseline_index
            last_feedback_at = time.perf_counter()
            feedback_recoveries = 0
            last_planar_pose: dict | None = baseline_pose
            passive_current_command = passive_current
            started = time.perf_counter()
            next_tick = started
            next_log = started
            def process_new_snapshots(target_xy: tuple[float, float]) -> None:
                nonlocal processed_index, last_feedback_at, sample_count, valid_pose_count, last_planar_pose
                while processed_index < len(complete_snapshots):
                    positions, currents, sampled_at, span = complete_snapshots[processed_index]
                    processed_index += 1
                    last_feedback_at = sampled_at
                    pose = motor_positions_to_planar_pose(
                        list(positions),
                        calibration,
                        active_indices=active_indices,
                        initial_pose=last_planar_pose,
                    )
                    if pose is None:
                        continue
                    last_planar_pose = pose
                    xy = (
                        float(pose["x_mm"]) - workspace_left,
                        float(pose["y_mm"]) - workspace_bottom,
                    )
                    xy_error = math.hypot(xy[0] - target_xy[0], xy[1] - target_xy[1])
                    xy_errors.add(xy_error)
                    yaw_error = abs(float(pose["yaw_deg"]) - PLATFORM_COMMAND_YAW_DEG)
                    closure_rms = float(pose["closure_rms_mm"])
                    closure_max = float(pose["closure_max_mm"])
                    redundant = pose.get("redundant_residuals_mm") or []
                    redundant_residual = float(redundant[0]) if redundant else 0.0
                    pose_valid = bool(
                        pose.get("converged")
                        and float(pose.get("observability_det", 0.0)) >= HYBRID_MIN_OBSERVABILITY_DET
                        and math.isfinite(xy_error + yaw_error + closure_rms + closure_max + redundant_residual)
                    )
                    if pose_valid:
                        valid_pose_count += 1
                        yaw_values.add(yaw_error)
                        closure_rms_values.add(closure_rms)
                        closure_max_values.add(closure_max)
                        redundant_residual_values.add(abs(redundant_residual))
                    sample = {
                            "t_s": round(max(0.0, sampled_at - started), 4),
                            "target_xy": [round(target_xy[0], 2), round(target_xy[1], 2)],
                            "positions_deg": [round(float(value), 2) for value in positions],
                            "relative_rope_lengths_mm": calibration_relative_rope_lengths(positions, calibration),
                            "xy": [round(xy[0], 2), round(xy[1], 2)],
                            "yaw_deg": round(float(pose["yaw_deg"]), 4),
                            "closure_rms_mm": round(closure_rms, 4),
                            "closure_max_mm": round(closure_max, 4),
                            "redundant_residual_mm": round(redundant_residual, 4),
                            "pose_valid": pose_valid,
                            "observability_det": round(float(pose.get("observability_det", 0.0)), 6),
                            "xy_error_mm": round(xy_error, 3),
                            "phase_current_ma": list(currents),
                            "passive_motor": MOTOR_IDS[passive_index],
                            "passive_current_command_ma": passive_current_command,
                            "feedback_span_ms": round(span * 1000.0, 3),
                        }
                    sample_count += 1
                    sample_records.append(sample)
                    if len(sample_records) > 256:
                        del sample_records[:-256]
                    append_process_log("planar_snake_test_sample", **sample)

            while time.perf_counter() - started < duration:
                if STOP_EVENT.is_set():
                    stopped = True
                    raise RuntimeError("用户急停")
                now = time.perf_counter()
                if now < next_tick:
                    time.sleep(min(0.002, next_tick - now))
                    continue
                elapsed = now - started
                phase = min(1.0, elapsed / max(0.001, duration))
                next_phase = min(1.0, (elapsed + TRAJECTORY_INTERVAL) / max(0.001, duration))
                x, y = sample_cumulative_path(path, cumulative, phase)
                next_x, next_y = sample_cumulative_path(path, cumulative, next_phase)
                force_balance = equilibrium_current_targets(next_x, next_y, target_current, calibration)
                force_target_currents = force_balance.get("target_currents_ma") if force_balance.get("ok") else None
                desired_passive_current = (
                    float(force_target_currents[passive_index])
                    if isinstance(force_target_currents, list)
                    else float(target_current)
                )
                desired_passive_current = min(
                    float(current),
                    float(HYBRID_PASSIVE_TORQUE_MAX_CURRENT_MA),
                    max(float(target_current), desired_passive_current),
                )
                # Limit torque changes to 20 mA/tick.  The passive cable remains
                # taut without injecting a step disturbance into the three pose
                # loops as the path crosses the centre.
                passive_current_command = int(
                    round(
                        passive_current_command
                        + max(-20.0, min(20.0, desired_passive_current - passive_current_command))
                    )
                )
                last_target_xy = (x, y)
                send_fast(
                    connection,
                    hybrid_trajectory_frame(
                        x,
                        y,
                        next_x,
                        next_y,
                        TRAJECTORY_INTERVAL,
                        passive_index,
                        passive_current_command,
                        [current] * len(MOTOR_IDS),
                        calibration,
                    ),
                )
                frame_count += 1
                consume_feedback(
                    read_timed_position_records(
                        connection,
                        stream_buffer,
                        timeout=0.0,
                        position_history=feedback_position_history,
                        parser_stats=parser_stats,
                    )
                )
                process_new_snapshots((x, y))
                if processed_index > 256:
                    del complete_snapshots[:processed_index]
                    processed_index = 0
                if time.perf_counter() - last_feedback_at > TRACKING_POSITION_FAIL_SECONDS:
                    if feedback_recoveries < 3:
                        stop_timed_position_stream(connection)
                        stream_buffer.clear()
                        feedback_position_history.clear()
                        stream_positions[:] = [None for _ in MOTOR_IDS]
                        stream_currents[:] = [None for _ in MOTOR_IDS]
                        stream_times[:] = [0.0 for _ in MOTOR_IDS]
                        stream_assembler = FourMotorFeedbackAssembler(stream_coherence_window)
                        last_snapshot_at = 0.0
                        start_timed_feedback_stream(connection, feedback_interval_ms, TIMED_FEEDBACK_INFO_CODE)
                        feedback_interval_ms = int(getattr(connection, "_y42_feedback_interval_ms", feedback_interval_ms))
                        feedback_hz_target = 1000.0 / max(1, feedback_interval_ms)
                        feedback_recoveries += 1
                        last_feedback_at = time.perf_counter()
                        append_process_log(
                            "planar_snake_feedback_recovery",
                            recovery=feedback_recoveries,
                            elapsed_s=round(elapsed, 3),
                            parser_stats=dict(parser_stats),
                        )
                        set_state(message=f"平面蛇形自测：反馈窗口中断，已自动重启反馈流（第 {feedback_recoveries} 次）")
                        next_tick += TRAJECTORY_INTERVAL
                        continue
                    raise RuntimeError("平面蛇形自测：反馈流连续恢复失败")
                if time.perf_counter() >= next_log:
                    latest_yaw = yaw_values.values[-1] if yaw_values.values else None
                    latest_closure = closure_rms_values.values[-1] if closure_rms_values.values else None
                    set_state(
                        planar_snake_test={
                            "status": "running",
                            "current_ma": current,
                            "workspace": [round(value, 2) for value in bounds],
                            "speed_mm_s": PLANAR_SNAKE_TEST_SPEED_MM_S,
                            "samples": sample_count,
                            "frames": frame_count,
                            "controller": "3-position-1-torque",
                            "passive_motor": MOTOR_IDS[passive_index],
                            "yaw_abs_deg": round(latest_yaw, 3) if latest_yaw is not None else None,
                            "closure_rms_mm": round(latest_closure, 3) if latest_closure is not None else None,
                        },
                        message=(
                            f"平面蛇形自测中 · {len(sample_records)}组反馈 · "
                            f"|yaw| {latest_yaw:.2f}° / closure {latest_closure:.3f}mm"
                            if latest_yaw is not None and latest_closure is not None
                            else "平面蛇形自测中 · 等待完整四电机反馈"
                        ),
                    )
                    next_log += PLANAR_SNAKE_TEST_LOG_INTERVAL
                    while next_log <= time.perf_counter():
                        next_log += PLANAR_SNAKE_TEST_LOG_INTERVAL
                next_tick += TRAJECTORY_INTERVAL
                while next_tick <= time.perf_counter():
                    next_tick += TRAJECTORY_INTERVAL

            final_targets = grid_motor_positions_at(path[-1][0], path[-1][1], calibration)
            hold_started = time.perf_counter()
            next_hold = hold_started
            while time.perf_counter() - hold_started < 0.30:
                if STOP_EVENT.is_set():
                    stopped = True
                    raise RuntimeError("用户急停")
                now = time.perf_counter()
                if now < next_hold:
                    time.sleep(min(0.002, next_hold - now))
                    continue
                send_fast(
                    connection,
                    three_position_one_torque_frame(
                        final_targets,
                        passive_index,
                        passive_current_command,
                        [25.0] * len(MOTOR_IDS),
                        [current] * len(MOTOR_IDS),
                    ),
                )
                consume_feedback(
                    read_timed_position_records(
                        connection,
                        stream_buffer,
                        timeout=0.0,
                        position_history=feedback_position_history,
                        parser_stats=parser_stats,
                    )
                )
                process_new_snapshots(path[-1])
                if processed_index > 256:
                    del complete_snapshots[:processed_index]
                    processed_index = 0
                next_hold += TRAJECTORY_INTERVAL
            consume_feedback(
                read_timed_position_records(
                    connection,
                    stream_buffer,
                    timeout=0.0,
                    position_history=feedback_position_history,
                    parser_stats=parser_stats,
                )
            )
            process_new_snapshots(path[-1])
            if not stop_timed_position_stream(connection):
                raise RuntimeError("平面蛇形自测：定时反馈流停止未确认")
            timed_stream_active = False

        valid_count = valid_pose_count
        total_count = sample_count
        yaw_p50 = _percentile(yaw_values.values, 0.50)
        yaw_p95 = _percentile(yaw_values.values, 0.95)
        yaw_max = max(yaw_values.values, default=None)
        closure_p95 = _percentile(closure_rms_values.values, 0.95)
        closure_max = max(closure_max_values.values, default=None)
        redundant_p95 = _percentile(redundant_residual_values.values, 0.95)
        xy_p95 = _percentile(xy_errors.values, 0.95)
        max_xy_error = max(xy_errors.values, default=None)
        valid_ratio = valid_count / max(1, total_count)
        summary = {
            "status": (
                "pass"
                if (
                    total_count >= 10
                    and valid_ratio >= 0.95
                    and yaw_p95 is not None
                    and yaw_p95 <= 3.0
                    and yaw_max is not None
                    and yaw_max <= TRAJECTORY_PLANAR_YAW_TOLERANCE_DEG
                    and closure_p95 is not None
                    and closure_p95 <= 1.0
                    and closure_max is not None
                    and closure_max <= TRAJECTORY_PLANAR_CLOSURE_MAX_TOLERANCE_MM
                    and xy_p95 is not None
                    and xy_p95 <= 1.5
                    and max_xy_error is not None
                    and max_xy_error <= TRAJECTORY_XY_SETTLE_TOLERANCE
                )
                else "fail"
            ),
            "current_ma": current,
            "tension_target_ma": target_current,
            "controller": "3-position-1-torque",
            "passive_motor": MOTOR_IDS[passive_index],
            "active_motors": [MOTOR_IDS[index] for index in active_indices],
            "frames": frame_count,
            "feedback_samples": total_count,
            "valid_pose_samples": valid_count,
            "valid_ratio": round(valid_ratio, 4),
            "yaw_abs_p50_deg": round(yaw_p50, 3) if yaw_p50 is not None else None,
            "yaw_abs_p95_deg": round(yaw_p95, 3) if yaw_p95 is not None else None,
            "yaw_abs_max_deg": round(yaw_max, 3) if yaw_max is not None else None,
            "closure_rms_p95_mm": round(closure_p95, 4) if closure_p95 is not None else None,
            "closure_max_mm": round(closure_max, 4) if closure_max is not None else None,
            "redundant_residual_p95_mm": round(redundant_p95, 4) if redundant_p95 is not None else None,
            "xy_error_p95_mm": round(xy_p95, 3) if xy_p95 is not None else None,
            "xy_error_max_mm": round(max_xy_error, 3) if max_xy_error is not None else None,
            "path_length_mm": round(path_length, 3),
            "duration_s": round(duration, 3),
            "parser_stats": dict(parser_stats),
        }
        append_process_log("planar_snake_test_complete", **summary)
    except Exception as exc:
        error = str(exc)
        summary = {
            "status": "error",
            "current_ma": current,
            "frames": frame_count,
            "feedback_samples": sample_count,
            "last_target_xy": [round(value, 2) for value in last_target_xy] if last_target_xy else None,
            "last_feedback": last_feedback_diagnostics,
        }
        append_process_log(
            "planar_snake_test_error",
            error=error,
            samples=sample_count,
            frames=frame_count,
            last_target_xy=summary["last_target_xy"],
            last_feedback=last_feedback_diagnostics,
            last_sample=sample_records[-1] if sample_records else None,
            parser_stats=dict(parser_stats) if "parser_stats" in locals() else {},
        )
    finally:
        if timed_stream_active:
            try:
                with SERIAL_LOCK, direct.open_serial(current_port(), current_baud()) as recovery_connection:
                    timed_stream_active = not stop_timed_position_stream(recovery_connection)
            except Exception:
                timed_stream_active = True
        recovery = disable_all_with_reconnect(current_port(), current_baud(), announce=bool(error or stopped))
        if not recovery["ok"] or timed_stream_active:
            detail = recovery.get("error", "定时反馈流停止未全部确认") if not recovery["ok"] else "定时反馈流停止未全部确认"
            set_state(
                auto="error",
                planar_snake_test={**summary, "status": "error", "error": detail},
                message="平面蛇形自测结束，但未能确认反馈流/四台失能；请立即切断动力或使用硬件急停（" + detail + "）",
            )
        elif error:
            set_state(
                control_unlocked=False,
                auto="error",
                planar_snake_test={**summary, "status": "error", "error": error},
                message="平面蛇形自测已停止：" + error + "；已自动重连并确认四台失能",
            )
        elif stopped or STOP_EVENT.is_set():
            set_state(
                auto="idle",
                planar_snake_test={"status": "stopped", **summary},
                message="平面蛇形自测已停止，四台已自动重连并失能",
            )
        else:
            result_text = "通过" if summary.get("status") == "pass" else "未通过"
            set_state(
                auto="idle",
                planar_snake_test=summary,
                message=(
                    f"平面刚体3+1自测{result_text}：有效 {summary.get('valid_pose_samples', 0)}/"
                    f"{summary.get('feedback_samples', 0)} 组，|yaw| P95 "
                    f"{summary.get('yaw_abs_p95_deg', '—')}°，闭合残差P95 "
                    f"{summary.get('closure_rms_p95_mm', '—')}mm，XY P95/最大 "
                    f"{summary.get('xy_error_p95_mm', '—')}/"
                    f"{summary.get('xy_error_max_mm', '—')}mm；四台已自动重连并失能"
                ),
            )
        if timer_resolution:
            set_high_resolution_timer(False)
        STOP_EVENT.clear()


def calibration_demo_worker() -> None:
    """Draw a conservative cross and circle after calibration for validation."""
    error: str | None = None
    stopped = False
    completed_shapes: list[str] = []
    try:
        calibration = calibration_data()
        if not calibration.get("valid"):
            raise RuntimeError("请先完成四角几何校准")
        width, height = drawable_workspace_dimensions(calibration)
        shapes = ("cross", "circle")
        set_state(
            auto="calibration-demo",
            repeat=False,
            message="校准验证准备：将以固定低速依次绘制十字、圆形",
        )
        append_process_log("calibration_demo_start", shapes=list(shapes), workspace=[width, height])
        for index, kind in enumerate(shapes):
            if STOP_EVENT.is_set():
                stopped = True
                return
            spec = test_shape_spec(kind, width, height)
            set_state(message=f"校准验证 {index + 1}/2：正在绘制{kind_label(kind)}（约 {spec['duration_ms'] / 1000:.1f}s）")
            completed = trajectory_worker(kind, spec, keep_enabled=index < len(shapes) - 1, balance_tension=True)
            if not completed:
                with STATE_LOCK:
                    detail = str(STATE.get("message", "校准验证失败"))
                stopped = "用户停止" in detail or "已停止" in detail or STOP_EVENT.is_set()
                if not stopped:
                    error = detail
                return
            completed_shapes.append(kind)
        append_process_log("calibration_demo_complete", shapes=completed_shapes)
    except Exception as exc:
        error = str(exc)
        append_process_log("calibration_demo_error", error=error, completed=completed_shapes)
    finally:
        recovery = disable_all_with_reconnect(current_port(), current_baud(), announce=bool(error or stopped))
        if not recovery["ok"]:
            set_state(
                control_unlocked=False,
                auto="error",
                message="校准验证结束，但重连后仍无法确认四台失能；请立即切断动力或使用硬件急停（" + recovery["error"] + "）",
            )
        elif error:
            set_state(control_unlocked=False, auto="error", message="校准验证已停止：" + error + "；四台已自动重连并失能")
        elif stopped or STOP_EVENT.is_set():
            set_state(auto="idle", message="校准验证已停止，四台已自动重连并失能")
        else:
            with STATE_LOCK:
                display_hz = float(STATE.get("trajectory_feedback_hz_actual") or 0.0)
                raw_hz = float(STATE.get("trajectory_feedback_raw_hz_actual") or 0.0)
            set_state(
                auto="idle",
                message=(
                    "校准验证完成：十字、圆形已绘制；同步反算显示 "
                    f"{display_hz:.1f}Hz，原始四电机更新 {raw_hz:.1f}Hz；四台已自动重连并失能"
                ),
            )
        STOP_EVENT.clear()


def test_shape_speed_mm_s(value: object = None) -> float:
    if value is None:
        value = calibration_data().get("path_speed_mm_s", PATH_SPEED_DEFAULT_MM_S)
    speed = float(value)
    if not math.isfinite(speed):
        raise ValueError("测试图案速度必须是有限数值")
    return max(PATH_SPEED_MIN_MM_S, min(PATH_SPEED_MAX_MM_S, speed))


def test_shape_spec(kind: str, width: float, height: float, speed_mm_s: float | None = None) -> dict:
    speed_mm_s = test_shape_speed_mm_s(speed_mm_s)
    if kind not in {"circle", "triangle", "square", "rectangle", "cross", "line", "snake"}:
        raise ValueError("未知测试图形")
    # Keep a small 4 mm boundary clearance and centre the first acceptance shapes
    # on the STEP/user frame centre (55,74).
    margin_x = width * (1.0 - DRAW_WORKSPACE_SCALE) / 2.0
    margin_y = height * (1.0 - DRAW_WORKSPACE_SCALE) / 2.0
    draw_width = width - 2.0 * margin_x
    draw_height = height - 2.0 * margin_y
    center_x = MECHANISM_CENTER_X_MM
    center_y = MECHANISM_CENTER_Y_MM
    origin_x = max(0.0, min(width - draw_width, center_x - draw_width / 2.0))
    origin_y = max(0.0, min(height - draw_height, center_y - draw_height / 2.0))
    spec = {
        "width": width,
        "height": height,
        "draw_width": draw_width,
        "draw_height": draw_height,
        "origin_x": origin_x,
        "origin_y": origin_y,
        "duration_ms": 0,
        "point_count": 0,
        "repeat": False,
        # Keep the same deterministic 100 Hz target path, while the X 0x43
        # stream observes actual motor motion asynchronously. Feedback never
        # gates the next command here; it is an overlay/health check so the
        # command clock stays smooth.
        "open_loop": False,
        "feedback": True,
        "feedback_during_motion": False,
        "target_gate": False,
        "controller_mode": "four_position",
        "allow_endpoint_timeout": True,
    }
    path_length = 0.0
    if kind == "triangle":
        vertices = [
            (draw_width / 2.0, draw_height * 0.10),
            (draw_width * 0.90, draw_height * 0.85),
            (draw_width * 0.10, draw_height * 0.85),
        ]
        # These are calibration shapes, not decorative smoothed curves.
        # Keep every edge straight and close the polygon explicitly so the
        # final target is the first vertex, with no Chaikin corner drift.
        path = vertices + [vertices[0]]
        spec["path"], spec["cumulative"] = path_with_cumulative(path)
        path_length = spec["cumulative"][-1]
    elif kind == "square":
        side = min(draw_width, draw_height)
        spec["draw_width"] = side
        spec["draw_height"] = side
        spec["origin_x"] = max(0.0, min(width - side, center_x - side / 2.0))
        spec["origin_y"] = max(0.0, min(height - side, center_y - side / 2.0))
        vertices = [(0.0, 0.0), (side, 0.0), (side, side), (0.0, side)]
        # Preserve an actual square.  Rounding the corners here was the
        # reason the validation picture did not look like the requested shape.
        path = vertices + [vertices[0]]
        spec["path"], spec["cumulative"] = path_with_cumulative(path)
        path_length = spec["cumulative"][-1]
    elif kind == "rectangle":
        vertices = [(0.0, 0.0), (draw_width, 0.0), (draw_width, draw_height), (0.0, draw_height)]
        path = vertices + [vertices[0]]
        spec["path"], spec["cumulative"] = path_with_cumulative(path)
        path_length = spec["cumulative"][-1]
    elif kind == "cross":
        vertices = [(draw_width * 0.18, draw_height * 0.18), (draw_width * 0.82, draw_height * 0.82), (draw_width / 2.0, draw_height / 2.0), (draw_width * 0.82, draw_height * 0.18), (draw_width * 0.18, draw_height * 0.82)]
        path = list(vertices)
        spec["path"], spec["cumulative"] = path_with_cumulative(path)
        path_length = spec["cumulative"][-1]
    elif kind == "line":
        # A single long stroke is the quickest way to expose serial cadence
        # hitches.  Keep both endpoints away from the frame so this test is
        # repeatable on the real 110x148 mm workspace.
        path = [
            (draw_width * 0.10, draw_height * 0.50),
            (draw_width * 0.90, draw_height * 0.50),
        ]
        spec["path"], spec["cumulative"] = path_with_cumulative(path)
        path_length = spec["cumulative"][-1]
    elif kind == "snake":
        # One continuous, exact polyline.  No corner smoothing or point
        # dropping: each row reversal remains visible in the command target.
        rows = 7
        x_left, x_right = draw_width * 0.10, draw_width * 0.90
        y_top, y_bottom = draw_height * 0.12, draw_height * 0.88
        path = []
        for row in range(rows):
            fraction = row / max(1, rows - 1)
            y = y_top + (y_bottom - y_top) * fraction
            path.extend(
                [(x_left, y), (x_right, y)]
                if row % 2 == 0
                else [(x_right, y), (x_left, y)]
            )
        spec["path"], spec["cumulative"] = path_with_cumulative(path)
        path_length = spec["cumulative"][-1]
    else:
        path_length = 2.0 * math.pi * min(draw_width, draw_height) * 0.40
    # The old fixed 0.9–1.2 s test durations drove the large circle at more
    # than 300 mm/s.  Derive time from path length so every demo shape uses a
    # stable Cartesian feed rate and the final tick is never a catch-up jump.
    duration = max(1000, int(round(path_length / speed_mm_s * 1000.0)))
    spec["duration_ms"] = duration
    spec["point_count"] = int(duration / (TRAJECTORY_INTERVAL * 1000.0)) + 1
    return spec


ALL_TEST_PATTERN_KINDS = ("line", "circle", "rectangle", "triangle", "cross", "snake")


def all_test_pattern_spec(width: float, height: float, speed_mm_s: float | None = None) -> dict:
    """Build one continuous physical path for the seven visual test shapes.

    The old browser button submitted seven independent jobs.  Each job reopened
    RS485, moved to a new start point, waited for a fresh local rebase, and then
    released the motors.  Keep the visible strokes separate, but make the
    physical transfer between them an ordinary pen-up phase in one motion plan.
    """
    speed_mm_s = test_shape_speed_mm_s(speed_mm_s)
    draw_segments: list[list[tuple[float, float]]] = []
    shape_ranges: list[dict] = []
    for kind in ALL_TEST_PATTERN_KINDS:
        shape = test_shape_spec(kind, width, height, speed_mm_s=speed_mm_s)
        raw_segments = sampled_trajectory_target_segments(kind, shape)
        usable: list[list[tuple[float, float]]] = []
        for raw_segment in raw_segments:
            segment = [
                (float(point[0]), float(point[1]))
                for point in raw_segment
                if isinstance(point, (list, tuple)) and len(point) >= 2
            ]
            if len(segment) >= 2:
                usable.append(segment)
        start_index = len(draw_segments)
        draw_segments.extend(usable)
        shape_ranges.append({
            "kind": kind,
            "segment_start": start_index,
            "segment_end": len(draw_segments),
        })
    if not draw_segments:
        raise RuntimeError("一键图案测试没有生成有效轨迹")

    motion_segments, _, elapsed, travel_total = plan_custom_motion_segments(
        draw_segments,
        speed_mm_s,
        speed_mm_s,
        exact_vertices=False,
        control_tick_s=TRAJECTORY_INTERVAL,
    )
    motion_path = [
        point
        for phase in motion_segments
        for point in phase.get("path", [])
    ]
    if len(motion_path) < 2 or elapsed <= 0.0:
        raise RuntimeError("一键图案测试运动计划为空")
    return {
        "kind": "custom",
        # The one-click sequence is a literal sampled path.  If the host
        # misses a 100 Hz deadline because RS485 is busy, retain the pending
        # point and extend the wall-clock duration instead of jumping over
        # several points.  A jump changes all four rope targets at once and
        # is exactly the transient that can unload one payout rope.
        "exact_polyline": True,
        "width": width,
        "height": height,
        "draw_width": width,
        "draw_height": height,
        "origin_x": 0.0,
        "origin_y": 0.0,
        "path_absolute": True,
        "draw_segments": draw_segments,
        "motion_segments": motion_segments,
        "path": motion_path,
        "cumulative": path_with_cumulative(motion_path)[1],
        "duration_ms": int(math.ceil(elapsed * 1000.0)),
        "point_count": int(math.ceil(elapsed / TRAJECTORY_INTERVAL)) + 1,
        "sequence_shapes": list(ALL_TEST_PATTERN_KINDS),
        "requested_speed_mm_s": speed_mm_s,
        "speed_mm_s": speed_mm_s,
        "sequence_ranges": shape_ranges,
        "travel_distance_mm": round(travel_total, 3),
        "repeat": False,
        "open_loop": False,
        "feedback": True,
        "feedback_during_motion": False,
        "target_gate": False,
        "controller_mode": "four_position",
    }


def all_test_patterns_worker() -> None:
    """Run every visual test shape in one enabled 100 Hz motion session."""
    error: str | None = None
    stopped = False
    completed = False
    try:
        calibration = calibration_data()
        if not calibration.get("valid"):
            raise RuntimeError("请先完成四角自动校准")
        width, height = drawable_workspace_dimensions(calibration)
        spec = all_test_pattern_spec(width, height)
        set_state(
            auto="all-test-patterns",
            repeat=False,
            all_test_patterns={
                "status": "running",
                "shapes": list(ALL_TEST_PATTERN_KINDS),
                "completed": [],
                "duration_s": round(spec["duration_ms"] / 1000.0, 2),
                "single_session": True,
            },
            message="一键图案测试准备：6种图案连续运行，只做一次通信准备和起点接管",
        )
        append_process_log(
            "all_test_patterns_start",
            shapes=list(ALL_TEST_PATTERN_KINDS),
            workspace=[width, height],
            duration_s=round(spec["duration_ms"] / 1000.0, 3),
            travel_distance_mm=spec["travel_distance_mm"],
            single_session=True,
        )
        completed = trajectory_worker(
            "custom",
            spec,
            keep_enabled=False,
            balance_tension=False,
        )
        if not completed:
            with STATE_LOCK:
                detail = str(STATE.get("message", "一键图案测试失败"))
            stopped = "用户停止" in detail or "已停止" in detail or STOP_EVENT.is_set()
            if not stopped:
                error = detail
            return
        append_process_log(
            "all_test_patterns_complete",
            shapes=list(ALL_TEST_PATTERN_KINDS),
            duration_s=round(spec["duration_ms"] / 1000.0, 3),
            single_session=True,
        )
    except Exception as exc:
        error = str(exc)
        append_process_log("all_test_patterns_error", error=error)
    finally:
        with STATE_LOCK:
            existing = dict(STATE.get("all_test_patterns", {}))
        if error:
            existing.update({"status": "error", "error": error, "single_session": True})
            set_state(auto="error", all_test_patterns=existing, message="一键图案测试失败：" + error)
        elif stopped or STOP_EVENT.is_set():
            existing.update({"status": "stopped", "single_session": True})
            set_state(auto="idle", all_test_patterns=existing, message="一键图案测试已停止，已保留四角校准")
        elif completed:
            existing.update({
                "status": "complete",
                "completed": list(ALL_TEST_PATTERN_KINDS),
                "single_session": True,
            })
            set_state(
                auto="idle",
                repeat=False,
                all_test_patterns=existing,
                message="一键图案测试完成：6种图案已连续绘制，四台电机已安全收尾",
            )
        STOP_EVENT.clear()


def kind_label(kind: str) -> str:
    return {"circle": "圆形", "triangle": "三角形", "square": "正方形", "rectangle": "矩形", "cross": "十字", "line": "直线", "snake": "蛇形", "custom": "手绘", "all-test-patterns": "一键图案测试"}.get(kind, kind)


def resolve_port(requested: object = None) -> str:
    """Pick the serial port for this request.

    ``direct.choose_port`` refuses to guess when a PC exposes more than one
    serial port, which made "connect" impossible on any machine that also has
    a built-in COM1.  The web console always offers an explicit port selector,
    so fall back in this order instead of failing:

    explicit request -> live state -> last operator choice -> only port -> first port
    """

    text = str(requested or "").strip()
    if text:
        return text
    with STATE_LOCK:
        cached = STATE.get("port")
    if cached:
        return str(cached)
    ports = [serial_port_label(port) for port in direct.list_serial_ports()]
    devices = [item["device"] for item in ports]
    saved = load_saved_port()
    if saved and saved in devices:
        return saved
    # Prefer the single USB bridge; a built-in "通信端口 (COM1)" must never win
    # just because it sorts first.
    adapters = [item["device"] for item in ports if item["likely_adapter"]]
    if len(adapters) == 1:
        return adapters[0]
    if devices:
        return devices[0]
    raise RuntimeError("没有发现串口，请插入 USB-RS485 转换器并检查驱动")


def current_port() -> str:
    return resolve_port(None)


def current_baud() -> int:
    with STATE_LOCK:
        return int(STATE.get("baud") or direct.DEFAULT_BAUD)


def start_thread(target, *args) -> None:
    # HTTP requests can arrive from two tabs or a double click concurrently.
    # Admission and worker publication must be atomic, not just a UI guard.
    if not AUTO_START_LOCK.acquire(blocking=False):
        raise RuntimeError("上一项操作正在启动，请勿重复点击")
    try:
        _start_thread_locked(target, *args)
    finally:
        AUTO_START_LOCK.release()


def _start_thread_locked(target, *args) -> None:
    global AUTO_THREAD
    if EMERGENCY_STOP_PENDING.is_set():
        raise RuntimeError("急停尚未确认完成，不能启动新动作；必要时使用硬件急停")
    if not BOOT_PREPARE_DONE.is_set():
        raise RuntimeError("服务启动自动准备尚未完成，请稍候再启动运动流程")
    if active_auto():
        raise RuntimeError("自动流程正在运行，请先按急停")
    STOP_EVENT.clear()
    SOFT_STOP_EVENT.clear()
    record_context = begin_manual_test_run(target, args)

    def recorded_worker() -> None:
        result = None
        failure: BaseException | None = None
        try:
            result = target(*args)
        except BaseException as exc:
            failure = exc
            raise
        finally:
            end_manual_test_run(record_context, result=result, error=failure)

    AUTO_THREAD = threading.Thread(
        target=recorded_worker,
        name=f"y42-{getattr(target, '__name__', 'worker')}",
        daemon=True,
    )
    try:
        AUTO_THREAD.start()
    except BaseException as exc:
        end_manual_test_run(record_context, error=exc)
        raise


def stop_motion_for_replacement(label: str) -> str | None:
    """Stop a live trajectory/tracking worker before replacing its request.

    A new path must never share the serial port with the old worker.  The
    worker's normal ``finally`` block performs the stop, reconnect and disable
    handshake; waiting here makes the next request start only after that
    handshake has completed.  Calibration/direction/shape-sequence flows are
    intentionally not replaceable from a drawing button.
    """
    global AUTO_THREAD
    if not AUTO_REPLACE_LOCK.acquire(blocking=False):
        raise RuntimeError("正在切换上一条轨迹，请稍候")
    try:
        thread = AUTO_THREAD
        if thread is None or not thread.is_alive():
            return None
        with STATE_LOCK:
            running = str(STATE.get("auto", ""))
        if running not in {"trajectory", "tracking"}:
            raise RuntimeError(f"当前正在运行{running or '自动流程'}，不能从此按钮中途替换")
        set_state(message=f"正在安全停止当前{('手绘轨迹' if running == 'trajectory' else '张力跟踪')}，准备切换{label}……")
        append_process_log("auto_replace_requested", old_auto=running, new_action=label)
        if running == "tracking":
            SOFT_STOP_EVENT.set()
        STOP_EVENT.set()
        thread.join(timeout=15.0)
        if thread.is_alive():
            raise RuntimeError("上一条流程未在 15 秒内完成失能，已保留急停状态；请检查通讯后再试")
        return running
    finally:
        AUTO_REPLACE_LOCK.release()


def auto_prepare_on_boot() -> None:
    """Run the non-motion safety preparation once when the web server starts.

    The user has already confirmed this machine's mechanism.  Preparation only
    scans, verifies/switches firmware, locks local keys, and sends STOP/DISABLE;
    it does not enable or move a motor.  Keeping it here prevents a browser
    reload or a code restart from silently leaving the UI in a stale locked
    state and asking for the same confirmation again.
    """

    try:
        port = resolve_port(None)
        baud = load_saved_baud()
        set_state(port=port, baud=baud, control_unlocked=False, message="自动准备：服务启动后正在扫描 ID 1..4")
        result = prepare_system(port, baud, preserve_saved_tension=True)
        # A device may have been changed by another tool since the last run.
        # Recover automatically instead of leaving the UI falsely offline at
        # 115200 (or at a stale saved rate).
        if not result.get("ready"):
            scan = baud_sweep(port, list(SUPPORTED_BAUDS))
            recovered_baud = scan.get("recommended_baud")
            if recovered_baud and recovered_baud != baud:
                baud = int(recovered_baud)
                set_state(port=port, baud=baud, control_unlocked=False, message=f"自动准备：已在 {baud} 找到四台电机，正在重新准备")
                result = prepare_system(port, baud, preserve_saved_tension=True)
        if not result.get("ready"):
            set_state(control_unlocked=False, auto="error", message=result.get("message", "自动准备未完成"))
    except Exception as exc:
        set_state(control_unlocked=False, auto="error", message="服务启动自动准备失败：" + str(exc))
    finally:
        BOOT_PREPARE_DONE.set()


def require_confirmed(data: dict) -> None:
    if data.get("confirmed") is not True:
        raise ValueError("此操作需要网页安全确认")


def require_control_unlocked() -> None:
    if EMERGENCY_STOP_PENDING.is_set():
        raise RuntimeError("急停正在确认，暂不能运行；急停未确认时请切断动力")
    with STATE_LOCK:
        if not STATE["control_unlocked"]:
            raise RuntimeError("控制按钮当前已锁定，请先确认 X 固件绿灯闪烁模式和机构安全后解锁")


def require_internal_model_ready(calibration: dict, action_label: str) -> None:
    """Gate motion on the four-corner geometry/encoder model only.

    This is the user's camera-free route.  ``external_pose_verified`` remains
    an optional metadata flag for experiments, never a prerequisite for motion.
    """
    ready, reason = internal_model_readiness(calibration)
    if not ready:
        raise RuntimeError(f"{action_label}已暂停：{reason}；请先完成四角几何/编码器校准")


def require_draw_model_ready(calibration: dict, action_label: str) -> None:
    """Admission check for the simple drawing path.

    The operator drawing route reuses the saved four-corner map and re-anchors
    from the current encoder positions in the trajectory worker.  It should not
    be blocked by diagnostic-only R², curve-shape, or live-session gates that
    belong to calibration/feedback experiments.  Keep only the data needed to
    produce four finite motor targets; the existing inverse code still falls
    back to the saved linear slope/intercept when a nonlinear curve is absent.
    """
    with STATE_LOCK:
        recovery_required = bool(STATE.get("calibration_requires_full"))
        recovery_reason = str(
            STATE.get("calibration_last_error")
            or "保存模型尚未通过本次急停恢复检查"
        )
    if recovery_required:
        raise RuntimeError(
            f"{action_label}已暂停：{recovery_reason}；已保留保存模型，"
            "请确认机构无人接触、急停已释放后点击“校准”，不能直接运行绘制"
        )
    if not is_same_tensioned_session(calibration):
        reason = str(
            calibration.get("session_invalid_reason")
            if isinstance(calibration, dict)
            else "当前会话尚未完成急停恢复"
        )
        raise RuntimeError(
            f"{action_label}已暂停：{reason or '当前会话尚未完成急停恢复'}；"
            "请确认机构无人接触、急停已释放后点击“校准”，恢复张力后再绘制"
        )
    if not isinstance(calibration, dict) or calibration.get("valid") is not True:
        raise RuntimeError(f"{action_label}没有可用的已保存四角模型；需要时再点一次校准")
    try:
        slopes = [float(value) for value in calibration.get("slope", [])]
        intercepts = [float(value) for value in calibration.get("intercept", [])]
    except (TypeError, ValueError):
        raise RuntimeError(f"{action_label}的已保存模型参数不完整；需要时再点一次校准") from None
    if len(slopes) != len(MOTOR_IDS) or len(intercepts) != len(MOTOR_IDS):
        raise RuntimeError(f"{action_label}的四台电机模型参数不完整；需要时再点一次校准")
    if any(not math.isfinite(value) for value in slopes + intercepts) or any(abs(value) <= 0.05 for value in slopes):
        raise RuntimeError(f"{action_label}的已保存模型参数无效；需要时再点一次校准")


def require_external_pose_verified(calibration: dict, action_label: str) -> None:
    """Backward-compatible alias for older API callers.

    The name is retained so a stale browser/client does not crash, but the
    desktop motion gate is intentionally internal-only and never asks for a
    camera or fixture measurement.
    """
    require_internal_model_ready(calibration, action_label)


def set_control_lock(data: dict) -> dict:
    global STATE
    armed = bool(data.get("armed", False))
    if armed:
        require_confirmed(data)
    with STATE_LOCK:
        STATE["control_unlocked"] = armed
    return {"ok": True, "control_unlocked": armed, "message": "控制按钮已解锁" if armed else "控制按钮已锁定"}


def _prepare_system_impl(port: str, baud: int, preserve_saved_tension: bool = False) -> dict:
    if active_auto():
        raise RuntimeError("自动流程运行中，请先按急停")
    set_state(control_unlocked=False, message="自动准备：正在扫描 ID 1..4")
    with SERIAL_LOCK, direct.open_serial(port, baud) as connection:
        found = direct.scan(connection, 1, 4, verbose=False)
        missing = [address for address in MOTOR_IDS if address not in found]
        if missing:
            message = "缺少电机 ID " + ", ".join(map(str, missing)) + "；请检查对应电机的动力电源、RS485 A/B 接线和接头；通讯恢复后重新点击“连接并自动准备”"
            set_state(message=message, auto="idle", control_unlocked=False)
            return {"ok": True, "action": "prepare", "ready": False, "stage": "ids", "found": found, "missing": missing, "message": message}

        set_state(message="自动准备：正在读取四台固件状态")
        firmware = [read_firmware_status(connection, address) for address in MOTOR_IDS]
        firmware_ok = all(item.get("firmware") == "X" for item in firmware)
        switch_result = None
        if not firmware_ok:
            set_state(message="自动准备：发现非 X 固件，正在停止并切换四台为 X")
            switch_result = switch_all_to_x(connection)
            if not switch_result["ok"]:
                disable_all(connection)
                message = "X 固件切换失败；请检查回包和接线后重试"
                set_state(message=message, auto="error", control_unlocked=False)
                return {"ok": True, "action": "prepare", "ready": False, "stage": "firmware", "firmware": switch_result.get("status", firmware), "switch": switch_result, "message": message}
            firmware = switch_result["status"]

        set_state(message="自动准备：正在锁定四台电机本体按键")
        keys_ok, key_results = lock_keys_all(connection)
        resume_reason = ""
        with STATE_LOCK:
            emergency_rearm_available = bool(
                isinstance(STATE.get("calibration"), dict)
                and STATE["calibration"].get("emergency_stop_rearm_available") is True
            )
        if keys_ok and preserve_saved_tension and switch_result is None and not emergency_rearm_available:
            set_state(message="自动准备：正在只读复核保存的标定与四绳张力")
            resumed, resume_reason = adopt_persisted_tensioned_calibration(connection)
            if resumed:
                message = "自动准备完成：" + resume_reason
                set_state(message=message, auto="idle", control_unlocked=True)
                return {
                    "ok": True,
                    "action": "prepare",
                    "ready": True,
                    "resumed_calibration": True,
                    "found": list(MOTOR_IDS),
                    "firmware": firmware,
                    "keys": key_results,
                    "disable": [],
                    "message": message,
                }
        set_state(message="自动准备：正在让四台电机全部失能")
        disable_results = disable_all(
            connection,
            invalidate=not emergency_rearm_available,
        )
        disable_ok = all(item["accepted"] for item in disable_results)
        if not keys_ok:
            message = "电机本体按键未全部锁定；四台已发送失能，请检查回包后重试"
            set_state(message=message, auto="error", control_unlocked=False)
            return {"ok": True, "action": "prepare", "ready": False, "stage": "keys", "firmware": firmware, "keys": key_results, "disable": disable_results, "message": message}
        if not disable_ok:
            message = "四台电机失能未全部收到 ACK；请检查 RS485 后重试"
            set_state(message=message, auto="error", control_unlocked=False)
            return {"ok": True, "action": "prepare", "ready": False, "stage": "disable", "firmware": firmware, "keys": key_results, "disable": disable_results, "message": message}

    message = "自动准备完成：ID 1..4 在线、X 固件已确认、物理按键已锁定、四台电机已失能"
    if preserve_saved_tension and resume_reason:
        message += "；保存的四角几何模型已保留，绘制会从当前编码器位置重新接管，无需重新校准；需要时仍可手动点击校准"
    elif emergency_rearm_available:
        message += "；急停位置已保留，点击‘校准’将原位快速恢复张力，无需重新采四角"
    set_state(message=message, auto="idle", control_unlocked=True)
    return {"ok": True, "action": "prepare", "ready": True, "found": list(MOTOR_IDS), "firmware": firmware, "keys": key_results, "disable": disable_results, "message": message}


def prepare_system(port: str, baud: int, preserve_saved_tension: bool = False) -> dict:
    if EMERGENCY_STOP_PENDING.is_set():
        raise RuntimeError("急停尚未确认完成，请等待停止结果后再连接准备")
    if not PREPARE_GUARD.acquire(blocking=False):
        raise RuntimeError("自动准备正在进行，请等待连接检查完成")
    try:
        return _prepare_system_impl(port, baud, preserve_saved_tension)
    finally:
        PREPARE_GUARD.release()


def schedule_prepare_if_needed(port: str, baud: int) -> None:
    """Re-run the non-motion preparation after a previously lost link returns."""

    def eligible() -> bool:
        with STATE_LOCK:
            return (not bool(STATE.get("control_unlocked"))
                    and STATE.get("auto") in {"idle", "error"}
                    and not (AUTO_THREAD is not None and AUTO_THREAD.is_alive())
                    and not (STATE.get("manual_test_recording") or {}).get("active", False)
                    and not EMERGENCY_STOP_PENDING.is_set())

    if not eligible() or PREPARE_GUARD.locked():
        return

    def worker() -> None:
        # Admission uses the same lock as start_auto: a queued reconnect must
        # not slip between a motion request's validation and worker startup.
        if not AUTO_REQUEST_LOCK.acquire(blocking=False):
            return
        try:
            if not eligible() or PREPARE_GUARD.locked():
                return
            with STATE_LOCK:
                before = (STATE.get("auto"), STATE.get("message"))
            try:
                prepare_system(port, baud)
            except Exception as exc:
                # STOP bypasses admission locks. Never overwrite a changed
                # state (including STOP/new work) with a stale recovery error.
                if eligible():
                    with STATE_LOCK:
                        if (STATE.get("auto"), STATE.get("message")) == before:
                            STATE.update(control_unlocked=False, auto="error",
                                         message="通讯恢复后的自动准备失败：" + str(exc))
        finally:
            AUTO_REQUEST_LOCK.release()

    threading.Thread(target=worker, name="y42-reprepare", daemon=True).start()


def diagnose_port(port: str, bauds: object = None) -> dict:
    """Read-only self test for one adapter.

    Answers the question the port selector cannot: is the chosen adapter
    hearing anything on the bus at all?  Only 0x3A status queries are sent;
    nothing here enables, moves or brakes a motor.
    """

    if active_auto():
        raise RuntimeError("自动流程运行中，请先按急停再做串口自检")
    requested = bauds if isinstance(bauds, (list, tuple)) and bauds else list(SUPPORTED_BAUDS)
    results = []
    total_bytes = 0
    found_at: dict[int, list[int]] = {}
    for baud in dict.fromkeys(int(value) for value in requested):
        if baud < 1200 or baud > 1000000:
            continue
        entry = {"baud": baud, "bytes": 0, "found": [], "rx": "", "error": ""}
        try:
            with SERIAL_LOCK, direct.open_serial(port, baud) as connection:
                connection.write(
                    b"".join(direct.frame(address, 0x3A, direct.FRAME_END) for address in MOTOR_IDS)
                )
                connection.flush()
                time.sleep(0.25)
                waiting = int(getattr(connection, "in_waiting", 0) or 0)
                raw = connection.read(waiting) if waiting else b""
                entry["bytes"] = len(raw)
                entry["rx"] = direct.hex_bytes(raw[:24]) if raw else ""
                total_bytes += len(raw)
                if raw:
                    entry["found"] = direct.scan(connection, min(MOTOR_IDS), max(MOTOR_IDS), verbose=False)
                    if entry["found"]:
                        found_at[baud] = entry["found"]
        except Exception as exc:  # noqa: BLE001 - report, never crash the page
            entry["error"] = str(exc)
        results.append(entry)

    if found_at:
        where = "、".join(f"{baud} → ID {ids}" for baud, ids in found_at.items())
        message = f"{port} 自检通过：{where}。"
    elif total_bytes == 0:
        message = (
            f"{port} 在所有波特率上都没有收到任何字节。这说明电脑端没有读到总线信号，"
            "与端口选择无关。请依次检查：① 电机驱动器的动力电源是否已打开（编码器/通讯部分是否带电）；"
            "② RS485 的 A/B 是否真的接到了这个转换器（不是接到了 ESP32 那一路）；"
            "③ A/B 是否接反（可对调试一次）；④ 转换器与电机是否共地；⑤ 该转换器是否为 USB-RS485 型。"
        )
    else:
        message = (
            f"{port} 收到了 {total_bytes} 字节，但没有解析出符合协议的应答。"
            "常见原因：波特率不在支持列表、电机 ID 不在 1–10、总线上还有别的设备在回包，"
            "或电机不在 X 固件模式。"
        )
    return {
        "ok": True,
        "action": "port-diagnose",
        "port": port,
        "results": results,
        "total_bytes": total_bytes,
        "found": found_at,
        "message": message,
    }


# Actions that mean "this is the adapter we are working with", so the explicit
# port is worth remembering.  Read-only discovery scans every port in turn and
# must not let the last scanned port overwrite the operator's choice.
PORT_PERSIST_ACTIONS = {
    "prepare",
    "baud-sweep",
    "baud-set",
    "baud-set-single",
    "firmware-status",
    "port-diagnose",
    "stability",
    "stability-long",
}


def execute(data: dict) -> dict:
    action = str(data.get("action", ""))
    if action == "ports":
        return ports_snapshot()
    if action == "set-port":
        chosen = str(data.get("port") or "").strip()
        devices = [str(port.device) for port in direct.list_serial_ports()]
        if chosen and chosen not in devices:
            raise ValueError(f"串口 {chosen} 当前不可用，请点击“刷新串口”后重新选择")
        with STATE_LOCK:
            STATE["port"] = chosen or None
        persist_saved_port(chosen)
        return {
            "ok": True,
            "action": action,
            "port": chosen,
            "message": f"已选择串口 {chosen}" if chosen else "已切换为自动选择串口",
        }
    if action == "port-diagnose":
        return diagnose_port(resolve_port(data.get("port")), data.get("bauds"))
    if action == "stop":
        return request_emergency_stop(data)
    port = resolve_port(data.get("port"))
    if action in PORT_PERSIST_ACTIONS and str(data.get("port") or "").strip():
        persist_saved_port(port)
    # Diagnostics and emergency actions are often sent by the compact UI
    # without repeating the connection fields. Reuse the verified live baud;
    # falling back to 115200 here silently made the 921600 stability test open
    # the same COM port at the wrong rate and report every motor offline.
    baud = int(data.get("baud", current_baud()))
    if baud < 1200 or baud > 1000000:
        raise ValueError("波特率范围无效")
    # Read-only probes use a temporary port/rate. Never redirect normal
    # telemetry and reconnect traffic to the last unsuccessful scan rate.
    if action not in {"scan", "baud-sweep"}:
        with STATE_LOCK:
            STATE["port"] = port
            STATE["baud"] = baud
    if action == "prepare":
        require_confirmed(data)
        return prepare_system(port, baud)
    if action == "stability":
        if active_auto():
            raise RuntimeError("自动流程运行中，请先按急停再做通讯稳定性测试")
        rounds = int(data.get("rounds", 20))
        return stability_test(port, baud, rounds)
    if action == "stability-long":
        if active_auto():
            raise RuntimeError("自动流程运行中，请先按急停再做 15 秒总线稳定性测试")
        return long_stability_test(port, baud, float(data.get("duration_s", 15.0)))
    if action == "sequential-position-transport-test":
        if active_auto():
            raise RuntimeError("自动流程运行中，请先按急停再做逐台通信对照测试")
        return sequential_position_transport_test(port, baud, float(data.get("duration_s", 3.0)))
    if action == "baud-sweep":
        if active_auto():
            raise RuntimeError("自动流程运行中，请先按急停再做波特率诊断")
        requested = data.get("bauds", list(SUPPORTED_BAUDS))
        bauds = list(dict.fromkeys(int(value) for value in requested))
        if not bauds or len(bauds) > 10 or any(value < 1200 or value > 1000000 for value in bauds):
            raise ValueError("波特率诊断参数无效")
        return baud_sweep(port, bauds)
    if action == "baud-set":
        if active_auto():
            raise RuntimeError("自动流程运行中，请先按急停再写入电机波特率")
        target_baud = int(data.get("target_baud", 0))
        return set_all_motor_baud(port, baud, target_baud)
    if action == "baud-set-single":
        if active_auto():
            raise RuntimeError("自动流程运行中，请先按急停再写入单台电机波特率")
        address = int(data.get("id", 0))
        target_baud = int(data.get("target_baud", 0))
        result = set_single_motor_baud(port, baud, address, target_baud)
        if result.get("verified"):
            set_state(auto="idle", control_unlocked=False, message=result.get("message", "单台波特率已更新"))
        return result
    if action == "status":
        if active_auto():
            snapshot = state_snapshot()
            return {"ok": True, "action": action, "motors": list(snapshot["telemetry"].values()), "auto": snapshot["auto"]}
        return status_for_web(port, baud)
    if action == "firmware-status":
        if active_auto():
            raise RuntimeError("自动流程运行中，请先按急停再读取固件类型")
        results = []
        with SERIAL_LOCK, direct.open_serial(port, baud) as connection:
            for address in MOTOR_IDS:
                results.append(read_firmware_status(connection, address))
        return {"ok": True, "action": action, "all_responded": all(item["ok"] for item in results), "results": results, "message": "已读取四台电机实际固件类型；无回包的电机可能不支持固件类型读取指令"}
    if action == "scan":
        start = int(data.get("start", direct.MIN_ID))
        end = int(data.get("end", direct.MAX_ID))
        if not 0 <= start <= end <= direct.MAX_ID:
            raise ValueError("扫描范围必须是 0 <= start <= end <= 255")
        if active_auto():
            raise RuntimeError("自动流程运行中，请先按急停再扫描 ID")
        # ID 0 is the broadcast address. Sending a status query to it can make
        # every motor answer at once, causing a collision, so 0 is accepted as
        # the UI range marker but is never transmitted on the bus.
        scan_start = max(direct.MIN_ID, start)
        with SERIAL_LOCK, direct.open_serial(port, baud) as connection:
            found = direct.scan(connection, scan_start, end, verbose=False) if scan_start <= end else []
        note = "（0 为广播地址，未向 ID 0 发送帧）" if start == 0 else ""
        return {"ok": True, "action": action, "start": start, "end": end, "scanned_start": scan_start, "found": found, "message": f"扫描完成，实际扫描 ID {scan_start}..{end}，发现 {len(found)} 个地址{note}"}
    if action == "direction-test":
        require_control_unlocked()
        require_confirmed(data)
        if active_auto():
            raise RuntimeError("已有自动流程运行中，请先按急停")
        address = direct.check_id(int(data.get("id", 0)))
        with STATE_LOCK:
            ready = copy.deepcopy(STATE.get("direction_ready", {}))
            ready.pop(str(address), None)
            STATE["direction_ready"] = ready
        start_thread(direction_test_worker, address)
        return {"ok": True, "action": action, "id": address, "message": f"M{MOTOR_IDS.index(address) + 1} 正方向测试已启动：仅转 45°，不复位"}
    if action == "direction-save":
        require_control_unlocked()
        require_confirmed(data)
        if active_auto():
            raise RuntimeError("正方向测试仍在运行，请等待测试完成")
        address = direct.check_id(int(data.get("id", 0)))
        return save_direction_choice(address, data.get("reverse") is True)
    if action in {"all-enable", "all-disable", "release-all"}:
        require_control_unlocked()
        require_confirmed(data)
        if active_auto():
            raise RuntimeError("自动流程运行中，仅允许急停")
        with SERIAL_LOCK, direct.open_serial(port, baud) as connection:
            if action == "all-enable":
                results = []
                for address in MOTOR_IDS:
                    ok, tx, rx = enable_address(connection, address)
                    results.append({"id": address, "ok": ok, "tx": direct.hex_bytes(tx), "rx": direct.hex_bytes(rx)})
                return {"ok": all(item["ok"] for item in results), "action": action, "results": results}
            if action == "all-disable":
                return {"ok": True, "action": action, "results": disable_all(connection)}
            results = []
            for address in MOTOR_IDS:
                tx = command_frame(address, "release", {})
                results.append(command_result(address, 0x0E, tx, direct.transact(connection, tx)))
            return {"ok": True, "action": action, "results": results}
    if action in {"firmware-x", "firmware-emm", "firmware-turbo"}:
        require_confirmed(data)
        if active_auto():
            raise RuntimeError("自动流程运行中，仅允许急停")
        firmware_code = {"firmware-x": 0, "firmware-emm": 1, "firmware-turbo": 2}[action]
        firmware_name = {0: "X", 1: "Emm", 2: "Emm 狂暴模式"}[firmware_code]
        with SERIAL_LOCK, direct.open_serial(port, baud) as connection:
            stop_results = stop_all(connection)
            if not all(item["ok"] for item in stop_results):
                return {"ok": False, "action": action, "target": firmware_name, "stop_results": stop_results, "message": "切换前急停未全部收到回包，已取消固件切换"}
            results = []
            for address in MOTOR_IDS:
                tx = firmware_switch_frame(address, firmware_code, store=True)
                rx = direct.transact(connection, tx, first_byte_timeout=0.3)
                results.append(command_result(address, 0xD5, tx, rx))
            restart_results = []
            for address in MOTOR_IDS:
                tx = firmware_restart_frame(address)
                rx = direct.transact(connection, tx, first_byte_timeout=0.5)
                restart_results.append(command_result(address, 0x08, tx, rx))
                time.sleep(0.25)
            time.sleep(0.5)
            status = []
            for address in MOTOR_IDS:
                status.append(read_firmware_status(connection, address))
        accepted = all(item["accepted"] for item in results)
        verified = all(item.get("ok") and item.get("firmware_code") == firmware_code for item in status)
        restarted = all(item["accepted"] for item in restart_results)
        message = f"已逐台写入 {firmware_name} 固件类型并重启复核"
        if verified:
            message += "，读取复核一致"
        else:
            message += "，仍有电机不是目标固件或未提供可靠回读"
        if not restarted:
            message += "；部分重启命令未收到 ACK"
        return {"ok": accepted and verified, "action": action, "target": firmware_name, "stored": True, "accepted": accepted, "restarted": restarted, "verified": verified, "results": results, "restart_results": restart_results, "status": status, "message": message}
    if action == "lock-keys":
        require_confirmed(data)
        if active_auto():
            raise RuntimeError("自动流程运行中，请先按急停再锁定电机按键")
        with SERIAL_LOCK, direct.open_serial(port, baud) as connection:
            ok, results = lock_keys_all(connection)
        return {"ok": ok, "action": action, "locked": ok, "results": results, "message": "四台电机物理按键已锁定并读取复核" if ok else "物理按键锁定未全部复核成功"}
    if action == "set-id":
        require_confirmed(data)
        if active_auto():
            raise RuntimeError("自动流程运行中，请先按急停再修改 ID")
        old_id = direct.check_id(int(data["old"]), "旧 ID")
        new_id = direct.check_id(int(data["new"]), "新 ID")
        if old_id == new_id:
            raise ValueError("旧 ID 和新 ID 不能相同")
        with SERIAL_LOCK, direct.open_serial(port, baud) as connection:
            tx = direct.frame(old_id, 0xAE, 0x4B, 0x01, new_id, direct.FRAME_END)
            rx = direct.set_motor_id(connection, old_id, new_id)
        accepted = direct.command_accepted(rx, old_id, 0xAE)
        if accepted:
            set_state(control_unlocked=False, message=f"ID {old_id} 已改为 {new_id}；请断电重启后重新执行一键准备")
        return {"ok": accepted, "action": action, "accepted": accepted, "tx": direct.hex_bytes(tx), "rx": direct.hex_bytes(rx), "message": "已收到设置 ID ACK，请断电重启后重新扫描新 ID" if accepted else "设置 ID 未收到标准 ACK，请勿继续改名；确认总线上只有目标电机"}
    if action == "raw":
        require_control_unlocked()
        require_confirmed(data)
        tx = direct.parse_hex_frame(str(data.get("hex_frame", "")))
        with SERIAL_LOCK, direct.open_serial(port, baud) as connection:
            rx = direct.transact(connection, tx, first_byte_timeout=0.08)
        return {"ok": True, "action": action, "tx": direct.hex_bytes(tx), "rx": direct.hex_bytes(rx)}
    single_motor_actions = {"enable", "position", "torque", "speed", "home", "disable", "clear", "release", "abort-home", "set-home"}
    if action in single_motor_actions:
        address = direct.check_id(int(data.get("id", 0)))
        require_control_unlocked()
        if action not in {"disable", "clear", "release", "abort-home", "set-home"}:
            require_confirmed(data)
        if active_auto():
            raise RuntimeError("自动流程运行中，仅允许急停")
        with SERIAL_LOCK, direct.open_serial(port, baud) as connection:
            if action in {"position", "torque", "speed", "home"}:
                enabled, _, _ = enable_address(connection, address)
                if not enabled:
                    raise RuntimeError(f"电机 ID {address} 自动使能失败")
            if action == "disable":
                stop_tx = command_frame(address, "stop", {})
                stop_rx = direct.transact(connection, stop_tx)
                tx = command_frame(address, action, data)
                rx = direct.transact(connection, tx)
                return {"ok": True, "action": action, "stop_rx": direct.hex_bytes(stop_rx), "tx": direct.hex_bytes(tx), "rx": direct.hex_bytes(rx)}
            tx = command_frame(address, action, data)
            rx = direct.transact(connection, tx)
        return {"ok": True, "action": action, **command_result(address, tx[1], tx, rx)}
    raise ValueError(f"未知操作: {action}")


def start_auto(data: dict) -> dict:
    # Serialize validation + state mutation + worker admission across browser
    # tabs. STOP must bypass this guard so a pending request cannot block it.
    if str(data.get("action", "")) in {"abort", "tracking-stop"}:
        return _start_auto_impl(data)
    if not AUTO_REQUEST_LOCK.acquire(blocking=False):
        raise RuntimeError("上一项请求仍在处理中，请勿重复点击；急停始终可用")
    try:
        return _start_auto_impl(data)
    finally:
        AUTO_REQUEST_LOCK.release()


def _start_auto_impl(data: dict) -> dict:
    global TRAJECTORY_SPEC
    action = str(data.get("action", ""))
    if action == "reset-defaults":
        return reset_default_parameters()
    if action == "parameter-save":
        return save_calibration_settings(data)
    if action == "abort":
        return request_emergency_stop(data)
    if action == "tracking-stop":
        with STATE_LOCK:
            running = STATE.get("auto")
        if active_auto() and running == "tracking":
            SOFT_STOP_EVENT.set()
        STOP_EVENT.set()
        return {
            "ok": True,
            "action": action,
            "message": (
                "已请求柔和结束张力跟踪；将无位置跳变交接到四电机位置闭环并保持自应力张紧"
                if active_auto() and running == "tracking"
                else "当前没有运行中的张力跟踪"
            ),
        }
    if action == "tracking-clear":
        return clear_tracking_cache()
    if action == "tracking-reference":
        with STATE_LOCK:
            running = STATE.get("auto")
        if active_auto() and running != "tracking":
            raise RuntimeError("其他自动流程正在运行，暂时不能设置跟踪参考点")
        return set_tracking_reference(data.get("point"))
    if action == "tracking-thresholds":
        # Threshold changes are configuration-only and are safe to apply while
        # tracking is running; the worker refreshes them on its 100 Hz clock.
        require_control_unlocked()
        require_confirmed(data)
        return save_calibration_settings(
            {
                "tracking_pen_up_height_mm": data.get("tracking_pen_up_height_mm"),
                "tracking_pen_down_height_mm": data.get("tracking_pen_down_height_mm"),
            }
        )
    if action == "clear-trace":
        return clear_trajectory_cache()
    if action == "trajectory-current":
        require_control_unlocked()
        require_confirmed(data)
        try:
            current = int(data.get("current"))
        except (TypeError, ValueError):
            raise ValueError("绘制张力上限必须是整数") from None
        if not TRAJECTORY_TENSION_MIN_CURRENT <= current <= TRAJECTORY_TENSION_MAX_CURRENT:
            raise ValueError(f"绘制张力上限必须在 {TRAJECTORY_TENSION_MIN_CURRENT}..{TRAJECTORY_TENSION_MAX_CURRENT}mA")
        save_calibration_settings({"draw_tension_current_ma": current})
        set_state(trajectory_current_override=current, message=f"绘制张力上限已调整为 {current}mA；下一控制帧生效")
        append_process_log("trajectory_current_override", current_ma=current, active=active_auto())
        return {"ok": True, "action": action, "current_ma": current, "message": f"绘制张力上限已调整为 {current}mA"}
    if action == "stop_loop":
        require_control_unlocked()
        require_confirmed(data)
        with STATE_LOCK:
            STATE["repeat"] = False
        return {"ok": True, "message": "已停止后续循环；当前轮结束后保持终点"}
    if action == "tracking-start":
        require_control_unlocked()
        require_confirmed(data)
        calibration = calibration_data()
        require_internal_model_ready(calibration, "张力跟踪")
        try:
            current = int(data.get("current", TRACKING_CURRENT_LIMIT_DEFAULT_MA))
        except (TypeError, ValueError):
            raise ValueError("张力跟踪保护上限必须是整数") from None
        if not TRACKING_MIN_CURRENT <= current <= TRACKING_MAX_CURRENT:
            raise ValueError(f"张力跟踪保护上限必须是 {TRACKING_MIN_CURRENT}..{TRACKING_MAX_CURRENT}mA")
        save_calibration_settings({"tracking_current_ma": current})
        replaced = stop_motion_for_replacement("新的张力跟踪")
        with STATE_LOCK:
            preserve_trace = bool(
                STATE.get("tracking_trace")
                or STATE.get("tracking_trace_segments")
            ) and STATE.get("auto") in {"tracking", "error"}
        start_thread(tracking_worker, current, preserve_trace)
        model_context = calibration_model_context(calibration)
        append_process_log(
            "tracking_start",
            current_limit_ma=current,
            automatic_floor_ma=min(current, TRACKING_AUTO_FLOOR_CURRENT_MA),
            directions=list(pull_directions()),
            replaced_auto=replaced,
            model_family_key=model_context.get("model_family_key"),
            position_reference_deg=model_context.get("position_reference_deg"),
        )
        return {
            "ok": True,
            "action": action,
            "current_ma": current,
            "replaced_auto": replaced,
            "message": f"四绳张力跟踪已启动：保护上限 {current}mA，自动从 {min(current, TRACKING_AUTO_FLOOR_CURRENT_MA)}mA 柔和建立并按几何配比" + ("（已替换上一轮跟踪）" if replaced else ""),
        }
    if action == "planar-snake-test":
        require_control_unlocked()
        require_confirmed(data)
        calibration = calibration_data()
        require_internal_model_ready(calibration, "平面蛇形自测")
        try:
            current = int(data.get("current", PLANAR_SNAKE_TEST_CURRENT))
        except (TypeError, ValueError):
            raise ValueError("平面蛇形自测电流必须是整数") from None
        if not 300 <= current <= OPERATING_CURRENT_MAX_MA:
            raise ValueError(f"平面蛇形自测电流必须在 300..{OPERATING_CURRENT_MAX_MA}mA 范围内")
        start_thread(planar_snake_test_worker, current)
        model_context = calibration_model_context(calibration)
        append_process_log(
            "planar_snake_test_requested",
            current_ma=current,
            model_family_key=model_context.get("model_family_key"),
            position_reference_deg=model_context.get("position_reference_deg"),
        )
        return {
            "ok": True,
            "action": action,
            "current_ma": current,
            "message": f"已启动平面蛇形高度自测：{current}mA，完成后自动记录高度并失能四台电机",
        }
    if action == "external-pose-calibration":
        # This is a pure-data operation: no motor command is sent.  The caller
        # must provide an independently measured pose for every row; accepting
        # encoder-only rows here would recreate the circular centre test.
        require_confirmed(data)
        if active_auto():
            raise RuntimeError("外部位姿拟合前请先停止当前自动流程，避免运行中的控制循环切换模型")
        calibration = calibration_data()
        if not calibration.get("valid"):
            raise RuntimeError("请先完成四角力矩扫描，获得初始绳长方向后再拟合外部位姿")
        result, reason = compute_external_pose_calibration(
            data.get("samples"), calibration, source=str(data.get("source", "camera"))
        )
        if result is None:
            raise RuntimeError(reason)
        persist_calibration(result)
        with STATE_LOCK:
            STATE["calibration"] = copy.deepcopy(result)
            STATE["message"] = "可选外部交叉验证完成：已将独立位姿样本写入绳长曲线"
        append_process_log(
            "external_pose_calibration_complete",
            source=result.get("calibration_source"),
            sample_count=len(result.get("pose_reference_samples", [])),
            r2=result.get("r2"),
            external_pose_verified=True,
        )
        return {
            "ok": True,
            "action": action,
            "source": result.get("calibration_source"),
            "sample_count": len(result.get("pose_reference_samples", [])),
            "r2": result.get("r2"),
            "message": "外部交叉验证完成；四台绳长曲线已更新，中心等电流诊断不会覆盖它",
        }
    if action == "center-tension-sweep":
        require_control_unlocked()
        require_confirmed(data)
        raise RuntimeError(
            "中心等电流标定已停用：电流只能近似电机力矩，不能确定绳张力或球心 XY/偏航；"
            "请使用四角已知几何 + 编码器闭环模型，中心测试仅作诊断"
        )
    # Calibration is the recovery action that re-establishes the control
    # session after an emergency stop, so it must remain available while the
    # normal motion controls are still locked.  All other actions keep the
    # ordinary unlock gate.
    if action != "calibrate":
        require_control_unlocked()
    require_confirmed(data)
    if active_auto():
        raise RuntimeError("自动流程正在运行，请先按急停")
    calibration = calibration_data()
    if action == "observe-torque":
        raise RuntimeError("低力力矩观察暂已停用：实测转速超过限制，待核实固件限速/制动；原始数据已保存")
    if action == "torque-admission":
        unexpected = set(data) - {"action", "confirmed"}
        if unexpected:
            raise ValueError("低力矩接管使用固定20mA/1RPM参数，不接受覆盖")
        start_thread(torque_admission_worker)
        return {"ok": True, "action": action, "message": "已启动逐轴低力矩接管检查；不执行旧四角标定"}
    if action == "corner-stop-probe":
        if set(data) - {"action", "confirmed"}:
            raise ValueError("角点短行程检查采用固定限制，不接受参数覆盖")
        start_thread(corner_stop_probe_worker)
        return {"ok": True, "action": action, "message": "已启动有界角点短行程检查；尚不发布四角校准"}
    if action in {"position-probe", "position-zero-takeover", "position-microprobe"}:
        # All ordinary admission gates above still apply. This bounded motor
        # diagnostic never publishes calibration or accepts Cartesian targets.
        unexpected = set(data) - {"action", "confirmed"}
        if unexpected:
            raise ValueError("微幅位置验证使用固定安全参数，不接受覆盖：" + ",".join(sorted(unexpected)))
        if action == "position-microprobe":
            start_thread(position_microprobe_worker)
        elif action == "position-zero-takeover":
            start_thread(position_probe_worker, True)
        else:
            start_thread(position_probe_worker)
        return {"ok": True, "action": action,
                "message": ("已启动固定四轴半度往返验证；逐帧检查反馈，原始指令和结果全量归档"
                            if action == "position-microprobe" else
                            "已启动零电流当前位置接管检查，暂不发送位移轨迹；原始指令和反馈全量归档"
                            if action == "position-zero-takeover" else
                            "已启动失能态低电流位置接管检查；原始指令和反馈全量归档")}
    if action == "corner-check":
        require_internal_model_ready(calibration, "四角复现")
        calibration_corner_targets(calibration)
        start_thread(corner_check_worker)
        append_process_log("corner_check_requested")
        return {"ok": True, "action": action, "message": "已启动四角复现检查：将依次移动到校准时保存的四个角点"}
    if action == "calibration-settings":
        return save_calibration_settings(data)
    if action == "calibrate":
        # ``force_full`` now selects the bounded four-corner position worker;
        # the quarantined open-ended C5 force worker is never admitted.
        # The independent emergency-stop thread may still be confirming the
        # four disable ACKs when the operator immediately clicks the single
        # "校准" button.  Wait through that short hand-off instead of exposing
        # a transient red error; a real communication failure still times out
        # and is reported below.
        if EMERGENCY_STOP_PENDING.is_set():
            stop_wait_deadline = time.perf_counter() + EMERGENCY_STOP_CONFIRM_WAIT_SECONDS
            while EMERGENCY_STOP_PENDING.is_set() and time.perf_counter() < stop_wait_deadline:
                time.sleep(0.05)
            if EMERGENCY_STOP_PENDING.is_set():
                raise RuntimeError("急停确认仍未完成；请等待四台失能确认后再校准，必要时切断动力")
        requested_height = float(data.get("side", calibration.get("side", WORKSPACE_HEIGHT_MM)))
        requested_ball = float(data.get("ball", calibration.get("ball", DEFAULT_BALL_DIAMETER_MM)))
        # The operator has defined the usable ball-center frame as exactly
        # 110x148 mm. The 40 mm ball diameter is metadata only; it must never
        # be used to crop the already-corrected 110 mm width a second time.
        if (
            not math.isclose(requested_height, WORKSPACE_HEIGHT_MM, abs_tol=0.0001)
            or not math.isclose(requested_ball, DEFAULT_BALL_DIAMETER_MM, abs_tol=0.0001)
        ):
            raise ValueError("本机电脑直连工作区固定为球心 110×148mm；球径元数据固定为 40mm")
        width = WORKSPACE_WIDTH_MM
        height = WORKSPACE_HEIGHT_MM
        ball = DEFAULT_BALL_DIAMETER_MM
        requested_strong = int(data.get("strong", calibration.get("strong_current", CALIBRATION_DEFAULT_STRONG_CURRENT)))
        requested_weak = int(data.get("weak", calibration.get("weak_current", CALIBRATION_DEFAULT_WEAK_CURRENT)))
        # Keep the proven 1500/300 calibration profile.  The worker applies a
        # current ramp so the same force does not arrive as a hard step.
        strong = CALIBRATION_BRUTE_FORCE_STRONG_CURRENT
        weak = CALIBRATION_BRUTE_FORCE_HOLD_CURRENT
        trajectory_current = int(data.get("trajectory_current", calibration.get("trajectory_current", TRAJECTORY_DEFAULT_CURRENT)))
        if not 50 <= strong <= OPERATING_CURRENT_MAX_MA or not 20 <= weak < strong or not 300 <= trajectory_current <= OPERATING_CURRENT_MAX_MA:
            raise ValueError(f"校准参数范围无效：强电流 50..{OPERATING_CURRENT_MAX_MA}、张力 20..强电流、轨迹电流 300..{OPERATING_CURRENT_MAX_MA}")
        saved_ready, saved_reason = persisted_calibration_structure_ready(calibration)
        # The operator-facing entry point is a single "校准" action.  It first
        # tries the read-only saved-model check when a structurally valid model
        # exists; the browser then automatically falls back to the explicit
        # full four-corner flow if this session cannot adopt that datum.
        force_full = bool(data.get("force_full") is True or not saved_ready)
        if data.get("activate_only") is True and data.get("force_full") is True:
            raise ValueError("启用保存参数与完整四角标定不能同时请求")
        if data.get("activate_only") is True and not saved_ready:
            raise ValueError("保存模型暂不能启用：" + saved_reason + "；未启动完整校准，请主动选择重新校准")
        if saved_ready and not force_full:
            set_state(
                calibration_run_mode="enable_saved",
                calibration_stage="queued",
                calibration_expected_seconds=PERSISTED_CALIBRATION_TARGET_SECONDS,
                calibration_requires_full=False,
                calibration_last_error=None,
                calibration_auto_fallback=False,
                message="正在只读检查已保存标定；失败将保留模型并提示人工确认，不自动进入完整四角校准",
            )
            start_thread(enable_saved_calibration_worker)
            append_process_log(
                "saved_calibration_enable_start",
                mode="saved_checkpoint_only",
                strong_current=strong,
                weak_current=weak,
                expected_seconds=PERSISTED_CALIBRATION_TARGET_SECONDS,
                automatic_full_calibration=False,
            )
            return {
                "ok": True,
                "action": "enable-saved-calibration",
                "mode": "enable_saved",
                "expected_seconds": PERSISTED_CALIBRATION_TARGET_SECONDS,
                "automatic_full_calibration": False,
                "message": "已受理保存标定核验；失败会保留模型并提示人工确认，不自动启动完整四角校准",
            }
        if not force_full:
            message = (
                "保存的标定当前无法快速启用："
                + saved_reason
                + "；本次点击将显式进入完整四角校准"
            )
            append_process_log(
                "saved_calibration_enable_rejected_before_start",
                reason=saved_reason,
                automatic_full_calibration_started=False,
            )
            force_full = True
            set_state(
                calibration_run_mode="full_four_corner",
                calibration_stage="queued",
                calibration_expected_seconds=CALIBRATION_EXPECTED_SECONDS,
                calibration_requires_full=False,
                calibration_last_error=saved_reason,
                calibration_auto_fallback=True,
                message=message,
            )
        previous = calibration
        calibration = blank_calibration()
        calibration["direction_reverse"] = list(direction_reversal_flags())
        calibration["slope_trim_percent"] = normalized_slope_trims(previous)
        calibration["trajectory_current"] = trajectory_current
        for key in (
            "draw_tension_current_ma",
            "tracking_current_ma",
            "path_speed_mm_s",
            "tracking_pen_up_height_mm",
            "tracking_pen_down_height_mm",
            "grid_tension_target_current_ma",
            "center_tension_target_current_ma",
            "grid_rows",
            "grid_cols",
        ):
            if key in previous:
                calibration[key] = previous[key]
        calibration.update(
            {
                "side": height,
                "ball": ball,
                "effective_side": height,
                "workspace_width": width,
                "workspace_height": height,
                "anchor_width": ANCHOR_WIDTH_MM,
                "anchor_height": ANCHOR_HEIGHT_MM,
                "motor_frame_origin_mm": [MOTOR_FRAME_ORIGIN_X_MM, MOTOR_FRAME_ORIGIN_Y_MM],
                "motor_center_coordinates_mm": [list(pair) for pair in zip(*motor_center_coordinates())],
                "cable_exit_offset_x_mm": MOTOR_CABLE_EXIT_OFFSET_X_MM,
                "spool_winding_radius_mm": SPOOL_WINDING_RADIUS_MM,
                "spool_reference_radius_mm": SPOOL_REFERENCE_RADIUS_MM,
                "spool_winding_z_range_mm": [SPOOL_WINDING_Z_MIN_MM, SPOOL_WINDING_Z_MAX_MM],
                "ball_center_contact_z_mm": BALL_CENTER_CONTACT_Z_MM,
                "ball_attachment_z_mm": BALL_ATTACHMENT_Z_MM,
                "ball_attachment_span_x_mm": BALL_ATTACHMENT_SPAN_X_MM,
                "ball_attachment_span_y_mm": BALL_ATTACHMENT_SPAN_Y_MM,
                "platform_command_yaw_deg": PLATFORM_COMMAND_YAW_DEG,
                "cable_exit_model": CABLE_EXIT_MODEL,
                "geometry_version": GEOMETRY_VERSION,
                "coordinate_frame": "ball_center_workspace",
                "control_architecture": CONTROL_ARCHITECTURE,
                "platform_pose_model": PLATFORM_POSE_MODEL,
                "strong_current": strong,
                "weak_current": weak,
            }
        )
        # Preserve the last accepted model while the new candidate is being
        # sampled.  Motion/readers must never see a transient blank geometry;
        # the worker publishes atomically only after all four corners fit.
        with STATE_LOCK:
            STATE["calibration_run_mode"] = "brute_force_four_corner"
            STATE["calibration_stage"] = "queued"
            STATE["calibration_expected_seconds"] = CALIBRATION_EXPECTED_SECONDS
            STATE["calibration_requires_full"] = False
            STATE["calibration_last_error"] = None
            STATE["calibration_auto_fallback"] = False
            STATE["calibration_candidate"] = None
            STATE["message"] = "已启动原始大力四角校准；强拉到角、全绳保持，反馈停稳且四角拟合通过后才保存，请保持无人接触并准备硬件急停"
        start_thread(calibration_worker, width, height, ball, strong, weak)
        append_process_log(
            "calibration_start",
            side=height,
            ball=ball,
            workspace=[width, height],
            anchor_frame=[ANCHOR_WIDTH_MM, ANCHOR_HEIGHT_MM],
            coordinate_frame="ball_center_workspace",
            strong_current=strong,
            weak_current=weak,
            trajectory_current=trajectory_current,
            slope_trim_percent=calibration.get("slope_trim_percent"),
            force_full=force_full,
        )
        return {
            "ok": True,
            "action": "full-four-corner-calibration",
            "mode": "brute_force_four_corner",
            "expected_seconds": CALIBRATION_EXPECTED_SECONDS,
            "automatic_full_calibration": False,
            "message": (
                f"原始大力四角校准已启动（实际用时以完成记录为准）：球心工作区 {width:.1f}×{height:.1f}mm、"
                f"卷轴轴心框 {ANCHOR_WIDTH_MM:.1f}×{ANCHOR_HEIGHT_MM:.1f}mm；"
                f"强拉 {strong}mA、四绳保持 {weak}mA，逐角等待反馈停稳，四角拟合通过后原子保存"
            ),
        }
    if not calibration.get("valid"):
        raise RuntimeError("请先完成四角自动校准")
    width, height = drawable_workspace_dimensions(calibration)
    if action == "calibration-demo":
        require_internal_model_ready(calibration, "校准验证")
        start_thread(calibration_demo_worker)
        return {"ok": True, "message": "已启动纯电机几何模型验收：十字 → 圆形；完成后四台自动失能"}
    if action == "grid-calibration":
        require_internal_model_ready(calibration, "多点网格校准")
        try:
            grid_target = int(data.get("grid_tension_target_current_ma", calibration.get("grid_tension_target_current_ma", GRID_DEFAULT_TENSION_CURRENT_MA)))
            grid_rows, grid_cols = normalized_grid_shape(
                data.get("grid_rows", calibration.get("grid_rows", GRID_DEFAULT_ROWS)),
                data.get("grid_cols", calibration.get("grid_cols", GRID_DEFAULT_COLS)),
            )
        except (TypeError, ValueError):
            raise ValueError("网格校准参数无效") from None
        if not GRID_TENSION_MIN_CURRENT_MA <= grid_target <= GRID_TENSION_MAX_CURRENT_MA:
            raise ValueError(f"网格张力下限必须在 {GRID_TENSION_MIN_CURRENT_MA}..{GRID_TENSION_MAX_CURRENT_MA}mA")
        save_calibration_settings(
            {
                "grid_tension_target_current_ma": grid_target,
                "grid_rows": grid_rows,
                "grid_cols": grid_cols,
            }
        )
        start_thread(grid_calibration_worker, grid_target, grid_rows, grid_cols)
        return {
            "ok": True,
            "message": f"已启动多点网格校准：{grid_rows}×{grid_cols}={grid_rows * grid_cols}点，四绳张力下限 {grid_target}mA",
        }
    if action == "shape-sequence":
        require_draw_model_ready(calibration, "完整轨迹验收")
        start_thread(shape_sequence_worker)
        return {"ok": True, "message": "已启动纯电机反馈完整验收：圆形 → 正方形 → 三角形 → 平面蛇形"}
    if action == "all-test-patterns":
        require_draw_model_ready(calibration, "一键图案测试")
        start_thread(all_test_patterns_worker)
        return {
            "ok": True,
            "message": "已启动一键图案测试：6种图案共用一次通信准备、一次起点接管，连续运行",
            "single_session": True,
            "shapes": list(ALL_TEST_PATTERN_KINDS),
        }
    if action in {"circle", "triangle", "square", "rectangle", "cross", "line", "snake"}:
        require_draw_model_ready(calibration, f"{kind_label(action)}轨迹")
        TRAJECTORY_SPEC = test_shape_spec(action, width, height)
        TRAJECTORY_SPEC["kind"] = action
        with STATE_LOCK:
            STATE["repeat"] = False
        start_thread(trajectory_worker, action, TRAJECTORY_SPEC, False, True)
        return {"ok": True, "message": f"{kind_label(action)}轨迹已启动"}
    if action == "loop_path":
        require_draw_model_ready(calibration, "循环手绘轨迹")
        # 复用最近一次已经完成的轨迹。手绘、固定验收图和快速测试图
        # 都是同一条位置轨迹，循环按钮不应因为来源不同而拒绝。
        if not TRAJECTORY_SPEC:
            raise RuntimeError("还没有可循环的轨迹，请先运行一次轨迹")
        spec = copy.deepcopy(TRAJECTORY_SPEC)
        spec["repeat"] = True
        with STATE_LOCK:
            STATE["repeat"] = True
        loop_kind = str(spec.get("kind") or "custom")
        start_thread(trajectory_worker, loop_kind, spec)
        return {"ok": True, "message": "已开始循环运行上次手绘轨迹；按急停结束"}
    raise ValueError(f"未知自动操作: {action}")


def validated_benchmark_identity(data: dict) -> dict | None:
    """Label fixed-input runs only when their actual submitted points match."""
    identity = data.get("benchmark")
    if identity is None:
        return None
    if not isinstance(identity, dict):
        raise ValueError("验收图标识无效")
    from y42_handwriting_benchmark import build_benchmark
    expected = build_benchmark(identity.get("scale", 1.0))
    if (identity.get("id") != expected["benchmark_id"]
            or identity.get("geometry_sha256") != expected["geometry_sha256"]
            or data.get("segments") != expected["payload"]["segments"]):
        raise ValueError("验收图坐标与固定版本不符；请重新载入或按普通手绘运行")
    return {"id": expected["benchmark_id"], "geometry_sha256": expected["geometry_sha256"],
            "scale": expected["scale"], "schema_version": expected["schema_version"],
            "stroke_labels": expected["operator_labels"]}


def handle_path(data: dict) -> dict:
    if not AUTO_REQUEST_LOCK.acquire(blocking=False):
        raise RuntimeError("另一条控制请求正在处理，请稍后重试")
    try:
        return _handle_path_locked(data)
    finally:
        AUTO_REQUEST_LOCK.release()


def handdraw_point_to_workspace(nx: float, ny: float, calibration: dict, coordinate_frame: str) -> tuple[float, float]:
    """Explicit canvas contract; full-board points are never scaled after drawing."""
    if not math.isfinite(nx) or not math.isfinite(ny) or not 0 <= nx <= 1 or not 0 <= ny <= 1:
        raise ValueError("手绘坐标超出画布")
    left, bottom, width, height = drawing_target_bounds(calibration)
    if coordinate_frame == "workspace_normalized":
        outer_width, outer_height = drawable_workspace_dimensions(calibration)
        x, y = nx * outer_width, (1-ny) * outer_height
        if not left-1e-6 <= x <= left+width+1e-6 or not bottom-1e-6 <= y <= bottom+height+1e-6:
            raise ValueError("轨迹超出可绘制边框；请在框内绘制，不会自动缩放")
        return x, y
    if coordinate_frame != "inset_normalized":
        raise ValueError("未知手绘坐标系")
    return left+width*nx, bottom+height*(1-ny)


def _handle_path_locked(data: dict) -> dict:
    global TRAJECTORY_SPEC
    require_control_unlocked()
    require_confirmed(data)
    if active_auto():
        raise RuntimeError("设备流程仍在运行；请等待完成或急停后再发送，避免控制请求互相覆盖")
    calibration = calibration_data()
    require_draw_model_ready(calibration, "手绘轨迹")
    feedback_during_motion = bool(data.get("feedback_during_motion", False))
    requested_open_loop = bool(
        data.get("open_loop")
        or data.get("feedback") is False
        or not feedback_during_motion
        or str(data.get("controller_mode", "")) == "four_position_open_loop"
    )
    motion_profile = ESP32_SMOOTH_PROFILE if requested_open_loop else None
    requested_controller = trajectory_controller_mode(
        {
            "controller_mode": (
                "four_position_open_loop"
                if requested_open_loop
                else data.get("controller_mode", "four_position")
            )
        }
    )
    benchmark_identity = validated_benchmark_identity(data)
    coordinate_frame = str(data.get("coordinate_frame", "inset_normalized"))
    raw = data.get("points")
    raw_segments = data.get("segments")
    if raw_segments is None:
        raw_segments = [raw]
    if not isinstance(raw_segments, list):
        raise ValueError("手绘轨迹笔画数据格式无效")
    usable_segments = [segment for segment in raw_segments if isinstance(segment, list) and len(segment) >= 2]
    raw_point_count = sum(len(segment) for segment in usable_segments)
    if len(usable_segments) == 0 or not 2 <= raw_point_count <= 6000:
        raise ValueError("手绘轨迹需要至少 1 笔、总计 2..6000 个点")
    margin_x, margin_y, draw_width, draw_height = drawing_target_bounds(calibration)
    outer_width, outer_height = drawable_workspace_dimensions(calibration)
    converted_segments: list[list[tuple[float, float]]] = []
    operator_input_normalized_segments: list[list[tuple[float, float]]] = []
    operator_input_absolute_segments: list[list[tuple[float, float]]] = []
    filtered_point_count = 0
    refined_point_count = 0
    for raw_segment in usable_segments:
        segment_points = []
        normalized_segment = []
        for item in raw_segment:
            nx = float(item["x"])
            ny = float(item["y"])
            normalized_segment.append((nx, ny))
            segment_points.append(handdraw_point_to_workspace(nx, ny, calibration, coordinate_frame))
        operator_input_normalized_segments.append(normalized_segment)
        operator_input_absolute_segments.append(list(segment_points))
        filtered_segment = list(segment_points)
        refined_segment = resample_polyline(filtered_segment)
        if len(refined_segment) >= 2:
            converted_segments.append(refined_segment)
            filtered_point_count += len(filtered_segment)
            refined_point_count += len(refined_segment)
    if not converted_segments:
        raise ValueError("手绘轨迹没有有效笔画")
    # Refinement only inserts points on each original stroke. Do not apply
    # Chaikin or join the end of one stroke to the start of the next: the
    # transfer is a real positioning phase, but it is not requested ink.
    draw_total = sum(
        math.hypot(second[0] - first[0], second[1] - first[1])
        for segment in converted_segments
        for first, second in zip(segment, segment[1:])
    )
    if draw_total < 3:
        raise ValueError("手绘轨迹太短")
    requested = max(PATH_SPEED_MIN_MM_S, min(PATH_SPEED_MAX_MM_S, float(data.get("speed", calibration.get("path_speed_mm_s", PATH_SPEED_DEFAULT_MM_S)))))
    max_slope = max(abs(value) for value in effective_slopes(calibration))
    motor_limit = min(5000.0, TRAJECTORY_MAX_RPM * 6.0 / (max_slope * TRAJECTORY_FEEDFORWARD)) if max_slope > 0.001 else 300.0
    profile_interval = (
        ESP32_SMOOTH_COMMAND_INTERVAL
        if motion_profile == ESP32_SMOOTH_PROFILE
        else TRAJECTORY_INTERVAL
    )
    profile_step = (
        ESP32_SMOOTH_PATH_STEP_MM
        if motion_profile == ESP32_SMOOTH_PROFILE
        else TRAJECTORY_MAX_STEP_MM
    )
    interval_ms = profile_interval * 1000.0
    controller_limit = profile_step * 1000.0 / interval_ms
    update_limit = draw_total * 1000.0 / (interval_ms * 4.0)
    speed = min(requested, motor_limit, controller_limit, update_limit)
    travel_speed = min(speed, CUSTOM_PATH_TRAVEL_SPEED_MM_S, motor_limit, controller_limit)
    if benchmark_identity is not None:
        # A benchmark speed sweep includes pen-up travel. A nominal low-speed
        # test must not retain the ordinary drawing UI's 150 mm/s transfer.
        travel_speed = min(travel_speed, speed)
    # The ESP32 profile feeds the refined literal polyline continuously.  All
    # original points remain in ``converted_segments``; the inserted points
    # only reproduce the old 1.5 mm command spacing.  Feedback-backed runs
    # keep the stricter exact-vertex planner used for diagnostics.
    planning_segments = (
        converted_segments if motion_profile == ESP32_SMOOTH_PROFILE
        else operator_input_absolute_segments
    )
    motion_segments, profile_speeds, elapsed, travel_total = plan_custom_motion_segments(
        planning_segments,
        speed,
        travel_speed,
        exact_vertices=motion_profile != ESP32_SMOOTH_PROFILE,
        control_tick_s=ESP32_SMOOTH_COMMAND_INTERVAL if motion_profile == ESP32_SMOOTH_PROFILE else TRAJECTORY_INTERVAL,
        profile=motion_profile,
    )
    # Never shorten a zero-speed endpoint by rounding the physical plan down.
    duration = math.ceil(elapsed * 1000.0)
    if duration < 28:
        raise ValueError("轨迹过短或速度过高，请降低速度")
    if duration > 600000:
        raise ValueError("轨迹运行时间超过 10 分钟，请缩短轨迹")
    save_calibration_settings({"path_speed_mm_s": requested})
    physical_total = draw_total + travel_total
    average_speed = physical_total / max(0.001, elapsed)
    selection_path = [
        point
        for phase in motion_segments
        for point in phase["path"]
    ]
    _, legacy_cumulative = path_with_cumulative(selection_path)
    command_point_count = sum(len(phase["path"]) for phase in motion_segments)
    new_spec = {
        "kind": "custom",
        "exact_polyline": True,
        "width": outer_width,
        "height": outer_height,
        "draw_width": draw_width,
        "draw_height": draw_height,
        "origin_x": margin_x,
        "origin_y": margin_y,
        "path_absolute": True,
        "path": selection_path,
        "cumulative": legacy_cumulative,
        "draw_segments": converted_segments,
        "motion_segments": motion_segments,
        "selection_path": selection_path,
        # Preserve the complete gesture; inserted display points do not replace
        # these mandatory on-clock command vertices.
        "operator_input_normalized_segments": operator_input_normalized_segments,
        "operator_coordinate_frame": coordinate_frame,
        "operator_input_absolute_segments": operator_input_absolute_segments,
        "duration_ms": duration,
        "point_count": int(duration / interval_ms) + 1,
        "repeat": bool(data.get("repeat", False)),
        "stroke_count": len(converted_segments),
        "raw_point_count": raw_point_count,
        "filtered_point_count": filtered_point_count,
        "refined_point_count": refined_point_count,
        "command_path_point_count": command_point_count,
        "requested_speed_mm_s": requested,
        "speed_mm_s": speed,
        "travel_speed_mm_s": travel_speed,
        "draw_distance_mm": draw_total,
        "travel_distance_mm": travel_total,
        "average_speed_mm_s": average_speed,
        "profile_min_speed_mm_s": min(profile_speeds),
        "corner_slowdown": motion_profile == ESP32_SMOOTH_PROFILE,
        "motion_profile": motion_profile,
        "motion_profile_parameters": {
            "path_step_mm": ESP32_SMOOTH_PATH_STEP_MM,
            "command_hz": ESP32_SMOOTH_COMMAND_HZ,
            "motion_current_ma": ESP32_SMOOTH_MOTION_CURRENT_MA,
            "position_rpm": ESP32_SMOOTH_MOTION_RPM,
        } if motion_profile == ESP32_SMOOTH_PROFILE else None,
    # Feedback remains an overlay for manual strokes.  Waiting for a complete
    # four-motor feedback batch before each point made a one-off stroke expose
    # a transient RS485 read gap that the continuous all-pattern run never
    # treated as a motion fault.
    "target_gate": False,
        "open_loop": requested_open_loop,
        "feedback": not requested_open_loop,
        "feedback_during_motion": feedback_during_motion,
        "motion_feedback": False,
        "controller_mode": requested_controller,
        "benchmark": benchmark_identity,
        "session_yaw_trial": data.get("session_yaw_trial") is True,
    }
    replaced = stop_motion_for_replacement("新的手绘轨迹")
    # A soft tracking hand-off preserves the session datum; an emergency/failed
    # stop does not. Recheck after ownership changes so a stale pre-stop result
    # can never silently fall back to over-constrained four-position control.
    require_internal_model_ready(calibration_data(), "手绘轨迹")
    # Capture an immutable request snapshot for the worker.  Otherwise a
    # later draw request can replace the module-level cache while the thread
    # is still resolving its start point, making the old path run again.
    TRAJECTORY_SPEC = copy.deepcopy(new_spec)
    with STATE_LOCK:
        STATE["repeat"] = bool(new_spec["repeat"])
        STATE["trajectory_target_path"] = []
        STATE["trajectory_target_path_segments"] = []
        STATE["trajectory_actual_path"] = []
        STATE["trajectory_actual_feedback_path"] = []
        STATE["trajectory_actual_path_segments"] = []
        STATE["trajectory_actual_feedback_path_segments"] = []
        STATE["trajectory_fit_error_mm"] = None
        STATE["trajectory_diagnostic"] = {
                "status": "纯位置开环待启动" if requested_open_loop else "运动中优先位置命令，结束窗口确认反馈",
                "recommendation": (
                "运动中不读取反馈；仅记录电脑发送的目标轨迹"
                if requested_open_loop
                else "运动期间不占用回传总线，结束窗口读取四台位置/电流"
                ),
        }
        STATE["message"] = (
            f"已接收新的手绘轨迹：{len(converted_segments)} 笔，准备启动"
            + ("（纯位置开环，不读取运动反馈）" if requested_open_loop else "")
            + ("（已替换上一条轨迹）" if replaced else "")
        )
    start_thread(trajectory_worker, "custom", copy.deepcopy(new_spec))
    stroke_note = (
        f"，共 {len(converted_segments)} 笔；笔间以 {travel_speed:.0f}mm/s 连续换位，换位不画线、不计绘制误差"
        if len(converted_segments) > 1 else ""
    )
    profile_note = (
        f"；复刻 ESP32 丝滑参数（{ESP32_SMOOTH_COMMAND_HZ:.0f}Hz / {ESP32_SMOOTH_PATH_STEP_MM:.1f}mm / "
        f"{ESP32_SMOOTH_MOTION_CURRENT_MA}mA / {ESP32_SMOOTH_MOTION_RPM:.0f}RPM）"
        if motion_profile == ESP32_SMOOTH_PROFILE else ""
    )
    return {
        "ok": True,
        "replaced_auto": replaced,
        "message": (
            f"已接收 {raw_point_count} 个点{stroke_note}，细化为 {refined_point_count} 个绘制点（不改变手绘折线），"
            f"绘制巡航 {speed:.1f}mm/s，预计 {duration / 1000:.2f} 秒"
            + ("；纯位置开环不读取运动反馈" if requested_open_loop else "")
            + profile_note
            + ("；已安全切换到新轨迹" if replaced else "")
        ),
        "stroke_count": len(converted_segments),
        "raw_point_count": raw_point_count,
        "filtered_point_count": filtered_point_count,
        "refined_point_count": refined_point_count,
        "command_path_point_count": command_point_count,
        "cruise_speed_mm_s": round(speed, 3),
        "travel_speed_mm_s": round(travel_speed, 3),
        "draw_distance_mm": round(draw_total, 3),
        "travel_distance_mm": round(travel_total, 3),
        "average_speed_mm_s": round(average_speed, 3),
        "open_loop": requested_open_loop,
        "motion_feedback": False,
        # Manual strokes deliberately run without a per-point feedback gate;
        # feedback remains an overlay and must not turn a transient RS485
        # batch gap into a false motion failure.
        "target_gate": False,
        "command_hz_target": (
            ESP32_SMOOTH_COMMAND_HZ
            if motion_profile == ESP32_SMOOTH_PROFILE
            else TRAJECTORY_HZ
            if requested_open_loop
            else None
        ),
    }


# All migration helpers are defined above.  Load only now so a legacy geometry
# can be refitted safely before the first API/browser request.
load_calibration()


