def api_error(exc: Exception) -> dict:
    return {"ok": False, "error": str(exc)}


class Handler(BaseHTTPRequestHandler):
    def log_message(self, _format: str, *_args: object) -> None:
        return

    def send_json(self, value: object, status: int = 200) -> None:
        body = json_bytes(value)
        try:
            self.send_response(status)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Cache-Control", "no-store")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
            # The browser may cancel an in-flight poll during reload.  It is
            # not a device or RS485 error and should not produce a traceback.
            return

    def do_GET(self) -> None:
        path = self.path.split("?", 1)[0]
        try:
            if path == "/":
                # Read presentation on every request: future page changes need
                # no serial-controller restart.
                base = Path(__file__).read_text(encoding="utf-8").split("PAGE = r'''", 1)[1].split("'''", 1)[0]
                script = Path(__file__).with_name("y42_four_pages.js").read_text(encoding="utf-8")
                body = (base + "<script>" + script + "</script>").encode("utf-8")
                self.send_response(200)
                self.send_header("Content-Type", "text/html; charset=utf-8")
                self.send_header("Cache-Control", "no-store")
                self.send_header("Content-Length", str(len(body)))
                self.end_headers()
                self.wfile.write(body)
                return
            if path == "/onboarding":
                body = Path(__file__).with_name("y42_real_lesson.html").read_bytes()
                self.send_response(200)
                self.send_header("Content-Type", "text/html; charset=utf-8")
                self.send_header("Cache-Control", "no-store")
                self.send_header("Content-Length", str(len(body)))
                self.end_headers()
                self.wfile.write(body)
                return
            if path == "/api/ports":
                self.send_json(execute({"action": "ports"}))
                return
            if path == "/api/benchmark":
                from y42_handwriting_benchmark import build_benchmark
                self.send_json({"ok": True, **build_benchmark()})
                return
            if path == "/api/xingmao":
                self.send_json(json.loads(Path(__file__).with_name("xingmao_path.json").read_text(encoding="utf-8")))
                return
            if path == "/effect-review":
                # A fixed read-only artifact: opening the comparison never
                # imports a run snapshot into the live motor controller.
                report = (Path(__file__).resolve().parent.parent / "qa" /
                          "trajectory_reviews" / "20260905_visual_audit" /
                          "same-input-comparison.html")
                if not report.is_file():
                    self.send_error(404, "Saved comparison is not available")
                    return
                body = report.read_bytes()
                self.send_response(200)
                self.send_header("Content-Type", "text/html; charset=utf-8")
                self.send_header("Cache-Control", "no-store")
                self.send_header("Content-Length", str(len(body)))
                self.end_headers()
                self.wfile.write(body)
                return
            if path == "/api/status":
                self.send_json(execute({"action": "status", "port": current_port(), "baud": current_baud()}))
                return
            if path == "/api/auto":
                self.send_json(web_state_snapshot())
                return
            if path == "/api/process-log":
                self.send_json({"ok": True, "file": str(PROCESS_LOG_FILE), "events": recent_process_log()})
                return
            self.send_error(404)
        except Exception as exc:
            self.send_json(api_error(exc), 400)

    def do_POST(self) -> None:
        try:
            length = int(self.headers.get("Content-Length", "0"))
            data = json.loads(self.rfile.read(length).decode("utf-8") or "{}")
            path = self.path.split("?", 1)[0]
            if path == "/api/command":
                result = execute(data)
            elif path == "/api/arm":
                result = set_control_lock(data)
            elif path == "/api/auto":
                result = start_auto(data)
            elif path == "/api/path":
                result = handle_path(data)
            else:
                self.send_error(404)
                return
            self.send_json(result)
        except Exception as exc:
            self.send_json(api_error(exc), 400)


def run() -> None:
    server = ThreadingHTTPServer((HOST, PORT), Handler)
    print(f"Y42 direct web: http://{HOST}:{PORT}/", flush=True)
    threading.Thread(target=auto_prepare_on_boot, name="y42-boot-prepare", daemon=True).start()
    server.serve_forever()


if __name__ == "__main__":
    run()
